public.apply_rakeback_player_stats(p_rak.def:
CREATE OR REPLACE FUNCTION public.apply_rakeback_player_stats(p_rake_record_id uuid, p_user_id uuid, p_club_id uuid, p_hands integer, p_rake numeric)
 RETURNS boolean
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_inserted integer;
BEGIN
  IF p_rake_record_id IS NULL OR p_user_id IS NULL OR p_club_id IS NULL THEN
    RETURN false;
  END IF;

  IF public.fn_ca_launch_accounting_cutoff('club',p_club_id) IS NOT NULL AND NOT EXISTS(SELECT 1 FROM public.rake_records r WHERE r.id=p_rake_record_id AND public.fn_ca_launch_accounting_accepts(p_club_id,r.created_at) AND ((r.is_tournament IS NOT TRUE AND r.tournament_id IS NULL) OR EXISTS(SELECT 1 FROM public.accounting_tournament_fee_sources f WHERE f.rake_record_id=r.id AND f.player_id=p_user_id AND f.club_id=p_club_id AND public.fn_ca_launch_accounting_accepts(p_club_id,f.charged_at)))) THEN RETURN false; END IF;

  INSERT INTO public.rakeback_stats_applied (rake_record_id, user_id, hands, rake)
  VALUES (p_rake_record_id, p_user_id, p_hands, p_rake)
  ON CONFLICT (rake_record_id, user_id) DO NOTHING;
  GET DIAGNOSTICS v_inserted = ROW_COUNT;
  IF v_inserted = 0 THEN
    RETURN false;
  END IF;

  INSERT INTO public.player_stats (
    user_id, club_id, hands_played, total_rake,
    total_winnings, total_losses, vpip, pfr, tournaments_played, tournaments_won
  ) VALUES (
    p_user_id, p_club_id, COALESCE(p_hands, 0), COALESCE(p_rake, 0),
    0, 0, 0, 0, 0, 0
  )
  ON CONFLICT (user_id, club_id) DO UPDATE SET
    hands_played = public.player_stats.hands_played + EXCLUDED.hands_played,
    total_rake   = ROUND((public.player_stats.total_rake + EXCLUDED.total_rake) * 100) / 100,
    updated_at   = NOW();

  RETURN true;
END;
$function$

public.ca_refresh_reporting_cash_rollup(.def:
CREATE OR REPLACE FUNCTION public.ca_refresh_reporting_cash_rollup(p_start date, p_end date)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_start date:=LEAST(p_start,p_end); v_end date:=GREATEST(p_start,p_end);
  v_from timestamptz; v_to timestamptz; v_rows bigint;
  v_facts_from date; v_d date;
BEGIN
  IF v_start IS NULL OR v_end IS NULL OR v_end-v_start>400 THEN
    RAISE EXCEPTION 'cash reporting refresh requires a 0-400 day range'; END IF;
  -- 20261017204111: every day the Club Data facts cover is rebuilt from them
  -- (fn_ca_reporting_rollups_from_facts); this rebuild keeps only the days
  -- before them, which nothing else holds.
  v_facts_from := public.fn_ca_club_data_facts_from();
  IF v_facts_from IS NOT NULL AND v_end >= v_facts_from THEN
    FOR v_d IN SELECT gs::date FROM generate_series(GREATEST(v_start, v_facts_from),
                 LEAST(v_end, (now() AT TIME ZONE 'UTC')::date), interval '1 day') gs LOOP
      PERFORM public.fn_ca_reporting_rollups_from_facts(v_d);
    END LOOP;
    IF v_start >= v_facts_from THEN
      RETURN jsonb_build_object('start',v_start,'end',v_end,'source','ca_club_data_fact','refreshed_at',now());
    END IF;
    v_end := v_facts_from - 1;
  END IF;
  PERFORM pg_advisory_xact_lock(918273645);
  v_from:=v_start::timestamp AT TIME ZONE 'UTC';
  v_to:=(v_end+1)::timestamp AT TIME ZONE 'UTC';
  UPDATE public.ca_club_player_daily SET cash_net=0,updated_at=now()
   WHERE stat_date BETWEEN v_start AND v_end AND cash_net<>0;
  WITH home AS MATERIALIZED (
    SELECT DISTINCT ON(uc.union_id,cm.user_id) uc.union_id,cm.user_id,cm.club_id
      FROM public.club_members cm JOIN public.union_clubs uc ON uc.club_id=cm.club_id
     ORDER BY uc.union_id,cm.user_id,cm.joined_at ASC NULLS LAST,cm.club_id
  ), cash AS (
    SELECT x.club_id,x.user_id,x.stat_date,SUM(x.cash_net) AS cash_net FROM (
      SELECT h.club_id,wt.user_id,(wt.created_at AT TIME ZONE 'UTC')::date stat_date,
             SUM(CASE WHEN wt.type='credit' THEN wt.amount
                      WHEN wt.type='debit' THEN -wt.amount ELSE 0 END) cash_net
        FROM public.wallet_transactions wt
        JOIN public.tables tb ON tb.id=wt.table_id AND tb.union_id IS NOT NULL
         AND tb.tournament_id IS NULL
        JOIN home h ON h.union_id=tb.union_id AND h.user_id=wt.user_id
       WHERE wt.created_at>=v_from AND wt.created_at<v_to
         AND wt.category IN('buyin','cashout','addon','rebuy','refund') AND wt.table_id IS NOT NULL
       GROUP BY 1,2,3
      UNION ALL
      -- 2026-09-04: standalone tables, which this rollup never read.
      SELECT tb.club_id,wt.user_id,(wt.created_at AT TIME ZONE 'UTC')::date,
             SUM(CASE WHEN wt.type='credit' THEN wt.amount
                      WHEN wt.type='debit' THEN -wt.amount ELSE 0 END)
        FROM public.wallet_transactions wt
        JOIN public.tables tb ON tb.id=wt.table_id AND tb.union_id IS NULL
         AND tb.tournament_id IS NULL AND tb.club_id IS NOT NULL
       WHERE wt.created_at>=v_from AND wt.created_at<v_to
         AND wt.category IN('buyin','cashout','addon','rebuy','refund') AND wt.table_id IS NOT NULL
       GROUP BY 1,2,3
    ) x GROUP BY 1,2,3
  )
  INSERT INTO public.ca_club_player_daily AS d
    (club_id,user_id,stat_date,cash_net,tournament_net,updated_at)
  SELECT club_id,user_id,stat_date,cash_net,0,now() FROM cash
  ON CONFLICT(club_id,user_id,stat_date) DO UPDATE
   SET cash_net=EXCLUDED.cash_net,updated_at=now();
  SELECT count(*) INTO v_rows FROM public.ca_club_player_daily
   WHERE stat_date BETWEEN v_start AND v_end AND cash_net<>0;
  RETURN jsonb_build_object('start',v_start,'end',v_end,'cash_facts',v_rows,'refreshed_at',now());
END;
$function$

public.ca_refresh_reporting_rollups(p_st.def:
CREATE OR REPLACE FUNCTION public.ca_refresh_reporting_rollups(p_start date, p_end date)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE v_base jsonb; v_cash jsonb;
BEGIN
  v_base:=public.ca_refresh_reporting_rollups_base(p_start,p_end);
  v_cash:=public.ca_refresh_reporting_cash_rollup(p_start,p_end);
  RETURN v_base || jsonb_build_object('cash_repair',v_cash);
END;
$function$

public.enforce_chip_ledger_performed_by(.def:
CREATE OR REPLACE FUNCTION public.enforce_chip_ledger_performed_by()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'public'
AS $function$
DECLARE
  v_reason text := NULLIF(current_setting('app.ledger_maintenance', true), '');
BEGIN
  IF TG_OP = 'UPDATE' THEN
    IF NEW.performed_by IS NOT DISTINCT FROM OLD.performed_by THEN
      RETURN NEW;
    END IF;
    IF OLD.performed_by IS NOT NULL
       AND NEW.performed_by IS NULL
       AND v_reason LIKE 'certification-cleanup:%'
       AND EXISTS (
         SELECT 1
           FROM public.ca_test_account_ledger_actor_archive a
          WHERE a.ledger_id = OLD.id
            AND a.actor_id = OLD.performed_by
            AND a.ledger_row = to_jsonb(OLD)
       ) THEN
      RETURN NEW;
    END IF;
    RAISE EXCEPTION
      'chip_ledger.performed_by is immutable except after exact archived certification cleanup'
      USING ERRCODE = '55000';
  END IF;

  IF NEW.performed_by IS NULL THEN
    RAISE EXCEPTION 'chip_ledger.performed_by must name a real user'
      USING ERRCODE = 'invalid_parameter_value';
  END IF;
  IF NEW.performed_by = '00000000-0000-0000-0000-000000000000'::uuid THEN
    RAISE EXCEPTION 'chip_ledger.performed_by must be a real user, got all-zero sentinel'
      USING ERRCODE = 'invalid_parameter_value';
  END IF;
  RETURN NEW;
END;
$function$

public.fn_accounting_agent_terms_at(p_cl.def:
CREATE OR REPLACE FUNCTION public.fn_accounting_agent_terms_at(p_club_id uuid, p_user_id uuid, p_at timestamp with time zone)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE identities text[]; identity_key text; v jsonb; result jsonb; active_count int:=0;
BEGIN
 -- Service-only EXECUTE ACL also permits private source-owner triggers.
 IF p_club_id IS NULL OR p_user_id IS NULL OR p_at IS NULL OR NOT isfinite(p_at) OR p_at>transaction_timestamp()
 THEN RAISE EXCEPTION 'invalid_accounting_terms_request' USING ERRCODE='22023'; END IF;
 -- Find candidate identities from history, then resolve each identity at the
 -- earning time. A later move/deletion closes the old identity; filtering the
 -- history by club before selecting its latest event would resurrect that row.
 SELECT array_agg(DISTINCT h.entity_key) INTO identities FROM public.accounting_agreement_history h
  WHERE h.entity_type='agents' AND h.club_id=p_club_id AND h.subject_user_id=p_user_id AND h.observed_at<=p_at AND (h.transaction_id=txid_current_if_assigned() OR NOT EXISTS(
   SELECT 1 FROM public.accounting_agreement_history later
   WHERE later.transaction_id=h.transaction_id AND later.observed_at>p_at));
 IF identities IS NULL THEN RAISE EXCEPTION 'accounting_terms_not_observed' USING ERRCODE='55000'; END IF;
 FOREACH identity_key IN ARRAY identities LOOP
  v:=public.fn_accounting_terms_at('agents',identity_key,p_at);
  IF v->'terms'->>'club_id'=p_club_id::text AND v->'terms'->>'user_id'=p_user_id::text
     AND v->'terms'->>'status'='active' THEN
   active_count:=active_count+1; result:=v;
  END IF;
 END LOOP;
 IF active_count=0 THEN RAISE EXCEPTION 'accounting_terms_not_active' USING ERRCODE='55000'; END IF;
 IF active_count>1 THEN RAISE EXCEPTION 'accounting_terms_ambiguous' USING ERRCODE='55000'; END IF;
 RETURN result;
END $function$

public.fn_accounting_agreement_capture().def:
CREATE OR REPLACE FUNCTION public.fn_accounting_agreement_capture()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE b jsonb; a jsonb; identity_row jsonb; identity_key text; moved boolean;
BEGIN
 b:=CASE WHEN TG_OP='INSERT' THEN NULL ELSE public.fn_accounting_agreement_terms(TG_TABLE_NAME,to_jsonb(OLD)) END;
 a:=CASE WHEN TG_OP='DELETE' THEN NULL ELSE public.fn_accounting_agreement_terms(TG_TABLE_NAME,to_jsonb(NEW)) END;
 IF b IS NOT DISTINCT FROM a THEN RETURN COALESCE(NEW,OLD); END IF;
 identity_row:=COALESCE(b,a);
 identity_key:=CASE WHEN TG_TABLE_NAME='club_members' THEN identity_row->>'club_id'||':'||(identity_row->>'user_id') ELSE identity_row->>'id' END;
 moved:=TG_OP='UPDATE' AND (b->>'id' IS DISTINCT FROM a->>'id'
   OR b->>'club_id' IS DISTINCT FROM a->>'club_id' OR b->>'user_id' IS DISTINCT FROM a->>'user_id');
 INSERT INTO public.accounting_agreement_history(entity_type,entity_key,club_id,subject_user_id,event_type,actor_id,before_terms,after_terms)
 VALUES(TG_TABLE_NAME,identity_key,(identity_row->>'club_id')::uuid,(identity_row->>'user_id')::uuid,TG_OP,auth.uid(),b,CASE WHEN moved THEN NULL ELSE a END);
 -- A moved identity closes its original key and establishes the new key too.
 -- Both changes are observed in this transaction; neither is backdated.
 IF moved THEN
   identity_key:=CASE WHEN TG_TABLE_NAME='club_members' THEN a->>'club_id'||':'||(a->>'user_id') ELSE a->>'id' END;
   INSERT INTO public.accounting_agreement_history(entity_type,entity_key,club_id,subject_user_id,event_type,actor_id,before_terms,after_terms)
   VALUES(TG_TABLE_NAME,identity_key,(a->>'club_id')::uuid,(a->>'user_id')::uuid,'UPDATE',auth.uid(),NULL,a);
 END IF;
 RETURN COALESCE(NEW,OLD);
END $function$

public.fn_accounting_cash_commission_pla.def:
CREATE OR REPLACE FUNCTION public.fn_accounting_cash_commission_plan(p_rake_record_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE source public.rake_records%ROWTYPE;a record;players jsonb:='[]';allocated numeric;n int;game_union uuid;
BEGIN
 IF NOT public.fn_caller_is_engine() THEN RAISE EXCEPTION 'service_role_required' USING ERRCODE='42501'; END IF;
 SELECT * INTO source FROM public.rake_records WHERE id=p_rake_record_id;
 IF NOT FOUND OR source.hand_id IS NULL OR COALESCE(source.is_tournament,false) OR source.tournament_id IS NOT NULL
  OR source.rake_amount<=0 OR source.rake_amount::text IN('NaN','Infinity','-Infinity') OR source.rake_amount<>round(source.rake_amount,2)
 THEN RAISE EXCEPTION 'cash_commission_source_invalid' USING ERRCODE='23514'; END IF;
 IF source.metadata->>'accounting_source_version' IS DISTINCT FROM '2' OR NOT (source.metadata ? 'union_id') THEN
  RAISE EXCEPTION 'cash_game_union_stamp_missing' USING ERRCODE='23514'; END IF;
 game_union:=NULLIF(source.metadata->>'union_id','')::uuid;
 IF COALESCE((source.metadata->>'is_private')::boolean,false) AND game_union IS NOT NULL THEN
  RAISE EXCEPTION 'private_cash_rake_cannot_belong_to_union' USING ERRCODE='23514'; END IF;
 -- A receipt creates liabilities only after the matching rake disposition:
 -- a Union wallet credit, or a standalone/private retirement. Retirement is
 -- source evidence, never funding for the existing treasury-funded payout.
 IF NOT EXISTS(SELECT 1 FROM public.accounting_cash_bank_receipts b
   LEFT JOIN public.union_wallet_transactions t ON t.id=b.union_transaction_id
   LEFT JOIN public.chip_ledger l ON l.id=b.club_ledger_id
   WHERE b.rake_record_id=source.id AND b.club_id=source.club_id AND b.amount=source.rake_amount
    AND b.banked_at=source.created_at AND b.union_id IS NOT DISTINCT FROM game_union
    AND ((game_union IS NOT NULL AND t.union_id=game_union AND t.amount=b.amount AND t.created_at=b.banked_at
      AND t.wallet='rake_wallet' AND t.direction='credit' AND t.tx_type='rake' AND b.club_ledger_id IS NULL)
     OR (game_union IS NULL AND b.union_transaction_id IS NULL AND l.amount=b.amount AND l.created_at=b.banked_at
      AND l.from_type='table_stack' AND l.to_type='chip_retirement' AND l.to_entity_id IS NULL
      AND l.club_id=source.club_id AND l.category='burn')))
 THEN RAISE EXCEPTION 'cash_commission_bank_receipt_not_proven' USING ERRCODE='23514'; END IF;
 SELECT count(*),sum(weighted_rake_credit) INTO n,allocated FROM public.rake_attributions WHERE rake_record_id=source.id AND hand_id=source.hand_id;
 IF n=0 OR allocated IS DISTINCT FROM source.rake_amount OR EXISTS(SELECT 1 FROM public.rake_attributions
  WHERE hand_id=source.hand_id AND (rake_record_id IS DISTINCT FROM source.id OR club_id IS NULL OR player_id IS NULL
   OR weighted_rake_credit IS NULL OR weighted_rake_credit<0 OR weighted_rake_credit<>round(weighted_rake_credit,2)
   OR weighted_rake_credit::text IN('NaN','Infinity','-Infinity')))
 THEN RAISE EXCEPTION 'cash_commission_attribution_incomplete' USING ERRCODE='23514'; END IF;
 IF EXISTS(SELECT 1 FROM public.rake_attributions WHERE rake_record_id=source.id GROUP BY player_id HAVING count(*)<>1)
 THEN RAISE EXCEPTION 'cash_commission_attribution_ambiguous' USING ERRCODE='23514'; END IF;
 FOR a IN SELECT * FROM public.rake_attributions WHERE rake_record_id=source.id ORDER BY club_id,player_id LOOP
  IF game_union IS NULL AND a.club_id<>source.club_id THEN
   RAISE EXCEPTION 'cash_commission_earning_club_not_observed' USING ERRCODE='23514'; END IF;
  players:=players||jsonb_build_array(public.fn_accounting_earning_contract(a.club_id,a.player_id,a.weighted_rake_credit,game_union,source.created_at)
   ||jsonb_build_object('attribution_id',a.id));
 END LOOP;
 RETURN jsonb_build_object('source_version',2,'rake_record_id',source.id,'hand_id',source.hand_id,
  'earned_at',source.created_at,'rake',source.rake_amount,'players',players);
END $function$

public.fn_accounting_cash_commission_sou.def:
CREATE OR REPLACE FUNCTION public.fn_accounting_cash_commission_source_guard()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE source public.accounting_cash_rake_sources%ROWTYPE; matches int;
BEGIN
 IF NEW.source_type='cash_rake_accrual' THEN
  SELECT * INTO source FROM public.accounting_effective_cash_rake_sources WHERE id=NEW.source_id;
  IF NOT FOUND OR NEW.club_id IS DISTINCT FROM source.club_id OR NEW.created_at IS DISTINCT FROM source.earned_at THEN
   RAISE EXCEPTION 'cash_commission_source_receipt_required' USING ERRCODE='23514'; END IF;
  SELECT count(*) INTO matches FROM jsonb_array_elements(source.contract->'tiers') t
   WHERE t->>'user_id'=NEW.user_id::text AND (t->>'amount')::numeric=NEW.amount
    AND (t->>'rate')::numeric=NEW.commission_rate AND NEW.amount>0;
  IF matches<>1 THEN RAISE EXCEPTION 'cash_commission_disagrees_with_recorded_entitlement' USING ERRCODE='23514'; END IF;
 ELSIF NEW.source_type IN('rake','rake_settlement') AND EXISTS(
  SELECT 1 FROM public.rake_records r CROSS JOIN public.accounting_cash_accrual_cutover c
   WHERE c.singleton AND r.hand_id=NEW.source_id AND r.created_at>=c.starts_at
     AND NOT COALESCE(r.is_tournament,false) AND r.tournament_id IS NULL) THEN
  RAISE EXCEPTION 'cash_commission_requires_canonical_source_writer' USING ERRCODE='23514';
 END IF;
 RETURN NEW;
END $function$

public.fn_accounting_close_windows_advan.def:
CREATE OR REPLACE FUNCTION public.fn_accounting_close_windows_advance_due()
 RETURNS jsonb
 LANGUAGE plpgsql
 SET search_path TO 'public'
AS $function$
DECLARE q record; done jsonb:='[]'::jsonb; advanced boolean:=false; stmt_stop timestamptz;
 n_windows bigint; n_before bigint; n_after bigint; v_msg text;
 budget interval:=COALESCE(NULLIF(current_setting('app.weekly_accounting_scope_budget',true),''),'8 minutes')::interval;
 saved_deadline text:=COALESCE(current_setting('app.weekly_accounting_scope_deadline',true),'');
BEGIN
 IF COALESCE(current_setting('app.weekly_accounting_chunked',true),'')<>'on'
  OR current_setting('statement_timeout') IN ('0','0ms')
  OR public.fn_platform_frozen() IS DISTINCT FROM false
  OR NOT pg_try_advisory_xact_lock(hashtextextended('union-accounting-scheduler',0)) THEN
  RETURN NULL;
 END IF;
 -- No window starts less than a minute before the statement is cancelled.
 stmt_stop:=statement_timestamp()+current_setting('statement_timeout')::interval-interval '60 seconds';
 FOR q IN SELECT r.scope_kind,r.scope_id,r.period_start,r.period_end FROM public.union_accounting_runs r
   WHERE r.status='running' AND r.result->>'chunk_committed'='true' AND r.result->>'stage'='prepared'
    AND r.scope_kind IN ('union','club') AND r.scope_id IS NOT NULL AND r.period_end<=clock_timestamp()
    AND NOT EXISTS(SELECT 1 FROM public.accounting_routed_settlement_runs s WHERE s.scope_kind=r.scope_kind
     AND s.scope_id=r.scope_id AND s.period_start=r.period_start AND s.period_end=r.period_end AND s.round_no=2)
   ORDER BY r.period_start,r.scope_kind,r.scope_id LOOP
  EXIT WHEN clock_timestamp()>stmt_stop;
  SELECT count(*),count(p.window_start) INTO n_windows,n_before
   FROM public.fn_accounting_close_windows(q.period_start,q.period_end) w
   LEFT JOIN public.accounting_close_partials p ON p.kind='round2_'||q.scope_kind||'_window' AND p.union_id=q.scope_id
    AND p.period_start=q.period_start AND p.period_end=q.period_end AND p.window_start=w.window_start AND p.window_end=w.window_end
    AND p.computed_at>=q.period_end AND p.computed_at>clock_timestamp()-public.fn_accounting_close_proof_lifetime();
  CONTINUE WHEN n_windows=0 OR n_before=n_windows;
  -- The advance stops 120 s after its attempt began and a minute before the
  -- statement ends: begin it so both points are the statement's minute.
  PERFORM set_config('app.weekly_accounting_scope_deadline',(stmt_stop-interval '120 seconds'+budget)::text,true);
  BEGIN
   PERFORM public.fn_settle_accounting_commission_advance(q.scope_kind,q.scope_id,q.period_start,q.period_end);
  EXCEPTION WHEN OTHERS THEN
   -- A window this read cannot prove is left to the book's own attempt,
   -- which refuses it as it always has.
   GET STACKED DIAGNOSTICS v_msg=MESSAGE_TEXT;
  END;
  SELECT count(p.window_start) INTO n_after
   FROM public.fn_accounting_close_windows(q.period_start,q.period_end) w
   JOIN public.accounting_close_partials p ON p.kind='round2_'||q.scope_kind||'_window' AND p.union_id=q.scope_id
    AND p.period_start=q.period_start AND p.period_end=q.period_end AND p.window_start=w.window_start AND p.window_end=w.window_end
    AND p.computed_at>=q.period_end AND p.computed_at>clock_timestamp()-public.fn_accounting_close_proof_lifetime();
  advanced:=advanced OR n_after>n_before;
  done:=done||jsonb_build_array(jsonb_build_object('scope_kind',q.scope_kind,'scope_id',q.scope_id,
   'period_start',q.period_start,'period_end',q.period_end,'windows',n_windows,'fresh_before',n_before,
   'fresh_after',n_after,'error',v_msg));
  v_msg:=NULL;
 END LOOP;
 PERFORM set_config('app.weekly_accounting_scope_deadline',saved_deadline,true);
 IF NOT advanced THEN RETURN NULL; END IF;
 RETURN jsonb_build_object('success',true,'checked',0,'failed',0,'visited_scopes',0,'more_remaining',true,
  'observed_at',clock_timestamp(),'detail','[]'::jsonb,'window_advance',done);
END
$function$

public.fn_accounting_close_windows_pendi.def:
CREATE OR REPLACE FUNCTION public.fn_accounting_close_windows_pending(p_union_id uuid, p_club_id uuid, p_period_start timestamp with time zone, p_period_end timestamp with time zone)
 RETURNS boolean
 LANGUAGE plpgsql
 SET search_path TO 'public'
AS $function$
-- True when this chunked close attempt had window work to do for the book's
-- next unpaid round (it then proved what its time allowed and the attempt ends
-- as a committed step); false when every window was already proved, the round
-- already has its receipt, or outside a chunked close attempt.
DECLARE v_kind text:=CASE WHEN p_union_id IS NOT NULL THEN 'union' ELSE 'club' END; v_scope uuid:=COALESCE(p_union_id,p_club_id);
 n_have bigint; n_expected bigint;
BEGIN
 IF COALESCE(current_setting('app.weekly_accounting_chunked',true),'')<>'on'
  OR NULLIF(current_setting('app.weekly_accounting_scope_deadline',true),'') IS NULL
  OR v_scope IS NULL OR (p_union_id IS NOT NULL AND p_club_id IS NOT NULL) THEN
  RETURN false;
 END IF;
 IF NOT EXISTS(SELECT 1 FROM public.accounting_routed_settlement_runs r WHERE r.scope_kind=v_kind AND r.scope_id=v_scope
   AND r.period_start=p_period_start AND r.period_end=p_period_end AND r.round_no=2) THEN
 SELECT count(*) INTO n_expected FROM public.fn_accounting_close_windows(p_period_start,p_period_end);
 SELECT count(*) INTO n_have FROM public.fn_accounting_close_windows(p_period_start,p_period_end) w JOIN public.accounting_close_partials p
  ON p.kind='round2_'||v_kind||'_window' AND p.union_id=v_scope AND p.period_start=p_period_start AND p.period_end=p_period_end
  AND p.window_start=w.window_start AND p.window_end=w.window_end
  AND p.computed_at>=p_period_end AND p.computed_at>clock_timestamp()-public.fn_accounting_close_proof_lifetime();
 IF n_have<>n_expected THEN
  PERFORM public.fn_settle_accounting_commission_advance(v_kind,v_scope,p_period_start,p_period_end);
  RETURN true;
 END IF;
 END IF;
 -- ROUND 3 READ ONCE (20261003): a book whose round 3 has no receipt proves its
 -- week's round-3 windows and reads its certificates once
 -- (fn_settle_accounting_rakeback_advance) in attempts of their own.
 IF NOT EXISTS(SELECT 1 FROM public.accounting_routed_settlement_runs r WHERE r.scope_kind=v_kind AND r.scope_id=v_scope
   AND r.period_start=p_period_start AND r.period_end=p_period_end AND r.round_no=3)
  AND public.fn_settle_accounting_rakeback_advance(v_kind,v_scope,p_period_start,p_period_end) THEN
  RETURN true;
 END IF;
 RETURN false;
END $function$

public.fn_accounting_commit_horizon().def:
CREATE OR REPLACE FUNCTION public.fn_accounting_commit_horizon()
 RETURNS timestamp with time zone
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE oldest timestamptz; stamp timestamptz;
BEGIN
 IF NOT pg_catalog.pg_has_role(current_user,'pg_read_all_stats','MEMBER') THEN RETURN NULL; END IF;
 IF EXISTS(SELECT 1 FROM pg_catalog.pg_prepared_xacts) THEN RETURN NULL; END IF;
 stamp:=clock_timestamp();
 SELECT min(a.xact_start) INTO oldest FROM pg_catalog.pg_stat_activity a WHERE a.xact_start IS NOT NULL;
 RETURN least(stamp,COALESCE(oldest,stamp))-interval '2 minutes';
END $function$

public.fn_accounting_correction_prepare(.def:
CREATE OR REPLACE FUNCTION public.fn_accounting_correction_prepare(p_ledger_id uuid)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
 SET "TimeZone" TO 'UTC'
 SET "DateStyle" TO 'ISO,YMD'
AS $function$
DECLARE l public.chip_ledger%ROWTYPE;c public.clubs%ROWTYPE;u public.unions%ROWTYPE;
 scope uuid;endpoint_clubs uuid[];candidate_unions uuid[];party_kind text;party_id uuid;person uuid;party_name text;side int;
 intended public.accounting_correction_documents%ROWTYPE;surviving public.accounting_correction_documents%ROWTYPE;
 issuer_kind text;issuer_id uuid;sender uuid;issuer_name text;payee_kind text;payee_id uuid;recipient uuid;payee_name text;
 endpoint_type text;endpoint_id uuid;incident uuid;failure bigint;expected_key text;audience uuid[];issuer_users uuid[];payee_users uuid[];issued timestamptz:=clock_timestamp();
BEGIN
 SELECT * INTO STRICT l FROM public.chip_ledger WHERE id=p_ledger_id;
 IF l.category IS DISTINCT FROM 'correction' OR l.status IS DISTINCT FROM 'posted'
  OR l.amount IS NULL OR l.amount::text IN('NaN','Infinity','-Infinity') OR l.amount<=0 OR l.amount>9999999999.99 OR l.amount<>round(l.amount,2)
  OR l.created_at IS NULL OR NOT isfinite(l.created_at) OR l.created_at>issued
  OR l.from_type NOT IN('union_bank','union_wallet','club_treasury','agent_wallet','player_wallet')
  OR l.to_type NOT IN('union_bank','union_wallet','club_treasury','agent_wallet','player_wallet')
  OR l.from_entity_id IS NULL OR l.to_entity_id IS NULL
  OR l.table_id IS NOT NULL OR l.hand_id IS NOT NULL OR l.tournament_id IS NOT NULL OR l.settlement_id IS NOT NULL
 THEN RAISE EXCEPTION 'correction_document_source_unverified' USING ERRCODE='23514';END IF;
 -- These are authoritative stored linkage facts, not authentication of the
 -- posted_via marker or proof of the original caller's unrecorded input bytes.
 incident:=NULLIF(l.metadata->>'incident_id','')::uuid;
 failure:=NULLIF(l.metadata->>'write_failure_id','')::bigint;
 expected_key:='correction:'||COALESCE('lwf:'||failure::text,'inc:'||incident::text);
 IF (incident IS NULL AND failure IS NULL) OR l.idempotency_key IS DISTINCT FROM expected_key
  OR (incident IS NOT NULL AND NOT EXISTS(SELECT 1 FROM public.ca_drift_incidents WHERE id=incident))
  OR (failure IS NOT NULL AND NOT EXISTS(SELECT 1 FROM public.ca_ledger_write_failures WHERE id=failure))
 THEN RAISE EXCEPTION 'correction_document_linkage_unverified' USING ERRCODE='23514';END IF;
 SELECT array_agg(DISTINCT x ORDER BY x) INTO endpoint_clubs FROM unnest(ARRAY[
  CASE WHEN l.from_type='club_treasury' THEN l.from_entity_id END,
  CASE WHEN l.to_type='club_treasury' THEN l.to_entity_id END])x WHERE x IS NOT NULL;
 scope:=l.club_id;
 IF scope IS NULL AND cardinality(endpoint_clubs)=1 THEN scope:=endpoint_clubs[1];END IF;
 IF scope IS NULL OR COALESCE(cardinality(endpoint_clubs),0)>1
  OR EXISTS(SELECT 1 FROM unnest(endpoint_clubs)x WHERE x<>scope)
 THEN RAISE EXCEPTION 'correction_document_club_scope_unverified' USING ERRCODE='23514';END IF;
 SELECT * INTO c FROM public.clubs WHERE id=scope FOR SHARE;
 IF NOT FOUND OR c.owner_id IS NULL THEN RAISE EXCEPTION 'correction_document_club_scope_unverified' USING ERRCODE='23514';END IF;
 IF l.union_id IS NOT NULL THEN
  SELECT * INTO u FROM public.unions WHERE id=l.union_id FOR SHARE;
  IF NOT FOUND OR u.owner_id IS NULL THEN RAISE EXCEPTION 'correction_document_union_scope_unverified' USING ERRCODE='23514';END IF;
 END IF;
 FOR side IN 1..2 LOOP
  endpoint_type:=CASE side WHEN 1 THEN l.from_type ELSE l.to_type END;
  endpoint_id:=CASE side WHEN 1 THEN l.from_entity_id ELSE l.to_entity_id END;
  IF endpoint_type IN('union_bank','union_wallet') THEN
   SELECT array_agg(DISTINCT id ORDER BY id) INTO candidate_unions FROM (
    SELECT x.id FROM public.unions x WHERE x.id=endpoint_id
    UNION SELECT w.union_id FROM public.union_wallets w WHERE w.id=endpoint_id)matches;
   IF l.union_id IS NULL OR cardinality(candidate_unions) IS DISTINCT FROM 1 OR candidate_unions[1] IS DISTINCT FROM l.union_id
   THEN RAISE EXCEPTION 'correction_document_union_identity_unverified' USING ERRCODE='23514';END IF;
   party_kind:='union';party_id:=l.union_id;person:=u.owner_id;party_name:=COALESCE(NULLIF(btrim(u.name),''),'Union');
  ELSIF endpoint_type='club_treasury' THEN
   party_kind:='club';party_id:=scope;person:=c.owner_id;party_name:=COALESCE(NULLIF(btrim(c.name),''),'Club');
  ELSE
   party_kind:=CASE endpoint_type WHEN 'agent_wallet' THEN 'agent' ELSE 'player' END;
   party_id:=endpoint_id;person:=endpoint_id;
   SELECT COALESCE(NULLIF(btrim(p.username),''),'Member') INTO party_name FROM public.profiles p WHERE p.id=person;
  END IF;
  IF person IS NULL OR party_name IS NULL OR NOT EXISTS(SELECT 1 FROM public.profiles p WHERE p.id=person)
  THEN RAISE EXCEPTION 'correction_document_recipient_unverified' USING ERRCODE='23514';END IF;
  IF side=1 THEN issuer_kind:=party_kind;issuer_id:=party_id;sender:=person;issuer_name:=party_name;
  ELSE payee_kind:=party_kind;payee_id:=party_id;recipient:=person;payee_name:=party_name;END IF;
 END LOOP;
 -- A club must not receive each individual's correction as a back door into
 -- weekly rakeback detail. The sender remains a real conversation participant.
 SELECT array_agg(user_id ORDER BY user_id) INTO issuer_users FROM public.fn_accounting_party_users(issuer_kind,issuer_id);
 SELECT array_agg(user_id ORDER BY user_id) INTO payee_users FROM public.fn_accounting_party_users(payee_kind,payee_id);
 IF COALESCE(cardinality(issuer_users),0)=0 OR COALESCE(cardinality(payee_users),0)=0
  OR sender=ANY(issuer_users) IS NOT TRUE OR recipient=ANY(payee_users) IS NOT TRUE
 THEN RAISE EXCEPTION 'correction_document_recipient_unverified' USING ERRCODE='23514';END IF;
 SELECT array_agg(DISTINCT x ORDER BY x) INTO audience FROM unnest(
  CASE WHEN issuer_kind='club' AND payee_kind IN('agent','player') THEN payee_users ELSE issuer_users||payee_users END)x;
 intended:=ROW(gen_random_uuid(),1,l.id,gen_random_uuid(),scope,l.union_id,l.club_id,l.union_id,to_jsonb(l),l.amount,
  issuer_kind,issuer_id,payee_kind,payee_id,sender,issuer_name,payee_name,audience,incident,failure,l.created_at,issued)::public.accounting_correction_documents;
 INSERT INTO public.accounting_correction_documents SELECT intended.*;
 SELECT * INTO surviving FROM public.accounting_correction_documents WHERE id=intended.id;
 IF NOT FOUND OR to_jsonb(surviving) IS DISTINCT FROM to_jsonb(intended)
 THEN RAISE EXCEPTION 'correction_document_provenance_write_missing' USING ERRCODE='23514';END IF;
END $function$

public.fn_accounting_credit_change_contr.def:
CREATE OR REPLACE FUNCTION public.fn_accounting_credit_change_contract_v1(p_invoice_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
 SET "TimeZone" TO 'UTC'
 SET "DateStyle" TO 'ISO,YMD'
AS $function$
DECLARE d public.accounting_credit_change_documents_v1%ROWTYPE;
 o public.accounting_credit_reduction_operations_v1%ROWTYPE;
 i public.settlement_invoices%ROWTYPE;payload jsonb;audience uuid[];
BEGIN
 SELECT * INTO d FROM public.accounting_credit_change_documents_v1 WHERE invoice_id=p_invoice_id;
 IF NOT FOUND THEN RAISE EXCEPTION 'credit_change_document_missing' USING ERRCODE='23514';END IF;
 SELECT * INTO o FROM public.accounting_credit_reduction_operations_v1 WHERE id=d.operation_receipt_id;
 IF NOT FOUND THEN RAISE EXCEPTION 'credit_change_operation_missing' USING ERRCODE='23514';END IF;
 SELECT array_agg(DISTINCT u ORDER BY u) INTO audience FROM unnest(ARRAY[o.actor_user_id,o.target_user_id])u;
 payload:=public.fn_accounting_credit_change_payload_v1(d.id);
 SELECT * INTO i FROM public.settlement_invoices WHERE id=d.invoice_id;
 IF NOT FOUND OR d.audience_user_ids IS DISTINCT FROM audience OR d.issued_at IS DISTINCT FROM o.recorded_at
  OR i.invoice_type IS DISTINCT FROM 'credit_limit_change' OR i.club_id IS DISTINCT FROM o.club_id
  OR i.from_entity_type IS DISTINCT FROM 'club' OR i.from_entity_id IS DISTINCT FROM o.club_id::text
  OR i.to_entity_type IS DISTINCT FROM 'agent' OR i.to_entity_id IS DISTINCT FROM o.target_user_id::text
  OR i.gross_amount IS DISTINCT FROM o.applied_reduction OR i.net_amount IS DISTINCT FROM o.applied_reduction
  OR i.deductions IS DISTINCT FROM 0 OR i.status IS DISTINCT FROM 'generated'
  OR i.chips_transferred IS DISTINCT FROM false OR i.transferred_at IS NOT NULL OR i.due_at IS NOT NULL
  OR i.chip_transfer_id IS NOT NULL OR i.adjusts_invoice_id IS NOT NULL OR i.period_id IS NOT NULL
  OR i.source_ledger_id IS NOT NULL OR i.source_credit_invoice_id IS NOT NULL OR i.source_credit_payment_id IS NOT NULL
  OR i.source_credit_reduction_operation_id IS DISTINCT FROM o.id
  OR i.overdue_at IS NOT NULL OR i.reminders_sent IS DISTINCT FROM 0 OR i.last_reminder_at IS NOT NULL
  OR i.notes IS NOT NULL OR i.created_at IS DISTINCT FROM d.issued_at
  OR i.invoice_number IS NULL OR i.breakdown IS DISTINCT FROM jsonb_build_object('category','credit_limit_change','credit_change',payload)
 THEN RAISE EXCEPTION 'credit_change_document_contract_mismatch' USING ERRCODE='23514';END IF;
 RETURN payload;
END $function$

public.fn_accounting_earning_contract(p_.def:
CREATE OR REPLACE FUNCTION public.fn_accounting_earning_contract(p_club_id uuid, p_player_id uuid, p_rake numeric, p_game_union_id uuid, p_terms_at timestamp with time zone)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE member jsonb;agent jsonb;terms jsonb;chain jsonb;remaining numeric;rate numeric;amount numeric;
 seen uuid[];agent_id uuid;parent_id uuid;agent_user uuid;direct_user uuid;union_count int;coordinator_union uuid;union_agreement jsonb;union_house boolean;
BEGIN
 -- Private EXECUTE grants admit only trusted source owners, including the
 -- registration trigger running for a human. Public wrappers verify actors.
 IF p_club_id IS NULL OR p_player_id IS NULL OR p_terms_at IS NULL OR NOT isfinite(p_terms_at) OR p_terms_at>clock_timestamp()
  OR p_rake IS NULL OR p_rake<0 OR p_rake<>round(p_rake,2) OR p_rake::text IN('NaN','Infinity','-Infinity')
 THEN RAISE EXCEPTION 'invalid_accounting_earning_contract' USING ERRCODE='22023'; END IF;
  SELECT count(*),(array_agg((uc.after_terms->>'union_id')::uuid))[1],
   (jsonb_agg(jsonb_build_object('history_id',uc.id,'observed_at',uc.observed_at,'terms',uc.after_terms)))->0
   INTO union_count,coordinator_union,union_agreement FROM (
    SELECT DISTINCT ON(h.entity_key) h.id,h.observed_at,h.after_terms FROM public.accounting_agreement_history h
     WHERE h.entity_type='union_clubs' AND h.club_id=p_club_id AND h.observed_at<=p_terms_at
     ORDER BY h.entity_key,h.observed_at DESC,h.id DESC) uc
    WHERE uc.after_terms IS NOT NULL AND uc.after_terms->>'club_id'=p_club_id::text;
  SELECT EXISTS(SELECT 1 FROM public.clubs c WHERE c.id=p_club_id AND c.is_union IS TRUE
   AND p_game_union_id IS NOT NULL AND (c.id=p_game_union_id OR c.union_id=p_game_union_id)) INTO union_house;
  IF union_house THEN coordinator_union:=p_game_union_id;union_agreement:=NULL; END IF;
  IF union_count>1 OR (p_game_union_id IS NOT NULL AND NOT union_house AND (union_count<>1 OR coordinator_union IS DISTINCT FROM p_game_union_id))
  THEN RAISE EXCEPTION 'cash_commission_earning_club_not_observed' USING ERRCODE='23514'; END IF;
  member:=public.fn_accounting_terms_at('club_members',p_club_id::text||':'||p_player_id::text,p_terms_at);
  terms:=member->'terms';
  IF terms IS NULL OR terms='null'::jsonb OR terms->>'club_id' IS DISTINCT FROM p_club_id::text OR terms->>'user_id' IS DISTINCT FROM p_player_id::text
   OR (terms->>'status' IS NULL OR terms->>'status' NOT IN('active','approved')) OR COALESCE((terms->>'is_active')::boolean,true)=false
  THEN RAISE EXCEPTION 'cash_commission_membership_not_active_at_earning' USING ERRCODE='23514'; END IF;
  direct_user:=NULLIF(terms->>'agent_id','')::uuid; agent:=NULL;
  -- An agent's own historical agreement covers their playing account too.
  -- A promotion without its observed agent row still uses the original upline.
  IF terms->>'role' IN ('super_agent','agent','sub_agent') AND NOT COALESCE(
    (terms->>'player_rakeback_pct')::numeric=0.70 AND EXISTS(SELECT 1 FROM public.clubs owner_club
      WHERE owner_club.id=p_club_id AND owner_club.owner_id=direct_user),false) THEN
   BEGIN agent:=public.fn_accounting_agent_terms_at(p_club_id,p_player_id,p_terms_at);
   EXCEPTION WHEN SQLSTATE '55000' THEN
    IF SQLERRM IN('accounting_terms_not_observed','accounting_terms_not_active') THEN agent:=NULL; ELSE RAISE; END IF;
   END;
  END IF;
  IF agent IS NOT NULL AND agent->'terms' IS NOT NULL AND agent->'terms'<>'null'::jsonb THEN
   NULL; -- The unchanged hierarchy loop validates the own agreement and parents.
  ELSIF (terms->>'player_rakeback_pct')::numeric=0.70 AND EXISTS(
    SELECT 1 FROM public.clubs owner_club WHERE owner_club.id=p_club_id AND owner_club.owner_id=direct_user
  ) THEN
   -- Explicit direct-owner seventy percent deals are club-funded.
   agent:=NULL;
  ELSIF direct_user IS NOT NULL THEN
   BEGIN agent:=public.fn_accounting_agent_terms_at(p_club_id,direct_user,p_terms_at);
   EXCEPTION WHEN SQLSTATE '55000' THEN
    -- An owner is not required to carry an agent agreement. Retain the real
    -- observed player deal during reassignment as well as after its rate edit.
    IF SQLERRM IN('accounting_terms_not_observed','accounting_terms_not_active')
       AND EXISTS(SELECT 1 FROM public.clubs owner_club
         WHERE owner_club.id=p_club_id AND owner_club.owner_id=direct_user)
    THEN agent:=NULL; ELSE RAISE; END IF;
   END;
  ELSE
   BEGIN agent:=public.fn_accounting_agent_terms_at(p_club_id,p_player_id,p_terms_at);
   EXCEPTION WHEN SQLSTATE '55000' THEN
    IF SQLERRM IN('accounting_terms_not_observed','accounting_terms_not_active') THEN agent:=NULL; ELSE RAISE; END IF; END;
  END IF;
  remaining:=p_rake;chain:='[]';seen:=ARRAY[]::uuid[];
  WHILE agent IS NOT NULL AND agent->'terms' IS NOT NULL AND agent->'terms'<>'null'::jsonb LOOP
   terms:=agent->'terms'; agent_id:=(terms->>'id')::uuid;agent_user:=(terms->>'user_id')::uuid;
   IF agent_id IS NULL OR agent_user IS NULL OR agent_id=ANY(seen) OR cardinality(seen)>=64
    OR terms->>'club_id' IS DISTINCT FROM p_club_id::text OR terms->>'status' IS DISTINCT FROM 'active'
    OR terms->>'role' IS NULL OR terms->>'role' NOT IN('super_agent','agent','sub_agent')
   THEN RAISE EXCEPTION 'cash_commission_hierarchy_invalid_at_earning' USING ERRCODE='23514'; END IF;
   seen:=array_append(seen,agent_id);
   rate:=(terms->>'commission_rate')::numeric;
   IF rate>1 THEN rate:=rate/100; END IF;
   IF rate IS NULL OR rate<0 OR rate>1 OR rate::text IN('NaN','Infinity','-Infinity')
   THEN RAISE EXCEPTION 'cash_commission_rate_invalid_at_earning' USING ERRCODE='23514'; END IF;
   -- Preserve the installed agreement model: each upline rate applies to the
   -- remaining rake after the preceding tier. Round each payable to cents.
   amount:=round(remaining*rate,2);
   chain:=chain||jsonb_build_array(jsonb_build_object('agent_id',agent_id,'user_id',agent_user,
    'role',terms->>'role','depth',cardinality(seen),'rake_basis',p_rake,'remaining_basis',remaining,
    'rate',rate,'amount',amount,'agreement',agent));
   remaining:=remaining-amount;
   parent_id:=NULLIF(terms->>'parent_agent_id','')::uuid;
   IF parent_id IS NULL THEN agent:=NULL; ELSE agent:=public.fn_accounting_terms_at('agents',parent_id::text,p_terms_at); END IF;
  END LOOP;
 RETURN jsonb_build_object('player_id',p_player_id,'club_id',p_club_id,'union_id',p_game_union_id,
  'coordinator_union_id',coordinator_union,'rake_credit',p_rake,'membership',member,'tiers',chain,
  'club_residual',remaining,'union_agreement',union_agreement,'is_union_house',union_house,'terms_at',p_terms_at);
END $function$

public.fn_accounting_tournament_commissi.def:
CREATE OR REPLACE FUNCTION public.fn_accounting_tournament_commission_source_guard()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$DECLARE s record;matches int;BEGIN
 IF NEW.source_type='tournament_fee_accrual' THEN
  SELECT f.*,r.recognized_at,r.disposition,b.status accounting_status INTO s FROM public.accounting_effective_tournament_fee_sources f
   JOIN public.accounting_tournament_recognized_sources r ON r.source_id=f.id
   JOIN public.accounting_tournament_fee_recognitions b ON b.tournament_id=r.tournament_id WHERE f.id=NEW.source_id;
  IF NOT FOUND OR s.disposition IS DISTINCT FROM 'earned' OR s.accounting_status IS DISTINCT FROM 'recognized'
   OR NEW.club_id IS DISTINCT FROM s.club_id OR NEW.created_at IS DISTINCT FROM s.recognized_at THEN
   RAISE EXCEPTION 'tournament_commission_recognized_source_required' USING ERRCODE='23514'; END IF;
  SELECT count(*) INTO matches FROM jsonb_array_elements(s.contract->'tiers')t
   WHERE t->>'user_id'=NEW.user_id::text AND (t->>'amount')::numeric=NEW.amount AND (t->>'rate')::numeric=NEW.commission_rate AND NEW.amount>0;
  IF matches<>1 THEN RAISE EXCEPTION 'tournament_commission_disagrees_with_recorded_entitlement' USING ERRCODE='23514'; END IF;
 ELSIF NEW.source_type IN('tournament_fee','tournament_rake_settlement') THEN
  RAISE EXCEPTION 'tournament_commission_requires_canonical_source_writer' USING ERRCODE='23514';
 END IF;
 RETURN NEW;
END$function$

public.fn_accounting_tournament_fee_net_.def:
CREATE OR REPLACE FUNCTION public.fn_accounting_tournament_fee_net_plan(p_tournament_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE cancelled_uncaptured uuid[]:='{}';refund_row record;raw_total numeric;positive_total numeric;refunded_total numeric:=0;expected numeric;raw_reference_sum numeric;
 positive_ids uuid[];negative_ids uuid[];processed uuid[]:='{}';refunded uuid[]:='{}';refs uuid[];direct_positive uuid[];
 pending uuid[];new_refunds uuid[];nested uuid[];covered uuid[];ref uuid;covered_ref uuid;
 refund_map jsonb:='{}';progress boolean;actual_union uuid;scope_count int;active_ids uuid[];refunded_ids uuid[];fingerprint text;
BEGIN
 IF p_tournament_id IS NULL THEN RAISE EXCEPTION 'tournament_required' USING ERRCODE='22023'; END IF;
 IF EXISTS(SELECT 1 FROM (SELECT cover_row.id,cover_row.hand_id,cover_row.table_id,cover_row.club_id,cover_row.rake_amount,cover_row.bbj_contribution,cover_row.pot_size,cover_row.num_players,cover_row.created_at,cover_row.player_contributions,cover_row.global_hand_id,cover_row.is_tournament,cover_row.tournament_id,cover_row.source,cover_row.metadata,cover_row.rake_method,cover_row.returned_uncalled FROM public.rake_records cover_row WHERE cover_row.tournament_id=p_tournament_id AND cover_row.is_tournament AND ((((((COALESCE(octet_length(jsonb_send(cover_row.metadata)), 0))::bigint + (COALESCE(octet_length(jsonb_send(cover_row.player_contributions)), 0))::bigint) + (COALESCE(octet_length(jsonb_send(cover_row.returned_uncalled)), 0))::bigint) <= 448) AND ((((COALESCE(smarter_private.rake_record_jsonb_raw_size(cover_row.metadata), 0))::bigint + (COALESCE(smarter_private.rake_record_jsonb_raw_size(cover_row.player_contributions), 0))::bigint) + (COALESCE(smarter_private.rake_record_jsonb_raw_size(cover_row.returned_uncalled), 0))::bigint) <= 1864) AND (((COALESCE(octet_length(cover_row.source), 0))::bigint + (COALESCE(octet_length(cover_row.rake_method), 0))::bigint) <= 128) AND ((((COALESCE(octet_length(numeric_send(cover_row.rake_amount)), 0))::bigint + (COALESCE(octet_length(numeric_send(cover_row.bbj_contribution)), 0))::bigint) + (COALESCE(octet_length(numeric_send(cover_row.pot_size)), 0))::bigint) <= 128))) UNION ALL SELECT cover_row.id,cover_row.hand_id,cover_row.table_id,cover_row.club_id,cover_row.rake_amount,cover_row.bbj_contribution,cover_row.pot_size,cover_row.num_players,cover_row.created_at,cover_row.player_contributions,cover_row.global_hand_id,cover_row.is_tournament,cover_row.tournament_id,cover_row.source,cover_row.metadata,cover_row.rake_method,cover_row.returned_uncalled FROM public.rake_records cover_row WHERE cover_row.tournament_id=p_tournament_id AND cover_row.is_tournament AND NOT ((((((COALESCE(octet_length(jsonb_send(cover_row.metadata)), 0))::bigint + (COALESCE(octet_length(jsonb_send(cover_row.player_contributions)), 0))::bigint) + (COALESCE(octet_length(jsonb_send(cover_row.returned_uncalled)), 0))::bigint) <= 448) AND ((((COALESCE(smarter_private.rake_record_jsonb_raw_size(cover_row.metadata), 0))::bigint + (COALESCE(smarter_private.rake_record_jsonb_raw_size(cover_row.player_contributions), 0))::bigint) + (COALESCE(smarter_private.rake_record_jsonb_raw_size(cover_row.returned_uncalled), 0))::bigint) <= 1864) AND (((COALESCE(octet_length(cover_row.source), 0))::bigint + (COALESCE(octet_length(cover_row.rake_method), 0))::bigint) <= 128) AND ((((COALESCE(octet_length(numeric_send(cover_row.rake_amount)), 0))::bigint + (COALESCE(octet_length(numeric_send(cover_row.bbj_contribution)), 0))::bigint) + (COALESCE(octet_length(numeric_send(cover_row.pot_size)), 0))::bigint) <= 128)))) r WHERE r.tournament_id=p_tournament_id AND r.is_tournament
