 0))::bigint + (COALESCE(octet_length(jsonb_send(cover_row.player_contributions)), 0))::bigint) + (COALESCE(octet_length(jsonb_send(cover_row.returned_uncalled)), 0))::bigint) <= 448) AND ((((COALESCE(smarter_private.rake_record_jsonb_raw_size(cover_row.metadata), 0))::bigint + (COALESCE(smarter_private.rake_record_jsonb_raw_size(cover_row.player_contributions), 0))::bigint) + (COALESCE(smarter_private.rake_record_jsonb_raw_size(cover_row.returned_uncalled), 0))::bigint) <= 1864) AND (((COALESCE(octet_length(cover_row.source), 0))::bigint + (COALESCE(octet_length(cover_row.rake_method), 0))::bigint) <= 128) AND ((((COALESCE(octet_length(numeric_send(cover_row.rake_amount)), 0))::bigint + (COALESCE(octet_length(numeric_send(cover_row.bbj_contribution)), 0))::bigint) + (COALESCE(octet_length(numeric_send(cover_row.pot_size)), 0))::bigint) <= 128)))) q WHERE q.id=ANY(refs) AND (q.club_id IS DISTINCT FROM refund_row.club_id
