public.fn_accounting_union_earned_plan(p.def:
CREATE OR REPLACE FUNCTION public.fn_accounting_union_earned_plan(p_union_id uuid, p_start timestamp with time zone, p_end timestamp with time zone)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
-- WEEKLY CLOSE SCALE (20260928): a union's weekly close proves the same earned
-- plan up to nine times in one transaction (preparation twice, round 1 twice,
-- round 3, the ECO gate and the invoice evidence), about a minute each at
-- Midway's scale. Inside a close (app.accounting_close_memo='on', set only by
-- fn_process_weekly_accounting_scope for the attempt it is running) the first
-- proof of a (union, week) is kept for the rest of that transaction; a
-- rolled-back attempt forgets it with its subtransaction. Everywhere else the
-- plan is proved on every call, exactly as before, by
-- fn_accounting_union_earned_plan_v3.
DECLARE memo jsonb; memo_key text; plan jsonb;
BEGIN
 IF current_setting('app.accounting_close_memo',true)='on' THEN
  memo_key:=p_union_id::text||'|'||p_start::text||'|'||p_end::text;
  memo:=NULLIF(current_setting('app.accounting_earned_plan_memo',true),'')::jsonb;
  IF memo ? memo_key THEN RETURN memo->memo_key; END IF;
 END IF;
 -- CHUNKED CLOSE CERTIFICATE (20261003): inside a chunked union close attempt a
 -- plan proved by an earlier attempt of this close is answered from
 -- accounting_close_certificates; one proved here is kept there. Off
 -- everywhere else (fn_accounting_close_certificate returns NULL).
 plan:=public.fn_accounting_close_certificate('earned_plan',p_union_id,p_start,p_end);
 IF plan IS NULL THEN
 -- 20261003: the set path certifies the identical plan; anything it does
 -- not certify is proved (and refused) by v3 exactly as before.
 -- CHUNKED CLOSE WINDOWS (20261003): inside a chunked close the plan is
 -- combined from its proved two-hour windows; NULL everywhere else and
 -- while any window is missing, when the set path runs as before.
 plan:=public.fn_accounting_union_earned_plan_combine(p_union_id,p_start,p_end);
 IF plan IS NULL THEN
 plan:=public.fn_accounting_union_earned_plan_sets(p_union_id,p_start,p_end);
 END IF;
 IF plan IS NULL THEN plan:=public.fn_accounting_union_earned_plan_v3(p_union_id,p_start,p_end); END IF;
  PERFORM public.fn_accounting_close_certify('earned_plan',p_union_id,p_start,p_end,plan);
 END IF;
 IF memo_key IS NOT NULL THEN
  PERFORM set_config('app.accounting_earned_plan_memo',(COALESCE(memo,'{}'::jsonb)||jsonb_build_object(memo_key,plan))::text,true);
 END IF;
 RETURN plan;
END $function$

public.fn_accounting_union_earned_plan_a.def:
CREATE OR REPLACE FUNCTION public.fn_accounting_union_earned_plan_advance(p_union_id uuid, p_start timestamp with time zone, p_end timestamp with time zone)
 RETURNS boolean
 LANGUAGE plpgsql
 SET search_path TO 'public'
AS $function$
DECLARE w record; r record; began timestamptz; proved boolean:=false;

 v_l_value jsonb;v_l_key jsonb;v_l_witness jsonb;v_l_counts jsonb;
 v_l_valid boolean;v_l_name text;v_l_number numeric;
 v_l_cached record;
 stop_at timestamptz; v_generation text; v_bad bigint; v_flows jsonb; v_windows bigint; v_fresh bigint;v_hand_projected boolean;v_hand_witness jsonb;v_hand_groups jsonb;
BEGIN
 IF COALESCE(current_setting('app.weekly_accounting_chunked',true),'')<>'on'
  OR current_setting('app.accounting_close_memo',true) IS DISTINCT FROM 'on'
  OR NULLIF(current_setting('app.weekly_accounting_scope_deadline',true),'') IS NULL
  OR p_union_id IS NULL OR p_start IS NULL OR p_end IS NULL OR NOT isfinite(p_start) OR NOT isfinite(p_end) OR p_start>=p_end
  OR p_end>clock_timestamp() THEN
  RETURN NULL;
 END IF;
 began:=NULLIF(current_setting('app.weekly_accounting_scope_deadline',true),'')::timestamptz
  -COALESCE(NULLIF(current_setting('app.weekly_accounting_scope_budget',true),''),'8 minutes')::interval;
 -- THE STATEMENT'S OWN CLOCK (20261015b): an attempt can begin late in its
 -- tick (job 272 visits other scopes first in the same 240 s statement), so a
 -- proving loop also stops a minute before the statement itself would be
 -- cancelled, not only 120 s after the attempt began.
 stop_at:=began+interval '120 seconds';
 IF current_setting('statement_timeout') NOT IN ('0','0ms') THEN
  stop_at:=LEAST(stop_at,statement_timestamp()+current_setting('statement_timeout')::interval-interval '60 seconds');
 END IF;
 IF public.fn_accounting_close_certificate('earned_plan',p_union_id,p_start,p_end) IS NULL THEN
 DELETE FROM public.accounting_close_partials WHERE computed_at<clock_timestamp()-interval '8 days';
 FOR w IN SELECT * FROM public.fn_accounting_close_windows(p_start,p_end) ORDER BY 1 LOOP
  CONTINUE WHEN EXISTS(SELECT 1 FROM public.accounting_close_partials p WHERE p.kind='earned_plan_window' AND p.union_id=p_union_id
   AND p.period_start=p_start AND p.period_end=p_end AND p.window_start=w.window_start AND p.window_end=w.window_end
   AND p.computed_at>=p_end AND p.computed_at>clock_timestamp()-public.fn_accounting_close_proof_lifetime());
  IF proved AND clock_timestamp()>stop_at THEN RETURN false; END IF;
  SELECT * INTO r FROM public.fn_accounting_union_earned_plan_window(p_union_id,w.window_start,w.window_end);
  IF NOT FOUND THEN
   -- v3 over the same window refuses exactly what it refuses in the week.
   PERFORM public.fn_accounting_union_earned_plan_v3(p_union_id,w.window_start,w.window_end);
   RAISE EXCEPTION 'union_earned_plan_window_unproved' USING ERRCODE='55000',
    DETAIL=jsonb_build_object('union_id',p_union_id,'period_start',p_start,'period_end',p_end,'window_start',w.window_start,'window_end',w.window_end)::text;
  END IF;
  INSERT INTO public.accounting_close_partials(kind,union_id,period_start,period_end,window_start,window_end,value,cash_ids,cash_md5,fee_ids,fee_md5,computed_at)
  VALUES('earned_plan_window',p_union_id,p_start,p_end,w.window_start,w.window_end,r.value,r.cash_ids,r.cash_md5,r.fee_ids,r.fee_md5,clock_timestamp())
  ON CONFLICT(kind,union_id,period_start,period_end,window_start) DO UPDATE SET window_end=EXCLUDED.window_end,value=EXCLUDED.value,
   cash_ids=EXCLUDED.cash_ids,cash_md5=EXCLUDED.cash_md5,fee_ids=EXCLUDED.fee_ids,fee_md5=EXCLUDED.fee_md5,computed_at=EXCLUDED.computed_at;
  proved:=true;
 END LOOP;
 -- PROVING WINDOWS IS A WHOLE ATTEMPT (20261015): an attempt that proved a
 -- window ends here, even when it proved the last one, so the closing boundary
 -- and every later step start the next attempt with the whole budget.
 IF proved THEN RETURN false; END IF;
 END IF;
 -- THE WEEK'S ORIGINAL FLOWS ARE PROVED TWO HOURS AT A TIME (20261015b).
 -- fn_union_pnl_evidence_report proves the week's original money flows in one
 -- statement (814,510 flows for the 2026-10-05 week: 162 s alone, 2 GB of
 -- temporary files), which cannot fit an attempt of job 272's 240 s statement
 -- once the attempt's preparation and the tick's other scopes have run, so
 -- every attempt that reached it was cancelled and rolled back. The same proof
 -- is made here one plan window at a time (each flow is proved from its own
 -- row and the week's bounds, so the windows partition the week exactly), kept
 -- as partials like the earned-plan windows, and assembled into the very
 -- certificate the report reads, in an attempt of its own. Only while the
 -- report and the week proof are the reviewed definitions, the window proof is
 -- derived from; otherwise the report proves the week itself, as before.
 IF p_union_id='fade0000-0000-0000-0000-000000000001'::uuid AND p_end>='2026-10-12 07:00Z'::timestamptz THEN
  v_generation:=COALESCE(smarter_private.original_inventory_basis_generation(),'original-inventory-245:unqualified');
 END IF;
 IF v_generation IS NOT DISTINCT FROM 'original-inventory-245:unqualified'
  OR md5(pg_get_functiondef('public.fn_union_pnl_original_flow_evidence(uuid,timestamp with time zone,timestamp with time zone)'::regprocedure))<>'b23655a15587192f137ae4ad57859742'
  OR md5(pg_get_functiondef('public.fn_union_pnl_evidence_report(uuid,timestamp with time zone,timestamp with time zone)'::regprocedure))<>'b36f9e252823addb55be086a26f3dedf'
 THEN RETURN true;END IF;
 IF smarter_private.inventory_basis_cache_read(v_generation,false,'pnl_flows',p_union_id,p_start,p_end) IS NOT NULL
 OR smarter_private.inventory_basis_cache_read(v_generation,true,'pnl_flows',p_union_id,p_start,p_end) IS NOT NULL THEN
 -- Original hand proof progresses only after original flow proof, in its own attempt.
 IF md5(pg_get_functiondef('smarter_private.weekly_hand_parts_witness(uuid,timestamptz,timestamptz,boolean)'::regprocedure)) IS DISTINCT FROM 'a7c22cb171d6d6548707c6aa73fada6d'
 OR md5(pg_get_functiondef('smarter_private.weekly_hand_parts_reduce(uuid,timestamptz,timestamptz,boolean)'::regprocedure)) IS DISTINCT FROM '97fc255997a2faeac593b5b1f5420d4c'
 OR md5(pg_get_functiondef('smarter_private.weekly_hand_parts_read(uuid,timestamptz,timestamptz,text,boolean)'::regprocedure)) IS DISTINCT FROM 'd427fd27d163ba72a7dc3cd50866163d'
 THEN RAISE EXCEPTION 'weekly_hand_parts_owner_changed';END IF;
 IF (SELECT count(*) FROM pg_proc WHERE oid IN('smarter_private.weekly_hand_parts_witness(uuid,timestamptz,timestamptz,boolean)'::regprocedure,'smarter_private.weekly_hand_parts_reduce(uuid,timestamptz,timestamptz,boolean)'::regprocedure,'smarter_private.weekly_hand_parts_read(uuid,timestamptz,timestamptz,text,boolean)'::regprocedure)
  AND proowner='postgres'::regrole AND NOT prosecdef AND provolatile='s' AND proacl::text='{postgres=X/postgres}' AND proconfig=ARRAY['search_path=pg_catalog, public, smarter_private']) IS DISTINCT FROM 3::bigint THEN RAISE EXCEPTION 'weekly_hand_parts_owner_authority_changed';END IF;
 v_hand_projected:=public.fn_union_pnl_projection_ready('cash_outcome_touches');
 -- ORIGINAL CANONICAL LINKED WINDOWS. New proof kind; no existing hand JSON ABI
 -- changes. An attempt that proves any linked unit ends warming before later work.
 IF v_generation IS NOT NULL AND v_generation<>'original-inventory-245:unqualified'THEN
  FOR w IN SELECT * FROM public.fn_accounting_close_windows(p_start,p_end)ORDER BY 1 LOOP
   v_l_witness:=smarter_private.weekly_hand_parts_witness(p_union_id,w.window_start,w.window_end,v_hand_projected);
   v_l_key:=jsonb_build_object('union_id',p_union_id::text,'period_start_epoch',extract(epoch FROM p_start),'period_end_epoch',extract(epoch FROM p_end),'window_start_epoch',extract(epoch FROM w.window_start),'window_end_epoch',extract(epoch FROM w.window_end));v_l_valid:=false;
   SELECT p.*INTO v_l_cached FROM public.accounting_close_partials p WHERE p.kind='pnl_linked_window'
    AND p.union_id=p_union_id AND p.period_start=p_start AND p.period_end=p_end AND p.window_start=w.window_start;
   IF FOUND AND v_l_cached.window_end=w.window_end AND isfinite(v_l_cached.computed_at)
    AND v_l_cached.computed_at>=p_end AND v_l_cached.computed_at>clock_timestamp()-public.fn_accounting_close_proof_lifetime()
    AND v_l_cached.computed_at<=clock_timestamp()AND v_l_cached.cash_ids IS NULL AND v_l_cached.cash_md5 IS NULL
    AND v_l_cached.fee_ids IS NULL AND v_l_cached.fee_md5 IS NULL THEN
    v_l_value:=v_l_cached.value;

 v_l_valid:=false;
 IF jsonb_typeof(v_l_value)='object'
 AND v_l_value->>'contract'='canonical-linked-validation-v1'
 AND v_l_value->>'generation'=v_generation
 AND v_l_value->'projected'=to_jsonb(v_hand_projected)
 AND v_l_value->>'reader_md5'='798e8c95a26ad587da13151675f47fd1'
 AND v_l_value->>'witness_md5'='a7c22cb171d6d6548707c6aa73fada6d'
 AND v_l_value->'input_key'=v_l_key
 AND v_l_value->'witness'=v_l_witness
 AND v_l_value->>'proof_md5'=md5((v_l_value-'proof_md5')::text)
 AND jsonb_typeof(v_l_value->'counts')='object' THEN
  v_l_counts:=v_l_value->'counts';v_l_valid:=true;
  IF(SELECT array_agg(key ORDER BY key)FROM jsonb_object_keys(v_l_counts)key)
    IS DISTINCT FROM ARRAY['bad','resolved','rows','unknown']THEN v_l_valid:=false;END IF;
  IF v_l_valid THEN
   FOREACH v_l_name IN ARRAY ARRAY['rows','bad','resolved','unknown']LOOP
    IF jsonb_typeof(v_l_counts->v_l_name)IS DISTINCT FROM'number'
     OR(v_l_counts->>v_l_name)!~'^[0-9]{1,19}$'THEN v_l_valid:=false;EXIT;END IF;
    v_l_number:=(v_l_counts->>v_l_name)::numeric;
    IF v_l_number>9223372036854775807 THEN v_l_valid:=false;EXIT;END IF;
   END LOOP;
  END IF;
  IF v_l_valid THEN
   IF (v_l_counts->>'rows')::numeric IS DISTINCT FROM
    (v_l_counts->>'bad')::numeric+(v_l_counts->>'resolved')::numeric+(v_l_counts->>'unknown')::numeric THEN v_l_valid:=false;END IF;
  END IF;
 END IF;

   END IF;
   CONTINUE WHEN v_l_valid;
   IF proved AND clock_timestamp()>stop_at THEN RETURN false;END IF;
   -- The canonical reader is a filtered subset of this admitted raw linked
   -- innerjoin bag. An exact zero witness therefore proves an empty result.
   IF (v_l_witness->>'links')::bigint=0 THEN
    v_l_counts:=jsonb_build_object('rows',0,'bad',0,'resolved',0,'unknown',0);
   ELSE
   SELECT jsonb_build_object('rows',count(*),
    'bad',count(*)FILTER(WHERE NOT(k.evidence->>'status'='ready'AND k.evidence->'basis_certified'='true'::jsonb AND k.evidence->'all_players_included'='true'::jsonb)),
    'resolved',count(*)FILTER(WHERE k.evidence->>'status'='ready'AND k.evidence->'basis_certified'='true'::jsonb AND k.evidence->'all_players_included'='true'::jsonb),
    'unknown',count(*)FILTER(WHERE(k.evidence->>'status'='ready'AND k.evidence->'basis_certified'='true'::jsonb AND k.evidence->'all_players_included'='true'::jsonb)IS NULL))
   INTO v_l_counts FROM public.fn_union_pnl_linked_cash_outcomes(p_union_id,w.window_start,w.window_end)k;
   END IF;
   IF v_l_witness IS DISTINCT FROM smarter_private.weekly_hand_parts_witness(p_union_id,w.window_start,w.window_end,v_hand_projected)
    THEN RAISE EXCEPTION 'weekly_linked_parts_sources_changed_during_window';END IF;
   v_l_value:=jsonb_build_object('contract','canonical-linked-validation-v1','generation',v_generation,
    'projected',v_hand_projected,'reader_md5','798e8c95a26ad587da13151675f47fd1',
    'witness_md5','a7c22cb171d6d6548707c6aa73fada6d','input_key',v_l_key,'witness',v_l_witness,'counts',v_l_counts);
   v_l_value:=v_l_value||jsonb_build_object('proof_md5',md5(v_l_value::text));
   INSERT INTO public.accounting_close_partials AS current_proof(kind,union_id,period_start,period_end,window_start,window_end,value,computed_at)
   VALUES('pnl_linked_window',p_union_id,p_start,p_end,w.window_start,w.window_end,v_l_value,clock_timestamp())
   ON CONFLICT(kind,union_id,period_start,period_end,window_start)DO UPDATE SET
    window_end=EXCLUDED.window_end,value=EXCLUDED.value,cash_ids=NULL,cash_md5=NULL,fee_ids=NULL,fee_md5=NULL,computed_at=EXCLUDED.computed_at
   WHERE current_proof.window_end IS DISTINCT FROM EXCLUDED.window_end OR current_proof.value IS DISTINCT FROM EXCLUDED.value
    OR current_proof.cash_ids IS NOT NULL OR current_proof.cash_md5 IS NOT NULL OR current_proof.fee_ids IS NOT NULL OR current_proof.fee_md5 IS NOT NULL
    OR NOT isfinite(current_proof.computed_at)OR current_proof.computed_at<p_end
    OR current_proof.computed_at<=clock_timestamp()-public.fn_accounting_close_proof_lifetime()OR current_proof.computed_at>clock_timestamp();
   -- Revalidate after the upsert while its row lock is held: a stale worker
   -- must roll back rather than overwrite a newer committed window proof.
   IF v_l_witness IS DISTINCT FROM smarter_private.weekly_hand_parts_witness(p_union_id,w.window_start,w.window_end,v_hand_projected)
    THEN RAISE EXCEPTION 'weekly_linked_parts_sources_changed_during_write';END IF;
   proved:=true;
   -- Batch sound empty units within the original stop budget. At most one
   -- nonempty canonical reader call is allowed in any original attempt.
   IF (v_l_witness->>'links')::bigint>0 THEN RETURN false;END IF;
  END LOOP;
  IF proved THEN RETURN false;END IF;
 END IF;

 IF EXISTS(SELECT FROM public.accounting_close_partials p WHERE p.kind='pnl_hands_window' AND p.union_id=p_union_id AND p.period_start=p_start AND p.period_end=p_end
 AND NOT EXISTS(SELECT FROM public.fn_accounting_close_windows(p_start,p_end)cw WHERE cw.window_start=p.window_start)) THEN RAISE EXCEPTION 'weekly_hand_parts_noncanonical_window';END IF;
 FOR w IN SELECT * FROM public.fn_accounting_close_windows(p_start,p_end) ORDER BY 1 LOOP
  v_hand_witness:=smarter_private.weekly_hand_parts_witness(p_union_id,w.window_start,w.window_end,v_hand_projected);
  CONTINUE WHEN EXISTS(SELECT FROM public.accounting_close_partials p WHERE p.kind='pnl_hands_window' AND p.union_id=p_union_id AND p.period_start=p_start AND p.period_end=p_end AND p.window_start=w.window_start AND p.window_end=w.window_end
   AND p.computed_at>=p_end AND p.computed_at>clock_timestamp()-public.fn_accounting_close_proof_lifetime()
   AND p.computed_at<=clock_timestamp() AND jsonb_typeof(p.value->'groups')='array' AND p.value->>'groups_md5'=md5((p.value->'groups')::text)
   AND p.value->>'generation' IS NOT DISTINCT FROM v_generation AND p.value->'projected' IS NOT DISTINCT FROM to_jsonb(v_hand_projected)
   AND p.value->>'contract' IS NOT DISTINCT FROM '9dee2921c7b956281be61a3eb9d7df6e' AND p.value->'witness' IS NOT DISTINCT FROM v_hand_witness);
  IF proved AND clock_timestamp()>stop_at THEN RETURN false;END IF;
  DELETE FROM public.accounting_close_certificates WHERE union_id=p_union_id AND period_start=p_start AND period_end=p_end AND kind IN('pnl_clubs','pnl_clubs_problem');
  v_hand_groups:=smarter_private.weekly_hand_parts_reduce(p_union_id,w.window_start,w.window_end,v_hand_projected);
  IF v_hand_witness IS DISTINCT FROM smarter_private.weekly_hand_parts_witness(p_union_id,w.window_start,w.window_end,v_hand_projected) THEN RAISE EXCEPTION 'weekly_hand_parts_sources_changed_during_window';END IF;
  INSERT INTO public.accounting_close_partials(kind,union_id,period_start,period_end,window_start,window_end,value,computed_at)
  VALUES('pnl_hands_window',p_union_id,p_start,p_end,w.window_start,w.window_end,jsonb_build_object('generation',v_generation,'projected',v_hand_projected,'contract','9dee2921c7b956281be61a3eb9d7df6e','witness',v_hand_witness,'groups',v_hand_groups,'groups_md5',md5(v_hand_groups::text)),clock_timestamp())
  ON CONFLICT(kind,union_id,period_start,period_end,window_start) DO UPDATE SET window_end=EXCLUDED.window_end,value=EXCLUDED.value,cash_ids=NULL,cash_md5=NULL,fee_ids=NULL,fee_md5=NULL,computed_at=EXCLUDED.computed_at;
  proved:=true;
 END LOOP;
 IF proved THEN RETURN false;END IF;
 IF smarter_private.weekly_hand_parts_read(p_union_id,p_start,p_end,v_generation,v_hand_projected) IS NULL THEN RETURN false;END IF;
 RETURN true;
 END IF;
 FOR w IN SELECT * FROM public.fn_accounting_close_windows(p_start,p_end) ORDER BY 1 LOOP
  -- A window that found a problem is re-proved after an hour, as the report
  -- re-proves a week whose flows found one.
  CONTINUE WHEN EXISTS(SELECT 1 FROM public.accounting_close_partials p WHERE p.kind='pnl_flows_window' AND p.union_id=p_union_id
   AND p.period_start=p_start AND p.period_end=p_end AND p.window_start=w.window_start AND p.window_end=w.window_end
   AND p.computed_at>=p_end AND p.computed_at>clock_timestamp()-public.fn_accounting_close_proof_lifetime()
   AND (p.value->>'bad'='0' OR p.computed_at>clock_timestamp()-interval '1 hour')
   AND p.value->>'generation' IS NOT DISTINCT FROM v_generation);
  IF proved AND clock_timestamp()>stop_at THEN RETURN false; END IF;
  SELECT count(*) FILTER(WHERE NOT f.valid),COALESCE(jsonb_agg(to_jsonb(f)),'[]') INTO v_bad,v_flows
   FROM smarter_private.union_pnl_original_flow_evidence_window(p_union_id,p_start,p_end,w.window_start,w.window_end) f;
  INSERT INTO public.accounting_close_partials(kind,union_id,period_start,period_end,window_start,window_end,value,computed_at)
  VALUES('pnl_flows_window',p_union_id,p_start,p_end,w.window_start,w.window_end,
   jsonb_build_object('generation',v_generation,'bad',v_bad,'flows',v_flows),clock_timestamp())
  ON CONFLICT(kind,union_id,period_start,period_end,window_start) DO UPDATE SET window_end=EXCLUDED.window_end,value=EXCLUDED.value,
   cash_ids=NULL,cash_md5=NULL,fee_ids=NULL,fee_md5=NULL,computed_at=EXCLUDED.computed_at;
  proved:=true;
 END LOOP;
 IF proved THEN RETURN false; END IF;
 -- Every window is fresh: the week's flows are its windows' flows and the two
 -- whole-week return families, the same rows the week proof returns.
 SELECT count(*),count(p.window_start) INTO v_windows,v_fresh
  FROM public.fn_accounting_close_windows(p_start,p_end) cw
  LEFT JOIN public.accounting_close_partials p ON p.kind='pnl_flows_window' AND p.union_id=p_union_id
   AND p.period_start=p_start AND p.period_end=p_end AND p.window_start=cw.window_start AND p.window_end=cw.window_end
   AND p.computed_at>=p_end AND p.computed_at>clock_timestamp()-public.fn_accounting_close_proof_lifetime()
   AND (p.value->>'bad'='0' OR p.computed_at>clock_timestamp()-interval '1 hour')
   AND p.value->>'generation' IS NOT DISTINCT FROM v_generation;
 IF v_windows=0 OR v_fresh<>v_windows THEN RETURN false; END IF;
 WITH parts AS MATERIALIZED (
  SELECT p.value FROM public.fn_accounting_close_windows(p_start,p_end) cw
  JOIN public.accounting_close_partials p ON p.kind='pnl_flows_window' AND p.union_id=p_union_id
   AND p.period_start=p_start AND p.period_end=p_end AND p.window_start=cw.window_start AND p.window_end=cw.window_end
 ), tails AS MATERIALIZED (
  SELECT t.* FROM smarter_private.original_restoration_cash_returns(p_union_id,p_start,p_end) t(ledger_id,club_id,user_id,buyins,cashouts,kind,valid)
  UNION ALL
  SELECT t.* FROM smarter_private.original_erased_cash_discharge_returns(p_union_id,p_start,p_end) t(ledger_id,club_id,user_id,buyins,cashouts,kind,valid)
 ) SELECT COALESCE((SELECT sum((value->>'bad')::bigint) FROM parts),0)+(SELECT count(*) FILTER(WHERE NOT valid) FROM tails),
  COALESCE((SELECT jsonb_agg(x.flow) FROM (SELECT e.flow FROM parts CROSS JOIN LATERAL jsonb_array_elements(parts.value->'flows') e(flow)
   UNION ALL SELECT to_jsonb(t) FROM tails t) x),'[]')
 INTO v_bad,v_flows;
 IF v_bad=0 THEN PERFORM smarter_private.inventory_basis_cache_write(v_generation,'pnl_flows',p_union_id,p_start,p_end,jsonb_build_object('bad',v_bad,'flows',v_flows));
 ELSE PERFORM smarter_private.inventory_basis_cache_write(v_generation,'pnl_flows_problem',p_union_id,p_start,p_end,jsonb_build_object('bad',v_bad,'flows',v_flows)); END IF;
 -- Assembling the certificate is the attempt's step; the report reads it next.
 RETURN false;
END $function$

public.fn_accounting_union_earned_plan_c.def:
CREATE OR REPLACE FUNCTION public.fn_accounting_union_earned_plan_combine(p_union_id uuid, p_start timestamp with time zone, p_end timestamp with time zone)
 RETURNS jsonb
 LANGUAGE plpgsql
 SET search_path TO 'public'
AS $function$
DECLARE n_expected bigint; n_have bigint; bank numeric; src numeric; house numeric; fp text; detail jsonb;
BEGIN
 IF COALESCE(current_setting('app.weekly_accounting_chunked',true),'')<>'on'
  OR current_setting('app.accounting_close_memo',true) IS DISTINCT FROM 'on'
  OR p_union_id IS NULL OR p_start IS NULL OR p_end IS NULL OR NOT isfinite(p_start) OR NOT isfinite(p_end) OR p_start>=p_end
  OR p_end>clock_timestamp()
  OR NOT EXISTS(SELECT 1 FROM public.accounting_cash_accrual_cutover WHERE singleton AND starts_at<=p_start) THEN
  RETURN NULL;
 END IF;
 CREATE TEMP TABLE IF NOT EXISTS _close_plan_windows(window_start timestamptz PRIMARY KEY,value jsonb,cash_ids uuid[],cash_md5 bytea,fee_ids uuid[],fee_md5 bytea) ON COMMIT DROP;
 TRUNCATE pg_temp._close_plan_windows;
 INSERT INTO pg_temp._close_plan_windows SELECT p.window_start,p.value,p.cash_ids,p.cash_md5,p.fee_ids,p.fee_md5
  FROM public.fn_accounting_close_windows(p_start,p_end) w JOIN public.accounting_close_partials p
   ON p.kind='earned_plan_window' AND p.union_id=p_union_id AND p.period_start=p_start AND p.period_end=p_end
   AND p.window_start=w.window_start AND p.window_end=w.window_end
   AND p.computed_at>=p_end AND p.computed_at>clock_timestamp()-public.fn_accounting_close_proof_lifetime();
 GET DIAGNOSTICS n_have=ROW_COUNT;
 SELECT count(*) INTO n_expected FROM public.fn_accounting_close_windows(p_start,p_end);
 IF n_have<>n_expected OR n_expected=0 THEN RETURN NULL; END IF;
 SELECT COALESCE(sum((value->>'bank_sum')::numeric),0),COALESCE(sum((value->>'source_sum')::numeric),0),
  COALESCE(sum((value->>'house_sum')::numeric),0) INTO bank,src,house FROM pg_temp._close_plan_windows;
 -- Every window passed the six source proofs, so the set path (and v3) would
 -- reach exactly this conservation test of the week, and refuse as v3 does.
 IF src IS DISTINCT FROM bank THEN RAISE EXCEPTION 'union_earned_rake_does_not_conserve_bank' USING ERRCODE='55000'; END IF;
 -- The set path's fingerprint: md5 of every source's row md5 in (source_type,
 -- source_id) order; every cash_rake_accrual sorts before every
 -- tournament_fee_accrual.
 WITH fingerprint_windows AS MATERIALIZED (SELECT w.cash_ids,w.cash_md5||''::bytea AS cash_md5,w.fee_ids,w.fee_md5||''::bytea AS fee_md5 FROM pg_temp._close_plan_windows w),
 cash_rows AS MATERIALIZED (SELECT u.id,encode(substring(w.cash_md5 FROM (u.ord::int-1)*16+1 FOR 16),'hex') AS row_md5 FROM fingerprint_windows w CROSS JOIN LATERAL unnest(w.cash_ids) WITH ORDINALITY u(id,ord)),
 fee_rows AS MATERIALIZED (SELECT u.id,encode(substring(w.fee_md5 FROM (u.ord::int-1)*16+1 FOR 16),'hex') AS row_md5 FROM fingerprint_windows w CROSS JOIN LATERAL unnest(w.fee_ids) WITH ORDINALITY u(id,ord))
 SELECT md5(COALESCE((SELECT string_agg(c.row_md5,'' ORDER BY c.id) FROM cash_rows c),'')
  ||COALESCE((SELECT string_agg(f.row_md5,'' ORDER BY f.id) FROM fee_rows f),'')) INTO fp;
 SELECT COALESCE(jsonb_agg(to_jsonb(b) ORDER BY club_id,game_type),'[]') INTO detail FROM (
  SELECT (e->>'club_id')::uuid AS club_id,e->>'game_type' AS game_type,sum((e->>'rake_in')::numeric) AS rake_in,
   CASE WHEN sum((e->>'rake_in')::numeric)>0 THEN sum((e->>'weighted')::numeric)/sum((e->>'rake_in')::numeric) ELSE 0 END AS rate,
   trunc(sum((e->>'weighted')::numeric),2) AS payout
   FROM pg_temp._close_plan_windows w CROSS JOIN LATERAL jsonb_array_elements(w.value->'basis') e
   GROUP BY (e->>'club_id')::uuid,e->>'game_type') b;
 RETURN jsonb_build_object('accounting_version',3,'union_id',p_union_id,'period_start',p_start,'period_end',p_end,
  'period_rake',bank,'earned_rake',src,'house_rake',house,'source_fingerprint',fp,'basis_detail',detail);
END $function$

public.fn_accounting_union_eco_capture().def:
CREATE OR REPLACE FUNCTION public.fn_accounting_union_eco_capture()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE b jsonb; a jsonb; stamp timestamptz:=(public.fn_union_pnl_original_frame()).observed_at; moved boolean;
BEGIN
 b:=CASE WHEN TG_OP='INSERT' THEN NULL ELSE public.fn_accounting_union_eco_terms(OLD.settings) END;
 a:=CASE WHEN TG_OP='DELETE' THEN NULL ELSE public.fn_accounting_union_eco_terms(NEW.settings) END;
 moved:=TG_OP='UPDATE' AND OLD.id IS DISTINCT FROM NEW.id;
 IF b IS NOT DISTINCT FROM a AND NOT moved THEN RETURN COALESCE(NEW,OLD); END IF;
 INSERT INTO public.accounting_agreement_history(entity_type,entity_key,union_id,club_id,event_type,
  observed_at,actor_id,before_terms,after_terms)
 VALUES('unions',CASE WHEN TG_OP='INSERT' THEN NEW.id ELSE OLD.id END::text,
  CASE WHEN TG_OP='INSERT' THEN NEW.id ELSE OLD.id END,NULL,CASE WHEN moved THEN 'DELETE' ELSE TG_OP END,
  stamp,auth.uid(),b,CASE WHEN moved THEN NULL ELSE a END);
 IF moved THEN
  INSERT INTO public.accounting_agreement_history(entity_type,entity_key,union_id,club_id,event_type,
   observed_at,actor_id,before_terms,after_terms)
  VALUES('unions',NEW.id::text,NEW.id,NULL,'INSERT',stamp,auth.uid(),NULL,a);
 END IF;
 RETURN COALESCE(NEW,OLD);
END $function$

public.fn_accrue_cash_hand_commissions(p.def:
CREATE OR REPLACE FUNCTION public.fn_accrue_cash_hand_commissions(p_hand_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE source public.rake_records%ROWTYPE; batch public.accounting_cash_accrual_batches%ROWTYPE;
 fingerprint text; plan jsonb; player jsonb; source_id uuid; count_rows int:=0; cutoff timestamptz;scope record;week_start timestamptz;week_end timestamptz;
BEGIN
 IF NOT public.fn_caller_is_engine() THEN RAISE EXCEPTION 'service_role_required' USING ERRCODE='42501'; END IF;
 IF p_hand_id IS NULL THEN RAISE EXCEPTION 'cash_hand_id_required' USING ERRCODE='22023'; END IF;
 PERFORM pg_advisory_xact_lock(hashtextextended('accounting_cash_hand:'||p_hand_id::text,0));
 SELECT * INTO source FROM public.rake_records WHERE hand_id=p_hand_id FOR SHARE;
 IF NOT FOUND OR COALESCE(source.is_tournament,false) OR source.tournament_id IS NOT NULL OR source.rake_amount<=0
 THEN RAISE EXCEPTION 'cash_rake_source_required' USING ERRCODE='23514'; END IF;
 SELECT md5(jsonb_build_object('record',source.id,'hand',source.hand_id,'rake',source.rake_amount,'earned_at',source.created_at,
   'shares',COALESCE(jsonb_agg(jsonb_build_array(a.id,a.player_id,a.club_id,a.weighted_rake_credit) ORDER BY a.player_id),'[]'::jsonb))::text)
 INTO fingerprint FROM public.rake_attributions a WHERE a.rake_record_id=source.id;
 SELECT * INTO batch FROM public.accounting_cash_accrual_batches WHERE rake_record_id=source.id;
 IF FOUND THEN
  IF batch.source_fingerprint<>fingerprint THEN RAISE EXCEPTION 'cash_accrual_source_changed_after_recording' USING ERRCODE='23514'; END IF;
  -- An explicit restart may admit a bounded, expected atomic-history
  -- correction before this original accrual's duplicate return. Ordinary
  -- duplicate requests retain their existing behavior and do not reprice.
  IF NULLIF(current_setting('app.accounting_atomic_contracts',true),'') IS NOT NULL THEN
   PERFORM smarter_private.admit_cash_atomic_contracts(source.id,current_setting('app.accounting_atomic_contracts')::jsonb);
  END IF;
  IF NULLIF(current_setting('app.accounting_funding_contracts',true),'') IS NOT NULL THEN
   PERFORM smarter_private.admit_cash_funding_contracts(source.id,current_setting('app.accounting_funding_contracts')::jsonb);
  END IF;
  RETURN jsonb_build_object('recorded',true,'duplicate',true,'status',batch.status,'source_version',2);
 END IF;
 IF NOT public.fn_ca_launch_accounting_accepts(source.club_id,source.created_at) THEN
  RETURN jsonb_build_object('status','waived','recorded',false,'reason','owner_directed_launch_waiver');
 END IF;
 SELECT starts_at INTO cutoff FROM public.accounting_cash_accrual_cutover WHERE singleton;
 IF cutoff IS NULL THEN RAISE EXCEPTION 'cash_accrual_cutover_missing' USING ERRCODE='23514'; END IF;
 -- Legacy rows remain untouched. Recording this gap is not a commission
 -- credit or a successful weekly close. The coordinator must reject it.
 IF source.created_at<cutoff THEN
  INSERT INTO public.accounting_cash_accrual_batches(rake_record_id,hand_id,earned_at,source_fingerprint,status)
   VALUES(source.id,source.hand_id,source.created_at,fingerprint,'legacy_unverified');
  RETURN jsonb_build_object('recorded',true,'status','legacy_unverified','requires_reconciliation',true,'source_version',2);
 END IF;
 IF EXISTS(SELECT 1 FROM public.agent_commissions ac WHERE ac.source_id=source.hand_id AND ac.source_type IN('rake','rake_settlement'))
 THEN RAISE EXCEPTION 'cash_accrual_legacy_writer_after_cutover' USING ERRCODE='23514'; END IF;
 plan:=public.fn_accounting_cash_commission_plan(source.id);
 week_start:=public.fn_union_week_start(source.created_at);week_end:=public.fn_union_week_start(week_start+interval '8 days');
 FOR scope IN SELECT DISTINCT CASE WHEN p->>'coordinator_union_id' IS NOT NULL THEN 'union-accounting:' ELSE 'club-accounting:' END
   ||COALESCE(p->>'coordinator_union_id',p->>'club_id')||':'||extract(epoch FROM week_start)::text||':'||extract(epoch FROM week_end)::text AS lock_key
   FROM jsonb_array_elements(plan->'players')p ORDER BY lock_key LOOP
  -- Shared: an accrual excludes the weekly close, never a sibling accrual.
  PERFORM pg_advisory_xact_lock_shared(hashtextextended(scope.lock_key,0));
 END LOOP;
 -- An empty or zero-own-commission completed week still closes the source set.
 IF EXISTS(SELECT 1 FROM public.accounting_routed_settlement_runs r CROSS JOIN LATERAL jsonb_array_elements(plan->'players')p
  WHERE r.period_start<=source.created_at AND r.period_end>source.created_at
   AND((r.union_id IS NOT NULL AND r.union_id::text=p->>'coordinator_union_id')
    OR(r.standalone_club_id IS NOT NULL AND p->>'coordinator_union_id' IS NULL AND r.standalone_club_id::text=p->>'club_id')))
 THEN RAISE EXCEPTION 'cash_accrual_closed_period_requires_adjustment' USING ERRCODE='23514'; END IF;
 INSERT INTO public.accounting_cash_accrual_batches(rake_record_id,hand_id,earned_at,source_fingerprint,status,plan)
  VALUES(source.id,source.hand_id,source.created_at,fingerprint,'accrued',plan);
 FOR player IN SELECT value FROM jsonb_array_elements(plan->'players') LOOP
  IF EXISTS(SELECT 1 FROM public.agent_commission_settlements s WHERE s.club_id=(player->>'club_id')::uuid
   AND source.created_at>=s.period_start AND source.created_at<s.period_end)
  THEN RAISE EXCEPTION 'cash_accrual_closed_period_requires_adjustment' USING ERRCODE='23514'; END IF;
  INSERT INTO public.accounting_cash_rake_sources(rake_record_id,player_id,club_id,union_id,coordinator_union_id,earned_at,rake_credit,contract)
   VALUES(source.id,(player->>'player_id')::uuid,(player->>'club_id')::uuid,(player->>'union_id')::uuid,(player->>'coordinator_union_id')::uuid,source.created_at,(player->>'rake_credit')::numeric,player)
   RETURNING id INTO source_id;
  count_rows:=count_rows+public.fn_post_accounting_commission_source(source_id,'cash_rake_accrual',source.created_at,player);
 END LOOP;
 RETURN jsonb_build_object('recorded',true,'status','accrued','source_version',2,'rows_written',count_rows);
END $function$

public.fn_admin_holds_no_player_wallet().def:
CREATE OR REPLACE FUNCTION public.fn_admin_holds_no_player_wallet()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE v_is_union boolean;
BEGIN
  IF COALESCE(NEW.role, 'player') <> 'admin' THEN RETURN NEW; END IF;

  SELECT COALESCE(c.is_union, false) INTO v_is_union FROM public.clubs c WHERE c.id = NEW.club_id;
  IF COALESCE(v_is_union, false) THEN RETURN NEW; END IF;

  IF TG_OP = 'UPDATE' AND OLD.role IS DISTINCT FROM NEW.role
     AND (COALESCE(NEW.chip_balance, 0) <> 0
          OR COALESCE(NEW.locked_chips, 0) <> 0
          OR COALESCE(NEW.held_chips, 0) <> 0
          OR COALESCE(NEW.promo_balance, 0) <> 0) THEN
    RAISE EXCEPTION 'Cash Out The Player Wallet Before Making This Member An Admin'
      USING ERRCODE = 'check_violation',
            DETAIL = format('chip_balance %s, locked %s, held %s, promo %s',
                            COALESCE(NEW.chip_balance, 0), COALESCE(NEW.locked_chips, 0),
                            COALESCE(NEW.held_chips, 0), COALESCE(NEW.promo_balance, 0));
  END IF;

  IF COALESCE(NEW.chip_balance, 0) > 0
     AND (TG_OP = 'INSERT' OR COALESCE(NEW.chip_balance, 0) > COALESCE(OLD.chip_balance, 0)) THEN
    RAISE EXCEPTION 'An Admin Does Not Hold A Player Wallet'
      USING ERRCODE = 'check_violation',
            HINT = 'Send To The Agent Wallet Or The Club Bank Instead.';
  END IF;

  RETURN NEW;
END;
$function$

public.fn_admin_update_agent(p_agent_id.def:
CREATE OR REPLACE FUNCTION public.fn_admin_update_agent(p_agent_id uuid, p_status text DEFAULT NULL::text, p_role text DEFAULT NULL::text, p_credit_limit numeric DEFAULT NULL::numeric, p_commission_rate numeric DEFAULT NULL::numeric, p_player_rakeback_rate numeric DEFAULT NULL::numeric, p_assigned_by uuid DEFAULT NULL::uuid, p_credit_reason text DEFAULT NULL::text, p_is_prepaid boolean DEFAULT NULL::boolean)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'extensions'
AS $function$
DECLARE
  v_caller uuid := (SELECT auth.uid());
  v_club_id uuid; v_user_id uuid; v_parent uuid; v_old_limit numeric; v_parent_limit numeric;
  v_member_role text; v_role_res jsonb;
  v_prepaid_now boolean; v_limit_now numeric; v_used_now numeric;
  v_prepaid_after boolean; v_limit_after numeric;
  v_touches_funding boolean;
  v_written public.agents%ROWTYPE;
  v_assignment public.credit_assignments%ROWTYPE;
BEGIN
  IF p_agent_id IS NULL THEN RETURN jsonb_build_object('success', false, 'error', 'agent id required'); END IF;
  IF v_caller IS NULL THEN RETURN jsonb_build_object('success', false, 'error', 'authentication required'); END IF;
  SELECT club_id, user_id, parent_agent_id, credit_limit INTO v_club_id, v_user_id, v_parent, v_old_limit
  FROM agents WHERE id = p_agent_id;
  IF v_club_id IS NULL THEN RETURN jsonb_build_object('success', false, 'error', 'agent not found'); END IF;
  PERFORM pg_advisory_xact_lock(hashtextextended('agent-agreement:'||v_club_id::text,0));
  SELECT user_id,parent_agent_id,credit_limit INTO v_user_id,v_parent,v_old_limit FROM public.agents WHERE id=p_agent_id AND club_id=v_club_id FOR UPDATE;
  IF NOT FOUND THEN RETURN jsonb_build_object('success',false,'error','agent scope changed');END IF;
  IF NOT EXISTS (
    SELECT 1 FROM clubs c WHERE c.id = v_club_id AND (
      c.owner_id = v_caller
      OR EXISTS (SELECT 1 FROM club_members cm WHERE cm.club_id = v_club_id AND cm.user_id = v_caller
                 AND cm.role IN ('owner','co_owner','admin') AND cm.status IN ('active','approved')))
  ) THEN
    RETURN jsonb_build_object('success', false, 'error', 'not authorized to manage this club''s agents');
  END IF;
  IF p_status IS NOT NULL AND p_status NOT IN ('active','suspended','frozen') THEN
    RETURN jsonb_build_object('success', false, 'error', 'invalid status'); END IF;
  IF p_role IS NOT NULL AND p_role NOT IN ('super_agent','agent','sub_agent') THEN
    RETURN jsonb_build_object('success', false, 'error', 'invalid role'); END IF;
  IF p_credit_limit IS NOT NULL AND (p_credit_limit::text IN ('NaN','Infinity','-Infinity') OR p_credit_limit < 0 OR p_credit_limit <> round(p_credit_limit,2)) THEN
    RETURN jsonb_build_object('success', false, 'error', 'credit_limit must be finite, nonnegative and in whole chip cents'); END IF;
  -- The table CHECK is 0..0.70 and 0..0.50. Validating against 0..100 let a
  -- caller who meant "25%" past this line and into a raw 23514 from Postgres.
  IF p_commission_rate IS NOT NULL AND (p_commission_rate < 0 OR p_commission_rate > 0.70) THEN
    RETURN jsonb_build_object('success', false, 'error', 'commission_rate must be between 0 and 0.70'); END IF;
  IF p_player_rakeback_rate IS NOT NULL AND (p_player_rakeback_rate < 0 OR p_player_rakeback_rate > 0.50) THEN
    RETURN jsonb_build_object('success', false, 'error', 'player_rakeback_rate must be between 0 and 0.50'); END IF;

  -- ---------------------------------------------------------------------------
  -- THE FUNDING PAIR
  -- ---------------------------------------------------------------------------
  SELECT COALESCE(is_prepaid, false), COALESCE(credit_limit, 0), COALESCE(credit_used, 0)
    INTO v_prepaid_now, v_limit_now, v_used_now
    FROM agents WHERE id = p_agent_id;

  v_touches_funding := (p_is_prepaid IS NOT NULL OR p_credit_limit IS NOT NULL);
  v_prepaid_after   := COALESCE(p_is_prepaid, v_prepaid_now);
  v_limit_after     := COALESCE(p_credit_limit, v_limit_now);

  IF v_touches_funding THEN
    -- Granting a line IS the choice of credit. Refusing here instead would
    -- dead-end every "raise this agent's limit" call against a prepaid agent,
    -- and no screen moves them to credit first.
    IF p_is_prepaid IS NULL AND COALESCE(p_credit_limit, 0) > 0 THEN
      v_prepaid_after := false;
    END IF;

    -- And moving somebody TO prepaid closes the line, for the same reason in
    -- reverse: prepaid and a line cannot both be true.
    IF COALESCE(p_is_prepaid, false) AND p_credit_limit IS NULL THEN
      v_limit_after := 0;
    END IF;

    -- Saying both, and contradicting yourself, is still a mistake worth naming.
    IF v_prepaid_after AND COALESCE(v_limit_after, 0) <> 0 THEN
      RETURN jsonb_build_object('success', false,
        'error', 'a prepaid agent carries no credit line. Send prepaid on its own, or a credit limit on its own.');
    END IF;

    -- The pair that can send nothing at all.
    IF NOT v_prepaid_after AND COALESCE(v_limit_after, 0) <= 0 THEN
      RETURN jsonb_build_object('success', false, 'needs_funding', true,
        'error', 'an agent on credit needs a limit greater than 0. Set them prepaid instead, or give a limit.');
    END IF;

    -- A debt outlives the line it was drawn against, so the line cannot simply
    -- be taken away while it is still owed.
    IF v_prepaid_after AND v_used_now > 0 THEN
      RETURN jsonb_build_object('success', false,
        'error', 'this agent still owes ' || trim(to_char(v_used_now, 'FM999,999,999,990.00'))
                 || ' chips on their credit line. Settle the invoice before moving them to prepaid.',
        'credit_used', v_used_now);
    END IF;

    -- Lowering a limit below what has already been drawn violates check_credit
    -- and used to reach the client as a raw 23514 with no explanation.
    IF NOT v_prepaid_after AND v_limit_after < v_used_now THEN
      RETURN jsonb_build_object('success', false,
        'error', 'that limit is below the ' || trim(to_char(v_used_now, 'FM999,999,999,990.00'))
                 || ' chips already drawn. Take a payment first, or set a limit of at least that much.',
        'credit_used', v_used_now, 'requested_limit', v_limit_after);
    END IF;
  END IF;

  IF v_touches_funding AND v_parent IS NOT NULL THEN
    SELECT credit_limit INTO v_parent_limit FROM agents WHERE id = v_parent AND club_id=v_club_id;
    IF v_parent_limit IS NOT NULL AND v_limit_after > v_parent_limit THEN
      RETURN jsonb_build_object('success', false, 'error', 'credit limit cannot exceed parent agent limit');
    END IF;
  END IF;

  SELECT role INTO v_member_role FROM club_members
   WHERE club_id = v_club_id AND user_id = v_user_id;

  -- Dan, B-02, 2026-08-31: OWNERS KEEP EARNING. This list used to include
  -- 'owner', which no rule anywhere else does: trg_agents_staff_earn_no_rakeback
  -- covers co_owner and admin only, and one live owner already holds an active
  -- agents row at 0.30 / 0.20 that this branch would have refused to edit.
  IF v_member_role IN ('co_owner','admin')
     AND (COALESCE(p_commission_rate, 0) <> 0 OR COALESCE(p_player_rakeback_rate, 0) <> 0)
     AND p_role IS NULL THEN
    RETURN jsonb_build_object('success', false,
      'error', 'this member is club staff and earns no rakeback. Change their role first.');
  END IF;

  -- The role change goes through the one door, so the grant matrix, the
  -- downline guard, the funding choice and the audit row apply here too. The
  -- RESOLVED funding pair is forwarded, not the raw arguments: the callee
  -- applies the same prepaid-or-a-line rule, and sending it a bare NULL where
  -- this call has already decided would make the two disagree.
  IF p_role IS NOT NULL AND v_member_role IS NOT NULL AND v_member_role <> p_role THEN
    v_role_res := public.fn_club_set_member_role(
      v_club_id, v_user_id, p_role, v_caller,
      p_commission_rate, p_player_rakeback_rate,
      CASE WHEN v_touches_funding THEN v_prepaid_after ELSE NULL END,
      CASE WHEN v_touches_funding THEN v_limit_after   ELSE NULL END);
    IF NOT COALESCE((v_role_res ->> 'success')::boolean, false) THEN
      RAISE EXCEPTION 'agent_role_change_refused' USING ERRCODE='PAG01';
    END IF;
  END IF;

  UPDATE agents SET
    status = COALESCE(p_status, status),
    role = COALESCE(p_role, role),
    credit_limit = CASE WHEN v_touches_funding THEN v_limit_after ELSE credit_limit END,
    commission_rate = COALESCE(p_commission_rate, commission_rate),
    player_rakeback_rate = COALESCE(p_player_rakeback_rate, player_rakeback_rate),
    is_prepaid = CASE WHEN v_touches_funding THEN v_prepaid_after ELSE is_prepaid END,
    updated_at = now()
  WHERE id = p_agent_id RETURNING * INTO v_written;
  IF NOT FOUND OR v_written.id IS DISTINCT FROM p_agent_id
    OR v_written.club_id IS DISTINCT FROM v_club_id OR v_written.user_id IS DISTINCT FROM v_user_id THEN
    RAISE EXCEPTION 'credit_admin_agent_write_unconfirmed' USING ERRCODE='23514';
  END IF;
  IF v_touches_funding AND (v_written.credit_limit IS DISTINCT FROM v_limit_after
    OR v_written.is_prepaid IS DISTINCT FROM v_prepaid_after) THEN
    RAISE EXCEPTION 'credit_admin_funding_write_unconfirmed' USING ERRCODE='23514';
  END IF;

  IF NOT EXISTS(SELECT 1 FROM public.agents a WHERE a.id=p_agent_id AND to_jsonb(a)=to_jsonb(v_written)) THEN
    RAISE EXCEPTION 'credit_admin_agent_retained_mismatch' USING ERRCODE='23514';
  END IF;

  IF v_touches_funding AND v_limit_after <> COALESCE(v_old_limit, -1) THEN
    INSERT INTO credit_assignments (agent_id, assigned_by, old_limit, new_limit, reason)
    VALUES (p_agent_id, v_caller, v_old_limit, v_limit_after, p_credit_reason)
    RETURNING * INTO v_assignment;
    IF NOT FOUND OR v_assignment.id IS NULL OR v_assignment.agent_id IS DISTINCT FROM p_agent_id
      OR v_assignment.assigned_by IS DISTINCT FROM v_caller
      OR v_assignment.old_limit IS DISTINCT FROM v_old_limit OR v_assignment.new_limit IS DISTINCT FROM v_limit_after
      OR v_assignment.reason IS DISTINCT FROM p_credit_reason OR v_assignment.created_at IS NULL
      OR NOT isfinite(v_assignment.created_at) THEN
      RAISE EXCEPTION 'credit_admin_assignment_write_unconfirmed' USING ERRCODE='23514';
    END IF;
    IF NOT EXISTS(SELECT 1 FROM public.credit_assignments a WHERE a.id=v_assignment.id AND to_jsonb(a)=to_jsonb(v_assignment)) THEN
      RAISE EXCEPTION 'credit_admin_assignment_retained_mismatch' USING ERRCODE='23514';
    END IF;
  END IF;

  -- Assignment triggers are part of this write; verify the surviving agent after them.
  IF NOT EXISTS(SELECT 1 FROM public.agents a WHERE a.id=p_agent_id AND to_jsonb(a)=to_jsonb(v_written)) THEN
    RAISE EXCEPTION 'credit_admin_agent_retained_mismatch' USING ERRCODE='23514';
  END IF;

  RETURN jsonb_build_object('success', true, 'agent_id', p_agent_id, 'club_id', v_club_id,
    'credit_assignment_id',v_assignment.id,
    'is_prepaid', CASE WHEN v_touches_funding THEN v_prepaid_after ELSE v_prepaid_now END,
    'credit_limit', CASE WHEN v_touches_funding THEN v_limit_after ELSE v_limit_now END);
EXCEPTION WHEN SQLSTATE 'PAG01' THEN
  -- This block rolls back the agent insert/update and every role-callee write.
  RETURN COALESCE(v_role_res,jsonb_build_object('success',false,'error','role change refused'));
END;
$function$

public.fn_agent_credit_control_revision_.def:
CREATE OR REPLACE FUNCTION public.fn_agent_credit_control_revision_v1()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'pg_catalog'
AS $function$
BEGIN
 IF TG_OP='INSERT' THEN
  IF NEW.credit_control_revision IS DISTINCT FROM 0 THEN
   RAISE EXCEPTION 'credit_control_revision_is_managed' USING ERRCODE='23514';END IF;
  RETURN NEW;
 END IF;
 IF NEW.credit_control_revision IS DISTINCT FROM OLD.credit_control_revision THEN
  RAISE EXCEPTION 'credit_control_revision_is_managed' USING ERRCODE='23514';END IF;
 IF ROW(NEW.club_id,NEW.user_id,NEW.credit_limit,NEW.credit_used,NEW.is_prepaid,NEW.status,NEW.role,NEW.parent_agent_id)
    IS DISTINCT FROM ROW(OLD.club_id,OLD.user_id,OLD.credit_limit,OLD.credit_used,OLD.is_prepaid,OLD.status,OLD.role,OLD.parent_agent_id) THEN
  IF OLD.credit_control_revision=9223372036854775807 THEN
   RAISE EXCEPTION 'credit_control_revision_exhausted' USING ERRCODE='22003';END IF;
  NEW.credit_control_revision:=OLD.credit_control_revision+1;
 END IF;
 RETURN NEW;
END $function$

public.fn_agent_default_prepaid().def:
CREATE OR REPLACE FUNCTION public.fn_agent_default_prepaid()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'pg_catalog'
AS $function$
BEGIN
  IF NEW.is_prepaid IS NULL OR NEW.credit_limit IS NULL
     OR NEW.credit_limit::text IN ('NaN', 'Infinity', '-Infinity')
     OR NEW.credit_limit < 0 THEN
    RAISE EXCEPTION 'Choose Valid Prepaid Or Credit Line Terms.' USING ERRCODE = '23514';
  END IF;
  IF NEW.is_prepaid AND NEW.credit_limit <> 0 THEN
    RAISE EXCEPTION 'A Prepaid Agent Carries No Credit Line.' USING ERRCODE = '23514';
  END IF;
  IF NOT NEW.is_prepaid AND NEW.credit_limit <= 0 THEN
    RAISE EXCEPTION 'A Credit Line Must Be Greater Than Zero.' USING ERRCODE = '23514';
  END IF;
  IF COALESCE(NEW.credit_used, 0) > NEW.credit_limit THEN
    RAISE EXCEPTION 'Settle Outstanding Credit Before Reducing The Line Or Choosing Prepaid.'
      USING ERRCODE = '23514';
  END IF;
  RETURN NEW;
END
$function$

public.fn_agent_set_player_rakeback(p_cl.def:
CREATE OR REPLACE FUNCTION public.fn_agent_set_player_rakeback(p_club_id uuid, p_rate numeric)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE
  v_caller uuid := auth.uid();
  v_agent public.agents%ROWTYPE;
  v_role text;
  v_old numeric;
BEGIN
  IF v_caller IS NULL THEN
    RETURN jsonb_build_object('success', false, 'error', 'authentication required');
  END IF;
  IF p_club_id IS NULL OR p_rate IS NULL OR p_rate::text IN ('NaN','Infinity','-Infinity') THEN
    RETURN jsonb_build_object('success', false, 'error', 'a club and a rate are required');
  END IF;

  SELECT cm.role INTO v_role
    FROM public.club_members cm
   WHERE cm.club_id = p_club_id AND cm.user_id = v_caller
     AND coalesce(cm.status, 'approved') IN ('active', 'approved');
  IF v_role IS NULL OR v_role NOT IN ('super_agent', 'agent', 'sub_agent') THEN
    RETURN jsonb_build_object('success', false, 'error', 'only an agent sets the rakeback their players receive');
  END IF;

  PERFORM pg_advisory_xact_lock(hashtextextended('agent-agreement:' || p_club_id::text, 0));
  SELECT * INTO v_agent FROM public.agents
   WHERE club_id = p_club_id AND user_id = v_caller AND status = 'active'
   FOR UPDATE;
  IF NOT FOUND THEN
    RETURN jsonb_build_object('success', false, 'error', 'no active agent agreement in this club');
  END IF;

  IF p_rate < 0 OR p_rate > 0.50 THEN
    RETURN jsonb_build_object('success', false, 'error', 'player rakeback must be between 0 and 50 percent');
  END IF;
  IF p_rate > v_agent.commission_rate THEN
    RETURN jsonb_build_object('success', false,
      'error', 'player rakeback cannot exceed your own rate of '
               || trim(to_char(v_agent.commission_rate * 100, 'FM990.00')) || ' percent',
      'max_rate', v_agent.commission_rate);
  END IF;

  v_old := v_agent.player_rakeback_rate;
  IF v_old IS DISTINCT FROM p_rate THEN
    UPDATE public.agents
       SET player_rakeback_rate = p_rate, updated_at = now()
     WHERE id = v_agent.id;

    INSERT INTO public.audit_trail (actor_id, actor_role, action, target_type, target_id,
                                    club_id, before_state, after_state, reason)
    VALUES (v_caller, v_role, 'set_player_rakeback', 'agent', v_caller, p_club_id,
            jsonb_build_object('player_rakeback_rate', v_old),
            jsonb_build_object('player_rakeback_rate', p_rate),
            'Agent set the rakeback their players receive');
  END IF;

  RETURN jsonb_build_object('success', true, 'club_id', p_club_id,
    'player_rakeback_rate', p_rate, 'max_rate', v_agent.commission_rate);
END;
$function$

public.fn_agent_wallet_send_core_2026083.def:
CREATE OR REPLACE FUNCTION public.fn_agent_wallet_send_core_20260830(p_club_id uuid, p_to_user_id uuid, p_amount numeric, p_destination text DEFAULT 'player_wallet'::text, p_reason text DEFAULT NULL::text, p_op_id uuid DEFAULT NULL::uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare
  v_context jsonb;
  v_setting text;
  v_actor        uuid := auth.uid();
  v_actor_role   text;
  v_dest         text := lower(coalesce(p_destination, 'player_wallet'));
  v_op_id        uuid := coalesce(p_op_id, gen_random_uuid());
  v_prior        record;
  v_agent_id     uuid;
  v_float_before numeric;
  v_float_after  numeric;
  v_is_prepaid   boolean;
  v_credit_limit numeric;
  v_credit_used  numeric;
  v_credit_after numeric;
  v_to_role      text;
  v_to_agent_id  uuid;
  v_to_after     numeric;
  v_tx_id        uuid;
  v_until        timestamptz;
begin
  -- Serialize the existing agreement before any operation/hierarchy/row lock.
  -- Nested callers reacquire the same transaction lock; no new money path.
  IF p_club_id IS NOT NULL THEN
    PERFORM pg_advisory_xact_lock(hashtextextended('agent-agreement:'||p_club_id::text,0));
  END IF;

  if v_actor is null then
    return jsonb_build_object('success', false, 'error', 'Not Authenticated');
  end if;

  select id, amount, metadata into v_prior
    from chip_transactions
   where club_id = p_club_id
     and transaction_type = 'agent_wallet_send'
     and from_user_id = v_actor
     and metadata ->> 'op_id' = v_op_id::text
   limit 1;
  if found then
    return jsonb_build_object(
      'success', true, 'replayed', true,
      'transaction_id', v_prior.id,
      'amount', v_prior.amount,
      'destination', v_prior.metadata ->> 'destination',
      'agent_wallet_after', (v_prior.metadata ->> 'agent_wallet_after')::numeric,
      'recipient_balance_after', (v_prior.metadata ->> 'recipient_balance_after')::numeric,
      'credit_drawn', coalesce((v_prior.metadata ->> 'credit_drawn')::numeric, 0),
      'credit_used_after', (v_prior.metadata ->> 'credit_used_after')::numeric,
      'credit_limit', (v_prior.metadata ->> 'credit_limit')::numeric);
  end if;

  v_actor_role := public.fn_club_bank_role(p_club_id);
  if v_actor_role is null
     or v_actor_role not in ('owner', 'co_owner', 'admin', 'super_agent', 'agent', 'sub_agent') then
    return jsonb_build_object('success', false,
      'error', 'Only Staff Or Agents Hold An Agent Wallet');
  end if;

  if p_amount is null or p_amount <= 0 then
    return jsonb_build_object('success', false, 'error', 'Amount Must Be Greater Than Zero');
  end if;
  if p_amount <> round(p_amount, 2) then
    return jsonb_build_object('success', false,
      'error', 'Chips Move In Hundredths At Most');
  end if;
  if p_amount > 1e9 then
    return jsonb_build_object('success', false, 'error', 'Amount Exceeds The Single Send Limit');
  end if;
  if v_dest not in ('player_wallet', 'agent_wallet', 'promo_wallet') then
    return jsonb_build_object('success', false, 'error', 'Unknown Destination Wallet');
  end if;
  if p_to_user_id is null then
    return jsonb_build_object('success', false, 'error', 'Choose A Recipient');
  end if;
  if p_to_user_id = v_actor and v_dest <> 'player_wallet' then
    return jsonb_build_object('success', false,
      'error', 'You Cannot Send Chips To Yourself');
  end if;

  if p_to_user_id <> v_actor and not public.fn_club_cashier_can_transact(p_club_id, v_actor, p_to_user_id) then
    return jsonb_build_object('success', false,
      'error', 'That Member Is Not In Your Downline');
  end if;

  select cm.role into v_to_role
    from club_members cm
   where cm.club_id = p_club_id
     and cm.user_id = p_to_user_id
     and coalesce(cm.status, 'active') in ('active', 'approved')
   for update;
  if v_to_role is null then
    return jsonb_build_object('success', false,
      'error', 'Recipient Is Not An Active Member Of This Club');
  end if;
  if v_dest in ('agent_wallet', 'promo_wallet')
     and v_to_role not in ('owner', 'co_owner', 'admin', 'super_agent', 'agent', 'sub_agent') then
    return jsonb_build_object('success', false,
      'error', 'Only Staff Or Agents Hold An Agent Wallet');
  end if;

  if v_dest = 'player_wallet' and v_to_role = 'admin' then
    return jsonb_build_object('success', false,
      'error', 'An Admin Does Not Hold A Player Wallet');
  end if;

  select a.id, coalesce(a.agent_wallet_balance, 0),
         coalesce(a.is_prepaid, true),
         coalesce(a.credit_limit, 0), coalesce(a.credit_used, 0)
    into v_agent_id, v_float_before, v_is_prepaid, v_credit_limit, v_credit_used
    from agents a
   where a.club_id = p_club_id and a.user_id = v_actor
   for update;
  if v_agent_id is null then
    return jsonb_build_object('success', false,
      'error', 'Your Agent Wallet Has Not Been Funded Yet');
  end if;

  -- The credit line records advances; it never funds a send.
  if v_float_before::text in ('NaN','Infinity','-Infinity') or v_float_before < 0 then
    raise exception 'Agent Wallet Balance Is Invalid' using errcode='23514';
  end if;
  if v_float_before < p_amount then
    return jsonb_build_object('success', false,
      'error', 'Your Agent Wallet Only Holds '
        || trim(to_char(v_float_before, 'FM999,999,999,990.00')) || ' Chips',
      'balance', v_float_before, 'requested', p_amount,
      'credit_tracking_only', true);
  end if;

  -- One funded agent_send transfers existing chips to the selected wallet.
  select jsonb_object_agg(k,coalesce(current_setting(k,true),'')) into v_context
   from unnest(array['app.ledger_category','app.ledger_counterparty','app.ledger_counterparty_entity','app.ledger_tournament','app.ledger_settlement','app.ledger_idempotency_key','app.ledger_correlation','app.ledger_autoskip_agents']) settings(k);
  perform set_config('app.ledger_tournament','',true);
  perform set_config('app.ledger_settlement','',true);
  perform public.fn_ca_declare_ledger('agent_send', 'agent_wallet', v_actor, null,
    'agent_send:' || v_op_id::text, array['agents']);
  perform set_config('app.ledger_correlation', v_op_id::text, true);
  update agents
     set agent_wallet_balance = coalesce(agent_wallet_balance, 0) - p_amount,
         updated_at = now()
   where id = v_agent_id
   returning agent_wallet_balance, credit_used into v_float_after, v_credit_after;

  if v_dest = 'player_wallet' then
    update club_members
       set chip_balance = coalesce(chip_balance, 0) + p_amount,
           updated_at = now()
     where club_id = p_club_id and user_id = p_to_user_id
     returning chip_balance into v_to_after;
  else
    v_to_agent_id := public.fn_ensure_agent_row(p_club_id, p_to_user_id, v_to_role);
    if v_to_agent_id is null then
      raise exception 'could not ensure agents row for % in club %', p_to_user_id, p_club_id;
    end if;
    if v_dest = 'promo_wallet' then
      update agents set promo_wallet_balance = coalesce(promo_wallet_balance, 0) + p_amount, updated_at = now()
       where id = v_to_agent_id returning promo_wallet_balance into v_to_after;
    else
      update agents set agent_wallet_balance = coalesce(agent_wallet_balance, 0) + p_amount, updated_at = now()
       where id = v_to_agent_id returning agent_wallet_balance into v_to_after;
    end if;
    perform set_config('app.ledger_idempotency_key', '', true);
    perform public.fn_ca_post_leg('agent_send', 'agent_wallet', v_actor, v_dest, p_to_user_id,
      p_amount, p_club_id, 'agent_send:' || v_op_id::text,
      'Agent wallet send to a downline agent wallet (fn_agent_wallet_send_core_20260830)');
  end if;

  for v_setting in select jsonb_object_keys(v_context) loop
    perform set_config(v_setting,v_context->>v_setting,true);
  end loop;

  v_until := now() + interval '10 minutes';

  insert into chip_transactions
    (club_id, from_user_id, to_user_id, amount, transaction_type, notes, metadata,
     balance_after, reversible_until)
  values
    (p_club_id, v_actor, p_to_user_id, p_amount, 'agent_wallet_send',
     coalesce(nullif(btrim(p_reason), ''), 'Agent Wallet Send'),
     jsonb_build_object(
       'op_id', v_op_id,
       'destination', v_dest,
       'actor_role', v_actor_role,
       'recipient_role', v_to_role,
       'agent_wallet_before', v_float_before,
       'agent_wallet_after', v_float_after,
       'recipient_balance_after', v_to_after,
       'claimed_back', 0,
       -- What was borrowed to make this send, and how much of that borrowing
       -- has since been handed back. The claim back reads both.
       'credit_drawn', 0,
       'credit_repaid', 0,
       'credit_used_after', v_credit_after,
       'credit_limit', v_credit_limit,
       'clawback_window_minutes', 10),
     v_float_after, v_until)
  returning id into v_tx_id;

  return jsonb_build_object(
    'success', true, 'replayed', false,
    'transaction_id', v_tx_id,
    'op_id', v_op_id,
    'amount', p_amount,
    'destination', v_dest,
    'agent_wallet_before', v_float_before,
    'agent_wallet_after', v_float_after,
    'recipient_balance_after', v_to_after,
    'credit_drawn', 0,
    'credit_used_after', v_credit_after,
    'credit_limit', v_credit_limit,
    'reversible_until', v_until);
exception
  when unique_violation then
    select id, amount, metadata into v_prior
      from chip_transactions
     where club_id = p_club_id
       and transaction_type = 'agent_wallet_send'
       and from_user_id = v_actor
       and metadata ->> 'op_id' = v_op_id::text
     limit 1;
    if v_prior.id is null then
      raise;
    end if;
    return jsonb_build_object(
      'success', true, 'replayed', true,
      'transaction_id', v_prior.id,
      'amount', v_prior.amount,
      'destination', v_prior.metadata ->> 'destination',
      'agent_wallet_after', (v_prior.metadata ->> 'agent_wallet_after')::numeric,
      'recipient_balance_after', (v_prior.metadata ->> 'recipient_balance_after')::numeric,
      'credit_drawn', coalesce((v_prior.metadata ->> 'credit_drawn')::numeric, 0),
      'credit_used_after', (v_prior.metadata ->> 'credit_used_after')::numeric,
      'credit_limit', (v_prior.metadata ->> 'credit_limit')::numeric);
end
$function$

public.fn_agents_staff_earn_no_rakeback(.def:
CREATE OR REPLACE FUNCTION public.fn_agents_staff_earn_no_rakeback()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'public'
AS $function$
BEGIN
  IF EXISTS (
    SELECT 1 FROM public.club_members cm
     WHERE cm.club_id = NEW.club_id AND cm.user_id = NEW.user_id
       AND cm.role IN ('co_owner', 'admin')
  ) THEN
    -- The row survives: it is also the agent wallet. Only the rate goes to zero.
    NEW.commission_rate      := 0;
    NEW.player_rakeback_rate := 0;
  END IF;
  RETURN NEW;
END;
$function$

public.fn_apply_union_ladder(p_union_id.def:
CREATE OR REPLACE FUNCTION public.fn_apply_union_ladder(p_union_id uuid)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_members bigint;
  v_level   smallint;
  v_clubs integer; v_admins integer; v_supers integer; v_agents integer;
  v_units numeric; v_units_up integer; v_hlevel integer; v_cursor integer;
BEGIN
  IF p_union_id IS NULL THEN RETURN; END IF;
  IF NOT EXISTS (SELECT 1 FROM public.unions WHERE id = p_union_id) THEN RETURN; END IF;

  SELECT member_count INTO v_members
    FROM public.fn_batch_union_realtime_member_counts(ARRAY[p_union_id]);
  v_members := COALESCE(v_members, 0);
  v_level := public.fn_club_level_for_members(v_members::integer);

  SELECT count(DISTINCT uc.club_id),
         COALESCE(sum(c.admin_count), 0),
         COALESCE(sum(c.super_agent_count), 0),
         COALESCE(sum(c.agent_count), 0)
    INTO v_clubs, v_admins, v_supers, v_agents
    FROM public.union_clubs uc
    JOIN public.clubs c ON c.id = uc.club_id
   WHERE uc.union_id = p_union_id;
  v_units := (v_admins * 1.00) + (v_supers * 1.00) + (v_agents * 0.25);
  v_units_up := CEIL(v_units);
  v_hlevel := 1;
  FOR v_cursor IN 1..50 LOOP
    IF v_units_up >= ROUND(2 * POWER(1.086, v_cursor - 1)) THEN v_hlevel := v_cursor; ELSE EXIT; END IF;
  END LOOP;

  UPDATE public.unions SET
    member_count               = v_members,
    total_players              = v_members,
    club_count                 = v_clubs,
    level                      = v_level,
    player_level               = v_level,
    player_threshold_current   = public.fn_club_level_min_members(v_level),
    player_threshold_next      = public.fn_club_level_min_members(v_level + 1),
    total_admins               = v_admins,
    total_super_agents         = v_supers,
    total_agents               = v_agents,
    hierarchy_units            = v_units,
    hierarchy_units_rounded_up = v_units_up,
    hierarchy_level            = v_hlevel,
    hierarchy_threshold_current = ROUND(2 * POWER(1.086, v_hlevel - 1)),
    hierarchy_threshold_next    = ROUND(2 * POWER(1.086, LEAST(v_hlevel, 49))),
    updated_at                 = now()
  WHERE id = p_union_id;
END;
$function$

public.fn_audit_club_entry_mutation().def:
CREATE OR REPLACE FUNCTION public.fn_audit_club_entry_mutation()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE v_action text; v_club uuid; v_target uuid; v_actor uuid; v_details jsonb;
BEGIN
  IF TG_TABLE_NAME='clubs' THEN
    v_action:='club_created'; v_club:=NEW.id; v_target:=NEW.id;
    v_actor:=COALESCE(auth.uid(),NEW.owner_id);
    v_details:=jsonb_build_object('club_code',NEW.club_id,'requires_approval',NEW.requires_approval);
  ELSIF TG_TABLE_NAME='club_members' THEN
    v_club:=NEW.club_id; v_target:=NEW.user_id;
    v_actor:=COALESCE(auth.uid(),NEW.user_id);
    v_action:=CASE WHEN TG_OP='INSERT' AND current_setting('app.club_membership_source',true)='historical_rakeback_wallet'
      AND NEW.membership_lifecycle_status='departed' AND NEW.status='suspended' AND NEW.is_active=false
      THEN 'historical_rakeback_wallet_preserved'
      WHEN TG_OP='INSERT' THEN 'club_join_'||NEW.status ELSE 'club_join_status_changed' END;
    v_details:=jsonb_build_object('status',NEW.status,'previous_status',CASE WHEN TG_OP='UPDATE' THEN OLD.status ELSE NULL END);
  ELSE
    v_action:='player_search_privacy_changed'; v_target:=NEW.user_id;
    v_actor:=COALESCE(auth.uid(),NEW.user_id);
    v_details:=jsonb_build_object('discoverable',NEW.discoverable,'show_presence',NEW.show_presence,'show_current_table',NEW.show_current_table);
  END IF;
  INSERT INTO public.audit_trail(
    club_id,actor_id,actor_role,action,target_type,target_id,after_state
  ) VALUES(
    v_club,v_actor,'system',v_action,TG_TABLE_NAME,v_target,jsonb_strip_nulls(v_details)
  );
  RETURN NEW;
END $function$

public.fn_audit_club_member_change().def:
CREATE OR REPLACE FUNCTION public.fn_audit_club_member_change()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE
  v_actor  uuid := auth.uid();
  v_action text;
  v_before jsonb;
  v_after  jsonb;
  v_club   uuid;
  v_target uuid;
BEGIN
  IF v_actor IS NULL THEN
    RETURN COALESCE(NEW, OLD);
  END IF;

  IF TG_OP = 'DELETE' THEN
    v_club   := OLD.club_id;
    v_target := OLD.user_id;
    v_action := CASE WHEN v_actor = OLD.user_id THEN 'member_left'
                     ELSE 'kick_member' END;
    v_before := jsonb_build_object('role', OLD.role, 'status', OLD.status);
    v_after  := NULL;
  ELSE
    v_club   := NEW.club_id;
    v_target := NEW.user_id;
    IF NEW.role IS DISTINCT FROM OLD.role THEN
      v_action := 'role_change';
      v_before := jsonb_build_object('role', OLD.role);
      v_after  := jsonb_build_object('role', NEW.role);
    ELSIF NEW.status IS DISTINCT FROM OLD.status THEN
      v_action := CASE
        WHEN NEW.status = 'banned' THEN 'banned'
        WHEN OLD.status = 'banned' THEN 'unban_member'
        ELSE 'member_status_change' END;
      v_before := jsonb_build_object('status', OLD.status);
      v_after  := jsonb_build_object('status', NEW.status);
    ELSE
      RETURN NEW;
    END IF;
  END IF;

  BEGIN
    INSERT INTO public.audit_trail
      (actor_id, actor_role, action, target_type, target_id, club_id,
       before_state, after_state)
    VALUES
      (v_actor, public.fn_audit_actor_role(v_club, v_actor),
       v_action, 'member', v_target, v_club, v_before, v_after);
  EXCEPTION WHEN OTHERS THEN
    RAISE WARNING 'audit_trail insert failed for club % member %: %',
      v_club, v_target, SQLERRM;
  END;

  RETURN COALESCE(NEW, OLD);
END;
$function$

public.fn_audit_club_settings_change().def:
CREATE OR REPLACE FUNCTION public.fn_audit_club_settings_change()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_actor   uuid := auth.uid();
  v_before  jsonb := '{}'::jsonb;
  v_after   jsonb := '{}'::jsonb;
  v_old     jsonb;
  v_new     jsonb;
  v_key     text;
  -- `settings`, `tagline` and `lobby_message` are new here. The rules a member
  -- is held to live inside `settings`, and a rewrite used to leave no trace at
  -- all: no row, no actor, no before.
  v_watched text[] := ARRAY[
    'name','description','is_public','requires_approval',
    'default_rake_percent','rake_cap',
    'allow_straddle','allow_run_it_twice','allow_rabbit_hunt',
    'min_buyin_bb','max_buyin_bb','logo_url',
    'bbj_rake_enabled','spins_enabled','spins_preseed_amount','spins_wallet_funding',
    'settings','tagline','lobby_message'];
BEGIN
  IF v_actor IS NULL THEN
    RETURN NEW;
  END IF;

  v_old := to_jsonb(OLD);
  v_new := to_jsonb(NEW);
  FOREACH v_key IN ARRAY v_watched LOOP
    IF (v_old -> v_key) IS DISTINCT FROM (v_new -> v_key) THEN
      v_before := v_before || jsonb_build_object(v_key, v_old -> v_key);
      v_after  := v_after  || jsonb_build_object(v_key, v_new -> v_key);
    END IF;
  END LOOP;

  IF v_after = '{}'::jsonb THEN
    RETURN NEW;
  END IF;

  -- The same target and the same swallow the original used. An audit row must
  -- never be the reason a club cannot be saved, and this migration is here to
  -- widen what is watched, not to change where it is written.
  BEGIN
    INSERT INTO public.audit_trail
      (actor_id, actor_role, action, target_type, target_id, club_id,
       before_state, after_state)
    VALUES
      (v_actor, public.fn_audit_actor_role(NEW.id, v_actor), 'update_club_settings',
       'club', NEW.id, NEW.id, v_before, v_after);
  EXCEPTION WHEN OTHERS THEN
    NULL;
  END;

  RETURN NEW;
END;
$function$

public.fn_bank_standalone_week_rake(p_cl.def:
CREATE OR REPLACE FUNCTION public.fn_bank_standalone_week_rake(p_club_id uuid, p_period_start timestamp with time zone, p_period_end timestamp with time zone)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_name text;
  v_cash numeric;
  v_fees numeric;
  v_total numeric;
  v_key text;
  v_res jsonb;
  v_cat text := COALESCE(current_setting('app.ledger_category', true), '');
  v_cp text := COALESCE(current_setting('app.ledger_counterparty', true), '');
  v_cpe text := COALESCE(current_setting('app.ledger_counterparty_entity', true), '');
  v_idem text := COALESCE(current_setting('app.ledger_idempotency_key', true), '');
BEGIN
  IF NOT public.fn_caller_is_engine() THEN
    RAISE EXCEPTION 'not_authorised' USING ERRCODE = '42501';
  END IF;
  IF p_club_id IS NULL OR p_period_start IS NULL OR p_period_end IS NULL
     OR p_period_start <> public.fn_union_week_start(p_period_start)
     OR p_period_end <> public.fn_union_week_start(p_period_start + interval '8 days')
     OR p_period_end > public.fn_union_week_start(clock_timestamp()) THEN
    RAISE EXCEPTION 'standalone_rake_bank_invalid_week' USING ERRCODE = '22023';
  END IF;
  SELECT c.name INTO v_name FROM public.clubs c
   WHERE c.id = p_club_id AND c.is_union IS NOT TRUE;
  IF NOT FOUND THEN
    RAISE EXCEPTION 'standalone_rake_bank_unknown_club' USING ERRCODE = '22023';
  END IF;

  -- Cash: the standalone bank receipt every retired cash rake leg carries.
  SELECT COALESCE(sum(b.amount), 0) INTO v_cash
    FROM public.accounting_cash_bank_receipts b
   WHERE b.union_id IS NULL AND b.club_id = p_club_id
     AND b.club_ledger_id IS NOT NULL
     AND b.banked_at >= p_period_start AND b.banked_at < p_period_end;
  -- Tournament fees: the settlement row of every standalone fee retirement.
  SELECT COALESCE(sum(s.amount), 0) INTO v_fees
    FROM public.tournament_rake_settlements s
   WHERE s.destination = 'chip_retirement:' || p_club_id::text
     AND s.settled_at >= p_period_start AND s.settled_at < p_period_end;
  v_total := v_cash + v_fees;
  IF v_total <= 0 THEN
    RETURN jsonb_build_object('ok', true, 'amount', 0, 'club_id', p_club_id,
      'period_start', p_period_start, 'period_end', p_period_end);
  END IF;

  v_key := 'standalone-rake-bank:' || p_club_id::text || ':'
    || to_char(p_period_start AT TIME ZONE 'UTC', 'YYYY-MM-DD"T"HH24:MI:SS"Z"') || '..'
    || to_char(p_period_end AT TIME ZONE 'UTC', 'YYYY-MM-DD"T"HH24:MI:SS"Z"');
  IF NOT EXISTS(SELECT FROM smarter_private.weekly_payout_financial_receipts r WHERE r.scope_kind='club' AND r.scope_id=p_club_id
   AND r.period_start=p_period_start AND r.period_end=p_period_end) THEN
   PERFORM smarter_private.weekly_payout_require_round('club',p_club_id,p_period_start,p_period_end,1);
  END IF;
  v_res := public.fn_ca_fund_club(
    p_club_id, v_total,
    'Weekly bank of the standalone rake ' || COALESCE(v_name, p_club_id::text)
      || ' retired in the week ' || to_char(p_period_start AT TIME ZONE 'UTC', 'YYYY-MM-DD')
      || '..' || to_char(p_period_end AT TIME ZONE 'UTC', 'YYYY-MM-DD')
      || ' (cash ' || v_cash::text || ', tournament fees ' || v_fees::text
      || '); standalone rake belongs to the club treasury (CLUB-MONEY-LEDGERS-CANONICAL)',
    v_key);
  PERFORM set_config('app.ledger_category', v_cat, true);
  PERFORM set_config('app.ledger_counterparty', v_cp, true);
  PERFORM set_config('app.ledger_counterparty_entity', v_cpe, true);
  PERFORM set_config('app.ledger_idempotency_key', v_idem, true);
  IF v_res->>'ok' IS DISTINCT FROM 'true' THEN
    RAISE EXCEPTION 'standalone_rake_bank_refused' USING DETAIL = v_res::text;
  END IF;
  RETURN v_res || jsonb_build_object('cash_rake', v_cash, 'tournament_fees', v_fees,
    'period_start', p_period_start, 'period_end', p_period_end);
END;
$function$

public.fn_block_browser_balance_writes().def:
CREATE OR REPLACE FUNCTION public.fn_block_browser_balance_writes()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare
  v_changed text;
begin
  if current_user not in ('authenticated', 'anon') then
    return new;
  end if;

  if tg_table_name = 'club_members' then
    if new.chip_balance is distinct from old.chip_balance then
      v_changed := 'chip_balance';
    elsif new.held_chips is distinct from old.held_chips then
      v_changed := 'held_chips';
    elsif new.locked_chips is distinct from old.locked_chips then
      v_changed := 'locked_chips';
    elsif new.promo_balance is distinct from old.promo_balance then
      v_changed := 'promo_balance';
    end if;
  elsif tg_table_name = 'clubs' then
    if new.chip_treasury is distinct from old.chip_treasury then
      v_changed := 'chip_treasury';
    elsif new.chip_pool is distinct from old.chip_pool then
      v_changed := 'chip_pool';
    end if;
  end if;

  if v_changed is null then
    return new;
  end if;

  raise exception
    'Direct balance mutation of %.% from the browser is forbidden. Chips move only through the money RPCs.',
    tg_table_name, v_changed
    using errcode = 'insufficient_privilege';
end
$function$

public.fn_ca_assert_player_action(p_user.def:
CREATE OR REPLACE FUNCTION public.fn_ca_assert_player_action(p_user_id uuid, p_scope text, p_source text)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public', 'pg_temp'
AS $function$
DECLARE v_enforced boolean; v_restriction public.ca_player_restrictions;
BEGIN
  IF p_user_id IS NULL THEN RETURN; END IF;
  IF p_scope NOT IN ('account','cash','tournaments','transfers','social') THEN
    RAISE EXCEPTION 'unknown_player_restriction_scope' USING ERRCODE='22023';
  END IF;
  PERFORM pg_advisory_xact_lock(hashtextextended(p_user_id::text,731));
  SELECT restrictions_enforced INTO v_enforced FROM public.ca_operator_policy WHERE id=true FOR SHARE;
  SELECT * INTO v_restriction FROM public.ca_player_restrictions
    WHERE user_id=p_user_id AND status='active'
      AND (expires_at IS NULL OR expires_at > statement_timestamp())
      AND scope IN ('account',p_scope) ORDER BY applied_at,id LIMIT 1;
  IF NOT FOUND THEN RETURN; END IF;
  IF v_enforced IS TRUE THEN
    RAISE EXCEPTION 'PLAYER_RESTRICTED: %',p_scope USING ERRCODE='42501';
  END IF;
  INSERT INTO public.ca_restriction_observations
    (user_id,scope,restriction_id,table_name,op,would_refuse,detail)
    VALUES(p_user_id,p_scope,v_restriction.id,p_source,'ACTION',true,
      jsonb_build_object('reason_code',v_restriction.reason_code,'restriction_scope',v_restriction.scope));
EXCEPTION WHEN insufficient_privilege THEN RAISE;
  WHEN OTHERS THEN
    -- Preserve PHASE4-CONTRACTS section 0: restriction lookup failures fail open.
    -- Session authentication and financial stops have separate fail-closed owners.
    RETURN;
END $function$

public.fn_ca_attested_day_is_restated().def:
CREATE OR REPLACE FUNCTION public.fn_ca_attested_day_is_restated()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
 SET "TimeZone" TO 'UTC'
AS $function$
DECLARE
  v_reason text := NULLIF(current_setting('app.ledger_maintenance', true), '');
  r record;
  v_res jsonb;
BEGIN
  IF v_reason IS NULL THEN
    RETURN NULL;
  END IF;

  IF TG_OP = 'DELETE' THEN
    FOR r IN
      SELECT DISTINCT o.created_at::date AS day
        FROM old_rows o
        JOIN public.ca_ledger_day_manifests m ON m.day = o.created_at::date
       ORDER BY 1
    LOOP
      v_res := public.fn_ca_ledger_day_manifest(r.day, 'maintenance:' || v_reason);
      IF COALESCE((v_res->>'tampered')::boolean, false) THEN
        RAISE EXCEPTION 'the manifest for % could not be restated after maintenance "%": %', r.day, v_reason, v_res
          USING ERRCODE = 'P0403';
      END IF;
    END LOOP;
  ELSE
    FOR r IN
      SELECT DISTINCT d.day
        FROM (SELECT created_at::date AS day FROM old_rows
              UNION
              SELECT created_at::date FROM new_rows) d
        JOIN public.ca_ledger_day_manifests m ON m.day = d.day
       ORDER BY 1
    LOOP
      v_res := public.fn_ca_ledger_day_manifest(r.day, 'maintenance:' || v_reason);
      IF COALESCE((v_res->>'tampered')::boolean, false) THEN
        RAISE EXCEPTION 'the manifest for % could not be restated after maintenance "%": %', r.day, v_reason, v_res
          USING ERRCODE = 'P0403';
      END IF;
    END LOOP;
  END IF;

  RETURN NULL;
END $function$

public.fn_ca_autoledger().def:
CREATE OR REPLACE FUNCTION public.fn_ca_autoledger()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  spec text; col text; acct text;
  o jsonb; nn jsonb;
  d numeric; oldv numeric; newv numeric;
  cat text; cp text; cpid uuid; cplbl text;
  v_club uuid; v_union uuid; v_entity uuid; v_guc_club uuid;
  actor uuid;
  v_st text; v_msg text;
BEGIN
  IF current_setting('app.ledger_autoskip_' || TG_TABLE_NAME, true) = '1' THEN
    RETURN NEW;
  END IF;

  o  := CASE WHEN TG_OP = 'INSERT' THEN '{}'::jsonb ELSE to_jsonb(OLD) END;
  nn := to_jsonb(NEW);

  cat := COALESCE(NULLIF(current_setting('app.ledger_category', true), ''), 'adjustment');
  cp  := COALESCE(NULLIF(current_setting('app.ledger_counterparty', true), ''), 'settlement_suspense');
  BEGIN
    cpid := NULLIF(current_setting('app.ledger_counterparty_entity', true), '')::uuid;
  EXCEPTION WHEN OTHERS THEN cpid := NULL;
  END;
  /* THE COUNTERPARTY NAMES ITS COLUMN (2026-10-04). A union wallet holds six
     balances and a promo bank lives on three kinds of owner, so the side this
     trigger writes for a declared union_wallet or promo_wallet counterparty
     carries the column the caller declared on app.ledger_counterparty_label.
     A label that cannot belong to the declared counterparty is not written:
     a stale declaration never names the wrong account. */
  cplbl := NULLIF(current_setting('app.ledger_counterparty_label', true), '');
  cplbl := CASE
    WHEN cp = 'union_wallet' AND cplbl LIKE 'union_wallets.%' THEN cplbl
    WHEN cp = 'bbj_pool' AND cplbl = 'bbj_pools.main_balance' THEN cplbl
    WHEN cp = 'promo_wallet' AND cplbl IN ('clubs.promo_balance', 'agents.promo_wallet_balance',
                                           'union_wallets.promo_wallet') THEN cplbl
    ELSE NULL END;
  actor := COALESCE(auth.uid(), '2d1cd6c3-5700-4af9-a271-d4863fdab20d'::uuid);

  /* THE JOURNAL LEG NAMES THE CLUB THE MONEY LANDED IN (2026-09-20).
     union_wallets and unions are the only autoledgered tables with no
     club_id column - `nn ? 'club_id'` is key EXISTENCE, so a table
     that has the column takes the arm above even when it is NULL. Before
     today every leg journalled from those two was written club-less, and
     fn_chip_drift_since_baseline filters movements on club_id IS NOT
     NULL while counting the balance they explain, so correctly paid
     union-hosted prizes were reported as member drift.
     A payer that knows the club declares it on
     app.ledger_autoledger_club_id, transaction-scoped, and clears it
     beside the autoskips. It is deliberately NOT app.ledger_club_id:
     that name is taken and decides which club a WALLET credit is paid
     into (atomic_credit_wallet_and_log, atomic_deduct_wallet_and_log,
     log_wallet_transaction), so borrowing it would let a rakeback
     close's club leak onto a union leg and would move real money when
     cleared. Read through an exception guard exactly as cpid is above:
     a malformed value must never abort a chip movement. */
  BEGIN
    v_guc_club := NULLIF(current_setting('app.ledger_autoledger_club_id', true), '')::uuid;
  EXCEPTION WHEN OTHERS THEN v_guc_club := NULL;
  END;
  v_club := CASE
    WHEN TG_TABLE_NAME = 'clubs' THEN (nn->>'id')::uuid
    WHEN nn ? 'club_id' THEN NULLIF(nn->>'club_id','')::uuid
    ELSE v_guc_club END;
  v_union := CASE
    WHEN TG_TABLE_NAME = 'unions' THEN (nn->>'id')::uuid
    WHEN nn ? 'union_id' THEN NULLIF(nn->>'union_id','')::uuid
    ELSE NULL END;
  v_entity := CASE
    WHEN TG_TABLE_NAME = 'agents' THEN NULLIF(nn->>'user_id','')::uuid
    WHEN TG_TABLE_NAME = 'club_members' THEN NULLIF(nn->>'user_id','')::uuid
    ELSE COALESCE(NULLIF(nn->>'id','')::uuid, v_club, v_union) END;

  FOR i IN 0 .. TG_NARGS - 1 LOOP
    spec := TG_ARGV[i];
    col  := split_part(spec, '=', 1);
    acct := split_part(spec, '=', 2);
    oldv := COALESCE(NULLIF(o->>col,'')::numeric, 0);
    newv := COALESCE(NULLIF(nn->>col,'')::numeric, 0);
    d := round(newv - oldv, 2);
    CONTINUE WHEN d = 0;
    /* THE AUTOLEDGER NEVER JOURNALS AN ACCOUNT TO ITSELF (2026-10-15). A leg
       whose counterparty is this very account, unlabelled, is from and to the
       same account (2026-10-06 15:42 KF player to three club treasuries;
       2026-09-17 16:39/16:41 treasury to promo). It nets to zero in every
       tally, so it is not written. A bbj_pool, a union_wallet and a promo bank
       off a club hold more than one column under one key, and their bare
       self-legs are the only record of which column moved: kept. */
    CONTINUE WHEN cp = acct AND cpid IS NOT DISTINCT FROM v_entity AND cplbl IS NULL
              AND acct NOT IN ('bbj_pool', 'union_wallet')
              AND (acct <> 'promo_wallet' OR TG_TABLE_NAME = 'clubs');

    BEGIN
      INSERT INTO public.chip_ledger
        (performed_by, from_type, from_entity_id, from_label,
         to_type, to_entity_id, to_label,
         amount, category, club_id, union_id, description,
         pre_from_balance, post_from_balance, pre_to_balance, post_to_balance)
      VALUES (actor,
        CASE WHEN d > 0 THEN cp   ELSE acct END,
        CASE WHEN d > 0 THEN cpid ELSE v_entity END,
        CASE WHEN d > 0 THEN cplbl ELSE TG_TABLE_NAME || '.' || col END,
        CASE WHEN d > 0 THEN acct ELSE cp END,
        CASE WHEN d > 0 THEN v_entity ELSE cpid END,
        CASE WHEN d > 0 THEN TG_TABLE_NAME || '.' || col ELSE cplbl END,
        abs(d), cat, v_club, v_union,
        'auto-ledgered ' || TG_TABLE_NAME || '.' || col || ' delta ' || d::text,
        CASE WHEN d < 0 THEN oldv END, CASE WHEN d < 0 THEN newv END,
        CASE WHEN d > 0 THEN oldv END, CASE WHEN d > 0 THEN newv END);
    EXCEPTION WHEN OTHERS THEN
      -- A journal failure must abort the enclosing chip movement.
      -- Preserve SQLSTATE so the existing caller can retry the whole operation.
      RAISE;
    END;
  END LOOP;

  RETURN NEW;
END $function$

public.fn_ca_autoledger_delete().def:
CREATE OR REPLACE FUNCTION public.fn_ca_autoledger_delete()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  spec text; col text; acct text;
  o jsonb; oldv numeric;
  v_club uuid; v_union uuid; v_entity uuid; actor uuid;
  v_st text; v_msg text;
BEGIN
  IF current_setting('app.ledger_autoskip_' || TG_TABLE_NAME, true) = '1' THEN
    RETURN OLD;
  END IF;

  o := to_jsonb(OLD);
  actor := COALESCE(auth.uid(), '2d1cd6c3-5700-4af9-a271-d4863fdab20d'::uuid);
  v_club := CASE
    WHEN TG_TABLE_NAME = 'clubs' THEN (o->>'id')::uuid
    WHEN o ? 'club_id' THEN NULLIF(o->>'club_id','')::uuid
    ELSE NULL END;
  v_union := CASE
    WHEN TG_TABLE_NAME = 'unions' THEN (o->>'id')::uuid
    WHEN o ? 'union_id' THEN NULLIF(o->>'union_id','')::uuid
    ELSE NULL END;
  v_entity := CASE
    WHEN TG_TABLE_NAME IN ('agents','club_members') THEN NULLIF(o->>'user_id','')::uuid
    ELSE COALESCE(NULLIF(o->>'id','')::uuid, v_club, v_union) END;

  FOR i IN 0 .. TG_NARGS - 1 LOOP
    spec := TG_ARGV[i];
    col  := split_part(spec, '=', 1);
    acct := split_part(spec, '=', 2);
    oldv := round(COALESCE(NULLIF(o->>col,'')::numeric, 0), 2);
    CONTINUE WHEN oldv = 0;

    BEGIN
      INSERT INTO public.chip_ledger
        (performed_by, from_type, from_entity_id, from_label,
         to_type, to_entity_id, to_label,
         amount, category, club_id, union_id, description,
         pre_from_balance, post_from_balance)
      VALUES (actor,
        acct, v_entity, TG_TABLE_NAME || '.' || col,
        'chip_retirement', NULL, NULL,
        abs(oldv), CASE WHEN oldv > 0 THEN 'burn' ELSE 'correction' END,
        v_club, v_union,
        'auto-ledgered ' || TG_TABLE_NAME || '.' || col || ' balance ' || oldv::text
          || ' retired on row delete',
        oldv, 0);
    EXCEPTION WHEN OTHERS THEN
      -- A journal failure must abort the enclosing chip movement.
      -- Preserve SQLSTATE so the existing caller can retry the whole operation.
      RAISE;
    END;
  END LOOP;

  RETURN OLD;
END $function$

public.fn_ca_balance_has_its_ledger_row(.def:
CREATE OR REPLACE FUNCTION public.fn_ca_balance_has_its_ledger_row()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
AS $function$
DECLARE
  v_ver text := NULLIF(current_setting('ca.ledger_tally_ver', true), '');
  v_checked text := NULLIF(current_setting('ca.ledger_tally_checked', true), '');
  v_mode text;
  t jsonb;
  r record;
  v_b numeric; v_l numeric;
  v_s numeric; v_moved text; v_moved_abs numeric;
BEGIN
  /* Deferred to commit. Every queued event re-enters here, so the tally is
     verified once per version: when nothing has been added since the last
     verification this is one setting read and out. A deferred trigger that
     writes money after us bumps the version and queues its own event, which
     verifies again, so the last word is always on the complete tally. */
  IF v_ver IS NULL OR v_ver = v_checked THEN
    RETURN NULL;
  END IF;

  t := COALESCE(NULLIF(current_setting('ca.ledger_tally', true), '')::jsonb, '{}'::jsonb);

  FOR r IN SELECT key, value FROM jsonb_each(t) LOOP
    v_b := round(COALESCE((r.value ->> 'b')::numeric, 0), 2);
    v_l := round(COALESCE((r.value ->> 'l')::numeric, 0), 2);
    IF v_b = v_l THEN
      CONTINUE;
    END IF;

    /* 2026-10-02: each store is judged by its own mode
       (ca_ledger_invariant_store_mode, keyed by the account-key prefix), so a
       store still being measured records a finding while a proven store
       refuses. A store with no row falls back to the one global row. */
    v_mode := COALESCE(
      (SELECT sm.mode FROM public.ca_ledger_invariant_store_mode sm WHERE sm.store = split_part(r.key, ':', 1)),
      (SELECT m.mode FROM public.ca_ledger_invariant_mode m LIMIT 1),
      'refuse');

    IF v_mode = 'refuse' THEN
      /* 20261002135708: the refusal rolls this transaction back, so it is
         recorded first on the recorder's own connection, which commits on
         its own. The recorder never raises and never changes the refusal. */
      BEGIN
        PERFORM public.fn_ca_ledger_refusal_record(jsonb_build_object(
          'kind',          'balance_moved_without_its_ledger_row',
          'account_key',   r.key,
          'store',         split_part(r.key, ':', 1),
          'balance_delta', v_b,
          'ledger_net',    v_l,
          'mode',          v_mode,
          'first_writer',  left(COALESCE(r.value ->> 'q', '(unknown statement)'), 1000),
          'message',       format('REFUSED: balance_moved_without_its_ledger_row account=%s balance_delta=%s ledger_net=%s', r.key, v_b, v_l)));
      EXCEPTION WHEN OTHERS THEN
        NULL;
      END;
      RAISE EXCEPTION 'REFUSED: balance_moved_without_its_ledger_row account=% balance_delta=% ledger_net=%',
        r.key, v_b, v_l
        USING ERRCODE = '23514',
              DETAIL  = CASE
                          WHEN v_l = 0 THEN 'the balance column moved and no chip_ledger leg in this transaction accounts for it'
                          WHEN v_b = 0 THEN 'a chip_ledger leg names this account and its balance column did not move in this transaction'
                          ELSE 'the balance column and the chip_ledger legs in this transaction disagree on how much moved'
                        END || '; first written in this transaction by: ' || COALESCE(r.value ->> 'q', '(unknown statement)'),
              HINT    = 'Every chip movement is written by its door as balance + leg in one transaction. If the door stood the autoledger down (app.ledger_autoskip_<table>), its own leg must equal the delta and name the same user, club, union, pool, table, tournament or ticket float. Nothing is corrected here; the transaction is refused whole.';
    END IF;

    INSERT INTO public.ca_ledger_invariant_findings
      (txid, account_key, balance_delta, ledger_net, mode, actor_service, db_role, statement)
    VALUES
      (pg_current_xact_id(), r.key, v_b, v_l, v_mode,
       current_setting('application_name', true), current_user,
       COALESCE(r.value ->> 'q', left(current_query(), 300)))
    ON CONFLICT (txid, account_key) DO UPDATE
      SET balance_delta = EXCLUDED.balance_delta,
          ledger_net    = EXCLUDED.ledger_net,
          found_at      = EXCLUDED.found_at,
          statement     = EXCLUDED.statement;
    RAISE WARNING 'OBSERVED: balance_moved_without_its_ledger_row account=% balance_delta=% ledger_net=% (store mode observe; this transaction would be refused)',
      r.key, v_b, v_l;
  END LOOP;

  /* NO BALANCE MOVES AGAINST SETTLEMENT SUSPENSE (2026-10-02). Every store
     above can balance and the chips still come from nowhere: a journal
     trigger whose writer declared no counterparty posts the store's leg
     against settlement_suspense, which holds no balance and is outside the
     supply count. A transaction that wrote a suspense leg may not move any
     covered balance. A journal-only suspense correction moves none. */
  v_s := round(COALESCE((t -> 'settlement_suspense' ->> 's')::numeric, 0), 2);
  IF v_s <> 0 THEN
    SELECT string_agg(e.key || ' ' || round((e.value ->> 'b')::numeric, 2)::text, ', ' ORDER BY e.key),
           sum(abs(round((e.value ->> 'b')::numeric, 2)))
      INTO v_moved, v_moved_abs
      FROM jsonb_each(t) e
     WHERE e.key <> 'settlement_suspense'
       AND round(COALESCE((e.value ->> 'b')::numeric, 0), 2) <> 0;

    IF v_moved IS NOT NULL THEN
      v_mode := COALESCE(
        (SELECT sm.mode FROM public.ca_ledger_invariant_store_mode sm WHERE sm.store = 'settlement_suspense'),
        (SELECT m.mode FROM public.ca_ledger_invariant_mode m LIMIT 1),
        'refuse');

      IF v_mode = 'refuse' THEN
        /* 20261002135708: recorded first, outside the rollback. */
        BEGIN
          PERFORM public.fn_ca_ledger_refusal_record(jsonb_build_object(
            'kind',          'balance_moved_against_settlement_suspense',
            'account_key',   'settlement_suspense',
            'store',         'settlement_suspense',
            'balance_delta', v_moved_abs,
            'ledger_net',    v_s,
            'mode',          v_mode,
            'moved',         left(v_moved, 2000),
            'first_writer',  left(COALESCE(t -> 'settlement_suspense' ->> 'q', '(unknown statement)'), 1000),
            'message',       format('REFUSED: balance_moved_against_settlement_suspense suspense_legs=%s moved=%s', v_s, left(v_moved, 1500))));
        EXCEPTION WHEN OTHERS THEN
          NULL;
        END;
        RAISE EXCEPTION 'REFUSED: balance_moved_against_settlement_suspense suspense_legs=% moved=%',
          v_s, v_moved
          USING ERRCODE = '23514',
                DETAIL  = 'this transaction wrote a chip_ledger leg against settlement_suspense, which holds no balance and is outside the supply count, and moved a covered chip balance; the suspense leg was first written by: '
                          || COALESCE(t -> 'settlement_suspense' ->> 'q', '(unknown statement)'),
                HINT    = 'A door names where its chips come from and go to: app.ledger_counterparty (+ app.ledger_counterparty_entity) before the balance write, or app.ledger_autoskip_<table> and its own leg. An undeclared journal trigger falls to settlement_suspense, and that is what is refused here. A journal-only correction that moves no balance is not affected.';
      END IF;

      INSERT INTO public.ca_ledger_invariant_findings
        (txid, account_key, balance_delta, ledger_net, mode, actor_service, db_role, statement)
      VALUES
        (pg_current_xact_id(), 'settlement_suspense', v_moved_abs, v_s, v_mode,
         current_setting('application_name', true), current_user,
         left(COALESCE(t -> 'settlement_suspense' ->> 'q', left(current_query(), 300)) || ' | moved: ' || v_moved, 1000))
      ON CONFLICT (txid, account_key) DO UPDATE
        SET balance_delta = EXCLUDED.balance_delta,
            ledger_net    = EXCLUDED.ledger_net,
            found_at      = EXCLUDED.found_at,
            statement     = EXCLUDED.statement;
      RAISE WARNING 'OBSERVED: balance_moved_against_settlement_suspense suspense_legs=% moved=% (mode observe; this transaction would be refused)',
        v_s, v_moved;
    END IF;
  END IF;

  PERFORM set_config('ca.ledger_tally_checked', v_ver, true);
  RETURN NULL;
END;
$function$

public.fn_ca_capture_tournament_charge_e.def:
CREATE OR REPLACE FUNCTION public.fn_ca_capture_tournament_charge_entitlement()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_split record;
  v_original_entitlement uuid;
BEGIN
  IF NEW.tournament_id IS NULL
     OR NEW.from_type IS DISTINCT FROM 'player_wallet'
     OR NEW.to_type IS DISTINCT FROM 'prize_liability'
     OR NEW.to_entity_id IS DISTINCT FROM NEW.tournament_id
     OR lower(COALESCE(NEW.category,'')) NOT IN (
          'tournament_buyin','rebuy','addon') THEN
    RETURN NULL;
  END IF;
  PERFORM smarter_private.tournament_abort_ingress(NEW.tournament_id);
  IF NEW.from_entity_id IS NULL OR NEW.club_id IS NULL THEN
    RAISE EXCEPTION 'tournament charge ledger omitted player or source club'
      USING ERRCODE = 'P0404';
  END IF;
  SELECT * INTO v_split FROM public.fn_ca_tournament_charge_split(
    NEW.tournament_id,NEW.category,NEW.amount);
  INSERT INTO public.tournament_refund_entitlements(
    tournament_id,user_id,entitlement_kind,charge_category,
    refund_wallet_club_id,gross,refund_prize,refund_bounty,refund_fee,
    source_ledger_id,registration_id,source_satellite_id,source_award_place,
    escrow_bucket,evidence_kind,created_at)
  VALUES(
    NEW.tournament_id,NEW.from_entity_id,'wallet_charge',lower(NEW.category),
    NEW.club_id,round(NEW.amount,2),v_split.refund_prize,
    v_split.refund_bounty,v_split.refund_fee,NEW.id,NULL,NULL,NULL,
    'wallet_gross','atomic_wallet_charge',transaction_timestamp()) RETURNING id INTO v_original_entitlement;
  PERFORM set_config('app.pnl_tournament_entitlement',v_original_entitlement::text,true);
  RETURN NULL;
END;
$function$

public.fn_ca_chip_ledger_enrich().def:
CREATE OR REPLACE FUNCTION public.fn_ca_chip_ledger_enrich()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_prev text;
BEGIN
  NEW.amount := round(NEW.amount, 2);
  NEW.created_at := COALESCE(NEW.created_at, now());

  NEW.epoch_id      := COALESCE(NEW.epoch_id, public.fn_ca_current_epoch());
  NEW.actor_service := COALESCE(NEW.actor_service,
                                current_setting('application_name', true));
  NEW.db_role       := COALESCE(NEW.db_role, current_user);
  NEW.correlation_id := COALESCE(NEW.correlation_id,
      NULLIF(current_setting('app.ledger_correlation', true), '')::uuid);
  NEW.settlement_id  := COALESCE(NEW.settlement_id,
      NULLIF(current_setting('app.ledger_settlement', true), ''));
  IF NEW.idempotency_key IS NULL THEN
    NEW.idempotency_key := NULLIF(current_setting('app.ledger_idempotency_key', true), '');
    IF NEW.idempotency_key IS NOT NULL THEN
      -- consume-once: the next row in this transaction must not inherit it
      PERFORM set_config('app.ledger_idempotency_key', '', true);
    END IF;
  END IF;

  /* PHASE 6.4 (2026-09-05): EVERY LEG NAMES ITS HAND OR ITS EVENT. The doors
     that know the hand say so on app.ledger_hand_id (the rake door and the
     BBJ drop, since today) or on a 'bbj:<hand>' settlement; the rake
     settlement is not read for it because it carries a random key when the
     hand is unknown, and a guessed hand is worse than none; a spin's reserve legs
     carry the spin on their prize_liability side. Read them here, once, so
     the hand and the event are columns a per-hand audit can index on rather
     than strings it has to parse. 231,211 legs a day; 29,617 named a hand
     and 50,359 an event before this. */
  IF NEW.hand_id IS NULL THEN
    NEW.hand_id := NULLIF(current_setting('app.ledger_hand_id', true), '')::uuid;
    IF NEW.hand_id IS NULL AND NEW.settlement_id ~ '^bbj:[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$' THEN
      NEW.hand_id := split_part(NEW.settlement_id, ':', 2)::uuid;
    END IF;
  END IF;
  IF NEW.tournament_id IS NULL THEN
    NEW.tournament_id := NULLIF(current_setting('app.ledger_tournament_id', true), '')::uuid;
    /* PHASE 6 GATE (2026-09-05): a prize_liability side IS the event, on every
       category, not only the two spin ones. This is what the 6.4 measurement
       missed: 777 tournament rake settlements in three hours (the fee leaving
       an event to a union rake wallet or a club treasury) and every tournament
       add-on named nothing. Read against the rows first: all 777 from_entity_id
       values are real tournaments. The FROM side wins when both sides are
       prize_liability (a satellite seat's pool transfer, which already stamps
       the satellite itself). */
    IF NEW.tournament_id IS NULL THEN
      IF NEW.from_type = 'prize_liability' THEN NEW.tournament_id := NEW.from_entity_id;
      ELSIF NEW.to_type = 'prize_liability' THEN NEW.tournament_id := NEW.to_entity_id;
      END IF;
    END IF;
  END IF;
  /* PHASE 6 GATE: and a table_stack side IS the table. Every cash buy-in,
     add-on and cash-out carries the table on its felt side (231, 53 and 222
     of each measured in the same window, every one a real table row) and
     none of them carried table_id. A cash buy-in is not a hand; the table is
     the name it has. */
  IF NEW.table_id IS NULL THEN
    IF NEW.to_type = 'table_stack' THEN NEW.table_id := NEW.to_entity_id;
    ELSIF NEW.from_type = 'table_stack' THEN NEW.table_id := NEW.from_entity_id;
    END IF;
  END IF;

  -- Tamper evidence: monotone sequence + per-row content checksum. NOT chained
  -- through the previous row's hash at insert time - that would put a global
  -- serialization point (and deadlock surface) inside every money transaction,
  -- which the availability policy forbids. prev_hash is best-effort forensics.
  NEW.chain_seq := nextval('public.chip_ledger_chain_seq');
  SELECT row_hash INTO v_prev
    FROM public.chip_ledger
   WHERE chain_seq = NEW.chain_seq - 1;
  NEW.prev_hash := v_prev;
  NEW.row_hash := encode(extensions.digest(
      'v1'
      || '|' || NEW.chain_seq::text
      || '|' || COALESCE(NEW.epoch_id::text,'')
      || '|' || NEW.amount::text
      || '|' || NEW.from_type || ':' || COALESCE(NEW.from_entity_id::text,'')
      || '|' || NEW.to_type   || ':' || COALESCE(NEW.to_entity_id::text,'')
      || '|' || NEW.category
      || '|' || COALESCE(NEW.idempotency_key,'')
      || '|' || COALESCE(NEW.correlation_id::text,'')
      || '|' || NEW.created_at::text,
      'sha256'), 'hex');
  RETURN NEW;
END $function$

public.fn_ca_declare_ledger(p_category t.def:
CREATE OR REPLACE FUNCTION public.fn_ca_declare_ledger(p_category text, p_counterparty text, p_counterparty_entity uuid DEFAULT NULL::uuid, p_settlement_id uuid DEFAULT NULL::uuid, p_idempotency_key text DEFAULT NULL::text, p_autoskip_tables text[] DEFAULT NULL::text[])
 RETURNS void
 LANGUAGE plpgsql
 SET search_path TO 'public'
AS $function$
DECLARE
  v_t text;
BEGIN
  -- validate against the LIVE vocabulary so this can never lag a CHECK change
  IF p_category IS NULL OR NOT EXISTS (
    SELECT 1 FROM pg_constraint
     WHERE conrelid = 'public.chip_ledger'::regclass
       AND conname = 'chip_ledger_category_check'
       AND pg_get_constraintdef(oid) LIKE '%''' || p_category || '''%') THEN
    RAISE EXCEPTION 'fn_ca_declare_ledger: category % is not in the ledger vocabulary - add it to chip_ledger_category_check FIRST, then declare it', p_category;
  END IF;
  IF p_counterparty IS NULL OR NOT EXISTS (
    SELECT 1 FROM pg_constraint
     WHERE conrelid = 'public.chip_ledger'::regclass
       AND conname = 'chip_ledger_from_type_check'
       AND pg_get_constraintdef(oid) LIKE '%''' || p_counterparty || '''%') THEN
    RAISE EXCEPTION 'fn_ca_declare_ledger: counterparty % is not in the ledger vocabulary - add it to the from/to type CHECKs FIRST, then declare it', p_counterparty;
  END IF;

  PERFORM set_config('app.ledger_category', p_category, true);
  PERFORM set_config('app.ledger_counterparty', p_counterparty, true);
  PERFORM set_config('app.ledger_counterparty_entity',
                     COALESCE(p_counterparty_entity::text, ''), true);
  /* A COUNTERPARTY NAMES ITS COLUMN, AND A NEW DECLARATION FORGETS THE LAST
     ONE'S (2026-10-04). A union wallet holds six balances; the caller whose
     counterparty is one of them names it on app.ledger_counterparty_label
     after this call, and fn_ca_autoledger writes it on that side. */
  PERFORM set_config('app.ledger_counterparty_label', '', true);
  IF p_settlement_id IS NOT NULL THEN
    PERFORM set_config('app.ledger_settlement', p_settlement_id::text, true);
  END IF;
  IF p_idempotency_key IS NOT NULL THEN
    PERFORM set_config('app.ledger_idempotency_key', p_idempotency_key, true);
  END IF;
  IF p_autoskip_tables IS NOT NULL THEN
    FOREACH v_t IN ARRAY p_autoskip_tables LOOP
      IF v_t !~ '^[a-z_]+$' THEN
        RAISE EXCEPTION 'fn_ca_declare_ledger: bad autoskip table name %', v_t;
      END IF;
      PERFORM set_config('app.ledger_autoskip_' || v_t, '1', true);
    END LOOP;
  END IF;
END $function$

public.fn_ca_deleted_wallet_bank_return(.def:
CREATE OR REPLACE FUNCTION public.fn_ca_deleted_wallet_bank_return(p_club uuid, p_user uuid, p_source text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
 SET lock_timeout TO '4s'
AS $function$
DECLARE
 v_player numeric:=0; v_agent numeric:=0; v_bank numeric; v_owner uuid; v_reserved numeric:=0;
 v_op uuid; v_amount numeric; v_source text; v_key text; v_saved jsonb:='{}'::jsonb;
 v_keys text[]:=ARRAY['app.ledger_category','app.ledger_counterparty',
 'app.ledger_counterparty_entity','app.ledger_counterparty_label','app.ledger_settlement',
 'app.ledger_idempotency_key','app.ledger_correlation','app.ledger_tournament','app.cash_original_debit_ledger','app.ledger_autoskip_clubs',
 'app.ledger_autoskip_club_members','app.ledger_autoskip_agents'];
BEGIN
 PERFORM 1 FROM public.profiles WHERE id=p_user AND status='deleted' FOR SHARE;
 IF NOT FOUND THEN
  RETURN jsonb_build_object('success',false,'reason','account_not_deleted');
 END IF;
 IF p_source NOT IN ('wallets','player_wallet','agent_wallet') OR p_source IS NULL THEN RAISE EXCEPTION 'unknown_deleted_wallet_source'; END IF;
 -- Agent-first for the explicit two-wallet lifecycle return. A live credit
 -- takes only its already-owned source row, never the other wallet.
 IF p_source IN ('wallets','agent_wallet') THEN
  SELECT greatest(coalesce(agent_wallet_balance,0),0) INTO v_agent
  FROM public.agents WHERE club_id=p_club AND user_id=p_user FOR NO KEY UPDATE;
 END IF;
 IF p_source IN ('wallets','player_wallet') THEN
  SELECT greatest(coalesce(chip_balance,0)-coalesce(held_chips,0)-coalesce(locked_chips,0),0)
  INTO v_player FROM public.club_members WHERE club_id=p_club AND user_id=p_user FOR NO KEY UPDATE;
 END IF;
 v_player:=coalesce(v_player,0); v_agent:=coalesce(v_agent,0);
 -- Published money owed to other players is not free money at account closure.
 -- The private reader locks existing periods NOWAIT and validates latest first.
 -- 20261022: a real agent pays its players' rakeback from its agent wallet,
 -- so published obligations are held back in the agent wallet first and only
 -- the part it cannot cover stays in the player wallet. reserved_rakeback is
 -- what this call held back from the wallet(s) it returns.
 IF v_player>0 OR v_agent>0 THEN
  v_reserved:=smarter_private.deleted_wallet_published_rakeback_reserve(p_club,p_user);
  IF p_source='player_wallet' THEN
   v_reserved:=greatest(v_reserved-COALESCE((SELECT greatest(coalesce(a.agent_wallet_balance,0),0) FROM public.agents a WHERE a.club_id=p_club AND a.user_id=p_user),0),0);
   v_player:=greatest(v_player-v_reserved,0);
  ELSIF p_source='agent_wallet' THEN
   v_agent:=greatest(v_agent-v_reserved,0);
  ELSE
   v_player:=greatest(v_player-greatest(v_reserved-v_agent,0),0);
   v_agent:=greatest(v_agent-v_reserved,0);
  END IF;
 END IF;
 SELECT chip_treasury,owner_id INTO v_bank,v_owner FROM public.clubs
 WHERE id=p_club AND asset='chips' AND lifecycle_status='active' FOR NO KEY UPDATE;
 IF NOT FOUND THEN RETURN jsonb_build_object('success',false,'reason','not_active_chip_club'); END IF;
 IF v_player+v_agent=0 THEN RETURN jsonb_build_object('success',true,'amount',0,'player_chips',0,'agent_chips',0,'reserved_rakeback',v_reserved,'bank_after',v_bank); END IF;
 IF public.fn_platform_frozen() THEN RAISE EXCEPTION 'platform_is_frozen'; END IF;
 FOREACH v_key IN ARRAY v_keys LOOP
  v_saved:=v_saved||jsonb_build_object(v_key,coalesce(current_setting(v_key,true),''));
 END LOOP;
 FOREACH v_source IN ARRAY ARRAY['player_wallet','agent_wallet'] LOOP
  v_amount:=CASE WHEN v_source='player_wallet' THEN v_player ELSE v_agent END;
  IF v_amount=0 THEN CONTINUE; END IF;
  v_op:=gen_random_uuid();
  PERFORM set_config('app.ledger_autoskip_club_members','',true);
  PERFORM set_config('app.ledger_autoskip_agents','',true);
  PERFORM public.fn_ca_declare_ledger('club_bank_claim','club_treasury',p_club,NULL,
   'deleted_account_bank_return:'||v_op,ARRAY['clubs']);
  PERFORM set_config('app.ledger_correlation',v_op::text,true);
  PERFORM set_config('app.ledger_settlement','',true);
  PERFORM set_config('app.ledger_tournament','',true);
  IF v_source='player_wallet' THEN
   UPDATE public.club_members SET chip_balance=chip_balance-v_amount,updated_at=now()
   WHERE club_id=p_club AND user_id=p_user;
  ELSE
   UPDATE public.agents SET agent_wallet_balance=agent_wallet_balance-v_amount,updated_at=now()
   WHERE club_id=p_club AND user_id=p_user;
  END IF;
  UPDATE public.clubs SET chip_treasury=coalesce(chip_treasury,0)+v_amount,updated_at=now()
  WHERE id=p_club RETURNING chip_treasury INTO v_bank;
  INSERT INTO public.chip_transactions
   (club_id,from_user_id,to_user_id,amount,transaction_type,notes,metadata,balance_after)
  VALUES(p_club,p_user,v_owner,v_amount,'club_bank_claim','Deleted Account Chips Returned To Club Bank',
   jsonb_build_object('op_id',v_op,'source',v_source,'direction','into_bank',
    'reason','deleted_account','bank_after',v_bank)
    ||CASE WHEN public.fn_caller_is_engine() IS TRUE AND nullif(current_setting('app.accounting_routing_context',true),'') IS NOT NULL
      THEN jsonb_build_object('accounting_routing_context',current_setting('app.accounting_routing_context',true)) ELSE '{}'::jsonb END,v_bank);
 END LOOP;
 FOREACH v_key IN ARRAY v_keys LOOP PERFORM set_config(v_key,v_saved->>v_key,true); END LOOP;
 RETURN jsonb_build_object('success',true,'amount',v_player+v_agent,
  'player_chips',v_player,'agent_chips',v_agent,'reserved_rakeback',v_reserved,'bank_after',v_bank);
END;
$function$

public.fn_ca_deleted_wallet_credit().def:
CREATE OR REPLACE FUNCTION public.fn_ca_deleted_wallet_credit()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE v_club uuid;
BEGIN
 IF TG_TABLE_NAME='profiles' THEN
  -- Only clubs where the person holds free chips have anything to return.
  FOR v_club IN
   SELECT s.club_id FROM (
    SELECT m.club_id FROM public.club_members m WHERE m.user_id=NEW.id
      AND coalesce(m.chip_balance,0)-coalesce(m.held_chips,0)-coalesce(m.locked_chips,0) > 0
    UNION
    SELECT a.club_id FROM public.agents a WHERE a.user_id=NEW.id
      AND coalesce(a.agent_wallet_balance,0) > 0
   ) s ORDER BY s.club_id
  LOOP
   PERFORM public.fn_ca_deleted_wallet_bank_return(v_club,NEW.id,'wallets');
  END LOOP;
  RETURN NEW;
 END IF;
 -- Only the trusted owning stage may hold a pass-through credit until its
 -- original transfer and final net-balance assertions have completed. Each
 -- stage flushes these exact pinned recipients before returning success.
 -- A browser-set GUC or an unrelated row never defers. Since 20261022 weekly
 -- commission is credited to agent wallets, so the commission stage's pinned
 -- agent-wallet recipients defer exactly as its member wallets did.
 IF TG_TABLE_NAME='agents' AND public.fn_caller_is_engine() IS TRUE
  AND nullif(current_setting('app.accounting_routing_context',true),'') IS NOT NULL
  AND current_setting('app.deleted_wallet_routing_stage',true)='commission'
  AND to_regclass('pg_temp._routed_nodes') IS NOT NULL THEN
  IF EXISTS(SELECT FROM pg_temp._routed_nodes n WHERE n.club_id=NEW.club_id AND n.user_id=NEW.user_id) THEN RETURN NEW; END IF;
 END IF;
 IF TG_TABLE_NAME='club_members' AND public.fn_caller_is_engine() IS TRUE
  AND nullif(current_setting('app.accounting_routing_context',true),'') IS NOT NULL THEN
  IF current_setting('app.deleted_wallet_routing_stage',true)='commission'
   AND to_regclass('pg_temp._routed_nodes') IS NOT NULL THEN
   IF EXISTS(SELECT FROM pg_temp._routed_nodes n WHERE n.club_id=NEW.club_id AND n.user_id=NEW.user_id) THEN RETURN NEW; END IF;
  ELSIF current_setting('app.deleted_wallet_routing_stage',true)='rakeback'
   AND to_regclass('pg_temp._routed_player_wallets') IS NOT NULL THEN
   IF EXISTS(SELECT FROM pg_temp._routed_player_wallets w WHERE w.club_id=NEW.club_id AND w.user_id=NEW.user_id) THEN RETURN NEW; END IF;
  END IF;
 END IF;
 IF EXISTS (SELECT 1 FROM public.profiles WHERE id=NEW.user_id AND status='deleted') THEN
  PERFORM public.fn_ca_deleted_wallet_bank_return(NEW.club_id,NEW.user_id,CASE WHEN TG_TABLE_NAME='agents' THEN 'agent_wallet' ELSE 'player_wallet' END);
 END IF;
 RETURN NEW;
END;
$function$

public.fn_ca_escrow_apply(p_tournament_i.def:
CREATE OR REPLACE FUNCTION public.fn_ca_escrow_apply(p_tournament_id uuid, p_what text, p_gross_in numeric DEFAULT 0, p_fee_entries_in numeric DEFAULT 0, p_satellite_fee_in numeric DEFAULT 0, p_bounty_in numeric DEFAULT 0, p_overlay_in numeric DEFAULT 0, p_satellite_in numeric DEFAULT 0, p_prize_out numeric DEFAULT 0, p_bounty_out numeric DEFAULT 0, p_fee_out numeric DEFAULT 0, p_refund numeric DEFAULT 0, p_reserve_out numeric DEFAULT 0, p_reserve_in numeric DEFAULT 0)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v public.tournament_escrow%ROWTYPE;
  v_spin boolean; e record; v_sat_fee numeric;
  v_prize_in numeric; v_tot numeric; r_p numeric := 0; r_b numeric := 0; r_f numeric := 0;
  v_outflow boolean := COALESCE(p_prize_out, 0) > 0 OR COALESCE(p_bounty_out, 0) > 0 OR COALESCE(p_fee_out, 0) > 0 OR COALESCE(p_refund, 0) > 0;
  r_out numeric := 0; r_in numeric := 0;
  v_sp_prize numeric; v_sp_bounty numeric;
BEGIN
  SELECT * INTO v FROM public.tournament_escrow WHERE tournament_id = p_tournament_id FOR UPDATE;
  IF NOT FOUND THEN
    SELECT (COALESCE(t.variant, '') = 'spin' OR COALESCE(t.is_premium_spin, false)) INTO v_spin
      FROM public.tournaments t WHERE t.id = p_tournament_id;
    IF NOT FOUND THEN
      RETURN;
    END IF;
    SELECT * INTO e FROM public.fn_ca_tournament_escrow(p_tournament_id);
    SELECT COALESCE(sum(rr.rake_amount), 0) INTO v_sat_fee FROM public.rake_records rr
     WHERE rr.tournament_id = p_tournament_id AND rr.is_tournament AND rr.source = 'fn_award_satellite_seat';
    v_prize_in := e.prize_in; v_tot := e.prize_in + e.satellite_in + e.bounty_in + e.fee_in;
    IF v_tot > 0 THEN
      r_p := round(e.refund_out * (e.prize_in + e.satellite_in) / v_tot, 2);
      r_b := round(e.refund_out * e.bounty_in / v_tot, 2);
    ELSE
      r_p := e.refund_out;
    END IF;
    r_f := round(e.refund_out - r_p - r_b, 2);
    /* PHASE 5.2: a spin's prize bank also moves through the reserve.
       2026-09-07: read from spin_reserve_ledger, not from the chip_ledger
       spin_entry / spin_prize legs it used to read. Those legs are the DERIVED
       record and one pair of them went missing: on 2026-09-06 at 12:50:38 both
       legs of tournament afa045db landed as `adjustment` rows into
       settlement_suspense with a NULL entity, their intended category
       surviving only inside the description text. The escrow therefore never
       learned that 60.00 had been drawn for a 60.00 prize, and
       fn_settle_tournament_obligation refused the winner's last 4.80 as
       escrow_short - for a day, with an open critical alert nobody could act
       on. spin_reserve_ledger is the record the pool balance itself moved by;
       it cannot be missing while the money has moved. Verified across 18,318
       escrow rows: 0 disagree with it, 1 was missing the legs entirely. */
    SELECT COALESCE(sum(l.amount) FILTER (WHERE l.kind = 'contribution'), 0),
           COALESCE(-sum(l.amount) FILTER (WHERE l.kind = 'jackpot_draw'), 0)
      INTO r_out, r_in
      FROM public.spin_reserve_ledger l
     WHERE l.tournament_id = p_tournament_id
       AND l.kind IN ('contribution', 'jackpot_draw');
    INSERT INTO public.tournament_escrow
      (tournament_id, enforced, gross_in, fee_entries_in, satellite_fee_in, bounty_in, overlay_in, satellite_in,
       prize_out, bounty_out, fee_out, refund_prize, refund_bounty, refund_fee, reserve_out, reserve_in,
       prize_balance, bounty_balance, fee_balance, opened_from)
    VALUES
      (p_tournament_id, true,
       round(e.prize_in + e.bounty_in + (e.fee_in - v_sat_fee), 2), round(e.fee_in - v_sat_fee, 2), round(v_sat_fee, 2),
       e.bounty_in, e.overlay_in, e.satellite_in, e.prize_out, e.bounty_out, e.fee_out, r_p, r_b, r_f, round(r_out, 2), round(r_in, 2),
       round(e.prize_balance - r_out + r_in, 2), e.bounty_balance, e.fee_balance,
       'shadow at first sight (' || p_what || ')')
    ON CONFLICT (tournament_id) DO NOTHING;
    RETURN;
  END IF;

  IF COALESCE(p_refund, 0) > 0 THEN
    v_prize_in := v.gross_in - v.fee_entries_in - v.bounty_in + v.satellite_in;
    v_tot := v.gross_in + v.satellite_in + v.satellite_fee_in;
    IF v_tot > 0 THEN
      r_p := round(p_refund * v_prize_in / v_tot, 2);
      r_b := round(p_refund * v.bounty_in / v_tot, 2);
    ELSE
      SELECT s.prize, s.bounty INTO v_sp_prize, v_sp_bounty
        FROM public.tournaments t2
        CROSS JOIN LATERAL public.fn_tournament_entry_split(t2.buy_in_amount, t2.buy_in_fee, t2.bounty_amount,
               COALESCE(t2.is_bounty, false) OR COALESCE(t2.is_pko, false) OR COALESCE(t2.is_mystery_bounty, false)) s
       WHERE t2.id = p_tournament_id;
      IF COALESCE(v_sp_prize, 0) + COALESCE(v_sp_bounty, 0) > 0 THEN
        r_p := round(p_refund * v_sp_prize / (v_sp_prize + v_sp_bounty + (SELECT COALESCE(t3.buy_in_fee, 0) FROM public.tournaments t3 WHERE t3.id = p_tournament_id)), 2);
        r_b := round(p_refund * v_sp_bounty / (v_sp_prize + v_sp_bounty + (SELECT COALESCE(t3.buy_in_fee, 0) FROM public.tournaments t3 WHERE t3.id = p_tournament_id)), 2);
      ELSE
        r_p := p_refund;
      END IF;
    END IF;
    r_f := round(p_refund - r_p - r_b, 2);
  END IF;

  UPDATE public.tournament_escrow
     SET gross_in = gross_in + COALESCE(p_gross_in, 0),
         fee_entries_in = fee_entries_in + COALESCE(p_fee_entries_in, 0),
         satellite_fee_in = satellite_fee_in + COALESCE(p_satellite_fee_in, 0),
         bounty_in = bounty_in + COALESCE(p_bounty_in, 0),
         overlay_in = overlay_in + COALESCE(p_overlay_in, 0),
         satellite_in = satellite_in + COALESCE(p_satellite_in, 0),
         prize_out = prize_out + COALESCE(p_prize_out, 0),
         bounty_out = bounty_out + COALESCE(p_bounty_out, 0),
         fee_out = fee_out + COALESCE(p_fee_out, 0),
         refund_prize = refund_prize + r_p, refund_bounty = refund_bounty + r_b, refund_fee = refund_fee + r_f,
         reserve_out = reserve_out + COALESCE(p_reserve_out, 0), reserve_in = reserve_in + COALESCE(p_reserve_in, 0),
         updated_at = now()
   WHERE tournament_id = p_tournament_id;
  UPDATE public.tournament_escrow
     SET prize_balance  = round((gross_in - fee_entries_in - bounty_in) + overlay_in + satellite_in - reserve_out + reserve_in - prize_out - refund_prize, 2),
         bounty_balance = round(bounty_in - bounty_out - refund_bounty, 2),
         fee_balance    = round(fee_entries_in + satellite_fee_in - fee_out - refund_fee, 2)
   WHERE tournament_id = p_tournament_id
   RETURNING * INTO v;

  IF v.enforced AND v_outflow
     AND (v.prize_balance < -0.005 OR v.bounty_balance < -0.005 OR v.fee_balance < -0.005) THEN
    RAISE EXCEPTION 'escrow_short: tournament % cannot pay this % - it would leave prize %, bounty %, fee % (chip standard Phase 5.1: an event pays only what it holds)',
      p_tournament_id, p_what, v.prize_balance, v.bounty_balance, v.fee_balance
      USING ERRCODE = 'P0403';
  END IF;
END;
$function$

public.fn_ca_escrow_can_pay(p_tournament.def:
CREATE OR REPLACE FUNCTION public.fn_ca_escrow_can_pay(p_tournament_id uuid, p_kind text, p_amount numeric)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE v public.tournament_escrow%ROWTYPE; v_have numeric; d record;
BEGIN
  IF public.fn_poker_diamond_tournament(p_tournament_id) THEN
    SELECT * INTO d FROM public.fn_poker_diamond_tournament_escrow(p_tournament_id);
    v_have := CASE WHEN p_kind IN ('bounty', 'mystery_bounty', 'bounty_residual') THEN d.bounty_balance
                   WHEN p_kind = 'refund' THEN d.prize_balance + d.bounty_balance + d.fee_balance
                   ELSE d.prize_balance END;
    RETURN jsonb_build_object('known', true, 'enforced', true, 'available', v_have,
                              'ok', p_amount <= v_have, 'asset', 'diamonds',
                              'prize_balance', d.prize_balance, 'bounty_balance', d.bounty_balance, 'fee_balance', d.fee_balance);
  END IF;
  SELECT * INTO v FROM public.tournament_escrow WHERE tournament_id = p_tournament_id;
  IF NOT FOUND THEN
    RETURN jsonb_build_object('known', false);
  END IF;
  v_have := CASE WHEN p_kind IN ('bounty', 'mystery_bounty', 'bounty_residual') THEN v.bounty_balance
                 WHEN p_kind = 'refund' THEN v.prize_balance + v.bounty_balance + v.fee_balance
                 ELSE v.prize_balance END;
  RETURN jsonb_build_object('known', true, 'enforced', v.enforced, 'available', v_have,
                            'ok', (NOT v.enforced) OR p_amount <= v_have + 0.005,
                            'prize_balance', v.prize_balance, 'bounty_balance', v.bounty_balance, 'fee_balance', v.fee_balance);
END;
$function$

public.fn_ca_escrow_on_reserve_leg().def:
CREATE OR REPLACE FUNCTION public.fn_ca_escrow_on_reserve_leg()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
BEGIN
  IF NEW.category = 'spin_entry' THEN
    PERFORM public.fn_ca_escrow_apply(NEW.from_entity_id, 'spin pool to reserve', p_reserve_out => round(NEW.amount, 2));
  ELSIF NEW.category = 'spin_prize' THEN
    PERFORM public.fn_ca_escrow_apply(NEW.to_entity_id, 'spin prize from reserve', p_reserve_in => round(NEW.amount, 2));
  END IF;
  RETURN NULL;
END;
$function$

public.fn_ca_escrow_on_seat_transfer_leg.def:
CREATE OR REPLACE FUNCTION public.fn_ca_escrow_on_seat_transfer_leg()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
BEGIN
  IF NEW.metadata->>'entry_split_version' = '2' THEN
    IF round(NEW.amount,2) IS DISTINCT FROM round((NEW.metadata->>'entry_prize')::numeric
        + (NEW.metadata->>'entry_bounty')::numeric + (NEW.metadata->>'entry_fee')::numeric,2)
       OR (NEW.metadata->>'entry_prize')::numeric < 0
       OR (NEW.metadata->>'entry_bounty')::numeric < 0
       OR (NEW.metadata->>'entry_fee')::numeric < 0 THEN
      RAISE EXCEPTION 'Satellite transfer does not match its funded split' USING ERRCODE='23514';
    END IF;
    PERFORM public.fn_ca_escrow_apply(NEW.to_entity_id, 'satellite split entry',
      p_gross_in => round(NEW.amount - (NEW.metadata->>'entry_fee')::numeric,2),
      p_bounty_in => (NEW.metadata->>'entry_bounty')::numeric);
    RETURN NULL;
  END IF;
  PERFORM public.fn_ca_escrow_apply(NEW.to_entity_id, 'satellite seat in', p_satellite_in => round(NEW.amount, 2));
  RETURN NULL;
END;
$function$

public.fn_ca_finding_key(p_dedupe_key te.def:
CREATE OR REPLACE FUNCTION public.fn_ca_finding_key(p_dedupe_key text, p_classification text, p_layer text, p_club_id uuid, p_union_id uuid)
 RETURNS text
 LANGUAGE plpgsql
 IMMUTABLE
 SET search_path TO 'public'
AS $function$
DECLARE
  k text := COALESCE(p_dedupe_key, '');
  before text;
BEGIN
  FOR i IN 1..4 LOOP
    before := k;
    k := regexp_replace(k, ':[0-9a-fA-F]{8}-[0-9a-fA-F]{4}-[0-9a-fA-F]{4}-[0-9a-fA-F]{4}-[0-9a-fA-F]{12}$', '');
    k := regexp_replace(k, ':[0-9a-fA-F]{32}$', '');
    k := regexp_replace(k, ':[0-9]{4}-[0-9]{2}-[0-9]{2}(-[0-9]{2})?$', '');
    EXIT WHEN k = before;
  END LOOP;

  IF k = '' THEN
    k := COALESCE(p_classification, 'unknown');
  END IF;

  RETURN k
      || '|' || COALESCE(p_layer, 'unknown')
      || '|' || COALESCE(p_club_id::text, '-')
      || '|' || COALESCE(p_union_id::text, '-');
END $function$

public.fn_ca_fund_club(p_club_id uuid, p.def:
CREATE OR REPLACE FUNCTION public.fn_ca_fund_club(p_club_id uuid, p_amount numeric, p_reason text, p_idempotency_key text DEFAULT NULL::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_club record; v_key text; v_before numeric; v_after numeric;
  v_leg uuid; v_supply numeric; v_reason text := btrim(COALESCE(p_reason, ''));
BEGIN
  IF p_amount IS NULL OR p_amount <= 0 OR p_amount <> round(p_amount, 2) THEN
    RAISE EXCEPTION 'fund_club refused: amount must be positive to two decimals';
  END IF;
  IF length(v_reason) < 10 THEN
    RAISE EXCEPTION 'fund_club refused: a reason of at least 10 characters is required';
  END IF;
  SELECT * INTO v_club FROM public.clubs WHERE id = p_club_id FOR NO KEY UPDATE;
  IF v_club.id IS NULL THEN
    RAISE EXCEPTION 'fund_club refused: unknown club %', p_club_id;
  END IF;
  v_key := COALESCE(p_idempotency_key,
                    'club-funding:' || p_club_id::text || ':' ||
                    extract(epoch from clock_timestamp())::bigint::text);
  -- Replay safety: an identical key that already journaled is a no-op.
  IF EXISTS (SELECT 1 FROM public.chip_ledger WHERE idempotency_key = v_key) THEN
    RETURN jsonb_build_object('ok', true, 'replayed', true, 'idempotency_key', v_key);
  END IF;
  v_before := COALESCE(v_club.chip_treasury, 0);

  PERFORM public.fn_ca_declare_ledger('mint', 'system_mint', NULL, NULL, v_key);
  UPDATE public.clubs
     SET chip_treasury = COALESCE(chip_treasury,0) + p_amount
   WHERE id = p_club_id
   RETURNING chip_treasury INTO v_after;
  SELECT id INTO v_leg FROM public.chip_ledger WHERE idempotency_key = v_key;
  -- The declaration is this mint's alone: a later write in the same
  -- transaction must never be journalled as house issuance.
  PERFORM set_config('app.ledger_category', '', true);
  PERFORM set_config('app.ledger_counterparty', '', true);
  PERFORM set_config('app.ledger_counterparty_entity', '', true);
  PERFORM set_config('app.ledger_idempotency_key', '', true);
  IF v_leg IS NULL THEN
    RAISE EXCEPTION 'fund_club: the treasury moved but no journal leg carries key % - refusing to mint what the journal does not carry', v_key;
  END IF;

  -- The register row is the door's, with the door's reason (2026-10-02): the
  -- commit-time check refuses a system_mint leg without one.
  SELECT COALESCE(SUM(CASE WHEN action = 'mint' THEN amount ELSE -amount END), 0) + p_amount
    INTO v_supply FROM public.ca_mint_ledger WHERE asset = 'chips';
  INSERT INTO public.ca_mint_ledger
    (op_id, action, asset, holder_type, holder_id, holder_label, amount,
     balance_before, balance_after, supply_after, reason,
     performed_by, performed_by_label, chip_ledger_id)
  VALUES
    (v_key, 'mint', 'chips',
     CASE WHEN COALESCE(v_club.is_union, false) THEN 'union' ELSE 'club' END,
     p_club_id, v_club.name, p_amount,
     v_before, v_after, v_supply, left(v_reason, 2000),
     auth.uid(), 'fn_ca_fund_club', v_leg);

  RETURN jsonb_build_object('ok', true, 'replayed', false, 'club_id', p_club_id,
                            'amount', p_amount, 'treasury_after', v_after,
                            'idempotency_key', v_key, 'reason', v_reason,
                            'ledger_id', v_leg);
END $function$

public.fn_ca_horse_club_refusal(p_horse.def:
CREATE OR REPLACE FUNCTION public.fn_ca_horse_club_refusal(p_horse uuid, p_host uuid, p_wallet uuid, p_membership boolean)
 RETURNS text
 LANGUAGE plpgsql
 STABLE
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE v_phase text := public.fn_ca_horse_split_phase(); v_home uuid;
BEGIN
  IF v_phase = 'inactive' THEN RETURN NULL; END IF;
  -- The platform arena is not a club; its entitlement rules govern it (20261102191900).
  IF EXISTS (SELECT 1 FROM public.clubs c WHERE c.id = p_host AND coalesce(c.is_platform, false)) THEN RETURN NULL; END IF;
  IF v_phase IN ('draining','executing') THEN
    -- The operation itself writes memberships (departures) under its own flag.
    IF coalesce(current_setting('app.horse_club_split_operation', true), '') <> '' THEN RETURN NULL; END IF;
    RETURN 'HORSE_CLUB_SPLIT_IN_PROGRESS: Horses Are Paused While Their Clubs Are Reassigned';
  END IF;
  v_home := public.fn_ca_horse_assigned_club(p_horse);
  IF v_home IS NULL THEN
    RETURN 'HORSE_HAS_NO_ASSIGNED_CLUB: This Horse Is Not On The Club Manifest';
  END IF;
  IF p_host = 'a41434bb-8d0c-400a-8f0d-e8b3d65afed4'::uuid THEN
    RETURN 'HORSE_NOT_ADMITTED_TO_KINGS_CLUB: Kings Club Has No Horses';
  END IF;
  IF p_membership THEN
    IF p_host IS DISTINCT FROM v_home THEN
      RETURN 'HORSE_ONE_CLUB_ONLY: A Horse Belongs Only To Its Assigned Club';
    END IF;
  ELSIF p_host IS DISTINCT FROM v_home
     AND NOT EXISTS (SELECT 1 FROM public.clubs u
                       JOIN public.union_clubs uc ON uc.union_id = u.union_id AND uc.club_id = v_home
                      WHERE u.id = p_host AND coalesce(u.is_union, false)) THEN
    RETURN 'HORSE_ONE_CLUB_ONLY: A Horse Plays Only In Its Assigned Club Or Its Union';
  END IF;
  IF p_wallet IS NOT NULL AND p_wallet IS DISTINCT FROM v_home THEN
    RETURN 'HORSE_ONE_CLUB_ONLY: A Horse Is Funded Only From Its Assigned Club';
  END IF;
  RETURN NULL;
END $function$

public.fn_ca_horse_split_return_late_cre.def:
CREATE OR REPLACE FUNCTION public.fn_ca_horse_split_return_late_credit()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE
  c_op constant uuid := '5b11c1b0-2026-1102-0000-000000000001';
  c_keys constant text[] := ARRAY['app.ledger_category', 'app.ledger_counterparty',
    'app.ledger_counterparty_entity', 'app.ledger_counterparty_label', 'app.ledger_settlement',
    'app.ledger_idempotency_key', 'app.ledger_correlation', 'app.ledger_autoskip_clubs',
    'app.ledger_autoskip_club_members'];
  v_amount numeric := coalesce(NEW.chip_balance, 0);
  v_saved text[] := ARRAY[]::text[];
  v_lock_timeout text := current_setting('lock_timeout');
  v_key uuid;
  v_bank_before numeric;
  v_bank_after numeric;
  v_after numeric;
  v_state text;
  v_message text;
  i integer;
BEGIN
  IF v_amount <= 0 OR NEW.membership_lifecycle_status IS DISTINCT FROM 'departed' THEN
    RETURN NULL;
  END IF;
  IF NOT EXISTS (SELECT 1 FROM public.ca_horse_club_split_receipts d
                  WHERE d.operation_id = c_op AND d.kind = 'departed'
                    AND d.horse_id = NEW.user_id AND d.club_id = NEW.club_id)
     OR public.fn_ca_horse_assigned_club(NEW.user_id) IS NOT DISTINCT FROM NEW.club_id THEN
    RETURN NULL;
  END IF;

  FOR i IN 1 .. array_length(c_keys, 1) LOOP
    v_saved := v_saved || coalesce(current_setting(c_keys[i], true), '');
  END LOOP;

  BEGIN
    PERFORM set_config('lock_timeout', '200ms', true);
    v_key := md5('horse-split-late-return:' || NEW.club_id::text || ':' || NEW.user_id::text || ':'
                 || txid_current()::text || ':' || clock_timestamp()::text || ':' || v_amount::text)::uuid;
    SELECT coalesce(c.chip_treasury, 0) INTO v_bank_before FROM public.clubs c WHERE c.id = NEW.club_id FOR UPDATE;
    IF v_bank_before IS NULL THEN RAISE EXCEPTION 'horse_split_late_return_club_missing %', NEW.club_id; END IF;
    PERFORM public.fn_ca_declare_ledger('club_bank_claim', 'club_treasury', NEW.club_id, NULL,
      'club_bank_claim:' || v_key::text, ARRAY['clubs']);
    PERFORM set_config('app.ledger_correlation', v_key::text, true);
    PERFORM set_config('app.ledger_autoskip_club_members', '', true);
    UPDATE public.club_members SET chip_balance = coalesce(chip_balance, 0) - v_amount, updated_at = now()
     WHERE club_id = NEW.club_id AND user_id = NEW.user_id RETURNING chip_balance INTO v_after;
    IF v_after IS DISTINCT FROM 0 THEN
      RAISE EXCEPTION 'horse_split_late_return_balance_moved % % %', NEW.club_id, NEW.user_id, v_after;
    END IF;
    UPDATE public.clubs SET chip_treasury = coalesce(chip_treasury, 0) + v_amount, updated_at = now()
     WHERE id = NEW.club_id RETURNING chip_treasury INTO v_bank_after;
    PERFORM set_config('app.ledger_autoskip_clubs', '', true);
    PERFORM set_config('app.ledger_autoskip_club_members', '', true);
    INSERT INTO public.chip_transactions(club_id, from_user_id, to_user_id, amount, transaction_type, notes, metadata, balance_after)
    VALUES (NEW.club_id, NEW.user_id, NULL, v_amount, 'club_bank_claim',
            'Horse Club Split: Late Prize Returned To The Club Bank (Dan, 2026-11-03)',
            jsonb_build_object('op_id', v_key, 'operation', 'horse-club-split-20261102', 'operation_id', c_op,
              'leg', 'late_return', 'actor', 'horse_club_split_late_return',
              'source', 'player_wallet', 'destination', 'club_bank',
              'bank_before', v_bank_before, 'bank_after', v_bank_after,
              'holder_balance_before', v_amount, 'holder_balance_after', v_after),
            v_bank_after);
    INSERT INTO public.ca_horse_club_split_late_returns(club_id, horse_id, amount, op_id, bank_before, bank_after)
    VALUES (NEW.club_id, NEW.user_id, v_amount, v_key, v_bank_before, v_bank_after);
  EXCEPTION WHEN OTHERS THEN
    -- Everything above rolled back with this subtransaction: the credit stays
    -- on the record and fn_ca_horse_club_split_late_claims returns it later.
    GET STACKED DIAGNOSTICS v_state = RETURNED_SQLSTATE, v_message = MESSAGE_TEXT;
    BEGIN
      INSERT INTO public.financial_alerts(severity, source, message, context)
      VALUES ('warning', 'horse_split.late_return_deferred',
              'A late prize on a split-departed horse record stayed on the record; the split late claim returns it after its events finish.',
              jsonb_build_object('club_id', NEW.club_id, 'horse_id', NEW.user_id, 'amount', v_amount,
                                 'sqlstate', v_state, 'error', v_message));
    EXCEPTION WHEN OTHERS THEN
      NULL; -- a note that cannot be written never blocks the payment it describes
    END;
  END;

  FOR i IN 1 .. array_length(c_keys, 1) LOOP
    PERFORM set_config(c_keys[i], v_saved[i], true);
  END LOOP;
  PERFORM set_config('lock_timeout', v_lock_timeout, true);
  RETURN NULL;
END;
$function$

public.fn_ca_incident_notify(p_incident_.def:
CREATE OR REPLACE FUNCTION public.fn_ca_incident_notify(p_incident_id uuid, p_kind text, p_headline text, p_senior_only boolean DEFAULT false)
 RETURNS integer
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  inc  public.ca_drift_incidents;
  rec  uuid;
  n    int := 0;
  club_name  text;
  union_name text;
  body text;
  age_min int;
  v_finding text;
  v_state   text;
  v_kind    text;
  v_fresh   boolean;
  v_withheld text := NULL;
  v_findings numeric;
  /* A LIVENESS FINDING CARRIES NO CHIP AMOUNT AND STILL MATTERS (2026-09-12).
     These detectors answer "is the platform dealing", not "do the chips add
     up", so their discrepancy is always 0.00 and the money gate below would
     mute every one of them. On 2026-09-12 the engine dealt zero tournament
     hands for five hours and every detector that could have said so would have
     been filed and muted here. Measured before changing it: 1,041 pushes were
     withheld on that gate in seven days and exactly 10 were liveness findings,
     so relaxing it generally would have sent a thousand pages a week. Named
     explicitly so a future detector has to ask to be on this list, and so the
     rule that decides who gets woken is readable in one glance. */
  v_liveness CONSTANT text[] := ARRAY[
    'fn_ca_conservation_sweep:fn_ca_orphaned_running_tournaments',
    'fn_ca_conservation_sweep:fn_ca_tables_that_cannot_deal',
    'fn_ca_conservation_sweep:fn_ca_knockout_door_stalled',
    'fn_ca_conservation_sweep:fn_ca_stranded_completing_tournaments',
    'fn_ca_conservation_sweep:fn_ca_rake_rollup_writer_silent',
    'fn_ca_conservation_sweep:fn_ca_absent_tournament_players'
  ];
  v_is_liveness boolean;
  v_is_diamond_rule boolean;
BEGIN
  SELECT * INTO inc FROM public.ca_drift_incidents WHERE id = p_incident_id;
  IF NOT FOUND THEN RETURN 0; END IF;

  v_kind := CASE
              WHEN p_kind = 'escalated'    THEN 'escalated'
              WHEN inc.status = 'resolved' THEN 'resolved'
              ELSE 'raised'
            END;

  v_is_liveness := COALESCE(inc.source, '') = ANY (v_liveness);
  /* A DIAMOND RULE'S CRITICAL IS ITS OWN JUDGEMENT (2026-09-29, Diamond
     Phase 10). The Diamond rule trigger files one incident per rule under
     this source. A rule row often carries no amount (DR0:health_critical names
     an area, not a sum), and the money gate below would mute every one of
     them, so, like a liveness finding, the source is named here and let
     through. Dan's other gates are unchanged: a fix is not a page, and below
     critical is not a page. */
  v_is_diamond_rule := COALESCE(inc.source, '') = 'ca_diamond_incidents';
  v_findings := COALESCE(
      NULLIF(inc.metadata->>'row_count','')::numeric,
      jsonb_array_length(COALESCE(inc.metadata->'rows','[]'::jsonb))::numeric,
      0);

  /* DAN'S RULE, 2026-09-06. Three gates, on the PUSH only. The incident is
     still filed, the event row is still written, the board still shows
     everything - what changes is whose night it interrupts.

     Order matters: 'resolved' is checked first because a fix is the case he
     named explicitly, and it would otherwise slip through on a critical. */
  IF v_kind = 'resolved' THEN
    v_withheld := 'a fix is not a page';
  ELSIF lower(COALESCE(inc.severity,'')) <> 'critical' THEN
    v_withheld := 'severity ' || COALESCE(inc.severity,'null') || ' is not critical';
  ELSIF COALESCE(inc.discrepancy_amount, 0) = 0 AND NOT v_is_liveness AND NOT v_is_diamond_rule THEN
    v_withheld := 'nothing is unaccounted for (0.00)';
  ELSIF COALESCE(inc.discrepancy_amount, 0) = 0 AND v_is_liveness AND v_findings = 0 THEN
    /* A liveness detector that found nothing is the healthy case and is not a
       page either. Only a detector that actually found something gets through. */
    v_withheld := 'the check is live and found nothing';
  END IF;

  IF v_withheld IS NOT NULL THEN
    INSERT INTO public.ca_incident_events (incident_id, kind, detail)
    VALUES (inc.id, 'notify_withheld',
            jsonb_build_object('reason', v_withheld, 'kind', v_kind,
                               'severity', inc.severity,
                               'discrepancy', inc.discrepancy_amount,
                               'headline', left(p_headline, 110),
                               'rule', 'Dan 2026-09-06: only critical errors that need my attention'));
    RETURN 0;
  END IF;

  SELECT name INTO club_name  FROM public.clubs  WHERE id = inc.club_id;
  SELECT name INTO union_name FROM public.unions WHERE id = inc.union_id;
  age_min := GREATEST(0, floor(extract(epoch FROM now() - inc.detected_at) / 60))::int;

  IF v_is_diamond_rule THEN
    /* Say which rule, what it found and how many Diamonds are in doubt. */
    body := format(
      '%s | %s%s. Age %smin, reconcile target %s.',
      upper(inc.severity),
      CASE WHEN COALESCE(inc.discrepancy_amount, 0) <> 0
           THEN to_char(inc.discrepancy_amount, 'FM999999999990') || ' Diamonds in doubt. '
           ELSE '' END,
      rtrim(COALESCE(inc.suspected_cause, inc.source), '. '),
      age_min, to_char(inc.deadline_at, 'HH24:MI UTC'));
  ELSIF v_is_liveness AND COALESCE(inc.discrepancy_amount, 0) = 0 THEN
    /* Say what was actually found. "drift 0.00 chips" reads as a rounding
       error, and an alert that reads like a rounding error gets ignored. */
    body := format(
      '%s | %s: %s finding(s) on the %s layer. %s%sAge %smin, reconcile target %s.',
      upper(inc.severity), inc.entity_type,
      to_char(v_findings, 'FM999999999990'),
      inc.layer,
      COALESCE('Club ' || club_name || '. ', ''),
      COALESCE('Union ' || union_name || '. ', ''),
      age_min, to_char(inc.deadline_at, 'HH24:MI UTC'));
  ELSE
    body := format(
      '%s | %s drift %s %s (%s layer). Expected %s, actual %s. %s%sAge %smin, reconcile target %s. Auto-repair: %s.',
      upper(inc.severity), inc.classification,
      to_char(COALESCE(inc.discrepancy_amount,0), CASE WHEN inc.currency = 'diamonds' THEN 'FM999999999990' ELSE 'FM999999999990.00' END),
      CASE WHEN inc.currency = 'diamonds' THEN 'Diamonds' ELSE 'chips' END,
      inc.layer,
      COALESCE(to_char(inc.expected_amount,'FM999999999990.00'),'?'),
      COALESCE(to_char(inc.actual_amount,'FM999999999990.00'),'?'),
      COALESCE('Club ' || club_name || '. ', ''),
      COALESCE('Union ' || union_name || '. ', ''),
      age_min, to_char(inc.deadline_at, 'HH24:MI UTC'), inc.auto_repair_status);
  END IF;

  v_finding := public.fn_ca_finding_key(inc.dedupe_key, inc.classification, inc.layer,
                                        inc.club_id, inc.union_id);
  v_state := md5(
      v_kind
      || '|' || COALESCE(inc.severity,'?')
      || '|' || COALESCE(inc.classification,'?')
      || '|' || COALESCE(inc.layer,'?')
      || '|' || COALESCE(inc.club_id::text,'-')
      || '|' || COALESCE(inc.union_id::text,'-')
      || '|' || CASE WHEN v_kind = 'escalated'
                     THEN COALESCE(inc.escalation_level, 0)::text ELSE '' END);

  FOR rec IN SELECT unnest(public.fn_ca_incident_recipient_ids(inc, p_senior_only))
  LOOP
    BEGIN
      v_fresh := NULL;
      INSERT INTO public.ca_incident_notify_ledger AS l
        (recipient_id, finding_key, state_hash, last_kind, last_incident_id)
      VALUES (rec, v_finding, v_state, v_kind, inc.id)
      ON CONFLICT (recipient_id, finding_key) DO UPDATE
        SET state_hash = EXCLUDED.state_hash, last_kind = EXCLUDED.last_kind,
            last_incident_id = EXCLUDED.last_incident_id, last_sent_at = now(),
            send_count = l.send_count + 1
        WHERE l.state_hash IS DISTINCT FROM EXCLUDED.state_hash
           /* A RECURRENCE AFTER A FIX IS NEWS (2026-10-03). 'A fix is not a
              page' returns before this ledger is written, so a resolution
              never re-armed it: a finding that came back after its fix
              matched the state it was last paged with and was filed as
              already reported. 28 critical recurrences in 14 days reached
              nobody, among them the kill switch (-2,624.78), the supply
              snapshot (-100,005.30) and tables that cannot deal. A new
              incident for a finding whose last paged incident is resolved,
              or gone, is a new episode and pages once. A second open
              incident for the same finding still does not. */
           OR (l.last_incident_id IS DISTINCT FROM EXCLUDED.last_incident_id
               AND NOT EXISTS (SELECT 1 FROM public.ca_drift_incidents p
                                WHERE p.id = l.last_incident_id
                                  AND p.status IS DISTINCT FROM 'resolved'))
      RETURNING true INTO v_fresh;

      IF NOT COALESCE(v_fresh, false) THEN
        INSERT INTO public.ca_incident_events (incident_id, kind, detail)
        VALUES (inc.id, 'notified',
                jsonb_build_object('already_reported', true, 'finding_key', v_finding,
                                   'state', v_kind, 'recipient', rec));
        CONTINUE;
      END IF;

      PERFORM public.fn_raise_notification(
        rec, 'financial_incident', left(p_headline, 110), left(body, 480),
        '/hub/club-arena/financial-incidents?id=' || inc.id::text,
        jsonb_build_object('incident_id', inc.id, 'finding_key', v_finding,
                           'classification', inc.classification, 'severity', inc.severity,
                           'discrepancy', inc.discrepancy_amount, 'club_id', inc.club_id,
                           'union_id', inc.union_id, 'deadline_at', inc.deadline_at));
      n := n + 1;
    EXCEPTION WHEN OTHERS THEN
      INSERT INTO public.ca_incident_events (incident_id, kind, detail)
      VALUES (inc.id, 'notify_failed',
              jsonb_build_object('recipient', rec, 'error', SQLERRM));
    END;
  END LOOP;

  INSERT INTO public.ca_incident_events (incident_id, kind, detail)
  VALUES (inc.id, p_kind,
          jsonb_build_object('headline', p_headline, 'recipients', n,
                             'senior_only', p_senior_only, 'age_min', age_min,
                             'finding_key', v_finding, 'state', v_kind));
  RETURN n;
EXCEPTION WHEN OTHERS THEN
  RAISE WARNING 'fn_ca_incident_notify failed for %: %', p_incident_id, SQLERRM;
  RETURN 0;
END $function$

public.fn_ca_issuance_leg_is_registered(.def:
CREATE OR REPLACE FUNCTION public.fn_ca_issuance_leg_is_registered()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_outside text[] := public.fn_ca_noncirculating_chip_stores();
  v_pol public.ca_mint_policy%ROWTYPE;
  v_24h numeric;
BEGIN
  IF NEW.from_type = ANY (v_outside) AND NOT (NEW.to_type = ANY (v_outside))
     AND NEW.category <> 'correction' AND NOT public.fn_ca_launch_is_retirement_reversal(NEW.id) AND NOT (NEW.from_type='issuance_reserve' AND NEW.to_type='club_treasury' AND left(NEW.idempotency_key,5)='mint:' AND public.fn_ca_launch_opening_authorized(substr(NEW.idempotency_key,6),'chips','club',NEW.to_entity_id,NEW.amount)) THEN
    SELECT * INTO v_pol FROM public.ca_mint_policy WHERE id = 1;
    IF NEW.amount > v_pol.per_operation_cap_chips THEN
      RAISE EXCEPTION 'issuance refused: % chips in one leg is over the per-operation ceiling of % (ca_mint_policy; raise it with a reason through fn_ca_mint_policy_set before a deliberate batch)',
        NEW.amount, v_pol.per_operation_cap_chips USING ERRCODE = 'P0403';
    END IF;
    v_24h := public.fn_ca_mint_issued_24h('chips', NEW.id) + NEW.amount;
    IF v_24h > v_pol.rolling_24h_cap_chips THEN
      RAISE EXCEPTION 'issuance refused: this leg would bring the last 24 hours to % chips, over the rolling ceiling of % (ca_mint_policy; raise it with a reason through fn_ca_mint_policy_set before a deliberate batch)',
        v_24h, v_pol.rolling_24h_cap_chips USING ERRCODE = 'P0403';
    END IF;
    -- 2026-10-02: chips enter circulation only under an operation key.
    IF NEW.idempotency_key IS NULL OR btrim(NEW.idempotency_key) = '' THEN
      RAISE EXCEPTION 'REFUSED: issuance_without_an_operation_key (% chips % -> %)', NEW.amount, NEW.from_type, NEW.to_type
        USING ERRCODE = '23514',
              HINT = 'Mint through a door that keys its leg: fn_ca_mint, fn_ca_fund_club, or a declared write with fn_ca_declare_ledger(..., p_idempotency_key).';
    END IF;
  END IF;
  PERFORM public.fn_ca_register_issuance_leg(NEW.id);
  -- 2026-10-02: the house mints and burns only through a door that writes its
  -- own register row with its reason. A hand-declared system_mint has none.
  IF (NEW.from_type IN ('system_mint', 'system_burn') OR NEW.to_type IN ('system_mint', 'system_burn'))
     AND NEW.category <> 'correction'
     AND NOT EXISTS (SELECT 1 FROM public.ca_mint_ledger m
                      WHERE m.chip_ledger_id = NEW.id AND m.op_id NOT LIKE 'ledger:%') THEN
    RAISE EXCEPTION 'REFUSED: house_issuance_without_its_door (% chips % -> %)', NEW.amount, NEW.from_type, NEW.to_type
      USING ERRCODE = '23514',
            HINT = 'House funding goes through fn_ca_fund_club(club, amount, reason, key), which records its reason in ca_mint_ledger.';
  END IF;
  RETURN NULL;
END;
$function$

public.fn_ca_kill_switch_trip(p_detector.def:
CREATE OR REPLACE FUNCTION public.fn_ca_kill_switch_trip(p_detector text, p_amount numeric, p_detail text)
 RETURNS boolean
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  pol public.ca_kill_switch_policy%ROWTYPE;
  v_inc uuid;
  v_hour text := to_char(now(), 'YYYY-MM-DD-HH24');
  v_prev numeric;
  v_prev_at timestamptz;
  v_corr text;
  v_redef text;
  v_explained text;
  v_persists boolean := false;
  v_head text;
BEGIN
  SELECT * INTO pol FROM public.ca_kill_switch_policy WHERE detector = p_detector;
  IF NOT FOUND OR NOT pol.armed OR p_amount IS NULL OR abs(p_amount) < pol.threshold_chips THEN
    RETURN false;
  END IF;

  /* THE SWITCH ESCALATES; A PERSON FREEZES (ruling 2026-09-05, on the
     evidence in this migration's header). This function must never write
     ca_payout_freeze: tests/law/PayoutFreezeIsHumanOnly.law.test.ts pins that
     the only insert into that table is inside the human opener. */

  -- The second opinion, taken now rather than an hour from now.
  IF p_detector = 'fn_ca_supply_snapshot' THEN
    SELECT s.unexplained, s.taken_at INTO v_prev, v_prev_at
      FROM public.ca_supply_snapshots s
     WHERE s.unexplained IS NOT NULL
       AND s.basis_version IS NOT DISTINCT FROM
           (SELECT latest.basis_version FROM public.ca_supply_snapshots latest
             ORDER BY latest.taken_at DESC LIMIT 1)
     ORDER BY s.taken_at DESC OFFSET 1 LIMIT 1;
    v_persists := v_prev IS NOT NULL AND abs(v_prev) > pol.threshold_chips / 4 AND sign(v_prev) = sign(p_amount);
  END IF;

  SELECT string_agg(m.op_id, ', ') INTO v_corr
    FROM public.ca_mint_ledger m
   WHERE m.op_id LIKE 'register-opening-baseline-correction:%'
     AND m.created_at > COALESCE(v_prev_at, now() - interval '2 hours');

  /* A migration that re-created the meter itself, named exactly. The guard
     watch is the backstop for a change no migration explains: it captures a
     new hash within the hour, so it errs toward "explained" for at most one
     hour after a real redefinition - which is exactly the hour the false
     alarms live in. Neither suppresses the incident; both name it. */
  SELECT string_agg(m.version || ' ' || m.name, ', ') INTO v_redef
    FROM supabase_migrations.schema_migrations m
   WHERE m.version >= to_char(COALESCE(v_prev_at, now() - interval '2 hours') AT TIME ZONE 'UTC', 'YYYYMMDDHH24MISS')
     AND m.statements[1] LIKE '%' || p_detector || '%';
  IF v_redef IS NULL THEN
    SELECT string_agg(DISTINCT 'the guard watch saw ' || h.proname || ' change', ', ') INTO v_redef
      FROM public.ca_guard_def_history h
     WHERE h.captured_at > COALESCE(v_prev_at, now() - interval '2 hours')
       AND h.proname = p_detector;
  END IF;

  v_explained := NULLIF(concat_ws('; ',
    CASE WHEN v_corr IS NOT NULL THEN 'a labelled register correction in the window (' || v_corr || ')' END,
    CASE WHEN v_redef IS NOT NULL THEN 'the meter''s own definition changed in the window (' || v_redef || ')' END), '');

  v_head := CASE
    WHEN v_explained IS NOT NULL THEN 'EXPLAINED: ' || v_explained || '. Read it before you freeze anything: a meter that has just changed definition reads like a leak and is not one.'
    WHEN v_persists THEN 'CONFIRMED: the previous reading agreed in sign (' || round(COALESCE(v_prev, 0), 2) || ' at ' || COALESCE(v_prev_at::text, 'n/a') || ') and nothing in the window explains it. A leak persists; an oscillation flips.'
    ELSE 'UNCONFIRMED: one reading over the threshold, nothing in the window explains it, and the previous reading did not agree. Take the next reading before you freeze.'
  END;

  v_inc := public.fn_ca_raise_drift_incident(
    'fn_ca_kill_switch_trip', 'ledger_imbalance',
    CASE WHEN v_explained IS NOT NULL THEN 'warning' ELSE 'critical' END,
    'kill-switch:' || p_detector || ':' || v_hour,
    round(p_amount, 2), NULL, NULL, 'ledger', 'ca_kill_switch_policy', NULL,
    'fade0000-0000-0000-0000-000000000001', NULL, NULL, NULL, NULL, NULL, NULL, NULL,
    format('KILL SWITCH THRESHOLD CROSSED by %s: %s (threshold %s). %s Payouts are NOT frozen: open the freeze yourself with fn_ca_open_payout_freeze if this is real.',
           p_detector, p_detail, pol.threshold_chips, v_head),
    false,
    jsonb_build_object('detector', p_detector, 'amount', round(p_amount, 2), 'threshold', pol.threshold_chips,
                       'freeze', 'human only', 'verdict', split_part(v_head, ':', 1),
                       'previous_reading', v_prev, 'previous_at', v_prev_at,
                       'explained_by', v_explained, 'persists', v_persists));

  IF v_inc IS NOT NULL AND v_explained IS NULL THEN
    PERFORM public.fn_ca_incident_notify(v_inc, 'escalated',
      format('KILL SWITCH: %s read %s. %s', p_detector, round(p_amount, 2), split_part(v_head, '.', 1)), true);
  END IF;

  PERFORM public.fn_raise_server_financial_alert(
    CASE WHEN v_explained IS NOT NULL THEN 'warning' ELSE 'critical' END, 'ca_kill_switch',
    format('KILL SWITCH THRESHOLD CROSSED by %s: %s. %s', p_detector, p_detail, v_head),
    jsonb_build_object('detector', p_detector, 'amount', round(p_amount, 2), 'threshold', pol.threshold_chips,
                       'verdict', split_part(v_head, ':', 1), 'explained_by', v_explained),
    'kill-switch:' || p_detector || ':' || v_hour);
  RETURN true;
EXCEPTION WHEN OTHERS THEN
  BEGIN
    PERFORM public.fn_raise_server_financial_alert('critical', 'ca_kill_switch',
      format('KILL SWITCH by %s could not complete its paging: %s', p_detector, SQLERRM),
      jsonb_build_object('detector', p_detector), 'kill-switch-error:' || v_hour);
  EXCEPTION WHEN OTHERS THEN NULL; END;
  RETURN true;
END;
$function$

public.fn_ca_launch_accounting_actor(p_c.def:
CREATE OR REPLACE FUNCTION public.fn_ca_launch_accounting_actor(p_club_id uuid)
 RETURNS boolean
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
AS $function$
DECLARE v_operation uuid;
BEGIN
 IF public.fn_caller_is_engine() IS NOT TRUE OR public.fn_platform_frozen() IS NOT TRUE THEN RETURN false; END IF;
 v_operation:=NULLIF(current_setting('app.launch_reset_operation',true),'')::uuid;
 RETURN EXISTS(SELECT 1 FROM public.ca_launch_reset_operations o WHERE o.operation_id=v_operation
   AND o.state IN('captured','executed') AND p_club_id=ANY(o.scoped_club_ids));
EXCEPTION WHEN invalid_text_representation THEN RETURN false;
END $function$

public.fn_ca_launch_accounting_invoice_t.def:
CREATE OR REPLACE FUNCTION public.fn_ca_launch_accounting_invoice_transition(p_old jsonb, p_new jsonb)
 RETURNS boolean
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
AS $function$
DECLARE v_operation uuid;v_state text;v_before jsonb;
BEGIN
 IF NOT public.fn_ca_launch_accounting_actor((p_old->>'club_id')::uuid) THEN RETURN false; END IF;
 v_operation:=NULLIF(current_setting('app.launch_reset_operation',true),'')::uuid;
 SELECT o.state INTO v_state FROM public.ca_launch_reset_operations o WHERE o.operation_id=v_operation;
 SELECT a.before_image INTO v_before FROM public.ca_launch_accounting_archives a
  WHERE a.operation_id=v_operation AND a.relation_name='settlement_invoices' AND a.before_image->>'id'=p_old->>'id';
 IF v_before IS NULL OR (p_old-ARRAY['status','updated_at']) IS DISTINCT FROM (p_new-ARRAY['status','updated_at']) THEN RETURN false; END IF;
 RETURN (v_state='captured' AND v_before=p_old AND p_old->>'status' IN('pending','generated','overdue','disputed') AND p_new->>'status'='cancelled')
  OR (v_state='executed' AND p_old->>'status'='cancelled' AND p_new=v_before);
END $function$

public.fn_ca_launch_reporting_fee_credit.def:
CREATE OR REPLACE FUNCTION public.fn_ca_launch_reporting_fee_credit(p_club uuid, p_record uuid, p_at timestamp with time zone, p_metadata jsonb, p_amount numeric, p_legacy numeric)
 RETURNS numeric
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
AS $function$
DECLARE c timestamptz;v_credit numeric;v_total numeric;v_floors numeric;v_cents bigint;v_manifest jsonb;
BEGIN
 c:=public.fn_ca_launch_accounting_cutoff('club',p_club);
 IF c IS NULL THEN RETURN p_legacy; END IF;
 IF public.fn_ca_launch_accounting_accepts(p_club,p_at) IS NOT TRUE THEN RETURN 0; END IF;
 IF EXISTS(SELECT 1 FROM public.accounting_tournament_fee_sources f WHERE f.rake_record_id=p_record) THEN
  SELECT COALESCE(sum(f.rake_credit),0) INTO v_credit FROM public.accounting_tournament_fee_sources f WHERE f.rake_record_id=p_record AND f.club_id=p_club AND public.fn_ca_launch_accounting_accepts(p_club,f.charged_at);
  RETURN v_credit;
 END IF;
 v_manifest:=p_metadata->'accounting_fee_source'->'contributors';
 IF p_metadata->>'accounting_source_version' IS DISTINCT FROM '2' OR jsonb_typeof(v_manifest) IS DISTINCT FROM 'array' OR jsonb_array_length(v_manifest)=0 THEN RETURN 0; END IF;
 -- This is the original producer's largest-remainder allocation, read-only; its financial transaction still validates every contributor.
 v_cents:=(p_amount*100)::bigint;
 SELECT sum((x->>'weight')::numeric) INTO v_total FROM jsonb_array_elements(v_manifest)x;
 IF v_total IS NULL OR v_total<=0 THEN RETURN 0; END IF;
 SELECT sum(floor(v_cents*(x->>'weight')::numeric/v_total)) INTO v_floors FROM jsonb_array_elements(v_manifest)x;
 SELECT COALESCE(sum(cents)/100.0,0) INTO v_credit FROM (
  SELECT x,floor(v_cents*(x->>'weight')::numeric/v_total)+CASE WHEN row_number() OVER(ORDER BY v_cents*(x->>'weight')::numeric/v_total-floor(v_cents*(x->>'weight')::numeric/v_total) DESC,x->>'player_id')<=v_cents-v_floors THEN 1 ELSE 0 END cents FROM jsonb_array_elements(v_manifest)x
 )q WHERE (x->>'club_id')::uuid=p_club AND public.fn_ca_launch_accounting_accepts(p_club,(x->>'charged_at')::timestamptz);
 RETURN v_credit;
END $function$

public.fn_ca_launch_reporting_wallet_acc.def:
CREATE OR REPLACE FUNCTION public.fn_ca_launch_reporting_wallet_accepts(p_club uuid, p_at timestamp with time zone, p_category text, p_tournament uuid, p_user uuid)
 RETURNS boolean
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
AS $function$
BEGIN
 IF public.fn_ca_launch_accounting_cutoff('club',p_club) IS NULL THEN RETURN true; END IF;
 IF public.fn_ca_launch_accounting_accepts(p_club,p_at) IS NOT TRUE THEN RETURN false; END IF;
 IF p_tournament IS NOT NULL AND p_category IN('prize','bounty','prize_reversal','refund') THEN
  RETURN EXISTS(SELECT 1 FROM public.tournaments t WHERE t.id=p_tournament AND public.fn_ca_launch_accounting_accepts(p_club,t.started_at)) OR (p_category='refund' AND EXISTS(SELECT 1 FROM public.tournament_players tp WHERE tp.tournament_id=p_tournament AND tp.user_id=p_user AND public.fn_ca_launch_accounting_accepts(p_club,tp.registered_at)));
 END IF;
 RETURN true;
END $function$

public.fn_ca_ledger_day_manifest(p_day d.def:
CREATE OR REPLACE FUNCTION public.fn_ca_ledger_day_manifest(p_day date DEFAULT (CURRENT_DATE - 1), p_restate_reason text DEFAULT NULL::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
 SET "TimeZone" TO 'UTC'
AS $function$
DECLARE v_count bigint; v_net numeric; v_first bigint; v_last bigint; v_sha text; v_prior text; v_prior_rows bigint;
BEGIN
  /* One index range over idx_chip_ledger_created_at: the cost is this day's
     legs, not the journal's. A day is a UTC day (SET timezone above). */
  SELECT count(*), COALESCE(sum(amount), 0), min(chain_seq), max(chain_seq),
         encode(extensions.digest(
           COALESCE(string_agg(
             id::text || '|' || amount::text || '|' || from_type || ':' || COALESCE(from_entity_id::text,'') ||
             '>' || to_type || ':' || COALESCE(to_entity_id::text,'') || '|' || category || '|' ||
             extract(epoch from created_at)::text || '|' || COALESCE(row_hash,''),
             E'\n' ORDER BY created_at, id), ''), 'sha256'), 'hex')
    INTO v_count, v_net, v_first, v_last, v_sha
    FROM public.chip_ledger
   WHERE created_at >= p_day AND created_at < p_day + 1;

  SELECT sha256, row_count INTO v_prior, v_prior_rows
    FROM public.ca_ledger_day_manifests WHERE day = p_day;

  IF v_prior IS NULL THEN
    IF v_count = 0 THEN
      /* Nothing to attest and nothing attested: not a manifest, not an error. */
      RETURN jsonb_build_object('day', p_day, 'rows', 0, 'attested', false, 'tampered', false);
    END IF;
    INSERT INTO public.ca_ledger_day_manifests
      (day, row_count, first_seq, last_seq, net_amount, sha256, last_checked_at)
    VALUES (p_day, v_count, v_first, v_last, v_net, v_sha, now())
    ON CONFLICT (day) DO NOTHING;
    RETURN jsonb_build_object('day', p_day, 'rows', v_count, 'net', v_net,
      'first_seq', v_first, 'last_seq', v_last, 'sha256', v_sha, 'tampered', false, 'restated', false);
  END IF;

  IF v_prior = v_sha THEN
    /* Read and agreed: that is a verification, so say when it happened. */
    UPDATE public.ca_ledger_day_manifests SET last_checked_at = now() WHERE day = p_day;
    RETURN jsonb_build_object('day', p_day, 'rows', v_count, 'net', v_net,
      'first_seq', v_first, 'last_seq', v_last, 'sha256', v_sha, 'tampered', false, 'restated', false);
  END IF;

  /* The stored attestation and the journal disagree. */
  IF p_restate_reason IS NULL THEN
    PERFORM public.fn_ca_raise_drift_incident(
      'fn_ca_ledger_day_manifest', 'unauthorized_adjustment', 'critical',
      'manifest-mismatch:' || p_day::text,
      0, NULL, NULL, 'ledger', 'ca_ledger_day_manifests',
      NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL,
      'the recomputed ledger manifest for ' || p_day || ' no longer matches the stored one - historical rows changed',
      false, jsonb_build_object('day', p_day, 'stored', v_prior, 'recomputed', v_sha,
                                'stored_rows', v_prior_rows, 'actual_rows', v_count));
    RETURN jsonb_build_object('day', p_day, 'tampered', true, 'stored', v_prior, 'recomputed', v_sha,
                              'stored_rows', v_prior_rows, 'actual_rows', v_count);
  END IF;

  IF v_count = 0 THEN
    /* A day that was attested cannot become a day that never happened. The
       statement that would empty it is refused whole. */
    RAISE EXCEPTION
      'refusing to restate % to zero rows (it attested % rows): an attested day cannot be emptied. Reason offered: %',
      p_day, v_prior_rows, p_restate_reason
      USING ERRCODE = 'P0403';
  END IF;

  /* Open the guard for exactly this update, in this transaction only. The
     guard writes the restatement row itself, old value kept. */
  PERFORM set_config('app.manifest_restatement', p_restate_reason, true);
  UPDATE public.ca_ledger_day_manifests
     SET row_count = v_count, first_seq = v_first, last_seq = v_last,
         net_amount = v_net, sha256 = v_sha, last_checked_at = now()
   WHERE day = p_day;
  PERFORM set_config('app.manifest_restatement', '', true);

  RETURN jsonb_build_object('day', p_day, 'rows', v_count, 'net', v_net,
    'first_seq', v_first, 'last_seq', v_last, 'sha256', v_sha, 'tampered', false,
    'restated', true, 'old_sha256', v_prior, 'old_rows', v_prior_rows, 'reason', p_restate_reason);
END $function$

public.fn_ca_ledger_declaration_restore(.def:
CREATE OR REPLACE FUNCTION public.fn_ca_ledger_declaration_restore(p_saved jsonb)
 RETURNS void
 LANGUAGE plpgsql
 SET search_path TO 'public'
AS $function$
DECLARE
  r record;
BEGIN
  FOR r IN SELECT key, value FROM jsonb_each_text(COALESCE(p_saved, '{}'::jsonb)) LOOP
    IF r.key !~ '^app\.ledger_(category|counterparty|counterparty_entity|counterparty_label|autoskip_[a-z_]+)$' THEN
      RAISE EXCEPTION 'fn_ca_ledger_declaration_restore: % is not a ledger declaration setting', r.key;
    END IF;
    PERFORM set_config(r.key, COALESCE(r.value, ''), true);
  END LOOP;
END $function$

public.fn_ca_ledger_declaration_save(p_a.def:
CREATE OR REPLACE FUNCTION public.fn_ca_ledger_declaration_save(p_autoskip_tables text[] DEFAULT NULL::text[])
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE
 SET search_path TO 'public'
AS $function$
DECLARE
  v jsonb;
  t text;
BEGIN
  v := jsonb_build_object(
    'app.ledger_category',            COALESCE(current_setting('app.ledger_category', true), ''),
    'app.ledger_counterparty',        COALESCE(current_setting('app.ledger_counterparty', true), ''),
    'app.ledger_counterparty_entity', COALESCE(current_setting('app.ledger_counterparty_entity', true), ''),
    'app.ledger_counterparty_label',  COALESCE(current_setting('app.ledger_counterparty_label', true), ''));
  IF p_autoskip_tables IS NOT NULL THEN
    FOREACH t IN ARRAY p_autoskip_tables LOOP
      IF t !~ '^[a-z_]+$' THEN
        RAISE EXCEPTION 'fn_ca_ledger_declaration_save: bad autoskip table name %', t;
      END IF;
      v := v || jsonb_build_object('app.ledger_autoskip_' || t,
                                   COALESCE(current_setting('app.ledger_autoskip_' || t, true), ''));
    END LOOP;
  END IF;
  RETURN v;
END $function$

public.fn_ca_ledger_refusal_record(p_ref.def:
CREATE OR REPLACE FUNCTION public.fn_ca_ledger_refusal_record(p_refusal jsonb)
 RETURNS boolean
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
AS $function$
DECLARE
  v_no      bigint;
  v_conn    text := 'ca_ledger_refusal_' || pg_backend_pid();
  v_info    text;
  v_id      bigint;
  v_claims  jsonb;
  v_path    text;
  v_q       text;
  v_src     text;
  v_payload jsonb;
BEGIN
  /* 1. COUNT IT FIRST. nextval survives the rollback that follows, so the
        refusal is counted even if nothing below works. */
  BEGIN
    v_no := nextval('public.ca_ledger_invariant_refusal_counter');
  EXCEPTION WHEN OTHERS THEN
    v_no := NULL;
  END;

  /* 2. Say who refused it. Inside SECURITY DEFINER current_user is the owner,
        so the caller is read from the role setting (PostgREST's SET ROLE),
        the session user, the JWT claims and the request path. */
  BEGIN
    v_path := NULLIF(current_setting('request.path', true), '');
    v_q := left(current_query(), 2000);
    /* The check is deferred to COMMIT, so for an explicit transaction the
       current statement is the COMMIT itself; the statement that first wrote
       the money (kept by the tally) then names the caller instead. */
    v_src := CASE WHEN v_q ~* '^\s*(commit|end)\y'
                  THEN COALESCE(NULLIF(p_refusal ->> 'first_writer', ''), v_q)
                  ELSE v_q END;
    BEGIN
      v_claims := NULLIF(current_setting('request.jwt.claims', true), '')::jsonb;
    EXCEPTION WHEN OTHERS THEN
      v_claims := NULL;
    END;
    v_payload := COALESCE(p_refusal, '{}'::jsonb) || jsonb_build_object(
      'counter_no',       v_no,
      'refused_at',       clock_timestamp(),
      'txid',             pg_current_xact_id()::text,
      'rpc',              COALESCE(
                            substring(v_path from '^/rpc/([A-Za-z0-9_]+)'),
                            CASE WHEN v_path IS NOT NULL
                                 THEN COALESCE(NULLIF(current_setting('request.method', true), ''), '?') || ' ' || v_path END,
                            substring(v_src from '(?i)(?:select|perform|call)\s+(?:\*\s+from\s+)?(?:"?[a-z_][a-z0-9_]*"?\.)?"?([a-z_][a-z0-9_]*)"?\s*\('),
                            (SELECT lower(regexp_replace(m[1], '\s+', ' ', 'g')) || ' ' || m[2]
                               FROM regexp_match(v_src, '(?i)^\s*(update|insert\s+into|delete\s+from)\s+([a-z0-9_."]+)') m),
                            'unknown'),
      'db_role',          COALESCE(NULLIF(current_setting('role', true), 'none'), session_user::text),
      'session_role',     session_user::text,
      'application_name', current_setting('application_name', true),
      'jwt_role',         v_claims ->> 'role',
      'jwt_sub',          v_claims ->> 'sub',
      'query',            v_q,
      'backend_pid',      pg_backend_pid());
  EXCEPTION WHEN OTHERS THEN
    v_payload := COALESCE(p_refusal, '{}'::jsonb) || jsonb_build_object('counter_no', v_no, 'refused_at', clock_timestamp());
  END;

  /* 3. WRITE IT WHERE THE ROLLBACK CANNOT REACH: the recorder's own
        connection, which commits each statement on its own. */
  BEGIN
    SELECT s.decrypted_secret INTO v_info
      FROM vault.decrypted_secrets s
     WHERE s.name = 'ca_ledger_refusal_recorder_conninfo'
     LIMIT 1;
    IF v_info IS NULL THEN
      RAISE WARNING 'LEDGER_REFUSAL_UNRECORDED counter=% reason=no recorder connection string in vault', v_no;
      RETURN false;
    END IF;

    IF v_conn = ANY (COALESCE(extensions.dblink_get_connections(), ARRAY[]::text[])) THEN
      PERFORM extensions.dblink_disconnect(v_conn);
    END IF;
    PERFORM extensions.dblink_connect(v_conn, v_info);

    SELECT t.id INTO v_id
      FROM extensions.dblink(v_conn, format('SELECT public.fn_ca_ledger_refusal_file(%L::jsonb)', v_payload::text)) AS t(id bigint);

    /* 4. The incident, in its own remote statement, after the record has
          committed: a slow board can cost the incident, never the record. */
    BEGIN
      PERFORM 1 FROM extensions.dblink(v_conn, format('SELECT public.fn_ca_ledger_refusal_raise(%s)', v_id)) AS t(incident uuid);
    EXCEPTION WHEN OTHERS THEN
      RAISE WARNING 'LEDGER_REFUSAL_RECORDED_NOT_RAISED refusal=% counter=% reason=%', v_id, v_no, SQLERRM;
    END;

    PERFORM extensions.dblink_disconnect(v_conn);
    RETURN true;
  EXCEPTION WHEN OTHERS THEN
    BEGIN
      IF v_conn = ANY (COALESCE(extensions.dblink_get_connections(), ARRAY[]::text[])) THEN
        PERFORM extensions.dblink_disconnect(v_conn);
      END IF;
    EXCEPTION WHEN OTHERS THEN
      NULL;
    END;
    RAISE WARNING 'LEDGER_REFUSAL_UNRECORDED counter=% reason=%', v_no, SQLERRM;
    RETURN false;
  END;
END;
$function$

public.fn_ca_ledger_tally_add(p_key text.def:
CREATE OR REPLACE FUNCTION public.fn_ca_ledger_tally_add(p_key text, p_side text, p_delta numeric)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
AS $function$
DECLARE
  t jsonb;
  e jsonb;
  v numeric;
BEGIN
  /* The tally lives in a transaction-local setting, so it is undone with the
     transaction and with any subtransaction (a plpgsql EXCEPTION block) that
     rolls back the write it counted. A SET clause on a function restores only
     the variables it names at exit (measured on production 2026-10-01: a
     set_config(..., true) made inside a SET search_path function was still
     set after it returned), so pinning search_path here does not lose the
     tally. Every object is named by schema regardless. */
  IF p_key IS NULL OR p_delta IS NULL OR round(p_delta, 2) = 0 THEN
    RETURN;
  END IF;
  t := COALESCE(NULLIF(current_setting('ca.ledger_tally', true), '')::jsonb, '{}'::jsonb);
  e := COALESCE(t -> p_key, '{"b":0,"l":0}'::jsonb);
  IF NOT (e ? 'q') THEN
    -- The top-level statement that first touched this account in this
    -- transaction: the name of the door, for the refusal and the finding
    -- (CLAUDE.md 10.86: a refusal names its writer).
    e := e || jsonb_build_object('q', left(COALESCE(current_query(), ''), 300));
  END IF;
  v := round(COALESCE((e ->> p_side)::numeric, 0) + p_delta, 2);
  e := jsonb_set(e, ARRAY[p_side], to_jsonb(v), true);
  t := t || jsonb_build_object(p_key, e);
  PERFORM set_config('ca.ledger_tally', t::text, true);
  PERFORM set_config('ca.ledger_tally_ver',
                     (COALESCE(NULLIF(current_setting('ca.ledger_tally_ver', true), ''), '0')::bigint + 1)::text,
                     true);
END;
$function$

public.fn_ca_ledger_tally_key(p_type tex.def:
CREATE OR REPLACE FUNCTION public.fn_ca_ledger_tally_key(p_type text, p_entity uuid, p_club uuid)
 RETURNS text
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
AS $function$
DECLARE
  v_union uuid;
  v_club uuid;
BEGIN
  /* The account a ledger side belongs to, in the covered set, or NULL when the
     side is not a chip store. The conventions are the ones every live writer
     already meets (measured 2026-10-01, seven days, 1,946,078 legs; extended
     2026-10-02 over the same seven days): a player_wallet leg names the user
     and the club; a union leg names the wallet row (fn_ca_autoledger) or the
     union (a declaring payer); a bbj_pool leg names the pool row; a
     table_stack leg names the table; a promo or agent leg names its holder
     (user, club or union); a club wallet or insurance leg names the
     club_wallets row or the club; a spin_reserve leg names the pool (10 of 10
     entities in seven days); a prize or bounty liability leg names the
     tournament (20,169 of 20,169 entities in a day, every one with an escrow
     row); a ticket escrow leg names the ticket, and every issued ticket is one
     float (fn_ca_ticket_escrow_float). */
  CASE p_type
    WHEN 'player_wallet' THEN
      RETURN 'player_wallet:' || COALESCE(p_entity::text, 'null') || ':' || COALESCE(p_club::text, 'null');
    WHEN 'club_treasury' THEN
      RETURN 'club_treasury:' || COALESCE(p_entity::text, 'null');
    WHEN 'table_stack' THEN
      IF p_entity IS NULL OR public.fn_ca_felt_counts_table(p_entity) THEN
        RETURN 'table_stack';
      END IF;
      RETURN NULL;  -- a tournament or Diamond table is not on the cash felt
    WHEN 'union_bank', 'union_wallet' THEN
      SELECT w.union_id INTO v_union FROM public.union_wallets w WHERE w.id = p_entity;
      RETURN p_type || ':' || COALESCE(v_union, p_entity)::text;
    WHEN 'bbj_pool' THEN
      RETURN 'bbj_pool:' || COALESCE(p_entity::text, 'null');
    -- 2026-10-02: every remaining chip store
    WHEN 'agent_wallet' THEN
      RETURN p_type || ':' || COALESCE(p_entity::text, 'null') || ':' || COALESCE(p_club::text, 'null');
    WHEN 'promo_wallet' THEN
      -- Club and union promo banks retain their original global identities.
      -- A user's promo account is scoped to the club that holds its balance.
      IF p_entity IS NULL OR EXISTS(SELECT 1 FROM public.clubs WHERE id=p_entity)
        OR EXISTS(SELECT 1 FROM public.unions WHERE id=p_entity) THEN
        RETURN p_type || ':' || COALESCE(p_entity::text, 'null');
      END IF;
      RETURN p_type || ':' || p_entity::text || ':' || COALESCE(p_club::text, 'null');
    WHEN 'club_wallet', 'insurance_bank' THEN
      SELECT cw.club_id INTO v_club FROM public.club_wallets cw WHERE cw.id = p_entity;
      RETURN p_type || ':' || COALESCE(COALESCE(v_club, p_entity)::text, 'null');
    WHEN 'spin_reserve' THEN
      RETURN 'spin_reserve:' || COALESCE(p_entity::text, 'null');
    WHEN 'prize_liability', 'bounty_liability' THEN
      IF p_entity IS NOT NULL AND NOT public.fn_ca_tournament_counts(p_entity) THEN
        RETURN NULL;  -- a Diamond event's liability is Diamonds in custody
      END IF;
      RETURN 'tournament_liability:' || COALESCE(p_entity::text, 'null');
    WHEN 'escrow' THEN
      RETURN 'ticket_escrow';
    WHEN 'opening_setup', 'leaderboard_round' THEN
      RETURN p_type || ':' || COALESCE(p_entity::text, 'null');
    ELSE
      RETURN NULL;
  END CASE;
END;
$function$

public.fn_ca_legacy_round3_wallet_receip.def:
CREATE OR REPLACE FUNCTION public.fn_ca_legacy_round3_wallet_receipt()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE v_period record; v_legacy numeric;
BEGIN
 IF NEW.category='rakeback' AND NEW.description='Round 3: agent -> player rakeback [club wallet]' THEN
  IF NEW.related_entity_id IS NULL OR NOT EXISTS(SELECT 1 FROM rakeback_period_payouts p
   JOIN rakeback_periods rp ON rp.id=p.rakeback_period_id
   WHERE p.id=NEW.related_entity_id AND p.user_id=NEW.user_id AND p.club_id=rp.club_id AND p.user_id=rp.user_id
    AND p.payout_amount=NEW.amount AND p.status='paid' AND p.wallet_transaction_id IS NULL AND rp.status='pending')
  THEN RAISE EXCEPTION 'Round3 requires the unique unpaid period receipt' USING ERRCODE='23514'; END IF;
 END IF;
 IF NEW.category='rakeback' AND NEW.related_entity_id IS NOT NULL THEN
  SELECT rp.*,receipt.payout_amount AS receipt_amount,receipt.user_id AS receipt_user INTO v_period
  FROM rakeback_period_payouts receipt JOIN rakeback_periods rp ON rp.id=receipt.rakeback_period_id
  WHERE receipt.id=NEW.related_entity_id;
  IF FOUND AND (v_period.period_end+1)::timestamp AT TIME ZONE 'America/Los_Angeles' > statement_timestamp() THEN
   RAISE EXCEPTION 'Legacy period payment requires a closed earning period' USING ERRCODE='55000';
  END IF;

 END IF;
 RETURN NEW;
END $function$

public.fn_ca_mint(p_asset text, p_destin.def:
CREATE OR REPLACE FUNCTION public.fn_ca_mint(p_asset text, p_destination text, p_target_id uuid, p_amount numeric, p_reason text, p_op_id text, p_class text DEFAULT 'admin'::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE
  c_house constant uuid := '00000000-0000-0000-0000-00000000d1a0';
  v_actor uuid := auth.uid();
  v_admin boolean := false;
  v_asset text := lower(btrim(COALESCE(p_asset, '')));
  v_dest  text := lower(btrim(COALESCE(p_destination, '')));
  v_reason text := btrim(COALESCE(p_reason, ''));
  v_class text := lower(btrim(COALESCE(p_class, 'admin')));
  v_holder uuid;
  v_prior jsonb; v_before numeric; v_after numeric; v_label text;
  v_supply numeric; v_chip_id uuid; v_dia_id uuid; v_actorlb text; v_result jsonb;
  v_pol public.ca_mint_policy%ROWTYPE;
  v_cap numeric; v_roll numeric; v_24h numeric;
BEGIN
  -- The trigger door (2026-09-08, DIAMOND-RULINGS 17 / roadmap 1.3): handle_new_user and the
  -- other seeders fire inside a trigger owned by the database itself, where auth.role() is
  -- NULL. The database's own code may mint; a browser never reaches this branch because a
  -- SECURITY DEFINER trigger runs as the owner and a client session is never at depth > 0.
  IF COALESCE(auth.role(), '') <> 'service_role'
     AND NOT (pg_trigger_depth() > 0
              AND current_user IN ('postgres', 'supabase_admin', 'supabase_auth_admin')) THEN
    SELECT EXISTS (SELECT 1 FROM public.profiles p
                    WHERE p.id = v_actor AND p.role IN ('admin', 'god')) INTO v_admin;
    IF NOT v_admin THEN
      RETURN jsonb_build_object('ok', false, 'reason', 'the_mint_is_admin_only');
    END IF;
  END IF;

  IF v_asset NOT IN ('chips', 'diamonds') THEN
    RETURN jsonb_build_object('ok', false, 'reason', 'asset_must_be_chips_or_diamonds');
  END IF;
  IF v_asset = 'chips' AND v_dest NOT IN ('club', 'union') THEN
    RETURN jsonb_build_object('ok', false, 'reason', 'chips_are_issued_to_a_club_or_union_wallet_only');
  END IF;
  IF v_asset = 'diamonds' AND v_dest NOT IN ('player', 'house') THEN
    RETURN jsonb_build_object('ok', false, 'reason', 'diamonds_are_issued_to_a_player_or_to_the_house_only');
  END IF;
  -- The foundation's issuance_class list (diamond_transactions_issuance_class_chk).
  -- Recorded on the diamond journal row; carried but unused for chips, which have
  -- their own ledger.
  IF v_class NOT IN ('purchased', 'promotional', 'earned', 'transferred', 'seeded',
                     'refund', 'spend', 'bridge', 'deletion', 'admin', 'arena',
                     'house', 'unknown') THEN
    RETURN jsonb_build_object('ok', false, 'reason', 'unknown_issuance_class', 'class', v_class);
  END IF;
  IF v_asset = 'diamonds' AND v_dest = 'house' THEN
    IF p_target_id IS NOT NULL AND p_target_id <> c_house THEN
      RETURN jsonb_build_object('ok', false, 'reason', 'the_house_target_is_the_house_sentinel_or_null');
    END IF;
  ELSIF p_target_id IS NULL THEN
    RETURN jsonb_build_object('ok', false, 'reason', 'target_required');
  END IF;
  IF p_amount IS NULL OR p_amount <= 0 OR p_amount <> round(p_amount, 2) THEN
    RETURN jsonb_build_object('ok', false, 'reason', 'amount_must_be_positive_to_two_decimals');
  END IF;
  IF v_asset = 'diamonds' AND p_amount <> round(p_amount, 0) THEN
    RETURN jsonb_build_object('ok', false, 'reason', 'diamonds_are_whole_numbers');
  END IF;
  -- Kill switch (standard 3.4 layer 6, review D11): a human-opened diamond_issuance freeze
  -- refuses diamond minting until it is cleared. Burns and chips are untouched.
  IF v_asset = 'diamonds' AND EXISTS (SELECT 1 FROM public.ca_payout_freeze f
                                        WHERE f.scope = 'diamond_issuance' AND f.cleared_at IS NULL) THEN
    RETURN jsonb_build_object('ok', false, 'reason', 'diamond_issuance_frozen');
  END IF;
  -- THE POLICY (ca_mint_policy): a per-operation cap and a rolling 24-hour
  -- ceiling, both refused here with a reason the operator can read, and
  -- refused again at commit by the constraint trigger for chips whatever the
  -- door. 24h issuance is read from the register with the advisory lock held
  -- below, so two operators cannot both fit under the ceiling at once.
  SELECT * INTO v_pol FROM public.ca_mint_policy WHERE id = 1;
  v_cap  := CASE WHEN v_asset = 'chips' THEN v_pol.per_operation_cap_chips ELSE v_pol.per_operation_cap_diamonds END;
  v_roll := CASE WHEN v_asset = 'chips' THEN v_pol.rolling_24h_cap_chips ELSE v_pol.rolling_24h_cap_diamonds END;
  IF p_amount > v_cap THEN
    RETURN jsonb_build_object('ok', false, 'reason', 'amount_over_the_single_mint_cap',
                              'cap', v_cap, 'requested', p_amount);
  END IF;
  IF length(v_reason) < 10 THEN
    RETURN jsonb_build_object('ok', false, 'reason', 'issuance_needs_a_real_reason');
  END IF;
  IF COALESCE(btrim(p_op_id), '') = '' THEN
    RETURN jsonb_build_object('ok', false, 'reason', 'idempotency_key_required');
  END IF;

  SELECT result INTO v_prior FROM public.ca_op_claims
   WHERE op_id = p_op_id AND fn_name = 'fn_ca_mint';
  IF FOUND AND v_prior IS NOT NULL THEN
    RETURN v_prior || jsonb_build_object('replayed', true);
  ELSIF FOUND THEN
    DELETE FROM public.ca_op_claims WHERE op_id = p_op_id AND fn_name = 'fn_ca_mint';
  END IF;
  INSERT INTO public.ca_op_claims (op_id, fn_name, claimed_by)
  VALUES (p_op_id, 'fn_ca_mint', v_actor);

  PERFORM pg_advisory_xact_lock(hashtext('ca_mint_ledger:' || v_asset));

  v_24h := public.fn_ca_mint_issued_24h(v_asset) + p_amount;
  IF v_24h > v_roll AND NOT public.fn_ca_launch_opening_authorized(p_op_id,v_asset,v_dest,p_target_id,p_amount) THEN
    RETURN public.fn_ca_release_claim('fn_ca_mint', p_op_id,
             jsonb_build_object('ok', false, 'reason', 'over_the_rolling_24h_issuance_ceiling',
                              'ceiling', v_roll, 'issued_24h', v_24h - p_amount, 'requested', p_amount));
  END IF;

  IF v_asset = 'diamonds' THEN
    IF v_dest = 'house' THEN
      INSERT INTO public.ca_diamond_house (id, balance)
      VALUES (1, 0) ON CONFLICT (id) DO NOTHING;
      SELECT COALESCE(balance, 0) INTO v_before
        FROM public.ca_diamond_house WHERE id = 1 FOR UPDATE;
      UPDATE public.ca_diamond_house
         SET balance = COALESCE(balance, 0) + p_amount, updated_at = now()
       WHERE id = 1 RETURNING balance INTO v_after;
      v_label  := 'the house';
      v_holder := c_house;
      -- No diamond_transactions row: that journal is keyed by a user (two FKs to
      -- auth.users and profiles) and the house is not one. ca_mint_ledger is the
      -- record of a house-side issuance.
    ELSE
      SELECT COALESCE(diamonds, 0), COALESCE(NULLIF(btrim(username), ''), full_name, id::text)
        INTO v_before, v_label FROM public.profiles WHERE id = p_target_id FOR UPDATE;
      IF NOT FOUND THEN
        RETURN public.fn_ca_release_claim('fn_ca_mint', p_op_id,
                 jsonb_build_object('ok', false, 'reason', 'player_not_found'));
      END IF;
      UPDATE public.profiles SET diamonds = COALESCE(diamonds, 0) + p_amount
       WHERE id = p_target_id RETURNING diamonds INTO v_after;
      -- The op id is the journal reference (DR4: a credit carries its reference), so the earn
      -- ledger files a promotional mint under its engine by prefix (signup: -> signup).
      INSERT INTO public.diamond_transactions
        (user_id, type, transaction_type, amount, balance_after, description, source,
         metadata, counterparty, issuance_class, reference_id)
      VALUES (p_target_id, 'earn', 'mint', p_amount, v_after,
              'The Mint: ' || v_reason, 'the_mint',
              jsonb_build_object('minted_by', v_actor, 'op_id', p_op_id),
              'issuance', v_class, p_op_id)
      RETURNING id INTO v_dia_id;
      v_holder := p_target_id;
    END IF;
  ELSE
    -- The leg is declared WITH A KEY and found by that key: never by shape.
    PERFORM public.fn_ca_declare_ledger('mint', 'issuance_reserve', NULL, NULL, 'mint:' || p_op_id, NULL);
    IF v_dest = 'club' THEN
      SELECT COALESCE(chip_treasury, 0), name INTO v_before, v_label
        FROM public.clubs WHERE id = p_target_id FOR UPDATE;
      IF NOT FOUND THEN
        RETURN public.fn_ca_release_claim('fn_ca_mint', p_op_id,
                 jsonb_build_object('ok', false, 'reason', 'club_not_found'));
      END IF;
      UPDATE public.clubs SET chip_treasury = COALESCE(chip_treasury, 0) + p_amount
       WHERE id = p_target_id RETURNING chip_treasury INTO v_after;
      INSERT INTO public.chip_transactions
        (club_id, from_user_id, to_user_id, amount, transaction_type, notes, balance_after)
      VALUES (p_target_id, v_actor, NULL, p_amount, 'treasury_mint',
              'The Mint: ' || v_reason, v_after);
    ELSE
      SELECT name INTO v_label FROM public.unions WHERE id = p_target_id;
      IF v_label IS NULL THEN
        RETURN public.fn_ca_release_claim('fn_ca_mint', p_op_id,
                 jsonb_build_object('ok', false, 'reason', 'union_not_found'));
      END IF;
      INSERT INTO public.union_wallets (union_id, created_at, updated_at)
      VALUES (p_target_id, now(), now()) ON CONFLICT (union_id) DO NOTHING;
      SELECT COALESCE(chip_balance, 0) INTO v_before
        FROM public.union_wallets WHERE union_id = p_target_id FOR UPDATE;
      UPDATE public.union_wallets
         SET chip_balance = COALESCE(chip_balance, 0) + p_amount, updated_at = now()
       WHERE union_id = p_target_id RETURNING chip_balance INTO v_after;
    END IF;
    SELECT id INTO v_chip_id FROM public.chip_ledger WHERE idempotency_key = 'mint:' || p_op_id;
    PERFORM set_config('app.ledger_category', '', true);
    PERFORM set_config('app.ledger_counterparty', '', true);
    PERFORM set_config('app.ledger_counterparty_entity', '', true);
    PERFORM set_config('app.ledger_idempotency_key', '', true);
    IF v_chip_id IS NULL THEN
      RAISE EXCEPTION 'fn_ca_mint: the balance moved but no journal leg was written for key mint:% - refusing to register an issuance the journal does not carry', p_op_id;
    END IF;
    v_holder := p_target_id;
  END IF;

  SELECT COALESCE(SUM(CASE WHEN action = 'mint' THEN amount ELSE -amount END), 0) + p_amount
    INTO v_supply FROM public.ca_mint_ledger WHERE asset = v_asset;
  SELECT COALESCE(NULLIF(btrim(username), ''), full_name, id::text)
    INTO v_actorlb FROM public.profiles WHERE id = v_actor;

  INSERT INTO public.ca_mint_ledger
    (op_id, action, asset, holder_type, holder_id, holder_label, amount,
     balance_before, balance_after, supply_after, reason,
     performed_by, performed_by_label, chip_ledger_id, diamond_tx_id)
  VALUES
    (p_op_id, 'mint', v_asset, v_dest, v_holder, v_label, p_amount,
     v_before, v_after, v_supply, v_reason, v_actor, v_actorlb, v_chip_id, v_dia_id);

  v_result := jsonb_build_object(
    'ok', true, 'replayed', false, 'action', 'mint',
    'asset', v_asset, 'destination', v_dest, 'issuance_class', v_class,
    'target_id', v_holder, 'target_label', v_label, 'amount', p_amount,
    'balance_before', v_before, 'balance_after', v_after, 'supply_after', v_supply,
    'ledger_id', v_chip_id, 'issued_24h_after', v_24h, 'rolling_24h_cap', v_roll,
    'minted_by', v_actor, 'reason', v_reason, 'op_id', p_op_id);

  UPDATE public.ca_op_claims SET result = v_result, finalized_at = now()
   WHERE op_id = p_op_id AND fn_name = 'fn_ca_mint';

  RETURN v_result;
END;
$function$

public.fn_ca_post_correction(p_from_type.def:
CREATE OR REPLACE FUNCTION public.fn_ca_post_correction(p_from_type text, p_from_entity uuid, p_to_type text, p_to_entity uuid, p_amount numeric, p_reason text, p_incident_id uuid DEFAULT NULL::uuid, p_write_failure_id bigint DEFAULT NULL::bigint, p_club_id uuid DEFAULT NULL::uuid, p_union_id uuid DEFAULT NULL::uuid, p_metadata jsonb DEFAULT '{}'::jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_uid uuid := auth.uid();
  v_mgmt boolean := false;
  v_key text;
  v_id uuid;
  v_existing uuid;
  v_intent jsonb;
  v_prior_intent jsonb;
  v_prior_ledger uuid;
  v_expected_ref text;
  v_event_id bigint;
  v_event_detail jsonb;
BEGIN
  IF COALESCE(auth.role(), '') <> 'service_role' THEN
    SELECT EXISTS (
      SELECT 1 FROM public.ca_incident_recipients r WHERE r.user_id = v_uid AND r.active
      UNION ALL
      SELECT 1 FROM public.profiles p WHERE p.id = v_uid AND p.role IN ('admin','god')
    ) INTO v_mgmt;
    IF NOT v_mgmt THEN
      RETURN jsonb_build_object('ok', false, 'reason', 'management_only');
    END IF;
  END IF;

  IF p_amount IS NULL OR p_amount::text IN ('NaN', 'Infinity', '-Infinity')
     OR p_amount <= 0 OR p_amount <> round(p_amount, 2) THEN
    RETURN jsonb_build_object('ok', false, 'reason', 'amount_must_be_positive_cents');
  END IF;
  IF COALESCE(btrim(p_reason), '') = '' OR length(p_reason) < 20 THEN
    RETURN jsonb_build_object('ok', false, 'reason', 'a_correction_needs_a_real_reason');
  END IF;

  -- THE LINKAGE RULE: no correction without a live reference to what it fixes.
  IF p_incident_id IS NULL AND p_write_failure_id IS NULL THEN
    RETURN jsonb_build_object('ok', false, 'reason', 'linkage_required_incident_or_write_failure');
  END IF;
  IF p_incident_id IS NOT NULL
     AND NOT EXISTS (SELECT 1 FROM public.ca_drift_incidents WHERE id = p_incident_id) THEN
    RETURN jsonb_build_object('ok', false, 'reason', 'incident_not_found');
  END IF;
  IF p_write_failure_id IS NOT NULL
     AND NOT EXISTS (SELECT 1 FROM public.ca_ledger_write_failures WHERE id = p_write_failure_id) THEN
    RETURN jsonb_build_object('ok', false, 'reason', 'write_failure_not_found');
  END IF;

  v_key := 'correction:' || COALESCE('lwf:' || p_write_failure_id::text,
                                     'inc:' || p_incident_id::text);

  -- Version 1 compares full typed intent, not the truncated ledger projection.
  -- JSONB object key order / numeric scale are semantic; SQL NULL metadata is
  -- deliberately distinct from JSON null and from an explicit empty object.
  v_intent := jsonb_build_object(
    'version', 1, 'actor_uid', v_uid,
    'from_type', p_from_type, 'from_entity', p_from_entity,
    'to_type', p_to_type, 'to_entity', p_to_entity,
    'amount', p_amount, 'reason', p_reason,
    'incident_id', p_incident_id, 'write_failure_id', p_write_failure_id,
    'club_id', p_club_id, 'union_id', p_union_id,
    'metadata_sql_null', p_metadata IS NULL, 'metadata', p_metadata);

  SELECT id INTO v_existing FROM public.chip_ledger WHERE idempotency_key = v_key;
  IF v_existing IS NOT NULL THEN
    SELECT request_intent, ledger_id INTO v_prior_intent, v_prior_ledger
      FROM public.ca_correction_request_intents_v1 WHERE linkage_key = v_key;
    IF NOT FOUND THEN
      RETURN jsonb_build_object('ok', false, 'reason', 'legacy_correction_intent_unavailable');
    END IF;
    IF v_prior_ledger IS DISTINCT FROM v_existing THEN
      RAISE EXCEPTION 'correction_intent_ledger_mismatch';
    END IF;
    IF v_prior_intent IS DISTINCT FROM v_intent THEN
      RETURN jsonb_build_object('ok', false, 'reason', 'correction_intent_conflict');
    END IF;
    IF NOT EXISTS (SELECT 1 FROM public.chip_ledger l
      WHERE l.id = v_existing AND l.idempotency_key = v_key
        AND l.status IS NOT DISTINCT FROM 'posted'
        AND l.performed_by IS NOT DISTINCT FROM
          COALESCE(v_uid, '2d1cd6c3-5700-4af9-a271-d4863fdab20d'::uuid)
        AND l.from_type IS NOT DISTINCT FROM p_from_type
        AND l.from_entity_id IS NOT DISTINCT FROM p_from_entity
        AND l.to_type IS NOT DISTINCT FROM p_to_type
        AND l.to_entity_id IS NOT DISTINCT FROM p_to_entity
        AND l.amount IS NOT DISTINCT FROM p_amount
        AND l.category IS NOT DISTINCT FROM 'correction'
        AND l.club_id IS NOT DISTINCT FROM p_club_id
        AND l.union_id IS NOT DISTINCT FROM p_union_id
        AND l.description IS NOT DISTINCT FROM left(p_reason, 900)
        AND l.metadata IS NOT DISTINCT FROM
          (COALESCE(p_metadata, '{}'::jsonb)
           || jsonb_build_object('incident_id', p_incident_id,
                                 'write_failure_id', p_write_failure_id,
                                 'posted_via', 'fn_ca_post_correction'))) THEN
      RAISE EXCEPTION 'correction_ledger_projection_mismatch';
    END IF;
    RETURN jsonb_build_object('ok', true, 'replayed', true, 'ledger_id', v_existing);
  END IF;

  INSERT INTO public.chip_ledger
    (performed_by, from_type, from_entity_id, to_type, to_entity_id,
     amount, category, club_id, union_id, description, idempotency_key, metadata)
  VALUES
    (COALESCE(v_uid, '2d1cd6c3-5700-4af9-a271-d4863fdab20d'::uuid),
     p_from_type, p_from_entity, p_to_type, p_to_entity,
     p_amount, 'correction', p_club_id, p_union_id,
     left(p_reason, 900), v_key,
     COALESCE(p_metadata, '{}'::jsonb)
       || jsonb_build_object('incident_id', p_incident_id,
                             'write_failure_id', p_write_failure_id,
                             'posted_via', 'fn_ca_post_correction'))
  RETURNING id INTO v_id;

  IF v_id IS NULL THEN RAISE EXCEPTION 'correction_ledger_insert_missing'; END IF;
  IF NOT EXISTS (SELECT 1 FROM public.chip_ledger l
    WHERE l.id = v_id AND l.idempotency_key = v_key
      AND l.status IS NOT DISTINCT FROM 'posted'
      AND l.performed_by IS NOT DISTINCT FROM
        COALESCE(v_uid, '2d1cd6c3-5700-4af9-a271-d4863fdab20d'::uuid)
      AND l.from_type IS NOT DISTINCT FROM p_from_type
      AND l.from_entity_id IS NOT DISTINCT FROM p_from_entity
      AND l.to_type IS NOT DISTINCT FROM p_to_type
      AND l.to_entity_id IS NOT DISTINCT FROM p_to_entity
      AND l.amount IS NOT DISTINCT FROM p_amount
      AND l.category IS NOT DISTINCT FROM 'correction'
      AND l.club_id IS NOT DISTINCT FROM p_club_id
      AND l.union_id IS NOT DISTINCT FROM p_union_id
      AND l.description IS NOT DISTINCT FROM left(p_reason, 900)
      AND l.metadata IS NOT DISTINCT FROM
        (COALESCE(p_metadata, '{}'::jsonb)
         || jsonb_build_object('incident_id', p_incident_id,
                               'write_failure_id', p_write_failure_id,
                               'posted_via', 'fn_ca_post_correction'))) THEN
    RAISE EXCEPTION 'correction_ledger_projection_mismatch';
  END IF;

  IF p_incident_id IS NOT NULL THEN
    -- Lock the same incident row the following UPDATE already owns. Freeze
    -- the preexisting reference so a trigger cannot silently replace it.
    SELECT COALESCE(correction_ref, 'chip_ledger ' || v_id::text)
      INTO v_expected_ref FROM public.ca_drift_incidents
      WHERE id = p_incident_id FOR UPDATE;
    IF NOT FOUND THEN RAISE EXCEPTION 'correction_incident_missing'; END IF;
    UPDATE public.ca_drift_incidents
       SET correction_ref = COALESCE(correction_ref, 'chip_ledger ' || v_id::text)
     WHERE id = p_incident_id;
    IF NOT FOUND THEN RAISE EXCEPTION 'correction_incident_update_missing'; END IF;
    IF NOT EXISTS (SELECT 1 FROM public.ca_drift_incidents
      WHERE id = p_incident_id AND correction_ref IS NOT DISTINCT FROM v_expected_ref) THEN
      RAISE EXCEPTION 'correction_incident_reference_mismatch';
    END IF;
    v_event_detail := jsonb_build_object('correction_posted', v_id, 'amount', p_amount,
                                        'from', p_from_type, 'to', p_to_type);
    INSERT INTO public.ca_incident_events (incident_id, kind, actor, detail)
    VALUES (p_incident_id, 'repair_action', v_uid, v_event_detail)
    RETURNING id INTO v_event_id;
    IF v_event_id IS NULL THEN RAISE EXCEPTION 'correction_incident_event_missing'; END IF;
    IF NOT EXISTS (SELECT 1 FROM public.ca_incident_events
      WHERE id = v_event_id AND incident_id = p_incident_id
        AND kind = 'repair_action' AND actor IS NOT DISTINCT FROM v_uid
        AND detail IS NOT DISTINCT FROM v_event_detail) THEN
      RAISE EXCEPTION 'correction_incident_event_mismatch';
    END IF;
  END IF;

  -- Same transaction as the original ledger, overlays, documents and incident.
  -- A duplicate/failed/suppressed intent insert must never commit uncovered work.
  IF v_id IS NULL THEN RAISE EXCEPTION 'correction_ledger_insert_missing'; END IF;
  INSERT INTO public.ca_correction_request_intents_v1(linkage_key, ledger_id, request_intent)
    VALUES (v_key, v_id, v_intent);
  IF NOT FOUND THEN RAISE EXCEPTION 'correction_intent_insert_missing'; END IF;

  IF NOT EXISTS (SELECT 1 FROM public.ca_correction_request_intents_v1
    WHERE linkage_key = v_key AND ledger_id = v_id
      AND request_intent IS NOT DISTINCT FROM v_intent) THEN
    RAISE EXCEPTION 'correction_intent_retained_mismatch';
  END IF;

  RETURN jsonb_build_object('ok', true, 'replayed', false, 'ledger_id', v_id);
END $function$

public.fn_ca_raise_drift_incident(p_sour.def:
CREATE OR REPLACE FUNCTION public.fn_ca_raise_drift_incident(p_source text, p_classification text, p_severity text, p_dedupe_key text, p_discrepancy numeric DEFAULT NULL::numeric, p_expected numeric DEFAULT NULL::numeric, p_actual numeric DEFAULT NULL::numeric, p_layer text DEFAULT NULL::text, p_entity_type text DEFAULT NULL::text, p_entity_id uuid DEFAULT NULL::uuid, p_club_id uuid DEFAULT NULL::uuid, p_union_id uuid DEFAULT NULL::uuid, p_table_id uuid DEFAULT NULL::uuid, p_tournament_id uuid DEFAULT NULL::uuid, p_hand_id uuid DEFAULT NULL::uuid, p_settlement_id text DEFAULT NULL::text, p_wallet_ids uuid[] DEFAULT NULL::uuid[], p_transaction_ids uuid[] DEFAULT NULL::uuid[], p_suspected_cause text DEFAULT NULL::text, p_ledger_balanced boolean DEFAULT NULL::boolean, p_metadata jsonb DEFAULT NULL::jsonb)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_id uuid;
  v_class text := p_classification;
  v_sev   text := lower(COALESCE(p_severity,'critical'));
  v_stable text;
  v_financial_member jsonb := '{}'::jsonb;
  /* A FINDING RECORDS ITS CURRENCY (2026-09-29, Diamond Phase 10). A finding
     whose metadata says asset = diamonds is recorded in diamonds, and its
     alert and headline say Diamonds: the engine's DiamondCustody alerts
     (their context already carries the tag), the Diamond supply snapshot and
     the Diamond rule trigger. Every other finding is filed in chips, word for
     word as before. The headline names the rule when there is one, else the
     detector, and the Diamonds in doubt when there are any. */
  v_currency text := CASE WHEN lower(COALESCE(p_metadata->>'asset', '')) = 'diamonds'
                          THEN 'diamonds' ELSE 'club_chips' END;
  v_diamond_headline text := COALESCE('Diamond rule ' || (p_metadata->>'rule'), p_source)
    || CASE WHEN COALESCE(p_discrepancy, 0) <> 0
            THEN ': ' || to_char(p_discrepancy, 'FM999999999990') || ' Diamonds in doubt'
            ELSE ' is ' || v_sev END;
BEGIN
  IF NOT public.fn_ca_is_midway_scope(
    p_union_id, p_club_id, p_table_id, p_tournament_id, p_metadata
  ) THEN
    RETURN NULL;
  END IF;
  IF EXISTS (SELECT 1 FROM public.ca_detector_registry r WHERE r.source = p_source AND r.status = 'retired') THEN
    RETURN NULL;
  END IF;
  INSERT INTO public.ca_detector_registry (source, owner, sla_hours, note)
  VALUES (p_source, 'unassigned', 24, 'auto-registered on first sight (Phase 6 gate); give it an owner')
  ON CONFLICT (source) DO NOTHING;

  IF v_class IS NULL OR v_class NOT IN (
      'ledger_imbalance','settlement_error','duplicate_payment','missing_payment',
      'projection_delay','cache_mismatch','reporting_mismatch','delayed_event',
      'duplicate_event','rounding_error','incorrect_rake','incorrect_weighted_rake',
      'incorrect_rakeback','bbj_error','treasury_error','credit_line_error',
      'cross_club_posting','cross_union_posting','unauthorized_adjustment',
      'historical_migration','unknown') THEN
    v_class := 'unknown';
  END IF;
  IF v_sev NOT IN ('critical','warning','info') THEN v_sev := 'critical'; END IF;

  -- Keep validated original alert identity in the append-only event at the
  -- original raise, including recurrence and concurrent insertion fallback.
  IF left(p_source,length('financial_alerts:'))='financial_alerts:' THEN
    PERFORM pg_advisory_xact_lock(hashtextextended('ca-financial-incident-members:' || public.fn_ca_stable_dedupe_key(p_dedupe_key),0));
    v_financial_member:=jsonb_build_object('financial_member_version',1,'alert_id',
      CASE WHEN jsonb_typeof(p_metadata->'alert_id')='string'
        AND p_metadata->>'alert_id' ~ '^[0-9a-fA-F]{8}-[0-9a-fA-F]{4}-[0-9a-fA-F]{4}-[0-9a-fA-F]{4}-[0-9a-fA-F]{12}$'
        AND EXISTS(SELECT 1 FROM public.financial_alerts a
          WHERE a.id=CASE WHEN p_metadata->>'alert_id' ~ '^[0-9a-fA-F]{8}-[0-9a-fA-F]{4}-[0-9a-fA-F]{4}-[0-9a-fA-F]{4}-[0-9a-fA-F]{12}$'
                         THEN (p_metadata->>'alert_id')::uuid END
            AND a.source=substr(p_source,length('financial_alerts:')+1)
            AND a.severity='critical')
      THEN lower(p_metadata->>'alert_id') ELSE NULL END);
  END IF;
  UPDATE public.ca_drift_incidents
     SET occurrences  = occurrences + 1,
         last_seen_at = now(),
         discrepancy_amount = COALESCE(p_discrepancy, discrepancy_amount),
         actual_amount      = COALESCE(p_actual, actual_amount),
         expected_amount    = COALESCE(p_expected, expected_amount),
         suspected_cause    = COALESCE(p_suspected_cause, suspected_cause),
         metadata           = COALESCE(p_metadata, metadata)
   WHERE dedupe_key = p_dedupe_key AND status <> 'resolved'
   RETURNING id INTO v_id;

  IF v_id IS NOT NULL THEN
    INSERT INTO public.ca_incident_events (incident_id, kind, detail)
    VALUES (v_id, 'recurred', jsonb_build_object('source', p_source,
            'discrepancy', p_discrepancy) || v_financial_member);
    RETURN v_id;
  END IF;

  /* ONE STANDING CONDITION IS ONE INCIDENT (2026-09-06).
     A sweep that puts the date in its key defeats the exact-match fold above
     and files a fresh critical every run: sweep:fn_bbj_promo_bank_check:
     2026-09-02 .. -09-06, five rows, all 6705.21, one condition.

     The amount is what makes this safe. `diamond-unexplained:2026-09-02-18`
     is an hourly bucket where each bucket is a DIFFERENT event, so folding on
     the key alone would hide real ones. A standing condition re-reports the
     same number; a new event reports a new one. Same detector, same key
     without its period label, same discrepancy - then and only then is it the
     same finding said twice. */
  v_stable := public.fn_ca_stable_dedupe_key(p_dedupe_key);
  IF v_stable <> p_dedupe_key THEN
    UPDATE public.ca_drift_incidents
       SET occurrences     = occurrences + 1,
           last_seen_at    = now(),
           suspected_cause = COALESCE(p_suspected_cause, suspected_cause),
           metadata        = COALESCE(p_metadata, metadata)
     WHERE status <> 'resolved'
       AND source = p_source
       AND public.fn_ca_stable_dedupe_key(dedupe_key) = v_stable
       AND COALESCE(discrepancy_amount,0) = COALESCE(p_discrepancy,0)
     RETURNING id INTO v_id;
    IF v_id IS NOT NULL THEN
      INSERT INTO public.ca_incident_events (incident_id, kind, detail)
      VALUES (v_id, 'recurred', jsonb_build_object(
        'source', p_source, 'rotated_key', p_dedupe_key,
        'note', 'same condition under a new period label; folded rather than re-filed') || v_financial_member);
      RETURN v_id;
    END IF;
  END IF;

  /* DETECTOR STORM CAP (2026-09-09). One source cannot own the board.
     Reached only after the exact-key fold and the stable-key fold above have
     both declined to absorb this finding, i.e. it really would be a NEW row. */
  IF (SELECT count(*) FROM public.ca_drift_incidents
       WHERE source = p_source AND status <> 'resolved') >= 25 THEN
    IF left(p_source,length('financial_alerts:'))='financial_alerts:' THEN
      PERFORM pg_advisory_xact_lock(hashtextextended('ca-financial-incident-members:storm:' || p_source,0));
    END IF;
    UPDATE public.ca_drift_incidents
       SET occurrences = occurrences + 1, last_seen_at = now()
     WHERE dedupe_key = 'storm:' || p_source AND status <> 'resolved'
     RETURNING id INTO v_id;
    IF v_id IS NULL THEN
      INSERT INTO public.ca_drift_incidents (
        classification, severity, layer, source, dedupe_key,
        discrepancy_amount, suspected_cause, metadata)
      VALUES ('unknown', v_sev, COALESCE(p_layer,'unknown'), p_source,
        'storm:' || p_source, 0,
        'DETECTOR STORM: this source has 25 or more open incidents, so further findings are counted here rather than filed as new rows. See this incident''s event log for the original capped finding keys and reported discrepancies; this branch does not create a separate financial_alerts row for each finding. Fix the detector, or the condition behind it, then resolve this.',
        jsonb_build_object('storm', true, 'capped_from', p_dedupe_key)
          || CASE WHEN p_source='financial_alerts:Tournament.atomic_finish_refused'
               THEN jsonb_build_object('storm_member_version',1) ELSE '{}'::jsonb END)
      ON CONFLICT (dedupe_key) WHERE status <> 'resolved' DO NOTHING
      RETURNING id INTO v_id;
      IF v_id IS NULL THEN
        UPDATE public.ca_drift_incidents
           SET occurrences = occurrences + 1, last_seen_at = now()
         WHERE dedupe_key = 'storm:' || p_source AND status <> 'resolved'
         RETURNING id INTO v_id;
      END IF;
    END IF;
    IF v_id IS NOT NULL THEN
      INSERT INTO public.ca_incident_events (incident_id, kind, detail)
      VALUES (v_id, 'recurred', jsonb_build_object(
        'source', p_source, 'capped_dedupe_key', p_dedupe_key,
        'discrepancy', p_discrepancy, 'suspected_cause', p_suspected_cause,
        'note', 'counted on the storm incident: this source is over its open-incident cap')
        || CASE WHEN p_source='financial_alerts:Tournament.atomic_finish_refused'
             THEN jsonb_build_object('alert_id',p_metadata->'alert_id') ELSE '{}'::jsonb END || v_financial_member);
    END IF;
    RETURN v_id;
  END IF;

  INSERT INTO public.ca_drift_incidents (
    classification, severity, layer, source, dedupe_key,
    union_id, club_id, entity_type, entity_id, table_id, tournament_id,
    hand_id, settlement_id, wallet_ids, transaction_ids,
    expected_amount, actual_amount, discrepancy_amount,
    ledger_balanced, suspected_cause, metadata, currency)
  VALUES (
    v_class, v_sev, COALESCE(p_layer,'unknown'), p_source, p_dedupe_key,
    p_union_id, p_club_id, p_entity_type, p_entity_id, p_table_id, p_tournament_id,
    p_hand_id, p_settlement_id, p_wallet_ids, p_transaction_ids,
    p_expected, p_actual, COALESCE(p_discrepancy, 0),
    p_ledger_balanced, p_suspected_cause, COALESCE(p_metadata,'{}'::jsonb), v_currency)
  ON CONFLICT (dedupe_key) WHERE status <> 'resolved' DO NOTHING
  RETURNING id INTO v_id;

  IF v_id IS NULL THEN
    UPDATE public.ca_drift_incidents
       SET occurrences     = occurrences + 1,
           last_seen_at    = now(),
           suspected_cause = COALESCE(p_suspected_cause, suspected_cause),
           metadata        = COALESCE(p_metadata, metadata)
     WHERE dedupe_key = p_dedupe_key AND status <> 'resolved'
     RETURNING id INTO v_id;
    IF v_id IS NOT NULL AND v_financial_member <> '{}'::jsonb THEN
      INSERT INTO public.ca_incident_events(incident_id,kind,detail)
      VALUES(v_id,'recurred',jsonb_build_object('source',p_source,'discrepancy',p_discrepancy) || v_financial_member);
    END IF;
    RETURN v_id;
  END IF;

  INSERT INTO public.ca_incident_events (incident_id, kind, detail)
  VALUES (v_id, 'created', jsonb_build_object('source', p_source) || v_financial_member);

  BEGIN
    PERFORM public.fn_raise_server_financial_alert(
      v_sev, 'drift_incident:' || p_source,
      CASE WHEN v_currency = 'diamonds' THEN v_diamond_headline
           ELSE v_class || ' drift ' || COALESCE(p_discrepancy,0)::text || ' chips' END,
      jsonb_build_object('incident_id', v_id) || COALESCE(p_metadata,'{}'::jsonb));
  EXCEPTION WHEN OTHERS THEN NULL;
  END;

  IF p_severity = 'info' THEN
    NULL;
  ELSIF (SELECT count(*) FROM public.ca_drift_incidents
       WHERE created_at > now() - interval '2 minutes') >= 10 THEN
    INSERT INTO public.ca_incident_events (incident_id, kind, detail)
    VALUES (v_id, 'notified', jsonb_build_object('storm_suppressed', true));
  ELSE
    PERFORM public.fn_ca_incident_notify(
      v_id, 'notified',
      CASE WHEN v_currency = 'diamonds' THEN v_diamond_headline
           /* A FINDING WITH NO AMOUNT IS NOT A CHIP DRIFT (2026-10-15). A
              liveness check (the knockout door, tables that cannot deal)
              files at 0.00 and is let through by fn_ca_incident_notify; its
              title named "0.00 chip drift" and hid which check fired. It is
              headlined by its detector, as a Diamond rule already is. */
           WHEN COALESCE(p_discrepancy, 0) = 0 THEN p_source || ' is ' || v_sev
           ELSE to_char(COALESCE(p_discrepancy,0),'FM999999999990.00') || ' chip drift: ' || v_class END,
      false);
  END IF;

  RETURN v_id;
EXCEPTION WHEN OTHERS THEN
  DECLARE v_state text; v_msg text;
  BEGIN
    GET STACKED DIAGNOSTICS v_state = RETURNED_SQLSTATE, v_msg = MESSAGE_TEXT;
    RAISE WARNING 'fn_ca_raise_drift_incident(%) failed: %', p_source, v_msg;
    BEGIN
      INSERT INTO public.ca_incident_file_failures
        (source, dedupe_key, classification, severity, discrepancy, sqlstate, message)
      VALUES (p_source, p_dedupe_key, v_class, v_sev, p_discrepancy, v_state, v_msg);
    EXCEPTION WHEN OTHERS THEN
      NULL;
    END;
    RETURN NULL;
  END;
END $function$

public.fn_ca_rakeback_payout_leg_is_docu.def:
CREATE OR REPLACE FUNCTION public.fn_ca_rakeback_payout_leg_is_documented()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  m        jsonb := COALESCE(NEW.metadata,'{}'::jsonb);
  v_period uuid; v_cert bigint; v_payout uuid;
  v_kind   text; v_scope uuid; v_start timestamptz; v_end timestamptz;
  v_docs   int;
  v_legacy_operation uuid;
BEGIN
  IF NEW.idempotency_key IS NULL OR btrim(NEW.idempotency_key)='' THEN
    RAISE EXCEPTION 'rakeback_payout_leg_undocumented' USING ERRCODE='23514',
      DETAIL='chip_ledger '||NEW.id::text||' carries no idempotency key';
  END IF;
  IF m->>'routing_version' IS DISTINCT FROM '3' THEN
    RAISE EXCEPTION 'rakeback_payout_leg_undocumented' USING ERRCODE='23514',
      DETAIL='chip_ledger '||NEW.id::text||' has no routed accounting identity';
  END IF;
  BEGIN
    v_period:=(m->>'period_id')::uuid;   v_cert :=(m->>'certificate_id')::bigint;
    v_payout:=(m->>'payout_id')::uuid;   v_kind :=m->>'accounting_scope_kind';
    v_scope :=(m->>'accounting_scope_id')::uuid;
    v_start :=(m->>'period_start')::timestamptz;
    v_end   :=(m->>'period_end')::timestamptz;
  EXCEPTION WHEN OTHERS THEN
    RAISE EXCEPTION 'rakeback_payout_leg_undocumented' USING ERRCODE='23514',
      DETAIL='chip_ledger '||NEW.id::text||' has an unreadable routed accounting identity';
  END;
  IF v_period IS NULL OR v_cert IS NULL OR v_payout IS NULL OR v_kind IS NULL
     OR v_scope IS NULL OR v_start IS NULL OR v_end IS NULL THEN
    RAISE EXCEPTION 'rakeback_payout_leg_undocumented' USING ERRCODE='23514',
      DETAIL='chip_ledger '||NEW.id::text||' is missing part of its period, certificate or payout identity';
  END IF;

  -- The settlement run a disputing player is shown the payment under.
  IF NOT EXISTS(SELECT 1 FROM public.accounting_routed_settlement_runs r
    WHERE r.scope_kind=v_kind AND r.scope_id=v_scope AND r.period_start=v_start
      AND r.period_end=v_end AND r.round_no=3 AND r.routing_version=3)
    AND NOT EXISTS(SELECT 1 FROM public.accounting_rakeback_period_calculations c
      JOIN public.rakeback_period_payouts pp ON pp.id=v_payout AND pp.rakeback_period_id=c.period_id
      JOIN public.rakeback_periods rp ON rp.id=c.period_id
      WHERE NOT(m ? 'certificate_kind') AND c.id=v_cert AND c.accounting_version=2
       AND c.period_id=v_period AND c.club_id=NEW.club_id AND c.player_id=NEW.to_entity_id
       AND pp.club_id=c.club_id AND pp.user_id=c.player_id AND pp.status='paid' AND pp.payout_amount=c.rakeback_amount
       AND rp.status='paid' AND rp.club_id=c.club_id AND rp.user_id=c.player_id
       AND c.period_start=(v_start AT TIME ZONE 'America/Los_Angeles')::date
       AND c.period_end=(v_end AT TIME ZONE 'America/Los_Angeles')::date-1 AND c.period_end=c.period_start+6
       AND v_end<=now()-interval '5 minutes' AND v_start=public.fn_union_week_start(v_start)
       AND v_end=public.fn_union_week_start(v_start+interval '8 days')
       AND m->>'source_fingerprint'=c.source_fingerprint
       AND((v_kind='union' AND c.coordinator_union_id=v_scope)
         OR(v_kind='club' AND c.coordinator_union_id IS NULL AND c.club_id=v_scope))) THEN
    RAISE EXCEPTION 'rakeback_payout_leg_undocumented' USING ERRCODE='23514',
      DETAIL='chip_ledger '||NEW.id::text||' names no routed settlement run';
  END IF;

  IF m->>'wallet_destination_version'='own-agent-v1' THEN
    IF m?'certificate_kind'OR NOT smarter_private.rakeback_wallet_payout_complete(v_payout,v_cert)
     OR NOT EXISTS(SELECT FROM public.accounting_rakeback_wallet_transfers t WHERE t.payout_id=v_payout AND t.calculation_id=v_cert AND t.period_id=v_period AND t.ledger_id=NEW.id AND t.amount=NEW.amount AND t.destination_kind=NEW.to_type)
    THEN RAISE EXCEPTION 'typed_rakeback_payout_leg_undocumented' USING ERRCODE='23514';END IF;
    RETURN NULL;
  END IF;
  IF NEW.to_type='agent_wallet' THEN RAISE EXCEPTION 'typed_rakeback_payout_leg_undocumented' USING ERRCODE='23514';END IF;

  IF EXISTS(SELECT 1 FROM public.accounting_rakeback_period_calculations c WHERE c.id=v_cert AND c.payer_kind='split') THEN
    IF NOT smarter_private.split_rakeback_payout_complete(v_payout,v_cert)
      OR NOT EXISTS(SELECT 1 FROM public.accounting_rakeback_payer_transfers t WHERE t.payout_id=v_payout AND t.calculation_id=v_cert AND t.period_id=v_period AND t.ledger_id=NEW.id AND t.amount=NEW.amount)
    THEN RAISE EXCEPTION 'split_rakeback_payout_leg_undocumented' USING ERRCODE='23514'; END IF;
    RETURN NULL;
  END IF;

  IF NOT EXISTS(SELECT 1 FROM public.rakeback_period_payouts pp
    WHERE pp.id=v_payout AND pp.rakeback_period_id=v_period AND pp.club_id=NEW.club_id
      AND pp.user_id=NEW.to_entity_id AND pp.status='paid' AND pp.payout_amount=NEW.amount) THEN
    RAISE EXCEPTION 'rakeback_payout_leg_undocumented' USING ERRCODE='23514',
      DETAIL='chip_ledger '||NEW.id::text||' names no matching paid rakeback period payout';
  END IF;

  IF m ? 'certificate_kind' THEN
    -- The only other certificate kind is the owner-authorized legacy one. It
    -- must name its operation, and the certificate must be that operation's.
    IF m->>'certificate_kind' IS DISTINCT FROM 'owner_legacy_v1' THEN
      RAISE EXCEPTION 'rakeback_payout_leg_undocumented' USING ERRCODE='23514',
        DETAIL='chip_ledger '||NEW.id::text||' names an unknown certificate kind';
    END IF;
    BEGIN v_legacy_operation:=(m->>'legacy_operation_id')::uuid;
    EXCEPTION WHEN OTHERS THEN v_legacy_operation:=NULL; END;
    IF v_legacy_operation IS NULL OR NOT EXISTS(SELECT 1 FROM public.accounting_legacy_rakeback_certificates c
      JOIN public.accounting_owner_legacy_operations o ON o.operation_id=c.operation_id
      WHERE c.id=v_cert AND c.operation_id=v_legacy_operation AND c.period_id=v_period AND c.club_id=NEW.club_id
        AND c.player_id=NEW.to_entity_id AND c.rakeback_amount=NEW.amount
        AND o.period_start=v_start AND o.period_end=v_end) THEN
      RAISE EXCEPTION 'rakeback_payout_leg_undocumented' USING ERRCODE='23514',
        DETAIL='chip_ledger '||NEW.id::text||' names no matching owner legacy certificate';
    END IF;
  ELSIF NOT EXISTS(SELECT 1 FROM public.accounting_rakeback_period_calculations c
    WHERE c.id=v_cert AND c.period_id=v_period AND c.club_id=NEW.club_id
      AND c.player_id=NEW.to_entity_id AND c.rakeback_amount=NEW.amount) THEN
    RAISE EXCEPTION 'rakeback_payout_leg_undocumented' USING ERRCODE='23514',
      DETAIL='chip_ledger '||NEW.id::text||' names no matching rakeback certificate';
  END IF;

  SELECT count(*) INTO v_docs FROM public.settlement_invoices i
   WHERE i.source_ledger_id=NEW.id AND i.status='paid' AND i.chips_transferred
     AND i.gross_amount=NEW.amount AND i.net_amount=NEW.amount;
  IF v_docs<>1 THEN
    RAISE EXCEPTION 'rakeback_payout_leg_undocumented' USING ERRCODE='23514',
      DETAIL='chip_ledger '||NEW.id::text||' has '||v_docs::text||' source-linked paid receipts, expected exactly 1';
  END IF;
  RETURN NULL;
END $function$

public.fn_ca_refuse_restricted_transfer(.def:
CREATE OR REPLACE FUNCTION public.fn_ca_refuse_restricted_transfer()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public', 'pg_temp'
AS $function$
BEGIN
  IF TG_TABLE_NAME='chip_transactions' THEN
    IF NEW.transaction_type IN ('transfer','peer_transfer','user_transfer') AND NEW.amount>0 THEN
      PERFORM public.fn_ca_assert_player_action(NEW.from_user_id,'transfers',TG_TABLE_NAME);
    END IF;
  ELSIF TG_TABLE_NAME='wallet_transactions' THEN
    IF NEW.type='debit' AND NEW.category='transfer' AND NEW.amount>0 THEN
      PERFORM public.fn_ca_assert_player_action(NEW.user_id,'transfers',TG_TABLE_NAME);
    END IF;
  ELSIF NEW.amount<0 AND NEW.source IN ('wallet_transfer','wallet_diamond_transfer','stream_gift') THEN
    PERFORM public.fn_ca_assert_player_action(NEW.user_id,'transfers',TG_TABLE_NAME);
  END IF;
  RETURN NEW;
END $function$

public.fn_ca_register_issuance_leg(p_led.def:
CREATE OR REPLACE FUNCTION public.fn_ca_register_issuance_leg(p_ledger_id uuid)
 RETURNS boolean
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  l record; v_action text; v_holder_type text; v_holder uuid; v_label text;
  v_before numeric; v_after numeric; v_supply numeric; v_reason text; v_op text;
  v_outside text[] := public.fn_ca_noncirculating_chip_stores();
BEGIN
  SELECT * INTO l FROM public.chip_ledger WHERE id = p_ledger_id;
  IF NOT FOUND THEN RETURN false; END IF;
  IF EXISTS (SELECT 1 FROM public.ca_mint_ledger m WHERE m.chip_ledger_id = l.id) THEN
    RETURN false;
  END IF;
  IF l.category = 'correction' AND l.metadata->>'posted_via' = 'fn_ca_post_correction' THEN
    RETURN false;  -- a correction moves no balance (a_correction_is_not_a_mint)
  END IF;
  IF l.from_type = ANY (v_outside) AND NOT (l.to_type = ANY (v_outside)) THEN
    v_action := 'mint'; v_holder := l.to_entity_id;
    v_holder_type := CASE l.to_type
      WHEN 'club_treasury' THEN 'club' WHEN 'club_wallet' THEN 'club'
      WHEN 'union_bank' THEN 'union' WHEN 'union_wallet' THEN 'union'
      WHEN 'player_wallet' THEN 'player' WHEN 'promo_wallet' THEN 'player'
      ELSE 'circulation' END;
  ELSIF l.to_type = ANY (v_outside) AND NOT (l.from_type = ANY (v_outside)) THEN
    v_action := 'burn'; v_holder := l.from_entity_id;
    v_holder_type := CASE l.from_type
      WHEN 'club_treasury' THEN 'club' WHEN 'club_wallet' THEN 'club'
      WHEN 'union_bank' THEN 'union' WHEN 'union_wallet' THEN 'union'
      WHEN 'player_wallet' THEN 'player' WHEN 'promo_wallet' THEN 'player'
      ELSE 'circulation' END;
  ELSE
    RETURN false;  -- store to store, or circulating to circulating
  END IF;
  -- The autoledger stamps a union wallet's row with the union id; a union is
  -- also a row in clubs (is_union), so resolve by what the id actually is.
  IF v_holder_type = 'club' AND EXISTS (SELECT 1 FROM public.clubs c WHERE c.id = v_holder AND COALESCE(c.is_union, false)) THEN
    v_holder_type := 'union';
  END IF;
  IF v_holder IS NULL THEN
    v_holder_type := 'circulation';
  END IF;
  IF v_holder_type = 'circulation' THEN
    v_holder := '00000000-0000-0000-0000-00000000c1c0';  -- the circulation sentinel (the house is ...d1a0)
  END IF;
  v_label := CASE v_holder_type
    WHEN 'club'   THEN (SELECT c.name FROM public.clubs c WHERE c.id = v_holder)
    WHEN 'union'  THEN COALESCE((SELECT u.name FROM public.unions u WHERE u.id = v_holder), (SELECT c.name FROM public.clubs c WHERE c.id = v_holder))
    WHEN 'player' THEN (SELECT COALESCE(NULLIF(btrim(p.username), ''), p.full_name, p.id::text) FROM public.profiles p WHERE p.id = v_holder)
    ELSE 'circulation' END;
  -- A leg written by hand (a linked compensating entry) carries no balances;
  -- the register still wants a pair, so the pair is the amount itself.
  /* A door that wrote its own register row but did not link the leg
     (fn_ca_burn looks the leg up by a shape it does not always match):
     adopt that row rather than write a second one. Same action, holder,
     amount, asset, within five seconds of the leg, not yet linked. */
  UPDATE public.ca_mint_ledger m
     SET chip_ledger_id = l.id
   WHERE m.id = (SELECT m2.id FROM public.ca_mint_ledger m2
                  WHERE m2.chip_ledger_id IS NULL AND m2.asset = 'chips' AND m2.action = v_action
                    AND m2.amount = l.amount AND m2.holder_id = v_holder
                    AND m2.created_at BETWEEN l.created_at - interval '5 seconds' AND l.created_at + interval '5 seconds'
                  ORDER BY m2.created_at LIMIT 1);
  IF FOUND THEN RETURN false; END IF;
  v_before := COALESCE(CASE WHEN v_action = 'mint' THEN l.pre_to_balance ELSE l.pre_from_balance END, 0);
  v_after  := COALESCE(CASE WHEN v_action = 'mint' THEN l.post_to_balance ELSE l.post_from_balance END,
                       v_before + CASE WHEN v_action = 'mint' THEN l.amount ELSE -l.amount END);
  SELECT COALESCE(SUM(CASE WHEN action = 'mint' THEN amount ELSE -amount END), 0)
       + CASE WHEN v_action = 'mint' THEN l.amount ELSE -l.amount END
    INTO v_supply FROM public.ca_mint_ledger WHERE asset = 'chips';
  v_op := 'ledger:' || l.id::text;
  v_reason := left(COALESCE(NULLIF(btrim(l.description), ''), l.category) || ' (' || l.category
              || CASE WHEN l.idempotency_key IS NOT NULL THEN ', key ' || l.idempotency_key ELSE '' END
              || '; registered from the journal leg)', 500);
  IF length(btrim(v_reason)) < 10 THEN v_reason := v_reason || ' - registered from the journal'; END IF;
  INSERT INTO public.ca_mint_ledger
    (op_id, action, asset, holder_type, holder_id, holder_label, amount,
     balance_before, balance_after, supply_after, reason, performed_by, performed_by_label, db_role, chip_ledger_id, created_at)
  VALUES (v_op, v_action, 'chips', v_holder_type, v_holder, v_label, l.amount,
          v_before, v_after, v_supply, v_reason, l.performed_by, COALESCE(l.actor_service, l.db_role), l.db_role, l.id, l.created_at)
  ON CONFLICT (op_id) DO NOTHING;
  RETURN true;
END;
$function$

public.fn_ca_reject_automated_user_club_.def:
CREATE OR REPLACE FUNCTION public.fn_ca_reject_automated_user_club_row()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE
  v_club_id uuid;
  v_user_id uuid;
  v_automated boolean := false;
  v_is_horse boolean := false;
  v_refusal text;
  v_tournament_seat boolean := false;
BEGIN
  IF TG_TABLE_NAME = 'club_members' THEN
    v_club_id := NEW.club_id;
    v_user_id := NEW.user_id;
    v_automated := COALESCE(NEW.is_bot, false);
  ELSIF TG_TABLE_NAME = 'agents' THEN
    v_club_id := NEW.club_id;
    v_user_id := NEW.user_id;
  ELSIF TG_TABLE_NAME = 'table_seats' THEN
    -- A historical/departed seat remains immutable evidence. Only a live seat
    -- can put an automated player back onto a user-created club table.
    IF NEW.left_at IS NOT NULL THEN RETURN NEW; END IF;
    SELECT t.club_id, t.tournament_id IS NOT NULL INTO v_club_id, v_tournament_seat FROM public.tables t WHERE t.id = NEW.table_id;
    v_user_id := NEW.user_id;
  ELSIF TG_TABLE_NAME = 'tournament_players' THEN
    SELECT t.club_id INTO v_club_id
      FROM public.tournaments t WHERE t.id = NEW.tournament_id;
    v_user_id := NEW.user_id;
  ELSE
    RAISE EXCEPTION 'Unsupported Automated-Club Guard Table: %', TG_TABLE_NAME;
  END IF;

  v_is_horse := COALESCE(
    (SELECT p.is_horse FROM public.profiles p WHERE p.id = v_user_id), false
  );
  v_automated := v_automated OR v_is_horse;

  IF v_automated AND NOT public.fn_ca_house_board_allows_automation(v_club_id) THEN
    RAISE EXCEPTION 'AUTOMATED_PLAYER_HOUSE_BOARD_ONLY: Automated Players Cannot Enter A User-Created Club'
      USING ERRCODE = '42501';
  END IF;

  -- HORSES BELONG TO ONE ASSIGNED CLUB (20261102141229). Agents rows follow
  -- their membership; a departed membership update (lifecycle) is judged by
  -- fn_guard_membership_lifecycle_write instead.
  -- A tournament seat belongs to an entry that was admitted when it was made;
  -- the event seats, moves and re-seats it in any phase (20261102191900).
  IF v_is_horse AND TG_TABLE_NAME <> 'agents' AND NOT v_tournament_seat THEN
    v_refusal := public.fn_ca_horse_club_refusal(
      v_user_id, v_club_id,
      CASE WHEN TG_TABLE_NAME = 'tournament_players' THEN NEW.club_id END,
      TG_TABLE_NAME = 'club_members');
    IF v_refusal IS NOT NULL THEN
      RAISE EXCEPTION '%', v_refusal USING ERRCODE = '42501';
    END IF;
  END IF;
  RETURN NEW;
END;
$function$

public.fn_ca_sep8_spin_original_fee_proo.def:
CREATE OR REPLACE FUNCTION public.fn_ca_sep8_spin_original_fee_proof(p_tournament_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE c record;r public.rake_records%ROWTYPE;t public.tournaments%ROWTYPE;
 v public.managed_game_contract_versions%ROWTYPE;tp record;e record;l record;s record;
 item record;n integer;gross numeric:=0;earliest timestamptz;rows jsonb:='[]';versions jsonb:='[]';
 reserve jsonb;game_union uuid;reserve_account uuid;
BEGIN
 IF p_tournament_id NOT IN (
 '199a71a9-f364-4e90-a3ba-3cdcfb7755bc'::uuid,'808ef798-0942-4ce0-9ae1-eeefaaf4b0a9',
 'b60c7add-6b38-4549-b091-601f64d118a0','e3f4e2ab-8397-43e8-8643-6cec3fff3a63',
 'f3f050f1-569e-4fb6-859f-86b6092e682e') THEN RETURN NULL; END IF;
 SELECT * INTO c FROM public.fn_ca_legacy_fee_custody_cohort(p_tournament_id);
 SELECT count(*) INTO n FROM public.rake_records WHERE tournament_id=p_tournament_id AND is_tournament;
 SELECT * INTO r FROM public.rake_records WHERE tournament_id=p_tournament_id AND is_tournament;
 SELECT * INTO t FROM public.tournaments WHERE id=p_tournament_id;
 IF n<>1 OR c.source_count IS DISTINCT FROM 1 OR r.source IS DISTINCT FROM 'fn_spin_book_entry'
  OR r.rake_amount IS DISTINCT FROM c.amount OR md5(public.fn_accounting_tournament_fee_fingerprint(r)) IS DISTINCT FROM c.source_fingerprint
  OR r.created_at>='2026-09-17T18:24:02.831517Z'::timestamptz OR r.hand_id IS NOT NULL
  OR r.metadata->>'kind' IS DISTINCT FROM 'spin_rake' OR jsonb_typeof(r.player_contributions) IS DISTINCT FROM 'object'
  OR t.is_private IS DISTINCT FROM false OR t.variant IS DISTINCT FROM 'spin' OR t.tournament_type IS DISTINCT FROM 'SPIN'
  OR public.fn_poker_diamond_tournament(p_tournament_id)
 THEN RAISE EXCEPTION 'named Spin original aggregate identity missing' USING ERRCODE='P0404'; END IF;
 IF (SELECT count(*) FROM jsonb_object_keys(r.player_contributions))<>3
  OR (SELECT count(*) FROM public.tournament_players WHERE tournament_id=p_tournament_id)<>3
  OR (SELECT count(DISTINCT value::numeric) FROM jsonb_each_text(r.player_contributions))<>1
 THEN RAISE EXCEPTION 'named Spin requires exactly three equal original paid contributors' USING ERRCODE='P0404'; END IF;
 FOR item IN SELECT key::uuid player_id,value::numeric weight FROM jsonb_each_text(r.player_contributions) ORDER BY key LOOP
  SELECT * INTO tp FROM public.tournament_players WHERE tournament_id=p_tournament_id AND user_id=item.player_id;
  SELECT count(*) INTO n FROM public.tournament_refund_entitlements x WHERE x.tournament_id=p_tournament_id
   AND x.user_id=item.player_id AND x.entitlement_kind='wallet_charge' AND x.charge_category='tournament_buyin'
   AND x.created_at=tp.registered_at AND x.gross=item.weight;
  IF n<>1 THEN RAISE EXCEPTION 'named Spin original paid entry ambiguous' USING ERRCODE='P0404'; END IF;
  SELECT * INTO e FROM public.tournament_refund_entitlements x WHERE x.tournament_id=p_tournament_id
   AND x.user_id=item.player_id AND x.entitlement_kind='wallet_charge' AND x.charge_category='tournament_buyin'
   AND x.created_at=tp.registered_at AND x.gross=item.weight;
  SELECT * INTO l FROM public.chip_ledger WHERE id=e.source_ledger_id;
  IF l.id IS NULL OR tp.club_id IS DISTINCT FROM e.refund_wallet_club_id OR l.created_at IS DISTINCT FROM e.created_at
   OR e.created_at>r.created_at OR l.amount IS DISTINCT FROM e.gross OR l.club_id IS DISTINCT FROM e.refund_wallet_club_id
   OR l.from_type IS DISTINCT FROM 'player_wallet' OR l.from_entity_id IS DISTINCT FROM item.player_id
   OR l.to_type IS DISTINCT FROM 'prize_liability' OR l.to_entity_id IS DISTINCT FROM p_tournament_id
   OR l.category IS DISTINCT FROM 'tournament_buyin' OR item.weight<=0
  THEN RAISE EXCEPTION 'named Spin original debit evidence disagrees' USING ERRCODE='P0404'; END IF;
  earliest:=least(earliest,e.created_at);gross:=gross+item.weight;
  rows:=rows||jsonb_build_array(jsonb_build_object('registration_id',tp.id,'player_id',item.player_id,
   'club_id',tp.club_id,'registered_at',tp.registered_at,'entitlement',to_jsonb(e)-'terminal_closed_at','ledger',to_jsonb(l)));
 END LOOP;
 SELECT count(*) INTO n FROM public.spin_reserve_ledger WHERE tournament_id=p_tournament_id AND kind='contribution';
 SELECT * INTO s FROM public.spin_reserve_ledger WHERE tournament_id=p_tournament_id AND kind='contribution';
 IF n<>1 OR s.seats IS DISTINCT FROM 3 OR s.house_rake IS DISTINCT FROM r.rake_amount
  OR s.amount IS DISTINCT FROM gross-r.rake_amount OR s.buy_in IS DISTINCT FROM gross/3
 THEN RAISE EXCEPTION 'named Spin original reserve contribution disagrees' USING ERRCODE='P0404'; END IF;
 reserve:=jsonb_build_object('contribution',to_jsonb(s)-'terminal_closed_at');
 SELECT count(*) INTO n FROM public.chip_ledger x WHERE x.tournament_id=p_tournament_id AND x.category='spin_entry';
 SELECT * INTO l FROM public.chip_ledger x WHERE x.tournament_id=p_tournament_id AND x.category='spin_entry';
 IF n<>1 OR l.amount IS DISTINCT FROM s.amount OR l.created_at IS DISTINCT FROM s.created_at
  OR l.club_id IS DISTINCT FROM s.club_id OR l.from_type IS DISTINCT FROM 'prize_liability'
  OR l.from_entity_id IS DISTINCT FROM p_tournament_id OR l.to_type IS DISTINCT FROM 'spin_reserve' OR l.to_entity_id IS NULL
 THEN RAISE EXCEPTION 'named Spin reserve contribution debit disagrees' USING ERRCODE='P0404'; END IF;
 reserve_account:=l.to_entity_id;reserve:=reserve||jsonb_build_object('contribution_ledger',to_jsonb(l));
 SELECT count(*) INTO n FROM public.spin_reserve_ledger WHERE tournament_id=p_tournament_id AND kind='jackpot_draw';
 SELECT * INTO s FROM public.spin_reserve_ledger WHERE tournament_id=p_tournament_id AND kind='jackpot_draw';
 IF n<>1 OR s.seats IS DISTINCT FROM 3 OR s.house_rake IS DISTINCT FROM r.rake_amount
  OR s.amount IS DISTINCT FROM -t.prize_pool OR s.buy_in IS DISTINCT FROM gross/3 OR s.amount>=0
 THEN RAISE EXCEPTION 'named Spin original prize draw disagrees' USING ERRCODE='P0404'; END IF;
 reserve:=reserve||jsonb_build_object('draw',to_jsonb(s)-'terminal_closed_at');
 SELECT count(*) INTO n FROM public.chip_ledger x WHERE x.tournament_id=p_tournament_id AND x.category='spin_prize';
 SELECT * INTO l FROM public.chip_ledger x WHERE x.tournament_id=p_tournament_id AND x.category='spin_prize';
 IF n<>1 OR l.amount IS DISTINCT FROM -s.amount OR l.created_at IS DISTINCT FROM s.created_at
  OR l.club_id IS DISTINCT FROM s.club_id OR l.from_type IS DISTINCT FROM 'spin_reserve'
  OR l.from_entity_id IS DISTINCT FROM reserve_account OR l.to_type IS DISTINCT FROM 'prize_liability'
  OR l.to_entity_id IS DISTINCT FROM p_tournament_id
 THEN RAISE EXCEPTION 'named Spin original prize draw credit disagrees' USING ERRCODE='P0404'; END IF;
 reserve:=reserve||jsonb_build_object('draw_ledger',to_jsonb(l));
 SELECT * INTO v FROM public.managed_game_contract_versions WHERE game_id=p_tournament_id AND game_kind='tournament' AND version=1;
 IF NOT FOUND OR v.published_at>earliest OR v.club_id IS DISTINCT FROM r.club_id
  OR v.club_id IS DISTINCT FROM t.club_id OR v.union_id IS DISTINCT FROM t.union_id
 THEN RAISE EXCEPTION 'named Spin original created scope missing' USING ERRCODE='P0404'; END IF;
 game_union:=v.union_id;
 FOR v IN SELECT * FROM public.managed_game_contract_versions WHERE game_id=p_tournament_id AND game_kind='tournament'
  AND published_at<=r.created_at ORDER BY version,id LOOP
  IF v.club_id IS DISTINCT FROM t.club_id OR v.union_id IS DISTINCT FROM game_union
   OR v.contract->>'id' IS DISTINCT FROM p_tournament_id::text OR v.contract->>'club_id' IS DISTINCT FROM v.club_id::text
   OR NULLIF(v.contract->>'union_id','')::uuid IS DISTINCT FROM game_union OR v.contract->'is_private' IS DISTINCT FROM 'false'::jsonb
   OR v.contract->>'variant' IS DISTINCT FROM 'spin' OR v.contract->>'tournament_type' IS DISTINCT FROM 'SPIN'
   OR (v.contract->>'buy_in_amount')::numeric IS DISTINCT FROM gross/3 OR (v.contract->>'max_players')::integer IS DISTINCT FROM 3
   OR v.contract_hash IS DISTINCT FROM public.fn_managed_game_contract_hash(v.contract)
  THEN RAISE EXCEPTION 'named Spin immutable economic scope disagrees' USING ERRCODE='P0404'; END IF;
  versions:=versions||jsonb_build_array(to_jsonb(v));
 END LOOP;
 RETURN jsonb_build_object('tournament_id',p_tournament_id,'raw_source_count',1,'recognized_contributors',3,
  'source_fingerprint',c.source_fingerprint,'fee',c.amount,'gross',gross,'contributors',rows,'reserve',reserve,'scope_versions',versions);
END $function$

public.fn_ca_settlement_transition_guard.def:
CREATE OR REPLACE FUNCTION public.fn_ca_settlement_transition_guard()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE
  ord_old int; ord_new int;
BEGIN
  IF NEW.state = OLD.state THEN RETURN NEW; END IF;
  ord_old := array_position(ARRAY['open','locked_for_calculation','calculated',
              'validated','ledger_posted','post_commit_verified','final'], OLD.state);
  ord_new := array_position(ARRAY['open','locked_for_calculation','calculated',
              'validated','ledger_posted','post_commit_verified','final'], NEW.state);
  IF OLD.state = 'final' THEN
    RAISE EXCEPTION 'settlement % is final and cannot change state', OLD.id;
  END IF;
  IF NEW.state = 'failed' THEN
    NEW.updated_at := now(); RETURN NEW;
  END IF;
  IF OLD.state = 'failed' THEN  -- resume: re-enter anywhere at or before ledger_posted
    IF ord_new IS NULL OR ord_new > 5 THEN
      RAISE EXCEPTION 'failed settlement % may only resume at or before ledger_posted', OLD.id;
    END IF;
    NEW.updated_at := now(); RETURN NEW;
  END IF;
  IF ord_old IS NULL OR ord_new IS NULL OR ord_new <> ord_old + 1 THEN
    RAISE EXCEPTION 'invalid settlement transition % -> % for %', OLD.state, NEW.state, OLD.id;
  END IF;
  NEW.updated_at := now();
  RETURN NEW;
END $function$

public.fn_ca_tally_balance_move().def:
CREATE OR REPLACE FUNCTION public.fn_ca_tally_balance_move()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
AS $function$
DECLARE
  o jsonb := CASE WHEN TG_OP = 'INSERT' THEN NULL ELSE to_jsonb(OLD) END;
  n jsonb := CASE WHEN TG_OP = 'DELETE' THEN NULL ELSE to_jsonb(NEW) END;
  k_old text; k_new text;
  v_old numeric := 0; v_new numeric := 0;
BEGIN
  CASE TG_TABLE_NAME
    WHEN 'club_members' THEN
      IF o IS NOT NULL THEN
        k_old := 'player_wallet:' || COALESCE(o ->> 'user_id', 'null') || ':' || COALESCE(o ->> 'club_id', 'null');
        v_old := COALESCE((o ->> 'chip_balance')::numeric, 0);
      END IF;
      IF n IS NOT NULL THEN
        k_new := 'player_wallet:' || COALESCE(n ->> 'user_id', 'null') || ':' || COALESCE(n ->> 'club_id', 'null');
        v_new := COALESCE((n ->> 'chip_balance')::numeric, 0);
      END IF;
    WHEN 'clubs' THEN
      IF o IS NOT NULL THEN
        k_old := 'club_treasury:' || (o ->> 'id');
        v_old := COALESCE((o ->> 'chip_treasury')::numeric, 0) + COALESCE((o ->> 'chip_pool')::numeric, 0);
      END IF;
      IF n IS NOT NULL THEN
        k_new := 'club_treasury:' || (n ->> 'id');
        v_new := COALESCE((n ->> 'chip_treasury')::numeric, 0) + COALESCE((n ->> 'chip_pool')::numeric, 0);
      END IF;
    WHEN 'table_seats' THEN
      /* A seat is on the felt while it is occupied (left_at IS NULL) and its
         table is a cash chip table. A vacated seat's stack has left the felt
         whether or not the row zeroes it, which is exactly what
         fn_log_seat_stack_exit records and what a cash-out leg explains. */
      k_old := 'table_stack'; k_new := 'table_stack';
      IF o IS NOT NULL AND (o ->> 'left_at') IS NULL
         AND public.fn_ca_felt_counts_table((o ->> 'table_id')::uuid) THEN
        v_old := COALESCE((o ->> 'stack')::numeric, 0);
      END IF;
      IF n IS NOT NULL AND (n ->> 'left_at') IS NULL
         AND public.fn_ca_felt_counts_table((n ->> 'table_id')::uuid) THEN
        v_new := COALESCE((n ->> 'stack')::numeric, 0);
      END IF;
    WHEN 'table_pending_addons' THEN
      /* The add-on's leg lands at request time; the chips wait here until the
         hand ends. They are on the felt the whole time (fn_ca_supply_snapshot
         pending_addons, 2026-09-12), so resolving one is not a movement. */
      k_old := 'table_stack'; k_new := 'table_stack';
      IF o IS NOT NULL AND (o ->> 'resolved_at') IS NULL
         AND public.fn_ca_felt_counts_table((o ->> 'table_id')::uuid) THEN
        v_old := COALESCE((o ->> 'amount')::numeric, 0);
      END IF;
      IF n IS NOT NULL AND (n ->> 'resolved_at') IS NULL
         AND public.fn_ca_felt_counts_table((n ->> 'table_id')::uuid) THEN
        v_new := COALESCE((n ->> 'amount')::numeric, 0);
      END IF;
    WHEN 'hand_atomic_commits' THEN
      /* THE FEES A HAND TAKES OFF ITS SEATS STAY ON THE FELT UNTIL THEIR LEGS
         ARE POSTED (20261001231409). The accepted-hand transaction moves the
         seats by inflow - rake - bbj and writes no leg for the fees. Their
         legs - table_stack -> union_wallet or chip_retirement for the rake,
         table_stack -> bbj_pool for the drop, the insurance bank's leg for the
         inflow - are posted by fn_ca_process_hand_post_commit_obligations in
         a LATER transaction, under the club wallet, VIP carry and pool locks
         the commit path must not wait on. So the hand's own receipt carries
         the fees as felt from the moment its envelope is stored until the
         moment that envelope completes - in the same transaction that posts
         the legs. Each transaction balances on its own, and a hand whose
         second half has not run yet reads as fees still on the felt, never as
         chips that vanished. Scoped exactly like the seat: the cash chip felt. */
      k_old := 'table_stack'; k_new := 'table_stack';
      IF o IS NOT NULL AND (o ->> 'post_commit_payload') IS NOT NULL
         AND (o ->> 'post_commit_completed_at') IS NULL
         AND public.fn_ca_felt_counts_table((o ->> 'table_id')::uuid) THEN
        v_old := COALESCE((o -> 'stack_result' ->> 'rake')::numeric, 0)
               + COALESCE((o -> 'stack_result' ->> 'bbj')::numeric, 0)
               - COALESCE((o -> 'stack_result' ->> 'inflow')::numeric, 0);
      END IF;
      IF n IS NOT NULL AND (n ->> 'post_commit_payload') IS NOT NULL
         AND (n ->> 'post_commit_completed_at') IS NULL
         AND public.fn_ca_felt_counts_table((n ->> 'table_id')::uuid) THEN
        v_new := COALESCE((n -> 'stack_result' ->> 'rake')::numeric, 0)
               + COALESCE((n -> 'stack_result' ->> 'bbj')::numeric, 0)
               - COALESCE((n -> 'stack_result' ->> 'inflow')::numeric, 0);
      END IF;
    WHEN 'union_wallets' THEN
      /* Two accounts on one row: the bank (chip_balance) and the five
         operating wallets, both keyed by the union. */
      IF o IS NOT NULL THEN
        PERFORM public.fn_ca_ledger_tally_add('union_bank:' || (o ->> 'union_id'), 'b',
                  -COALESCE((o ->> 'chip_balance')::numeric, 0));
        k_old := 'union_wallet:' || (o ->> 'union_id');
        v_old := COALESCE((o ->> 'rake_wallet')::numeric, 0) + COALESCE((o ->> 'bbj_wallet')::numeric, 0)
               + COALESCE((o ->> 'promo_wallet')::numeric, 0) + COALESCE((o ->> 'insurance_wallet')::numeric, 0)
               + COALESCE((o ->> 'spin_reserve_wallet')::numeric, 0);
      END IF;
      IF n IS NOT NULL THEN
        PERFORM public.fn_ca_ledger_tally_add('union_bank:' || (n ->> 'union_id'), 'b',
                  COALESCE((n ->> 'chip_balance')::numeric, 0));
        k_new := 'union_wallet:' || (n ->> 'union_id');
        v_new := COALESCE((n ->> 'rake_wallet')::numeric, 0) + COALESCE((n ->> 'bbj_wallet')::numeric, 0)
               + COALESCE((n ->> 'promo_wallet')::numeric, 0) + COALESCE((n ->> 'insurance_wallet')::numeric, 0)
               + COALESCE((n ->> 'spin_reserve_wallet')::numeric, 0);
      END IF;
    WHEN 'bbj_pools' THEN
      IF o IS NOT NULL THEN
        k_old := 'bbj_pool:' || (o ->> 'id');
        v_old := COALESCE((o ->> 'main_balance')::numeric, 0) + COALESCE((o ->> 'backup_balance')::numeric, 0)
               + COALESCE((o ->> 'promo_balance')::numeric, 0);
      END IF;
      IF n IS NOT NULL THEN
        k_new := 'bbj_pool:' || (n ->> 'id');
        v_new := COALESCE((n ->> 'main_balance')::numeric, 0) + COALESCE((n ->> 'backup_balance')::numeric, 0)
               + COALESCE((n ->> 'promo_balance')::numeric, 0);
      END IF;
    ELSE
      RAISE EXCEPTION 'fn_ca_tally_balance_move is not configured for %', TG_TABLE_NAME;
  END CASE;

  /* A row that changes account (a seat changing table, a membership changing
     club) leaves one account and arrives in another; both sides are counted. */
  IF k_old IS NOT NULL AND k_new IS NOT NULL AND k_old = k_new THEN
    PERFORM public.fn_ca_ledger_tally_add(k_new, 'b', v_new - v_old);
  ELSE
    IF k_old IS NOT NULL THEN PERFORM public.fn_ca_ledger_tally_add(k_old, 'b', -v_old); END IF;
    IF k_new IS NOT NULL THEN PERFORM public.fn_ca_ledger_tally_add(k_new, 'b', v_new); END IF;
  END IF;
  RETURN NULL;
END;
$function$

public.fn_ca_tally_ledger_leg().def:
CREATE OR REPLACE FUNCTION public.fn_ca_tally_ledger_leg()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
AS $function$
BEGIN
  /* SETTLEMENT SUSPENSE IS NOT A COUNTERPARTY FOR A BALANCE (2026-10-02).
     Every leg with settlement_suspense on either side is counted, before the
     journal-only exemption below, under a key no store resolves to. The
     commit check refuses a transaction that wrote one and moved any covered
     balance; a journal-only correction moves none and still commits. */
  IF NEW.from_type = 'settlement_suspense' OR NEW.to_type = 'settlement_suspense' THEN
    PERFORM public.fn_ca_ledger_tally_add('settlement_suspense', 's', abs(NEW.amount));
  END IF;
  /* A journal-only restatement (CLAUDE.md 10.9 rule 3, fn_ca_post_correction)
     moves no balance by design and is outside every meter, including this one. */
  IF NEW.category = 'correction' AND NEW.metadata ->> 'posted_via' = 'fn_ca_post_correction' THEN
    RETURN NULL;
  END IF;
  PERFORM public.fn_ca_ledger_tally_add(
    CASE WHEN NEW.to_type = 'escrow' AND NEW.category IN ('escrow_hold', 'escrow_release')
      THEN 'cashout_escrow:' || COALESCE(NEW.to_entity_id::text, 'null')
      ELSE public.fn_ca_ledger_tally_key(NEW.to_type, NEW.to_entity_id, NEW.club_id) END, 'l', NEW.amount);
  PERFORM public.fn_ca_ledger_tally_add(
    CASE WHEN NEW.from_type = 'escrow' AND NEW.category IN ('escrow_hold', 'escrow_release')
      THEN 'cashout_escrow:' || COALESCE(NEW.from_entity_id::text, 'null')
      ELSE public.fn_ca_ledger_tally_key(NEW.from_type, NEW.from_entity_id, NEW.club_id) END, 'l', -NEW.amount);
  RETURN NULL;
END;
$function$

public.fn_ca_tally_pair(p_k_old text, p_.def:
CREATE OR REPLACE FUNCTION public.fn_ca_tally_pair(p_k_old text, p_v_old numeric, p_k_new text, p_v_new numeric)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
AS $function$
BEGIN
  /* One balance column of one row, before and after. A row that changes
     account (a membership changing club, a ticket leaving 'issued') leaves one
     account and arrives in another; both sides are counted. A NULL key is a
     side that does not exist (an INSERT's OLD, a DELETE's NEW, a Diamond
     event), and fn_ca_ledger_tally_add ignores it. */
  IF p_k_old IS NOT DISTINCT FROM p_k_new THEN
    PERFORM public.fn_ca_ledger_tally_add(p_k_new, 'b', COALESCE(p_v_new, 0) - COALESCE(p_v_old, 0));
  ELSE
    PERFORM public.fn_ca_ledger_tally_add(p_k_old, 'b', -COALESCE(p_v_old, 0));
    PERFORM public.fn_ca_ledger_tally_add(p_k_new, 'b', COALESCE(p_v_new, 0));
  END IF;
END;
$function$

public.fn_ca_tournament_charge_split(p_t.def:
CREATE OR REPLACE FUNCTION public.fn_ca_tournament_charge_split(p_tournament_id uuid, p_charge_category text, p_gross numeric)
 RETURNS TABLE(refund_prize numeric, refund_bounty numeric, refund_fee numeric)
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_t record;
  v_entry record;
  v_kind text := lower(btrim(COALESCE(p_charge_category,'')));
  v_gross numeric := round(COALESCE(p_gross,0),2);
  v_is_bounty boolean;
  v_ratio numeric;
  v_fee numeric;
  v_bounty numeric;
BEGIN
  IF p_tournament_id IS NULL OR p_gross IS NULL
     OR p_gross::text IN ('NaN','Infinity','-Infinity')
     OR p_gross IS DISTINCT FROM v_gross OR v_gross <= 0
     OR v_kind NOT IN ('tournament_buyin','rebuy','addon') THEN
    RAISE EXCEPTION 'tournament charge split received an invalid contract'
      USING ERRCODE = '22003';
  END IF;
  SELECT t.buy_in_amount,t.buy_in_fee,t.bounty_amount,
         t.is_bounty,t.is_pko,t.is_mystery_bounty
    INTO v_t FROM public.tournaments t WHERE t.id=p_tournament_id;
  IF NOT FOUND THEN
    RAISE EXCEPTION 'tournament charge split has no tournament %',p_tournament_id
      USING ERRCODE = 'P0002';
  END IF;
  v_is_bounty := COALESCE(v_t.is_bounty,false)
              OR COALESCE(v_t.is_pko,false)
              OR COALESCE(v_t.is_mystery_bounty,false);
  IF v_kind='tournament_buyin' THEN
    SELECT * INTO v_entry FROM public.fn_tournament_entry_split(
      v_t.buy_in_amount,v_t.buy_in_fee,v_t.bounty_amount,v_is_bounty);
    IF v_entry.charge IS DISTINCT FROM v_gross THEN
      RAISE EXCEPTION
        'tournament buy-in ledger amount % does not match its funded split %',
        v_gross,v_entry.charge USING ERRCODE = '23514';
    END IF;
    refund_prize := v_entry.prize;
    refund_bounty := v_entry.bounty;
    refund_fee := v_entry.rake;
  ELSIF v_kind='addon' THEN
    IF v_gross IS DISTINCT FROM round(v_gross) THEN
      RAISE EXCEPTION 'add-on charge must be a positive whole chip amount'
        USING ERRCODE = '23514';
    END IF;
    -- A Midway Mystery Free Buy add-on splits like its entries and rebuys.
    refund_bounty := CASE WHEN v_is_bounty
        AND public.fn_ca_midway_free_buy_format(p_tournament_id)='mystery' THEN
      public.fn_ca_unit_floor_cents(
        round(LEAST(GREATEST(0,round(COALESCE(v_t.bounty_amount,0),2)),v_gross)*100)::bigint,
        public.fn_ca_tournament_unit_cents(p_tournament_id))::numeric / 100
      ELSE 0 END;
    refund_prize := round(v_gross-refund_bounty,2);
    refund_fee := 0;
  ELSE
    IF v_gross IS DISTINCT FROM round(v_gross) THEN
      RAISE EXCEPTION 'rebuy charge must be a positive whole chip amount'
        USING ERRCODE = '23514';
    END IF;
    v_ratio := public.fn_ca_tournament_purchase_fee_ratio(
      v_t.buy_in_amount, v_t.buy_in_fee, public.fn_ca_tournament_unit_cents(p_tournament_id));
    IF public.fn_ca_midway_free_buy_format(p_tournament_id) IS NOT NULL THEN v_ratio:=0; END IF;
    v_fee := public.fn_ca_recovery_fee_cents(
      round(v_gross*100)::bigint, v_ratio,
      public.fn_ca_tournament_unit_cents(p_tournament_id))::numeric / 100;    v_bounty := CASE WHEN v_is_bounty THEN
      public.fn_ca_unit_floor_cents(
        round(LEAST(GREATEST(0,round(COALESCE(v_t.bounty_amount,0),2)),
                    v_gross-v_fee)*100)::bigint,
        public.fn_ca_tournament_unit_cents(p_tournament_id))::numeric / 100
      ELSE 0 END;
    refund_fee := v_fee;
    refund_bounty := v_bounty;
    refund_prize := round(v_gross-v_fee-v_bounty,2);
  END IF;
  IF refund_prize IS NULL OR refund_bounty IS NULL OR refund_fee IS NULL
     OR refund_prize::text IN ('NaN','Infinity','-Infinity')
     OR refund_bounty::text IN ('NaN','Infinity','-Infinity')
     OR refund_fee::text IN ('NaN','Infinity','-Infinity')
     OR refund_prize < 0 OR refund_bounty < 0 OR refund_fee < 0
     OR v_gross IS DISTINCT FROM
          round(refund_prize+refund_bounty+refund_fee,2) THEN
    RAISE EXCEPTION 'tournament charge split produced invalid component rails'
      USING ERRCODE = '23514';
  END IF;
  RETURN NEXT;
END;
$function$

public.fn_cancelled_tournament_evidence_.def:
CREATE OR REPLACE FUNCTION public.fn_cancelled_tournament_evidence_is_immutable()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_old_tournament_id uuid;
  v_new_tournament_id uuid;
  v_tournament_id uuid;
BEGIN
 IF TG_OP='INSERT' AND TG_TABLE_NAME='chip_ledger' AND to_jsonb(NEW)->'metadata'->>'entry_kind'='launch_closing_position' THEN RETURN NEW; END IF;
  IF TG_OP<>'INSERT' THEN
    v_old_tournament_id:=NULLIF(to_jsonb(OLD)->>'tournament_id','')::uuid;
  END IF;
  IF TG_OP<>'DELETE' THEN
    v_new_tournament_id:=NULLIF(to_jsonb(NEW)->>'tournament_id','')::uuid;
  END IF;
  IF TG_OP='UPDATE' AND v_new_tournament_id IS DISTINCT FROM v_old_tournament_id THEN
    RAISE EXCEPTION '% rows cannot move between tournaments',TG_TABLE_NAME
      USING ERRCODE='55000';
  END IF;
  v_tournament_id:=COALESCE(v_new_tournament_id,v_old_tournament_id);
  IF v_tournament_id IS NULL THEN
    IF TG_OP='DELETE' THEN RETURN OLD; ELSE RETURN NEW; END IF;
  END IF;
  IF TG_TABLE_NAME='chip_ledger' AND TG_OP<>'INSERT' THEN
    RAISE EXCEPTION 'tournament chip ledger evidence is append-only'
      USING ERRCODE='55000';
  END IF;
  IF TG_OP='INSERT' THEN
    PERFORM 1 FROM public.tournaments t
     WHERE t.id=v_tournament_id FOR KEY SHARE;
  END IF;
  IF EXISTS (SELECT 1 FROM public.tournament_cancellation_receipts h
              WHERE h.tournament_id=v_tournament_id) THEN
    RAISE EXCEPTION 'cancelled tournament % has immutable % evidence',
      v_tournament_id,TG_TABLE_NAME USING ERRCODE='55000';
  END IF;
  IF TG_OP='DELETE' THEN RETURN OLD; ELSE RETURN NEW; END IF;
END;
$function$

public.fn_cancelled_tournament_wallet_is.def:
CREATE OR REPLACE FUNCTION public.fn_cancelled_tournament_wallet_is_immutable()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_old_tournament_id uuid;
  v_new_tournament_id uuid;
BEGIN
  IF TG_OP<>'INSERT' THEN v_old_tournament_id:=OLD.related_entity_id; END IF;
  IF TG_OP<>'DELETE' THEN v_new_tournament_id:=NEW.related_entity_id; END IF;
  IF TG_OP='INSERT' AND v_new_tournament_id IS NOT NULL
     AND EXISTS (SELECT 1 FROM public.tournaments t
                  WHERE t.id=v_new_tournament_id) THEN
    PERFORM 1 FROM public.tournaments t
     WHERE t.id=v_new_tournament_id FOR KEY SHARE;
  END IF;
  IF EXISTS (SELECT 1 FROM public.tournament_cancellation_receipts h
              WHERE h.tournament_id=v_old_tournament_id)
     OR EXISTS (SELECT 1 FROM public.tournament_cancellation_receipts h
                 WHERE h.tournament_id=v_new_tournament_id) THEN
    RAISE EXCEPTION 'cancelled tournament wallet evidence is immutable'
      USING ERRCODE='55000';
  END IF;
  IF TG_OP='DELETE' THEN RETURN OLD; ELSE RETURN NEW; END IF;
END;
$function$

public.fn_capture_agent_credit_week(p_cl.def:
CREATE OR REPLACE FUNCTION public.fn_capture_agent_credit_week(p_clubs uuid[], p_from timestamp with time zone, p_to timestamp with time zone, p_kind text, p_scope uuid)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE c uuid;a record;
BEGIN
 IF NOT public.fn_caller_is_engine() THEN RAISE EXCEPTION 'service_role_required' USING ERRCODE='42501'; END IF;
 IF p_clubs IS NULL OR p_from IS NULL OR p_to IS NULL OR NOT isfinite(p_from) OR NOT isfinite(p_to) OR p_from>=p_to OR p_to>now() THEN RAISE EXCEPTION 'invalid_credit_scope' USING ERRCODE='22023'; END IF;
 IF p_from IS DISTINCT FROM public.fn_union_week_start(p_from) OR p_to IS DISTINCT FROM public.fn_union_week_start(p_from+interval '8 days') THEN RAISE EXCEPTION 'credit_tracking_requires_one_accounting_week' USING ERRCODE='22023'; END IF;
 -- Never reconstruct an old week's balance from today's chips.
 IF p_to<(SELECT activated_at FROM public.agent_credit_tracking_policy WHERE singleton) THEN RETURN; END IF;
 -- A paid stage can only replay the basis it captured, never invent a late one.
 IF EXISTS(SELECT FROM public.accounting_routed_settlement_runs WHERE scope_kind=p_kind AND scope_id=p_scope AND period_start=p_from AND period_end=p_to AND round_no=2) THEN RETURN; END IF;
 FOR c IN SELECT DISTINCT x FROM unnest(p_clubs)x ORDER BY x LOOP
  PERFORM pg_advisory_xact_lock(hashtextextended('agent-agreement:'||c::text,0));
 END LOOP;
 FOR a IN SELECT id,club_id,credit_limit,agent_wallet_balance FROM public.agents WHERE club_id=ANY(p_clubs) AND NOT COALESCE(is_prepaid,false) AND credit_limit>0 AND NOT EXISTS(SELECT FROM public.agent_credit_weekly_scopes captured WHERE captured.club_id=agents.club_id AND captured.period_end=p_to) ORDER BY club_id,id FOR UPDATE LOOP
  INSERT INTO public.agent_credit_weekly_basis(agent_id,club_id,period_start,period_end,credit_line,agent_wallet_before_rakeback)
  VALUES(a.id,a.club_id,p_from,p_to,a.credit_limit,a.agent_wallet_balance) ON CONFLICT(agent_id,period_end) DO NOTHING;
 END LOOP;
 FOR c IN SELECT DISTINCT x FROM unnest(p_clubs)x ORDER BY x LOOP
  INSERT INTO public.agent_credit_weekly_scopes(club_id,period_start,period_end) VALUES(c,p_from,p_to) ON CONFLICT(club_id,period_end) DO NOTHING;
  PERFORM public.fn_generate_scope_credit_invoices(c,p_from,p_to);
 END LOOP;
END $function$

public.fn_capture_club_messenger_admissi.def:
CREATE OR REPLACE FUNCTION public.fn_capture_club_messenger_admission()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'extensions'
AS $function$
DECLARE v_active boolean; v_previous boolean:=false; v_assignment_changed boolean:=false;
BEGIN
 v_active:=NEW.is_active=true AND NEW.status IN ('active','approved') AND NEW.membership_lifecycle_status='active';
 IF TG_OP='UPDATE' THEN
  v_previous:=OLD.is_active=true AND OLD.status IN ('active','approved') AND OLD.membership_lifecycle_status='active';
  v_assignment_changed:=NEW.agent_id IS DISTINCT FROM OLD.agent_id;
 END IF;
 IF v_active AND (NOT v_previous OR v_assignment_changed) THEN
  INSERT INTO public.club_messenger_admissions(club_id,user_id,active) VALUES(NEW.club_id,NEW.user_id,true)
  ON CONFLICT(club_id,user_id) DO UPDATE SET generation=gen_random_uuid(),active=true,transaction_id=txid_current(),started_at=now();
 ELSIF NOT v_active THEN
  UPDATE public.club_messenger_admissions SET active=false WHERE club_id=NEW.club_id AND user_id=NEW.user_id;
 END IF;
 RETURN NEW;
END $function$

public.fn_cash_original_funding_lineage(.def:
CREATE OR REPLACE FUNCTION public.fn_cash_original_funding_lineage(p_user uuid, p_table uuid, p_seat uuid, p_occupancy uuid, p_join timestamp with time zone, p_at timestamp with time zone, p_boundary boolean DEFAULT false)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
 SET "TimeZone" TO 'UTC'
AS $function$
DECLARE m public.cash_seat_move_receipts%ROWTYPE; f public.cash_participant_funding_receipts%ROWTYPE;
 l public.chip_ledger%ROWTYPE; a public.cash_funding_application_receipts%ROWTYPE;
 current_table uuid:=p_table; current_occupancy uuid:=p_occupancy;
 seen uuid[]:=ARRAY[]::uuid[]; ids uuid[]:=ARRAY[]::uuid[]; refs jsonb:='[]'; moves jsonb:='[]'; issues jsonb:='[]';
 cutoff timestamptz:=p_at; cutoff_transaction xid8; move_at timestamptz;
 move_club uuid; n integer; depth integer:=0;
BEGIN
 IF p_user IS NULL OR p_table IS NULL OR p_seat IS NULL OR p_occupancy IS NULL
  OR p_join IS NULL OR NOT isfinite(p_join) OR p_at IS NULL OR NOT isfinite(p_at) THEN
  RETURN jsonb_build_object('version',1,'observed_at',p_at,'funding_receipts',refs,'moves',moves,'issues',jsonb_build_array('cash_lineage_identity_missing'));
 END IF;
 LOOP
  IF current_occupancy=ANY(seen) OR depth>64 THEN
   issues:=issues||'"cash_move_cycle_or_depth_unproven"'::jsonb; EXIT;
  END IF;
  seen:=array_append(seen,current_occupancy);
  FOR f IN SELECT r.* FROM public.cash_participant_funding_receipts r
   LEFT JOIN public.union_pnl_transaction_frames b ON b.transaction_id=r.transaction_id
   WHERE r.occupancy_id=current_occupancy AND (CASE WHEN p_boundary THEN COALESCE(b.observed_at,r.recorded_at) ELSE r.recorded_at END)<p_at
    AND ((CASE WHEN p_boundary THEN COALESCE(b.observed_at,r.recorded_at) ELSE r.recorded_at END)<=cutoff OR r.transaction_id=cutoff_transaction)
   ORDER BY r.recorded_at,r.id LOOP
   IF f.id=ANY(ids) OR f.user_id IS DISTINCT FROM p_user OR f.table_id IS DISTINCT FROM current_table
    OR (depth=0 AND (f.seat_id IS DISTINCT FROM p_seat OR f.seat_joined_at IS DISTINCT FROM p_join))
    OR (move_club IS NOT NULL AND f.funding_club_id IS DISTINCT FROM move_club)
    OR (f.account_type='player_wallet' AND f.account_entity_id IS DISTINCT FROM f.user_id)
    OR (f.account_type='club_treasury' AND f.account_entity_id IS DISTINCT FROM f.funding_club_id AND NOT (f.operation_kind='horse_funding' AND smarter_private.cash_initial_funding_receipt(f.id) IS TRUE))
    OR f.asset IS DISTINCT FROM 'chips' OR f.unit_scale<>2 OR NOT isfinite(f.recorded_at)
    OR f.amount<=0 OR f.amount<>round(f.amount,2) OR f.amount::text IN ('NaN','Infinity','-Infinity')
    OR f.balance_before-f.balance_after IS DISTINCT FROM f.amount THEN
    issues:=issues||'"cash_lineage_funding_identity_invalid"'::jsonb;
   END IF;
   SELECT * INTO l FROM public.chip_ledger WHERE id=f.source_ledger_id;
   IF NOT FOUND OR l.status IS DISTINCT FROM 'posted' OR (l.club_id IS DISTINCT FROM f.funding_club_id AND NOT (f.operation_kind='horse_funding' AND smarter_private.cash_initial_funding_receipt(f.id) IS TRUE))
    OR l.from_type IS DISTINCT FROM f.account_type OR l.from_entity_id IS DISTINCT FROM f.account_entity_id
    OR l.to_type IS DISTINCT FROM 'table_stack' OR l.to_entity_id IS DISTINCT FROM f.table_id
    OR l.category IS DISTINCT FROM f.operation_kind OR l.amount IS DISTINCT FROM f.amount THEN
    issues:=issues||'"cash_lineage_original_debit_invalid"'::jsonb;
   END IF;
   IF f.pending_addon_id IS NOT NULL AND NOT p_boundary THEN
    SELECT * INTO a FROM public.cash_funding_application_receipts WHERE funding_receipt_id=f.id;
    IF NOT FOUND OR a.original_occupancy_id IS DISTINCT FROM f.occupancy_id
     OR NOT isfinite(a.applied_at) OR a.applied+a.refunded IS DISTINCT FROM f.amount
     OR (a.applied>0 AND a.applied_occupancy_id IS DISTINCT FROM f.occupancy_id) THEN
     issues:=issues||'"pending_funding_application_unproven"'::jsonb;
    END IF;
   END IF;
   ids:=array_append(ids,f.id);
   refs:=refs||jsonb_build_array(jsonb_build_object('id',f.id,'account_type',f.account_type,
    'account_entity_id',f.account_entity_id,'funding_club_id',f.funding_club_id,'funding_union_id',f.funding_union_id,
    'pending_addon_id',f.pending_addon_id));
  END LOOP;
  SELECT count(*) INTO n FROM public.cash_seat_move_receipts r LEFT JOIN public.union_pnl_transaction_frames b ON b.transaction_id=r.transaction_id
   WHERE r.destination_occupancy_id=current_occupancy AND (CASE WHEN p_boundary THEN COALESCE(b.observed_at,r.created_at) ELSE r.created_at END)<p_at;
  IF n=0 THEN EXIT; END IF;
  IF n<>1 THEN issues:=issues||'"cash_move_destination_fork"'::jsonb; EXIT; END IF;
  SELECT r.* INTO m FROM public.cash_seat_move_receipts r LEFT JOIN public.union_pnl_transaction_frames b ON b.transaction_id=r.transaction_id
   WHERE r.destination_occupancy_id=current_occupancy AND (CASE WHEN p_boundary THEN COALESCE(b.observed_at,r.created_at) ELSE r.created_at END)<p_at;
  SELECT observed_at INTO move_at FROM public.union_pnl_transaction_frames WHERE transaction_id=m.transaction_id;
  IF p_boundary AND (m.transaction_id IS NULL OR move_at IS NULL) THEN
   issues:=issues||'"cash_move_original_transaction_frame_missing"'::jsonb;
  END IF;
  IF m.player_id IS DISTINCT FROM p_user OR m.to_table_id IS DISTINCT FROM current_table
   OR m.source_occupancy_id=ANY(seen) OR m.from_table_id=m.to_table_id
   OR m.club_id IS NULL OR (move_club IS NOT NULL AND m.club_id IS DISTINCT FROM move_club)
   OR m.amount<=0 OR m.amount<>round(m.amount,2) OR m.amount::text IN ('NaN','Infinity','-Infinity')
   OR NOT isfinite(m.created_at) OR (CASE WHEN p_boundary THEN COALESCE(move_at,m.created_at) ELSE m.created_at END)>cutoff
   OR (move_at IS NOT NULL AND (NOT isfinite(move_at) OR move_at>=p_at))
   OR jsonb_typeof(m.receipt) IS DISTINCT FROM 'object' OR m.receipt->>'ok' IS DISTINCT FROM 'true'
   OR m.receipt->>'move_id' IS DISTINCT FROM m.move_id::text OR m.receipt->>'player_id' IS DISTINCT FROM p_user::text
   OR m.receipt->>'from_table_id' IS DISTINCT FROM m.from_table_id::text
   OR m.receipt->>'to_table_id' IS DISTINCT FROM m.to_table_id::text
   OR m.receipt->>'source_seat_number' IS DISTINCT FROM m.from_seat_number::text
   OR m.receipt->>'to_seat_number' IS DISTINCT FROM m.to_seat_number::text
   OR m.receipt->>'source_occupancy_id' IS DISTINCT FROM m.source_occupancy_id::text
   OR m.receipt->>'destination_occupancy_id' IS DISTINCT FROM m.destination_occupancy_id::text
   OR public.fn_pnl_evidence_cents(m.receipt->'stack') IS DISTINCT FROM m.amount
   OR m.receipt->>'idempotency_key' IS DISTINCT FROM 'seatmove:'||m.move_id::text
   OR (SELECT count(*) FROM public.cash_seat_move_receipts r LEFT JOIN public.union_pnl_transaction_frames b ON b.transaction_id=r.transaction_id WHERE r.source_occupancy_id=m.source_occupancy_id AND (CASE WHEN p_boundary THEN COALESCE(b.observed_at,r.created_at) ELSE r.created_at END)<p_at)<>1 THEN
   issues:=issues||'"cash_move_original_receipt_invalid"'::jsonb; EXIT;
  END IF;
  moves:=moves||jsonb_build_array(to_jsonb(m));
  move_club:=m.club_id; current_table:=m.from_table_id; current_occupancy:=m.source_occupancy_id;
  cutoff:=CASE WHEN p_boundary THEN COALESCE(move_at,m.created_at) ELSE m.created_at END; cutoff_transaction:=m.transaction_id; depth:=depth+1;
 END LOOP;
 -- Every retained source must agree with the exact custody club through all moves.
 IF move_club IS NOT NULL AND EXISTS(SELECT 1 FROM jsonb_array_elements(refs) r WHERE r->>'funding_club_id' IS DISTINCT FROM move_club::text) THEN
  issues:=issues||'"cash_move_original_funding_club_mismatch"'::jsonb;
 END IF;
 RETURN jsonb_build_object('version',1,'observed_at',p_at,'funding_receipts',refs,'moves',moves,'issues',issues);
EXCEPTION WHEN invalid_text_representation OR numeric_value_out_of_range OR datetime_field_overflow THEN
 RETURN jsonb_build_object('version',1,'observed_at',p_at,'funding_receipts','[]'::jsonb,'moves',moves,'issues',jsonb_build_array('cash_move_malformed_original_evidence'));
END $function$

public.fn_cash_rakeback_period_basis(p_c.def:
CREATE OR REPLACE FUNCTION public.fn_cash_rakeback_period_basis(p_club_id uuid, p_period_start date, p_period_end date, p_user_ids uuid[] DEFAULT NULL::uuid[])
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
 SET statement_timeout TO '300s'
AS $function$
DECLARE
 v_from timestamptz; v_to timestamptz; v_union uuid; source_issues bigint; missing_terms bigint:=0;
 invalid_terms bigint:=0; legacy_pending bigint; paid_conflicts bigint; v record;
 member_receipt jsonb; agent_receipt jsonb; member_terms jsonb; member_agent uuid;
 rows_by_user jsonb:='{}'; item jsonb; histories jsonb; total_cents numeric:=0; basis_rows jsonb;
BEGIN
 IF NOT public.fn_caller_is_engine() THEN RAISE EXCEPTION 'accounting_basis_not_authorised' USING ERRCODE='42501'; END IF;
 IF p_club_id IS NULL OR p_period_start IS NULL OR p_period_end IS NULL
    OR NOT isfinite(p_period_start) OR NOT isfinite(p_period_end)
    OR extract(isodow FROM p_period_start)<>1 OR p_period_end<>p_period_start+6
    OR (p_user_ids IS NOT NULL AND (cardinality(p_user_ids)>2000 OR array_position(p_user_ids,NULL) IS NOT NULL))
 THEN RAISE EXCEPTION 'invalid_accounting_basis_request' USING ERRCODE='22023'; END IF;
 IF NOT EXISTS(SELECT 1 FROM public.clubs WHERE id=p_club_id) THEN RAISE EXCEPTION 'accounting_club_not_found' USING ERRCODE='22023'; END IF;
 v_from:=p_period_start::timestamp AT TIME ZONE 'America/Los_Angeles';
 v_to:=(p_period_end+1)::timestamp AT TIME ZONE 'America/Los_Angeles';
 v_from:=public.fn_ca_launch_accounting_start('club',p_club_id,v_from);
 SELECT union_id INTO v_union FROM public.clubs WHERE id=p_club_id;
 -- Missing attribution cannot be assigned to a particular member club. Hold
 -- every affected union preview when a source under its house club is missing,
 -- rather than quietly omitting the unknown beneficiary. Current club routing
 -- is used only to widen this failure check, never to assign a player's credit.
 WITH scoped_records AS (
  SELECT r.* FROM public.rake_records r
   WHERE r.created_at>=v_from AND r.created_at<v_to AND r.rake_amount>0
     AND r.is_tournament IS NOT TRUE AND r.tournament_id IS NULL
     AND NOT public.fn_rake_record_is_ghost_twin(r.hand_id,r.table_id,r.metadata)
     AND (r.club_id=p_club_id
       OR EXISTS(SELECT 1 FROM public.rake_attributions a WHERE a.rake_record_id=r.id AND a.club_id=p_club_id)
       OR EXISTS(SELECT 1 FROM public.clubs house WHERE house.id=r.club_id AND house.is_union IS TRUE
          AND v_union IS NOT NULL AND (house.union_id=v_union OR house.id=v_union)))
 ), checks AS (
  SELECT r.id,r.hand_id,r.rake_amount,count(a.id) AS attribution_count,
    COALESCE(sum(a.weighted_rake_credit),0) AS attributed,
    count(a.id) FILTER(WHERE a.hand_id IS DISTINCT FROM r.hand_id OR a.club_id IS NULL
      OR a.player_id IS NULL OR a.weighted_rake_credit IS NULL OR a.weighted_rake_credit<0
      OR a.weighted_rake_credit<>round(a.weighted_rake_credit,2)
      OR NOT EXISTS(SELECT 1 FROM public.clubs c WHERE c.id=a.club_id AND c.is_union IS NOT TRUE)) AS invalid_count
   FROM scoped_records r LEFT JOIN public.rake_attributions a ON a.rake_record_id=r.id
   GROUP BY r.id,r.hand_id,r.rake_amount
 )
 SELECT count(*) INTO source_issues FROM checks WHERE hand_id IS NULL OR attribution_count=0
  OR invalid_count>0 OR attributed<>rake_amount OR rake_amount<>round(rake_amount,2);

 FOR v IN
  SELECT a.player_id,a.weighted_rake_credit,r.id AS rake_record_id,r.created_at
   FROM public.rake_attributions a JOIN public.rake_records r ON r.id=a.rake_record_id AND r.hand_id=a.hand_id
   WHERE a.club_id=p_club_id AND r.created_at>=v_from AND r.created_at<v_to
    AND r.rake_amount>0 AND r.is_tournament IS NOT TRUE AND r.tournament_id IS NULL
    AND a.weighted_rake_credit>0 AND a.weighted_rake_credit=round(a.weighted_rake_credit,2)
    AND (p_user_ids IS NULL OR a.player_id=ANY(p_user_ids))
    AND NOT public.fn_rake_record_is_ghost_twin(r.hand_id,r.table_id,r.metadata)
   ORDER BY r.created_at,r.id,a.player_id
 LOOP
  item:=COALESCE(rows_by_user->v.player_id::text,jsonb_build_object('user_id',v.player_id,
    'rake_generated',0,'source_count',0,'first_earned_at',v.created_at,'contract_versions','[]'::jsonb));
  histories:=item->'contract_versions';
  BEGIN
   member_receipt:=public.fn_accounting_terms_at('club_members',p_club_id::text||':'||v.player_id::text,v.created_at);
   member_terms:=member_receipt->'terms';
   IF member_terms IS NULL OR member_terms='null'::jsonb
      OR member_terms->>'club_id' IS DISTINCT FROM p_club_id::text OR member_terms->>'user_id' IS DISTINCT FROM v.player_id::text
      OR member_terms->>'is_active' IS DISTINCT FROM 'true'
      OR COALESCE(member_terms->>'status','') NOT IN('active','approved')
   THEN RAISE EXCEPTION 'accounting_terms_not_active' USING ERRCODE='55000'; END IF;
   histories:=histories||jsonb_build_array(member_receipt->'history_id');
   member_agent:=NULLIF(member_terms->>'agent_id','')::uuid;
   IF member_agent IS NOT NULL THEN
    agent_receipt:=public.fn_accounting_agent_terms_at(p_club_id,member_agent,v.created_at);
    histories:=histories||jsonb_build_array(agent_receipt->'history_id');
   END IF;
  EXCEPTION WHEN SQLSTATE '55000' THEN
   IF SQLERRM='accounting_terms_not_observed' THEN missing_terms:=missing_terms+1;
   ELSIF SQLERRM IN('accounting_terms_not_active','accounting_terms_ambiguous') THEN invalid_terms:=invalid_terms+1;
   ELSE RAISE; END IF;
  END;
  SELECT COALESCE(jsonb_agg(DISTINCT h),'[]'::jsonb) INTO histories FROM jsonb_array_elements(histories) h;
  item:=item||jsonb_build_object('rake_generated',(item->>'rake_generated')::numeric+v.weighted_rake_credit,
    'source_count',(item->>'source_count')::bigint+1,'last_earned_at',v.created_at,'contract_versions',histories);
  rows_by_user:=jsonb_set(rows_by_user,ARRAY[v.player_id::text],item,true);
  total_cents:=total_cents+v.weighted_rake_credit*100;
 END LOOP;
 SELECT COALESCE(jsonb_agg(value ORDER BY key),'[]'::jsonb) INTO basis_rows FROM jsonb_each(rows_by_user);
 -- Existing rows do not carry a source version or observed contracts. They
 -- are conflicts for the eventual writer even when the displayed totals match.
 SELECT count(*) FILTER(WHERE status='pending'),count(*) FILTER(WHERE status<>'pending')
  INTO legacy_pending,paid_conflicts FROM public.rakeback_periods
  WHERE club_id=p_club_id AND period_start<=p_period_end AND period_end>=p_period_start
    AND (p_user_ids IS NULL OR user_id=ANY(p_user_ids));
 RETURN jsonb_build_object('source_version',2,'accounting_timezone','America/Los_Angeles','club_id',p_club_id,
  'period_start',p_period_start,'period_end',p_period_end,'from',v_from,'to',v_to,
  'status',CASE WHEN source_issues+missing_terms+invalid_terms+legacy_pending+paid_conflicts=0 THEN 'ready' ELSE 'needs_reconciliation' END,
  'payable',false,'rows',basis_rows,'total_rake',total_cents/100,
  'missing_source_count',source_issues,'missing_terms_count',missing_terms,'invalid_terms_count',invalid_terms,
  'legacy_pending_conflicts',legacy_pending,'paid_period_conflicts',paid_conflicts,
  'scope','cash_only','written',0);
END $function$

public.fn_cash_source_refusal_scope(p_ra.def:
CREATE OR REPLACE FUNCTION public.fn_cash_source_refusal_scope(p_rake_record_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE r public.rake_records%ROWTYPE;b public.accounting_cash_bank_receipts%ROWTYPE;
 n int; historical_union uuid; cutoff timestamptz;
BEGIN
 SELECT * INTO r FROM public.rake_records WHERE id=p_rake_record_id;
 SELECT * INTO b FROM public.accounting_cash_bank_receipts WHERE rake_record_id=r.id;
 -- A source's bank receipt is immutable. A real union deposit identifies its
 -- book even when a player's attribution or commercial terms are incomplete.
 IF b.union_id IS NOT NULL AND b.amount=r.rake_amount AND b.banked_at=r.created_at
  AND EXISTS(SELECT 1 FROM public.union_wallet_transactions t WHERE t.id=b.union_transaction_id
   AND t.union_id=b.union_id AND t.wallet='rake_wallet' AND t.direction='credit'
   AND t.tx_type='rake' AND t.amount=b.amount AND t.created_at=b.banked_at) THEN
  RETURN jsonb_build_object('kind','union','id',b.union_id,'proof','union_bank_receipt');
 END IF;
 IF b.union_id IS NULL AND b.club_id=r.club_id AND b.amount=r.rake_amount AND b.banked_at=r.created_at
  AND EXISTS(SELECT 1 FROM public.chip_ledger l WHERE l.id=b.club_ledger_id
   AND l.from_type='table_stack' AND l.to_type='chip_retirement' AND l.to_entity_id IS NULL AND l.club_id=b.club_id
   AND l.amount=b.amount AND l.category='burn' AND l.created_at=b.banked_at) THEN
  SELECT count(*),(array_agg((h.after_terms->>'union_id')::uuid))[1] INTO n,historical_union FROM (
   SELECT DISTINCT ON(entity_key) after_terms FROM public.accounting_agreement_history
    WHERE entity_type='union_clubs' AND club_id=b.club_id AND observed_at<=r.created_at
    ORDER BY entity_key,observed_at DESC,id DESC)h
   WHERE h.after_terms IS NOT NULL AND h.after_terms->>'club_id'=b.club_id::text;
  IF n=1 AND historical_union IS NOT NULL THEN
   RETURN jsonb_build_object('kind','union','id',historical_union,'proof','private_bank_and_observed_membership');
  END IF;
  SELECT starts_at INTO cutoff FROM public.accounting_cash_accrual_cutover WHERE singleton;
  -- After source cutover the installed observer covers all union membership
  -- transitions. Before it, absence of a historical row proves no absence.
  IF n=0 AND r.created_at>=cutoff THEN
   RETURN jsonb_build_object('kind','club','id',b.club_id,'proof','private_bank_after_history_cutover');
  END IF;
 END IF;
 RETURN jsonb_build_object('kind','unknown','id',NULL,'proof','coordinator_not_proven');
END $function$

public.fn_cashier_assert_active_actor(p_.def:
CREATE OR REPLACE FUNCTION public.fn_cashier_assert_active_actor(p_club uuid)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE
  v_actor uuid := auth.uid();
  v_role text;
  v_status text;
BEGIN
  IF auth.role() = 'service_role' THEN RETURN; END IF;
  IF v_actor IS NULL OR p_club IS NULL THEN RETURN; END IF;
  IF EXISTS (SELECT 1 FROM public.clubs WHERE id = p_club AND owner_id = v_actor) THEN
    RETURN;
  END IF;

  SELECT role INTO v_role
    FROM public.club_members
   WHERE club_id = p_club
     AND user_id = v_actor
     AND coalesce(status, 'active') IN ('active', 'approved')
   LIMIT 1;

  IF v_role IN ('super_agent', 'agent', 'sub_agent') THEN
    -- Serialize against status changes without taking a row lock ahead of the
    -- retained money core's established wallet/club lock order. The matching
    -- agents trigger below takes this same mutex before status/update/delete.
    PERFORM pg_advisory_xact_lock(hashtextextended(
      'cashier-agent-authority:' || p_club || ':' || v_actor, 0));
    SELECT a.status INTO v_status
      FROM public.agents a
     WHERE a.club_id = p_club AND a.user_id = v_actor;
    IF v_status IS DISTINCT FROM 'active' THEN
      RAISE EXCEPTION 'cashier_agent_inactive' USING ERRCODE = '42501';
    END IF;
  END IF;
END
$function$

public.fn_cashier_exact_intent_begin(p_a.def:
CREATE OR REPLACE FUNCTION public.fn_cashier_exact_intent_begin(p_action text, p_club uuid, p_operation uuid, p_intent jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE
  v_actor uuid := auth.uid();
  v_existing public.cashier_rpc_operation_intents%ROWTYPE;
BEGIN
  IF v_actor IS NULL THEN
    RETURN jsonb_build_object('state', 'return', 'response',
      jsonb_build_object('success', false, 'error', 'Not Authenticated'));
  END IF;
  IF p_operation IS NULL THEN
    RETURN jsonb_build_object('state', 'return', 'response',
      jsonb_build_object('success', false, 'error', 'A Retry Key Is Required'));
  END IF;

  -- Global ownership prevents two actors racing the same UUID through the
  -- legacy core's looser metadata replay lookup.
  PERFORM pg_advisory_xact_lock(hashtextextended('cashier-exact-intent:' || p_operation, 0));
  SELECT * INTO v_existing
    FROM public.cashier_rpc_operation_intents
   WHERE operation_id = p_operation
   FOR UPDATE;

  IF FOUND THEN
    IF v_existing.actor_user_id IS DISTINCT FROM v_actor
       OR v_existing.action IS DISTINCT FROM p_action
       OR v_existing.club_id IS DISTINCT FROM p_club
       OR v_existing.operation_intent IS DISTINCT FROM p_intent THEN
      RETURN jsonb_build_object('state', 'return', 'response',
        jsonb_build_object('success', false,
          'error', 'That Retry Key Belongs To A Different Cashier Request'));
    END IF;
    IF v_existing.receipt IS NOT NULL THEN
      RETURN jsonb_build_object('state', 'return', 'response',
        v_existing.receipt || jsonb_build_object('replayed', true));
    END IF;
    IF NOT public.fn_ca_launch_accounting_accepts(v_existing.club_id,v_existing.created_at) THEN
      RETURN jsonb_build_object('state','return','response',jsonb_build_object('success',false,'error','Prior Launch Cashier Request Was Waived'));
    END IF;
    RETURN jsonb_build_object('state', 'proceed');
  END IF;

  IF EXISTS (
    SELECT 1 FROM public.chip_transactions t
     WHERE t.metadata ->> 'op_id' = p_operation::text
  ) OR EXISTS (
    SELECT 1 FROM public.chip_requests r
     WHERE r.op_id = p_operation
  ) THEN
    RETURN jsonb_build_object('state', 'return', 'response',
      jsonb_build_object('success', false,
        'error', 'That Legacy Retry Key Cannot Be Verified; Reconcile It Before Retrying'));
  END IF;

  INSERT INTO public.cashier_rpc_operation_intents(
    operation_id, actor_user_id, action, club_id, operation_intent, intent_fingerprint
  ) VALUES (
    p_operation, v_actor, p_action, p_club, p_intent, md5(p_intent::text)
  );
  RETURN jsonb_build_object('state', 'proceed');
END
$function$

public.fn_cashier_operation_intent_guard.def:
CREATE OR REPLACE FUNCTION public.fn_cashier_operation_intent_guard()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE
  v_operation uuid;
  v_owner uuid;
  v_action text;
  v_expected_type text;
BEGIN
  IF NEW.metadata ->> 'op_id' IS NULL THEN RETURN NEW; END IF;
  BEGIN
    v_operation := (NEW.metadata ->> 'op_id')::uuid;
  EXCEPTION WHEN invalid_text_representation THEN
    RETURN NEW;
  END;

  PERFORM pg_advisory_xact_lock(hashtextextended(
    'cashier-exact-intent:' || v_operation, 0));
  SELECT actor_user_id, action INTO v_owner, v_action
    FROM public.cashier_rpc_operation_intents
   WHERE operation_id = v_operation;
  IF NOT FOUND THEN RETURN NEW; END IF;

  v_expected_type := CASE v_action
    WHEN 'club_bank_send' THEN 'club_bank_send'
    WHEN 'club_bank_claim' THEN 'club_bank_claim'
    WHEN 'club_bank_reversal' THEN 'club_bank_reversal'
    WHEN 'admin_removal' THEN 'admin_removal'
    WHEN 'promo_wallet_send' THEN 'promo_wallet_send'
    WHEN 'club_promo_send' THEN 'club_promo_send'
    WHEN 'agent_wallet_send' THEN 'agent_wallet_send'
    WHEN 'cashier_player_send' THEN 'peer_transfer'
    WHEN 'agent_wallet_claim_back' THEN 'agent_wallet_claim_back'
  END;
  IF v_owner IS DISTINCT FROM auth.uid()
     OR v_expected_type IS NULL
     OR NEW.transaction_type IS DISTINCT FROM v_expected_type THEN
    RAISE EXCEPTION 'cashier_retry_key_reused_across_actions' USING ERRCODE = '23505';
  END IF;
  RETURN NEW;
END
$function$

public.fn_check_club_message_permission(.def:
CREATE OR REPLACE FUNCTION public.fn_check_club_message_permission()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'public', 'extensions'
AS $function$
DECLARE
    conv_category TEXT;
    conv_club_id UUID;
BEGIN
    -- Get conversation details
    SELECT category, club_id INTO conv_category, conv_club_id
    FROM conversations
    WHERE id = NEW.conversation_id;

    -- If not a club conversation, allow (personal messages have different rules)
    IF conv_category != 'club' OR conv_club_id IS NULL THEN
        RETURN NEW;
    END IF;

    -- Check permission
    IF NOT fn_can_message_in_club(NEW.sender_id, NEW.receiver_id, conv_club_id) THEN
        RAISE EXCEPTION 'Not authorized to message this user in this club';
    END IF;

    RETURN NEW;
END;
$function$

public.fn_close_club_wallets_on_union_jo.def:
CREATE OR REPLACE FUNCTION public.fn_close_club_wallets_on_union_join(p_club_id uuid, p_union_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE
  v_spin jsonb;
  v_bbj_main numeric := 0; v_bbj_backup numeric := 0; v_bbj_promo numeric := 0;
  v_bbj_total numeric := 0; v_club_promo numeric := 0;
  v_keep_main numeric; v_keep_backup numeric; v_pool_id uuid; v_union_pool uuid; v_after numeric; v_treasury numeric;
  v_saved jsonb;
BEGIN
  IF p_club_id IS NULL OR p_union_id IS NULL OR p_club_id = p_union_id THEN
    RETURN jsonb_build_object('ok', true, 'reason', 'nothing_to_close');
  END IF;

  v_spin := public.fn_spin_absorb_club_pool_into_union(p_club_id, p_union_id);

  SELECT id, COALESCE(main_balance,0), COALESCE(backup_balance,0), COALESCE(promo_balance,0)
    INTO v_pool_id, v_bbj_main, v_bbj_backup, v_bbj_promo
    FROM public.bbj_pools
   WHERE club_id = p_club_id AND union_id IS NULL
   FOR UPDATE;

  IF v_pool_id IS NOT NULL THEN
    v_keep_main := public.fn_bbj_parked_reserve(v_pool_id,'main');
    v_keep_backup := public.fn_bbj_parked_reserve(v_pool_id,'backup');
    v_bbj_main := v_bbj_main-v_keep_main;
    v_bbj_backup := v_bbj_backup-v_keep_backup;
    IF v_bbj_main<0 OR v_bbj_backup<0 THEN
      RAISE EXCEPTION 'club jackpot bank cannot cover its parked obligations';
    END IF;
    v_bbj_total := v_bbj_main + v_bbj_backup + v_bbj_promo;
    SELECT id INTO v_union_pool FROM public.bbj_pools WHERE union_id = p_union_id LIMIT 1;

    /* THE JACKPOT BANK PAYS THE TREASURY, BY NAME (2026-10-02,
       20261002140203). One leg, BBJ pool -> club treasury; the pool's own
       journal stands down for the sweep below instead of booking a second
       leg. */
    v_saved := public.fn_ca_ledger_declaration_save(ARRAY['bbj_pools']);
    PERFORM public.fn_ca_declare_ledger('treasury_transfer', 'bbj_pool', v_pool_id,
                                        NULL, NULL, ARRAY['bbj_pools']);

    IF v_bbj_total > 0 THEN
      v_after := public.fn_spin_move_owner_wallet(p_club_id, 'club', 'chip_treasury', v_bbj_total);
      IF v_after IS NULL THEN
        RAISE EXCEPTION 'cannot pay the % BBJ balance of club % into its treasury', v_bbj_total, p_club_id;
      END IF;

      -- bbj_promo_sweep so fn_bbj_conservation_check counts this as OUTFLOW.
      -- Without this row the gap moves by exactly v_bbj_total and a correct
      -- transfer reads as a money leak.
      INSERT INTO public.chip_transactions
        (id, club_id, amount, transaction_type, notes, balance_after, metadata)
      VALUES (gen_random_uuid(), p_club_id, v_bbj_total, 'bbj_promo_sweep',
              format('BBJ, backup and promo closed into the club main bank on joining union %s - the club keeps these funds. Play moves to the union pool; this money does not.', p_union_id),
              v_after,
              jsonb_build_object('reason','union_join','union_id',p_union_id,
                                 'bbj_main',v_bbj_main,'bbj_backup',v_bbj_backup,
                                 'bbj_promo',v_bbj_promo,'club_pool_id',v_pool_id));
    END IF;

    UPDATE public.bbj_pools
       SET main_balance = v_keep_main, backup_balance = v_keep_backup, promo_balance = 0,
           status = 'retired',
           merged_into_pool_id = COALESCE(merged_into_pool_id, v_union_pool),
           updated_at = now()
     WHERE id = v_pool_id;

    PERFORM public.fn_ca_ledger_declaration_restore(v_saved);
  END IF;

  SELECT COALESCE(promo_balance,0) INTO v_club_promo
    FROM public.clubs WHERE id = p_club_id FOR UPDATE;

  IF v_club_promo > 0 THEN
    /* THE PROMO FLOAT PAYS THE TREASURY, BY NAME (2026-10-02,
       20261002140203). Two statements so each column is journalled once:
       the promo float is emptied under a declared club_treasury counterparty
       (one leg, promo wallet -> club treasury), then the treasury is
       credited with the clubs journal stood down. */
    v_saved := public.fn_ca_ledger_declaration_save(ARRAY['clubs']);
    PERFORM public.fn_ca_declare_ledger('treasury_transfer', 'club_treasury', p_club_id);

    UPDATE public.clubs
       SET promo_balance = 0
     WHERE id = p_club_id;

    PERFORM set_config('app.ledger_autoskip_clubs', '1', true);

    UPDATE public.clubs
       SET chip_treasury = COALESCE(chip_treasury,0) + v_club_promo
     WHERE id = p_club_id
     RETURNING chip_treasury INTO v_treasury;

    PERFORM public.fn_ca_ledger_declaration_restore(v_saved);

    INSERT INTO public.chip_transactions
      (id, club_id, amount, transaction_type, notes, balance_after, metadata)
    VALUES (gen_random_uuid(), p_club_id, v_club_promo, 'promo_closed_on_union_join',
            format('Club promo float closed into the main bank on joining union %s - the club keeps these funds to disburse at its own discretion', p_union_id),
            v_treasury,
            jsonb_build_object('reason','union_join','union_id',p_union_id));
  END IF;

  RETURN jsonb_build_object('ok', true, 'club_id', p_club_id, 'union_id', p_union_id,
    'spins', v_spin, 'bbj_swept', v_bbj_total, 'club_promo_swept', v_club_promo,
    'club_treasury_after', COALESCE(v_treasury, v_after));
END;
$function$

public.fn_club_bank_send(p_club_id uuid,.def:
CREATE OR REPLACE FUNCTION public.fn_club_bank_send(p_club_id uuid, p_to_user_id uuid, p_amount numeric, p_destination text DEFAULT 'agent_wallet'::text, p_reason text DEFAULT NULL::text, p_op_id uuid DEFAULT NULL::uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE
  v_intent jsonb := jsonb_build_object(
    'actor', auth.uid(), 'club', p_club_id, 'action', 'club_bank_send',
    'target', p_to_user_id, 'amount', p_amount,
    'effective_wallet', lower(coalesce(p_destination, 'agent_wallet')),
    'reason', coalesce(nullif(btrim(p_reason), ''), 'Club Bank Send'));
  v_gate jsonb; v_result jsonb;
BEGIN
  IF p_op_id IS NULL THEN RETURN jsonb_build_object('success', false, 'error', 'A Retry Key Is Required'); END IF;
  v_gate := public.fn_cashier_exact_intent_begin('club_bank_send', p_club_id, p_op_id, v_intent);
  IF v_gate ->> 'state' = 'return' THEN RETURN v_gate -> 'response'; END IF;
  IF p_club_id IS NOT NULL THEN
    PERFORM pg_advisory_xact_lock(hashtextextended('agent-agreement:' || p_club_id::text, 0));
  END IF;
  v_result := public.fn_club_bank_send_core_20261004(p_club_id, p_to_user_id, p_amount, p_destination, p_reason, p_op_id);
  RETURN public.fn_cashier_exact_intent_finish(p_op_id, v_result);
END
$function$

public.fn_club_bank_send_core_20261004(p.def:
CREATE OR REPLACE FUNCTION public.fn_club_bank_send_core_20261004(p_club_id uuid, p_to_user_id uuid, p_amount numeric, p_destination text DEFAULT 'agent_wallet'::text, p_reason text DEFAULT NULL::text, p_op_id uuid DEFAULT NULL::uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare
  v_actor        uuid := auth.uid();
  v_actor_role   text;
  v_dest         text := lower(coalesce(p_destination, 'agent_wallet'));
  v_op_id        uuid := coalesce(p_op_id, gen_random_uuid());
  v_prior        record;
  v_bank_before  numeric;
  v_bank_after   numeric;
  v_to_role      text;
  v_to_after     numeric;
  v_agent_id     uuid;
  v_tx_id        uuid;
begin
  if v_actor is null then
    return jsonb_build_object('success', false, 'error', 'Not Authenticated');
  end if;

  v_actor_role := public.fn_club_bank_role(p_club_id);
  if v_actor_role is null or v_actor_role not in ('owner', 'co_owner', 'admin') then
    return jsonb_build_object('success', false,
      'error', 'Only An Owner, Co Owner Or Admin May Send From The Club Bank');
  end if;

  select id, amount, metadata into v_prior
    from chip_transactions
   where club_id = p_club_id
     and transaction_type = 'club_bank_send'
     and from_user_id = v_actor
     and metadata ->> 'op_id' = v_op_id::text
   limit 1;
  if found then
    return jsonb_build_object(
      'success', true, 'replayed', true,
      'transaction_id', v_prior.id,
      'amount', v_prior.amount,
      'destination', v_prior.metadata ->> 'destination',
      'bank_after', (v_prior.metadata ->> 'bank_after')::numeric,
      'recipient_balance_after', (v_prior.metadata ->> 'recipient_balance_after')::numeric);
  end if;

  if p_amount is null or p_amount <= 0 then
    return jsonb_build_object('success', false, 'error', 'Amount Must Be Greater Than Zero');
  end if;
  if p_amount <> round(p_amount, 2) then
    return jsonb_build_object('success', false,
      'error', 'Chips Move In Hundredths At Most');
  end if;
  if p_amount > 1e9 then
    return jsonb_build_object('success', false, 'error', 'Amount Exceeds The Single Send Limit');
  end if;
  if v_dest not in ('agent_wallet', 'promo_wallet', 'player_wallet') then
    return jsonb_build_object('success', false, 'error', 'Unknown Destination Wallet');
  end if;
  if p_to_user_id is null then
    return jsonb_build_object('success', false, 'error', 'Choose A Recipient');
  end if;

  select cm.role into v_to_role
    from club_members cm
   where cm.club_id = p_club_id
     and cm.user_id = p_to_user_id
     and coalesce(cm.status, 'active') in ('active', 'approved')
   for update;
  if v_to_role is null then
    return jsonb_build_object('success', false, 'error', 'Recipient Is Not An Active Member Of This Club');
  end if;
  if v_dest in ('agent_wallet', 'promo_wallet')
     and v_to_role not in ('owner', 'co_owner', 'admin', 'super_agent', 'agent', 'sub_agent') then
    return jsonb_build_object('success', false,
      'error', 'Only Staff Or Agents Hold An Agent Wallet');
  end if;
  -- Dan 2026-09-02: "ALL CLUB OWNERS AND CO-OWNERS SHOULD HAVE A PLAYER
  -- WALLET (ADMIN'S SHOULD NOT)". A player-wallet credit to an admin lands in
  -- a balance no surface shows them, so it is refused here rather than
  -- stranded.
  if v_dest = 'player_wallet' and v_to_role = 'admin' then
    return jsonb_build_object('success', false,
      'error', 'An Admin Does Not Hold A Player Wallet');
  end if;

  if p_to_user_id <> v_actor
     and not public.fn_club_cashier_can_transact(p_club_id, v_actor, p_to_user_id) then
    return jsonb_build_object('success', false,
      'error', 'That Member Is Not In Your Downline');
  end if;

  select coalesce(c.chip_treasury, 0) into v_bank_before
    from clubs c where c.id = p_club_id for update;
  if v_bank_before is null then
    return jsonb_build_object('success', false, 'error', 'Club Not Found');
  end if;
  if v_bank_before < p_amount then
    return jsonb_build_object('success', false, 'error', 'Insufficient Club Bank Balance',
      'balance', v_bank_before, 'requested', p_amount);
  end if;

  -- CHIP STANDARD 2.4 (2026-09-03): a club bank send is ONE journal row from
  -- the bank to the wallet that receives it. Undeclared, the two balance
  -- writes landed as `adjustment club_treasury -> settlement_suspense` plus
  -- `adjustment settlement_suspense -> agent_wallet` (or `table_stack ->
  -- player_wallet`), unkeyed and uncorrelated (3,750,000.00 on 2026-09-01
  -- 14:02:19 journaled exactly so). The clubs trigger is skipped for this
  -- write; the receiving wallet's trigger writes the row with the bank as its
  -- counterparty, keyed and correlated on the op. Never a refusal: a journal
  -- miss falls back inside the trigger, the money moves as before.
  perform public.fn_ca_declare_ledger('club_bank_send', 'club_treasury', p_club_id, null,
    'club_bank_send:' || v_op_id::text, array['clubs']);
  perform set_config('app.ledger_correlation', v_op_id::text, true);

  update clubs
     set chip_treasury = coalesce(chip_treasury, 0) - p_amount,
         updated_at = now()
   where id = p_club_id
   returning chip_treasury into v_bank_after;

  if v_dest = 'player_wallet' then
    update club_members
       set chip_balance = coalesce(chip_balance, 0) + p_amount,
           updated_at = now()
     where club_id = p_club_id and user_id = p_to_user_id
     returning chip_balance into v_to_after;
  else
    v_agent_id := public.fn_ensure_agent_row(p_club_id, p_to_user_id, v_to_role);
    if v_agent_id is null then
      raise exception 'could not ensure agents row for % in club %', p_to_user_id, p_club_id;
    end if;

    if v_dest = 'agent_wallet' then
      update agents
         set agent_wallet_balance = coalesce(agent_wallet_balance, 0) + p_amount,
             updated_at = now()
       where id = v_agent_id
       returning agent_wallet_balance into v_to_after;
    else
      update agents
         set promo_wallet_balance = coalesce(promo_wallet_balance, 0) + p_amount,
             updated_at = now()
       where id = v_agent_id
       returning promo_wallet_balance into v_to_after;
    end if;
  end if;
  perform set_config('app.ledger_autoskip_clubs', '', true);

  insert into chip_transactions
    (club_id, from_user_id, to_user_id, amount, transaction_type, notes, metadata,
     balance_after, reversible_until)
  values
    (p_club_id, v_actor, p_to_user_id, p_amount, 'club_bank_send',
     coalesce(nullif(btrim(p_reason), ''), 'Club Bank Send'),
     jsonb_build_object(
       'op_id', v_op_id,
       'destination', v_dest,
       'actor_role', v_actor_role,
       'recipient_role', v_to_role,
       'bank_before', v_bank_before,
       'bank_after', v_bank_after,
       'recipient_balance_after', v_to_after),
     v_bank_after, now() + interval '7 days')
  returning id into v_tx_id;

  return jsonb_build_object(
    'success', true,
    'replayed', false,
    'transaction_id', v_tx_id,
    'op_id', v_op_id,
    'amount', p_amount,
    'destination', v_dest,
    'bank_before', v_bank_before,
    'bank_after', v_bank_after,
    'recipient_balance_after', v_to_after);
exception
  when unique_violation then
    select id, amount, metadata into v_prior
      from chip_transactions
     where club_id = p_club_id
       and transaction_type = 'club_bank_send'
       and from_user_id = v_actor
       and metadata ->> 'op_id' = v_op_id::text
     limit 1;
    if v_prior.id is null then
      raise;
    end if;
    return jsonb_build_object(
      'success', true, 'replayed', true,
      'transaction_id', v_prior.id,
      'amount', v_prior.amount,
      'destination', v_prior.metadata ->> 'destination',
      'bank_after', (v_prior.metadata ->> 'bank_after')::numeric,
      'recipient_balance_after', (v_prior.metadata ->> 'recipient_balance_after')::numeric);
end
$function$

public.fn_club_grantable_roles(p_club_id.def:
CREATE OR REPLACE FUNCTION public.fn_club_grantable_roles(p_club_id uuid, p_actor_user_id uuid, p_target_user_id uuid)
 RETURNS text[]
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE
  v_actor_role  text;
  v_target_role text;
  v_platform_admin boolean := false;
BEGIN
  -- A browser can establish only its own actor. Trusted service/management
  -- calls with no user JWT retain the existing actor-based business contract.
  IF auth.uid() IS NOT NULL AND p_actor_user_id IS DISTINCT FROM auth.uid() THEN RETURN '{}'; END IF;
  IF p_actor_user_id IS NULL OR p_target_user_id IS NULL THEN RETURN '{}'; END IF;

  -- Nobody edits their own title. An owner demoting themselves would leave a
  -- club with no owner; anyone else would simply be promoting themselves.
  IF p_actor_user_id = p_target_user_id THEN RETURN '{}'; END IF;

  SELECT role INTO v_actor_role FROM club_members
   WHERE club_id = p_club_id AND user_id = p_actor_user_id
     AND status IN ('active','approved');

  SELECT role INTO v_target_role FROM club_members
   WHERE club_id = p_club_id AND user_id = p_target_user_id
     AND status IN ('active','approved');

  IF v_target_role IS NULL THEN RETURN '{}'; END IF;

  SELECT COALESCE(is_admin, false) INTO v_platform_admin
    FROM profiles WHERE id = p_actor_user_id;

  IF v_actor_role IS NULL AND NOT v_platform_admin THEN RETURN '{}'; END IF;

  -- The club owner is not demotable through this path. Handing over a club is
  -- a deliberate act of its own, not a dropdown on the members list.
  IF v_target_role = 'owner' THEN RETURN '{}'; END IF;

  IF v_platform_admin OR v_actor_role = 'owner' THEN
    RETURN ARRAY['co_owner','admin','super_agent','agent','sub_agent','player'];
  END IF;

  IF v_actor_role IN ('co_owner','admin') THEN
    -- "as high as admin". A co-owner outranks an admin but may not appoint or
    -- remove another co-owner; only the owner does that.
    IF fn_club_role_rank(v_target_role) >= fn_club_role_rank(v_actor_role) THEN
      RETURN '{}';
    END IF;
    RETURN ARRAY['admin','super_agent','agent','sub_agent','player'];
  END IF;

  -- A super agent manages the whole ladder beneath it, inside its own
  -- downline: agent, sub agent, player -- in either direction. It may not
  -- mint another super agent; that is owner / co-owner / admin work.
  IF v_actor_role = 'super_agent' THEN
    IF v_target_role IN ('player','agent','sub_agent')
       AND fn_club_is_in_downline(p_club_id, p_actor_user_id, p_target_user_id) THEN
      RETURN ARRAY['agent','sub_agent','player'];
    END IF;
    RETURN '{}';
  END IF;

  -- An agent may raise a player of theirs to sub agent, and put them back.
  IF v_actor_role = 'agent' THEN
    IF v_target_role IN ('player','sub_agent')
       AND fn_club_is_in_downline(p_club_id, p_actor_user_id, p_target_user_id) THEN
      RETURN ARRAY['sub_agent','player'];
    END IF;
    RETURN '{}';
  END IF;

  -- sub agents and players promote nobody
  RETURN '{}';
END;
$function$

public.fn_club_member_notes_guard().def:
CREATE OR REPLACE FUNCTION public.fn_club_member_notes_guard()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
BEGIN
  IF NEW.nickname IS NOT DISTINCT FROM OLD.nickname
     AND NEW.notes IS NOT DISTINCT FROM OLD.notes THEN
    RETURN NEW;
  END IF;

  IF coalesce(auth.role(), 'service_role') = 'service_role'
     OR current_setting('app.club_notes_update', true) = 'on' THEN
    RETURN NEW;
  END IF;

  RAISE EXCEPTION USING ERRCODE = '42501',
    MESSAGE = 'Member Notes Must Be Updated Through ca_club_member_notes_update';
END;
$function$

public.fn_club_members_ledger_writer().def:
CREATE OR REPLACE FUNCTION public.fn_club_members_ledger_writer()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_original_ledger uuid;
  d     numeric;
  actor uuid;
  cat   text;
  tid   uuid;
  st    text;
  msg   text;
  cp    text;
  cpid  uuid;
  cplbl text;
BEGIN
  /* THE AUTOSKIP CONTRACT IS ONE CONTRACT (2026-09-09). Every other journal
     writer on this platform stands down when the caller sets
     app.ledger_autoskip_<table>, because the caller is writing the leg itself
     with the period, the key and the metadata that only it knows. This writer
     never learned that clause. So a settlement that suppressed the clubs
     trigger and wrote its own named leg still got an anonymous twin from this
     side, and the movement reached the journal twice: on 2026-09-09 round 2
     moved 20,377.49 of commission and recorded 40,754.98 of legs. Standing
     down here is what makes one movement, one leg true for the busiest
     balance column on the platform. */
  IF current_setting('app.ledger_autoskip_club_members', true) = '1' THEN
    RETURN NEW;
  END IF;

  d := COALESCE(NEW.chip_balance, 0) - COALESCE(OLD.chip_balance, 0);

  IF d = 0 THEN
    RETURN NEW;
  END IF;

  actor := COALESCE(auth.uid(), '2d1cd6c3-5700-4af9-a271-d4863fdab20d'::uuid);

  cat := COALESCE(NULLIF(current_setting('app.ledger_category', true), ''), 'adjustment');

  /* RAKEBACK IS NOT JOURNALLED FROM HERE (2026-09-21). This trigger takes the
     category from app.ledger_category and the counterparty from
     app.ledger_counterparty, and it knows no period, certificate, payout row,
     settlement run or document. On 2026-09-14 that produced 420 anonymous
     rakeback legs moving 84,041.00 into 420 player wallets with no invoice, no
     receipt and no run to tie them to. Rakeback is paid by
     public.fn_settle_accounting_rakeback_stage, which stands this journal down
     with app.ledger_autoskip_club_members and writes its own leg carrying all
     of those facts. A caller that reaches this line with rakeback declared is
     by construction a caller that has none of them, so it refuses instead of
     minting an anonymous twin. The 420 historical rows are left exactly as
     they are. */
  IF cat = 'rakeback' THEN
    RAISE EXCEPTION 'rakeback_requires_accounting_authority'
      USING ERRCODE = '42501',
            DETAIL  = 'club_members.chip_balance moved under app.ledger_category=rakeback outside public.fn_settle_accounting_rakeback_stage',
            HINT    = 'The weekly accounting authority stands this journal down with app.ledger_autoskip_club_members and writes its own documented, period- and run-identified rakeback leg.';
  END IF;

  BEGIN
    tid := NULLIF(current_setting('app.ledger_tournament', true), '')::uuid;
  EXCEPTION WHEN OTHERS THEN
    tid := NULL;
  END;

  /* THE COUNTERPARTY IS DECLARED, NEVER INFERRED (2026-08-31). */
  cp := COALESCE(NULLIF(current_setting('app.ledger_counterparty', true), ''), 'settlement_suspense');
  BEGIN
    cpid := NULLIF(current_setting('app.ledger_counterparty_entity', true), '')::uuid;
  EXCEPTION WHEN OTHERS THEN
    cpid := NULL;
  END;

  cplbl := NULLIF(current_setting('app.ledger_counterparty_label', true), '');
  cplbl := CASE
    WHEN cp = 'union_wallet' AND cplbl LIKE 'union_wallets.%' THEN cplbl
    WHEN cp = 'promo_wallet' AND cplbl IN ('clubs.promo_balance', 'agents.promo_wallet_balance',
                                           'union_wallets.promo_wallet') THEN cplbl
    ELSE NULL END;

  BEGIN
    INSERT INTO public.chip_ledger
      (performed_by, from_type, from_entity_id, from_label, to_type, to_entity_id, to_label,
       amount, category, club_id, tournament_id, description)
    VALUES (
      actor,
      CASE WHEN d > 0 THEN cp              ELSE 'player_wallet' END,
      CASE WHEN d > 0 THEN cpid            ELSE NEW.user_id     END,
      CASE WHEN d > 0 THEN cplbl ELSE 'club_members.chip_balance' END,
      CASE WHEN d > 0 THEN 'player_wallet' ELSE cp              END,
      CASE WHEN d > 0 THEN NEW.user_id     ELSE cpid            END,
      CASE WHEN d > 0 THEN 'club_members.chip_balance' ELSE cplbl END,
      abs(d), cat, NEW.club_id, tid,
      'auto-audited club_members.chip_balance delta ' || d::text)
    RETURNING id INTO v_original_ledger;
    -- Private original-debit callers read this immediately after their UPDATE.
    PERFORM set_config('app.cash_original_debit_ledger',v_original_ledger::text,true);

  EXCEPTION WHEN OTHERS THEN
      -- A journal failure must abort the enclosing chip movement.
      -- Preserve SQLSTATE so the existing caller can retry the whole operation.
      RAISE;
    END;

  RETURN NEW;
END;
$function$

public.fn_club_members_no_agent_cycle().def:
CREATE OR REPLACE FUNCTION public.fn_club_members_no_agent_cycle()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare
  v_cursor uuid;
  v_hops   int := 0;
begin
  if new.agent_id is null then
    return new;
  end if;

  if new.agent_id = new.user_id then
    raise exception
      'club_members.agent_id: a member cannot be their own upline (club %, member %)',
      new.club_id, new.user_id
      using errcode = '23514';
  end if;

  v_cursor := new.agent_id;
  while v_cursor is not null and v_hops < 64 loop
    if v_cursor = new.user_id then
      raise exception
        'club_members.agent_id: % cannot sit under % - that would close a cycle in club %',
        new.user_id, new.agent_id, new.club_id
        using errcode = '23514';
    end if;
    select cm.agent_id
      into v_cursor
      from public.club_members cm
     where cm.club_id = new.club_id
       and cm.user_id = v_cursor;
    if not found then
      exit;
    end if;
    v_hops := v_hops + 1;
  end loop;

  if v_hops >= 64 then
    raise exception
      'club_members.agent_id: the upline chain above % is deeper than 64 levels or already loops',
      new.agent_id
      using errcode = '23514';
  end if;

  return new;
end
$function$

public.fn_club_members_staff_earn_no_rak.def:
CREATE OR REPLACE FUNCTION public.fn_club_members_staff_earn_no_rakeback()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'public'
AS $function$
BEGIN
  -- Dan 2026-08-31: "CO-OWNERS AND ADMINS GET NO RAKE BACK."
  -- player_rakeback_pct is the first branch of fn_player_rakeback_rate, so a
  -- non-zero value here is money. owner is deliberately not covered.
  NEW.player_rakeback_pct := 0;
  NEW.rakeback_rate       := 0;
  NEW.commission_rate     := 0;
  RETURN NEW;
END;
$function$

public.fn_club_opening_checklist_complet.def:
CREATE OR REPLACE FUNCTION public.fn_club_opening_checklist_complete(p_club_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE
  v_uid uuid := auth.uid();
  v_club public.clubs%ROWTYPE;
  v_row public.club_opening_checklists%ROWTYPE;
  v_skipped text[] := '{}'::text[];
  v_unfinished text[] := '{}'::text[];
BEGIN
  IF v_uid IS NULL THEN RAISE EXCEPTION 'Sign In To Finish The Opening Checklist' USING ERRCODE='42501'; END IF;
  SELECT * INTO v_club FROM public.clubs c WHERE c.id=p_club_id FOR SHARE;
  IF NOT FOUND THEN RAISE EXCEPTION 'Club Not Found' USING ERRCODE='P0002'; END IF;
  IF v_club.owner_id IS DISTINCT FROM v_uid THEN RAISE EXCEPTION 'Only The Club Owner Can Finish The Opening Checklist' USING ERRCODE='42501'; END IF;
  SELECT * INTO v_row FROM public.club_opening_checklists k WHERE k.club_id=p_club_id FOR UPDATE;
  IF FOUND AND v_row.completed_at IS NOT NULL THEN
    RETURN jsonb_build_object('clubId',p_club_id,'completedAt',v_row.completed_at,'skippedTaskIds',to_jsonb(v_row.skipped_task_ids));
  END IF;
  IF NOT COALESCE(public.fn_club_opening_checklist_eligible(p_club_id),false) THEN RAISE EXCEPTION 'This Club Has No Opening Checklist' USING ERRCODE='55000'; END IF;
  IF NOT EXISTS(SELECT 1 FROM public.club_opening_setups s WHERE s.club_id=p_club_id) THEN RAISE EXCEPTION 'Complete The Opening Setup Wizard First' USING ERRCODE='55000'; END IF;
  v_skipped:=COALESCE(v_row.skipped_task_ids,'{}'::text[]);
  IF NOT('identity'=ANY(v_skipped)) AND NOT(
    (NULLIF(btrim(COALESCE(v_club.logo_url,'')),'') IS NOT NULL AND v_club.logo_url !~* '(^|/)club-logos/preset-[0-9]+[.](webp|png|jpe?g)([?#].*)?$')
    OR (NULLIF(btrim(COALESCE(v_club.avatar_url,'')),'') IS NOT NULL AND v_club.avatar_url !~* '(^|/)club-logos/preset-[0-9]+[.](webp|png|jpe?g)([?#].*)?$')
  ) THEN v_unfinished:=array_append(v_unfinished,'identity'); END IF;
  IF NOT('tagline'=ANY(v_skipped)) AND NULLIF(btrim(COALESCE(v_club.tagline,'')),'') IS NULL THEN v_unfinished:=array_append(v_unfinished,'tagline'); END IF;
  IF NOT('nlh'=ANY(v_skipped)) AND NOT EXISTS(SELECT 1 FROM public.tables t WHERE t.club_id=p_club_id AND lower(COALESCE(t.game_variant,'')) IN('nlh','short_deck','pineapple') AND lower(COALESCE(t.status,'')) NOT IN('deleted','archived')) THEN v_unfinished:=array_append(v_unfinished,'nlh'); END IF;
  IF NOT('plo'=ANY(v_skipped)) AND NOT EXISTS(SELECT 1 FROM public.tables t WHERE t.club_id=p_club_id AND lower(COALESCE(t.game_variant,'')) LIKE 'plo%' AND lower(COALESCE(t.status,'')) NOT IN('deleted','archived')) THEN v_unfinished:=array_append(v_unfinished,'plo'); END IF;
  IF NOT('limit'=ANY(v_skipped)) AND NOT EXISTS(SELECT 1 FROM public.tables t WHERE t.club_id=p_club_id AND (lower(COALESCE(t.game_variant,'')) IN('flh','flo8') OR lower(COALESCE(t.game_variant,'')) LIKE 'limit%') AND lower(COALESCE(t.status,'')) NOT IN('deleted','archived')) THEN v_unfinished:=array_append(v_unfinished,'limit'); END IF;
  IF NOT('mtt'=ANY(v_skipped)) AND NOT EXISTS(SELECT 1 FROM public.tournaments t WHERE t.club_id=p_club_id AND t.format_contract IN('mtt-v1','mtt-v2')) THEN v_unfinished:=array_append(v_unfinished,'mtt'); END IF;
  IF NOT('spin'=ANY(v_skipped)) AND NOT EXISTS(SELECT 1 FROM public.tournaments t WHERE t.club_id=p_club_id AND t.format_contract='spin-v1') THEN v_unfinished:=array_append(v_unfinished,'spin'); END IF;
  IF NOT('heads-up'=ANY(v_skipped)) AND NOT EXISTS(SELECT 1 FROM public.tournaments t WHERE t.club_id=p_club_id AND t.format_contract='sng-v1') THEN v_unfinished:=array_append(v_unfinished,'heads-up'); END IF;
  IF NOT('first-player'=ANY(v_skipped)) AND NOT EXISTS(SELECT 1 FROM public.club_members m WHERE m.club_id=p_club_id AND m.user_id IS DISTINCT FROM v_club.owner_id AND m.status::text IN('active','approved')) THEN v_unfinished:=array_append(v_unfinished,'first-player'); END IF;
  IF NOT('first-agent'=ANY(v_skipped)) AND NOT EXISTS(SELECT 1 FROM public.agents a WHERE a.club_id=p_club_id AND lower(COALESCE(a.status,'active'))<>'inactive') THEN v_unfinished:=array_append(v_unfinished,'first-agent'); END IF;
  IF cardinality(v_unfinished)>0 THEN RAISE EXCEPTION 'Finish Or Skip Every Opening Checklist Step: %',array_to_string(v_unfinished,', ') USING ERRCODE='55000'; END IF;
  INSERT INTO public.club_opening_checklists AS k(club_id,completed_at,completed_by) VALUES(p_club_id,now(),v_uid)
  ON CONFLICT(club_id) DO UPDATE SET completed_at=now(),completed_by=v_uid,updated_at=now() WHERE k.completed_at IS NULL;
  SELECT * INTO v_row FROM public.club_opening_checklists k WHERE k.club_id=p_club_id;
  RETURN jsonb_build_object('clubId',p_club_id,'completedAt',v_row.completed_at,'skippedTaskIds',to_jsonb(v_row.skipped_task_ids));
END
$function$

public.fn_club_owner_has_a_player_wallet.def:
CREATE OR REPLACE FUNCTION public.fn_club_owner_has_a_player_wallet()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE v_previous text := COALESCE(current_setting('app.club_membership_source', true), '');
BEGIN
  -- THE ARENA BELONGS TO THE SYSTEM (2026-09-30): only a chip club gives its
  -- owner a player wallet. Diamond participation is automatic and holds no
  -- wallet (the arena's membership guard refuses any other row), so for the
  -- Diamond Arena this trigger would refuse every change of owner at commit.
  IF NEW.owner_id IS NULL OR COALESCE(NEW.is_union, false) OR NEW.asset IS DISTINCT FROM 'chips' THEN RETURN NULL; END IF;
  IF TG_OP = 'UPDATE' AND OLD.owner_id IS NOT DISTINCT FROM NEW.owner_id THEN
    RETURN NULL;
  END IF;

  IF EXISTS (SELECT 1 FROM public.club_members cm
              WHERE cm.club_id = NEW.id AND cm.user_id = NEW.owner_id) THEN
    UPDATE public.club_members
       SET status = CASE WHEN COALESCE(status, 'active') IN ('active', 'approved') THEN status ELSE 'active' END,
           role   = CASE WHEN role IN ('owner', 'co_owner') THEN role ELSE 'owner' END,
           updated_at = now()
     WHERE club_id = NEW.id AND user_id = NEW.owner_id
       AND (COALESCE(status, 'active') NOT IN ('active', 'approved') OR role NOT IN ('owner', 'co_owner'));
    RETURN NULL;
  END IF;

  PERFORM set_config('app.club_membership_source', 'club_owner_create', true);
  PERFORM set_config('app.club_role_change', 'on', true);
  BEGIN
    INSERT INTO public.club_members (club_id, user_id, role, status, chip_balance)
    VALUES (NEW.id, NEW.owner_id, 'owner', 'active', 0)
    ON CONFLICT (club_id, user_id) DO NOTHING;
  EXCEPTION WHEN OTHERS THEN
    PERFORM set_config('app.club_membership_source', v_previous, true);
    RAISE;
  END;
  PERFORM set_config('app.club_membership_source', v_previous, true);
  RETURN NULL;
END;
$function$

public.fn_club_set_member_role(p_club_id.def:
CREATE OR REPLACE FUNCTION public.fn_club_set_member_role(p_club_id uuid, p_user_id uuid, p_role text, p_actor_user_id uuid DEFAULT NULL::uuid, p_commission_rate numeric DEFAULT NULL::numeric, p_player_rakeback_rate numeric DEFAULT NULL::numeric, p_is_prepaid boolean DEFAULT NULL::boolean, p_credit_limit numeric DEFAULT NULL::numeric)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_actor      uuid;
  v_old_role   text;
  v_actor_role text;
  v_allowed    text[];
  v_downline   int;
  v_agent_id   uuid;
  v_parent     uuid;
  v_set_upline boolean := false;
  v_is_agent   boolean;
  v_is_staff   boolean;
  v_comm       numeric;
  v_rake       numeric;
  v_prepaid    boolean;
  v_limit      numeric;
  v_have_row   boolean := false;
  v_fresh      boolean;
  v_cap_comm   numeric;
  v_cap_rake   numeric;
  v_cap_limit  numeric;
  v_float      numeric;
  v_owed       numeric;
  v_commission numeric;
  v_keeps_wallet boolean;
  v_club_name  text;
  v_label      text;
BEGIN
  -- Serialize the existing agreement before any operation/hierarchy/row lock.
  -- Nested callers reacquire the same transaction lock; no new money path.
  IF p_club_id IS NOT NULL THEN
    PERFORM pg_advisory_xact_lock(hashtextextended('agent-agreement:'||p_club_id::text,0));
  END IF;

  -- IDENTITY. auth.uid() is the ONLY identity a browser can establish; it is
  -- NULL for anon, and a NULL here used to mean "believe p_actor_user_id".
  -- A caller-supplied actor is now accepted from a trusted backend only.
  v_actor := auth.uid();
  IF v_actor IS NULL THEN
    IF COALESCE(auth.role(), 'service_role') = 'service_role'
       AND p_actor_user_id IS NOT NULL THEN
      v_actor := p_actor_user_id;
    ELSE
      RETURN jsonb_build_object('success', false, 'error', 'actor identity required');
    END IF;
  END IF;

  IF p_role IS NULL OR p_role NOT IN
     ('co_owner','admin','super_agent','agent','sub_agent','player') THEN
    RETURN jsonb_build_object('success', false, 'error', 'invalid role: ' || COALESCE(p_role,'null'));
  END IF;

  v_is_agent := p_role IN ('super_agent','agent','sub_agent');
  v_is_staff := p_role IN ('co_owner','admin');

  IF NOT v_is_agent
     AND (COALESCE(p_commission_rate, 0) <> 0 OR COALESCE(p_player_rakeback_rate, 0) <> 0) THEN
    RETURN jsonb_build_object('success', false,
      'error', CASE WHEN v_is_staff
                    THEN 'co owners and admins receive no rakeback, so no rate may be set for one'
                    ELSE 'only an agent role carries a commission or rakeback rate' END);
  END IF;

  -- Funding belongs to an agent role. Sending it with a demotion to player, or
  -- with a promotion to staff, is a caller mistake worth naming rather than
  -- quietly ignoring: it usually means the wrong role reached this call.
  IF NOT v_is_agent AND (p_is_prepaid IS NOT NULL OR p_credit_limit IS NOT NULL) THEN
    RETURN jsonb_build_object('success', false,
      'error', 'only an agent role is funded prepaid or on a credit line');
  END IF;

  SELECT role INTO v_old_role FROM club_members
   WHERE club_id = p_club_id AND user_id = p_user_id
     AND status IN ('active','approved')
   FOR UPDATE;

  IF v_old_role IS NULL THEN
    RETURN jsonb_build_object('success', false, 'error', 'target is not a member of this club');
  END IF;

  IF v_old_role = p_role THEN
    RETURN jsonb_build_object('success', true, 'unchanged', true, 'role', p_role);
  END IF;

  v_allowed := fn_club_grantable_roles(p_club_id, v_actor, p_user_id);
  IF NOT (p_role = ANY (v_allowed)) THEN
    RETURN jsonb_build_object('success', false, 'error', 'not permitted to set this role',
      'allowed', COALESCE(to_jsonb(v_allowed), '[]'::jsonb));
  END IF;

  SELECT role INTO v_actor_role FROM club_members
   WHERE club_id = p_club_id AND user_id = v_actor AND status IN ('active','approved');

  IF fn_club_role_rank(v_old_role) > fn_club_role_rank(p_role)
     AND v_old_role IN ('super_agent','agent','sub_agent') THEN
    SELECT count(*) INTO v_downline FROM club_members
     WHERE club_id = p_club_id AND agent_id = p_user_id;
    IF v_downline > 0 THEN
      RETURN jsonb_build_object('success', false,
        'error', 'this member still has ' || v_downline || ' player'
                 || CASE WHEN v_downline = 1 THEN '' ELSE 's' END
                 || ' reporting to them. Move them to another agent first.',
        'downline_count', v_downline);
    END IF;
  END IF;

  v_set_upline := v_actor_role IN ('super_agent','agent')
                  AND p_role IN ('agent','sub_agent');

  -- ---------------------------------------------------------------------------
  -- A DEMOTION MUST NOT STRAND MONEY
  -- ---------------------------------------------------------------------------
  -- Every role except 'player' may hold an agent wallet - Dan, 2026-08-31:
  -- "OWNERS AND CO OWNERS CAN AND SHOULD HAVE AGENT WALLETS." So moving an
  -- agent up to co-owner, or sideways to another agent tier, strands nothing:
  -- the wallet goes with them and they can still spend it.
  --
  -- Becoming a PLAYER is the one move that takes the wallet away.
  -- fn_club_bank_role then returns 'player', fn_agent_wallet_send refuses them
  -- outright, and fn_agent_wallet_claim_back with it - so whatever the row still
  -- holds becomes chips nobody can move and nobody is watching. 67 of the 111
  -- active agents hold float today, 6,726,000 chips between them.
  --
  -- The remedy already exists and is named in the refusal:
  -- fn_club_bank_claim_back pulls the float back into the club bank, keyed on an
  -- op_id and written to the ledger, and any owner, co-owner, admin or super
  -- agent may run it. A debt is not sweepable and must be settled instead -
  -- fn_apply_credit_payment pays credit_used down when the invoice is paid.
  v_keeps_wallet := p_role <> 'player';

  -- PHASE 7. What the club still owes this person, from the ledger the claim
  -- path settles - rather than from the agents column that migration drops,
  -- which nothing ever wrote. It said 26,859.87 across 5 agents on a day the
  -- ledger held 408,809.59 across 114, so 109 of those 114 were reported to the
  -- person changing their role as owed nothing at all. One partial-index lookup
  -- (agent_commissions_unsettled_idx).
  -- reads the ledger directly: this function has already authorized its
  -- actor through fn_club_grantable_roles above, and it is SECURITY DEFINER,
  -- so it does not need the guarded caller-facing RPC's door. That RPC now
  -- admits only self, club admin and above, an agent ancestor, or the
  -- service role, and THIS report must not be able to fail on it. Same
  -- SELECT, same partial index (agent_commissions_unsettled_idx).
  SELECT COALESCE(SUM(ac.amount), 0)::numeric INTO v_commission
    FROM public.agent_commissions ac
   WHERE ac.club_id = p_club_id
     AND ac.user_id = p_user_id
     AND ac.settled_at IS NULL AND NOT public.fn_agent_commission_paid_by_period(ac.club_id, ac.user_id, ac.created_at);

  -- v_old_role was checked against the three AGENT tiers here, which missed the
  -- people phase 2 deliberately gave wallets to. A co-owner or an admin holds an
  -- agent wallet by design - Dan: "OWNERS AND CO OWNERS CAN AND SHOULD HAVE
  -- AGENT WALLETS" - so demoting one straight to player took the wallet away
  -- with the float still in it, which is the exact defect this phase exists to
  -- stop. Any role that is not already 'player' can be holding one.
  IF NOT v_keeps_wallet AND v_old_role <> 'player' THEN
    SELECT COALESCE(a.agent_wallet_balance, 0), greatest(COALESCE(a.credit_used, 0), CASE WHEN NOT COALESCE(a.is_prepaid,false) THEN greatest(a.credit_limit-a.agent_wallet_balance,0) ELSE 0 END)
      INTO v_float, v_owed
      FROM agents a
     WHERE a.club_id = p_club_id AND a.user_id = p_user_id;

    IF COALESCE(v_float, 0) > 0 OR COALESCE(v_owed, 0) > 0 THEN
      -- Name only what is actually outstanding. "holds 5,000 chips and owes
      -- 0.00" invites somebody to go looking for a debt that is not there.
      RETURN jsonb_build_object('success', false, 'needs_settlement', true,
        'error', 'this member cannot become a player yet: '
                 || CASE WHEN COALESCE(v_float, 0) > 0 AND COALESCE(v_owed, 0) > 0
                         THEN 'their agent wallet still holds '
                              || trim(to_char(v_float, 'FM999,999,999,990.00'))
                              || ' chips, and they still owe '
                              || trim(to_char(v_owed, 'FM999,999,999,990.00'))
                              || '. Claim the chips back into the club bank and settle the debt first.'
                         WHEN COALESCE(v_float, 0) > 0
                         THEN 'their agent wallet still holds '
                              || trim(to_char(v_float, 'FM999,999,999,990.00'))
                              || ' chips. Claim them back into the club bank first, '
                              || 'because a player cannot spend an agent wallet.'
                         ELSE 'they still owe '
                              || trim(to_char(v_owed, 'FM999,999,999,990.00'))
                              || ' on their credit line. Settle the invoice first.'
                    END,
        'agent_wallet_balance', COALESCE(v_float, 0),
        'credit_used', COALESCE(v_owed, 0),
        'unclaimed_commission', COALESCE(v_commission, 0));
    END IF;
  END IF;

  IF v_is_agent THEN
    SELECT a.commission_rate, a.player_rakeback_rate, a.is_prepaid, a.credit_limit
      INTO v_comm, v_rake, v_prepaid, v_limit
      FROM agents a
     WHERE a.club_id = p_club_id AND a.user_id = p_user_id;
    v_have_row := FOUND;

    -- B-01, Dan 2026-08-31: FORCE A FRESH CHOICE.
    --
    -- A member whose current club role is not an agent tier is being PROMOTED.
    -- Their agents row may still hold the commission, rakeback and credit line
    -- they carried before they were demoted, and a commercial term nobody has
    -- re-agreed does not come back by default - "getting this wrong costs
    -- money" was the whole of the question put to Dan. So on a promotion every
    -- term is taken from this call and from nowhere else.
    --
    -- Re-GRADING an existing agent (agent to super agent) is a different act:
    -- their terms are live, not stale, and carrying them forward when the
    -- caller sends nothing is what every existing caller already relies on.
    v_fresh := v_old_role NOT IN ('super_agent','agent','sub_agent');

    IF v_fresh THEN
      v_comm    := p_commission_rate;
      -- The agent sets what their own players receive (Dan, 2026-10-15).
      -- A promotion that does not name it starts it at 0 until they do.
      v_rake    := COALESCE(p_player_rakeback_rate, 0);
      v_prepaid := p_is_prepaid;
      v_limit   := p_credit_limit;
    ELSE
      v_comm    := COALESCE(p_commission_rate, v_comm);
      v_rake    := COALESCE(p_player_rakeback_rate, v_rake);
      v_prepaid := COALESCE(p_is_prepaid, v_prepaid);
      v_limit   := COALESCE(p_credit_limit, v_limit);
    END IF;

    IF v_comm IS NULL OR v_rake IS NULL THEN
      RETURN jsonb_build_object('success', false, 'needs_rates', true,
        'error', 'a commission rate and a player rakeback rate must be chosen when granting an agent role');
    END IF;
    IF v_comm < 0 OR v_comm > 0.70 THEN
      RETURN jsonb_build_object('success', false, 'error', 'the commission rate must be between 0 and 0.70');
    END IF;
    IF v_rake < 0 OR v_rake > 0.50 THEN
      RETURN jsonb_build_object('success', false, 'error', 'the player rakeback rate must be between 0 and 0.50');
    END IF;
    IF v_rake > v_comm THEN
      RETURN jsonb_build_object('success', false,
        'error', 'the player rakeback rate cannot exceed the commission rate it is paid out of');
    END IF;

    -- Dan, 2026-08-31: "WHEN A AGENT IS PROMOTED ... THEY ALSO NEED TO BE
    -- ASSIGNED 'PRE PAID' OR CREDIT LINE, (AND IF SO, THEN HOW MUCH)".
    -- Before this, every promotion hardcoded credit_limit 0 and left is_prepaid
    -- at its column default of false, which is the one combination that can
    -- send nothing at all: not prepaid, and no line to draw on. Three agents
    -- are in exactly that state on production today.
    IF v_prepaid IS NULL THEN
      RETURN jsonb_build_object('success', false, 'needs_funding', true,
        'error', 'choose prepaid or a credit line when granting an agent role');
    END IF;
    IF v_prepaid THEN
      IF COALESCE(v_limit, 0) <> 0 THEN
        RETURN jsonb_build_object('success', false,
          'error', 'a prepaid agent carries no credit line, so the limit must be 0');
      END IF;
      v_limit := 0;
    ELSE
      IF v_limit IS NULL THEN
        RETURN jsonb_build_object('success', false, 'needs_funding', true,
          'error', 'a credit agent needs a credit limit');
      END IF;
      IF v_limit <= 0 THEN
        RETURN jsonb_build_object('success', false,
          'error', 'a credit line must be greater than 0, or the agent should be prepaid');
      END IF;
    END IF;

    IF v_set_upline THEN
      SELECT id, commission_rate, player_rakeback_rate, credit_limit
        INTO v_parent, v_cap_comm, v_cap_rake, v_cap_limit
        FROM agents WHERE club_id = p_club_id AND user_id = v_actor;
    ELSIF v_have_row THEN
      SELECT p.commission_rate, p.player_rakeback_rate, p.credit_limit
        INTO v_cap_comm, v_cap_rake, v_cap_limit
        FROM agents a JOIN agents p ON p.id = a.parent_agent_id
       WHERE a.club_id = p_club_id AND a.user_id = p_user_id;
    END IF;

    IF v_cap_comm IS NOT NULL AND v_comm > v_cap_comm THEN
      RETURN jsonb_build_object('success', false,
        'error', 'the commission rate cannot exceed the upline rate of ' || v_cap_comm);
    END IF;
    -- No upline cap on the PLAYER rakeback (Dan, 2026-10-15): it is paid out
    -- of this agent's own commission, which is checked against it above.
    -- An upline cannot lend downward what it does not itself hold.
    IF v_cap_limit IS NOT NULL AND v_limit > v_cap_limit THEN
      RETURN jsonb_build_object('success', false,
        'error', 'the credit limit cannot exceed the upline limit of ' || v_cap_limit);
    END IF;
  END IF;

  PERFORM set_config('app.club_role_change', 'on', true);

  UPDATE club_members
     SET role                = p_role,
         agent_id            = CASE WHEN v_set_upline THEN v_actor ELSE agent_id END,
         player_rakeback_pct = CASE WHEN v_is_staff THEN 0 ELSE player_rakeback_pct END,
         rakeback_rate       = CASE WHEN v_is_staff THEN 0 ELSE rakeback_rate END,
         commission_rate     = CASE WHEN v_is_staff THEN 0 ELSE commission_rate END,
         updated_at          = now()
   WHERE club_id = p_club_id AND user_id = p_user_id;

  PERFORM set_config('app.club_role_change', '', true);

  IF v_is_agent THEN
    SELECT id INTO v_agent_id FROM agents
     WHERE club_id = p_club_id AND user_id = p_user_id;

    IF v_agent_id IS NOT NULL THEN
      UPDATE agents
         SET role = p_role, status = 'active',
             parent_agent_id = COALESCE(v_parent, parent_agent_id),
             commission_rate = v_comm, player_rakeback_rate = v_rake,
             is_prepaid = v_prepaid, credit_limit = v_limit,
             updated_at = now()
       WHERE id = v_agent_id;
    ELSE
      INSERT INTO agents (club_id, user_id, role, status, parent_agent_id,
                          commission_rate, player_rakeback_rate,
                          is_prepaid, credit_limit, credit_used)
      VALUES (p_club_id, p_user_id, p_role, 'active', v_parent, v_comm, v_rake,
              v_prepaid, v_limit, 0)
      RETURNING id INTO v_agent_id;
    END IF;
  ELSE
    -- Suspend the row only when the member can no longer hold a wallet. A
    -- promotion to co-owner or admin used to suspend it too, which contradicted
    -- the rule that staff hold agent wallets and left the club bank funding a
    -- row marked inactive.
    -- Active while they can hold a wallet, suspended when they cannot. Keyed on
    -- the role they are BECOMING, for the same reason the guard above is: a
    -- co-owner demoted to player left an ACTIVE agents row behind, so a player
    -- still read as an agent - fn_player_rakeback_rate joins that row on
    -- status = 'active'.
    UPDATE agents
       SET status = CASE WHEN p_role = 'player' AND v_old_role <> 'player'
                         THEN 'suspended' ELSE status END,
           commission_rate      = CASE WHEN v_is_staff THEN 0 ELSE commission_rate END,
           player_rakeback_rate = CASE WHEN v_is_staff THEN 0 ELSE player_rakeback_rate END,
           updated_at = now()
     WHERE club_id = p_club_id AND user_id = p_user_id;
  END IF;

  INSERT INTO audit_trail (actor_id, actor_role, action, target_type, target_id,
                           club_id, before_state, after_state, reason)
  VALUES (v_actor, COALESCE(v_actor_role, 'platform_admin'), 'set_member_role',
          'club_member', p_user_id, p_club_id,
          jsonb_build_object('role', v_old_role),
          jsonb_build_object('role', p_role, 'upline_set', v_set_upline,
                             'commission_rate', v_comm, 'player_rakeback_rate', v_rake,
                             'is_prepaid', v_prepaid, 'credit_limit', v_limit,
                             'funding_rechosen', COALESCE(v_fresh, false)),
          'Role changed via fn_club_set_member_role');

  -- ---------------------------------------------------------------------------
  -- TELL THE PERSON IT HAPPENED
  -- ---------------------------------------------------------------------------
  -- Until now the only announcement was masterBus.emit('MEMBER_ROLE_CHANGED'),
  -- a browser-local event. It reaches the tabs of whoever performed the change
  -- and nobody else, so the person whose role actually changed found out when a
  -- button appeared or vanished. notifications is the estate's real channel:
  -- 11,362 rows, four RLS policies, rendered by NotificationDropdown, the
  -- header store and NotificationsPage.
  --
  -- Failing to notify must never fail the role change. The role is the fact;
  -- the notice is a courtesy, and a courtesy that can roll back a promotion is
  -- worse than no courtesy at all.
  SELECT name INTO v_club_name FROM clubs WHERE id = p_club_id;
  v_label := CASE p_role
               WHEN 'co_owner' THEN 'Co Owner'
               WHEN 'admin' THEN 'Admin'
               WHEN 'super_agent' THEN 'Super Agent'
               WHEN 'agent' THEN 'Agent'
               WHEN 'sub_agent' THEN 'Sub Agent'
               ELSE 'Player'
             END;
  BEGIN
    PERFORM public.fn_raise_notification(
      p_user_id,
      'club_role_changed',
      'Your Role Changed In ' || COALESCE(v_club_name, 'Your Club'),
      'You Are Now ' || v_label || '.'
        || CASE WHEN v_is_agent
                THEN ' Your Commission Is ' || trim(to_char(v_comm * 100, 'FM990.00'))
                     || ' Percent. You Set The Rakeback Your Players Receive, Now '
                     || trim(to_char(v_rake * 100, 'FM990.00')) || ' Percent.'
                     || CASE WHEN v_prepaid THEN ' You Are Prepaid.'
                             ELSE ' Your Credit Line Is '
                                  || trim(to_char(v_limit, 'FM999,999,999,990.00')) || ' Chips.'
                        END
                ELSE '' END,
      '/clubs/' || p_club_id::text,
      jsonb_build_object(
        'club_id', p_club_id, 'old_role', v_old_role, 'new_role', p_role,
        'commission_rate', v_comm, 'player_rakeback_rate', v_rake,
        'is_prepaid', v_prepaid, 'credit_limit', v_limit));
  EXCEPTION WHEN OTHERS THEN
    -- Swallowed on purpose, and only here. The role change is already durable.
    NULL;
  END;

  RETURN jsonb_build_object('success', true, 'old_role', v_old_role, 'new_role', p_role,
    'commission_rate', v_comm, 'player_rakeback_rate', v_rake,
    'is_prepaid', v_prepaid, 'credit_limit', v_limit,
    -- Commission the CLUB owes THEM. It does not block the demotion: the agents
    -- row survives with the figure intact, so nothing is lost by moving the
    -- role, and there is no payout path to send them to yet (phase 6 builds
    -- one). Blocking here would strand the club, not the money. Reported so the
    -- caller can say it out loud rather than discover it later.
    'unclaimed_commission', COALESCE(v_commission, 0),
    'reports_to', CASE WHEN v_set_upline THEN v_actor ELSE NULL END);
END;
$function$

public.fn_club_set_member_status(p_club_.def:
CREATE OR REPLACE FUNCTION public.fn_club_set_member_status(p_club_id uuid, p_user_id uuid, p_status text, p_reason text DEFAULT NULL::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
 SET lock_timeout TO '5s'
AS $function$
DECLARE
  v_actor          uuid := auth.uid();
  v_status         text := lower(btrim(COALESCE(p_status, '')));
  v_reason         text := NULLIF(btrim(COALESCE(p_reason, '')), '');
  v_owner          uuid;
  v_platform_admin boolean := false;
  v_staff          boolean := false;
  v_actor_role     text;
  v_target         public.club_members%ROWTYPE;
  v_old            text;
  v_changed        integer := 0;
  v_audit_id       uuid;
BEGIN
  -- IDENTITY. auth.uid() only; a caller cannot name someone else as the actor.
  IF v_actor IS NULL THEN
    RETURN jsonb_build_object('success', false, 'error', 'Sign In To Change A Member''s Status');
  END IF;
  IF p_club_id IS NULL OR p_user_id IS NULL THEN
    RETURN jsonb_build_object('success', false, 'error', 'Choose A Club Member');
  END IF;
  IF v_status NOT IN ('active', 'suspended', 'banned') THEN
    RETURN jsonb_build_object('success', false,
      'error', 'A Member Can Only Be Set Active, Suspended Or Banned');
  END IF;
  IF length(v_reason) > 500 THEN
    RETURN jsonb_build_object('success', false, 'error', 'Keep The Reason Under 500 Characters');
  END IF;
  IF p_user_id = v_actor THEN
    RETURN jsonb_build_object('success', false,
      'error', 'You Cannot Change Your Own Membership Status');
  END IF;

  -- Same lock order as fn_remove_settled_club_member: hierarchy lock, club
  -- row, then both membership rows by user id.
  PERFORM pg_advisory_xact_lock(hashtextextended('cashier-hierarchy:' || p_club_id::text, 0));

  SELECT c.owner_id INTO v_owner FROM public.clubs c WHERE c.id = p_club_id FOR UPDATE;
  IF NOT FOUND THEN
    RETURN jsonb_build_object('success', false, 'error', 'That Club No Longer Exists');
  END IF;

  PERFORM 1 FROM public.club_members cm
   WHERE cm.club_id = p_club_id AND cm.user_id IN (v_actor, p_user_id)
   ORDER BY cm.user_id
   FOR UPDATE;

  -- AUTHORITY, read after the locks so a concurrent demotion lands first.
  SELECT COALESCE(p.is_admin, false) INTO v_platform_admin
    FROM public.profiles p WHERE p.id = v_actor;
  v_platform_admin := COALESCE(v_platform_admin, false);
  v_staff := COALESCE(public.is_club_admin(p_club_id, v_actor), false);

  SELECT cm.role INTO v_actor_role
    FROM public.club_members cm
   WHERE cm.club_id = p_club_id AND cm.user_id = v_actor
     AND cm.status::text IN ('active', 'approved');
  IF v_actor = v_owner THEN
    v_actor_role := 'owner';
  END IF;

  IF NOT v_staff AND NOT v_platform_admin THEN
    RETURN jsonb_build_object('success', false,
      'error', 'Only Club Staff Can Suspend, Ban Or Reinstate A Member');
  END IF;

  SELECT * INTO v_target
    FROM public.club_members cm
   WHERE cm.club_id = p_club_id AND cm.user_id = p_user_id;
  IF NOT FOUND THEN
    RETURN jsonb_build_object('success', false, 'error', 'That Person Is Not A Member Of This Club');
  END IF;
  IF v_target.membership_lifecycle_status = 'departed' THEN
    RETURN jsonb_build_object('success', false,
      'error', 'This Member Has Left The Club And Must Rejoin First');
  END IF;

  -- The owner is never suspended or banned through this path, by anyone.
  IF p_user_id = v_owner OR v_target.role = 'owner' THEN
    RETURN jsonb_build_object('success', false,
      'error', 'The Club Owner''s Membership Cannot Be Suspended Or Banned');
  END IF;

  -- A co-owner or admin acts only on members ranked below them, exactly as
  -- fn_club_grantable_roles limits their role changes.
  IF NOT v_platform_admin AND v_actor_role IS DISTINCT FROM 'owner'
     AND public.fn_club_role_rank(v_target.role) >= public.fn_club_role_rank(v_actor_role) THEN
    RETURN jsonb_build_object('success', false,
      'error', 'Staff Can Only Change The Status Of Members Ranked Below Them');
  END IF;

  v_old := COALESCE(v_target.status::text, 'active');

  IF v_old = 'pending' THEN
    RETURN jsonb_build_object('success', false,
      'error', 'Approve Or Deny This Join Request Instead');
  END IF;
  IF v_old NOT IN ('active', 'approved', 'suspended', 'banned') THEN
    RETURN jsonb_build_object('success', false,
      'error', 'This Membership Cannot Be Changed From Its Current State');
  END IF;

  IF v_old = v_status OR (v_status = 'active' AND v_old = 'approved') THEN
    RETURN jsonb_build_object('success', true, 'unchanged', true, 'user_id', p_user_id,
      'old_status', v_old, 'new_status', v_old);
  END IF;

  PERFORM set_config('app.club_status_change', 'on', true);
  UPDATE public.club_members cm
     SET status = v_status,
         updated_at = now()
   WHERE cm.club_id = p_club_id
     AND cm.user_id = p_user_id
     AND cm.status IS NOT DISTINCT FROM v_target.status;
  GET DIAGNOSTICS v_changed = ROW_COUNT;
  PERFORM set_config('app.club_status_change', '', true);

  IF v_changed <> 1 THEN
    RAISE EXCEPTION 'membership changed during status change' USING ERRCODE = '55000';
  END IF;

  INSERT INTO public.audit_trail (actor_id, actor_role, action, target_type, target_id,
                                  club_id, before_state, after_state, reason)
  VALUES (v_actor,
          CASE WHEN v_staff AND v_actor_role IN ('owner', 'co_owner', 'admin') THEN v_actor_role
               ELSE 'platform_admin' END,
          'set_member_status', 'club_member', p_user_id, p_club_id,
          jsonb_build_object('status', v_old, 'role', v_target.role),
          jsonb_build_object('status', v_status),
          COALESCE(v_reason, 'No Reason Given'))
  RETURNING id INTO v_audit_id;

  RETURN jsonb_build_object('success', true, 'unchanged', false, 'user_id', p_user_id,
    'old_status', v_old, 'new_status', v_status, 'audit_id', v_audit_id,
    'reason', COALESCE(v_reason, 'No Reason Given'));
END;
$function$

public.fn_club_staff_notice_role_event().def:
CREATE OR REPLACE FUNCTION public.fn_club_staff_notice_role_event()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'extensions'
AS $function$
BEGIN
 IF TG_TABLE_NAME='clubs' THEN
  PERFORM public.fn_sync_club_staff_notice_group(NEW.id); RETURN NULL;
 END IF;
 IF TG_OP<>'DELETE' THEN PERFORM public.fn_sync_club_staff_notice_group(NEW.club_id); END IF;
 IF TG_OP='DELETE' OR (TG_OP='UPDATE' AND OLD.club_id IS DISTINCT FROM NEW.club_id) THEN PERFORM public.fn_sync_club_staff_notice_group(OLD.club_id); END IF;
 RETURN NULL;
END $function$

public.fn_clubs_lobby_message_keeps_its_.def:
CREATE OR REPLACE FUNCTION public.fn_clubs_lobby_message_keeps_its_own_books()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'public', 'pg_temp'
AS $function$
BEGIN
  -- Whitespace is not a message. One rule, applied before any writer's own.
  IF NEW.lobby_message IS NOT NULL AND btrim(NEW.lobby_message) = '' THEN
    NEW.lobby_message := NULL;
  END IF;

  IF TG_OP = 'INSERT' THEN
    NEW.lobby_message_updated_at := CASE
      WHEN NEW.lobby_message IS NULL THEN NULL
      ELSE COALESCE(NEW.lobby_message_updated_at, now())
    END;
    RETURN NEW;
  END IF;

  IF NEW.lobby_message IS DISTINCT FROM OLD.lobby_message THEN
    NEW.lobby_message_updated_at := CASE
      WHEN NEW.lobby_message IS NULL THEN NULL
      ELSE now()
    END;
    -- A writer that bumped the revision in this same statement is left alone.
    -- One that forgot is corrected, which is the difference between a message
    -- rewritten from Club Settings reaching a player who dismissed the last
    -- one, and that message never reaching them at all.
    IF NEW.message_revision IS NOT DISTINCT FROM OLD.message_revision THEN
      NEW.message_revision := COALESCE(OLD.message_revision, 0) + 1;
    END IF;
  END IF;

  RETURN NEW;
END;
$function$

public.fn_create_agent(p_user_id uuid, p.def:
CREATE OR REPLACE FUNCTION public.fn_create_agent(p_user_id uuid, p_club_id uuid, p_role text, p_parent_agent_id uuid, p_commission_rate numeric, p_player_rakeback_rate numeric, p_credit_limit numeric, p_is_prepaid boolean)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'extensions'
AS $function$
DECLARE
  v_caller uuid := (SELECT auth.uid());
  v_membership_user uuid; v_member_role text;
  v_parent_role text; v_parent_comm numeric; v_parent_rake numeric; v_parent_limit numeric;
  v_new_id uuid; v_role_res jsonb;
  v_is_staff boolean; v_comm numeric; v_rake numeric; v_prepaid boolean;
BEGIN
  IF p_user_id IS NULL OR p_club_id IS NULL THEN RETURN jsonb_build_object('success',false,'error','user and club required'); END IF;
  IF v_caller IS NULL THEN RETURN jsonb_build_object('success',false,'error','authentication required'); END IF;
  PERFORM pg_advisory_xact_lock(hashtextextended('agent-agreement:'||p_club_id::text,0));
  IF NOT EXISTS (SELECT 1 FROM clubs c WHERE c.id=p_club_id AND (c.owner_id=v_caller
     OR EXISTS (SELECT 1 FROM club_members cm WHERE cm.club_id=p_club_id AND cm.user_id=v_caller AND cm.role IN ('owner','co_owner','admin') AND cm.status IN ('active','approved')))) THEN
    RETURN jsonb_build_object('success',false,'error','not authorized to manage this club''s agents'); END IF;
  IF p_role IS NULL OR p_role NOT IN ('super_agent','agent','sub_agent') THEN RETURN jsonb_build_object('success',false,'error','invalid role'); END IF;
  IF p_commission_rate IS NULL OR p_commission_rate < 0 OR p_commission_rate > 0.7 THEN RETURN jsonb_build_object('success',false,'error','commission rate must be 0-0.7'); END IF;
  IF p_player_rakeback_rate < 0 OR p_player_rakeback_rate > 0.5 THEN RETURN jsonb_build_object('success',false,'error','rakeback rate must be 0-0.5'); END IF;
  IF p_credit_limit IS NULL OR p_credit_limit::text IN ('NaN','Infinity','-Infinity') OR p_credit_limit < 0 OR p_credit_limit <> round(p_credit_limit,2) THEN RETURN jsonb_build_object('success',false,'error','credit_limit must be finite, nonnegative and in whole chip cents'); END IF;
  IF EXISTS (SELECT 1 FROM agents WHERE user_id=p_user_id AND club_id=p_club_id) THEN RETURN jsonb_build_object('success',false,'error','already an agent in this club'); END IF;

  SELECT user_id, role INTO v_membership_user, v_member_role
    FROM club_members WHERE club_id=p_club_id AND user_id=p_user_id;

  -- Dan, 2026-08-31: "OWNERS AND CO OWNERS CAN AND SHOULD HAVE AGENT WALLETS,
  -- THAT WAS A MISTAKE."
  --
  -- PR #2132 refused outright here, on the reasoning that staff earn no
  -- rakeback so making one an agent is a demotion wearing a create button. That
  -- conflated two separate things. The agents row is BOTH the commission
  -- profile AND the agent wallet, and Dan's chip flow - main bank to agent
  -- wallet to agents and players - requires an owner or a co-owner to hold one.
  -- What they must not get is a rate, and what they must not lose is their
  -- title. Both are handled below instead of refusing the whole operation.
  v_is_staff := v_member_role IN ('owner','co_owner','admin');

  -- Owners keep earning (Dan, B-02, 2026-08-31). A co-owner and an admin do
  -- not, so their wallet is minted at zero rather than at whatever the caller
  -- typed; trg_agents_staff_earn_no_rakeback would zero it anyway, and doing it
  -- here means the row and the request agree instead of silently differing.
  IF v_member_role IN ('co_owner','admin') THEN
    v_comm := 0;
    v_rake := 0;
  ELSE
    v_comm := p_commission_rate;
    -- The agent sets what their own players receive (Dan, 2026-10-15).
    v_rake := COALESCE(p_player_rakeback_rate, 0);
    IF v_rake > v_comm THEN RETURN jsonb_build_object('success',false,'error','the player rakeback rate cannot exceed the commission it is paid out of'); END IF;
  END IF;

  -- Prepaid or a line, and how much. There is no third option, and the pair
  -- that means "can send nothing at all" is refused rather than stored.
  v_prepaid := COALESCE(p_is_prepaid, false);
  IF v_prepaid AND p_credit_limit <> 0 THEN
    RETURN jsonb_build_object('success',false,'error','a prepaid agent carries no credit line, so the limit must be 0');
  END IF;
  IF NOT v_prepaid AND p_credit_limit <= 0 THEN
    RETURN jsonb_build_object('success',false,'needs_funding',true,
      'error','choose prepaid, or give a credit limit greater than 0');
  END IF;

  IF p_parent_agent_id IS NOT NULL THEN
    SELECT role, commission_rate, player_rakeback_rate, credit_limit
      INTO v_parent_role, v_parent_comm, v_parent_rake, v_parent_limit
      FROM agents WHERE id=p_parent_agent_id AND club_id=p_club_id AND status='active';
    IF v_parent_role IS NULL THEN RETURN jsonb_build_object('success',false,'error','parent agent not found'); END IF;
    IF v_parent_role = 'sub_agent' THEN RETURN jsonb_build_object('success',false,'error','sub-agents cannot have sub-agents'); END IF;
    IF v_comm > v_parent_comm THEN RETURN jsonb_build_object('success',false,'error','commission rate cannot exceed parent rate'); END IF;
    IF v_parent_limit IS NOT NULL AND p_credit_limit > v_parent_limit THEN
      RETURN jsonb_build_object('success',false,'error','credit limit cannot exceed parent agent limit'); END IF;
  END IF;

  INSERT INTO agents (user_id, club_id, membership_id, role, parent_agent_id, commission_rate, player_rakeback_rate, credit_limit, credit_used, is_prepaid)
  VALUES (p_user_id, p_club_id, COALESCE(v_membership_user, p_user_id), p_role, p_parent_agent_id, v_comm, v_rake, p_credit_limit, 0, v_prepaid)
  RETURNING id INTO v_new_id;

  -- THE TITLE SURVIVES THE WALLET. Giving an owner an agent wallet must not
  -- write 'agent' over 'owner' in club_members - that is a demotion nobody
  -- asked for, and fn_club_grantable_roles would refuse it anyway (an owner is
  -- never demotable through this door), so the whole create would fail with a
  -- confusing permission error. Only a player being made into an agent has a
  -- club role to change.
  IF NOT v_is_staff AND v_membership_user IS NOT NULL AND v_member_role IS DISTINCT FROM p_role THEN
    v_role_res := public.fn_club_set_member_role(
      p_club_id, p_user_id, p_role, v_caller, v_comm, v_rake, v_prepaid, p_credit_limit);
    IF NOT COALESCE((v_role_res ->> 'success')::boolean, false) THEN
      RAISE EXCEPTION 'agent_role_change_refused' USING ERRCODE='PAG01';
    END IF;
  END IF;

  RETURN jsonb_build_object('success',true,'agent_id',v_new_id,
    'club_role_unchanged', v_is_staff, 'club_role', v_member_role);
EXCEPTION WHEN SQLSTATE 'PAG01' THEN
  -- This block rolls back the agent insert/update and every role-callee write.
  RETURN COALESCE(v_role_res,jsonb_build_object('success',false,'error','role change refused'));
END;
$function$

public.fn_credit_and_log(p_user_id uuid,.def:
CREATE OR REPLACE FUNCTION public.fn_credit_and_log(p_user_id uuid, p_amount numeric, p_idempotency_key text, p_category text, p_description text, p_related_entity_id uuid DEFAULT NULL::uuid, p_wallet_type text DEFAULT 'PLAYER'::text, p_table_id uuid DEFAULT NULL::uuid, p_hand_id uuid DEFAULT NULL::uuid, p_payout_position integer DEFAULT NULL::integer, p_payout_source text DEFAULT NULL::text)
 RETURNS boolean
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
 SET statement_timeout TO '30s'
AS $function$
DECLARE
  v_original_ledger uuid; v_original_wallet uuid;
  v_diamond boolean := false;  -- DIAMOND PHASE 8
  v_credited boolean;
  v_ledger_cat text;
  v_t record;
  v_field integer;
  v_shape_source text;
  v_shape_place integer;
  v_payout_source text;
  v_payout_place integer;
  v_payout_id uuid;
  v_existing_key record;
  v_key_existed boolean := false;
  v_evidence_count integer;
  v_prev_cp text;
  v_prev_cp_entity text;
BEGIN
  IF p_user_id IS NULL THEN
    RAISE EXCEPTION 'fn_credit_and_log requires a user id' USING ERRCODE = '22004';
  END IF;
  IF p_idempotency_key IS NULL OR length(btrim(p_idempotency_key)) = 0 THEN
    RAISE EXCEPTION 'fn_credit_and_log requires an idempotency key' USING ERRCODE = '22023';
  END IF;
  IF p_amount IS NULL
     OR p_amount::text IN ('NaN', 'Infinity', '-Infinity')
     OR p_amount <= 0
     OR p_amount IS DISTINCT FROM round(p_amount, 2) THEN
    RAISE EXCEPTION
      'fn_credit_and_log requires a finite positive whole-cent amount (got %)',
      p_amount USING ERRCODE = '22003';
  END IF;

  SELECT k.user_id, k.amount INTO v_existing_key
    FROM public.wallet_credit_idempotency k
   WHERE k.key = p_idempotency_key;
  v_key_existed := FOUND;
  IF v_key_existed
     AND (v_existing_key.user_id IS DISTINCT FROM p_user_id
       OR v_existing_key.amount IS NULL
       OR v_existing_key.amount::text IN ('NaN', 'Infinity', '-Infinity')
       OR v_existing_key.amount IS DISTINCT FROM p_amount) THEN
    RAISE EXCEPTION 'idempotency key % belongs to a different credit',
      p_idempotency_key USING ERRCODE = '23505';
  END IF;

  v_ledger_cat := CASE lower(COALESCE(p_category, ''))
                    WHEN 'prize' THEN 'tournament_prize'
                    WHEN 'buyin' THEN 'tournament_buyin'
                    WHEN '' THEN 'adjustment'
                    ELSE lower(p_category)
                  END;

  -- Resolve mandatory evidence before the wallet move. Explicit obligation
  -- metadata wins; legacy owner-only callers may still classify their key.
  IF lower(COALESCE(p_category, '')) = 'prize' THEN
    IF p_related_entity_id IS NULL THEN
      RAISE EXCEPTION 'a tournament prize requires a tournament id'
        USING ERRCODE = '23502';
    END IF;
    SELECT t.id, t.tournament_type, t.prize_pool, t.payout_structure
      INTO v_t FROM public.tournaments t
     WHERE t.id = p_related_entity_id;
    IF NOT FOUND THEN
      RAISE EXCEPTION 'tournament % does not exist for prize evidence',
        p_related_entity_id USING ERRCODE = '23503';
    END IF;
    SELECT s.source, s.place INTO v_shape_source, v_shape_place
      FROM public.fn_tournament_payout_shape(p_idempotency_key) s;
    v_payout_source := COALESCE(NULLIF(btrim(p_payout_source), ''),
                                v_shape_source);
    -- A payment whose kind is unknown is not allowed to move. This check is
    -- deliberately before fn_credit_player_wallet_once: the payout row and
    -- wallet credit are one transaction, but rejecting the unnamed path here
    -- also prevents an older catch-and-alert writer from ever treating a
    -- missing classification as non-fatal.
    IF v_payout_source IS NULL THEN
      RAISE EXCEPTION
        'tournament prize % has no recognized payout source',
        p_idempotency_key USING ERRCODE = '22023';
    END IF;
    IF v_payout_source NOT IN (
      'structure','reconcile','hu_shortfall','bounty','bounty_residual',
      'own_bounty','late_reg_adjustment','clawback','final_table_deal',
      'mystery_bounty','mystery_bounty_residual','spin_backpay',
      'overlay_backpay','bubble_protection','satellite_remainder',
      'satellite_seat','satellite_ticket','finish_position_correction','operator_abort_equal_share'
    ) THEN
      RAISE EXCEPTION
        'tournament prize % supplied unknown payout source %',
        p_idempotency_key, v_payout_source USING ERRCODE = '22023';
    END IF;
    v_payout_place := COALESCE(p_payout_position, v_shape_place);
    IF v_payout_place IS NOT NULL AND v_payout_place <= 0 THEN
      RAISE EXCEPTION 'prize evidence has invalid finish position %', v_payout_place
        USING ERRCODE = '22023';
    END IF;
    IF v_payout_source = 'structure' AND v_payout_place IS NULL THEN
      RAISE EXCEPTION 'a structure prize requires a finish position'
        USING ERRCODE = '23502';
    END IF;
    SELECT count(*) INTO v_field FROM public.tournament_players
     WHERE tournament_id = v_t.id;
  END IF;

  PERFORM set_config('app.ledger_category', v_ledger_cat, true);
  IF p_related_entity_id IS NOT NULL THEN
    PERFORM set_config('app.ledger_tournament', p_related_entity_id::text, true);
  END IF;
  v_prev_cp := current_setting('app.ledger_counterparty', true);
  v_prev_cp_entity := current_setting('app.ledger_counterparty_entity', true);
  IF p_related_entity_id IS NOT NULL
     AND v_ledger_cat IN ('tournament_prize','bounty','refund','tournament_refund') THEN
    PERFORM set_config('app.ledger_counterparty', 'prize_liability', true);
    PERFORM set_config('app.ledger_counterparty_entity', p_related_entity_id::text, true);
  END IF;

  -- DIAMOND PHASE 8: a Diamond event pays from its own custody, never from a
  -- club chip wallet. Same key, same obligation, same evidence row below.
  v_diamond := p_related_entity_id IS NOT NULL AND public.fn_poker_diamond_tournament(p_related_entity_id);
  IF v_diamond THEN
    -- DIAMOND PHASE 11: the payer answers a retry with its first receipt
    -- (true), so its answer no longer says whether THIS call paid. The key the
    -- payer names when it pays does: the call that paid writes the evidence
    -- below, and a retry takes the replay verification that follows, as before.
    PERFORM set_config('app.diamond_tournament_pay_claimed', '', true);
    IF public.fn_poker_diamond_tournament_pay(
         p_user_id, p_amount, p_idempotency_key, p_category, p_related_entity_id, p_description) IS NOT TRUE THEN
      RAISE EXCEPTION 'diamond tournament payment % answered no receipt', p_idempotency_key USING ERRCODE = 'P0404';
    END IF;
    v_credited := current_setting('app.diamond_tournament_pay_claimed', true) IS NOT DISTINCT FROM p_idempotency_key;
  ELSE
  PERFORM set_config('app.pnl_tournament_credit_ledger','',true);
  v_credited := public.fn_credit_player_wallet_once(
    p_user_id, p_amount, p_idempotency_key);
  v_original_ledger:=NULLIF(current_setting('app.pnl_tournament_credit_ledger',true),'')::uuid;
  END IF;

  PERFORM set_config('app.ledger_category', '', true);
  PERFORM set_config('app.ledger_tournament', '', true);
  PERFORM set_config('app.ledger_counterparty', COALESCE(v_prev_cp, ''), true);
  PERFORM set_config('app.ledger_counterparty_entity', COALESCE(v_prev_cp_entity, ''), true);

  IF NOT v_credited THEN
    -- The first snapshot is not authoritative here. Two same-key transactions
    -- can both see no row; the loser then waits on the unique index inside
    -- fn_credit_player_wallet_once and returns FALSE after the winner commits.
    -- Re-read in a new statement snapshot, after that wait, and accept only the
    -- exact committed key. A genuinely orphaned or mismatched claim still
    -- aborts the outer transaction.
    SELECT k.user_id, k.amount INTO v_existing_key
      FROM public.wallet_credit_idempotency k
     WHERE k.key = p_idempotency_key
     FOR SHARE;
    IF NOT FOUND THEN
      RAISE EXCEPTION
        'wallet credit % claimed its key but did not credit a wallet',
        p_idempotency_key USING ERRCODE = 'P0404';
    END IF;
    IF v_existing_key.user_id IS DISTINCT FROM p_user_id
       OR v_existing_key.amount IS NULL
       OR v_existing_key.amount::text IN ('NaN', 'Infinity', '-Infinity')
       OR v_existing_key.amount IS DISTINCT FROM p_amount THEN
      RAISE EXCEPTION 'idempotency key % belongs to a different credit',
        p_idempotency_key USING ERRCODE = '23505';
    END IF;
    IF lower(COALESCE(p_category, '')) = 'prize' THEN
      SELECT count(*) INTO v_evidence_count
        FROM public.tournament_payouts tp
       WHERE tp.idempotency_key = p_idempotency_key
         AND tp.tournament_id = p_related_entity_id
         AND tp.user_id = p_user_id
         AND tp.amount = p_amount
         AND tp."position" IS NOT DISTINCT FROM v_payout_place
         AND tp.source IS NOT DISTINCT FROM v_payout_source;
      IF v_evidence_count <> 1 THEN
        RAISE EXCEPTION
          'prize replay % has % exact payout rows, expected one',
          p_idempotency_key, v_evidence_count USING ERRCODE = 'P0404';
      END IF;
    END IF;
    RETURN false;
  END IF;

  IF NOT v_diamond THEN -- DIAMOND PHASE 8: wallet_transactions is the chip receipt
  PERFORM public.log_wallet_transaction(
    p_user_id, p_wallet_type, p_amount, 'credit', p_category, p_description,
    p_table_id, p_hand_id, p_related_entity_id);
  v_original_wallet:=NULLIF(current_setting('app.pnl_tournament_wallet_tx',true),'')::uuid;
  END IF;

  IF lower(COALESCE(p_category, '')) = 'prize' THEN
    INSERT INTO public.tournament_payouts
      (tournament_id, user_id, "position", amount, source, idempotency_key,
       paid_at, tournament_type, field_size, prize_pool, payout_structure,
       recorded_by)
    VALUES
      (v_t.id, p_user_id, v_payout_place, p_amount, v_payout_source,
       p_idempotency_key, now(), v_t.tournament_type, v_field, v_t.prize_pool,
       CASE WHEN v_t.payout_structure IS NULL THEN NULL
            ELSE jsonb_build_object('payout_structure', v_t.payout_structure) END,
       'credit_and_log')
    RETURNING id INTO v_payout_id;

    IF v_payout_id IS NULL OR NOT EXISTS (
      SELECT 1 FROM public.tournament_payouts tp
       WHERE tp.id = v_payout_id
         AND tp.idempotency_key = p_idempotency_key
         AND tp.tournament_id = p_related_entity_id
         AND tp.user_id = p_user_id
         AND tp.amount = p_amount
         AND tp."position" IS NOT DISTINCT FROM v_payout_place
         AND tp.source IS NOT DISTINCT FROM v_payout_source
    ) THEN
      RAISE EXCEPTION 'prize % could not verify its payout evidence',
        p_idempotency_key USING ERRCODE = 'P0404';
    END IF;
  END IF;
  IF NOT v_diamond AND p_related_entity_id IS NOT NULL
     AND v_ledger_cat IN ('tournament_prize','bounty','refund','tournament_refund') THEN
    PERFORM public.fn_ca_record_tournament_accounting_credit(p_idempotency_key,
      p_related_entity_id,p_user_id,p_amount,v_original_ledger,v_original_wallet,v_payout_id);
  END IF;
  RETURN true;
END;
$function$

public.fn_credit_treasury(p_club_id uuid.def:
CREATE OR REPLACE FUNCTION public.fn_credit_treasury(p_club_id uuid, p_amount numeric, p_reason text DEFAULT NULL::text, p_metadata jsonb DEFAULT '{}'::jsonb, p_op_id text DEFAULT NULL::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SET search_path TO 'public', 'extensions'
AS $function$
DECLARE
  v_prior jsonb;
  v_res jsonb;
BEGIN
  IF p_op_id IS NULL THEN
    RETURN public.fn_credit_treasury_zd4core(p_club_id, p_amount, p_reason, p_metadata);
  END IF;

  SELECT result INTO v_prior
    FROM public.ca_op_claims
   WHERE op_id = p_op_id AND fn_name = 'fn_credit_treasury';
  IF FOUND AND v_prior IS NOT NULL THEN
    RETURN v_prior || jsonb_build_object('replayed', true, 'op_id', p_op_id);
  ELSIF FOUND THEN
    DELETE FROM public.ca_op_claims
     WHERE op_id = p_op_id AND fn_name = 'fn_credit_treasury';
  END IF;

  INSERT INTO public.ca_op_claims (op_id, fn_name, claimed_by)
  VALUES (p_op_id, 'fn_credit_treasury', auth.uid());

  v_res := public.fn_credit_treasury_zd4core(p_club_id, p_amount, p_reason, p_metadata);

  IF COALESCE(v_res->>'success', '') = 'true' THEN
    UPDATE public.ca_op_claims
       SET result = v_res, finalized_at = now()
     WHERE op_id = p_op_id AND fn_name = 'fn_credit_treasury';
  ELSE
    DELETE FROM public.ca_op_claims
     WHERE op_id = p_op_id AND fn_name = 'fn_credit_treasury';
  END IF;

  RETURN v_res;
END;
$function$

public.fn_credit_treasury_zd4core(p_club.def:
CREATE OR REPLACE FUNCTION public.fn_credit_treasury_zd4core(p_club_id uuid, p_amount numeric, p_reason text, p_metadata jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SET search_path TO 'public', 'extensions'
AS $function$
DECLARE
  v_before numeric;
  v_after numeric;
BEGIN
  IF p_club_id IS NULL OR p_amount IS NULL OR p_amount <= 0 THEN
    RETURN jsonb_build_object('success', false, 'error', 'invalid parameters');
  END IF;

  /* THE CALLER NAMES WHERE THE CHIPS COME FROM (2026-10-02,
     20261002140203). fn_union_weekly_rakeback_close and
     fn_accounting_legacy_pay_week declare and stand the clubs journal down;
     a caller that does neither would be refused at commit. Say so here, by
     name, before anything moves. */
  IF NULLIF(current_setting('app.ledger_counterparty', true), '') IS NULL
     AND COALESCE(current_setting('app.ledger_autoskip_clubs', true), '') <> '1' THEN
    RAISE EXCEPTION 'fn_credit_treasury_requires_a_declared_counterparty'
      USING ERRCODE = '23514',
            DETAIL  = 'a club treasury credit with no app.ledger_counterparty would be journalled against settlement_suspense',
            HINT    = 'The calling door declares where the chips come from (fn_ca_declare_ledger), or stands the clubs journal down and writes its own leg.';
  END IF;

  SELECT COALESCE(chip_treasury, 0) INTO v_before
  FROM clubs WHERE id = p_club_id FOR NO KEY UPDATE;

  IF v_before IS NULL THEN
    RETURN jsonb_build_object('success', false, 'error', 'club not found');
  END IF;

  UPDATE clubs
  SET chip_treasury = COALESCE(chip_treasury, 0) + p_amount,
      updated_at = NOW()
  WHERE id = p_club_id;
  v_after := v_before + p_amount;

  INSERT INTO chip_transactions (
    id, club_id, amount, transaction_type, notes, metadata, balance_after, created_at
  ) VALUES (
    gen_random_uuid(), p_club_id, p_amount,
    'treasury_credit', COALESCE(p_reason, 'Treasury credit'), p_metadata, v_after, NOW()
  );

  RETURN jsonb_build_object(
    'success', true,
    'amount', p_amount,
    'balance_before', v_before,
    'balance_after', v_after
  );
END;
$function$

public.fn_deliver_accounting_invoice(p_i.def:
CREATE OR REPLACE FUNCTION public.fn_deliver_accounting_invoice(p_invoice_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
#variable_conflict use_variable
DECLARE inv public.settlement_invoices%ROWTYPE; sender uuid; issuer_name text; recipient_name text;
 issuer_kind text; issuer_id uuid; recipient_id uuid; scope_id uuid; page_id uuid; users uuid[]; issuer_users uuid[]; recipient_users uuid[];
 person uuid; conv uuid; msg uuid; note uuid; body text; meta jsonb; count_sent int:=0; n int; line record; cashier public.accounting_cashier_events%ROWTYPE; cashier_payload jsonb; correction public.accounting_correction_documents%ROWTYPE; correction_payload jsonb; credit_change public.accounting_credit_change_documents_v1%ROWTYPE; credit_operation public.accounting_credit_reduction_operations_v1%ROWTYPE; credit_payload jsonb;
BEGIN
 SELECT * INTO inv FROM public.settlement_invoices WHERE id=p_invoice_id FOR UPDATE;
 IF NOT FOUND THEN RAISE EXCEPTION 'accounting_invoice_missing' USING ERRCODE='23514'; END IF;
 IF public.fn_accounting_correction_is_unverified(inv.id)
 THEN RAISE EXCEPTION 'historical_correction_document_unverified' USING ERRCODE='23514';END IF;
 IF inv.net_amount IS NULL OR inv.net_amount::text IN('NaN','Infinity','-Infinity') OR inv.net_amount<>round(inv.net_amount,2)
 THEN RAISE EXCEPTION 'invalid_invoice_amount' USING ERRCODE='23514'; END IF;
 -- Owner rule (2026-10-15): only cashout documents reach the messenger (the player's request
 -- reaches their agent, the approval reaches the player). Every other invoice is recorded in
 -- transaction history only and marked delivered so the weekly close is satisfied.
 IF inv.invoice_type IS DISTINCT FROM 'cashier_cashout' THEN
  IF inv.invoice_number IS NULL THEN
   UPDATE public.settlement_invoices SET invoice_number=public.fn_accounting_next_invoice_number() WHERE id=inv.id RETURNING invoice_number INTO inv.invoice_number;
  END IF;
  UPDATE public.settlement_invoices SET message_sent=true,message_sent_at=COALESCE(message_sent_at,now()) WHERE id=inv.id;
  RETURN jsonb_build_object('success',true,'invoice_id',inv.id,'delivered',0,'new_deliveries',0);
 END IF;
 issuer_kind:=inv.from_entity_type; issuer_id:=inv.from_entity_id::uuid; recipient_id:=inv.to_entity_id::uuid;
 scope_id:=COALESCE(inv.club_id,issuer_id);
 IF inv.invoice_type='credit_limit_change' THEN
  credit_payload:=public.fn_accounting_credit_change_contract_v1(inv.id);
  SELECT * INTO STRICT credit_change FROM public.accounting_credit_change_documents_v1 WHERE invoice_id=inv.id;
  SELECT * INTO STRICT credit_operation FROM public.accounting_credit_reduction_operations_v1 WHERE id=credit_change.operation_receipt_id;
  users:=credit_change.audience_user_ids;sender:=credit_operation.actor_user_id;
  issuer_kind:='club';issuer_id:=credit_operation.club_id;scope_id:=credit_operation.club_id;
  issuer_name:=credit_change.issuer_name;recipient_name:=credit_change.recipient_name;
 ELSIF inv.invoice_type='accounting_correction' THEN
  SELECT * INTO correction FROM public.accounting_correction_documents WHERE invoice_id=inv.id;
  IF NOT FOUND OR correction.club_id IS DISTINCT FROM inv.club_id OR correction.source_ledger_id IS DISTINCT FROM inv.source_ledger_id
   OR correction.amount IS DISTINCT FROM inv.net_amount OR inv.breakdown IS DISTINCT FROM jsonb_build_object('category','correction','correction',public.fn_accounting_correction_payload(correction))
   OR inv.status IS DISTINCT FROM 'generated' OR inv.chips_transferred IS DISTINCT FROM false OR inv.transferred_at IS NOT NULL OR inv.due_at IS NOT NULL
  THEN RAISE EXCEPTION 'correction_document_delivery_source_unverified' USING ERRCODE='23514';END IF;
  users:=correction.audience_user_ids;sender:=correction.issuer_representative_id;
  issuer_kind:=correction.issuer_type;issuer_id:=correction.issuer_id;scope_id:=correction.club_id;
  issuer_name:=correction.issuer_name;recipient_name:=correction.payee_name;correction_payload:=public.fn_accounting_correction_payload(correction);
 ELSIF inv.invoice_type='cashier_cashout' THEN
  SELECT * INTO cashier FROM public.accounting_cashier_events WHERE invoice_id=inv.id;
  IF NOT FOUND OR cashier.club_id IS DISTINCT FROM inv.club_id OR cashier.source_ledger_id IS DISTINCT FROM inv.source_ledger_id
    OR cashier.amount IS DISTINCT FROM inv.net_amount OR inv.breakdown->'cashier' IS DISTINCT FROM public.fn_cashier_event_payload(cashier)
  THEN RAISE EXCEPTION 'cashier_delivery_event_missing' USING ERRCODE='23514';END IF;
  users:=cashier.audience_user_ids;sender:=cashier.issuer_representative_id;
  issuer_kind:='club';issuer_id:=cashier.club_id;scope_id:=cashier.club_id;
  issuer_name:=cashier.issuer_name;recipient_name:=cashier.player_name;
  cashier_payload:=public.fn_cashier_event_payload(cashier);
 ELSE
 SELECT array_agg(user_id ORDER BY user_id) INTO issuer_users FROM public.fn_accounting_invoice_party_users(inv.from_entity_type,issuer_id);
 SELECT array_agg(user_id ORDER BY user_id) INTO recipient_users FROM public.fn_accounting_invoice_party_users(inv.to_entity_type,recipient_id);
 IF COALESCE(cardinality(issuer_users),0)=0 OR COALESCE(cardinality(recipient_users),0)=0
 THEN RAISE EXCEPTION 'accounting_invoice_recipient_missing' USING ERRCODE='23514'; END IF;
 SELECT array_agg(DISTINCT x ORDER BY x) INTO users FROM unnest(issuer_users||recipient_users) x;
 -- Club senders receive one weekly summary; individual payees still get their receipt immediately.
 IF inv.from_entity_type='club' AND inv.to_entity_type IN('agent','player')
    AND inv.source_ledger_id IS NOT NULL AND inv.breakdown->>'category' IN('rakeback','commission') THEN
   users:=recipient_users;
 END IF;
 IF inv.invoice_type IN('union_weekly_squareup','union_weekly_credit_note') THEN
   issuer_kind:='union';issuer_id:=(inv.breakdown->>'union_id')::uuid;
 END IF;
 sender:=CASE WHEN issuer_kind='club' THEN (SELECT owner_id FROM public.clubs WHERE id=issuer_id)
              WHEN issuer_kind='union' THEN (SELECT owner_id FROM public.unions WHERE id=issuer_id)
              ELSE issuer_id END;
 IF sender IS NULL OR NOT sender=ANY(issuer_users||recipient_users) THEN RAISE EXCEPTION 'accounting_invoice_sender_missing' USING ERRCODE='23514'; END IF;
 issuer_name:=CASE WHEN issuer_kind='club' THEN (SELECT name FROM public.clubs WHERE id=issuer_id)
                   WHEN issuer_kind='union' THEN (SELECT name FROM public.unions WHERE id=issuer_id)
                   ELSE (SELECT username FROM public.profiles WHERE id=issuer_id) END;
 recipient_name:=CASE WHEN inv.to_entity_type='club' THEN (SELECT name FROM public.clubs WHERE id=recipient_id)
                      WHEN inv.to_entity_type='union' THEN (SELECT name FROM public.unions WHERE id=recipient_id)
                      ELSE (SELECT username FROM public.profiles WHERE id=recipient_id) END;
 END IF;
 IF inv.invoice_number IS NULL THEN
   UPDATE public.settlement_invoices SET invoice_number=public.fn_accounting_next_invoice_number() WHERE id=inv.id RETURNING invoice_number INTO inv.invoice_number;
 END IF;
 IF inv.invoice_type IN('union_weekly_squareup','union_weekly_credit_note') THEN recipient_name:=(SELECT name FROM public.clubs WHERE id=inv.club_id); END IF;
 body:=CASE WHEN inv.invoice_type='club_weekly_accounting' THEN 'Weekly Club Statement ' ELSE 'Invoice ' END||inv.invoice_number||E'\nIssued By: '||COALESCE(issuer_name,inv.from_entity_type)||E'\nFor: '||COALESCE(recipient_name,inv.to_entity_type)
  ||E'\nDirection: '||initcap(inv.from_entity_type)||' To '||initcap(inv.to_entity_type)
  ||E'\nAmount: '||to_char(abs(inv.net_amount),'FM999,999,999,999,990.00')||' Chips'
  ||E'\nStatus: '||initcap(inv.status)
  ||CASE WHEN inv.chips_transferred THEN E'\nTransfer Recorded: '||COALESCE(inv.transferred_at,inv.created_at)::text ELSE '' END
  ||CASE WHEN inv.due_at IS NOT NULL THEN E'\nDue: '||to_char(inv.due_at AT TIME ZONE 'America/Chicago','YYYY-MM-DD HH24:MI')||' Chicago Time' ELSE '' END
  ||CASE WHEN inv.breakdown ? 'period_start' THEN E'\nPeriod: '||(inv.breakdown->>'period_start')||' To '||COALESCE(inv.breakdown->>'period_end','') ELSE '' END
  ||CASE WHEN inv.notes IS NOT NULL THEN E'\n'||inv.notes ELSE '' END;
 FOR line IN SELECT key,value FROM jsonb_each_text(COALESCE(inv.breakdown,'{}'))
   WHERE key IN('rake_generated','rakeback_due','union_fee_kept','players_won','settled_in_chips','eco_amount','presettled','rake_earned','union_rake_earned','private_rake_earned','private_rake_banked','total_rake_funding','rake_received','paid_super_agents','paid_agents','paid_sub_agents','paid_players','total_paid_by_club','retained_by_club','downstream_redistributed','downstream_paid_super_agents','downstream_paid_agents','downstream_paid_sub_agents','downstream_paid_players') ORDER BY key
 LOOP
   IF line.value IS NOT NULL THEN body:=body||E'\n'||initcap(replace(line.key,'_',' '))||': '||to_char(line.value::numeric,'FM999,999,999,999,990.00'); END IF;
 END LOOP;
 IF inv.invoice_type='credit_limit_change' THEN body:=public.fn_accounting_credit_change_body_v1(credit_change.id,inv.invoice_number);
 ELSIF inv.invoice_type='cashier_cashout' THEN body:=public.fn_cashier_document_body(cashier.id,inv.invoice_number);
 ELSIF inv.invoice_type='accounting_correction' THEN body:=public.fn_accounting_correction_document_body(correction.id,inv.invoice_number);END IF;
 meta:=jsonb_build_object('kind','accounting_invoice' ,'invoice_id',inv.id,'invoice_number',inv.invoice_number,
   'club_id',inv.club_id,'source_ledger_id',inv.source_ledger_id,'source_credit_invoice_id',inv.source_credit_invoice_id,
   'source_credit_payment_id',inv.source_credit_payment_id,'amount',inv.net_amount,'currency','CHIPS','conversationId',NULL,'status',inv.status,
   'invoice_type',inv.invoice_type,'from_entity_type',inv.from_entity_type,'from_entity_id',inv.from_entity_id,
   'to_entity_type',inv.to_entity_type,'to_entity_id',inv.to_entity_id,'lines',inv.breakdown-ARRAY['source_ledger_ids','private_bank_ledger_ids','standalone_bank_ledger_ids','standalone_bank_mint_ids']);
 IF inv.invoice_type='credit_limit_change' THEN meta:=meta||jsonb_build_object('credit_change',credit_payload);
 ELSIF inv.invoice_type='cashier_cashout' THEN meta:=meta||jsonb_build_object('cashier',cashier_payload);
 ELSIF inv.invoice_type='accounting_correction' THEN meta:=meta||jsonb_build_object('correction',correction_payload);END IF;
 SELECT id INTO page_id FROM public.social_pages WHERE linked_entity_id=scope_id::text AND linked_entity_type='club' ORDER BY id LIMIT 1;
 FOREACH person IN ARRAY users LOOP
   IF EXISTS(SELECT 1 FROM public.accounting_invoice_deliveries d WHERE d.invoice_id=inv.id AND d.recipient_id=person) THEN CONTINUE; END IF;
   -- One private accounting conversation per issuer, sender, scope and recipient.
   PERFORM pg_advisory_xact_lock(hashtextextended('accounting_conversation:'||scope_id::text||':'||issuer_id::text||':'||sender::text||':'||person::text,0));
   SELECT conversation_id INTO conv FROM public.accounting_conversations c
    WHERE c.scope_id=scope_id AND c.issuer_type=issuer_kind AND c.issuer_id=issuer_id AND c.sender_id=sender AND c.recipient_id=person;
   IF conv IS NULL THEN
     INSERT INTO public.social_conversations(is_group,group_name,context_entity_id,context_entity_type)
      VALUES(true,COALESCE(issuer_name,'Account')||' Accounting',page_id,CASE WHEN page_id IS NULL THEN NULL ELSE 'club' END) RETURNING id INTO conv;
     INSERT INTO public.social_conversation_participants(conversation_id,user_id,context_entity_id,context_entity_type)
      SELECT conv,x,page_id,CASE WHEN page_id IS NULL THEN NULL ELSE 'club' END FROM (SELECT DISTINCT unnest(ARRAY[sender,person]) AS x) members;
     INSERT INTO public.accounting_conversations(scope_id,issuer_type,issuer_id,sender_id,recipient_id,conversation_id)
      VALUES(scope_id,issuer_kind,issuer_id,sender,person,conv);
   END IF;
   -- Refuse a conversation whose audience changed instead of leaking invoices.
   IF EXISTS(SELECT 1 FROM public.social_conversation_participants WHERE conversation_id=conv AND user_id<>ALL(ARRAY[sender,person]))
      OR NOT EXISTS(SELECT 1 FROM public.social_conversation_participants WHERE conversation_id=conv AND user_id=person)
      OR NOT EXISTS(SELECT 1 FROM public.social_conversation_participants WHERE conversation_id=conv AND user_id=sender)
   THEN RAISE EXCEPTION 'accounting_conversation_audience_changed' USING ERRCODE='23514'; END IF;
   meta:=meta||jsonb_build_object('conversation_id',conv,'conversationId',conv);
   INSERT INTO public.social_messages(conversation_id,sender_id,content,message_type,media_metadata)
    VALUES(conv,sender,body,'invoice',meta) RETURNING id INTO msg;
   UPDATE public.social_conversations SET last_message_at=now(),last_message_preview=left(body,100),updated_at=now() WHERE id=conv;
   meta:=meta||jsonb_build_object('conversation_id',conv,'conversationId',conv);
   INSERT INTO public.notifications(user_id,type,title,message,data,read,action_url,metadata)
    VALUES(person,CASE WHEN inv.chips_transferred AND inv.invoice_type NOT IN('credit_limit_change','accounting_correction','cashier_cashout') THEN 'accounting_invoice_detail' ELSE 'accounting_invoice' END,CASE WHEN inv.invoice_type='cashier_cashout' THEN public.fn_cashier_notice_copy(cashier,person,inv.invoice_number)->>'title' ELSE CASE WHEN inv.invoice_type='credit_limit_change' THEN 'Credit Line Updated · ' WHEN inv.invoice_type='accounting_correction' THEN 'Correction Recorded · ' WHEN inv.invoice_type='cashier_cashout' THEN CASE cashier.event_kind WHEN 'hold' THEN 'Chips Held · ' WHEN 'approval' THEN 'Cashout Approved · ' ELSE 'Chips Returned · ' END WHEN inv.invoice_type='club_weekly_accounting' THEN 'Weekly Club Statement ' ELSE 'Invoice ' END||inv.invoice_number END,
     CASE WHEN inv.invoice_type='cashier_cashout' THEN public.fn_cashier_notice_copy(cashier,person,inv.invoice_number)->>'message' ELSE CASE WHEN inv.invoice_type='credit_limit_change' THEN 'Credit capacity reduced: '||to_char(inv.net_amount,'FM999,999,999,999,990.00')||'. No payment due.'
      ELSE CASE WHEN inv.invoice_type='accounting_correction' THEN 'Correction Recorded: ' WHEN inv.invoice_type='cashier_cashout' THEN CASE cashier.event_kind WHEN 'hold' THEN 'Chips Held: ' WHEN 'approval' THEN 'Cashout Approved: ' ELSE 'Chips Returned: ' END WHEN inv.chips_transferred AND inv.breakdown->>'category'='rakeback' THEN 'Rakeback Transfer Recorded: ' WHEN inv.chips_transferred AND inv.breakdown->>'category'='commission' THEN 'Commission Transfer Recorded: ' WHEN inv.chips_transferred THEN 'Transfer Recorded: ' ELSE 'Invoice Issued: ' END||to_char(abs(inv.net_amount),'FM999,999,999,999,990.00')||' Chips' END END,
     meta,(inv.chips_transferred AND inv.invoice_type NOT IN('credit_limit_change','accounting_correction','cashier_cashout')),'/hub/messenger?conversation='||conv::text,meta) RETURNING id INTO note;
   INSERT INTO public.accounting_invoice_deliveries(invoice_id,recipient_id,message_id,notification_id) VALUES(inv.id,person,msg,note);
   count_sent:=count_sent+1;
 END LOOP;
 SELECT count(*) INTO n FROM public.accounting_invoice_deliveries WHERE invoice_id=inv.id;
 UPDATE public.settlement_invoices SET message_sent=true,message_sent_at=COALESCE(message_sent_at,now()) WHERE id=inv.id;
 RETURN jsonb_build_object('success',true,'invoice_id',inv.id,'delivered',n,'new_deliveries',count_sent);
END $function$

public.fn_deliver_club_messenger_welcome.def:
CREATE OR REPLACE FUNCTION public.fn_deliver_club_messenger_welcome()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'extensions'
AS $function$
DECLARE v_member record; v_admission record; v_sender uuid; v_owner uuid; v_template record; v_result jsonb;
BEGIN
 SELECT * INTO v_member FROM public.club_members WHERE club_id=NEW.club_id AND user_id=NEW.user_id;
 IF NOT FOUND OR v_member.is_active IS NOT TRUE OR v_member.status NOT IN ('active','approved') OR v_member.membership_lifecycle_status<>'active' THEN RETURN NEW; END IF;
 IF public.fn_ca_is_cert_account(NEW.user_id) THEN RETURN NEW; END IF;
 SELECT * INTO v_admission FROM public.club_messenger_admissions WHERE club_id=NEW.club_id AND user_id=NEW.user_id AND active AND transaction_id=txid_current() FOR UPDATE;
 IF NOT FOUND OR EXISTS(SELECT 1 FROM public.club_messenger_welcome_deliveries WHERE generation=v_admission.generation) THEN RETURN NEW; END IF;
 SELECT owner_id INTO v_owner FROM public.clubs WHERE id=NEW.club_id;
 v_sender:=v_member.agent_id;
 IF v_sender IS NOT NULL AND NOT EXISTS(SELECT 1 FROM public.agents WHERE club_id=NEW.club_id AND user_id=v_sender AND status='active') THEN v_sender:=NULL; END IF;
 IF v_sender IS NULL OR public.fn_club_messenger_staff_role(NEW.club_id,v_sender) IS NULL THEN v_sender:=v_owner; END IF;
 IF v_sender IS NULL OR v_sender=NEW.user_id THEN RETURN NEW; END IF;
 SELECT * INTO v_template FROM public.club_messenger_welcome_templates WHERE club_id=NEW.club_id AND user_id=v_sender AND enabled FOR SHARE;
 IF NOT FOUND THEN RETURN NEW; END IF;
 v_result:=public.fn_send_club_welcome_text(NEW.club_id,NEW.user_id,v_sender,v_template.content,v_template.revision,'downline');
 IF v_result->>'status'='cancelled' THEN RETURN NEW; END IF;
 INSERT INTO public.club_messenger_welcome_deliveries(generation,club_id,recipient_id,sender_id,template_revision,conversation_id,message_id,status)
 VALUES(v_admission.generation,NEW.club_id,NEW.user_id,v_sender,v_template.revision,(v_result->>'conversation_id')::uuid,(v_result->>'message_id')::uuid,v_result->>'status');
 IF v_result->>'status'='sent' AND v_owner<>NEW.user_id THEN
  INSERT INTO public.club_messenger_owner_followups(generation,club_id,recipient_id,sender_id,content,template_revision,due_at)
  SELECT v_admission.generation,NEW.club_id,NEW.user_id,v_owner,t.content,t.revision,clock_timestamp()+interval '10 minutes'
  FROM public.club_messenger_owner_welcome_templates t WHERE t.club_id=NEW.club_id AND t.user_id=v_owner AND t.enabled
  ON CONFLICT(generation) DO NOTHING;
 END IF;
 RETURN NEW;
END $function$

public.fn_diamond_game_reserved_cover_gu.def:
CREATE OR REPLACE FUNCTION public.fn_diamond_game_reserved_cover_guard()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE host uuid; cover numeric; old_cover numeric; held numeric;
BEGIN
 IF TG_TABLE_NAME='clubs' THEN
  host:=NEW.id; cover:=GREATEST(COALESCE(NEW.promo_balance,0),0)+GREATEST(COALESCE(NEW.chip_treasury,0),0);
  old_cover:=GREATEST(COALESCE(OLD.promo_balance,0),0)+GREATEST(COALESCE(OLD.chip_treasury,0),0);
 ELSE
  host:=NEW.union_id; cover:=GREATEST(COALESCE(NEW.promo_wallet,0),0)+GREATEST(COALESCE(NEW.chip_balance,0),0);
  old_cover:=GREATEST(COALESCE(OLD.promo_wallet,0),0)+GREATEST(COALESCE(OLD.chip_balance,0),0);
 END IF;
 IF cover>=old_cover THEN RETURN NEW; END IF;
 SELECT COALESCE(sum(reserved_chips),0) INTO held FROM public.diamond_game_pools WHERE host_id=host;
 IF cover<held THEN RAISE EXCEPTION 'These Chips Are Reserved For Open Game Rounds'; END IF;
 RETURN NEW;
END $function$

public.fn_dispatch_private_record_signal.def:
CREATE OR REPLACE FUNCTION public.fn_dispatch_private_record_signal(p_topic text, p_payload jsonb)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE paid boolean;
BEGIN
 IF p_topic IS NULL OR NOT (
   p_topic ~ '^member-record:[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}:[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$'
   OR p_topic ~ '^club-roster:[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$'
 ) THEN RAISE EXCEPTION 'Invalid private record topic'; END IF;
 SELECT supabase_enabled INTO STRICT paid FROM public.ca_private_record_transport_state WHERE singleton;
 PERFORM pg_notify('ca_private_record_changes',jsonb_build_object('topic',p_topic,'event','record_changed')::text);
 IF paid THEN PERFORM realtime.send(p_payload,'record_changed',p_topic,true); END IF;
END $function$

public.fn_emit_game_management_event(p_e.def:
CREATE OR REPLACE FUNCTION public.fn_emit_game_management_event(p_event_type text, p_club_id uuid DEFAULT NULL::uuid, p_union_id uuid DEFAULT NULL::uuid, p_recipient_id uuid DEFAULT NULL::uuid, p_entity_type text DEFAULT NULL::text, p_entity_id uuid DEFAULT NULL::uuid, p_command_id uuid DEFAULT NULL::uuid, p_payload jsonb DEFAULT '{}'::jsonb)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE v_scope_kind text; v_scope_id uuid; v_union_id uuid;
BEGIN
  IF p_union_id IS NOT NULL THEN
    v_scope_kind := 'union'; v_scope_id := p_union_id; v_union_id := p_union_id;
  ELSIF p_club_id IS NOT NULL THEN
    SELECT s.scope_kind,s.scope_id,s.union_id
      INTO v_scope_kind,v_scope_id,v_union_id
      FROM public.fn_game_management_scope(p_club_id) s;
  END IF;
  INSERT INTO public.game_management_events(
    event_type,scope_kind,scope_id,club_id,union_id,recipient_id,
    entity_type,entity_id,command_id,actor_id,payload
  ) VALUES (
    p_event_type,v_scope_kind,v_scope_id,p_club_id,v_union_id,p_recipient_id,
    p_entity_type,p_entity_id,p_command_id,auth.uid(),COALESCE(p_payload,'{}'::jsonb)
  );
END;
$function$

public.fn_emit_management_content_event(.def:
CREATE OR REPLACE FUNCTION public.fn_emit_management_content_event()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_club uuid; v_union uuid; v_type text; v_id uuid; v_role text := 'host';
  v_before jsonb; v_after jsonb;
BEGIN
  IF TG_TABLE_NAME = 'game_ticker_settings' THEN
    IF TG_OP = 'UPDATE'
       AND (to_jsonb(NEW) - ARRAY['updated_at','revision'])
           IS NOT DISTINCT FROM (to_jsonb(OLD) - ARRAY['updated_at','revision']) THEN
      RETURN NULL;
    END IF;
    v_club := COALESCE(NEW.club_id, OLD.club_id);
    v_union := COALESCE(NEW.union_id, OLD.union_id);
    v_type := 'ticker_settings_changed'; v_id := COALESCE(NEW.id, OLD.id);
    v_before := CASE WHEN TG_OP='INSERT' THEN NULL ELSE jsonb_build_object('settings',OLD.settings) END;
    v_after := CASE WHEN TG_OP='DELETE' THEN NULL ELSE jsonb_build_object('settings',NEW.settings) END;
  ELSIF TG_TABLE_NAME = 'clubs' THEN
    IF NEW.tagline IS NOT DISTINCT FROM OLD.tagline
       AND NEW.lobby_message IS NOT DISTINCT FROM OLD.lobby_message
       AND NEW.description IS NOT DISTINCT FROM OLD.description THEN
      RETURN NULL;
    END IF;
    v_club := NEW.id; v_type := 'club_identity_changed'; v_id := NEW.id;
    v_before := jsonb_build_object('tagline',OLD.tagline,'lobby_message',OLD.lobby_message,'description',OLD.description);
    v_after := jsonb_build_object('tagline',NEW.tagline,'lobby_message',NEW.lobby_message,'description',NEW.description);
  ELSE
    IF TG_OP = 'UPDATE'
       AND (to_jsonb(NEW) - ARRAY['updated_at','management_revision'])
           IS NOT DISTINCT FROM (to_jsonb(OLD) - ARRAY['updated_at','management_revision']) THEN
      RETURN NULL;
    END IF;
    v_club := COALESCE(NEW.club_id,OLD.club_id);
    v_type := 'announcement_changed'; v_id := COALESCE(NEW.id,OLD.id);
    v_before := CASE WHEN TG_OP='INSERT' THEN NULL ELSE jsonb_build_object(
      'title',OLD.title,'content',OLD.content,'is_pinned',OLD.is_pinned,'is_active',OLD.is_active) END;
    v_after := CASE WHEN TG_OP='DELETE' THEN NULL ELSE jsonb_build_object(
      'title',NEW.title,'content',NEW.content,'is_pinned',NEW.is_pinned,'is_active',NEW.is_active) END;
  END IF;

  PERFORM public.fn_emit_game_management_event(
    v_type,v_club,v_union,NULL,TG_TABLE_NAME,v_id,NULL,
    jsonb_build_object('operation',lower(TG_OP)));

  IF auth.uid() IS NOT NULL THEN
    IF v_union IS NOT NULL OR EXISTS (
      SELECT 1 FROM public.union_clubs WHERE club_id=v_club) THEN
      v_role := 'union_admin';
    ELSE
      SELECT CASE WHEN c.owner_id=auth.uid() THEN 'owner'
                  WHEN m.role='co_owner' THEN 'co_owner'
                  WHEN m.role='admin' THEN 'admin' ELSE 'host' END
        INTO v_role FROM public.clubs c
        LEFT JOIN public.club_members m
          ON m.club_id=c.id AND m.user_id=auth.uid()
       WHERE c.id=v_club;
    END IF;
    INSERT INTO public.audit_trail(
      actor_id,actor_role,action,target_type,target_id,club_id,before_state,after_state
    ) VALUES (
      auth.uid(),COALESCE(v_role,'host'),v_type,TG_TABLE_NAME,v_id,v_club,v_before,v_after);
  END IF;
  RETURN NULL;
END;
$function$

public.fn_emit_union_owner_access_event(.def:
CREATE OR REPLACE FUNCTION public.fn_emit_union_owner_access_event()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
BEGIN
  IF NEW.owner_id IS DISTINCT FROM OLD.owner_id THEN
    PERFORM public.fn_emit_game_management_event(
      'management_access_changed',NULL,NEW.id,OLD.owner_id,'union',NEW.id,NULL,
      jsonb_build_object('operation','owner_changed')
    );
    PERFORM public.fn_emit_game_management_event(
      'management_access_changed',NULL,NEW.id,NEW.owner_id,'union',NEW.id,NULL,
      jsonb_build_object('operation','owner_changed')
    );
  END IF;
  RETURN NEW;
END;
$function$

public.fn_enforce_four_club_limit().def:
CREATE OR REPLACE FUNCTION public.fn_enforce_four_club_limit()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_count int;
BEGIN
  IF NEW.status NOT IN ('active', 'approved') THEN
    RETURN NEW;
  END IF;

  IF TG_OP = 'UPDATE' AND OLD.status IN ('active', 'approved') THEN
    RETURN NEW;
  END IF;

  -- THE UNION OWNER IS A MEMBER OF EVERY CLUB (2026-10-12): the membership
  -- the union rule makes is the platform's, not a club the owner chose, so the
  -- personal club cap does not refuse it (fn_union_owner_holds_membership).
  IF COALESCE(current_setting('app.club_membership_source', true), '') = 'union_owner_membership' THEN
    RETURN NEW;
  END IF;

  IF EXISTS (
    SELECT 1 FROM profiles WHERE id = NEW.user_id AND COALESCE(is_horse, false)
  ) THEN
    RETURN NEW;
  END IF;

  PERFORM public.fn_club_membership_lock(NEW.user_id);
  v_count := public.fn_club_membership_count(NEW.user_id, NEW.club_id);

  IF v_count >= public.fn_club_membership_cap() THEN
    RAISE EXCEPTION
      'You can only be a member of up to % clubs. Leave a club to join a new one.',
      public.fn_club_membership_cap()
      USING ERRCODE = 'check_violation';
  END IF;

  RETURN NEW;
END;
$function$

public.fn_ensure_social_page_for_club(p_.def:
CREATE OR REPLACE FUNCTION public.fn_ensure_social_page_for_club(p_club_id uuid)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE v_existing_id uuid; v_club RECORD; v_new_id uuid;
BEGIN
    SELECT id INTO v_existing_id FROM social_pages
     WHERE linked_entity_type = 'club' AND linked_entity_id = p_club_id::text
     LIMIT 1;
    IF v_existing_id IS NOT NULL THEN RETURN v_existing_id; END IF;

    SELECT id, name, description, owner_id, avatar_url, logo_url, is_public
      INTO v_club FROM clubs WHERE id = p_club_id;
    IF NOT FOUND THEN RETURN NULL; END IF;

    INSERT INTO social_pages (
        owner_id, page_type, name, description, avatar_url, category,
        linked_entity_type, linked_entity_id,
        is_public, metadata
    ) VALUES (
        v_club.owner_id, 'club', v_club.name, v_club.description,
        COALESCE(v_club.avatar_url, v_club.logo_url), 'poker',
        'club', v_club.id::text,
        COALESCE(v_club.is_public, true),
        jsonb_build_object('auto_provisioned', true, 'source', 'phase29', 'at', now())
    ) RETURNING id INTO v_new_id;
    RETURN v_new_id;
EXCEPTION WHEN OTHERS THEN
    RAISE WARNING 'fn_ensure_social_page_for_club failed for %: %', p_club_id, SQLERRM;
    RETURN NULL;
END; $function$

public.fn_generate_credit_invoice(p_agen.def:
CREATE OR REPLACE FUNCTION public.fn_generate_credit_invoice(p_agent_id uuid, p_period_start timestamp with time zone, p_period_end timestamp with time zone, p_debt_owed numeric, p_due_date timestamp with time zone)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'extensions'
AS $function$
DECLARE
 v_agent public.agents%ROWTYPE;
 v_row public.credit_invoices%ROWTYPE;
 v_invoiced numeric;
 v_available numeric; carry_dispute boolean;
BEGIN
 IF p_agent_id IS NULL THEN RAISE EXCEPTION 'agent_required' USING ERRCODE='22023'; END IF;
 SELECT * INTO v_agent FROM public.agents WHERE id=p_agent_id FOR UPDATE;
 IF NOT FOUND THEN RAISE EXCEPTION 'agent_not_found' USING ERRCODE='22023'; END IF;
 IF NOT public.fn_caller_is_engine() AND (auth.uid() IS NULL OR
   (auth.uid()<>v_agent.user_id AND NOT public.fn_is_platform_admin()
    AND NOT public.fn_is_club_admin_uid(v_agent.club_id))) THEN
   RAISE EXCEPTION 'not_authorised' USING ERRCODE='42501';
 END IF;
 IF p_period_start IS NULL OR p_period_end IS NULL OR p_due_date IS NULL
   OR NOT isfinite(p_period_start) OR NOT isfinite(p_period_end) OR NOT isfinite(p_due_date)
   OR p_period_start>=p_period_end OR p_period_end>now() OR p_due_date<p_period_end
   OR p_debt_owed IS NULL OR p_debt_owed::text IN ('NaN','Infinity','-Infinity')
   OR p_debt_owed<=0 OR p_debt_owed<>round(p_debt_owed,2) THEN
   RAISE EXCEPTION 'invalid_credit_invoice_terms' USING ERRCODE='22023';
 END IF;
 -- An issued document is immutable. Replay returns its original terms.
 SELECT * INTO v_row FROM public.credit_invoices WHERE agent_id=p_agent_id AND period_end=p_period_end;
 IF FOUND THEN RETURN jsonb_build_object('success',true,'duplicate',true,'invoice',to_jsonb(v_row)); END IF;
 IF COALESCE(v_agent.is_prepaid,false) THEN
   RETURN jsonb_build_object('success',false,'error','prepaid_agent');
 END IF;
 SELECT b.amount_owed INTO v_available FROM public.agent_credit_weekly_basis b
  WHERE b.agent_id=p_agent_id AND b.period_start=p_period_start AND b.period_end=p_period_end;
 IF NOT FOUND THEN RAISE EXCEPTION 'pre_rakeback_credit_basis_required' USING ERRCODE='55000'; END IF;
 IF p_debt_owed IS DISTINCT FROM v_available THEN RAISE EXCEPTION 'credit_invoice_basis_mismatch' USING ERRCODE='23514'; END IF;
 SELECT EXISTS(SELECT FROM public.credit_invoices i WHERE i.agent_id=p_agent_id AND i.status='disputed' AND i.period_end<p_period_end AND EXISTS(SELECT FROM public.agent_credit_weekly_basis b WHERE b.agent_id=i.agent_id AND b.period_end=i.period_end)) INTO carry_dispute;
 -- Older tracking statements describe the same replenishable balance. Preserve
 -- their original amounts and payments, superseding only the unpaid remainder.
 UPDATE public.credit_invoices i SET status='void',amount_remaining=0,
  void_reason='Superseded By Agent Wallet Top-Up Statement Ending '||p_period_end::text
 WHERE i.agent_id=p_agent_id AND i.period_end<p_period_end AND i.status IN('pending','partial','overdue','disputed')
  AND EXISTS(SELECT FROM public.agent_credit_weekly_basis b WHERE b.agent_id=i.agent_id AND b.period_end=i.period_end);
 INSERT INTO public.credit_invoices(agent_id,period_start,period_end,debt_owed,amount_paid,amount_remaining,status,due_date)
 VALUES(p_agent_id,p_period_start,p_period_end,p_debt_owed,0,p_debt_owed,CASE WHEN carry_dispute THEN 'disputed' ELSE 'pending' END,p_due_date)
 RETURNING * INTO v_row;
 RETURN jsonb_build_object('success',true,'duplicate',false,'invoice',to_jsonb(v_row));
END $function$

public.fn_generate_scope_credit_invoices.def:
CREATE OR REPLACE FUNCTION public.fn_generate_scope_credit_invoices(p_club_id uuid, p_from timestamp with time zone, p_to timestamp with time zone)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE v_basis record;r jsonb;generated int:=0;duplicates int:=0;
BEGIN
 IF NOT public.fn_caller_is_engine() THEN RAISE EXCEPTION 'service_role_required' USING ERRCODE='42501'; END IF;
 IF p_club_id IS NULL OR p_from IS NULL OR p_to IS NULL OR NOT isfinite(p_from) OR NOT isfinite(p_to) OR p_from>=p_to OR p_to>now() THEN RAISE EXCEPTION 'invalid_credit_scope' USING ERRCODE='22023'; END IF;
 IF p_to<(SELECT activated_at FROM public.agent_credit_tracking_policy WHERE singleton) THEN RETURN jsonb_build_object('success',true,'generated',0,'duplicate',0,'failed',0,'legacy_period',true); END IF;
 IF NOT EXISTS(SELECT FROM public.agent_credit_weekly_scopes captured WHERE captured.club_id=p_club_id AND captured.period_start=p_from AND captured.period_end=p_to) THEN RAISE EXCEPTION 'pre_rakeback_credit_basis_required' USING ERRCODE='55000'; END IF;
 FOR v_basis IN SELECT * FROM public.agent_credit_weekly_basis WHERE club_id=p_club_id AND period_start=p_from AND period_end=p_to AND amount_owed>0 ORDER BY agent_id LOOP
  r:=public.fn_generate_credit_invoice(v_basis.agent_id,p_from,p_to,v_basis.amount_owed,p_to+interval '2 days');
  IF r->>'success' IS DISTINCT FROM 'true' THEN RAISE EXCEPTION 'credit_invoice_generation_failed' USING DETAIL=r::text; END IF;
  IF r->>'duplicate'='true' THEN duplicates:=duplicates+1; ELSE generated:=generated+1; END IF;
 END LOOP;
 UPDATE public.credit_invoices i SET status='void',amount_remaining=0,void_reason='Superseded By Fully Funded Agent Wallet Statement Ending '||p_to::text WHERE i.period_end<p_to AND i.status IN('pending','partial','overdue','disputed') AND EXISTS(SELECT FROM public.agent_credit_weekly_basis previous_basis WHERE previous_basis.agent_id=i.agent_id AND previous_basis.period_end=i.period_end) AND EXISTS(SELECT FROM public.agent_credit_weekly_basis current_basis WHERE current_basis.agent_id=i.agent_id AND current_basis.club_id=p_club_id AND current_basis.period_start=p_from AND current_basis.period_end=p_to AND current_basis.amount_owed=0);
 RETURN jsonb_build_object('success',true,'generated',generated,'duplicate',duplicates,'failed',0);
END $function$

public.fn_guard_agent_agreement().def:
CREATE OR REPLACE FUNCTION public.fn_guard_agent_agreement()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE parent public.agents%ROWTYPE;child record;field text;new_value numeric;old_value numeric;parent_value numeric;child_value numeric;
 old_terms jsonb;new_terms jsonb;parent_terms jsonb;new_edge boolean;
BEGIN
 IF TG_OP='UPDATE' AND (NEW.id IS DISTINCT FROM OLD.id OR NEW.user_id IS DISTINCT FROM OLD.user_id OR NEW.club_id IS DISTINCT FROM OLD.club_id) THEN
  RAISE EXCEPTION 'agent financial account identity is immutable; create a separate account for another club or user' USING ERRCODE='23514';END IF;
 -- All agreement RPCs take this same club lock before reading terms. Direct
 -- writes also pass this guard; the financial account's club is immutable.
 PERFORM pg_advisory_xact_lock(hashtextextended('agent-agreement:'||NEW.club_id::text,0));
 old_terms:=CASE WHEN TG_OP='UPDATE' THEN to_jsonb(OLD) ELSE '{}'::jsonb END;
 new_terms:=to_jsonb(NEW);
 new_edge:=TG_OP='INSERT' OR NEW.parent_agent_id IS DISTINCT FROM OLD.parent_agent_id OR NEW.club_id IS DISTINCT FROM OLD.club_id;
 IF NEW.parent_agent_id IS NOT NULL THEN
  SELECT * INTO parent FROM public.agents WHERE id=NEW.parent_agent_id AND club_id=NEW.club_id;
  IF NOT FOUND THEN RAISE EXCEPTION 'parent agent must belong to the same club' USING ERRCODE='23514';END IF;
  IF NEW.parent_agent_id=NEW.id OR EXISTS(WITH RECURSIVE chain AS (
    SELECT id,parent_agent_id FROM public.agents WHERE id=NEW.parent_agent_id AND club_id=NEW.club_id
    UNION SELECT a.id,a.parent_agent_id FROM public.agents a JOIN chain c ON a.id=c.parent_agent_id WHERE a.club_id=NEW.club_id
   ) SELECT 1 FROM chain WHERE id=NEW.id) THEN
   RAISE EXCEPTION 'agent hierarchy cannot contain a cycle' USING ERRCODE='23514';END IF;
  IF new_edge AND (parent.role='sub_agent' OR parent.status IS DISTINCT FROM 'active') THEN
   RAISE EXCEPTION 'new parent must be an active agent or super agent' USING ERRCODE='23514';END IF;
  parent_terms:=to_jsonb(parent);
 END IF;
 IF NEW.role='sub_agent' AND (TG_OP='INSERT' OR NEW.role IS DISTINCT FROM OLD.role)
  AND EXISTS(SELECT 1 FROM public.agents c WHERE c.parent_agent_id=NEW.id) THEN
  RAISE EXCEPTION 'a sub-agent cannot have agent children' USING ERRCODE='23514';END IF;

 FOREACH field IN ARRAY ARRAY['commission_rate','player_rakeback_rate','credit_limit'] LOOP
  new_value:=(new_terms->>field)::numeric;old_value:=(old_terms->>field)::numeric;
  IF TG_OP='INSERT' OR new_value IS DISTINCT FROM old_value THEN
   IF new_value IS NULL OR new_value::text IN('NaN','Infinity','-Infinity') OR new_value<0
    OR (field='credit_limit' AND new_value<>round(new_value,2))
    OR (field='commission_rate' AND new_value>0.70)
    OR (field='player_rakeback_rate' AND new_value>0.50) THEN
    RAISE EXCEPTION 'invalid agent agreement value: %',field USING ERRCODE='23514';END IF;
  END IF;
  IF field='player_rakeback_rate' AND (TG_OP='INSERT' OR new_value IS DISTINCT FROM old_value)
     AND new_value > COALESCE((new_terms->>'commission_rate')::numeric, 0) THEN
   RAISE EXCEPTION 'agent player_rakeback_rate cannot exceed its own commission_rate' USING ERRCODE='23514';END IF;
  IF field<>'player_rakeback_rate' AND NEW.parent_agent_id IS NOT NULL AND (new_edge OR new_value IS DISTINCT FROM old_value) THEN
   parent_value:=(parent_terms->>field)::numeric;
   IF parent_value IS NOT NULL AND greatest(new_value-parent_value,0)>
      (CASE WHEN new_edge THEN 0 ELSE greatest(old_value-parent_value,0) END) THEN
    RAISE EXCEPTION 'agent % cannot exceed or worsen its parent cap',field USING ERRCODE='23514';END IF;
  END IF;
  IF TG_OP='UPDATE' AND field<>'player_rakeback_rate' AND new_value IS DISTINCT FROM old_value THEN
   FOR child IN SELECT to_jsonb(a) AS terms FROM public.agents a WHERE a.parent_agent_id=NEW.id AND a.club_id=NEW.club_id LOOP
    child_value:=(child.terms->>field)::numeric;
    IF child_value IS NOT NULL AND greatest(child_value-new_value,0)>greatest(child_value-old_value,0) THEN
     RAISE EXCEPTION 'agent % cannot be reduced below an existing child agreement',field USING ERRCODE='23514';END IF;
   END LOOP;
  END IF;
 END LOOP;
 RETURN NEW;
END $function$

public.fn_guard_club_lifecycle_write().def:
CREATE OR REPLACE FUNCTION public.fn_guard_club_lifecycle_write()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE
  v_retirement_write boolean :=
    coalesce(current_setting('app.club_retirement_write', true), '') = 'on';
  v_maintenance boolean :=
    auth.uid() IS NULL
    AND coalesce(current_setting('app.club_retirement_maintenance', true), '') = 'on';
BEGIN
  IF TG_OP = 'DELETE' THEN
    IF NOT v_maintenance AND NOT (
      auth.uid() IS NULL
      AND (OLD.name LIKE 'Crest Cert %' OR OLD.name LIKE 'Preset Crest Cert %')
      AND coalesce(current_setting('app.ledger_maintenance', true), '') <> ''
      AND coalesce(current_setting('app.game_management_retention', true), '') = 'on'
    ) THEN
      RAISE EXCEPTION 'CLUB_RECORD_RETAINED: real club records cannot be deleted'
        USING ERRCODE = '55000';
    END IF;
    RETURN OLD;
  END IF;

  IF OLD.lifecycle_status = 'retired' AND NOT v_maintenance THEN
    RAISE EXCEPTION 'CLUB_RETIRED: this club is read-only'
      USING ERRCODE = '55000';
  END IF;

  IF (NEW.lifecycle_status, NEW.retired_at, NEW.retired_by, NEW.retirement_reason)
       IS DISTINCT FROM
     (OLD.lifecycle_status, OLD.retired_at, OLD.retired_by, OLD.retirement_reason)
     AND NOT v_retirement_write
     AND NOT v_maintenance THEN
    RAISE EXCEPTION 'CLUB_LIFECYCLE_REQUIRES_RPC: use fn_retire_settled_club'
      USING ERRCODE = '42501';
  END IF;

  RETURN NEW;
END
$function$

public.fn_guard_retired_club_mutation().def:
CREATE OR REPLACE FUNCTION public.fn_guard_retired_club_mutation()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE
  v_club_id uuid;
  v_old_club_id uuid;
  v_maintenance boolean :=
    auth.uid() IS NULL
    AND coalesce(current_setting('app.club_retirement_maintenance', true), '') = 'on';
BEGIN
  IF v_maintenance THEN
    IF TG_OP = 'DELETE' THEN RETURN OLD; END IF;
    RETURN NEW;
  END IF;

  IF TG_OP = 'DELETE' THEN
    IF TG_TABLE_NAME = 'unions' THEN
      v_club_id := OLD.id;
    ELSIF TG_TABLE_NAME = 'table_seats' THEN
      SELECT t.club_id INTO v_club_id FROM public.tables t WHERE t.id = OLD.table_id;
    ELSIF TG_TABLE_NAME IN ('tournament_players', 'tournament_escrow') THEN
      SELECT t.club_id INTO v_club_id FROM public.tournaments t WHERE t.id = OLD.tournament_id;
    ELSIF TG_TABLE_NAME = 'chip_escrow' THEN
      SELECT cr.club_id INTO v_club_id FROM public.cashout_requests cr WHERE cr.id = OLD.cashout_request_id;
    ELSIF TG_TABLE_NAME = 'credit_invoices' THEN
      SELECT a.club_id INTO v_club_id FROM public.agents a WHERE a.id = OLD.agent_id;
    ELSIF TG_TABLE_NAME = 'tournament_schedule_spawns' THEN
      SELECT s.club_id INTO v_club_id FROM public.tournament_schedules s WHERE s.id = OLD.schedule_id;
    ELSIF TG_TABLE_NAME = 'managed_game_schedules' THEN
      IF OLD.game_kind = 'table' THEN
        SELECT t.club_id INTO v_club_id FROM public.tables t WHERE t.id = OLD.game_id;
      ELSE
        SELECT t.club_id INTO v_club_id FROM public.tournaments t WHERE t.id = OLD.game_id;
      END IF;
    ELSIF TG_TABLE_NAME IN ('wheel_configs','diamond_game_configs') THEN
      IF OLD.host_kind = 'club' THEN v_club_id := OLD.host_id; END IF;
    ELSIF TG_TABLE_NAME = 'wheel_pools' THEN
      SELECT c.host_id INTO v_club_id FROM public.wheel_configs c
       WHERE c.host_id=OLD.host_id AND c.host_kind='club';
    ELSIF TG_TABLE_NAME = 'diamond_game_pools' THEN
      SELECT c.host_id INTO v_club_id FROM public.diamond_game_configs c
       WHERE c.host_id=OLD.host_id AND c.game=OLD.game AND c.host_kind='club';
    ELSE
      v_club_id := OLD.club_id;
    END IF;
  ELSE
    IF TG_TABLE_NAME = 'unions' THEN
      v_club_id := NEW.id;
    ELSIF TG_TABLE_NAME = 'table_seats' THEN
      SELECT t.club_id INTO v_club_id FROM public.tables t WHERE t.id = NEW.table_id;
    ELSIF TG_TABLE_NAME IN ('tournament_players', 'tournament_escrow') THEN
      SELECT t.club_id INTO v_club_id FROM public.tournaments t WHERE t.id = NEW.tournament_id;
    ELSIF TG_TABLE_NAME = 'chip_escrow' THEN
      SELECT cr.club_id INTO v_club_id FROM public.cashout_requests cr WHERE cr.id = NEW.cashout_request_id;
    ELSIF TG_TABLE_NAME = 'credit_invoices' THEN
      SELECT a.club_id INTO v_club_id FROM public.agents a WHERE a.id = NEW.agent_id;
    ELSIF TG_TABLE_NAME = 'tournament_schedule_spawns' THEN
      SELECT s.club_id INTO v_club_id FROM public.tournament_schedules s WHERE s.id = NEW.schedule_id;
    ELSIF TG_TABLE_NAME = 'managed_game_schedules' THEN
      IF NEW.game_kind = 'table' THEN
        SELECT t.club_id INTO v_club_id FROM public.tables t WHERE t.id = NEW.game_id;
      ELSE
        SELECT t.club_id INTO v_club_id FROM public.tournaments t WHERE t.id = NEW.game_id;
      END IF;
    ELSIF TG_TABLE_NAME IN ('wheel_configs','diamond_game_configs') THEN
      IF NEW.host_kind = 'club' THEN v_club_id := NEW.host_id; END IF;
    ELSIF TG_TABLE_NAME = 'wheel_pools' THEN
      SELECT c.host_id INTO v_club_id FROM public.wheel_configs c
       WHERE c.host_id=NEW.host_id AND c.host_kind='club';
    ELSIF TG_TABLE_NAME = 'diamond_game_pools' THEN
      SELECT c.host_id INTO v_club_id FROM public.diamond_game_configs c
       WHERE c.host_id=NEW.host_id AND c.game=NEW.game AND c.host_kind='club';
    ELSE
      v_club_id := NEW.club_id;
    END IF;

    IF TG_OP = 'UPDATE' THEN
      IF TG_TABLE_NAME = 'unions' THEN
        v_old_club_id := OLD.id;
      ELSIF TG_TABLE_NAME = 'table_seats' THEN
        SELECT t.club_id INTO v_old_club_id FROM public.tables t WHERE t.id = OLD.table_id;
      ELSIF TG_TABLE_NAME IN ('tournament_players', 'tournament_escrow') THEN
        SELECT t.club_id INTO v_old_club_id FROM public.tournaments t WHERE t.id = OLD.tournament_id;
      ELSIF TG_TABLE_NAME = 'chip_escrow' THEN
        SELECT cr.club_id INTO v_old_club_id FROM public.cashout_requests cr WHERE cr.id = OLD.cashout_request_id;
      ELSIF TG_TABLE_NAME = 'credit_invoices' THEN
        SELECT a.club_id INTO v_old_club_id FROM public.agents a WHERE a.id = OLD.agent_id;
      ELSIF TG_TABLE_NAME = 'tournament_schedule_spawns' THEN
        SELECT s.club_id INTO v_old_club_id FROM public.tournament_schedules s WHERE s.id = OLD.schedule_id;
      ELSIF TG_TABLE_NAME = 'managed_game_schedules' THEN
        IF OLD.game_kind = 'table' THEN
          SELECT t.club_id INTO v_old_club_id FROM public.tables t WHERE t.id = OLD.game_id;
        ELSE
          SELECT t.club_id INTO v_old_club_id FROM public.tournaments t WHERE t.id = OLD.game_id;
        END IF;
      ELSIF TG_TABLE_NAME IN ('wheel_configs','diamond_game_configs') THEN
        IF OLD.host_kind = 'club' THEN v_old_club_id := OLD.host_id; END IF;
      ELSIF TG_TABLE_NAME = 'wheel_pools' THEN
        SELECT c.host_id INTO v_old_club_id FROM public.wheel_configs c
         WHERE c.host_id=OLD.host_id AND c.host_kind='club';
      ELSIF TG_TABLE_NAME = 'diamond_game_pools' THEN
        SELECT c.host_id INTO v_old_club_id FROM public.diamond_game_configs c
         WHERE c.host_id=OLD.host_id AND c.game=OLD.game AND c.host_kind='club';
      ELSE
        v_old_club_id := OLD.club_id;
      END IF;
    END IF;
  END IF;

  IF TG_TABLE_NAME = 'unions' AND v_club_id IS NOT NULL THEN
    PERFORM pg_advisory_xact_lock(hashtextextended('cashier-hierarchy:' || v_club_id::text, 0));
  END IF;

  -- Lock both scopes in UUID order.  A writer that began just before retirement
  -- waits here and then observes the committed retired lifecycle.
  PERFORM 1
    FROM public.clubs c
   WHERE c.id IN (v_club_id, v_old_club_id)
   ORDER BY c.id
   FOR KEY SHARE;

  -- These two owning stores have no club FK. Recheck after the shared
  -- parent lock: cleanup may have deleted that parent while this writer waited.
  IF TG_OP <> 'DELETE' AND TG_TABLE_NAME IN ('cash_games','tournament_schedules')
     AND v_club_id IS NOT NULL
     AND NOT EXISTS (SELECT 1 FROM public.clubs WHERE id=v_club_id) THEN
    RAISE EXCEPTION 'CLUB_NOT_FOUND: game records require their owning club'
      USING ERRCODE='23503';
  END IF;

  IF (v_club_id IS NOT NULL OR v_old_club_id IS NOT NULL) AND EXISTS (
    SELECT 1 FROM public.clubs c
     WHERE c.id IN (v_club_id, v_old_club_id) AND c.lifecycle_status = 'retired'
  ) THEN
    RAISE EXCEPTION 'CLUB_RETIRED: gameplay and cashier records are read-only'
      USING ERRCODE = '55000';
  END IF;

  IF TG_OP = 'DELETE' THEN RETURN OLD; END IF;
  RETURN NEW;
END
$function$

public.fn_invoice_accounting_ledger_tran.def:
CREATE OR REPLACE FUNCTION public.fn_invoice_accounting_ledger_transfer(p_ledger_id uuid)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE leg public.chip_ledger%ROWTYPE; inv_id uuid; issuer_kind text; issuer_id uuid; payee_kind text; payee_id uuid; kind text; recorded_role text; routed boolean; correction public.accounting_correction_documents%ROWTYPE;
BEGIN
 SELECT * INTO leg FROM public.chip_ledger WHERE id=p_ledger_id;
 IF leg.metadata->>'entry_kind'='launch_closing_position' THEN RETURN NULL; END IF;
 IF public.fn_ca_launch_is_internal_transfer(leg.id) THEN RETURN NULL; END IF;
 IF NOT FOUND OR leg.status IS DISTINCT FROM 'posted' OR leg.amount IS NULL OR leg.amount<=0
    OR leg.amount::text IN('NaN','Infinity','-Infinity') OR leg.amount<>round(leg.amount,2)
 THEN RAISE EXCEPTION 'invalid_accounting_transfer' USING ERRCODE='23514'; END IF;
 IF leg.category='correction' THEN
  PERFORM pg_advisory_xact_lock(hashtextextended('accounting_ledger_invoice:'||leg.id::text,0));
  SELECT * INTO correction FROM public.accounting_correction_documents WHERE source_ledger_id=leg.id;
  IF NOT FOUND THEN RAISE EXCEPTION 'historical_correction_document_unverified' USING ERRCODE='23514';END IF;
  SELECT id INTO inv_id FROM public.settlement_invoices WHERE source_ledger_id=leg.id;
  IF inv_id IS NOT NULL THEN
   IF inv_id IS DISTINCT FROM correction.invoice_id THEN RAISE EXCEPTION 'correction_document_invoice_collision' USING ERRCODE='23514';END IF;
   PERFORM public.fn_accounting_correction_assert_delivery(correction.id);
   RETURN inv_id;
  END IF;
  INSERT INTO public.settlement_invoices(id,club_id,invoice_type,from_entity_type,from_entity_id,to_entity_type,to_entity_id,
    gross_amount,net_amount,deductions,breakdown,status,chips_transferred,transferred_at,due_at,notes,source_ledger_id,created_at)
  VALUES(correction.invoice_id,correction.club_id,'accounting_correction',correction.issuer_type,correction.issuer_id::text,
    correction.payee_type,correction.payee_id::text,correction.amount,correction.amount,0,
    jsonb_build_object('category','correction','correction',public.fn_accounting_correction_payload(correction)),
    'generated',false,NULL,NULL,NULL,leg.id,correction.issued_at) RETURNING id INTO inv_id;
  IF NOT FOUND OR inv_id IS DISTINCT FROM correction.invoice_id THEN RAISE EXCEPTION 'correction_document_invoice_write_missing' USING ERRCODE='23514';END IF;
  PERFORM public.fn_deliver_accounting_invoice(inv_id);
  PERFORM public.fn_accounting_correction_assert_delivery(correction.id);
  RETURN inv_id;
 END IF;
 routed:=COALESCE(leg.metadata->>'routing_version'='3'
  AND current_setting('app.accounting_routing_context',true)=
   CASE WHEN leg.union_id IS NOT NULL THEN leg.union_id::text
    WHEN leg.metadata->>'accounting_scope_kind'='club' AND leg.metadata->>'accounting_scope_id'=leg.club_id::text
     THEN 'club:'||leg.club_id::text END
   ||':'||((leg.metadata->>'period_start')::timestamptz)::text||':'||((leg.metadata->>'period_end')::timestamptz)::text,false);
 recorded_role:=CASE WHEN routed THEN leg.metadata->>'payee_role_at_transfer' END;
 IF routed AND leg.to_type IN('player_wallet','agent_wallet') AND (recorded_role IS NULL OR recorded_role NOT IN('player','sub_agent','agent','super_agent')) THEN
  RAISE EXCEPTION 'routed_payment_recipient_role_missing' USING ERRCODE='23514'; END IF;

 IF leg.from_type IN('union_wallet','union_bank') THEN issuer_kind:='union';issuer_id:=leg.from_entity_id;
 ELSIF leg.from_type='club_treasury' THEN issuer_kind:='club';issuer_id:=leg.from_entity_id;
 ELSIF leg.from_type IN('player_wallet','agent_wallet') THEN issuer_id:=leg.from_entity_id;
   issuer_kind:=CASE WHEN routed OR leg.from_type='agent_wallet' OR EXISTS(SELECT 1 FROM public.agents a WHERE a.user_id=issuer_id AND a.club_id=leg.club_id) THEN 'agent' ELSE 'player' END;
 ELSIF leg.from_type='settlement_suspense' AND leg.category='rakeback' AND leg.club_id IS NOT NULL THEN
   -- Club-issued receipt for the existing clearing-account leg; preserve its actual source in breakdown.
   issuer_kind:='club';issuer_id:=leg.club_id;
 ELSE RAISE EXCEPTION 'unsupported_accounting_transfer_source' USING ERRCODE='23514'; END IF;
 -- Game payout journals retain the physical union_wallets.id store identity.
 -- Accounting parties use unions.id. Resolve only a matching, declared host;
 -- never rewrite the original journal or infer a different union.
 IF leg.category IN('wheel_prize','plinko_prize','crash_prize','crossing_prize','mines_prize')
    AND issuer_kind='union' AND leg.union_id IS NOT NULL
    AND EXISTS(SELECT 1 FROM public.union_wallets w WHERE w.id=issuer_id AND w.union_id=leg.union_id)
 THEN issuer_id:=leg.union_id; END IF;
 IF leg.to_type IN('union_wallet','union_bank') THEN payee_kind:='union';payee_id:=leg.to_entity_id;
 ELSIF leg.to_type='club_treasury' THEN payee_kind:='club';payee_id:=leg.to_entity_id;
 ELSIF leg.to_type IN('player_wallet','agent_wallet') THEN
   payee_id:=leg.to_entity_id;
   payee_kind:=CASE WHEN routed THEN CASE WHEN recorded_role='player' THEN 'player' ELSE 'agent' END WHEN leg.category='commission' OR EXISTS(SELECT 1 FROM public.agents a WHERE a.user_id=payee_id AND a.club_id=leg.club_id) THEN 'agent' ELSE 'player' END;
 ELSE RAISE EXCEPTION 'unsupported_accounting_transfer_recipient' USING ERRCODE='23514'; END IF;
 kind:=CASE WHEN issuer_kind='union' AND payee_kind='club' THEN 'union_to_club'
            WHEN issuer_kind='club' AND payee_kind='agent' THEN 'club_to_agent'
            WHEN issuer_kind='agent' AND payee_kind='agent' THEN 'agent_to_subagent'
            WHEN issuer_kind='agent' AND payee_kind='player' THEN 'agent_to_player' ELSE 'transaction_receipt' END;
 PERFORM pg_advisory_xact_lock(hashtextextended('accounting_ledger_invoice:'||leg.id::text,0));
 SELECT id INTO inv_id FROM public.settlement_invoices WHERE source_ledger_id=leg.id;
 IF inv_id IS NULL THEN
   INSERT INTO public.settlement_invoices(club_id,invoice_type,from_entity_type,from_entity_id,to_entity_type,to_entity_id,
    gross_amount,net_amount,deductions,breakdown,status,chips_transferred,transferred_at,notes,source_ledger_id)
   VALUES(COALESCE(leg.club_id,leg.union_id),kind,issuer_kind,issuer_id::text,payee_kind,payee_id::text,leg.amount,leg.amount,0,
    COALESCE(leg.metadata,'{}'::jsonb)||jsonb_build_object('ledger_id',leg.id,'category',leg.category,'ledger_from_type',leg.from_type,
      'ledger_from_entity_id',leg.from_entity_id,'ledger_to_type',leg.to_type,'ledger_to_entity_id',leg.to_entity_id,
      'payee_role_at_transfer',CASE WHEN routed AND recorded_role IS NOT NULL THEN recorded_role WHEN payee_kind='player' THEN 'player' ELSE (SELECT a.role FROM public.agents a WHERE a.user_id=payee_id AND a.club_id=leg.club_id ORDER BY a.id LIMIT 1) END),
    'paid',true,leg.created_at,'Receipt For A Posted Accounting Transfer. This Does Not Certify The Entire Weekly Close.',leg.id)
   RETURNING id INTO inv_id;
 END IF;
 PERFORM public.fn_deliver_accounting_invoice(inv_id);
 RETURN inv_id;
END $function$

public.fn_is_platform_admin().def:
CREATE OR REPLACE FUNCTION public.fn_is_platform_admin()
 RETURNS boolean
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE v_role text;
BEGIN
  IF auth.uid() IS NULL THEN RETURN false; END IF;
  SELECT role INTO v_role FROM public.profiles WHERE id = auth.uid();
  -- No profile row, or a NULL role, is not staff: never NULL (#9390).
  RETURN COALESCE(v_role IN ('admin', 'superadmin', 'god'), false);
END;
$function$

