   PERFORM set_config('app.ledger_maintenance',COALESCE(maintenance,''),true);
   END IF;
   INSERT INTO public.chip_ledger(performed_by,from_type,from_entity_id,to_type,to_entity_id,amount,category,club_id,union_id,description,idempotency_key,metadata,
    pre_from_balance,post_from_balance,pre_to_balance,post_to_balance)
    VALUES(COALESCE(auth.uid(),'2d1cd6c3-5700-4af9-a271-d4863fdab20d'::uuid),CASE WHEN g.funded_from='club_treasury' THEN 'club_treasury' ELSE 'agent_wallet' END,
     CASE WHEN g.funded_from='club_treasury' THEN r.club_id ELSE g.payer_user END,g.destination_kind,r.user_id,amount,'rakeback',r.club_id,p_union_id,'Weekly rakeback from certified historical payer',
     CASE WHEN g.typed_wallet THEN 'round3-period:own-agent-v1:'||r.period_id::text||':payer:'||g.payer_kind||':'||g.payer_entity::text||':destination:'||g.destination_kind ELSE 'round3-period:v3:'||r.period_id::text||CASE WHEN r.payer_kind='split' THEN ':payer:'||g.payer_kind||':'||g.payer_entity::text ELSE '' END END,jsonb_build_object('routing_version',3,'accounting_scope_kind',p_scope_kind,'accounting_scope_id',p_scope_id,'period_id',r.period_id,'period_start',p_period_start,'period_end',p_period_end,
       'certificate_id',r.certificate_id,'source_fingerprint',r.fingerprint,'payout_id',payout_id,'wallet_transaction_id',wallet_id,'payee_role_at_transfer',CASE WHEN g.destination_kind='agent_wallet' THEN 'agent' ELSE 'player' END,
       'paid_from',g.funded_from,'owner_share_payer',CASE WHEN g.payer_kind='agent' AND g.funded_from='club_treasury' THEN g.payer_user END)||CASE WHEN g.typed_wallet THEN jsonb_build_object('wallet_destination_version','own-agent-v1','destination_kind',g.destination_kind) ELSE '{}'::jsonb END,
      payer_before,payer_after,player_before,player_after) RETURNING id INTO ledger_id;
   IF g.typed_wallet THEN
    INSERT INTO public.accounting_rakeback_wallet_transfers(payout_id,calculation_id,period_id,payer_kind,payer_entity_id,destination_kind,amount,ledger_id,wallet_transaction_id)
    VALUES(payout_id,r.certificate_id,r.period_id,g.payer_kind,g.payer_entity,g.destination_kind,amount,ledger_id,wallet_id);
   ELSIF r.payer_kind='split' THEN
    INSERT INTO public.accounting_rakeback_payer_transfers(payout_id,calculation_id,period_id,payer_kind,payer_entity_id,amount,ledger_id,wallet_transaction_id)
    VALUES(payout_id,r.certificate_id,r.period_id,g.payer_kind,g.payer_entity,amount,ledger_id,wallet_id);
   END IF;
   SELECT count(*) INTO receipt_count FROM public.settlement_invoices i WHERE i.source_ledger_id=ledger_id AND i.status='paid'
    AND i.chips_transferred AND i.message_sent AND i.net_amount=amount AND i.gross_amount=amount AND i.deductions=0;
   IF receipt_count<>1 THEN RAISE EXCEPTION 'routed_rakeback_invoice_delivery_incomplete' USING ERRCODE='23514'; END IF;
   END LOOP;
   paid:=paid+r.owed;payees:=payees+1;
  END IF;
  UPDATE public.rakeback_periods SET status='paid',paid_at=now() WHERE id=r.period_id;
  INSERT INTO pg_temp._routed_player_now VALUES(r.period_id);
  IF v_batched AND clock_timestamp()>v_stop
    AND NOT smarter_private.weekly_payout_owns_round(p_scope_kind,p_scope_id,p_period_start,p_period_end,3) THEN EXIT; END IF;
 END LOOP;
 SELECT count(*) INTO v_remaining FROM pg_temp._routed_player_todo t WHERE NOT EXISTS(SELECT 1 FROM pg_temp._routed_player_now n WHERE n.period_id=t.period_id);
 IF v_remaining>0 THEN
  -- A batch: every locked wallet must hold exactly what this batch paid it.
  UPDATE pg_temp._routed_player_wallets w SET delta=COALESCE((SELECT sum(x.delta) FROM(
   SELECT t.club_id,t.user_id,f.owed AS delta FROM pg_temp._routed_player_todo t JOIN pg_temp._routed_player_now n ON n.period_id=t.period_id JOIN pg_temp._routed_player_funding f ON f.period_id=t.period_id WHERE f.destination_kind='player_wallet'
   ) x
   WHERE x.club_id=w.club_id AND x.user_id=w.user_id),0);
  UPDATE pg_temp._routed_agent_wallets w SET delta=COALESCE((SELECT sum(x.delta)FROM(SELECT f.club_id,f.payer_user user_id,-f.owed delta FROM pg_temp._routed_player_funding f JOIN pg_temp._routed_player_now n ON n.period_id=f.period_id WHERE f.funded_from='agent_wallet' UNION ALL SELECT f.club_id,t.user_id,f.owed FROM pg_temp._routed_player_funding f JOIN pg_temp._routed_player_now n ON n.period_id=f.period_id JOIN pg_temp._routed_player_todo t ON t.period_id=f.period_id WHERE f.destination_kind='agent_wallet')x WHERE x.club_id=w.club_id AND x.user_id=w.user_id),0);
 END IF;
 PERFORM set_config('app.ledger_autoskip_clubs',COALESCE(club_skip,''),true);PERFORM set_config('app.ledger_autoskip_club_members',COALESCE(member_skip,''),true);PERFORM set_config('app.ledger_autoskip_agents',COALESCE(agent_skip,''),true);
 PERFORM set_config('app.deleted_wallet_routing_stage',COALESCE(deleted_deferral,''),true);
 CREATE TEMP TABLE IF NOT EXISTS _routed_split_returns(club_id uuid,user_id uuid,returned numeric,PRIMARY KEY(club_id,user_id)) ON COMMIT DROP;
 TRUNCATE pg_temp._routed_split_returns;
 INSERT INTO pg_temp._routed_split_returns(club_id,user_id,returned)
 SELECT lr.club_id,lr.horse_id,sum(lr.amount)-b.returned FROM public.ca_horse_club_split_late_returns lr
  JOIN pg_temp._routed_player_wallets pw ON pw.club_id=lr.club_id AND pw.user_id=lr.horse_id
  JOIN pg_temp._routed_split_return_openings b ON b.club_id=lr.club_id AND b.user_id=lr.horse_id
  GROUP BY lr.club_id,lr.horse_id,b.returned;
 IF EXISTS(SELECT 1 FROM pg_temp._routed_player_wallets w JOIN public.club_members cm ON cm.club_id=w.club_id AND cm.user_id=w.user_id
   LEFT JOIN pg_temp._routed_split_returns sr ON sr.club_id=w.club_id AND sr.user_id=w.user_id
   WHERE cm.chip_balance IS DISTINCT FROM w.opening+w.delta-COALESCE(sr.returned,0))
 THEN RAISE EXCEPTION 'routed_rakeback_final_balance_incorrect' USING ERRCODE='23514',
   DETAIL=left('final_balance_disagreements: '||COALESCE((SELECT jsonb_agg(jsonb_build_object('club',w.club_id,'user',w.user_id,'opening',w.opening,'delta',w.delta,'split_returned',COALESCE(sr.returned,0),'actual',cm.chip_balance,'off_by',round(cm.chip_balance-(w.opening+w.delta-COALESCE(sr.returned,0)),2)) ORDER BY abs(cm.chip_balance-(w.opening+w.delta-COALESCE(sr.returned,0))) DESC) FROM pg_temp._routed_player_wallets w JOIN public.club_members cm ON cm.club_id=w.club_id AND cm.user_id=w.user_id LEFT JOIN pg_temp._routed_split_returns sr ON sr.club_id=w.club_id AND sr.user_id=w.user_id WHERE cm.chip_balance IS DISTINCT FROM w.opening+w.delta-COALESCE(sr.returned,0))::text,'none'),3200); END IF;
 IF EXISTS(SELECT 1 FROM pg_temp._routed_agent_wallets w LEFT JOIN public.agents a ON a.club_id=w.club_id AND a.user_id=w.user_id
   WHERE a.agent_wallet_balance IS DISTINCT FROM w.opening+w.delta)
 THEN RAISE EXCEPTION 'routed_rakeback_final_agent_wallet_incorrect' USING ERRCODE='23514',
   DETAIL=left('final_balance_disagreements: '||COALESCE((SELECT jsonb_agg(jsonb_build_object('club',w.club_id,'user',w.user_id,'opening',w.opening,'delta',w.delta,'actual',a.agent_wallet_balance,'off_by',round(COALESCE(a.agent_wallet_balance,0)-(w.opening+w.delta),2)) ORDER BY abs(COALESCE(a.agent_wallet_balance,0)-(w.opening+w.delta)) DESC) FROM pg_temp._routed_agent_wallets w LEFT JOIN public.agents a ON a.club_id=w.club_id AND a.user_id=w.user_id WHERE a.agent_wallet_balance IS DISTINCT FROM w.opening+w.delta)::text,'none'),3200); END IF;
 -- All original transfer, invoice and net-wallet checks above still decide
 -- whether this stage may finish. Return only free net chips afterward,
 -- retaining published unpaid player obligations across bounded chunks.
 FOR v_deleted IN
  SELECT cm.club_id,cm.user_id FROM public.club_members cm
  JOIN public.profiles dp ON dp.id=cm.user_id AND dp.status='deleted'
  WHERE EXISTS(SELECT FROM pg_temp._routed_player_wallets w WHERE w.club_id=cm.club_id AND w.user_id=cm.user_id) AND EXISTS(SELECT FROM pg_temp._routed_player_todo t JOIN pg_temp._routed_player_now done ON done.period_id=t.period_id WHERE t.club_id=cm.club_id AND t.user_id=cm.user_id) ORDER BY cm.club_id,cm.user_id
 LOOP
  SELECT cm.chip_balance,coalesce(cm.held_chips,0),coalesce(cm.locked_chips,0)
   INTO STRICT v_deleted_before,v_deleted_held,v_deleted_locked FROM public.club_members cm
   WHERE cm.club_id=v_deleted.club_id AND cm.user_id=v_deleted.user_id;
  SELECT dwr_bank.chip_treasury INTO STRICT v_deleted_bank FROM public.clubs dwr_bank WHERE dwr_bank.id=v_deleted.club_id;
  v_deleted_return:=public.fn_ca_deleted_wallet_bank_return(v_deleted.club_id,v_deleted.user_id,'player_wallet');
  IF v_deleted_return->'success' IS DISTINCT FROM 'true'::jsonb
   OR v_deleted_return->>'reserved_rakeback' IS NULL OR (v_deleted_return->>'reserved_rakeback')::numeric<0
   OR (v_deleted_return->>'reserved_rakeback')::numeric::text IN('NaN','Infinity','-Infinity')
   OR (v_deleted_return->>'amount')::numeric IS DISTINCT FROM greatest(v_deleted_before-v_deleted_held-v_deleted_locked-(v_deleted_return->>'reserved_rakeback')::numeric,0)
   OR (v_deleted_return->>'player_chips')::numeric IS DISTINCT FROM (v_deleted_return->>'amount')::numeric
   OR (v_deleted_return->>'agent_chips')::numeric IS DISTINCT FROM 0::numeric
   OR NOT EXISTS(SELECT FROM public.club_members cm WHERE cm.club_id=v_deleted.club_id AND cm.user_id=v_deleted.user_id
     AND cm.chip_balance=v_deleted_before-(v_deleted_return->>'amount')::numeric
     AND coalesce(cm.held_chips,0)=v_deleted_held AND coalesce(cm.locked_chips,0)=v_deleted_locked)
   OR NOT EXISTS(SELECT FROM public.clubs dwr_bank WHERE dwr_bank.id=v_deleted.club_id AND dwr_bank.chip_treasury=v_deleted_bank+(v_deleted_return->>'amount')::numeric)
  THEN RAISE EXCEPTION 'deleted_weekly_net_bank_return_not_conserved' USING ERRCODE='23514'; END IF;
 END LOOP;
 FOR v_deleted IN
  SELECT a.club_id,a.user_id FROM public.agents a
  JOIN public.profiles dp ON dp.id=a.user_id AND dp.status='deleted'
  WHERE EXISTS(SELECT FROM pg_temp._routed_agent_wallets w WHERE w.club_id=a.club_id AND w.user_id=a.user_id)
   AND EXISTS(SELECT FROM pg_temp._routed_player_funding f JOIN pg_temp._routed_player_now done ON done.period_id=f.period_id
    WHERE f.club_id=a.club_id AND ((f.funded_from='agent_wallet' AND f.payer_user=a.user_id) OR(f.destination_kind='agent_wallet' AND EXISTS(SELECT FROM pg_temp._routed_player_todo t WHERE t.period_id=f.period_id AND t.user_id=a.user_id)))) ORDER BY a.club_id,a.user_id
 LOOP
  SELECT a.agent_wallet_balance INTO STRICT v_deleted_before FROM public.agents a
   WHERE a.club_id=v_deleted.club_id AND a.user_id=v_deleted.user_id;
  SELECT dwr_bank.chip_treasury INTO STRICT v_deleted_bank FROM public.clubs dwr_bank WHERE dwr_bank.id=v_deleted.club_id;
  v_deleted_return:=public.fn_ca_deleted_wallet_bank_return(v_deleted.club_id,v_deleted.user_id,'agent_wallet');
  IF v_deleted_return->'success' IS DISTINCT FROM 'true'::jsonb
   OR v_deleted_return->>'reserved_rakeback' IS NULL OR (v_deleted_return->>'reserved_rakeback')::numeric<0
   OR (v_deleted_return->>'reserved_rakeback')::numeric::text IN('NaN','Infinity','-Infinity')
   OR (v_deleted_return->>'amount')::numeric IS DISTINCT FROM greatest(v_deleted_before-(v_deleted_return->>'reserved_rakeback')::numeric,0)
   OR (v_deleted_return->>'agent_chips')::numeric IS DISTINCT FROM (v_deleted_return->>'amount')::numeric
   OR (v_deleted_return->>'player_chips')::numeric IS DISTINCT FROM 0::numeric
   OR NOT EXISTS(SELECT FROM public.agents a WHERE a.club_id=v_deleted.club_id AND a.user_id=v_deleted.user_id
     AND a.agent_wallet_balance=v_deleted_before-(v_deleted_return->>'amount')::numeric)
   OR NOT EXISTS(SELECT FROM public.clubs dwr_bank WHERE dwr_bank.id=v_deleted.club_id AND dwr_bank.chip_treasury=v_deleted_bank+(v_deleted_return->>'amount')::numeric)
  THEN RAISE EXCEPTION 'deleted_weekly_net_bank_return_not_conserved' USING ERRCODE='23514'; END IF;
 END LOOP;
 PERFORM set_config('app.accounting_routing_context',COALESCE(routing_context,''),true);

 IF v_remaining>0 THEN
  RETURN jsonb_build_object('success',false,'batch_committed',true,'round',3,'routing_version',3,'source_version',2,'scope_kind',p_scope_kind,'scope_id',p_scope_id,
   'periods',(SELECT count(*) FROM pg_temp._routed_player_items),'paid_periods',(SELECT count(*) FROM pg_temp._routed_player_done)+(SELECT count(*) FROM pg_temp._routed_player_now),
   'remaining',v_remaining,'source_fingerprint',fingerprint,'plan_used',v_plan_used);
 END IF;
 -- The round's totals include what earlier batches of it paid.
 SELECT COALESCE(sum(i.owed),0),count(*) INTO v_paid_before,v_payees_before FROM pg_temp._routed_player_items i
  JOIN pg_temp._routed_player_done d ON d.period_id=i.period_id WHERE i.owed>0;
 paid:=paid+v_paid_before;payees:=payees+v_payees_before;
 result:=jsonb_build_object('success',true,'round',3,'name','certified_payer_to_players','routing_version',3,'source_version',2,'source_contract_version',3,'scope_kind',p_scope_kind,'scope_id',p_scope_id,
  'amount',paid,'payees',payees,'shortfalls',0,'periods',(SELECT count(*) FROM pg_temp._routed_player_items),'detail','[]'::jsonb);
 result:=result||jsonb_build_object('existing_transfer_economic_plan',smarter_private.existing_rakeback_transfer_scope_economic_plan(p_scope_kind,p_scope_id,p_period_start,p_period_end,'player'),
  'existing_transfer_receipts',smarter_private.existing_rakeback_transfer_scope_receipts(p_scope_kind,p_scope_id,p_period_start,p_period_end,'player'));
 INSERT INTO public.accounting_routed_settlement_runs(union_id,standalone_club_id,period_start,period_end,round_no,source_fingerprint,result)
  VALUES(p_union_id,standalone_club,p_period_start,p_period_end,3,fingerprint,result);
 RETURN result;
END $function$

public.fn_settle_tournament_obligation_b.def:
CREATE OR REPLACE FUNCTION public.fn_settle_tournament_obligation_before_atomic_batch_gate(p_tournament_id uuid, p_kind text, p_place integer, p_user_id uuid, p_amount numeric, p_source text, p_description text DEFAULT NULL::text, p_adjustment_id uuid DEFAULT NULL::uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_kind        text := lower(btrim(COALESCE(p_kind, '')));
  v_row_kind    text;
  v_place       integer;
  v_amount      numeric := round(COALESCE(p_amount, 0), 2);
  v_t           record;
  v_ob          public.tournament_obligations%ROWTYPE;
  v_seeded_paid numeric := 0;
  v_owed        numeric;
  v_pay         numeric;
  v_key         text;
  v_category    text;
  v_desc        text;
  v_pool_kinds  text[] := ARRAY['place','late_reg_adjustment','bubble_protection','final_table_deal','satellite_remainder','seat'];
  -- Rows paid from the BOUNTY pool (or recorded on the target by a satellite),
  -- never from the prize pool. Everything else counts against the pool.
  v_not_pool    text[] := ARRAY['satellite_seat','bounty','mystery_bounty','bounty_residual','own_bounty','mystery_bounty_residual'];
  v_paid_pool   numeric := 0;
  v_credited    boolean;
  v_alert_ctx   jsonb;
  v_payout_source text;
  v_adj         public.ca_manual_adjustments%ROWTYPE;
  v_src         text := lower(btrim(COALESCE(p_source, '')));
  v_can         jsonb;
  v_short       numeric;
BEGIN
  IF p_tournament_id IS NULL OR p_user_id IS NULL THEN
    RETURN jsonb_build_object('ok', false, 'paid', 0, 'already_paid', 0,
      'refused_reason', 'missing_ids', 'obligation_id', NULL, 'idempotency_key', NULL);
  END IF;
  IF v_kind NOT IN ('place','bounty','bounty_residual','mystery_bounty','refund','seat',
                    'satellite_remainder','bubble_protection','final_table_deal','late_reg_adjustment') THEN
    RETURN jsonb_build_object('ok', false, 'paid', 0, 'already_paid', 0,
      'refused_reason', 'unknown_kind', 'obligation_id', NULL, 'idempotency_key', NULL);
  END IF;
  IF p_amount IS NULL OR p_amount::text IN ('NaN','Infinity','-Infinity') THEN
    RETURN jsonb_build_object('ok', false, 'paid', 0, 'already_paid', 0,
      'refused_reason', 'invalid_amount', 'obligation_id', NULL, 'idempotency_key', NULL);
  END IF;
  IF p_amount < 0 THEN
    RETURN jsonb_build_object('ok', false, 'paid', 0, 'already_paid', 0,
      'refused_reason', 'negative_amount', 'obligation_id', NULL, 'idempotency_key', NULL);
  END IF;

  -- A late-registration top-up is the SAME obligation as the place it corrects:
  -- it carries the new total and the difference is what moves.
  v_row_kind := CASE WHEN v_kind = 'late_reg_adjustment' THEN 'place' ELSE v_kind END;
  v_place    := CASE WHEN v_row_kind IN ('place') THEN p_place ELSE NULL END;
  IF v_row_kind = 'place' AND v_place IS NULL THEN
    RETURN jsonb_build_object('ok', false, 'paid', 0, 'already_paid', 0,
      'refused_reason', 'place_required', 'obligation_id', NULL, 'idempotency_key', NULL);
  END IF;

  IF v_row_kind = 'place' AND v_place <= 0 THEN
    RETURN jsonb_build_object('ok', false, 'paid', 0, 'already_paid', 0,
      'refused_reason', 'invalid_place', 'obligation_id', NULL, 'idempotency_key', NULL);
  END IF;

  -- Kill switch (Lane E): an open freeze on tournament payouts refuses everything.
  IF to_regclass('public.ca_payout_freeze') IS NOT NULL THEN
    IF EXISTS (SELECT 1 FROM public.ca_payout_freeze f
                WHERE f.scope = 'tournament_payouts' AND f.cleared_at IS NULL) THEN
      RETURN jsonb_build_object('ok', false, 'paid', 0, 'already_paid', 0,
        'refused_reason', 'payout_frozen', 'obligation_id', NULL, 'idempotency_key', NULL);
    END IF;
  END IF;

  /* CHIP STANDARD PHASE 6.1 (2026-09-05): A SETTLEMENT FROM OUTSIDE THE
     PLATFORM NEEDS AN APPROVED ADJUSTMENT. The engine, the recovery and the
     registered doors settle under their own names (ca_settle_sources). Any
     other caller - a migration, an operator, an agent under CLAUDE.md 10.9 -
     must name a ca_manual_adjustments row that is approved, for this event,
     this player, at least this amount, in chips; the row is marked settled
     when the chips move and the obligation carries its id. p_adjustment_id
     was accepted and ignored until today. */
  IF NOT (v_src LIKE 'engine.%' OR EXISTS (SELECT 1 FROM public.ca_settle_sources s WHERE s.source = v_src)) THEN
    IF p_adjustment_id IS NULL THEN
      RETURN jsonb_build_object('ok', false, 'paid', 0, 'already_paid', 0,
        'refused_reason', 'adjustment_required', 'obligation_id', NULL, 'idempotency_key', NULL,
        'detail', format('source %s is not a platform settle source; name an approved ca_manual_adjustments row (fn_ca_adjustment_under_10_9 writes one)', COALESCE(NULLIF(v_src, ''), '<none>')));
    END IF;
    SELECT * INTO v_adj FROM public.ca_manual_adjustments WHERE id = p_adjustment_id FOR UPDATE;
    IF NOT FOUND OR v_adj.status <> 'approved' OR v_adj.asset <> 'chips'
       OR v_adj.tournament_id IS DISTINCT FROM p_tournament_id
       OR v_adj.target_kind <> 'player_wallet' OR v_adj.target_id IS DISTINCT FROM p_user_id
       OR v_adj.amount < v_amount THEN
      RETURN jsonb_build_object('ok', false, 'paid', 0, 'already_paid', 0,
        'refused_reason', 'adjustment_mismatch', 'obligation_id', NULL, 'idempotency_key', NULL,
        'detail', 'the adjustment must be approved, in chips, for this tournament, this player wallet, and at least this amount');
    END IF;
  END IF;

  SELECT t.id, t.name, t.club_id, t.prize_pool, t.bounty_pool, t.bounty_pool_paid, t.status
    INTO v_t
    FROM public.tournaments t
   WHERE t.id = p_tournament_id
   FOR UPDATE;
  IF NOT FOUND THEN
    RETURN jsonb_build_object('ok', false, 'paid', 0, 'already_paid', 0,
      'refused_reason', 'tournament_not_found', 'obligation_id', NULL, 'idempotency_key', NULL);
  END IF;

  -- Upsert the obligation. amount_owed only ever rises.
  IF v_place IS NOT NULL THEN
    SELECT * INTO v_ob FROM public.tournament_obligations
     WHERE tournament_id = p_tournament_id AND kind = v_row_kind AND place = v_place
     FOR UPDATE;
  ELSE
    SELECT * INTO v_ob FROM public.tournament_obligations
     WHERE tournament_id = p_tournament_id AND kind = v_row_kind AND place IS NULL AND user_id = p_user_id
     FOR UPDATE;
  END IF;

  IF NOT FOUND THEN
    -- Legacy seeding: what did the old key shapes already pay for this obligation?
    IF v_place IS NOT NULL THEN
      SELECT COALESCE(sum(tp.amount), 0) INTO v_seeded_paid
        FROM public.tournament_payouts tp
       WHERE tp.tournament_id = p_tournament_id AND tp."position" = v_place
         AND COALESCE(tp.source, '') NOT IN ('satellite_seat');
    ELSIF v_row_kind = 'refund' THEN
      SELECT COALESCE(sum(w.amount), 0) INTO v_seeded_paid
        FROM public.wallet_transactions w
       WHERE w.related_entity_id = p_tournament_id AND w.user_id = p_user_id
         AND w.type = 'credit' AND lower(w.category) IN ('refund','tournament_refund');
    END IF;
    v_seeded_paid := round(v_seeded_paid, 2);
    v_owed := GREATEST(v_amount, v_seeded_paid);

    -- Refuse before creating a new debt. The later guard still protects an
    -- existing unpaid obligation; neither path rewrites historical records.
    -- Only an existing positive legacy payment exempts a no-payment replay.
    IF v_row_kind = 'place' AND (v_seeded_paid <= 0 OR v_amount > v_seeded_paid)
       AND EXISTS (
         SELECT 1 FROM public.tournament_obligations o
          WHERE o.tournament_id = p_tournament_id AND o.kind = 'place'
            AND o.user_id = p_user_id AND o.place <> v_place
            AND o.amount_paid > 0
       ) THEN
      v_pay := round(v_amount - v_seeded_paid, 2);
      v_alert_ctx := jsonb_build_object(
        'kind','second_place_prize_refused','tournament_id',p_tournament_id,
        'user_id',p_user_id,'place',v_place,'amount',v_pay,'source',p_source);
      PERFORM public.fn_raise_server_financial_alert(
        'critical','fn_settle_tournament_obligation',
        format('Refused a second structure place: this player already holds a paid place in tournament %s', p_tournament_id),
        v_alert_ctx, 'obl:second_place:' || p_tournament_id::text || ':' || p_user_id::text);
      RETURN jsonb_build_object(
        'ok',false,'paid',0,'already_paid',v_seeded_paid,
        'refused_reason','player_already_holds_a_place',
        'obligation_id',NULL,'idempotency_key',NULL);
    END IF;

    INSERT INTO public.tournament_obligations
      (tournament_id, kind, place, user_id, amount_owed, amount_paid, source)
    VALUES (p_tournament_id, v_row_kind, v_place, p_user_id, v_owed, v_seeded_paid, p_source)
    RETURNING * INTO v_ob;
  ELSE
  -- The player on record for a place is whoever was first paid for it; a
  -- different user asking for an already-paid place gets a refusal, not chips.
  IF v_place IS NOT NULL AND v_ob.user_id IS NOT NULL AND v_ob.user_id <> p_user_id AND v_ob.amount_paid > 0 THEN
    RETURN jsonb_build_object('ok', false, 'paid', 0, 'already_paid', v_ob.amount_paid,
      'refused_reason', 'place_paid_to_another_user', 'obligation_id', v_ob.id, 'idempotency_key', NULL);
  END IF;

    -- An existing unpaid second-place row also remains unchanged on refusal.
    -- A no-payment replay still reports the durable unpaid amount.
    IF v_row_kind = 'place' AND v_amount > v_ob.amount_paid
       AND EXISTS (
         SELECT 1 FROM public.tournament_obligations o
          WHERE o.tournament_id = p_tournament_id AND o.kind = 'place'
            AND o.user_id = p_user_id AND o.place <> v_place
            AND o.amount_paid > 0
       ) THEN
      v_pay := round(v_amount - v_ob.amount_paid, 2);
      v_alert_ctx := jsonb_build_object(
        'kind','second_place_prize_refused','tournament_id',p_tournament_id,
        'user_id',p_user_id,'place',v_place,'amount',v_pay,'source',p_source);
      PERFORM public.fn_raise_server_financial_alert(
        'critical','fn_settle_tournament_obligation',
        format('Refused a second structure place: this player already holds a paid place in tournament %s', p_tournament_id),
        v_alert_ctx, 'obl:second_place:' || p_tournament_id::text || ':' || p_user_id::text);
      RETURN jsonb_build_object(
        'ok',false,'paid',0,'already_paid',v_ob.amount_paid,
        'refused_reason','player_already_holds_a_place',
        'obligation_id',v_ob.id,'idempotency_key',NULL);
    END IF;

    IF v_amount > v_ob.amount_owed THEN
      UPDATE public.tournament_obligations
         SET amount_owed = v_amount, updated_at = now(), user_id = COALESCE(user_id, p_user_id)
       WHERE id = v_ob.id
       RETURNING * INTO v_ob;
    END IF;
  END IF;

  v_pay := round(LEAST(v_amount, v_ob.amount_owed) - v_ob.amount_paid, 2);
  IF v_pay <= 0 THEN
    -- A replay of an older, smaller request can still leave the recorded
    -- obligation unpaid. Report the durable total, not the caller's amount.
    RETURN jsonb_build_object('ok', true, 'paid', 0, 'already_paid', v_ob.amount_paid,
      'amount_owed', v_ob.amount_owed, 'amount_paid', v_ob.amount_paid,
      'remaining', GREATEST(0, v_ob.amount_owed - v_ob.amount_paid),
      'fully_settled', v_ob.amount_paid >= v_ob.amount_owed,
      'refused_reason', NULL, 'obligation_id', v_ob.id, 'idempotency_key', NULL);
  END IF;

  -- R2b: one finisher, one place.
  IF v_row_kind = 'place' THEN
    IF EXISTS (SELECT 1 FROM public.tournament_obligations o
                WHERE o.tournament_id = p_tournament_id AND o.kind = 'place'
                  AND o.user_id = p_user_id AND o.place <> v_place AND o.amount_paid > 0) THEN
      v_alert_ctx := jsonb_build_object('kind','second_place_prize_refused','tournament_id',p_tournament_id,
        'user_id',p_user_id,'place',v_place,'amount',v_pay,'source',p_source);
      PERFORM public.fn_raise_server_financial_alert('critical','fn_settle_tournament_obligation',
        format('Refused a second structure place: this player already holds a paid place in tournament %s', p_tournament_id),
        v_alert_ctx, 'obl:second_place:' || p_tournament_id::text || ':' || p_user_id::text);
      RETURN jsonb_build_object('ok', false, 'paid', 0, 'already_paid', v_ob.amount_paid,
        'refused_reason', 'player_already_holds_a_place', 'obligation_id', v_ob.id, 'idempotency_key', NULL);
    END IF;
  END IF;

  /* R1 (chip standard Phase 5.1, 2026-09-04): the ESCROW BALANCE decides.
     tournament_escrow holds what the event holds, per bank; a place is paid
     from the prize bank, a bounty from the bounty bank, a refund from all
     three. When the balance knows the event, the counter cap below is not
     consulted; the escrow trigger refuses again inside the credit if a race
     gets past this read. An event the balance has never seen (opened on its
     first row) keeps the old counter cap for this call. */
  v_can := public.fn_ca_escrow_can_pay(p_tournament_id, v_row_kind, v_pay);

  /* A BANK THAT IS SHORT PAYS WHAT IT HOLDS (2026-09-07). This used to refuse
     the whole payment, so a bank 180.00 short of a 13,441.68 obligation paid
     the winner nothing and froze 13,261.68 - three events were sitting like
     that when this was written. Paying what is there takes nothing from
     anybody: amount_owed is untouched, so the remainder stays owed and
     payable, and the credit is still capped by the bank and refused again by
     the escrow trigger if a race gets past this read. */
  IF (v_can->>'known')::boolean AND NOT (v_can->>'ok')::boolean
     AND COALESCE((v_can->>'available')::numeric, 0) >= 0.01 THEN
    v_short := round(v_pay - (v_can->>'available')::numeric, 2);
    v_pay   := round((v_can->>'available')::numeric, 2);
    v_alert_ctx := jsonb_build_object('kind','escrow_short_paid_what_it_holds',
      'tournament_id',p_tournament_id,'tournament',v_t.name,'user_id',p_user_id,
      'obligation_kind',v_kind,'place',v_place,'paid',v_pay,'still_owed',v_short,
      'prize_balance',(v_can->>'prize_balance')::numeric,
      'bounty_balance',(v_can->>'bounty_balance')::numeric,
      'fee_balance',(v_can->>'fee_balance')::numeric,'source',p_source);
    PERFORM public.fn_raise_server_financial_alert('critical','fn_settle_tournament_obligation',
      format('Paid %s of %s to %s for %s and %s is still owed: the escrow bank was short (%s)',
             v_pay, v_pay + v_short, p_user_id, v_kind, v_short, v_t.name),
      v_alert_ctx, 'obl:escrow_short_partial:' || v_ob.id::text);
    v_can := public.fn_ca_escrow_can_pay(p_tournament_id, v_row_kind, v_pay);
  END IF;

  IF (v_can->>'known')::boolean AND NOT (v_can->>'ok')::boolean THEN
    v_alert_ctx := jsonb_build_object('kind','escrow_short','tournament_id',p_tournament_id,'tournament',v_t.name,
      'user_id',p_user_id,'obligation_kind',v_kind,'place',v_place,'requested',v_pay,
      'escrow_available',(v_can->>'available')::numeric,'prize_balance',(v_can->>'prize_balance')::numeric,
      'bounty_balance',(v_can->>'bounty_balance')::numeric,'fee_balance',(v_can->>'fee_balance')::numeric,'source',p_source);
    PERFORM public.fn_raise_server_financial_alert('critical','fn_settle_tournament_obligation',
      format('Refused %s to %s for %s: the escrow holds %s for that bank (%s)',
             v_pay, p_user_id, v_kind, (v_can->>'available')::numeric, v_t.name),
      v_alert_ctx, 'obl:escrow_short:' || v_ob.id::text);
    RETURN jsonb_build_object('ok', false, 'paid', 0, 'already_paid', v_ob.amount_paid,
      'refused_reason', 'escrow_short', 'obligation_id', v_ob.id, 'idempotency_key', NULL);
  END IF;

  -- R1-lite (counter cap), only for an event the balance has never seen.
  IF v_row_kind = ANY (v_pool_kinds) AND NOT (v_can->>'known')::boolean THEN
    SELECT COALESCE(sum(tp.amount), 0) INTO v_paid_pool
      FROM public.tournament_payouts tp
     WHERE tp.tournament_id = p_tournament_id
       AND NOT (COALESCE(tp.source, '') = ANY (v_not_pool));
    IF v_paid_pool + v_pay > COALESCE(v_t.prize_pool, 0) + 0.05 THEN
      v_alert_ctx := jsonb_build_object('kind','escrow_short','tournament_id',p_tournament_id,'tournament',v_t.name,
        'user_id',p_user_id,'obligation_kind',v_kind,'place',v_place,'requested',v_pay,
        'paid_from_pool_so_far',v_paid_pool,'prize_pool',v_t.prize_pool,'source',p_source);
      PERFORM public.fn_raise_server_financial_alert('critical','fn_settle_tournament_obligation',
        format('Refused %s to %s for %s: the prize pool of %s has already paid %s (%s)',
               v_pay, p_user_id, v_kind, round(COALESCE(v_t.prize_pool,0),2), v_paid_pool, v_t.name),
        v_alert_ctx, 'obl:escrow_short:' || v_ob.id::text);
      RETURN jsonb_build_object('ok', false, 'paid', 0, 'already_paid', v_ob.amount_paid,
        'refused_reason', 'escrow_short', 'obligation_id', v_ob.id, 'idempotency_key', NULL);
    END IF;
  END IF;

  /* THE KEY NAMES THE TOURNAMENT (Lane A3, 2026-09-02). fn_credit_player_wallet_once
     resolves WHICH club wallet to credit from a 'tourney:<id>:...' key
     (tournament_players.club_id for that entry); any other shape falls back to
     fn_player_home_club, which is the club the player joined FIRST, not the
     club they bought in from. Measured in the rolled-back probe: 3 of 4 places
     landed in the wrong club under the old 'obl:<id>:<n>' shape. No 'obl:' key
     was ever spent in production, so the rename costs nothing. */
  v_key := 'tourney:' || p_tournament_id::text || ':obl:' || v_ob.id::text || ':' || (round(v_ob.amount_paid * 100))::bigint::text;
  v_category := CASE
                  WHEN v_row_kind IN ('bounty','bounty_residual','mystery_bounty') THEN 'bounty'
                  WHEN v_row_kind = 'refund' THEN 'refund'
                  ELSE 'prize'
                END;
  /* THE PAYOUT RECORD KEEPS ITS CLASS (2026-09-02). tournament_payouts.source is
     the CLASS of a payment ('structure', 'reconcile', 'late_reg_adjustment',
     'final_table_deal', ...) and every detector downstream filters on it:
     fn_tournament_guarantee_check and fn_tournament_double_paid_obligations
     whitelist it, fn_payout_guarantee_check blacklists the bounty classes. The
     engine calls this function with its own provenance ('engine.finishTournament'
     and friends), which the first build wrote straight into that column - so
     the moment the engine cut over, the guarantee check would have counted
     every engine-paid place as unpaid. Provenance stays on
     tournament_obligations.source; the payout row gets the class. */
  v_payout_source := CASE
    WHEN lower(COALESCE(p_source, '')) IN ('structure','reconcile','hu_shortfall','spin_backpay',
         'overlay_backpay','late_reg_adjustment','final_table_deal','bubble_protection',
         'satellite_remainder','clawback') THEN lower(p_source)
    WHEN v_kind = 'late_reg_adjustment' THEN 'late_reg_adjustment'
    WHEN v_row_kind IN ('final_table_deal','bubble_protection','satellite_remainder') THEN v_row_kind
    ELSE 'structure'
  END;
  v_desc := COALESCE(NULLIF(btrim(p_description), ''),
              CASE
                WHEN v_row_kind = 'place' THEN format('Tournament prize: position %s', v_place)
                WHEN v_row_kind = 'refund' THEN 'Tournament refund'
                ELSE format('Tournament %s', replace(v_row_kind, '_', ' '))
              END);

  PERFORM set_config('app.money_path', 'fn_settle_tournament_obligation', true);

  -- Guard against a key that was already spent while the obligation says otherwise:
  -- that means the obligation row was rebuilt without its payments, and paying
  -- again would be exactly the bug this function exists to end.
  IF EXISTS (SELECT 1 FROM public.wallet_credit_idempotency k WHERE k.key = v_key) THEN
    RAISE EXCEPTION 'fn_settle_tournament_obligation: key % already spent while obligation % shows paid %; refusing',
      v_key, v_ob.id, v_ob.amount_paid;
  END IF;

  v_credited := public.fn_credit_and_log(
    p_user_id, v_pay, v_key, v_category, v_desc, p_tournament_id,
    'PLAYER', NULL, NULL,
    CASE WHEN v_category = 'prize' THEN v_place ELSE NULL END,
    CASE WHEN v_category = 'prize' THEN v_payout_source ELSE NULL END);

  PERFORM set_config('app.money_path', '', true);

  IF NOT v_credited THEN
    -- fn_credit_and_log returns false only when the key was already spent or a
    -- guard inside it refused; either way no chips moved for THIS call.
    RETURN jsonb_build_object('ok', false, 'paid', 0, 'already_paid', v_ob.amount_paid,
      'refused_reason', 'credit_refused', 'obligation_id', v_ob.id, 'idempotency_key', v_key);
  END IF;

  PERFORM set_config('app.pnl_tournament_obligation_credit_key',v_key,true);
  UPDATE public.tournament_obligations
     SET amount_paid = amount_paid + v_pay,
         user_id     = COALESCE(user_id, p_user_id),
         source      = COALESCE(p_source, source),
         adjustment_id = COALESCE(adjustment_id, p_adjustment_id),
         updated_at  = now(),
         settled_at  = CASE WHEN amount_paid + v_pay >= amount_owed THEN now() ELSE settled_at END
   WHERE id = v_ob.id;
  PERFORM set_config('app.pnl_tournament_obligation_credit_key','',true);
  IF v_adj.id IS NOT NULL THEN
    UPDATE public.ca_manual_adjustments SET status = 'settled' WHERE id = v_adj.id;
  END IF;

  -- ok acknowledges this operation; it is not proof that the entire debt
  -- was paid. v_ob holds the pre-credit row, so include this call's v_pay.
  RETURN jsonb_build_object('ok', true, 'paid', v_pay, 'already_paid', v_ob.amount_paid,
    'amount_owed', v_ob.amount_owed, 'amount_paid', v_ob.amount_paid + v_pay,
    'remaining', GREATEST(0, v_ob.amount_owed - v_ob.amount_paid - v_pay),
    'fully_settled', v_ob.amount_paid + v_pay >= v_ob.amount_owed,
    'refused_reason', NULL, 'obligation_id', v_ob.id, 'idempotency_key', v_key);
END;
$function$

public.fn_spin_absorb_club_pool_into_uni.def:
CREATE OR REPLACE FUNCTION public.fn_spin_absorb_club_pool_into_union(p_club_id uuid, p_union_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE
  v_bal numeric; v_seed numeric; v_after numeric; v_pool_id uuid; v_saved jsonb;
BEGIN
  IF p_club_id IS NULL OR p_union_id IS NULL OR p_club_id = p_union_id THEN
    RETURN jsonb_build_object('ok', true, 'reason', 'nothing_to_absorb');
  END IF;

  SELECT id, balance, seeded_amount INTO v_pool_id, v_bal, v_seed
    FROM public.spin_bonus_pools WHERE club_id = p_club_id FOR UPDATE;

  IF NOT FOUND THEN
    RETURN jsonb_build_object('ok', true, 'reason', 'club_had_no_pool');
  END IF;

  /* A pool below zero owes the house; paying it "into" the treasury would
     book a negative payment. No pool has ever been below zero (0 of 49 on
     2026-10-02); refuse by name rather than invent the rule here. */
  IF COALESCE(v_bal,0) < 0 THEN
    RAISE EXCEPTION 'spin_pool_below_zero_cannot_be_absorbed: club % pool %', p_club_id, v_bal
      USING ERRCODE = '23514';
  END IF;

  /* THE POOL PAYS THE TREASURY, BY NAME (2026-10-02, 20261002140203). One
     leg, spin reserve (this pool) -> club treasury; the pool's own journal
     stands down for the zeroing below instead of booking a second leg. */
  v_saved := public.fn_ca_ledger_declaration_save(ARRAY['spin_bonus_pools']);
  PERFORM public.fn_ca_declare_ledger('treasury_transfer', 'spin_reserve', v_pool_id,
                                      NULL, NULL, ARRAY['spin_bonus_pools']);

  IF COALESCE(v_bal,0) > 0 THEN
    v_after := public.fn_spin_move_owner_wallet(p_club_id, 'club', 'chip_treasury', v_bal);
    IF v_after IS NULL THEN
      RAISE EXCEPTION 'cannot return the % Spins balance of club % to its treasury', v_bal, p_club_id;
    END IF;

    INSERT INTO public.spin_reserve_ledger (club_id, kind, amount, balance_after, note)
    VALUES (p_club_id, 'merge', -v_bal, 0,
            format('Spins wallet closed on joining union %s - entire balance (including %s of outstanding seed) paid to the club main bank, to keep or disburse at its own discretion',
                   p_union_id, COALESCE(v_seed,0)));
  END IF;

  UPDATE public.spin_bonus_pools
     SET balance = 0, seeded_amount = 0, required_seed_at_activation = 0,
         seed_source_wallet = NULL, offered_max_stake = 0,
         is_active = false, deactivated_at = now(), updated_at = now()
   WHERE club_id = p_club_id;

  PERFORM public.fn_ca_ledger_declaration_restore(v_saved);

  RETURN jsonb_build_object('ok', true, 'club_id', p_club_id, 'union_id', p_union_id,
    'paid_to_main_bank', COALESCE(v_bal,0), 'club_treasury_after', v_after);
END;
$function$

public.fn_spin_pool_follows_union_member.def:
CREATE OR REPLACE FUNCTION public.fn_spin_pool_follows_union_membership()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
BEGIN
  IF NEW.union_id IS NOT NULL AND OLD.union_id IS DISTINCT FROM NEW.union_id THEN
    PERFORM public.fn_close_club_wallets_on_union_join(NEW.id, NEW.union_id);
  END IF;
  RETURN NEW;
END;
$function$

public.fn_sync_club_member_count().def:
CREATE OR REPLACE FUNCTION public.fn_sync_club_member_count()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE v_club uuid; v_union uuid;
BEGIN
  FOR v_club IN
    SELECT DISTINCT x FROM unnest(ARRAY[
      CASE WHEN TG_OP <> 'DELETE' THEN NEW.club_id END,
      CASE WHEN TG_OP <> 'INSERT' THEN OLD.club_id END
    ]) AS t(x) WHERE x IS NOT NULL
  LOOP
    PERFORM public.fn_apply_club_ladder(v_club);
    FOR v_union IN
      SELECT uc.union_id FROM public.union_clubs uc WHERE uc.club_id = v_club
    LOOP
      PERFORM public.fn_apply_union_ladder(v_union);
    END LOOP;
  END LOOP;
  RETURN COALESCE(NEW, OLD);
END;
$function$

public.fn_sync_club_staff_notice_group(p.def:
CREATE OR REPLACE FUNCTION public.fn_sync_club_staff_notice_group(p_club uuid)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'extensions'
AS $function$
DECLARE v_conversation uuid; v_name text;
BEGIN
 PERFORM pg_advisory_xact_lock(hashtextextended('club-staff-notice-group:'||p_club::text,0));
 SELECT name INTO v_name FROM public.clubs WHERE id=p_club;
 IF NOT FOUND THEN
  DELETE FROM public.social_conversation_participants WHERE conversation_id IN(SELECT conversation_id FROM public.club_messenger_staff_notice_groups WHERE club_id=p_club);
  RETURN;
 END IF;
 SELECT conversation_id INTO v_conversation FROM public.club_messenger_staff_notice_groups WHERE club_id=p_club;
 IF v_conversation IS NULL AND EXISTS(SELECT 1 FROM public.club_members m WHERE m.club_id=p_club AND public.fn_club_messenger_staff_role(p_club,m.user_id) IS NOT NULL) THEN
  INSERT INTO public.social_conversations(is_group,is_request,group_name) VALUES(true,false,v_name||' - Notice Board') RETURNING id INTO v_conversation;
  INSERT INTO public.club_messenger_staff_notice_groups(club_id,conversation_id) VALUES(p_club,v_conversation);
 END IF;
 IF v_conversation IS NULL THEN RETURN; END IF;
 DELETE FROM public.social_conversation_participants p WHERE p.conversation_id=v_conversation AND public.fn_club_messenger_staff_role(p_club,p.user_id) IS NULL;
 INSERT INTO public.social_conversation_participants(conversation_id,user_id)
 SELECT v_conversation,m.user_id FROM public.club_members m WHERE m.club_id=p_club AND public.fn_club_messenger_staff_role(p_club,m.user_id) IS NOT NULL
 AND NOT EXISTS(SELECT 1 FROM public.social_conversation_participants p WHERE p.conversation_id=v_conversation AND p.user_id=m.user_id);
END $function$

public.fn_terminal_tournament_evidence_i.def:
CREATE OR REPLACE FUNCTION public.fn_terminal_tournament_evidence_is_immutable()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_tournament_id uuid;
  v_status text;
  v_receipted boolean := false;
  v_old_marker timestamptz;
  v_new_marker timestamptz;
BEGIN
 IF TG_OP='INSERT' AND TG_TABLE_NAME='chip_ledger' AND to_jsonb(NEW)->'metadata'->>'entry_kind'='launch_closing_position' THEN RETURN NEW; END IF;
  IF TG_OP<>'DELETE' AND public.fn_ca_legacy_fee_resolution_write_is_exact(TG_TABLE_NAME,TG_OP,CASE WHEN TG_OP='INSERT' THEN NULL ELSE to_jsonb(OLD) END,to_jsonb(NEW)) THEN RETURN NEW; END IF;
  IF TG_OP = 'INSERT' THEN
    v_tournament_id := NULLIF(to_jsonb(NEW)->>'tournament_id','')::uuid;
  ELSIF TG_OP = 'UPDATE' THEN
    IF NULLIF(to_jsonb(NEW)->>'tournament_id','')::uuid IS DISTINCT FROM
       NULLIF(to_jsonb(OLD)->>'tournament_id','')::uuid THEN
      RAISE EXCEPTION '% rows cannot move between tournaments',TG_TABLE_NAME
        USING ERRCODE = '55000';
    END IF;
    v_tournament_id := NULLIF(to_jsonb(OLD)->>'tournament_id','')::uuid;
  ELSE
    v_tournament_id := NULLIF(to_jsonb(OLD)->>'tournament_id','')::uuid;
  END IF;

  IF v_tournament_id IS NULL THEN
    IF TG_OP = 'DELETE' THEN RETURN OLD; END IF;
    RETURN NEW;
  END IF;
  IF TG_OP <> 'INSERT' AND to_jsonb(OLD) ? 'terminal_closed_at' THEN
    v_old_marker := NULLIF(to_jsonb(OLD)->>'terminal_closed_at','')::timestamptz;
  END IF;
  IF TG_OP <> 'DELETE' AND to_jsonb(NEW) ? 'terminal_closed_at' THEN
    v_new_marker := NULLIF(to_jsonb(NEW)->>'terminal_closed_at','')::timestamptz;
  END IF;
  IF TG_OP = 'INSERT' AND v_new_marker IS NOT NULL THEN
    RAISE EXCEPTION '% rows cannot supply a terminal marker',TG_TABLE_NAME
      USING ERRCODE = '55000';
  END IF;
  IF TG_OP <> 'INSERT' AND v_old_marker IS NOT NULL THEN
    RAISE EXCEPTION 'terminal tournament % has immutable % evidence',
      v_tournament_id,TG_TABLE_NAME USING ERRCODE = '55000';
  END IF;
  IF TG_OP = 'UPDATE' AND v_new_marker IS DISTINCT FROM v_old_marker THEN
    IF public.fn_ca_terminal_marker_transition_is_exact(
         to_jsonb(OLD),to_jsonb(NEW),v_tournament_id) THEN
      RETURN NEW;
    END IF;
    RAISE EXCEPTION '% terminal marker transition is not canonical',TG_TABLE_NAME
      USING ERRCODE = '55000';
  END IF;
  -- A journal row is durable testimony from the instant it names a
  -- tournament. Refuse its UPDATE/DELETE without taking a child-to-parent
  -- lock; a row trigger already owns the child tuple at this point. INSERT is
  -- the only operation that takes the root lock, which preserves the
  -- parent-to-child order used by both terminal authorities.
  IF TG_TABLE_NAME = 'chip_ledger' AND TG_OP <> 'INSERT' THEN
    RAISE EXCEPTION 'tournament chip ledger evidence is append-only'
      USING ERRCODE = '55000';
  END IF;
  IF TG_OP = 'INSERT' THEN
    SELECT upper(COALESCE(t.status::text,'')) INTO v_status
      FROM public.tournaments t
     WHERE t.id = v_tournament_id
     FOR SHARE;
  ELSE
    SELECT upper(COALESCE(t.status::text,'')) INTO v_status
      FROM public.tournaments t
     WHERE t.id = v_tournament_id;
  END IF;
  SELECT EXISTS (
           SELECT 1 FROM public.tournament_terminal_settlements h
            WHERE h.tournament_id = v_tournament_id)
      OR EXISTS (
           SELECT 1 FROM public.tournament_satellite_settlements h
            WHERE h.tournament_id = v_tournament_id)
      OR EXISTS (
           SELECT 1 FROM public.tournament_cancellation_receipts h
            WHERE h.tournament_id = v_tournament_id)
    INTO v_receipted;
  IF v_status IN ('COMPLETED','CANCELLED','CANCELED')
     AND (TG_OP = 'INSERT' OR v_receipted) THEN
    RAISE EXCEPTION
      'terminal tournament % has immutable % evidence',
      v_tournament_id,TG_TABLE_NAME USING ERRCODE = '55000';
  END IF;
  IF TG_OP = 'DELETE' THEN RETURN OLD; END IF;
  RETURN NEW;
END;
$function$

public.fn_terminal_wallet_transaction_is.def:
CREATE OR REPLACE FUNCTION public.fn_terminal_wallet_transaction_is_immutable()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_old_tournament_id uuid;
  v_new_tournament_id uuid;
  v_old_marker timestamptz;
  v_new_marker timestamptz;
  v_new_status text;
BEGIN
  IF TG_OP = 'UPDATE'
     AND NEW.related_entity_id IS DISTINCT FROM OLD.related_entity_id THEN
    RAISE EXCEPTION 'wallet transaction ownership is immutable'
      USING ERRCODE = '55000';
  END IF;
  IF TG_OP <> 'INSERT' THEN
    SELECT t.id INTO v_old_tournament_id FROM public.tournaments t
     WHERE t.id = OLD.related_entity_id;
  END IF;
  IF TG_OP <> 'DELETE' THEN
    SELECT t.id INTO v_new_tournament_id FROM public.tournaments t
     WHERE t.id = NEW.related_entity_id;
  END IF;
  IF TG_OP <> 'INSERT' THEN v_old_marker := OLD.terminal_closed_at; END IF;
  IF TG_OP <> 'DELETE' THEN v_new_marker := NEW.terminal_closed_at; END IF;
  IF TG_OP = 'INSERT' AND v_new_marker IS NOT NULL THEN
    RAISE EXCEPTION 'new wallet transaction cannot supply a terminal marker'
      USING ERRCODE = '55000';
  END IF;
  IF TG_OP <> 'INSERT' AND v_old_marker IS NOT NULL THEN
    RAISE EXCEPTION 'terminal wallet transaction evidence is immutable'
      USING ERRCODE = '55000';
  END IF;
  IF TG_OP = 'UPDATE' AND v_new_marker IS DISTINCT FROM v_old_marker THEN
    IF public.fn_ca_terminal_marker_transition_is_exact(
         to_jsonb(OLD),to_jsonb(NEW),v_old_tournament_id) THEN
      RETURN NEW;
    END IF;
    RAISE EXCEPTION 'wallet transaction terminal marker transition is not canonical'
      USING ERRCODE = '55000';
  END IF;
  IF TG_OP = 'INSERT' AND v_new_tournament_id IS NOT NULL THEN
    SELECT upper(COALESCE(t.status::text,'')) INTO v_new_status
      FROM public.tournaments t
     WHERE t.id = v_new_tournament_id FOR SHARE;
    IF v_new_status IN ('COMPLETED','CANCELLED','CANCELED') THEN
      RAISE EXCEPTION 'terminal wallet transaction evidence is immutable'
        USING ERRCODE = '55000';
    END IF;
  END IF;
  IF public.fn_ca_has_committed_tournament_receipt(v_old_tournament_id)
     OR public.fn_ca_has_committed_tournament_receipt(v_new_tournament_id) THEN
    RAISE EXCEPTION 'terminal wallet transaction evidence is immutable'
      USING ERRCODE = '55000';
  END IF;
  IF TG_OP = 'DELETE' THEN RETURN OLD; END IF;
  RETURN NEW;
END;
$function$

public.fn_tournament_entry_split(p_buy_i.def:
CREATE OR REPLACE FUNCTION public.fn_tournament_entry_split(p_buy_in numeric, p_fee numeric, p_bounty numeric, p_is_bounty boolean)
 RETURNS TABLE(charge numeric, rake numeric, bounty numeric, prize numeric)
 LANGUAGE plpgsql
 IMMUTABLE
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE v_charge numeric; v_rake numeric; v_bounty numeric; v_prize numeric;
BEGIN
  IF NOT COALESCE(p_is_bounty, false) THEN
    -- Non-bounty: unchanged - fee charged on top of the buy-in portion.
    v_charge := round(COALESCE(p_buy_in,0),2) + round(COALESCE(p_fee,0),2);
    v_rake   := round(COALESCE(p_fee,0),2);
    v_bounty := 0;
    v_prize  := round(COALESCE(p_buy_in,0),2);
  ELSE
    -- Bounty event: the rake is exactly the fee. A zero fee is a legitimate
    -- outcome of the whole-number floor rule (totals under 10 take no rake)
    -- and must NEVER be replaced with a percentage default.
    v_charge := round(COALESCE(p_buy_in,0),2) + round(COALESCE(p_fee,0),2);
    v_rake   := round(COALESCE(p_fee,0),2);
    v_bounty := round(COALESCE(p_bounty,0), 2);
    v_prize  := round(v_charge - v_rake - v_bounty, 2);  -- = buy_in - bounty
  END IF;
  RETURN QUERY SELECT v_charge, v_rake, v_bounty, v_prize;
END;
$function$

public.fn_union_eco_terms_evidence(p_uni.def:
CREATE OR REPLACE FUNCTION public.fn_union_eco_terms_evidence(p_union_id uuid, p_start timestamp with time zone, p_end timestamp with time zone)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE first_at timestamptz; r record; previous_terms jsonb; seen boolean:=false;
 terms jsonb; rate numeric; issue text; issues jsonb:='[]'; segments jsonb:='[]';
BEGIN
 IF p_union_id IS NULL OR p_start IS NULL OR p_end IS NULL OR NOT isfinite(p_start) OR NOT isfinite(p_end)
  OR p_end<=p_start OR p_end>statement_timestamp() OR p_end-p_start>interval '8 days' THEN
  RETURN jsonb_build_object('status','blocked','issues',jsonb_build_array('invalid_closed_eco_terms_period'));
 END IF;
 SELECT max(observed_at) INTO first_at FROM public.accounting_agreement_history
  WHERE entity_type='unions' AND union_id=p_union_id AND observed_at<=p_start;
 IF first_at IS NULL THEN
  RETURN jsonb_build_object('status','blocked','issues',jsonb_build_array('eco_terms_opening_coverage_missing'));
 END IF;
 FOR r IN
  SELECT h.*,lead(h.observed_at,1,p_end) OVER(ORDER BY h.observed_at,h.id) AS next_at,
   count(*) OVER(PARTITION BY h.observed_at) AS same_time
  FROM public.accounting_agreement_history h
  WHERE h.entity_type='unions' AND h.union_id=p_union_id AND h.observed_at>=first_at AND h.observed_at<p_end
  ORDER BY h.observed_at,h.id
 LOOP
  terms:=r.after_terms; issue:=NULL;
  IF r.same_time<>1 OR NOT isfinite(r.observed_at) THEN issue:='eco_terms_ambiguous_observation';
  ELSIF r.event_type='baseline' AND NOT EXISTS(SELECT 1 FROM public.union_pnl_eco_observations o
   WHERE o.agreement_id=r.id AND o.union_id=r.union_id AND o.observed_from=r.observed_at AND o.observed_from<=p_start)
   THEN issue:='eco_terms_observation_is_not_original_write';
  ELSIF seen AND r.before_terms IS DISTINCT FROM previous_terms THEN issue:='eco_terms_history_discontinuity';
  ELSIF r.event_type='DELETE' OR terms IS NULL THEN issue:='eco_terms_deleted_during_period';
  ELSIF jsonb_typeof(terms) IS DISTINCT FROM 'object'
    OR NOT terms ?& ARRAY['eco_enabled','eco_base_mode','eco_rate','eco_include_horses'] THEN
   issue:='eco_terms_explicit_configuration_missing';
  ELSIF jsonb_typeof(terms->'eco_enabled') IS DISTINCT FROM 'boolean'
    OR jsonb_typeof(terms->'eco_include_horses') IS DISTINCT FROM 'boolean'
    OR jsonb_typeof(terms->'eco_base_mode') IS DISTINCT FROM 'string'
    OR jsonb_typeof(terms->'eco_rate') IS DISTINCT FROM 'number' THEN issue:='eco_terms_invalid_types';
  ELSIF terms->>'eco_base_mode' NOT IN('club_cash_profit','net_invoice_position','winnings_plus_rake','winnings_only') THEN
   issue:='eco_terms_unsupported_mode';
  ELSIF terms->'eco_include_horses' IS DISTINCT FROM 'true'::jsonb THEN
   issue:='eco_terms_excludes_horses';
  ELSE
   rate:=(terms->>'eco_rate')::numeric;
   IF rate::text IN('NaN','Infinity','-Infinity') OR rate<0 OR rate>1 THEN issue:='eco_terms_invalid_rate'; END IF;
  END IF;
  IF issue IS NOT NULL THEN
   issues:=issues||jsonb_build_array(jsonb_build_object('reason',issue,'agreement_id',r.id));
  END IF;
  segments:=segments||jsonb_build_array(jsonb_build_object('agreement_id',r.id,'observed_at',r.observed_at,
   'from',greatest(p_start,r.observed_at),'to',r.next_at,'terms',terms));
  seen:=true; previous_terms:=terms;
 END LOOP;
 RETURN jsonb_build_object('status',CASE WHEN seen AND issues='[]'::jsonb THEN 'ready' ELSE 'blocked' END,
  'union_id',p_union_id,'period_start',p_start,'period_end',p_end,'issues',issues,'segments',segments,
  'scope','observed_commercial_terms_only','payment_authorized',false);
END $function$

public.fn_union_pnl_capture_original_flo.def:
CREATE OR REPLACE FUNCTION public.fn_union_pnl_capture_original_flow()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE frame public.union_pnl_transaction_frames; scope jsonb;
BEGIN
 -- These are the original cash/table and tournament/liability journal legs.
 -- Other wallet transfers, rakeback and P&L payments are not poker winnings.
 IF NOT ((NEW.from_type IN ('player_wallet','club_treasury') AND NEW.to_type IN ('table_stack','prize_liability'))
  OR (NEW.to_type IN ('player_wallet','club_treasury') AND NEW.from_type IN ('table_stack','prize_liability'))) THEN RETURN NULL; END IF;
 frame:=public.fn_union_pnl_original_frame();
 IF NEW.tournament_id IS NOT NULL THEN
  SELECT jsonb_build_object('game_union_id',t.union_id,'host_club_id',t.club_id,'tournament_id',t.id,'is_private',t.is_private,'asset','chips','unit_scale',2)
  INTO scope FROM public.tournaments t WHERE t.id=NEW.tournament_id;
 ELSE
  SELECT jsonb_build_object('game_union_id',t.union_id,'host_club_id',t.club_id,'tournament_id',t.tournament_id,'is_private',t.is_private,'asset','chips','unit_scale',2)
  INTO scope FROM public.tables t WHERE t.id=NEW.table_id;
 END IF;
 INSERT INTO public.union_pnl_original_flows VALUES(NEW.id,frame.transaction_id,frame.observed_at,COALESCE(scope,'{}'),to_jsonb(NEW));
 RETURN NULL;
END $function$

public.fn_union_pnl_closed_book_barrier(.def:
CREATE OR REPLACE FUNCTION public.fn_union_pnl_closed_book_barrier(p_at timestamp with time zone)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE started timestamptz; book timestamptz;
BEGIN
 IF p_at IS NULL OR NOT isfinite(p_at) OR p_at<>public.fn_union_week_start(p_at) OR p_at>clock_timestamp()
  OR current_setting('transaction_isolation')<>'read committed' THEN
  RAISE EXCEPTION 'closed_original_book_barrier_required' USING ERRCODE='22023'; END IF;
 SELECT captured_at INTO started FROM public.union_pnl_inventory_capture WHERE singleton;
 IF started IS NULL THEN RAISE EXCEPTION 'original_inventory_capture_missing' USING ERRCODE='55000'; END IF;
 book:=public.fn_union_week_start(started);
 WHILE book<p_at LOOP
  PERFORM pg_advisory_xact_lock(hashtextextended('union-pnl-inventory:'||extract(epoch FROM book)::bigint::text,0));
  book:=public.fn_union_week_start(book+interval '8 days');
 END LOOP;
END $function$

public.fn_union_pnl_evidence_report(p_un.def:
CREATE OR REPLACE FUNCTION public.fn_union_pnl_evidence_report(p_union_id uuid, p_start timestamp with time zone, p_end timestamp with time zone)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE v_open jsonb; v_close jsonb; v_issues jsonb:='[]'; v_clubs jsonb; v_eco jsonb; v_terms jsonb;
 v_fence timestamptz; v_bad bigint; v_hands bigint; v_resolved bigint:=0; v_rows bigint; v_cash_reconciled boolean; v_terms_value jsonb; v_cash_rake numeric; v_accepted_rake numeric;
 v_memo_key text; v_memo jsonb; v_report jsonb; v_flows jsonb; v_open_resolved uuid[];
 v_inv boolean; v_cash boolean; v_credit boolean;
 v_cert jsonb; v_generation text;v_hand_parts jsonb;
 v_l_value jsonb;v_l_key jsonb;v_l_witness jsonb;v_l_counts jsonb;
 v_l_valid boolean;v_l_name text;v_l_number numeric;
 v_hand_projected boolean;v_l_snapshot jsonb;v_l_entry jsonb;v_l_complete boolean;
 v_l_checked_at timestamptz;v_l_rows numeric;v_l_bad numeric;v_l_resolved numeric;v_l_unknown numeric;
BEGIN
 IF p_union_id IS NULL OR p_start IS NULL OR p_end IS NULL OR NOT isfinite(p_start) OR NOT isfinite(p_end)
  OR p_start<>public.fn_union_week_start(p_start) OR p_end<>public.fn_union_week_start(p_start+interval '8 days')
  OR p_end>clock_timestamp() THEN RAISE EXCEPTION 'invalid_closed_pnl_evidence_period' USING ERRCODE='22023'; END IF;
 SELECT captured_at INTO v_fence FROM public.union_pnl_weekly_capture WHERE singleton;
 IF v_fence IS NULL OR p_start<=v_fence THEN
  RETURN jsonb_build_object('report_version',1,'status','blocked','basis_certified',false,'payment_authorized',false,
   'issues',jsonb_build_array('week_precedes_complete_original_capture'),'capture_started_at',v_fence,'all_players_included',false);
 END IF;
 IF p_union_id='fade0000-0000-0000-0000-000000000001'::uuid AND p_end>='2026-10-12 07:00:00Z'::timestamptz THEN
  v_generation:=COALESCE(smarter_private.original_inventory_basis_generation(),'original-inventory-245:unqualified');
 END IF;
 -- UNION P&L EVIDENCE MEMO (20260928): one weekly close reaches this report
 -- through preparation (close quality), the cascade (qualified clubs, ECO,
 -- player P&L) and the invoices. Inside a union close attempt
 -- (app.accounting_close_memo='on', set only by fn_weekly_accounting_attempt_begin)
 -- the first complete report of this (union, week) is kept for the rest of
 -- the attempt; attempt_begin and attempt_end clear it and a rolled-back
 -- subtransaction forgets it with its settings. Everywhere else the report is
 -- proved on every call, exactly as before.
 IF current_setting('app.accounting_close_memo',true)='on' THEN
  v_memo_key:=CASE WHEN v_generation='original-inventory-245:unqualified' THEN NULL ELSE COALESCE(v_generation||'|','')||p_union_id::text||'|'||p_start::text||'|'||p_end::text END;
  v_memo:=NULLIF(current_setting('app.union_pnl_evidence_memo',true),'')::jsonb;
  IF v_memo ? v_memo_key THEN RETURN v_memo->v_memo_key; END IF;
 END IF;
 -- UNION P&L NARROW READS (20260929044303): the week's registration events,
 -- hands and tournament credits are read through their narrow projections
 -- (union_pnl_inventory_touches, union_pnl_cash_outcome_touches,
 -- union_pnl_credit_touches), each written by its source row's own insert,
 -- once the throttled backfill has proved it complete; until then through
 -- the original wide rows, statement for statement as before.
 v_inv:=public.fn_union_pnl_projection_ready('inventory_touches');
 v_cash:=public.fn_union_pnl_projection_ready('cash_outcome_touches');
 v_credit:=public.fn_union_pnl_projection_ready('credit_touches');
 -- Both readers wait for the original book's in-flight transactions; this
 -- function is VOLATILE so every subsequent query sees their committed facts.
 -- CHUNKED CLOSE CERTIFICATES (20261003): inside a chunked union close attempt
 -- each expensive read below that found nothing wrong is kept, once proved,
 -- in accounting_close_certificates for the rest of that close of this
 -- closed week (fn_accounting_close_certificate / fn_accounting_close_certify;
 -- both do nothing anywhere else). An attempt whose time budget is spent
 -- after a step it had to prove returns 'warming' - not ready, nothing
 -- certified for payment - and the next attempt continues from the kept
 -- steps. A step that found a problem is kept for ONE HOUR (20261012), as
 -- '<kind>_problem' (fn_accounting_close_problem): it is never certified and
 -- never pays, its issues are reported exactly as before, and an attempt
 -- re-proves it once that hour has passed. Re-proving every problem step on
 -- every attempt is what held job 272's transactions for 3 to 5 minutes.
 v_open:=COALESCE(smarter_private.inventory_basis_cache_read(v_generation,false,'pnl_boundary',p_union_id,p_start,p_start),
  smarter_private.inventory_basis_cache_read(v_generation,true,'pnl_boundary',p_union_id,p_start,p_start));
 IF v_open IS NULL THEN
  v_open:=public.fn_union_pnl_boundary(p_union_id,p_start);
  IF v_open->>'status'='ready' THEN PERFORM smarter_private.inventory_basis_cache_write(v_generation,'pnl_boundary',p_union_id,p_start,p_start,v_open);
  ELSE PERFORM smarter_private.inventory_basis_cache_write(v_generation,'pnl_boundary_problem',p_union_id,p_start,p_start,v_open); END IF;
 END IF;
 IF public.fn_accounting_close_warm_stop() THEN RETURN jsonb_build_object('report_version',1,'status','warming','basis_certified',false,'payment_authorized',false,'union_id',p_union_id,'period_start',p_start,'period_end',p_end,'issues',jsonb_build_array('union_pnl_certification_in_progress'),'all_players_included',false); END IF;
 -- THE WINDOWS GO FIRST (20261012): the plan's two-hour windows (seconds each)
 -- are proved before the steps below, so an attempt that would otherwise
 -- spend its budget re-reading the boundaries and flows proves windows
 -- instead. Outside a chunked close the advance is NULL and nothing changes.
 IF public.fn_accounting_union_earned_plan_advance(p_union_id,p_start,p_end) IS FALSE THEN RETURN jsonb_build_object('report_version',1,'status','warming','basis_certified',false,'payment_authorized',false,'union_id',p_union_id,'period_start',p_start,'period_end',p_end,'issues',jsonb_build_array('union_pnl_certification_in_progress'),'all_players_included',false); END IF;
 v_close:=COALESCE(smarter_private.inventory_basis_cache_read(v_generation,false,'pnl_boundary',p_union_id,p_end,p_end),
  smarter_private.inventory_basis_cache_read(v_generation,true,'pnl_boundary',p_union_id,p_end,p_end));
 IF v_close IS NULL THEN
  v_close:=public.fn_union_pnl_boundary(p_union_id,p_end);
  IF v_close->>'status'='ready' THEN PERFORM smarter_private.inventory_basis_cache_write(v_generation,'pnl_boundary',p_union_id,p_end,p_end,v_close);
  ELSE PERFORM smarter_private.inventory_basis_cache_write(v_generation,'pnl_boundary_problem',p_union_id,p_end,p_end,v_close); END IF;
 END IF;
 IF public.fn_accounting_close_warm_stop() THEN RETURN jsonb_build_object('report_version',1,'status','warming','basis_certified',false,'payment_authorized',false,'union_id',p_union_id,'period_start',p_start,'period_end',p_end,'issues',jsonb_build_array('union_pnl_certification_in_progress'),'all_players_included',false); END IF;
 IF v_open->>'status' IS DISTINCT FROM 'ready' THEN v_issues:=v_issues||jsonb_build_array(jsonb_build_object('reason','opening_basis_incomplete','evidence',v_open)); END IF;
 IF v_close->>'status' IS DISTINCT FROM 'ready' THEN v_issues:=v_issues||jsonb_build_array(jsonb_build_object('reason','closing_basis_incomplete','evidence',v_close)); END IF;
 -- The registrations the opening boundary carried through a valid opening
 -- resolution (union_pnl_opening_registration_resolutions): each one's
 -- original entry is proved from the posted chip ledger, not a funding receipt.
 v_open_resolved:=ARRAY(SELECT (x->>'source_id')::uuid FROM jsonb_array_elements(COALESCE(v_open->'holdings','[]')) x
  WHERE x->>'kind'='deferred_tournament_result' AND x->>'basis'='opening_registration_resolution');
 -- A blocked outcome counts as accepted only through an immutable resolution
 -- receipt re-proved from primary receipts and bound to this exact outcome
 -- (hand, payload hash, evidence). The outcome row itself is never changed.
 -- Only a hand outside the ready/certified/all-players/same-scope shape can
 -- be refused or resolved: those hands (the predicate of
 -- union_pnl_cash_outcomes_unaccepted), found through the projection's shape
 -- flag and re-checked against their rows, never the whole week's evidence.
 SELECT count(*) FILTER(WHERE NOT public.fn_union_pnl_cash_outcome_accepted(o)),
  count(*) FILTER(WHERE (o.evidence->>'status' IS DISTINCT FROM 'ready' OR o.evidence->'basis_certified' IS DISTINCT FROM 'true'::jsonb)
   AND public.fn_union_pnl_cash_outcome_accepted(o))
 INTO v_bad,v_resolved FROM public.fn_union_pnl_week_shaped_hands(p_union_id,p_start,p_end,v_cash) o;
 -- A hand whose provenance link the engine never recorded (its outcome has no
 -- game scope) counts only through its immutable link resolution
 -- (union_pnl_cash_outcome_link_resolutions), in the Union its re-proved scope
 -- names, and is accepted only when its re-proved evidence is certified.

 -- LINKED WINDOW ASSEMBLY: one source snapshot for ALL canonical windows,
 -- stored proofs and STABLE trusted witnesses; subsequent loop reads JSON only.
 v_l_snapshot:=NULL;v_l_complete:=false;v_l_bad:=0;v_l_resolved:=0;v_l_rows:=0;v_l_unknown:=0;
 IF current_setting('app.weekly_accounting_chunked',true)='on'
 AND current_setting('app.accounting_close_memo',true)='on'
 AND v_generation IS NOT NULL AND v_generation<>'original-inventory-245:unqualified'THEN
  WITH canonical AS MATERIALIZED(SELECT * FROM public.fn_accounting_close_windows(p_start,p_end)),
  proofs AS MATERIALIZED(SELECT p.* FROM public.accounting_close_partials p
   WHERE p.kind='pnl_linked_window'AND p.union_id=p_union_id AND p.period_start=p_start AND p.period_end=p_end),
  witnesses AS MATERIALIZED(SELECT w.window_start,w.window_end,
   smarter_private.weekly_hand_parts_witness(p_union_id,w.window_start,w.window_end,v_cash)witness FROM canonical w)
  SELECT jsonb_build_object('expected',(SELECT count(*)FROM canonical),'actual',(SELECT count(*)FROM proofs),
   'entries',(SELECT COALESCE(jsonb_agg(jsonb_build_object(
    'key',jsonb_build_object('union_id',p_union_id::text,'period_start_epoch',extract(epoch FROM p_start),'period_end_epoch',extract(epoch FROM p_end),'window_start_epoch',extract(epoch FROM w.window_start),'window_end_epoch',extract(epoch FROM w.window_end)),
    'window_start',w.window_start,'window_end',w.window_end,'proof',to_jsonb(p),'witness',w.witness,
    'bounds_match',p.window_start=w.window_start AND p.window_end=w.window_end,
    'finite_time',isfinite(p.computed_at),
    'unused_null',p.cash_ids IS NULL AND p.cash_md5 IS NULL AND p.fee_ids IS NULL AND p.fee_md5 IS NULL)
    ORDER BY w.window_start,w.window_end),'[]'::jsonb)FROM witnesses w LEFT JOIN proofs p ON p.window_start=w.window_start))
  INTO v_l_snapshot;
  v_l_checked_at:=clock_timestamp();v_hand_projected:=v_cash;
  IF(v_l_snapshot->>'expected')::bigint>0
   AND v_l_snapshot->'expected'=v_l_snapshot->'actual'
   AND jsonb_array_length(v_l_snapshot->'entries')=(v_l_snapshot->>'expected')::bigint THEN
   v_l_complete:=true;
   FOR v_l_entry IN SELECT value FROM jsonb_array_elements(v_l_snapshot->'entries')LOOP
    IF v_l_entry->'bounds_match'IS DISTINCT FROM'true'::jsonb
     OR v_l_entry->'finite_time'IS DISTINCT FROM'true'::jsonb
     OR v_l_entry->'unused_null'IS DISTINCT FROM'true'::jsonb THEN v_l_complete:=false;EXIT;END IF;
    IF(v_l_entry#>>'{proof,computed_at}')::timestamptz<p_end
     OR(v_l_entry#>>'{proof,computed_at}')::timestamptz<=v_l_checked_at-public.fn_accounting_close_proof_lifetime()
     OR(v_l_entry#>>'{proof,computed_at}')::timestamptz>v_l_checked_at THEN v_l_complete:=false;EXIT;END IF;
    v_l_value:=v_l_entry#>'{proof,value}';v_l_key:=v_l_entry->'key';v_l_witness:=v_l_entry->'witness';

 v_l_valid:=false;
 IF jsonb_typeof(v_l_value)='object'
 AND v_l_value->>'contract'='canonical-linked-validation-v1'
 AND v_l_value->>'generation'=v_generation
 AND v_l_value->'projected'=to_jsonb(v_hand_projected)
 AND v_l_value->>'reader_md5'='798e8c95a26ad587da13151675f47fd1'
 AND v_l_value->>'witness_md5'='a7c22cb171d6d6548707c6aa73fada6d'
 AND v_l_value->'input_key'=v_l_key
 AND v_l_value->'witness'=v_l_witness
 AND v_l_value->>'proof_md5'=md5((v_l_value-'proof_md5')::text)
 AND jsonb_typeof(v_l_value->'counts')='object' THEN
  v_l_counts:=v_l_value->'counts';v_l_valid:=true;
  IF(SELECT array_agg(key ORDER BY key)FROM jsonb_object_keys(v_l_counts)key)
    IS DISTINCT FROM ARRAY['bad','resolved','rows','unknown']THEN v_l_valid:=false;END IF;
  IF v_l_valid THEN
   FOREACH v_l_name IN ARRAY ARRAY['rows','bad','resolved','unknown']LOOP
    IF jsonb_typeof(v_l_counts->v_l_name)IS DISTINCT FROM'number'
     OR(v_l_counts->>v_l_name)!~'^[0-9]{1,19}$'THEN v_l_valid:=false;EXIT;END IF;
    v_l_number:=(v_l_counts->>v_l_name)::numeric;
    IF v_l_number>9223372036854775807 THEN v_l_valid:=false;EXIT;END IF;
   END LOOP;
  END IF;
  IF v_l_valid THEN
   IF (v_l_counts->>'rows')::numeric IS DISTINCT FROM
    (v_l_counts->>'bad')::numeric+(v_l_counts->>'resolved')::numeric+(v_l_counts->>'unknown')::numeric THEN v_l_valid:=false;END IF;
  END IF;
 END IF;

    IF NOT v_l_valid THEN v_l_complete:=false;EXIT;END IF;
    v_l_rows:=v_l_rows+(v_l_counts->>'rows')::numeric;v_l_bad:=v_l_bad+(v_l_counts->>'bad')::numeric;
    v_l_resolved:=v_l_resolved+(v_l_counts->>'resolved')::numeric;v_l_unknown:=v_l_unknown+(v_l_counts->>'unknown')::numeric;
   END LOOP;
   IF greatest(v_l_rows,v_l_bad,v_l_resolved,v_l_unknown)>9223372036854775807 THEN v_l_complete:=false;END IF;
  END IF;
 END IF;
