public.zz_chip_ledger_key_is_claimed_onc.def:
CREATE OR REPLACE FUNCTION public.zz_chip_ledger_key_is_claimed_once()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
BEGIN
  /* 99.92% of legs carry no key and this does nothing for them. */
  IF NEW.idempotency_key IS NULL THEN
    RETURN NEW;
  END IF;

  /* No ON CONFLICT: the unique violation IS the refusal, and it must reach the
     caller exactly as ux_chip_ledger_idempotency_key's does today. Both are
     live until the cut; either one refusing is the correct outcome. */
  INSERT INTO public.chip_ledger_idem (idempotency_key, leg_id, created_at)
  VALUES (NEW.idempotency_key, NEW.id, COALESCE(NEW.created_at, now()));

  RETURN NEW;
END;
$function$

smarter_private.admit_own_agent_source(p.def:
CREATE OR REPLACE FUNCTION smarter_private.admit_own_agent_source(p_type text, p_source uuid)
 RETURNS boolean
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
AS $function$
DECLARE s record;raw jsonb;canonical jsonb;old_rows jsonb;source_proof jsonb;w_from timestamptz;w_to timestamptz;key text;old_setting text;posted int;expected int;
BEGIN
 IF NOT public.fn_caller_is_engine()OR p_type NOT IN('cash_rake_accrual','tournament_fee_accrual')OR p_type IS NULL OR p_source IS NULL THEN RAISE EXCEPTION 'own_agent_interpretation_not_authorised' USING ERRCODE='42501';END IF;
 SELECT x.*,CASE WHEN x.source_type='tournament_fee_accrual' THEN public.fn_accounting_tournament_source_terms_at(f.tournament_id,f.charged_at,f.contract)ELSE x.earned_at END terms_at
 INTO s FROM public.accounting_payable_earning_sources x LEFT JOIN public.accounting_tournament_fee_sources f ON f.id=CASE WHEN x.source_type='tournament_fee_accrual'THEN x.source_id END WHERE x.source_type=p_type AND x.source_id=p_source;
 IF NOT FOUND THEN RAISE EXCEPTION 'own_agent_interpretation_payable_source_required' USING ERRCODE='23514';END IF;
 IF EXISTS(SELECT FROM public.accounting_own_agent_interpretations a WHERE a.source_type=p_type AND a.source_id=p_source)THEN RETURN false;END IF;
 canonical:=smarter_private.own_agent_interpreted_contract(s.contract,s.club_id,s.player_id,s.rake_credit,s.union_id,s.terms_at);
 IF canonical IS NULL THEN RETURN false;END IF;
 w_from:=public.fn_union_week_start(s.earned_at);w_to:=public.fn_union_week_start(w_from+interval '8 days');
 key:=CASE WHEN s.coordinator_union_id IS NULL THEN'club-accounting:'ELSE'union-accounting:'END||coalesce(s.coordinator_union_id,s.club_id)||':'||extract(epoch FROM w_from)||':'||extract(epoch FROM w_to);
 IF NOT pg_try_advisory_xact_lock(hashtextextended(key,0))THEN RAISE EXCEPTION 'own_agent_interpretation_scope_busy' USING ERRCODE='55000';END IF;
 -- Take the same original producer lock without reversing its lock order.
 IF p_type='cash_rake_accrual' THEN
  SELECT to_jsonb(x)INTO raw FROM public.accounting_cash_rake_sources x WHERE x.id=p_source;
  SELECT 'accounting_cash_hand:'||r.hand_id INTO key FROM public.rake_records r WHERE r.id=s.rake_record_id;
 ELSE
  SELECT to_jsonb(x)INTO raw FROM public.accounting_tournament_fee_sources x WHERE x.id=p_source;
  key:='accounting_tournament_recognition:'||s.tournament_id;
 END IF;
 IF raw IS NULL OR key IS NULL OR NOT pg_try_advisory_xact_lock(hashtextextended(key,0))THEN RAISE EXCEPTION 'own_agent_interpretation_source_busy' USING ERRCODE='55000';END IF;
 IF EXISTS(SELECT FROM public.agent_commission_settlements a WHERE a.club_id=s.club_id AND a.period_start<=s.earned_at AND a.period_end>s.earned_at)
 OR EXISTS(SELECT FROM public.accounting_routed_settlement_runs r WHERE r.period_start=w_from AND r.period_end=w_to AND((r.union_id IS NOT NULL AND r.union_id=s.coordinator_union_id)OR(r.standalone_club_id=s.club_id AND s.coordinator_union_id IS NULL)))
 OR EXISTS(SELECT FROM public.rakeback_periods r WHERE r.club_id=s.club_id AND r.period_start=(w_from AT TIME ZONE'America/Los_Angeles')::date AND r.status<>'pending')
 OR EXISTS(SELECT FROM public.rakeback_period_payouts pp JOIN public.rakeback_periods r ON r.id=pp.rakeback_period_id WHERE r.club_id=s.club_id AND r.period_start=(w_from AT TIME ZONE'America/Los_Angeles')::date)
 THEN RAISE EXCEPTION 'own_agent_interpretation_week_already_paid' USING ERRCODE='23514';END IF;
 -- Reuse the real capture/disposition proof; do not fabricate bad history IDs.
 IF p_type='cash_rake_accrual' THEN
  source_proof:=public.fn_accounting_cash_commission_plan(s.rake_record_id);
  IF NOT EXISTS(SELECT FROM jsonb_array_elements(source_proof->'players')p WHERE p->>'attribution_id'=s.contract->>'attribution_id'AND p->>'player_id'=s.player_id::text AND(p->>'rake_credit')::numeric=s.rake_credit)THEN RAISE EXCEPTION 'own_agent_interpretation_cash_capture_changed' USING ERRCODE='23514';END IF;
 ELSE
  source_proof:=public.fn_accounting_tournament_fee_net_plan(s.tournament_id);
  IF NOT(source_proof->'active_source_ids'@>jsonb_build_array(p_source))OR source_proof->>'status'IS DISTINCT FROM'proven'
  OR NOT EXISTS(SELECT FROM public.accounting_tournament_fee_recognitions r WHERE r.tournament_id=s.tournament_id AND r.status='recognized'AND r.recognized_at=s.earned_at AND r.source_fingerprint=source_proof->>'source_fingerprint')THEN RAISE EXCEPTION 'own_agent_interpretation_fee_capture_changed' USING ERRCODE='23514';END IF;
 END IF;
 PERFORM 1 FROM public.agent_commissions a WHERE a.source_type=p_type AND a.source_id=p_source FOR UPDATE;
 SELECT coalesce(jsonb_agg(to_jsonb(a)ORDER BY a.id),'[]')INTO old_rows FROM public.agent_commissions a WHERE a.source_type=p_type AND a.source_id=p_source;
 SELECT count(*)INTO expected FROM jsonb_array_elements(s.contract->'tiers')t WHERE(t->>'amount')::numeric>0;
 IF jsonb_array_length(old_rows)<>expected OR EXISTS(SELECT FROM jsonb_array_elements(old_rows)a WHERE a->>'settled_at'IS NOT NULL OR a->>'club_id'IS DISTINCT FROM s.club_id::text OR(a->>'created_at')::timestamptz IS DISTINCT FROM s.earned_at OR NOT EXISTS(SELECT FROM jsonb_array_elements(s.contract->'tiers')t WHERE t->>'user_id'=a->>'user_id'AND(t->>'amount')::numeric=(a->>'amount')::numeric AND(t->>'rate')::numeric=(a->>'commission_rate')::numeric))THEN RAISE EXCEPTION 'own_agent_interpretation_original_commissions_changed' USING ERRCODE='23514';END IF;
 IF NOT pg_try_advisory_xact_lock(hashtextextended('accounting_rakeback_period:'||s.club_id||':'||(w_from AT TIME ZONE'America/Los_Angeles')::date,0))THEN RAISE EXCEPTION 'own_agent_interpretation_period_busy' USING ERRCODE='55000';END IF;
 -- These are the original unpaid proof records, never copied or retagged.
 DELETE FROM public.accounting_close_partials WHERE union_id=coalesce(s.coordinator_union_id,s.club_id)AND period_start=w_from AND period_end=w_to;
 DELETE FROM public.accounting_close_certificates WHERE union_id=coalesce(s.coordinator_union_id,s.club_id)AND period_start=w_from AND period_end=w_to;
 DELETE FROM public.accounting_recompute_split_parts WHERE club_id=s.club_id AND period_start=(w_from AT TIME ZONE'America/Los_Angeles')::date AND period_end=(w_to AT TIME ZONE'America/Los_Angeles')::date-1;
 INSERT INTO public.accounting_own_agent_interpretations(source_type,source_id,version,club_id,player_id,earned_at,raw_source,raw_source_md5,original_contract,admitted_contract,original_commissions)VALUES(p_type,p_source,'own-agent-v1',s.club_id,s.player_id,s.earned_at,raw,md5(raw::text),s.contract,canonical,old_rows);
 old_setting:=current_setting('app.ledger_maintenance',true);PERFORM set_config('app.ledger_maintenance','own-agent-interpretation:'||p_source,true);
 DELETE FROM public.agent_commissions WHERE source_type=p_type AND source_id=p_source;
 PERFORM set_config('app.ledger_maintenance',coalesce(old_setting,''),true);
 UPDATE public.agents a SET lifetime_rake_generated=coalesce(a.lifetime_rake_generated,0)-s.rake_credit,weekly_rake_generated=coalesce(a.weekly_rake_generated,0)-CASE WHEN public.fn_union_week_start(s.earned_at)=public.fn_union_week_start(now())THEN s.rake_credit ELSE 0 END WHERE a.club_id=s.club_id AND EXISTS(SELECT FROM jsonb_array_elements(s.contract->'tiers')t WHERE a.id=(t->>'agent_id')::uuid AND a.user_id=(t->>'user_id')::uuid);
 posted:=public.fn_post_accounting_commission_source(p_source,p_type,s.earned_at,canonical);
 IF posted<>(SELECT count(*)FROM jsonb_array_elements(canonical->'tiers')t WHERE(t->>'amount')::numeric>0)THEN RAISE EXCEPTION 'own_agent_interpretation_posting_incomplete' USING ERRCODE='23514';END IF;
 INSERT INTO public.accounting_period_recompute_requests(club_id,period_start,period_end)VALUES(s.club_id,(w_from AT TIME ZONE'America/Los_Angeles')::date,(w_to AT TIME ZONE'America/Los_Angeles')::date-1)ON CONFLICT(club_id,period_start,period_end)DO UPDATE SET last_requested_at=clock_timestamp(),status='pending',reason=NULL,last_result='{}';
 RETURN true;
END $function$

smarter_private.apply_existing_rakeback_.def:
CREATE OR REPLACE FUNCTION smarter_private.apply_existing_rakeback_transfer(p_scope_kind text, p_scope_id uuid, p_start timestamp with time zone, p_end timestamp with time zone, p_role text, p_club uuid, p_user uuid, p_period uuid DEFAULT NULL::uuid, p_certificate bigint DEFAULT NULL::bigint)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public', 'smarter_private'
 SET "TimeZone" TO 'UTC'
AS $function$
DECLARE plan jsonb;scope record;a smarter_private.existing_rakeback_transfer_allocations%ROWTYPE;
 payer_before numeric;payer_after numeric;recipient_before numeric;recipient_after numeric;
 saved_club text;saved_member text;saved_agent text;docs bigint;
BEGIN
 SELECT * INTO scope FROM public.fn_resolve_accounting_routing_scope(p_scope_kind,p_scope_id,p_start,p_end);
 IF public.fn_caller_is_engine()IS DISTINCT FROM true OR public.fn_platform_frozen()IS DISTINCT FROM false
 OR current_setting('app.accounting_routing_context',true)IS DISTINCT FROM scope.routing_context OR NOT(p_club=ANY(scope.club_ids))
 THEN RAISE EXCEPTION 'existing_transfer_original_stage_context_required' USING ERRCODE='42501';END IF;
 IF p_role='player'AND(to_regclass('pg_temp._routed_player_items')IS NULL OR NOT EXISTS(SELECT FROM pg_class WHERE oid=to_regclass('pg_temp._routed_player_items')AND pg_get_userbyid(relowner)='postgres'))
 THEN RAISE EXCEPTION 'existing_transfer_original_player_stage_required' USING ERRCODE='42501';END IF;
 plan:=smarter_private.existing_rakeback_transfer_plan(p_club,p_user,p_start,p_end,p_role,p_period,p_certificate);
 IF plan IS NULL THEN RETURN NULL;END IF;
 SELECT * INTO a FROM jsonb_populate_record(NULL::smarter_private.existing_rakeback_transfer_allocations,plan);
 a.created_at:=clock_timestamp();
 IF p_role='player'THEN
  IF NOT EXISTS(SELECT FROM pg_temp._routed_player_items WHERE period_id=p_period AND certificate_id=p_certificate AND club_id=p_club AND user_id=p_user AND owed=a.amount AND fingerprint=a.source_fingerprint)
  THEN RAISE EXCEPTION 'existing_transfer_original_player_item_required' USING ERRCODE='42501';END IF;
 END IF;
 IF(plan->>'duplicate')::boolean THEN
  IF NOT smarter_private.existing_rakeback_transfer_complete(p_role,a.obligation_id)THEN RAISE EXCEPTION 'existing_transfer_discharge_receipt_incomplete' USING ERRCODE='23514';END IF;
  RETURN plan;
 END IF;
 PERFORM id FROM public.clubs WHERE id=p_club FOR NO KEY UPDATE;
 PERFORM id FROM public.agents WHERE club_id=p_club AND user_id=a.original_payer_id FOR NO KEY UPDATE;
 SELECT chip_treasury INTO payer_before FROM public.clubs WHERE id=p_club;
 SELECT agent_wallet_balance INTO recipient_before FROM public.agents WHERE club_id=p_club AND user_id=a.original_payer_id;
 IF payer_before IS NULL OR recipient_before IS NULL OR payer_before<a.amount
 OR payer_before<>round(payer_before,2)OR recipient_before<>round(recipient_before,2)OR payer_before::text IN('NaN','Infinity','-Infinity')OR recipient_before::text IN('NaN','Infinity','-Infinity')
 THEN RAISE EXCEPTION 'existing_transfer_reimbursement_accounts_invalid' USING ERRCODE='23514';END IF;
 saved_club:=current_setting('app.ledger_autoskip_clubs',true);saved_member:=current_setting('app.ledger_autoskip_club_members',true);saved_agent:=current_setting('app.ledger_autoskip_agents',true);
 PERFORM set_config('app.ledger_autoskip_clubs','1',true);PERFORM set_config('app.ledger_autoskip_club_members','1',true);PERFORM set_config('app.ledger_autoskip_agents','1',true);
 IF p_role='player'THEN
  INSERT INTO public.rakeback_period_payouts(id,rakeback_period_id,club_id,user_id,user_rake_contribution,rakeback_pct,payout_amount,status,paid_at)
  SELECT a.payout_id,r.id,r.club_id,r.user_id,r.rake_generated,round(r.rakeback_rate*100,2),a.amount,'paid',clock_timestamp()FROM public.rakeback_periods r WHERE r.id=p_period;
 END IF;
 UPDATE public.clubs SET chip_treasury=chip_treasury-a.amount WHERE id=p_club AND chip_treasury>=a.amount RETURNING chip_treasury INTO payer_after;
 UPDATE public.agents SET agent_wallet_balance=agent_wallet_balance+a.amount,updated_at=now()WHERE club_id=p_club AND user_id=a.original_payer_id RETURNING agent_wallet_balance INTO recipient_after;
 IF payer_after IS NULL OR recipient_after IS NULL OR payer_before-payer_after IS DISTINCT FROM a.amount OR recipient_after-recipient_before IS DISTINCT FROM a.amount
 THEN RAISE EXCEPTION 'existing_transfer_reimbursement_not_conserved' USING ERRCODE='23514';END IF;
 INSERT INTO public.chip_ledger(id,performed_by,from_type,from_entity_id,to_type,to_entity_id,amount,category,club_id,union_id,description,idempotency_key,metadata,pre_from_balance,post_from_balance,pre_to_balance,post_to_balance)
 VALUES(a.reimbursement_ledger_id,COALESCE(auth.uid(),'2d1cd6c3-5700-4af9-a271-d4863fdab20d'),'club_treasury',p_club,'agent_wallet',a.original_payer_id,a.amount,'treasury_transfer',p_club,scope.union_id,
 'Certified prior payout reimbursement; beneficiary was already credited',
 'existing-rakeback-reimbursement:v1:'||p_role||':'||a.obligation_id::text,
 jsonb_build_object('routing_version',3,'accounting_scope_kind',p_scope_kind,'accounting_scope_id',p_scope_id,'period_start',p_start,'period_end',p_end,
 'payment_method','owner_confirmed_existing_transfer','existing_transfer_allocation_id',a.id,'original_ledger_id',a.original_ledger_id,'original_transaction_id',a.original_transaction_id,
 'original_operation_id',a.original_operation_id,'beneficiary_id',p_user,'obligation_role',p_role,'actual_prior_destination','player_wallet','canonical_funded_from','club_treasury',
 'certificate_id',p_certificate,'period_id',p_period,'source_fingerprint',a.source_fingerprint,'payee_role_at_transfer','agent','owner_prefunding_reimbursement',true),
 payer_before,payer_after,recipient_before,recipient_after);
 SELECT count(*)INTO docs FROM public.settlement_invoices WHERE source_ledger_id=a.reimbursement_ledger_id AND status='paid'AND chips_transferred AND message_sent AND gross_amount=a.amount AND net_amount=a.amount AND deductions=0;
 IF docs<>1 THEN RAISE EXCEPTION 'existing_transfer_reimbursement_invoice_required' USING ERRCODE='23514';END IF;
 INSERT INTO smarter_private.existing_rakeback_transfer_allocations SELECT a.*;
 IF p_role='player'THEN UPDATE public.rakeback_periods SET status='paid',paid_at=clock_timestamp()WHERE id=p_period;END IF;
 PERFORM set_config('app.ledger_autoskip_clubs',COALESCE(saved_club,''),true);PERFORM set_config('app.ledger_autoskip_club_members',COALESCE(saved_member,''),true);PERFORM set_config('app.ledger_autoskip_agents',COALESCE(saved_agent,''),true);
 IF p_role='player'AND NOT smarter_private.existing_rakeback_transfer_complete(p_role,a.obligation_id)THEN RAISE EXCEPTION 'existing_transfer_final_receipt_incomplete' USING ERRCODE='23514';END IF;
 RETURN to_jsonb(a)||jsonb_build_object('duplicate',false);
END $function$

smarter_private.cash_initial_funding_rec.def:
CREATE OR REPLACE FUNCTION smarter_private.cash_initial_funding_receipt(p_receipt uuid)
 RETURNS boolean
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
 SET "TimeZone" TO 'UTC'
AS $function$
DECLARE f public.cash_participant_funding_receipts%ROWTYPE;g jsonb;
BEGIN
 SELECT * INTO f FROM public.cash_participant_funding_receipts WHERE id=p_receipt;
 IF NOT FOUND THEN RETURN false;END IF;
 IF f.operation_kind='buyin' THEN RETURN true;END IF;
 IF f.operation_kind IS DISTINCT FROM 'horse_funding' OR f.pending_addon_id IS NOT NULL THEN RETURN false;END IF;
 g:=smarter_private.original_treasury_gift_evidence(f.source_ledger_id);
 RETURN g->>'status'='proven' AND f.user_id::text=g->>'user_id' AND f.table_id::text=g->>'table_id'
  AND f.seat_id::text=g->>'seat_id' AND f.occupancy_id::text=g->>'occupancy_id'
  AND f.seat_joined_at=(g->>'seat_joined_at')::timestamptz AND f.recorded_at=f.seat_joined_at
  AND f.funding_club_id::text=g->>'earning_club' AND f.account_type='club_treasury'
  AND f.account_entity_id::text=g->>'sponsor_bank_club' AND f.asset='chips' AND f.unit_scale=2
  AND f.amount=(g->>'amount')::numeric AND f.balance_before-f.balance_after=f.amount
  AND f.operation_key=g->>'operation_key';
EXCEPTION WHEN invalid_text_representation OR numeric_value_out_of_range OR datetime_field_overflow THEN RETURN false;
END $function$

smarter_private.deleted_reserve_certific.def:
CREATE OR REPLACE FUNCTION smarter_private.deleted_reserve_certificate_payers(p_calculation bigint)
 RETURNS TABLE(payer_kind text, payer_user uuid, payer_entity uuid, owed numeric)
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public', 'pg_temp'
AS $function$
DECLARE cert_tid tid;cert_xid text;v_contracts_version text;cached jsonb;cache_oid oid;
BEGIN
 -- Reports retain the original pure-reader contract in a read-only transaction.
 IF current_setting('transaction_read_only')::boolean THEN
  RETURN QUERY SELECT p.payer_kind,p.payer_user,p.payer_entity,p.owed FROM smarter_private.rakeback_certificate_payers(p_calculation)p;RETURN;
 END IF;
 -- Re-read physical row versions on every call. xmin alone is insufficient:
 -- updates performed in this same transaction retain xmin but replace ctid.
 SELECT c.ctid,c.xmin::text||'/'||c.cmin::text||'/'||c.tableoid::text||'/'||pg_catalog.pg_relation_filenode(c.tableoid)::text INTO STRICT cert_tid,cert_xid
 FROM public.accounting_rakeback_period_calculations c WHERE c.id=p_calculation;
 SELECT md5(count(*)::text||':'||coalesce(string_agg(g.tableoid::text||'/'||pg_catalog.pg_relation_filenode(g.tableoid)::text||'/'||g.ctid::text||'/'||g.xmin::text||'/'||g.cmin::text||'/'||md5(to_jsonb(g)::text),',' ORDER BY g.tableoid,g.ctid),''))
 INTO v_contracts_version FROM public.accounting_rakeback_payer_contracts g WHERE g.calculation_id=p_calculation;
 cache_oid:=to_regclass('pg_temp._deleted_reserve_payer_proofs');
 IF cache_oid IS NULL THEN
  CREATE TEMP TABLE _deleted_reserve_payer_proofs(calculation_id bigint PRIMARY KEY,certificate_tid tid NOT NULL,certificate_xid text NOT NULL,contracts_version text NOT NULL,payers jsonb NOT NULL)ON COMMIT DROP;
  REVOKE ALL ON TABLE pg_temp._deleted_reserve_payer_proofs FROM PUBLIC,anon,authenticated,service_role;
  cache_oid:=to_regclass('pg_temp._deleted_reserve_payer_proofs');
 END IF;
 IF NOT EXISTS(SELECT FROM pg_catalog.pg_class c WHERE c.oid=cache_oid AND c.relnamespace=pg_my_temp_schema()
   AND c.relkind='r'AND c.relpersistence='t'AND pg_get_userbyid(c.relowner)='postgres'AND NOT c.relrowsecurity)
  OR EXISTS(SELECT FROM pg_catalog.pg_trigger WHERE tgrelid=cache_oid AND NOT tgisinternal)
  OR EXISTS(SELECT FROM pg_catalog.pg_rewrite WHERE ev_class=cache_oid)
  OR (SELECT count(*)FROM pg_catalog.pg_attribute WHERE attrelid=cache_oid AND attnum>0 AND NOT attisdropped)<>5
  OR EXISTS(SELECT FROM(VALUES('calculation_id','bigint'::regtype),('certificate_tid','tid'::regtype),('certificate_xid','text'::regtype),('contracts_version','text'::regtype),('payers','jsonb'::regtype))v(n,t)
   WHERE NOT EXISTS(SELECT FROM pg_catalog.pg_attribute a WHERE a.attrelid=cache_oid AND a.attname=v.n AND a.atttypid=v.t AND a.attnotnull AND a.attnum>0 AND NOT a.attisdropped))
  OR EXISTS(SELECT FROM(VALUES('anon'),('authenticated'),('service_role'))roles(n)
   WHERE has_table_privilege(roles.n,cache_oid,'SELECT,INSERT,UPDATE,DELETE,TRUNCATE,REFERENCES,TRIGGER')OR has_any_column_privilege(roles.n,cache_oid,'SELECT,INSERT,UPDATE,REFERENCES'))
 THEN RAISE EXCEPTION 'deleted_reserve_payer_proof_temp_not_authoritative' USING ERRCODE='42501';END IF;
 SELECT p.payers INTO cached FROM pg_temp._deleted_reserve_payer_proofs p
 WHERE p.calculation_id=p_calculation AND p.certificate_tid=cert_tid AND p.certificate_xid=cert_xid AND p.contracts_version=v_contracts_version;
 IF NOT FOUND THEN
  -- The unchanged original validator is the sole producer of reusable output.
  SELECT coalesce(jsonb_agg(to_jsonb(p)ORDER BY p.payer_kind,p.payer_entity),'[]'::jsonb)INTO cached
  FROM smarter_private.rakeback_certificate_payers(p_calculation)p;
  INSERT INTO pg_temp._deleted_reserve_payer_proofs VALUES(p_calculation,cert_tid,cert_xid,v_contracts_version,cached)
  ON CONFLICT(calculation_id)DO UPDATE SET certificate_tid=EXCLUDED.certificate_tid,certificate_xid=EXCLUDED.certificate_xid,contracts_version=EXCLUDED.contracts_version,payers=EXCLUDED.payers;
 END IF;
 RETURN QUERY SELECT r.payer_kind,r.payer_user,r.payer_entity,r.owed FROM jsonb_to_recordset(cached)AS r(payer_kind text,payer_user uuid,payer_entity uuid,owed numeric);
END $function$

smarter_private.ensure_rakeback_payer_co.def:
CREATE OR REPLACE FUNCTION smarter_private.ensure_rakeback_payer_contracts(p_calculation bigint)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
AS $function$
DECLARE c public.accounting_rakeback_period_calculations%ROWTYPE;r public.rakeback_periods%ROWTYPE;plan jsonb;generated numeric;unrounded numeric;n bigint;distinct_n bigint;
BEGIN
 SELECT * INTO STRICT c FROM public.accounting_rakeback_period_calculations WHERE id=p_calculation;
 SELECT * INTO STRICT r FROM public.rakeback_periods WHERE id=c.period_id FOR UPDATE;
 IF r.status IS DISTINCT FROM 'pending' OR c.id IS DISTINCT FROM(SELECT max(x.id)FROM public.accounting_rakeback_period_calculations x WHERE x.period_id=r.id)
  OR c.accounting_version IS DISTINCT FROM 2 OR(c.club_id,c.player_id,c.period_start,c.period_end)IS DISTINCT FROM(r.club_id,r.user_id,r.period_start,r.period_end)
  OR(c.rake_generated,c.rake_generated,c.rakeback_amount,c.rakeback_amount,c.display_rate)IS DISTINCT FROM(r.rake_generated,r.total_rake_paid,r.rakeback_amount,r.rakeback_earned,r.rakeback_rate)
  OR c.source_fingerprint IS DISTINCT FROM md5(jsonb_build_object('allocations',c.source_allocations,'rake',c.rake_generated,'amount',c.rakeback_amount,'rate',c.display_rate)::text)
 THEN RAISE EXCEPTION 'rakeback_payer_certificate_not_current_pending' USING ERRCODE='23514';END IF;
 SELECT count(*),count(DISTINCT ROW(a->>'source_type',a->>'source_id')),sum((a->>'rake_credit')::numeric),sum((a->>'rake_credit')::numeric*(a->>'rate')::numeric)
 INTO n,distinct_n,generated,unrounded FROM jsonb_array_elements(c.source_allocations)a;
 IF n=0 OR n<>distinct_n OR generated IS DISTINCT FROM c.rake_generated OR round(unrounded,2)IS DISTINCT FROM c.rakeback_amount
  OR c.display_rate IS DISTINCT FROM(CASE WHEN generated>0 THEN round(unrounded/generated,4)ELSE 0 END)
  OR EXISTS(SELECT FROM jsonb_array_elements(c.source_allocations)a WHERE a->>'source_type'IS NULL OR a->>'source_type'NOT IN('cash_rake_accrual','tournament_fee_accrual')OR NULLIF(a->>'source_id','')IS NULL OR NULLIF(a->>'payer_user_id','')::uuid=c.player_id OR NULLIF(a->>'coordinator_union_id','')::uuid IS DISTINCT FROM c.coordinator_union_id)
 THEN RAISE EXCEPTION 'rakeback_payer_certificate_allocations_invalid' USING ERRCODE='23514';END IF;
 plan:=smarter_private.rakeback_payer_plan(c.source_allocations,c.rakeback_amount);
 IF c.payer_kind='split' THEN
  IF c.payer_user_id IS NOT NULL OR jsonb_array_length(plan)<2 THEN RAISE EXCEPTION 'split_rakeback_payers_required' USING ERRCODE='23514';END IF;
 ELSIF jsonb_array_length(plan)<>1 OR plan->0->>'payer_kind'IS DISTINCT FROM c.payer_kind OR NULLIF(plan->0->>'payer_user_id','')::uuid IS DISTINCT FROM c.payer_user_id
 THEN RAISE EXCEPTION 'rakeback_certificate_payer_disagrees' USING ERRCODE='23514';END IF;
 IF EXISTS(SELECT FROM public.accounting_rakeback_payer_contracts g LEFT JOIN jsonb_array_elements(plan)p ON g.payer_kind=p->>'payer_kind'AND g.payer_entity_id=COALESCE(NULLIF(p->>'payer_user_id','')::uuid,c.club_id)
 WHERE g.calculation_id=c.id AND(p IS NULL OR g.payer_user_id IS DISTINCT FROM NULLIF(p->>'payer_user_id','')::uuid OR g.amount IS DISTINCT FROM(p->>'amount')::numeric OR g.unrounded IS DISTINCT FROM(p->>'unrounded')::numeric OR g.rake IS DISTINCT FROM(p->>'rake')::numeric OR g.source_count IS DISTINCT FROM(p->>'source_count')::bigint OR g.source_fingerprint IS DISTINCT FROM c.source_fingerprint))
 THEN RAISE EXCEPTION 'existing_rakeback_payer_contract_disagrees' USING ERRCODE='23514';END IF;
 INSERT INTO public.accounting_rakeback_payer_contracts(calculation_id,payer_kind,payer_entity_id,payer_user_id,amount,unrounded,rake,source_count,source_fingerprint)
 SELECT c.id,p->>'payer_kind',COALESCE(NULLIF(p->>'payer_user_id','')::uuid,c.club_id),NULLIF(p->>'payer_user_id','')::uuid,(p->>'amount')::numeric,(p->>'unrounded')::numeric,(p->>'rake')::numeric,(p->>'source_count')::bigint,c.source_fingerprint
 FROM jsonb_array_elements(plan)p WHERE NOT EXISTS(SELECT FROM public.accounting_rakeback_payer_contracts g WHERE g.calculation_id=c.id AND g.payer_kind=p->>'payer_kind'AND g.payer_entity_id=COALESCE(NULLIF(p->>'payer_user_id','')::uuid,c.club_id));
END $function$

smarter_private.existing_rakeback_transf.def:
CREATE OR REPLACE FUNCTION smarter_private.existing_rakeback_transfer_plan(p_club uuid, p_user uuid, p_start timestamp with time zone, p_end timestamp with time zone, p_role text, p_period uuid DEFAULT NULL::uuid, p_certificate bigint DEFAULT NULL::bigint)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public', 'smarter_private'
 SET "TimeZone" TO 'UTC'
AS $function$
DECLARE ins smarter_private.existing_rakeback_transfer_instructions%ROWTYPE;l public.chip_ledger%ROWTYPE;
 tx public.chip_transactions%ROWTYPE;op public.cashier_rpc_operation_intents%ROWTYPE;c public.accounting_rakeback_period_calculations%ROWTYPE;
 rp public.rakeback_periods%ROWTYPE;prior smarter_private.existing_rakeback_transfer_allocations%ROWTYPE;
 club_owner uuid;owed numeric;allocated numeric;source_hash text;scope_source_hash text;obligation uuid;extra public.chip_ledger%ROWTYPE;
BEGIN
 SELECT * INTO ins FROM smarter_private.existing_rakeback_transfer_instructions WHERE club_id=p_club AND beneficiary_id=p_user AND period_start=p_start AND period_end=p_end;
 IF NOT FOUND THEN RETURN NULL;END IF;
 IF public.fn_caller_is_engine() IS DISTINCT FROM true OR public.fn_platform_frozen() IS DISTINCT FROM false OR NOT(p_role=ANY(ins.roles))
 THEN RAISE EXCEPTION 'existing_transfer_admission_refused' USING ERRCODE='42501';END IF;
 PERFORM pg_advisory_xact_lock(hashtextextended('existing-rakeback-transfer:'||ins.original_ledger_id::text,0));
 SELECT owner_id INTO club_owner FROM public.clubs WHERE id=p_club;
 SELECT * INTO l FROM public.chip_ledger WHERE id=ins.original_ledger_id FOR SHARE;
 IF NOT FOUND OR l.status IS DISTINCT FROM 'posted' OR l.category IS DISTINCT FROM 'agent_send' OR l.club_id IS DISTINCT FROM p_club
 OR l.from_type IS DISTINCT FROM 'agent_wallet' OR l.from_entity_id IS DISTINCT FROM club_owner OR l.to_type IS DISTINCT FROM 'player_wallet'
 OR l.to_entity_id IS DISTINCT FROM p_user OR l.amount IS NULL OR l.amount<=0 OR l.amount<>round(l.amount,2)
 OR l.amount::text IN('NaN','Infinity','-Infinity') OR l.idempotency_key IS DISTINCT FROM 'agent_send:'||l.correlation_id::text
 OR l.created_at<p_end OR l.correlation_id IS NULL THEN RAISE EXCEPTION 'existing_transfer_original_credit_required' USING ERRCODE='23514';END IF;
 SELECT * INTO op FROM public.cashier_rpc_operation_intents WHERE operation_id=l.correlation_id FOR SHARE;
 IF NOT FOUND OR op.actor_user_id IS DISTINCT FROM club_owner OR op.club_id IS DISTINCT FROM p_club OR op.action IS DISTINCT FROM 'agent_wallet_send'
 OR op.completed_at IS NULL OR op.receipt->>'success' IS DISTINCT FROM 'true' OR op.receipt->>'op_id' IS DISTINCT FROM op.operation_id::text
 OR op.operation_intent->>'actor' IS DISTINCT FROM club_owner::text OR op.operation_intent->>'club' IS DISTINCT FROM p_club::text
 OR op.operation_intent->>'target' IS DISTINCT FROM p_user::text OR op.operation_intent->>'action' IS DISTINCT FROM 'agent_wallet_send'
 OR op.operation_intent->>'requested_destination' IS DISTINCT FROM 'player_wallet' OR op.receipt->>'destination' IS DISTINCT FROM 'player_wallet'
 OR (op.operation_intent->>'amount')::numeric IS DISTINCT FROM l.amount OR(op.receipt->>'amount')::numeric IS DISTINCT FROM l.amount
 OR(op.receipt->>'credit_drawn')::numeric IS DISTINCT FROM 0 OR(op.receipt->>'agent_wallet_before')::numeric-(op.receipt->>'agent_wallet_after')::numeric IS DISTINCT FROM l.amount
 THEN RAISE EXCEPTION 'existing_transfer_completed_cashier_receipt_required' USING ERRCODE='23514';END IF;
 SELECT * INTO tx FROM public.chip_transactions WHERE id=(op.receipt->>'transaction_id')::uuid FOR SHARE;
 IF NOT FOUND OR tx.club_id IS DISTINCT FROM p_club OR tx.from_user_id IS DISTINCT FROM club_owner OR tx.to_user_id IS DISTINCT FROM p_user
 OR tx.amount IS DISTINCT FROM l.amount OR tx.transaction_type IS DISTINCT FROM 'agent_wallet_send' OR tx.is_reversed IS DISTINCT FROM false OR tx.clawed_back IS DISTINCT FROM false
 OR tx.metadata->>'op_id' IS DISTINCT FROM op.operation_id::text OR tx.metadata->>'destination' IS DISTINCT FROM 'player_wallet'
 OR(tx.metadata->>'claimed_back')::numeric IS DISTINCT FROM 0 OR tx.balance_after IS DISTINCT FROM(op.receipt->>'agent_wallet_after')::numeric
 OR(tx.metadata->>'recipient_balance_after')::numeric IS DISTINCT FROM(op.receipt->>'recipient_balance_after')::numeric
 OR(tx.metadata->>'agent_wallet_before')::numeric-(tx.metadata->>'agent_wallet_after')::numeric IS DISTINCT FROM l.amount
 OR tx.reversible_until IS NULL OR tx.reversible_until>=clock_timestamp()
 THEN RAISE EXCEPTION 'existing_transfer_unreversed_original_transaction_required' USING ERRCODE='23514';END IF;
 FOR extra IN SELECT * FROM public.chip_ledger WHERE id=ANY(ins.evidence_ledger_ids) LOOP
  IF extra.status IS DISTINCT FROM 'posted' OR extra.category IS DISTINCT FROM 'agent_send' OR extra.club_id IS DISTINCT FROM p_club
  OR extra.from_type IS DISTINCT FROM 'agent_wallet' OR extra.from_entity_id IS DISTINCT FROM club_owner OR extra.to_type IS DISTINCT FROM 'player_wallet' OR extra.to_entity_id IS DISTINCT FROM p_user
  THEN RAISE EXCEPTION 'existing_transfer_extra_evidence_disagrees' USING ERRCODE='23514';END IF;
 END LOOP;
 IF(SELECT count(*)FROM public.chip_ledger WHERE id=ANY(ins.evidence_ledger_ids))<>cardinality(ins.evidence_ledger_ids)
 THEN RAISE EXCEPTION 'existing_transfer_extra_evidence_missing' USING ERRCODE='23514';END IF;
 IF p_role='player' THEN
  SELECT * INTO rp FROM public.rakeback_periods WHERE id=p_period FOR UPDATE;
  SELECT * INTO c FROM public.accounting_rakeback_period_calculations WHERE period_id=p_period ORDER BY id DESC LIMIT 1;
  IF rp.id IS NULL OR c.id IS DISTINCT FROM p_certificate OR c.accounting_version IS DISTINCT FROM 2 OR c.club_id IS DISTINCT FROM p_club OR c.player_id IS DISTINCT FROM p_user
  OR c.period_start IS DISTINCT FROM(p_start AT TIME ZONE 'America/Los_Angeles')::date OR c.period_end IS DISTINCT FROM((p_end AT TIME ZONE 'America/Los_Angeles')::date-1)
  OR c.rakeback_amount IS DISTINCT FROM rp.rakeback_amount OR c.rakeback_amount IS DISTINCT FROM rp.rakeback_earned OR c.rake_generated IS DISTINCT FROM rp.rake_generated
  OR c.rake_generated IS DISTINCT FROM rp.total_rake_paid OR c.display_rate IS DISTINCT FROM rp.rakeback_rate OR rp.club_id IS DISTINCT FROM p_club OR rp.user_id IS DISTINCT FROM p_user
  OR c.source_fingerprint IS DISTINCT FROM md5(jsonb_build_object('allocations',c.source_allocations,'rake',c.rake_generated,'amount',c.rakeback_amount,'rate',c.display_rate)::text)
  OR(SELECT count(*)FROM smarter_private.rakeback_certificate_payers(c.id)g)<>1 OR NOT EXISTS(SELECT FROM smarter_private.rakeback_certificate_payers(c.id)g WHERE g.payer_kind='agent'AND g.payer_user=club_owner AND g.payer_entity=club_owner AND g.owed=c.rakeback_amount)
  THEN RAISE EXCEPTION 'existing_transfer_latest_owner_payer_certificate_required' USING ERRCODE='23514';END IF;
  owed:=c.rakeback_amount;source_hash:=c.source_fingerprint;obligation:=rp.id;
 ELSIF p_role='commission' THEN
  IF to_regclass('pg_temp._routed_nodes') IS NULL OR to_regclass('pg_temp._routed_prior_discharge_context') IS NULL OR to_regclass('pg_temp._routed_edges') IS NULL
  OR(SELECT count(*)FROM pg_class WHERE oid=ANY(ARRAY[to_regclass('pg_temp._routed_nodes'),to_regclass('pg_temp._routed_edges'),to_regclass('pg_temp._routed_prior_discharge_context')])AND pg_get_userbyid(relowner)='postgres')<>3
  THEN RAISE EXCEPTION 'existing_transfer_original_commission_stage_required' USING ERRCODE='42501';END IF;
  -- Only the original whole-club request can establish that the latest
  -- certificates cover every human and horse. A page-only request remains
  -- pending in fn_rakeback_recompute_periods and cannot establish zero here.
  IF NOT EXISTS(SELECT FROM public.accounting_period_recompute_requests q WHERE q.club_id=p_club
    AND q.period_start=(p_start AT TIME ZONE 'America/Los_Angeles')::date AND q.period_end=((p_end AT TIME ZONE 'America/Los_Angeles')::date-1)
    AND q.status='complete'AND q.attempted_at IS NOT NULL AND q.last_requested_at<=q.attempted_at
    AND q.last_result->>'accounting_version'='2'AND q.last_result->>'status'='ready'AND q.last_result->>'club_id'=p_club::text
    AND q.last_result->>'period_start'=q.period_start::text AND q.last_result->>'period_end'=q.period_end::text
    AND NOT EXISTS(SELECT FROM(SELECT s.earned_at FROM public.accounting_cash_rake_sources s
      WHERE s.club_id=p_club AND s.recorded_at>q.attempted_at-interval '1 minute'OFFSET 0)s WHERE s.earned_at>=p_start AND s.earned_at<p_end)
    AND NOT EXISTS(SELECT FROM(SELECT h.source_id FROM public.accounting_cash_atomic_contract_admissions h
      WHERE h.admitted_at>q.attempted_at-interval '1 minute'OFFSET 0)h CROSS JOIN LATERAL(
      SELECT s.club_id,s.earned_at FROM public.accounting_cash_rake_sources s WHERE s.id=h.source_id OFFSET 0)s
      WHERE s.club_id=p_club AND s.earned_at>=p_start AND s.earned_at<p_end)
    AND NOT EXISTS(SELECT FROM(SELECT h.source_id,h.funding_club_id FROM public.accounting_cash_funding_contract_admissions h
      WHERE h.admitted_at>q.attempted_at-interval '1 minute'OFFSET 0)h CROSS JOIN LATERAL(
      SELECT s.club_id,s.earned_at FROM public.accounting_cash_rake_sources s WHERE s.id=h.source_id OFFSET 0)s
      WHERE(s.club_id=p_club OR h.funding_club_id=p_club)AND s.earned_at>=p_start AND s.earned_at<p_end)
    AND NOT EXISTS(SELECT FROM public.accounting_tournament_fee_sources f WHERE f.club_id=p_club AND f.charged_at<p_end AND f.recorded_at>q.attempted_at-interval '1 minute'))
  THEN RAISE EXCEPTION 'existing_transfer_current_whole_club_calculation_required' USING ERRCODE='23514';END IF;
  SELECT source_fingerprint INTO scope_source_hash FROM pg_temp._routed_prior_discharge_context WHERE stage_round=2 AND period_start=p_start AND period_end=p_end AND p_club=ANY(club_ids);
  SELECT own_amount INTO owed FROM pg_temp._routed_nodes WHERE club_id=p_club AND user_id=p_user;
  IF owed IS NULL OR scope_source_hash IS NULL
  OR EXISTS(SELECT FROM pg_temp._routed_edges WHERE club_id=p_club AND payee_user=p_user AND payer_user IS NOT NULL)
  THEN RAISE EXCEPTION 'existing_transfer_original_commission_payer_required' USING ERRCODE='23514';END IF;
  -- Descendant-agent pass-through is retained by the original edges. A
  -- positive direct PLAYER liability is different: discharging its gross
  -- funding as personal income would pay that funding twice. This narrowly
  -- scoped admission refuses that case instead of inventing a new advance.
  IF EXISTS(SELECT FROM(SELECT DISTINCT ON(z.period_id)z.*FROM public.accounting_rakeback_period_calculations z
    WHERE z.club_id=p_club AND z.period_start=(p_start AT TIME ZONE 'America/Los_Angeles')::date
    AND z.period_end=((p_end AT TIME ZONE 'America/Los_Angeles')::date-1)ORDER BY z.period_id,z.id DESC)latest
    CROSS JOIN LATERAL smarter_private.rakeback_certificate_payers(latest.id)g WHERE latest.player_id<>p_user AND g.payer_kind='agent'AND g.payer_user=p_user AND g.owed>0)
  THEN RAISE EXCEPTION 'existing_transfer_commission_player_pass_through_requires_net_discharge' USING ERRCODE='23514';END IF;
  source_hash:=md5(jsonb_build_array('commission_own',p_club,p_user,p_start,p_end,scope_source_hash,owed)::text);
  obligation:=md5('prior-commission:'||p_club::text||':'||p_user::text||':'||p_start::text||':'||p_end::text)::uuid;
 ELSE RAISE EXCEPTION 'existing_transfer_role_refused' USING ERRCODE='23514';END IF;
 IF owed IS NULL OR owed<=0 OR owed<>round(owed,2) OR owed::text IN('NaN','Infinity','-Infinity')
 THEN RAISE EXCEPTION 'existing_transfer_positive_certified_obligation_required' USING ERRCODE='23514';END IF;
 SELECT * INTO prior FROM smarter_private.existing_rakeback_transfer_allocations WHERE obligation_role=p_role AND obligation_id=obligation;
 IF FOUND THEN
  IF prior.instruction_id IS DISTINCT FROM ins.id OR prior.amount IS DISTINCT FROM owed OR prior.source_fingerprint IS DISTINCT FROM source_hash OR prior.certificate_id IS DISTINCT FROM p_certificate
  THEN RAISE EXCEPTION 'existing_transfer_obligation_changed_after_discharge' USING ERRCODE='23514';END IF;
  RETURN to_jsonb(prior)||jsonb_build_object('duplicate',true);
 END IF;
 IF p_role='player'AND(rp.status IS DISTINCT FROM 'pending'OR EXISTS(SELECT FROM public.rakeback_period_payouts WHERE rakeback_period_id=rp.id))
 THEN RAISE EXCEPTION 'existing_transfer_unpaid_original_period_required' USING ERRCODE='23514';END IF;
 SELECT coalesce(sum(amount),0)INTO allocated FROM smarter_private.existing_rakeback_transfer_allocations WHERE original_ledger_id=l.id;
 IF allocated+owed>l.amount THEN RAISE EXCEPTION 'existing_transfer_credit_already_allocated' USING ERRCODE='23514';END IF;
 RETURN jsonb_build_object('instruction_id',ins.id,'obligation_role',p_role,'obligation_id',obligation,'certificate_id',p_certificate,'source_fingerprint',source_hash,
 'club_id',p_club,'beneficiary_id',p_user,'period_start',p_start,'period_end',p_end,'original_ledger_id',l.id,'original_transaction_id',tx.id,'original_operation_id',op.operation_id,
 'original_payer_id',club_owner,'actual_destination','player_wallet','amount',owed,'original_credit',l.amount,'canonical_funded_from','club_treasury',
 'original_evidence',jsonb_build_object('instruction',to_jsonb(ins),'ledger',to_jsonb(l),'transaction',to_jsonb(tx),'cashier_operation',to_jsonb(op)),
 'id',gen_random_uuid(),'reimbursement_ledger_id',gen_random_uuid(),'payout_id',CASE WHEN p_role='player'THEN gen_random_uuid()END,'duplicate',false);
END $function$

smarter_private.invalidate_agent_commiss.def:
CREATE OR REPLACE FUNCTION smarter_private.invalidate_agent_commission_report_days()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public', 'smarter_private'
AS $function$
DECLARE c uuid;affected jsonb;
BEGIN
 IF TG_OP='TRUNCATE' THEN
   FOR c IN SELECT club_id FROM smarter_private.agent_commission_report_days UNION SELECT club_id FROM smarter_private.agent_commission_report_frontiers ORDER BY club_id LOOP
     PERFORM pg_advisory_xact_lock(hashtextextended('agent-commission:'||c::text,0));
   END LOOP;
   DELETE FROM smarter_private.agent_commission_report_days;
   DELETE FROM smarter_private.agent_commission_report_frontiers;
   RETURN NULL;
 ELSIF TG_OP='UPDATE' THEN
   SELECT jsonb_agg(DISTINCT jsonb_build_object('club',x.club_id,'day',(x.created_at AT TIME ZONE 'UTC')::date)) INTO affected
   FROM (
     SELECT o.club_id,o.created_at FROM old_rows o FULL JOIN new_rows n USING(id)
      WHERE o.id IS NULL OR n.id IS NULL OR o.amount IS DISTINCT FROM n.amount OR o.user_id IS DISTINCT FROM n.user_id
         OR o.club_id IS DISTINCT FROM n.club_id OR o.created_at IS DISTINCT FROM n.created_at
     UNION ALL
     SELECT n.club_id,n.created_at FROM old_rows o FULL JOIN new_rows n USING(id)
      WHERE o.id IS NULL OR n.id IS NULL OR o.amount IS DISTINCT FROM n.amount OR o.user_id IS DISTINCT FROM n.user_id
         OR o.club_id IS DISTINCT FROM n.club_id OR o.created_at IS DISTINCT FROM n.created_at
   )x WHERE x.club_id IS NOT NULL AND x.created_at IS NOT NULL;
 ELSE
   SELECT jsonb_agg(DISTINCT jsonb_build_object('club',o.club_id,'day',(o.created_at AT TIME ZONE 'UTC')::date))
    INTO affected FROM old_rows o WHERE o.club_id IS NOT NULL AND o.created_at IS NOT NULL;
 END IF;
 FOR c IN SELECT DISTINCT (x->>'club')::uuid FROM jsonb_array_elements(affected)x ORDER BY 1 LOOP
   PERFORM pg_advisory_xact_lock(hashtextextended('agent-commission:'||c::text,0));
 END LOOP;
 INSERT INTO smarter_private.agent_commission_report_days(club_id,day,complete)
 SELECT DISTINCT (x->>'club')::uuid,(x->>'day')::date,false FROM jsonb_array_elements(affected)x
 ON CONFLICT(club_id,day) DO UPDATE SET complete=false,computed_at=clock_timestamp();
 RETURN NULL;
END;$function$

smarter_private.inventory_basis_cache_re.def:
CREATE OR REPLACE FUNCTION smarter_private.inventory_basis_cache_read(p_generation text, p_problem boolean, p_kind text, p_union uuid, p_start timestamp with time zone, p_end timestamp with time zone)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE
 SET search_path TO 'pg_catalog', 'public', 'smarter_private'
AS $function$
DECLARE v jsonb;
BEGIN
 IF p_generation='original-inventory-245:unqualified' THEN RETURN NULL;END IF;
 IF p_problem IS NULL OR p_kind NOT IN('pnl_boundary','pnl_flows','pnl_touched','pnl_clubs') OR p_kind IS NULL THEN RETURN NULL;END IF;
 IF p_problem THEN v:=public.fn_accounting_close_problem(p_kind,p_union,p_start,p_end);
 ELSE v:=public.fn_accounting_close_certificate(p_kind,p_union,p_start,p_end);END IF;
 IF p_generation IS NULL THEN RETURN v;END IF;
 IF v IS NULL OR v->>'_original_inventory_generation' IS DISTINCT FROM p_generation THEN RETURN NULL;END IF;
 RETURN v-'_original_inventory_generation';
END $function$

smarter_private.original_erased_cash_bas.def:
CREATE OR REPLACE FUNCTION smarter_private.original_erased_cash_base_discharge_receipt(e bigint, h text)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE
 SET search_path TO 'pg_catalog', 'public', 'smarter_private'
 SET "TimeZone" TO 'UTC'
AS $function$
DECLARE c record;r jsonb;f jsonb;p jsonb;s jsonb;v record;n integer;refs jsonb;
BEGIN
 IF h IS NULL OR h IS DISTINCT FROM smarter_private.original_erased_cash_base_expected_hash(e) THEN
 RETURN jsonb_build_object('status','blocked','reason','unknown_original_cash_discharge');END IF;
 r:=smarter_private.original_erased_cash_base_request(e,h);
 IF r->>'status' IS DISTINCT FROM 'ready' OR r->'financial_admission' IS DISTINCT FROM 'false'::jsonb
 OR r->>'witness_md5' IS DISTINCT FROM h OR md5((r->'witness')::text) IS DISTINCT FROM h
 OR md5((r->'proof')::text) IS DISTINCT FROM r->>'proof_md5' THEN
 RETURN jsonb_build_object('status','blocked','reason','original_cash_source_changed');END IF;
 f:=r->'witness';p:=r->'proof';
 SELECT * INTO c FROM smarter_private.original_erased_cash_base_discharges WHERE event_id=e;
 IF NOT FOUND THEN RETURN jsonb_build_object('status','pending','event_id',e);END IF;
 s:=c.evidence;
 IF c.witness_md5 IS DISTINCT FROM h OR c.evidence_md5 IS DISTINCT FROM md5(s::text)
 OR c.user_id::text IS DISTINCT FROM p#>>'{holding,user_id}'
 OR c.funding_club_id::text IS DISTINCT FROM p#>>'{holding,club_id}'
 OR c.base_cents IS DISTINCT FROM ((p->>'original_base')::numeric*100)::bigint
 OR c.occupancy_id::text IS DISTINCT FROM f#>>'{signed,occupancy_id}'
 OR s->>'restoration_key' IS DISTINCT FROM c.restoration_key
 OR (s->>'discharged_at')::timestamptz IS DISTINCT FROM c.discharged_at
 OR s->>'custody' IS DISTINCT FROM 'canonical_deleted_account_bank'
 OR s->'final_player_wallet' IS DISTINCT FROM '0'::jsonb THEN
 RETURN jsonb_build_object('status','blocked','reason','original_cash_certificate_changed');END IF;
 refs:=s->'financial_refs';
 IF jsonb_typeof(refs) IS DISTINCT FROM 'array' OR jsonb_array_length(refs) IS DISTINCT FROM 6
 OR (SELECT count(DISTINCT jsonb_build_array(x->>'kind',x->>'id')) FROM jsonb_array_elements(refs)x)<>6 THEN
 RETURN jsonb_build_object('status','blocked','reason','original_cash_financial_refs_refused');END IF;
 FOR v IN SELECT value ref FROM jsonb_array_elements(refs) LOOP
 IF v.ref->>'md5' IS NULL OR v.ref->>'md5' !~ '^[0-9a-f]{32}$'
 OR smarter_private.original_inventory_source_ref_md5(v.ref) IS DISTINCT FROM v.ref->>'md5' THEN
 RETURN jsonb_build_object('status','blocked','reason','original_cash_financial_rows_changed');END IF;
 END LOOP;
 IF NOT smarter_private.original_erased_cash_base_discharge_evidence_valid(e,h,s) THEN RETURN jsonb_build_object('status','blocked','reason','original_cash_financial_association_refused');END IF;
 RETURN s||jsonb_build_object('status','discharged','event_id',e,'witness_md5',h,'evidence_md5',c.evidence_md5);
EXCEPTION WHEN invalid_text_representation OR numeric_value_out_of_range OR datetime_field_overflow THEN
 RETURN jsonb_build_object('status','blocked','reason','malformed_original_cash_discharge');
END$function$

smarter_private.original_erased_cash_dis.def:
CREATE OR REPLACE FUNCTION smarter_private.original_erased_cash_discharge_returns(p_union_id uuid, p_start timestamp with time zone, p_end timestamp with time zone)
 RETURNS TABLE(ledger_id uuid, club_id uuid, user_id uuid, buyins numeric, cashouts numeric, kind text, valid boolean)
 LANGUAGE plpgsql
 STABLE
 SET search_path TO 'pg_catalog', 'public', 'smarter_private'
 SET "TimeZone" TO 'UTC'
AS $function$
DECLARE c record;f jsonb;receipt jsonb;h text;
BEGIN
 IF p_union_id IS DISTINCT FROM 'fade0000-0000-0000-0000-000000000001'::uuid
 OR p_start IS NULL OR p_end IS NULL OR NOT isfinite(p_start) OR NOT isfinite(p_end) OR p_end<=p_start THEN RETURN;END IF;
 FOR c IN SELECT * FROM smarter_private.original_inventory_restoration_cases WHERE family='erased_cash_receivable' LOOP
 f:=smarter_private.original_inventory_finite_witness(c.event_id);
 IF f IS NULL THEN RAISE EXCEPTION 'original_discharge_flow_source_refused' USING ERRCODE='55000';END IF;
 h:=md5((f-'original_table_scope'-'original_manifest_scope')::text);
 receipt:=smarter_private.original_erased_cash_base_discharge_receipt(c.event_id,h);
 IF receipt->>'status'='pending' THEN CONTINUE;END IF;
 IF receipt->>'status' IS DISTINCT FROM 'discharged'
 OR receipt->>'discharged_at' IS NULL OR NOT isfinite((receipt->>'discharged_at')::timestamptz)
 OR receipt->>'custody' IS DISTINCT FROM 'canonical_deleted_account_bank'
 OR receipt->'final_player_wallet' IS DISTINCT FROM '0'::jsonb
 OR receipt->>'occupancy_id' IS DISTINCT FROM f#>>'{event,before_row,occupancy_id}'
 OR receipt->>'restoration_key' IS DISTINCT FROM ('retired_completed_cash_base:'||(f#>>'{event,before_row,occupancy_id}'))
 OR (receipt->>'discharged_at')::timestamptz<='2026-10-12 07:00:00Z'::timestamptz
 OR EXISTS(SELECT 1 FROM public.union_pnl_original_flows old WHERE old.ledger_id=(receipt->>'issuance_leg_id')::uuid)
 THEN RAISE EXCEPTION 'original_discharge_flow_proof_refused' USING ERRCODE='55000';END IF;
 IF (receipt->>'discharged_at')::timestamptz<p_start OR (receipt->>'discharged_at')::timestamptz>=p_end THEN CONTINUE;END IF;
 ledger_id:=(receipt->>'issuance_leg_id')::uuid;club_id:=(receipt->>'funding_club_id')::uuid;user_id:=(receipt->>'user_id')::uuid;
 buyins:=0;cashouts:=(receipt->>'amount')::numeric;kind:='cash_return';valid:=true;RETURN NEXT;
 END LOOP;
END $function$

smarter_private.original_inventory_basis.def:
CREATE OR REPLACE FUNCTION smarter_private.original_inventory_basis_generation()
 RETURNS text
 LANGUAGE plpgsql
 STABLE
 SET search_path TO 'pg_catalog', 'public', 'smarter_private'
 SET "TimeZone" TO 'UTC'
AS $function$
DECLARE r jsonb; receipt jsonb; c record; proofs text;source_hash text;source_count bigint;discharges jsonb:='[]';treasury text;tw record;tp jsonb;
BEGIN
 IF (SELECT count(*) FROM smarter_private.original_inventory_restoration_cases) IS DISTINCT FROM 245::bigint
 OR (SELECT count(*) FROM smarter_private.original_inventory_restoration_certificates WHERE boundary='2026-10-12 07:00:00Z') IS DISTINCT FROM 245::bigint
 OR smarter_private.original_inventory_proof_sources_match() IS DISTINCT FROM true THEN RETURN NULL;END IF;
 -- Deduplicate shared original authorities; no 4x family source scan.
 FOR r IN SELECT DISTINCT x FROM smarter_private.original_inventory_restoration_cases k CROSS JOIN LATERAL jsonb_array_elements(k.source_refs)x LOOP
 IF r->>'md5' IS NULL OR smarter_private.original_inventory_source_ref_md5(r) IS DISTINCT FROM r->>'md5' THEN RETURN NULL;END IF;
 END LOOP;
 FOR c IN SELECT * FROM smarter_private.original_inventory_restoration_cases WHERE family='erased_cash_receivable' ORDER BY event_id LOOP
 receipt:=smarter_private.original_erased_cash_base_discharge_receipt(c.event_id,md5((c.original_witness-'original_table_scope'-'original_manifest_scope')::text));
 IF receipt->>'status' NOT IN('pending','discharged') OR receipt->>'status' IS NULL THEN RETURN NULL;END IF;
 discharges:=discharges||jsonb_build_array(jsonb_build_object('event_id',c.event_id,'receipt',receipt));
 END LOOP;
 SELECT md5(string_agg(event_id::text||':'||witness_md5||':'||proof_md5,'|' ORDER BY event_id)) INTO proofs
 FROM smarter_private.original_inventory_restoration_certificates WHERE boundary='2026-10-12 07:00:00Z';
 SELECT count(to_regprocedure(signature)),md5(string_agg(signature||':'||md5(pg_get_functiondef(to_regprocedure(signature))),'|' ORDER BY signature)) INTO source_count,source_hash FROM(VALUES ('public.fn_union_pnl_boundary(uuid,timestamptz)'),('public.fn_union_pnl_original_flow_evidence(uuid,timestamptz,timestamptz)'),('public.fn_union_pnl_evidence_report(uuid,timestamptz,timestamptz)'),('smarter_private.original_inventory_basis_generation()'),('smarter_private.original_inventory_proof_sources_match()'))s(signature);
 IF source_count IS DISTINCT FROM 5::bigint OR source_hash IS NULL OR proofs IS NULL THEN RETURN NULL;END IF;
 -- A newly admitted original treasury witness is a new proof input. Old
 -- derived blocked parts must be recomputed by their existing generation owner.
 FOR tw IN SELECT ledger_id,kind FROM smarter_private.original_treasury_historical_admissions ORDER BY ledger_id LOOP
  tp:=CASE tw.kind WHEN 'gift' THEN smarter_private.original_treasury_gift_evidence(tw.ledger_id)
   WHEN 'return' THEN smarter_private.original_treasury_return_evidence(tw.ledger_id) END;
  IF tp->>'status' IS DISTINCT FROM 'proven' THEN RETURN NULL;END IF;
 END LOOP;
 SELECT md5(COALESCE(string_agg(ledger_id::text||':'||kind||':'||source_fingerprint,'|' ORDER BY ledger_id),'no-original-treasury-witnesses')) INTO treasury
 FROM smarter_private.original_treasury_historical_admissions;
 RETURN 'original-inventory-245-v1:'||md5(source_hash||'|'||proofs||'|'||discharges::text||'|'||treasury);
END $function$

smarter_private.original_inventory_finit.def:
CREATE OR REPLACE FUNCTION smarter_private.original_inventory_finite_witness(p_event_id bigint)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE
 SET search_path TO 'pg_catalog', 'public', 'smarter_private'
AS $function$
DECLARE c record;r jsonb;n integer;distinct_n integer;
BEGIN
 SELECT * INTO c FROM smarter_private.original_inventory_restoration_cases WHERE event_id=p_event_id;
 IF NOT FOUND OR c.original_witness IS NULL OR c.witness_md5 IS DISTINCT FROM md5(c.original_witness::text)
 OR jsonb_typeof(c.source_refs) IS DISTINCT FROM 'array' OR jsonb_array_length(c.source_refs)=0 THEN RETURN NULL;END IF;
 SELECT count(*),count(DISTINCT jsonb_build_array(x->>'kind',x->>'id',x->>'other_id')) INTO n,distinct_n FROM jsonb_array_elements(c.source_refs) x;
 IF n IS DISTINCT FROM distinct_n THEN RETURN NULL;END IF;
 FOR r IN SELECT value FROM jsonb_array_elements(c.source_refs) LOOP
 IF r->>'md5' IS NULL OR r->>'md5' !~ '^[0-9a-f]{32}$'
 OR smarter_private.original_inventory_source_ref_md5(r) IS DISTINCT FROM r->>'md5' THEN RETURN NULL;END IF;
 END LOOP;
 RETURN c.original_witness;
END $function$

smarter_private.original_inventory_sourc.def:
CREATE OR REPLACE FUNCTION smarter_private.original_inventory_source_ref_md5(ref jsonb)
 RETURNS text
 LANGUAGE plpgsql
 STABLE
 SET search_path TO 'pg_catalog', 'public', 'smarter_private'
 SET "TimeZone" TO 'UTC'
AS $function$
DECLARE n integer;digest text;k text;v_ref_id uuid;v_ref_other uuid;sid bigint;economic jsonb;s record;d record;a record;
BEGIN
 IF ref IS NULL OR jsonb_typeof(ref) IS DISTINCT FROM 'object' OR ref->>'kind' IS NULL THEN RETURN NULL;END IF;
 k:=ref->>'kind';
 IF k='inventory_event' THEN
  sid:=(ref->>'id')::bigint;SELECT count(*),min(md5(to_jsonb(t)::text)) INTO n,digest FROM public.union_pnl_inventory_events t WHERE t.event_id=sid;
 ELSIF k='migration_source' THEN
  SELECT count(*),min(md5(array_to_string(t.statements,E'\n'))) INTO n,digest FROM supabase_migrations.schema_migrations t
  WHERE t.version=ref->>'id' AND cardinality(t.statements)=1;
 ELSIF k='mint_ledger' THEN
  SELECT count(*),min(md5(to_jsonb(t)::text)) INTO n,digest FROM public.ca_mint_ledger t WHERE t.op_id=ref->>'id';
 ELSIF k='wallet_credit_idempotency' THEN
  SELECT count(*),min(md5(to_jsonb(t)::text)) INTO n,digest FROM public.wallet_credit_idempotency t WHERE t.key=ref->>'id';
 ELSE
  v_ref_id:=(ref->>'id')::uuid;
  CASE k
  WHEN 'chip_ledger' THEN SELECT count(*),min(md5(to_jsonb(t)::text)) INTO n,digest FROM public.chip_ledger t WHERE t.id=v_ref_id;
  WHEN 'chip_transaction' THEN SELECT count(*),min(md5(to_jsonb(t)::text)) INTO n,digest FROM public.chip_transactions t WHERE t.id=v_ref_id;
  WHEN 'cash_move' THEN SELECT count(*),min(md5(to_jsonb(t)::text)) INTO n,digest FROM public.cash_participant_moves t WHERE t.id=v_ref_id;
  WHEN 'wallet_transaction' THEN SELECT count(*),min(md5(to_jsonb(t)::text)) INTO n,digest FROM public.wallet_transactions t WHERE t.id=v_ref_id;
  WHEN 'cash_manifest' THEN SELECT count(*),min(md5(to_jsonb(t)::text)) INTO n,digest FROM public.cash_hand_participant_manifests t WHERE t.id=v_ref_id;
  WHEN 'cash_funding' THEN SELECT count(*),min(md5(to_jsonb(t)::text)) INTO n,digest FROM public.cash_participant_funding_receipts t WHERE t.id=v_ref_id;
  WHEN 'tournament_funding' THEN SELECT count(*),min(md5(to_jsonb(t)::text)) INTO n,digest FROM public.tournament_participant_funding_receipts t WHERE t.id=v_ref_id;
  WHEN 'original_hand_qualification' THEN SELECT count(*),min(md5(to_jsonb(t)::text)) INTO n,digest FROM smarter_private.retirement_original_hand_qualification t WHERE t.submission_id=v_ref_id;
  WHEN 'original_hand_restoration' THEN SELECT count(*),min(md5(to_jsonb(t)::text)) INTO n,digest FROM smarter_private.retirement_original_hand_restorations t WHERE t.submission_id=v_ref_id;
  WHEN 'cash_qualification' THEN SELECT count(*),min(md5(to_jsonb(t)::text)) INTO n,digest FROM smarter_private.retired_cash_hand_qualification t WHERE t.submission_id=v_ref_id;
  WHEN 'cash_custody' THEN
   v_ref_other:=(ref->>'other_id')::uuid;
   SELECT count(*),min(md5(to_jsonb(t)::text)) INTO n,digest FROM smarter_private.retired_cash_hand_custody t WHERE t.submission_id=v_ref_id AND t.user_id=v_ref_other;
  WHEN 'undealt_qualification' THEN SELECT count(*),min(md5(to_jsonb(t)::text)) INTO n,digest FROM smarter_private.retirement_undealt_paid_entry_qualification t WHERE t.tournament_id=v_ref_id;
  WHEN 'undealt_restoration' THEN SELECT count(*),min(md5(to_jsonb(t)::text)) INTO n,digest FROM smarter_private.retirement_undealt_paid_entry_restorations t WHERE t.tournament_id=v_ref_id;
  WHEN 'terminal_settlement' THEN SELECT count(*),min(md5(to_jsonb(t)::text)) INTO n,digest FROM public.tournament_terminal_settlements t WHERE t.tournament_id=v_ref_id;
  WHEN 'cancellation_receipt' THEN SELECT count(*),min(md5(to_jsonb(t)::text)) INTO n,digest FROM public.tournament_cancellation_receipts t WHERE t.tournament_id=v_ref_id;
  WHEN 'tournament_payout' THEN SELECT count(*),min(md5(to_jsonb(t)::text)) INTO n,digest FROM public.tournament_payouts t WHERE t.id=v_ref_id;
  WHEN 'tournament_credit' THEN SELECT count(*),min(md5(to_jsonb(t)::text)) INTO n,digest FROM public.tournament_accounting_credit_receipts t WHERE t.id=v_ref_id;
  WHEN 'satellite_settlement' THEN SELECT count(*),min(md5(to_jsonb(t)::text)) INTO n,digest FROM public.tournament_satellite_settlements t WHERE t.tournament_id=v_ref_id;
  WHEN 'satellite_award' THEN
   v_ref_other:=(ref->>'other_id')::uuid;
   SELECT count(*),min(md5(to_jsonb(t)::text)) INTO n,digest FROM public.tournament_satellite_awards t WHERE t.tournament_id=v_ref_id AND t.user_id=v_ref_other;
  WHEN 'tournament_ticket' THEN SELECT count(*),min(md5(to_jsonb(t)::text)) INTO n,digest FROM public.tournament_tickets t WHERE t.id=v_ref_id;
  WHEN 'atomic_economics' THEN
   SELECT count(*),min(md5(jsonb_build_object('hand_id',t.hand_id,'table_id',t.table_id,'hand_number',t.hand_number,
    'payload_hash',t.payload_hash,'stack_result',t.stack_result,'committed_at',t.committed_at,
    'post_commit_completed_at',t.post_commit_completed_at,'post_commit_result',t.post_commit_result)::text)) INTO n,digest
   FROM public.hand_atomic_commits t WHERE t.hand_id=v_ref_id;
   IF n=0 THEN
    -- RETENTION PRUNED THIS COMMIT (2026-10-14). sp_prune_hand_history deletes a
    -- settled horse hand's atomic commit after the retention window and, in the
    -- same transaction, writes its disposal from the live row. The digest below was
    -- certified while the row existed; the disposal is the only authority that the
    -- hand settled and was removed by retention. Anything else stays refused.
    SELECT count(*) INTO n FROM smarter_private.hand_submission_disposals t WHERE t.submission_id=v_ref_id;
    IF n IS DISTINCT FROM 1 THEN RETURN NULL;END IF;
    SELECT * INTO d FROM smarter_private.hand_submission_disposals t WHERE t.submission_id=v_ref_id;
    SELECT * INTO s FROM smarter_private.hand_submissions t WHERE t.submission_id=v_ref_id AND t.table_id=d.table_id AND t.hand_number=d.hand_number;
    IF NOT FOUND
    OR EXISTS(SELECT 1 FROM public.hand_atomic_commits x WHERE x.table_id=d.table_id AND x.hand_number=d.hand_number)
    OR EXISTS(SELECT 1 FROM public.hand_history x WHERE x.id=v_ref_id)
    OR d.expected->>'kind' IS DISTINCT FROM 'retention_pruned_settled_hand'
    OR d.expected->>'settled' IS DISTINCT FROM 'true' OR d.expected->>'settlement_completed' IS DISTINCT FROM 'true'
    OR d.expected->>'submission_id' IS DISTINCT FROM v_ref_id::text OR d.expected->>'pruned_hand_id' IS DISTINCT FROM v_ref_id::text
    OR d.expected->>'table_id' IS DISTINCT FROM d.table_id::text OR d.expected->>'hand_number' IS DISTINCT FROM d.hand_number::text
    OR d.expected->>'request_hash' IS DISTINCT FROM s.request_hash
    OR (d.expected->>'settlement_completed_at')::timestamptz IS NULL OR NOT isfinite((d.expected->>'settlement_completed_at')::timestamptz)
    OR (d.expected->>'disposed_at')::timestamptz IS NULL OR NOT isfinite((d.expected->>'disposed_at')::timestamptz)
    OR (d.expected->>'disposed_at')::timestamptz>clock_timestamp()
    OR (d.expected->>'disposed_at')::timestamptz < (d.expected->>'settlement_completed_at')::timestamptz+interval '8 days'
    OR (SELECT horse_retention_days FROM public.hand_history_retention_policy LIMIT 1) IS DISTINCT FROM 8
    OR ref->>'md5' IS NULL OR ref->>'md5' !~ '^[0-9a-f]{32}$' THEN RETURN NULL;END IF;
    n:=1;digest:=ref->>'md5';
   END IF;
  WHEN 'signed_economics' THEN
   SELECT count(*) INTO n FROM smarter_private.hand_submissions t WHERE t.submission_id=v_ref_id;
   IF n IS DISTINCT FROM 1 THEN RETURN NULL;END IF;
   SELECT * INTO s FROM smarter_private.hand_submissions t WHERE t.submission_id=v_ref_id;
   IF NOT FOUND THEN RETURN NULL;END IF;
   IF s.request<>'{}'::jsonb THEN
    economic:=jsonb_build_object('submission_id',s.submission_id,'request_hash',s.request_hash,'table_id',s.table_id,
     'hand_number',s.hand_number,'lease_generation',s.lease_generation,'stacks',s.request->'p_stacks','started_at',s.request#>>'{p_hand_row,started_at}');
   ELSE
    -- Reconstruct only the captured card-free economic DTO under the existing
    -- qualified retention disposal. Missing payload alone is never authority.
    SELECT count(*) INTO n FROM smarter_private.hand_submission_disposals t WHERE t.submission_id=v_ref_id AND t.table_id=s.table_id AND t.hand_number=s.hand_number;
    IF n IS DISTINCT FROM 1 THEN RETURN NULL;END IF;
    SELECT * INTO d FROM smarter_private.hand_submission_disposals t WHERE t.submission_id=v_ref_id AND t.table_id=s.table_id AND t.hand_number=s.hand_number;
    IF NOT FOUND THEN RETURN NULL;END IF;
    SELECT * INTO a FROM public.hand_atomic_commits t WHERE t.hand_id=v_ref_id AND t.table_id=s.table_id AND t.hand_number=s.hand_number;
    IF NOT FOUND THEN
     -- RETENTION PRUNED THIS COMMIT (2026-10-14): its settled completion is read from
     -- the disposal retention wrote from the live row in the same transaction.
     IF EXISTS(SELECT 1 FROM public.hand_atomic_commits x WHERE x.table_id=s.table_id AND x.hand_number=s.hand_number)
     OR EXISTS(SELECT 1 FROM public.hand_history x WHERE x.id=v_ref_id)
     OR NOT pg_input_is_valid(d.expected->>'settlement_completed_at','timestamptz') THEN RETURN NULL;END IF;
     a.post_commit_completed_at:=(d.expected->>'settlement_completed_at')::timestamptz;
     a.committed_at:=a.post_commit_completed_at;
     a.post_commit_result:=jsonb_build_object('ok',true);
    END IF;
    IF s.retained_at IS NULL OR NOT isfinite(s.retained_at)
    OR a.post_commit_completed_at IS NULL OR NOT isfinite(a.post_commit_completed_at) OR a.post_commit_result->>'ok' IS DISTINCT FROM 'true'
    OR d.expected->>'kind' IS DISTINCT FROM 'retention_pruned_settled_hand'
    OR d.expected->>'settled' IS DISTINCT FROM 'true' OR d.expected->>'settlement_completed' IS DISTINCT FROM 'true'
    OR d.expected->>'submission_id' IS DISTINCT FROM v_ref_id::text OR d.expected->>'pruned_hand_id' IS DISTINCT FROM v_ref_id::text
    OR d.expected->>'table_id' IS DISTINCT FROM s.table_id::text OR d.expected->>'hand_number' IS DISTINCT FROM s.hand_number::text
    OR d.expected->>'request_hash' IS DISTINCT FROM s.request_hash
    OR (d.expected->>'settlement_completed_at')::timestamptz IS DISTINCT FROM a.post_commit_completed_at
    OR (d.expected->>'disposed_at')::timestamptz IS NULL OR NOT isfinite((d.expected->>'disposed_at')::timestamptz)
    OR (d.expected->>'disposed_at')::timestamptz>clock_timestamp()
    OR (d.expected->>'hand_created_at')::timestamptz IS NULL OR NOT isfinite((d.expected->>'hand_created_at')::timestamptz)
    OR (d.expected->>'disposed_at')::timestamptz < (d.expected->>'hand_created_at')::timestamptz+interval '8 days'
    OR (d.expected->>'disposed_at')::timestamptz < a.post_commit_completed_at+interval '8 days'
    OR (d.expected->>'disposed_at')::timestamptz < s.retained_at+interval '8 days'
    OR (SELECT horse_retention_days FROM public.hand_history_retention_policy LIMIT 1) IS DISTINCT FROM 8
    THEN RETURN NULL;END IF;
    economic:=ref->'economic';
    IF jsonb_typeof(economic) IS DISTINCT FROM 'object' OR economic->>'submission_id' IS DISTINCT FROM v_ref_id::text
    OR economic->>'request_hash' IS DISTINCT FROM s.request_hash OR economic->>'table_id' IS DISTINCT FROM s.table_id::text
    OR economic->>'hand_number' IS DISTINCT FROM s.hand_number::text OR economic->>'lease_generation' IS DISTINCT FROM s.lease_generation::text
    OR jsonb_typeof(economic->'stacks') IS DISTINCT FROM 'array' OR jsonb_array_length(economic->'stacks')=0
    OR economic->>'started_at' IS NULL OR NOT isfinite((economic->>'started_at')::timestamptz)
    OR (economic->>'started_at')::timestamptz>a.committed_at THEN RETURN NULL;END IF;
   END IF;
   n:=1;digest:=md5(economic::text);
  ELSE RETURN NULL;
  END CASE;
 END IF;
 IF n IS DISTINCT FROM 1 OR digest IS NULL THEN RETURN NULL;END IF;
 RETURN digest;
EXCEPTION WHEN invalid_text_representation OR invalid_datetime_format OR datetime_field_overflow OR numeric_value_out_of_range THEN RETURN NULL;
END $function$

smarter_private.original_treasury_gift_e.def:
CREATE OR REPLACE FUNCTION smarter_private.original_treasury_gift_evidence(p_ledger uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
 SET "TimeZone" TO 'UTC'
AS $function$
DECLARE w smarter_private.original_treasury_funding_witnesses%ROWTYPE;src jsonb;l jsonb;e jsonb;r jsonb;j jsonb;f jsonb;
 uid uuid;bank uuid;club uuid;tid uuid;sid uuid;occ uuid;joined timestamptz;amt numeric;n bigint;cutover_at timestamptz;
BEGIN
 SELECT * INTO w FROM smarter_private.original_treasury_funding_witnesses WHERE ledger_id=p_ledger AND kind='gift';
 IF NOT FOUND OR w.source_fingerprint IS DISTINCT FROM md5(w.source::text) THEN RETURN NULL;END IF;
 src:=w.source;l:=src->'ledger';e:=src->'seat_event';r:=src->'entry';j:=src->'journal';f:=src->'flow';
 SELECT installed_at INTO STRICT cutover_at FROM smarter_private.original_treasury_funding_cutover WHERE singleton;
 IF w.historical_late IS DISTINCT FROM ((f->>'recognized_at')::timestamptz<cutover_at)
  OR (w.historical_late AND NOT EXISTS(SELECT FROM smarter_private.original_treasury_historical_admissions h WHERE h.ledger_id=w.ledger_id AND h.kind=w.kind AND h.source_fingerprint=w.source_fingerprint))
  OR (NOT w.historical_late AND EXISTS(SELECT FROM smarter_private.original_treasury_historical_admissions h WHERE h.ledger_id=w.ledger_id)) THEN RETURN NULL;END IF;
 SELECT count(*) INTO n FROM public.chip_ledger q WHERE q.id=p_ledger AND to_jsonb(q)=l;
 IF n<>1 THEN RETURN NULL;END IF;
 uid:=(l#>>'{metadata,user_id}')::uuid;bank:=(l->>'from_entity_id')::uuid;tid:=(l->>'table_id')::uuid;
 club:=(e#>>'{after_row,club_id}')::uuid;sid:=(e#>>'{after_row,id}')::uuid;occ:=(e#>>'{after_row,occupancy_id}')::uuid;
 joined:=(e#>>'{after_row,joined_at}')::timestamptz;amt:=(l->>'amount')::numeric;
 IF uid IS NULL OR bank IS NULL OR club IS NULL OR tid IS NULL OR sid IS NULL OR occ IS NULL OR joined IS NULL OR NOT isfinite(joined)
  OR l->>'status' IS DISTINCT FROM 'posted' OR l->>'category' IS DISTINCT FROM 'horse_funding'
  OR l->>'from_type' IS DISTINCT FROM 'club_treasury' OR l->>'club_id' IS DISTINCT FROM bank::text
  OR l->>'to_type' IS DISTINCT FROM 'table_stack' OR l->>'to_entity_id' IS DISTINCT FROM tid::text
  OR l#>>'{metadata,door}' IS DISTINCT FROM 'fn_horse_seat_from_treasury'
  OR l->>'idempotency_key' IS DISTINCT FROM 'horse_fund:'||(l#>>'{metadata,op_id}')
  OR NULLIF(l#>>'{metadata,op_id}','') IS NULL
  OR amt IS NULL OR amt<=0 OR amt<>round(amt,2) OR amt::text IN('NaN','Infinity','-Infinity')
  OR e->>'source_name' IS DISTINCT FROM 'table_seats' OR e->>'operation' IS DISTINCT FROM 'INSERT'
  OR e->'before_row' IS DISTINCT FROM 'null'::jsonb OR e#>>'{after_row,left_at}' IS NOT NULL
  OR e->>'row_id' IS DISTINCT FROM sid::text OR e#>>'{after_row,user_id}' IS DISTINCT FROM uid::text
  OR e#>>'{after_row,table_id}' IS DISTINCT FROM tid::text OR (e#>>'{after_row,stack}')::numeric IS DISTINCT FROM amt
  OR (l->>'created_at')::timestamptz IS DISTINCT FROM joined
  OR f->>'ledger_id' IS DISTINCT FROM p_ledger::text OR f->'ledger_snapshot' IS DISTINCT FROM l
  OR f->>'transaction_id' IS DISTINCT FROM e->>'transaction_id'
  OR f#>>'{game_scope,asset}' IS DISTINCT FROM 'chips' OR f#>'{game_scope,unit_scale}' IS DISTINCT FROM '2'::jsonb
  OR f#>'{game_scope,tournament_id}' IS DISTINCT FROM 'null'::jsonb
  OR f#>>'{game_scope,host_club_id}' IS DISTINCT FROM bank::text
  OR src#>>'{frame,transaction_id}' IS DISTINCT FROM e->>'transaction_id'
  OR src#>'{frame,observed_at}' IS DISTINCT FROM f->'recognized_at'
 THEN RETURN NULL;END IF;
 SELECT count(*) INTO n FROM public.entry_purchase_idempotency_receipts q
  WHERE q.key_domain='horse_funding' AND q.idempotency_key=l#>>'{metadata,op_id}' AND to_jsonb(q)=r;
 IF n<>1 OR r->'response' IS NULL OR r->'response'='null'::jsonb OR r#>>'{response,success}' IS DISTINCT FROM 'true'
  OR r->>'completed_at' IS NULL OR r->>'claimed_at' IS NULL
  OR (r->>'completed_at')::timestamptz IS DISTINCT FROM joined OR (r->>'claimed_at')::timestamptz IS DISTINCT FROM joined
  OR r#>>'{request,door}' IS DISTINCT FROM 'fn_horse_seat_from_treasury'
  OR r#>>'{request,user_id}' IS DISTINCT FROM uid::text OR r#>>'{request,table_id}' IS DISTINCT FROM tid::text
  OR (r#>>'{request,amount}')::numeric IS DISTINCT FROM amt
  OR NULLIF(r#>>'{request,seat_number}','') IS NULL OR (r#>>'{request,seat_number}')::integer NOT BETWEEN 1 AND 10 THEN RETURN NULL;END IF;
 SELECT count(*) INTO n FROM public.chip_transactions q WHERE q.id=(j->>'id')::uuid AND to_jsonb(q)=j;
 IF n<>1 OR j->>'transaction_type' IS DISTINCT FROM 'horse_treasury_funding'
  OR j->>'club_id' IS DISTINCT FROM bank::text OR j->>'to_user_id' IS DISTINCT FROM uid::text OR j->>'from_user_id' IS NOT NULL
  OR (j->>'amount')::numeric IS DISTINCT FROM amt OR (j->>'balance_after')::numeric IS DISTINCT FROM (r#>>'{response,treasury_after}')::numeric
  OR (j->>'created_at')::timestamptz IS DISTINCT FROM joined THEN RETURN NULL;END IF;
 -- When original volatile inventory is still present it must be byte-exact;
 -- the admitted original event/frame survives its normal later retirement.
 IF EXISTS(SELECT FROM public.union_pnl_inventory_events q WHERE q.event_id=(e->>'event_id')::bigint AND to_jsonb(q) IS DISTINCT FROM e)
  OR EXISTS(SELECT FROM public.union_pnl_original_flows q WHERE q.ledger_id=p_ledger AND to_jsonb(q) IS DISTINCT FROM f)
  OR EXISTS(SELECT FROM public.union_pnl_transaction_frames q WHERE q.transaction_id=(e->>'transaction_id')::xid8 AND to_jsonb(q) IS DISTINCT FROM src->'frame') THEN RETURN NULL;END IF;
 RETURN jsonb_build_object('status','proven','ledger_id',p_ledger,'earning_club',club,'sponsor_bank_club',bank,'user_id',uid,
  'table_id',tid,'seat_id',sid,'occupancy_id',occ,'seat_joined_at',joined,'operation_key',l#>>'{metadata,op_id}','amount',amt,'asset','chips','unit_scale',2,
  'bank_balance_after',j->'balance_after','original_event_id',e->'event_id','original_transaction_id',e->'transaction_id','source_fingerprint',w.source_fingerprint);
EXCEPTION WHEN no_data_found OR invalid_text_representation OR numeric_value_out_of_range OR datetime_field_overflow THEN RETURN NULL;
END $function$

smarter_private.original_treasury_return.def:
CREATE OR REPLACE FUNCTION smarter_private.original_treasury_return_evidence(p_ledger uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
 SET "TimeZone" TO 'UTC'
AS $function$
DECLARE w smarter_private.original_treasury_funding_witnesses%ROWTYPE;src jsonb;l jsonb;e jsonb;b jsonb;a jsonb;f jsonb;j jsonb;g jsonb;lineage jsonb;
 uid uuid;tid uuid;club uuid;amt numeric;at_time timestamptz;n bigint;cutover_at timestamptz;
BEGIN
 SELECT * INTO w FROM smarter_private.original_treasury_funding_witnesses WHERE ledger_id=p_ledger AND kind='return';
 IF NOT FOUND OR w.source_fingerprint IS DISTINCT FROM md5(w.source::text) THEN RETURN NULL;END IF;
 src:=w.source;l:=src->'ledger';e:=src->'seat_event';b:=e->'before_row';a:=e->'after_row';f:=src->'flow';j:=src->'journal';
 SELECT installed_at INTO STRICT cutover_at FROM smarter_private.original_treasury_funding_cutover WHERE singleton;
 IF w.historical_late IS DISTINCT FROM ((f->>'recognized_at')::timestamptz<cutover_at)
  OR (w.historical_late AND NOT EXISTS(SELECT FROM smarter_private.original_treasury_historical_admissions h WHERE h.ledger_id=w.ledger_id AND h.kind=w.kind AND h.source_fingerprint=w.source_fingerprint))
  OR (NOT w.historical_late AND EXISTS(SELECT FROM smarter_private.original_treasury_historical_admissions h WHERE h.ledger_id=w.ledger_id)) THEN RETURN NULL;END IF;
 uid:=(l->>'to_entity_id')::uuid;tid:=(l->>'table_id')::uuid;club:=(l->>'club_id')::uuid;amt:=(l->>'amount')::numeric;at_time:=(l->>'created_at')::timestamptz;
 SELECT count(*) INTO n FROM public.chip_ledger q WHERE id=p_ledger AND to_jsonb(q)=l;
 IF n<>1 OR uid IS NULL OR tid IS NULL OR club IS NULL OR at_time IS NULL OR NOT isfinite(at_time)
  OR l->>'status' IS DISTINCT FROM 'posted' OR l->>'category' NOT IN('cashout','table_cashout','refund')
  OR l->>'from_type' IS DISTINCT FROM 'table_stack' OR l->>'from_entity_id' IS DISTINCT FROM tid::text
  OR l->>'to_type' IS DISTINCT FROM 'player_wallet' OR amt IS NULL OR amt<=0 OR amt<>round(amt,2) OR amt::text IN('NaN','Infinity','-Infinity')
  OR e->>'source_name' IS DISTINCT FROM 'table_seats' OR e->>'operation' IS DISTINCT FROM 'UPDATE'
  OR b->>'id' IS NULL OR b->>'occupancy_id' IS NULL OR b->>'joined_at' IS NULL OR b->>'left_at' IS NOT NULL
  OR e->>'row_id' IS DISTINCT FROM b->>'id' OR b->>'user_id' IS DISTINCT FROM uid::text OR b->>'table_id' IS DISTINCT FROM tid::text
  OR b->>'club_id' IS DISTINCT FROM club::text OR (b->>'stack')::numeric IS DISTINCT FROM amt
  OR a-'left_at' IS DISTINCT FROM b-'left_at' OR (a->>'left_at')::timestamptz IS DISTINCT FROM at_time
  OR f->>'ledger_id' IS DISTINCT FROM p_ledger::text OR f->'ledger_snapshot' IS DISTINCT FROM l
  OR f->>'transaction_id' IS DISTINCT FROM e->>'transaction_id'
  OR f#>>'{game_scope,asset}' IS DISTINCT FROM 'chips' OR f#>'{game_scope,unit_scale}' IS DISTINCT FROM '2'::jsonb
  OR f#>'{game_scope,tournament_id}' IS DISTINCT FROM 'null'::jsonb
  OR src#>>'{frame,transaction_id}' IS DISTINCT FROM e->>'transaction_id'
  OR src#>'{frame,observed_at}' IS DISTINCT FROM f->'recognized_at' THEN RETURN NULL;END IF;
 g:=smarter_private.original_treasury_gift_evidence((src->>'gift_ledger_id')::uuid);
 IF g->>'status' IS DISTINCT FROM 'proven' OR g->>'earning_club' IS DISTINCT FROM club::text OR g->>'user_id' IS DISTINCT FROM uid::text
  OR g->>'table_id' IS DISTINCT FROM tid::text OR g->>'seat_id' IS DISTINCT FROM b->>'id'
  OR g->>'occupancy_id' IS DISTINCT FROM b->>'occupancy_id' OR (g->>'seat_joined_at')::timestamptz IS DISTINCT FROM (b->>'joined_at')::timestamptz
  OR (g->>'seat_joined_at')::timestamptz>=at_time THEN RETURN NULL;END IF;
 SELECT count(*) INTO n FROM public.wallet_transactions q WHERE id=(j->>'id')::uuid AND to_jsonb(q)=j;
 IF n<>1 OR j->>'type' IS DISTINCT FROM 'credit' OR j->>'wallet_type' IS DISTINCT FROM 'PLAYER' OR j->>'category' IS DISTINCT FROM 'cashout'
  OR j->>'user_id' IS DISTINCT FROM uid::text OR j->>'table_id' IS DISTINCT FROM tid::text
  OR (j->>'amount')::numeric IS DISTINCT FROM amt OR (j->>'created_at')::timestamptz IS DISTINCT FROM at_time
  OR j->>'balance_after' IS NULL THEN RETURN NULL;END IF;
 lineage:=public.fn_cash_original_funding_lineage(uid,tid,(b->>'id')::uuid,(b->>'occupancy_id')::uuid,(b->>'joined_at')::timestamptz,(f->>'recognized_at')::timestamptz,true);
 IF lineage->'issues' IS DISTINCT FROM '[]'::jsonb OR lineage->'moves' IS DISTINCT FROM '[]'::jsonb
  OR EXISTS(SELECT FROM jsonb_array_elements(lineage->'funding_receipts') r WHERE r->>'funding_club_id' IS DISTINCT FROM club::text) THEN RETURN NULL;END IF;
 IF EXISTS(SELECT FROM public.union_pnl_inventory_events q WHERE event_id=(e->>'event_id')::bigint AND to_jsonb(q) IS DISTINCT FROM e)
  OR EXISTS(SELECT FROM public.union_pnl_original_flows q WHERE ledger_id=p_ledger AND to_jsonb(q) IS DISTINCT FROM f)
  OR EXISTS(SELECT FROM public.union_pnl_transaction_frames q WHERE transaction_id=(e->>'transaction_id')::xid8 AND to_jsonb(q) IS DISTINCT FROM src->'frame') THEN RETURN NULL;END IF;
 RETURN jsonb_build_object('status','proven','ledger_id',p_ledger,'earning_club',club,'user_id',uid,'amount',amt,'table_id',tid,
  'seat_id',b->'id','occupancy_id',b->'occupancy_id','seat_joined_at',b->'joined_at','gift_ledger_id',g->'ledger_id',
  'asset','chips','unit_scale',2,'funding_lineage',lineage,'original_event_id',e->'event_id','original_transaction_id',e->'transaction_id','source_fingerprint',w.source_fingerprint);
EXCEPTION WHEN no_data_found OR invalid_text_representation OR numeric_value_out_of_range OR datetime_field_overflow THEN RETURN NULL;
END $function$

smarter_private.own_agent_destination_co.def:
CREATE OR REPLACE FUNCTION smarter_private.own_agent_destination_contract(p_contract jsonb, p_club uuid, p_player uuid, p_terms_at timestamp with time zone)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
AS $function$
DECLARE member jsonb:=p_contract#>'{membership,terms}'; own jsonb; terms jsonb;
BEGIN
 IF member->>'role'NOT IN('super_agent','agent','sub_agent')OR member->>'role'IS NULL
  OR(member->>'player_rakeback_pct')::numeric IS DISTINCT FROM .70
  OR jsonb_array_length(p_contract->'tiers')<>0
  OR NOT EXISTS(SELECT FROM public.clubs c WHERE c.id=p_club AND c.owner_id=NULLIF(member->>'agent_id','')::uuid)
 THEN RETURN NULL;END IF;
 BEGIN own:=public.fn_accounting_agent_terms_at(p_club,p_player,p_terms_at);
 EXCEPTION WHEN SQLSTATE '55000' THEN
  IF SQLERRM IN('accounting_terms_not_observed','accounting_terms_not_active')THEN RETURN NULL;ELSE RAISE;END IF;
 END;
 terms:=own->'terms';
 IF terms IS NULL OR terms='null'::jsonb THEN RETURN NULL;END IF;
 IF terms->>'club_id'IS DISTINCT FROM p_club::text OR terms->>'user_id'IS DISTINCT FROM p_player::text
  OR terms->>'status'IS DISTINCT FROM'active'OR COALESCE(terms->>'role','')NOT IN('super_agent','agent','sub_agent')
  OR NULLIF(terms->>'id','')IS NULL OR(own->>'history_id')::bigint IS NULL OR(own->>'observed_at')::timestamptz>p_terms_at
 THEN RAISE EXCEPTION 'owner_agent_destination_contract_invalid' USING ERRCODE='55000';END IF;
 RETURN own;
END $function$

smarter_private.own_agent_interpreted_co.def:
CREATE OR REPLACE FUNCTION smarter_private.own_agent_interpreted_contract(p_contract jsonb, p_club uuid, p_player uuid, p_rake numeric, p_union uuid, p_terms timestamp with time zone)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
AS $function$
DECLARE own jsonb;canonical jsonb;
BEGIN
 IF coalesce(p_contract#>>'{membership,terms,role}','')NOT IN('super_agent','agent','sub_agent')
 OR p_contract#>>'{tiers,0,user_id}'=p_player::text
 OR ((p_contract#>>'{membership,terms,player_rakeback_pct}')::numeric=.70 AND EXISTS(SELECT FROM public.clubs c WHERE c.id=p_club AND c.owner_id=NULLIF(p_contract#>>'{membership,terms,agent_id}','')::uuid))THEN RETURN NULL;END IF;
 BEGIN own:=public.fn_accounting_agent_terms_at(p_club,p_player,p_terms);
 EXCEPTION WHEN SQLSTATE '55000' THEN IF SQLERRM IN('accounting_terms_not_observed','accounting_terms_not_active')THEN RETURN NULL;ELSE RAISE;END IF;END;
 canonical:=public.fn_accounting_earning_contract(p_club,p_player,p_rake,p_union,p_terms);
 -- Only hierarchy and its retained residual may change. Owner-basis,
 -- attribution and every original capture field remain in the admitted row.
 IF canonical#>>'{tiers,0,user_id}'IS DISTINCT FROM p_player::text
 OR canonical#>'{tiers,0,agreement}'IS DISTINCT FROM own
 OR NOT((p_contract-'tiers'-'club_residual')@>(canonical-'tiers'-'club_residual'))
 THEN RAISE EXCEPTION 'own_agent_interpretation_historical_contract_disagrees' USING ERRCODE='23514';END IF;
 RETURN p_contract||jsonb_build_object('tiers',canonical->'tiers','club_residual',canonical->'club_residual');
END $function$

smarter_private.posthand_escrow_certific.def:
CREATE OR REPLACE FUNCTION smarter_private.posthand_escrow_certificate_immutable()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public', 'smarter_private'
AS $function$
DECLARE original jsonb;
BEGIN
 IF TG_OP<>'INSERT' THEN RAISE EXCEPTION 'POSTHAND_ESCROW_CERTIFICATE_IMMUTABLE' USING ERRCODE='55000';END IF;
 original:=smarter_private.posthand_escrow_original_snapshot(NEW.table_id,NEW.hand_number);
 IF NEW.hand_id::text IS DISTINCT FROM original->>'hand_id' OR NEW.original IS DISTINCT FROM original
  OR NEW.original_sha256 IS DISTINCT FROM encode(extensions.digest(convert_to(original::text,'UTF8'),'sha256'),'hex') THEN
  RAISE EXCEPTION 'POSTHAND_ESCROW_EXACT_ORIGINAL_REQUIRED' USING ERRCODE='55000';END IF;
 RETURN NEW;
END $function$

smarter_private.prepare_own_agent_interp.def:
CREATE OR REPLACE FUNCTION smarter_private.prepare_own_agent_interpretation(p_union uuid, p_club uuid, p_from timestamp with time zone, p_to timestamp with time zone, p_limit integer DEFAULT 256)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
AS $function$
DECLARE kind text;identity uuid;item record;seen int:=0;admitted int:=0;clubs uuid[];parts jsonb;certs jsonb;old_hash text;new_hash text;did_admit boolean;budget_exhausted boolean:=false;w record;win_first timestamptz;win_last timestamptz;win_n int;win_gaps int;by_window boolean:=false;win_seen int;win_exited boolean;work_deadline timestamptz:=LEAST(NULLIF(current_setting('app.weekly_accounting_preparation_deadline',true),'')::timestamptz,NULLIF(current_setting('app.weekly_accounting_scope_deadline',true),'')::timestamptz);
BEGIN
 IF NOT public.fn_caller_is_engine()OR p_from IS NULL OR p_to IS NULL OR(p_union IS NULL)=(p_club IS NULL)OR p_limit IS NULL OR p_limit<1 OR p_limit>1024
 OR p_from IS DISTINCT FROM public.fn_union_week_start(p_from)OR p_to IS DISTINCT FROM public.fn_union_week_start(p_from+interval '8 days')OR p_to>now()THEN RAISE EXCEPTION 'own_agent_preparation_scope_invalid' USING ERRCODE='22023';END IF;
 kind:=CASE WHEN p_union IS NULL THEN'club'ELSE'union'END;identity:=coalesce(p_union,p_club);
 IF NOT pg_try_advisory_xact_lock(hashtextextended(CASE WHEN p_union IS NULL THEN'club-accounting:'ELSE'union-accounting:'END||identity||':'||extract(epoch FROM p_from)||':'||extract(epoch FROM p_to),0))THEN RAISE EXCEPTION 'own_agent_interpretation_scope_busy' USING ERRCODE='55000';END IF;
 -- Original completed books remain authoritative, including manual correction
 -- receipts made later. Replaying them cannot create a v1 source or new delta.
 IF EXISTS(SELECT FROM public.accounting_routed_settlement_runs r WHERE r.scope_kind=kind AND r.scope_id=identity AND r.period_start=p_from AND r.period_end=p_to AND r.round_no=3)THEN RETURN jsonb_build_object('ready',true,'legacy_paid',true,'admitted',0);END IF;
 IF work_deadline IS NOT NULL AND(NOT isfinite(work_deadline)OR clock_timestamp()+interval '1 second'>=work_deadline)THEN RETURN jsonb_build_object('ready',false,'admitted',0,'reviewed',0,'budget_exhausted',true,'version','own-agent-v1');END IF;
 -- WEEK CLUBS FROM THE INDEXED READER (owner override, 2026-11-02): the whole-week
 -- view scan took over 45 s inside the payout's money window.
 SELECT coalesce(array_agg(c.club_id),'{}')INTO clubs FROM public.fn_accounting_week_clubs(p_union,p_club,p_from,p_to)c;
 IF NOT EXISTS(SELECT FROM public.accounting_own_agent_preparation_versions v WHERE v.scope_kind=kind AND v.scope_id=identity AND v.period_start=p_from AND v.period_end=p_to)THEN
  IF EXISTS(SELECT FROM public.accounting_routed_settlement_runs r WHERE r.scope_kind=kind AND r.scope_id=identity AND r.period_start=p_from AND r.period_end=p_to)
  OR EXISTS(SELECT FROM public.agent_commission_settlements a WHERE a.club_id=ANY(clubs)AND a.period_start=p_from AND a.period_end=p_to)
  OR EXISTS(SELECT FROM public.rakeback_periods r WHERE r.club_id=ANY(clubs)AND r.period_start=(p_from AT TIME ZONE'America/Los_Angeles')::date AND(r.status<>'pending'OR EXISTS(SELECT FROM public.rakeback_period_payouts pp WHERE pp.rakeback_period_id=r.id)))THEN RAISE EXCEPTION 'own_agent_interpretation_week_already_paid' USING ERRCODE='23514';END IF;
  SELECT coalesce(jsonb_agg(jsonb_build_object('kind',p.kind,'window_start',p.window_start,'window_end',p.window_end,'full_row_md5',md5(to_jsonb(p)::text))ORDER BY p.kind,p.window_start),'[]')INTO parts FROM public.accounting_close_partials p WHERE p.union_id=identity AND p.period_start=p_from AND p.period_end=p_to;
  SELECT coalesce(jsonb_agg(jsonb_build_object('kind',c.kind,'full_row_md5',md5(to_jsonb(c)::text))ORDER BY c.kind),'[]')INTO certs FROM public.accounting_close_certificates c WHERE c.union_id=identity AND c.period_start=p_from AND c.period_end=p_to;
  INSERT INTO public.accounting_own_agent_preparation_versions(scope_kind,scope_id,period_start,period_end,version,original_partials,original_certificates,owner_hashes)VALUES(kind,identity,p_from,p_to,'own-agent-v1',parts,certs,jsonb_build_object('producer',md5(pg_get_functiondef('public.fn_accounting_earning_contract(uuid,uuid,numeric,uuid,timestamptz)'::regprocedure)),'calculator',md5(pg_get_functiondef('public.fn_calculate_cash_rakeback_periods(uuid,date,date,uuid[])'::regprocedure)),'split_check',md5(pg_get_functiondef('public.fn_rakeback_split_check(uuid,date,date,uuid[])'::regprocedure)),'split_write',md5(pg_get_functiondef('public.fn_rakeback_split_write(uuid,date,date,uuid[])'::regprocedure))));
  DELETE FROM public.accounting_close_partials WHERE union_id=identity AND period_start=p_from AND period_end=p_to;
  DELETE FROM public.accounting_close_certificates WHERE union_id=identity AND period_start=p_from AND period_end=p_to;
  DELETE FROM public.accounting_recompute_split_parts WHERE club_id=ANY(clubs)AND period_start=(p_from AT TIME ZONE'America/Los_Angeles')::date AND period_end=(p_to AT TIME ZONE'America/Los_Angeles')::date-1;
  UPDATE public.accounting_period_recompute_requests SET status='pending',reason=NULL,last_result='{}',last_requested_at=clock_timestamp()WHERE club_id=ANY(clubs)AND period_start=(p_from AT TIME ZONE'America/Los_Angeles')::date AND period_end=(p_to AT TIME ZONE'America/Los_Angeles')::date-1;
 END IF;
 -- WINDOW BY WINDOW 20261102: the whole-week form of this query sorted every
 -- payable source of the week (millions of rows through the union view and
 -- their contract JSON) before returning one row, so it could not finish
 -- inside a 240s preparation tick and the 2026-11-02 payout never prepared.
 -- The same filters run per canonical close window (about 0.5s each); the
 -- reviewed set and every decision are identical, only the visiting order
 -- becomes window, then source. If the canonical windows do not tile the week
 -- exactly, the original whole-week query runs unchanged.
 SELECT min(x.window_start),max(x.window_end),count(*),
  count(*) FILTER(WHERE x.window_start IS DISTINCT FROM x.prev_end AND x.prev_end IS NOT NULL)
  INTO win_first,win_last,win_n,win_gaps
  FROM(SELECT c.window_start,c.window_end,lag(c.window_end)OVER(ORDER BY c.window_start)prev_end FROM public.fn_accounting_close_windows(p_from,p_to)c)x;
 by_window:=win_n>0 AND win_first=p_from AND win_last=p_to AND win_gaps=0;
 IF by_window THEN
 FOR w IN SELECT c.window_start,c.window_end FROM public.fn_accounting_close_windows(p_from,p_to)c ORDER BY c.window_start LOOP
  EXIT WHEN seen>=p_limit OR budget_exhausted;
  IF work_deadline IS NOT NULL AND clock_timestamp()+interval '1 second'>=work_deadline THEN budget_exhausted:=true;EXIT;END IF;
  -- CLEAN WINDOWS ARE REMEMBERED 20261102: a window whose every candidate
  -- was reviewed stays clean until a source of this week's clubs is recorded
  -- or admitted after the window was checked (the recompute's reuse rule).
  CONTINUE WHEN EXISTS(SELECT 1 FROM smarter_private.own_agent_clean_windows k
   WHERE k.scope_kind=kind AND k.scope_id=identity AND k.period_start=p_from AND k.period_end=p_to AND k.window_start=w.window_start
    AND NOT EXISTS(SELECT 1 FROM (SELECT s.earned_at FROM public.accounting_cash_rake_sources s
      WHERE s.club_id=ANY(clubs) AND s.recorded_at>k.checked_at-interval '1 minute' OFFSET 0) s WHERE s.earned_at>=w.window_start AND s.earned_at<w.window_end)
    AND NOT EXISTS(SELECT 1 FROM public.accounting_tournament_fee_sources f
      WHERE f.club_id=ANY(clubs) AND f.recorded_at>k.checked_at-interval '1 minute' AND f.charged_at>=w.window_start AND f.charged_at<w.window_end)
    AND NOT EXISTS(SELECT 1 FROM public.accounting_cash_atomic_contract_admissions a WHERE a.admitted_at>k.checked_at-interval '1 minute'));
  win_seen:=seen;win_exited:=false;
 FOR item IN SELECT s.source_type,s.source_id FROM public.accounting_payable_earning_sources s
 WHERE s.earned_at>=w.window_start AND s.earned_at<w.window_end AND((p_union IS NOT NULL AND s.coordinator_union_id=p_union)OR(p_club IS NOT NULL AND s.club_id=p_club AND s.coordinator_union_id IS NULL))
 AND coalesce(s.contract#>>'{membership,terms,role}','')IN('super_agent','agent','sub_agent')AND s.contract#>>'{tiers,0,user_id}'IS DISTINCT FROM s.player_id::text
 AND NOT(coalesce((s.contract#>>'{membership,terms,player_rakeback_pct}')::numeric=.70,false)AND EXISTS(SELECT FROM public.clubs c WHERE c.id=s.club_id AND c.owner_id=NULLIF(s.contract#>>'{membership,terms,agent_id}','')::uuid))
 AND NOT EXISTS(SELECT FROM public.accounting_own_agent_source_reviews a WHERE a.source_type=s.source_type AND a.source_id=s.source_id)
 ORDER BY s.source_type,s.source_id LIMIT p_limit-seen LOOP
  IF work_deadline IS NOT NULL AND clock_timestamp()+interval '1 second'>=work_deadline THEN budget_exhausted:=true;win_exited:=true;EXIT;END IF;
  seen:=seen+1;
  SELECT md5(s.contract::text)INTO STRICT old_hash FROM public.accounting_payable_earning_sources s WHERE s.source_type=item.source_type AND s.source_id=item.source_id;
  did_admit:=smarter_private.admit_own_agent_source(item.source_type,item.source_id);
  IF did_admit THEN admitted:=admitted+1;END IF;
  SELECT md5(s.contract::text)INTO STRICT new_hash FROM public.accounting_payable_earning_sources s WHERE s.source_type=item.source_type AND s.source_id=item.source_id;
  INSERT INTO public.accounting_own_agent_source_reviews(source_type,source_id,version,original_contract_md5,effective_contract_md5,outcome)VALUES(item.source_type,item.source_id,'own-agent-v1',old_hash,new_hash,CASE WHEN did_admit THEN'admitted'ELSE'unchanged'END);
  IF work_deadline IS NOT NULL AND clock_timestamp()+interval '1 second'>=work_deadline THEN budget_exhausted:=true;win_exited:=true;EXIT;END IF;
 END LOOP;
  IF NOT win_exited AND NOT budget_exhausted AND seen-win_seen<p_limit-win_seen THEN
   INSERT INTO smarter_private.own_agent_clean_windows(scope_kind,scope_id,period_start,period_end,window_start,checked_at)
   VALUES(kind,identity,p_from,p_to,w.window_start,clock_timestamp())
   ON CONFLICT(scope_kind,scope_id,period_start,period_end,window_start) DO UPDATE SET checked_at=EXCLUDED.checked_at;
  END IF;
 END LOOP;
 ELSE
 FOR item IN SELECT s.source_type,s.source_id FROM public.accounting_payable_earning_sources s
 WHERE s.earned_at>=p_from AND s.earned_at<p_to AND((p_union IS NOT NULL AND s.coordinator_union_id=p_union)OR(p_club IS NOT NULL AND s.club_id=p_club AND s.coordinator_union_id IS NULL))
 AND coalesce(s.contract#>>'{membership,terms,role}','')IN('super_agent','agent','sub_agent')AND s.contract#>>'{tiers,0,user_id}'IS DISTINCT FROM s.player_id::text
 AND NOT(coalesce((s.contract#>>'{membership,terms,player_rakeback_pct}')::numeric=.70,false)AND EXISTS(SELECT FROM public.clubs c WHERE c.id=s.club_id AND c.owner_id=NULLIF(s.contract#>>'{membership,terms,agent_id}','')::uuid))
 AND NOT EXISTS(SELECT FROM public.accounting_own_agent_source_reviews a WHERE a.source_type=s.source_type AND a.source_id=s.source_id)
 ORDER BY s.source_type,s.source_id LIMIT p_limit LOOP
  IF work_deadline IS NOT NULL AND clock_timestamp()+interval '1 second'>=work_deadline THEN budget_exhausted:=true;EXIT;END IF;
  seen:=seen+1;
  SELECT md5(s.contract::text)INTO STRICT old_hash FROM public.accounting_payable_earning_sources s WHERE s.source_type=item.source_type AND s.source_id=item.source_id;
  did_admit:=smarter_private.admit_own_agent_source(item.source_type,item.source_id);
  IF did_admit THEN admitted:=admitted+1;END IF;
  SELECT md5(s.contract::text)INTO STRICT new_hash FROM public.accounting_payable_earning_sources s WHERE s.source_type=item.source_type AND s.source_id=item.source_id;
  INSERT INTO public.accounting_own_agent_source_reviews(source_type,source_id,version,original_contract_md5,effective_contract_md5,outcome)VALUES(item.source_type,item.source_id,'own-agent-v1',old_hash,new_hash,CASE WHEN did_admit THEN'admitted'ELSE'unchanged'END);
  IF work_deadline IS NOT NULL AND clock_timestamp()+interval '1 second'>=work_deadline THEN budget_exhausted:=true;EXIT;END IF;
 END LOOP;
 END IF;
 RETURN jsonb_build_object('ready',NOT budget_exhausted AND seen<p_limit,'admitted',admitted,'reviewed',seen,'budget_exhausted',budget_exhausted,'version','own-agent-v1');
END $function$

smarter_private.preserve_historical_rake.def:
CREATE OR REPLACE FUNCTION smarter_private.preserve_historical_rakeback_wallet(p_period uuid, p_certificate bigint, p_start timestamp with time zone, p_end timestamp with time zone)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
AS $function$
DECLARE admission jsonb; cid uuid; uid uuid; saved text; saved_period text; saved_cert text; saved_start text; saved_end text;
BEGIN
 admission:=smarter_private.historical_rakeback_wallet_admission(p_period,p_certificate,p_start,p_end);
 cid:=(admission->>'club_id')::uuid;uid:=(admission->>'user_id')::uuid;
 IF to_regclass('pg_temp._routed_player_todo') IS NULL OR to_regclass('pg_temp._routed_player_funding') IS NULL THEN RAISE EXCEPTION 'historical_wallet_native_stage_required'; END IF;
 IF NOT EXISTS(SELECT FROM pg_temp._routed_player_todo WHERE period_id=p_period AND certificate_id=p_certificate AND club_id=cid AND user_id=uid AND owed>0)
 OR EXISTS(SELECT FROM pg_temp._routed_player_funding WHERE club_id=cid AND payer_kind='agent' AND payer_user=uid) THEN RAISE EXCEPTION 'historical_wallet_payer_restoration_refused'; END IF;
 PERFORM public.fn_club_membership_lock(uid);
 IF EXISTS(SELECT FROM public.club_members WHERE club_id=cid AND user_id=uid) THEN RETURN; END IF;
 saved:=current_setting('app.club_membership_source',true);saved_period:=current_setting('app.historical_rakeback_period',true);
 saved_cert:=current_setting('app.historical_rakeback_certificate',true);saved_start:=current_setting('app.historical_rakeback_start',true);saved_end:=current_setting('app.historical_rakeback_end',true);
 PERFORM set_config('app.club_membership_source','historical_rakeback_wallet',true);
 PERFORM set_config('app.historical_rakeback_period',p_period::text,true);PERFORM set_config('app.historical_rakeback_certificate',p_certificate::text,true);
 PERFORM set_config('app.historical_rakeback_start',p_start::text,true);PERFORM set_config('app.historical_rakeback_end',p_end::text,true);
 INSERT INTO public.club_members(club_id,user_id,role,status,is_active,membership_lifecycle_status,departed_at,departure_reason,chip_balance,promo_balance,held_chips,locked_chips,credit_limit,credit_used,commission_rate,rakeback_rate,player_rakeback_pct,agent_id,parent_agent_id)
 VALUES(cid,uid,'player','suspended',false,'departed',clock_timestamp(),'historical_rakeback:'||p_period::text||':'||p_certificate::text,0,0,0,0,0,0,0,0,0,NULL,NULL);
 PERFORM set_config('app.club_membership_source',coalesce(saved,''),true);PERFORM set_config('app.historical_rakeback_period',coalesce(saved_period,''),true);
 PERFORM set_config('app.historical_rakeback_certificate',coalesce(saved_cert,''),true);PERFORM set_config('app.historical_rakeback_start',coalesce(saved_start,''),true);PERFORM set_config('app.historical_rakeback_end',coalesce(saved_end,''),true);
 IF NOT EXISTS(SELECT FROM public.club_members WHERE club_id=cid AND user_id=uid AND role='player' AND status='suspended' AND is_active=false AND membership_lifecycle_status='departed'
 AND chip_balance=0 AND promo_balance=0 AND held_chips=0 AND locked_chips=0 AND credit_limit=0 AND credit_used=0 AND agent_id IS NULL AND parent_agent_id IS NULL) THEN RAISE EXCEPTION 'historical_wallet_insert_shape_changed'; END IF;
END $function$

smarter_private.rakeback_certificate_wal.def:
CREATE OR REPLACE FUNCTION smarter_private.rakeback_certificate_wallets(p_calculation bigint)
 RETURNS TABLE(payer_kind text, payer_user uuid, payer_entity uuid, owed numeric, destination_kind text)
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
AS $function$
DECLARE c public.accounting_rakeback_period_calculations%ROWTYPE;plan jsonb;
BEGIN
 SELECT*INTO STRICT c FROM public.accounting_rakeback_period_calculations WHERE id=p_calculation;
 IF NOT EXISTS(SELECT FROM jsonb_array_elements(c.source_allocations)a WHERE a?'destination_kind')THEN
  RETURN QUERY SELECT g.payer_kind,g.payer_user,g.payer_entity,g.owed,'player_wallet'::text FROM smarter_private.rakeback_certificate_payers(p_calculation)g;RETURN;
 END IF;
 -- Preserve and verify the original per-payer contract and cent allocation.
 PERFORM*FROM smarter_private.rakeback_certificate_payers(p_calculation);
 plan:=smarter_private.rakeback_wallet_plan(c.source_allocations,c.rakeback_amount);
 IF(SELECT count(*)FROM public.accounting_rakeback_wallet_contracts w WHERE w.calculation_id=c.id)<>jsonb_array_length(plan)
 OR EXISTS(SELECT FROM jsonb_array_elements(plan)p LEFT JOIN public.accounting_rakeback_wallet_contracts w ON w.calculation_id=c.id AND w.payer_kind=p->>'payer_kind'AND w.payer_entity_id=coalesce(NULLIF(p->>'payer_user_id','')::uuid,c.club_id)AND w.destination_kind=p->>'destination_kind'WHERE w.calculation_id IS NULL OR w.amount IS DISTINCT FROM(p->>'amount')::numeric OR w.unrounded IS DISTINCT FROM(p->>'unrounded')::numeric OR w.rake IS DISTINCT FROM(p->>'rake')::numeric OR w.source_count IS DISTINCT FROM(p->>'source_count')::bigint OR w.source_fingerprint IS DISTINCT FROM c.source_fingerprint OR w.payer_user_id=c.player_id)
 THEN RAISE EXCEPTION 'typed_wallet_contract_disagrees' USING ERRCODE='23514';END IF;
 RETURN QUERY SELECT w.payer_kind,w.payer_user_id,w.payer_entity_id,w.amount,w.destination_kind FROM public.accounting_rakeback_wallet_contracts w WHERE w.calculation_id=c.id ORDER BY w.payer_kind,w.payer_entity_id,w.destination_kind;
END $function$

smarter_private.rakeback_wallet_plan(p_a.def:
CREATE OR REPLACE FUNCTION smarter_private.rakeback_wallet_plan(p_allocations jsonb, p_amount numeric)
 RETURNS jsonb
 LANGUAGE plpgsql
 IMMUTABLE SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
AS $function$
DECLARE original jsonb;result jsonb;
BEGIN
 original:=smarter_private.rakeback_payer_plan(p_allocations,p_amount);
 IF EXISTS(SELECT FROM jsonb_array_elements(p_allocations)a WHERE a?'destination_kind'AND(a->>'destination_kind'IS DISTINCT FROM'agent_wallet'OR a->>'interpretation_version'IS DISTINCT FROM'own-agent-v1'OR jsonb_typeof(a->'destination_agreement')IS DISTINCT FROM'object'))THEN RAISE EXCEPTION 'rakeback_wallet_destination_invalid' USING ERRCODE='23514';END IF;
 WITH groups AS(
  SELECT a->>'payer_kind'kind,NULLIF(a->>'payer_user_id','')::uuid payer,coalesce(a->>'destination_kind','player_wallet')destination,
   sum((a->>'rake_credit')::numeric)rake,sum((a->>'rake_credit')::numeric*(a->>'rate')::numeric)unrounded,count(*)n
  FROM jsonb_array_elements(p_allocations)a GROUP BY 1,2,3
 ),cents AS(
  SELECT g.*,floor(g.unrounded*100)whole,row_number()OVER(PARTITION BY g.kind,g.payer ORDER BY g.unrounded*100-floor(g.unrounded*100)DESC,g.destination)rank,
   (p->>'amount')::numeric*100-sum(floor(g.unrounded*100))OVER(PARTITION BY g.kind,g.payer)extra
  FROM groups g JOIN jsonb_array_elements(original)p ON p->>'payer_kind'=g.kind AND NULLIF(p->>'payer_user_id','')::uuid IS NOT DISTINCT FROM g.payer
 )SELECT jsonb_agg(jsonb_build_object('payer_kind',kind,'payer_user_id',payer,'destination_kind',destination,'rake',rake,'unrounded',unrounded,'source_count',n,'amount',(whole+CASE WHEN rank<=extra THEN 1 ELSE 0 END)/100)ORDER BY kind,payer NULLS FIRST,destination)INTO result FROM cents;
 IF(SELECT sum((p->>'amount')::numeric)FROM jsonb_array_elements(result)p)IS DISTINCT FROM p_amount THEN RAISE EXCEPTION 'rakeback_wallet_plan_not_conserved' USING ERRCODE='23514';END IF;
 RETURN result;
END $function$

smarter_private.record_rakeback_wallet_c.def:
CREATE OR REPLACE FUNCTION smarter_private.record_rakeback_wallet_contracts()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
AS $function$
DECLARE allocation jsonb;actual jsonb;authority jsonb;plan jsonb;n int;
BEGIN
 IF NOT EXISTS(SELECT FROM jsonb_array_elements(NEW.source_allocations)a WHERE a?'destination_kind')THEN RETURN NULL;END IF;
 IF NOT EXISTS(SELECT FROM public.rakeback_periods r WHERE r.id=NEW.period_id AND r.status='pending')THEN RAISE EXCEPTION 'typed_wallet_certificate_requires_unpaid_period' USING ERRCODE='23514';END IF;
 FOR allocation IN SELECT a FROM jsonb_array_elements(NEW.source_allocations)a WHERE a?'destination_kind'LOOP
  SELECT count(*),(jsonb_agg(to_jsonb(s)))->0 INTO n,actual FROM public.accounting_payable_earning_sources s WHERE s.source_type=allocation->>'source_type'AND s.source_id=(allocation->>'source_id')::uuid;
  IF n<>1 OR actual->>'club_id'IS DISTINCT FROM NEW.club_id::text OR actual->>'player_id'IS DISTINCT FROM NEW.player_id::text THEN RAISE EXCEPTION 'typed_wallet_source_identity_changed' USING ERRCODE='23514';END IF;
  authority:=smarter_private.own_agent_destination_contract(actual->'contract',NEW.club_id,NEW.player_id,(allocation->>'agreement_at')::timestamptz);
  IF authority IS NULL OR authority IS DISTINCT FROM allocation->'destination_agreement'OR allocation->>'interpretation_version'IS DISTINCT FROM'own-agent-v1'OR allocation->>'destination_kind'IS DISTINCT FROM'agent_wallet'OR(allocation->>'rate')::numeric IS DISTINCT FROM .70 OR actual#>>'{contract,membership,terms,role}'NOT IN('super_agent','agent','sub_agent')THEN RAISE EXCEPTION 'typed_wallet_historical_destination_not_observed' USING ERRCODE='23514';END IF;
 END LOOP;
 plan:=smarter_private.rakeback_wallet_plan(NEW.source_allocations,NEW.rakeback_amount);
 INSERT INTO public.accounting_rakeback_wallet_contracts(calculation_id,payer_kind,payer_entity_id,payer_user_id,destination_kind,amount,unrounded,rake,source_count,source_fingerprint)
 SELECT NEW.id,p->>'payer_kind',coalesce(NULLIF(p->>'payer_user_id','')::uuid,NEW.club_id),NULLIF(p->>'payer_user_id','')::uuid,p->>'destination_kind',(p->>'amount')::numeric,(p->>'unrounded')::numeric,(p->>'rake')::numeric,(p->>'source_count')::bigint,NEW.source_fingerprint FROM jsonb_array_elements(plan)p;
 RETURN NULL;
END $function$

smarter_private.weekly_hand_parts_read(p.def:
CREATE OR REPLACE FUNCTION smarter_private.weekly_hand_parts_read(p_union uuid, p_start timestamp with time zone, p_end timestamp with time zone, p_generation text, p_projected boolean)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE
 SET search_path TO 'pg_catalog', 'public', 'smarter_private'
AS $function$
DECLARE w record;p record;groups jsonb:='[]';n bigint;expected bigint;
BEGIN
 IF current_setting('app.weekly_accounting_chunked',true) IS DISTINCT FROM 'on' OR current_setting('app.accounting_close_memo',true) IS DISTINCT FROM 'on' THEN RETURN NULL;END IF;
 IF p_generation IS NULL OR p_generation='original-inventory-245:unqualified' THEN RETURN NULL;END IF;
 SELECT count(*) INTO expected FROM public.fn_accounting_close_windows(p_start,p_end);
 SELECT count(*) INTO n FROM public.accounting_close_partials WHERE kind='pnl_hands_window' AND union_id=p_union AND period_start=p_start AND period_end=p_end;
 IF expected=0 OR n<>expected THEN RETURN NULL;END IF;
 FOR w IN SELECT * FROM public.fn_accounting_close_windows(p_start,p_end) ORDER BY 1 LOOP
 SELECT * INTO p FROM public.accounting_close_partials WHERE kind='pnl_hands_window' AND union_id=p_union AND period_start=p_start AND period_end=p_end AND window_start=w.window_start;
 IF NOT FOUND OR p.window_end IS DISTINCT FROM w.window_end OR p.computed_at<p_end OR p.computed_at<=clock_timestamp()-public.fn_accounting_close_proof_lifetime()
 OR p.value->>'generation' IS DISTINCT FROM p_generation OR p.value->'projected' IS DISTINCT FROM to_jsonb(p_projected)
 OR p.computed_at>clock_timestamp() OR jsonb_typeof(p.value->'groups') IS DISTINCT FROM 'array' OR p.value->>'groups_md5' IS DISTINCT FROM md5((p.value->'groups')::text)
 OR p.value->>'contract' IS DISTINCT FROM '9dee2921c7b956281be61a3eb9d7df6e'
 OR p.value->'witness' IS DISTINCT FROM smarter_private.weekly_hand_parts_witness(p_union,w.window_start,w.window_end,p_projected)
 THEN RETURN NULL;END IF;
 groups:=groups||(p.value->'groups');
 END LOOP;
 RETURN(SELECT COALESCE(jsonb_agg(to_jsonb(q) ORDER BY kind,club_id,user_id),'[]'::jsonb) FROM(
 SELECT kind,club_id,user_id,sum(delta)delta,sum(hands)::bigint hands,sum(rake)rake
 FROM jsonb_to_recordset(groups)x(kind integer,club_id uuid,user_id uuid,delta numeric,hands bigint,rake numeric)GROUP BY kind,club_id,user_id)q);
END $function$

smarter_private.weekly_payout_due().def:
CREATE OR REPLACE FUNCTION smarter_private.weekly_payout_due()
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
AS $function$
DECLARE n timestamptz:=smarter_private.weekly_payout_clock();e timestamptz:=public.fn_union_week_start(n);
 c timestamptz;r public.weekly_accounting_payout_pauses%ROWTYPE;answer jsonb;lost jsonb;
BEGIN
 SELECT cutover_period_end INTO STRICT c FROM smarter_private.weekly_payout_phase_configuration WHERE singleton;
 IF e<c THEN RETURN NULL;END IF;
 IF NOT pg_try_advisory_xact_lock(hashtextextended('union-accounting-scheduler',0)) THEN
  RETURN jsonb_build_object('success',false,'owns_tick',true,'advanced',false,'stage','weekly_payout_original_scheduler_owned');END IF;
 -- EVERY PREPARED SCOPE IS PAID; THE REST CATCH UP (20261031190020): the
 -- newest owned boundary of this closed week. Released (paid, refused or
 -- missed) means the next slot is prepared for whatever this week still owes;
 -- with nothing owed, or every slot spent, the original post-money scope owner
 -- continues P&L/docs and reads the original financial receipts, never paying
 -- them again.
 SELECT * INTO r FROM public.weekly_accounting_payout_pauses p WHERE p.period_end=e ORDER BY p.attempt_no DESC LIMIT 1;
 -- ROUND RUNNER OWNS THE MONEY (owner, 2026-11-02): a database-only runner
 -- boundary is paid round by round by weekly_payout_next_round, never here.
 IF FOUND AND r.instance_id IS NOT DISTINCT FROM 'weekly-payout-rounds' AND r.phase<>'released' THEN
  RETURN jsonb_build_object('success',true,'owns_tick',true,'advanced',false,'stage','weekly_payout_rounds_running','run_id',r.run_id);END IF;
 IF NOT FOUND OR r.phase='released' THEN RETURN smarter_private.weekly_payout_prepare_due();END IF;
 IF n<r.money_starts_at THEN
  RETURN jsonb_build_object('success',false,'owns_tick',true,'advanced',false,'stage','weekly_payout_prepared',
   'run_id',r.run_id,'attempt_no',r.attempt_no,'scheduled_for',r.money_starts_at);
 END IF;
 BEGIN
  answer:=smarter_private.weekly_payout_execute(r.run_id);
 EXCEPTION WHEN OTHERS THEN
  -- This subtransaction rolled back every financial pass, context capability
  -- and receipt together. A network-unknown outcome is read from this SAME
  -- durable run; this handler never starts another payer or extends the pause.
  -- The scopes it owned stay owed and are prepared for the next owned slot.
  answer:=jsonb_build_object('success',false,'owns_tick',true,'advanced',false,'stage','weekly_payout_financial_refused',
   'run_id',r.run_id,'attempt_no',r.attempt_no,'sqlstate',SQLSTATE,'reason',SQLERRM,'paid',false,'scheduled_for',r.money_starts_at,'observed_at',smarter_private.weekly_payout_clock());
  -- MEASURED MONEY ADMISSION (20261031223940): an acknowledged slot whose own
  -- money statement was lost (read from the scheduler's durable run record,
  -- outside the rolled-back statement) is marked so that every later slot of
  -- this week owns one scope; a lost SOLO statement records that scope's loss.
  IF r.acknowledged_at IS NOT NULL THEN
   lost:=smarter_private.weekly_payout_lost_money_run(r.money_starts_at,r.money_deadline_at);
  END IF;
  IF lost IS NOT NULL THEN
   answer:=answer||jsonb_build_object('money_lost',true,'money_lost_run',lost);
   IF jsonb_array_length(r.scope_plan)=1 THEN
    INSERT INTO smarter_private.weekly_payout_money_losses(period_end,scope_kind,scope_id,run_id,attempt_no,evidence)
    VALUES(r.period_end,r.scope_plan->0->>'kind',(r.scope_plan->0->>'id')::uuid,r.run_id,r.attempt_no,lost)ON CONFLICT DO NOTHING;
   END IF;
  END IF;
  UPDATE public.weekly_accounting_payout_pauses SET phase='released',result=answer WHERE run_id=r.run_id;
 END;
 -- PRODUCTION ALERTS (20261031210000): a refused slot or a deferred scope is
 -- recorded once per boundary for Production Alerts; it never pages and never
 -- changes the payout outcome. The owed scopes are prepared for the next slot.
 IF answer->>'stage'='weekly_payout_financial_refused' OR jsonb_array_length(COALESCE(answer->'deferred_scopes','[]'::jsonb))>0 THEN
  BEGIN
   PERFORM public.fn_record_operational_alert('weekly-payout',
    CASE WHEN answer->>'stage'='weekly_payout_financial_refused' THEN 'refused:' ELSE 'deferred:' END||r.run_id::text,
    CASE WHEN answer->>'stage'='weekly_payout_financial_refused' THEN 'WeeklyPayoutSlotRefused' ELSE 'WeeklyPayoutScopeDeferred' END,
    'firing','warning',jsonb_build_object('target_task_id','01a09b86-5ba8-7290-8657-1041f13dd3ca','period_start',r.period_start,'period_end',r.period_end,'attempt_no',r.attempt_no,
     'scheduled_for',r.money_starts_at,'reason',answer->>'reason','deferred_scopes',COALESCE(answer->'deferred_scopes','[]'::jsonb),
     'next','owed scopes are prepared for the next owned hourly slot'));
  EXCEPTION WHEN OTHERS THEN NULL;
  END;
 END IF;
 RETURN answer;
END $function$

smarter_private.weekly_payout_execute(p_.def:
CREATE OR REPLACE FUNCTION smarter_private.weekly_payout_execute(p_run uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
 SET lock_timeout TO '20s'
AS $function$
DECLARE r public.weekly_accounting_payout_pauses%ROWTYPE;item jsonb;res jsonb;prep jsonb;
 round integer;k text;id uuid;ws timestamptz;we timestamptz;receipts jsonb:='[]'::jsonb;
 kept jsonb:='[]'::jsonb;deferred jsonb:='[]'::jsonb;
 began timestamptz:=smarter_private.weekly_payout_clock();
BEGIN
 IF NOT public.fn_caller_is_engine() THEN RAISE EXCEPTION 'service_role_required' USING ERRCODE='42501';END IF;
 IF current_setting('statement_timeout')::interval < interval '240 seconds'
  OR COALESCE(current_setting('app.weekly_accounting_chunked',true),'')<>'on'
 THEN RAISE EXCEPTION 'weekly_payout_original_240s_tick_required' USING ERRCODE='55000';END IF;
 SELECT * INTO STRICT r FROM public.weekly_accounting_payout_pauses WHERE run_id=p_run;
 -- The original 04:00 invocation waits for its own physical fleet barrier.
 -- Do not lock the row before ACK: that would block the engine transaction
 -- needed to release this very wait. This bounded wait is part of the SAME
 -- original DUE statement, never a repair worker, new payer or renewed lease.
 WHILE r.phase='draining' AND smarter_private.weekly_payout_clock()>=r.money_starts_at
  AND smarter_private.weekly_payout_clock()+interval '45 seconds'<r.money_deadline_at LOOP
  PERFORM pg_sleep(0.05);
  SELECT * INTO STRICT r FROM public.weekly_accounting_payout_pauses WHERE run_id=p_run;
 END LOOP;
 SELECT * INTO STRICT r FROM public.weekly_accounting_payout_pauses WHERE run_id=p_run FOR UPDATE;
 began:=smarter_private.weekly_payout_clock();
 IF r.phase='released' THEN RETURN r.result||jsonb_build_object('duplicate',true);END IF;
 -- The original 180s scope must fit before the absolute money deadline and
 -- the original 240s statement must fit before the gameplay lease. Admission
 -- never renews either clock. Actual start time is retained rather than
 -- calling a late cron invocation an on-time four-o'clock payout.
 IF r.phase<>'ready' OR r.acknowledged_at>=r.money_deadline_at OR r.acknowledged_at IS NULL
  OR began<r.money_starts_at OR began+interval '45 seconds'>=r.money_deadline_at
  OR statement_timestamp()+interval '240 seconds'>=r.expires_at
  OR NOT smarter_private.weekly_payout_claims_match(r.instance_id,r.lease_claims)
 THEN RAISE EXCEPTION 'weekly_payout_not_prepared_and_parked_at_four' USING ERRCODE='55000';END IF;
 -- EVERY PREPARED SCOPE IS PAID (20261031190020): a boundary may own a subset
 -- of what this week still owes; every owned scope must still be owed, once.
 IF EXISTS(SELECT FROM jsonb_array_elements(r.scope_plan) j
   WHERE NOT j IN (SELECT value FROM jsonb_array_elements(smarter_private.weekly_payout_scope_plan(r.period_end,began))))
  OR (SELECT count(DISTINCT j) FROM jsonb_array_elements(r.scope_plan) j)<>jsonb_array_length(r.scope_plan)
 THEN RAISE EXCEPTION 'weekly_payout_prepared_scope_changed' USING ERRCODE='55000';END IF;
 PERFORM public.fn_weekly_accounting_attempt_begin(true);
 -- THE MONEY WINDOW IS THE BUDGET (owner override, 2026-11-02): the scope
 -- deadline runs to two seconds before the absolute money deadline instead of
 -- the statement start plus 180 seconds, which the engine's park acknowledgement
 -- (34 s on 2026-11-02) had already consumed.
 PERFORM set_config('app.weekly_accounting_scope_deadline',(r.money_deadline_at-interval '2 seconds')::text,true);
 -- Revalidate original prepared earning/certificate owners immediately before
 -- any financial capability exists. Changed applicable source evidence must
 -- refuse or be admitted by its original producer, never by a current-rate
 -- rewrite here. No old paid JSON, timestamps or fingerprints are retagged.
 FOR item IN SELECT value FROM jsonb_array_elements(r.scope_plan) LOOP
  PERFORM public.fn_weekly_accounting_deadline_check();
  -- A scope whose preparation changed is deferred to the next owned slot with
  -- nothing paid; it never refuses the scopes that are still prepared.
  BEGIN
   prep:=public.fn_prepare_accounting_week(CASE WHEN item->>'kind'='union' THEN (item->>'id')::uuid END,
    CASE WHEN item->>'kind'='club' THEN (item->>'id')::uuid END,(item->>'period_start')::timestamptz,(item->>'period_end')::timestamptz);
  EXCEPTION WHEN OTHERS THEN
   IF SQLSTATE='57014' THEN RAISE;END IF;
   prep:=jsonb_build_object('success',false,'error',SQLERRM,'sqlstate',SQLSTATE);
  END;
  IF prep->>'success'='true' THEN kept:=kept||jsonb_build_array(item);
  ELSE deferred:=deferred||jsonb_build_array(jsonb_build_object('scope',item,'preparation',prep));END IF;
 END LOOP;
 IF jsonb_array_length(kept)=0 THEN
  RAISE EXCEPTION 'weekly_payout_precommit_preparation_changed' USING ERRCODE='55000',DETAIL=deferred::text;END IF;
 IF kept IS DISTINCT FROM r.scope_plan THEN
  UPDATE public.weekly_accounting_payout_pauses SET scope_plan=kept WHERE run_id=r.run_id RETURNING * INTO r;
 END IF;
 UPDATE public.weekly_accounting_payout_pauses SET phase='paying' WHERE run_id=r.run_id;
 -- This outer order is deliberate: ALL club funding, then ALL agent gross
 -- pass-downs, and only then ANY player/horse secondary payment.
 FOR round IN 1..3 LOOP
  FOR item IN SELECT value FROM jsonb_array_elements(r.scope_plan) LOOP
   k:=item->>'kind';id:=(item->>'id')::uuid;ws:=(item->>'period_start')::timestamptz;we:=(item->>'period_end')::timestamptz;
   PERFORM public.fn_weekly_accounting_deadline_check();
   IF smarter_private.weekly_payout_clock()>=r.money_deadline_at THEN
    RAISE EXCEPTION 'weekly_payout_absolute_money_deadline' USING ERRCODE='57014';END IF;
   INSERT INTO smarter_private.weekly_payout_owned_transactions(backend_pid,transaction_id,run_id,scope_kind,scope_id,period_start,period_end,round_no)
   VALUES(pg_backend_pid(),txid_current(),r.run_id,k,id,ws,we,round)
   ON CONFLICT(backend_pid,transaction_id)DO UPDATE SET scope_kind=EXCLUDED.scope_kind,scope_id=EXCLUDED.scope_id,
    period_start=EXCLUDED.period_start,period_end=EXCLUDED.period_end,round_no=EXCLUDED.round_no;
   IF round=1 THEN
    -- The original R1 closes and posts its own treasury debit; there is no
    -- transaction-local debit deferred until slow post-money documents.
    PERFORM set_config('app.union_close_defer_rake_debit','',true);
    IF k='union' THEN
     res:=public.fn_union_weekly_rakeback_close(id,ws,we);
     IF res->>'success' IS DISTINCT FROM 'true' AND res->>'error' IS DISTINCT FROM 'already_executed' THEN
      RAISE EXCEPTION 'weekly_payout_original_round1_refused' USING DETAIL=res::text;END IF;
    ELSE
     res:=public.fn_bank_standalone_week_rake(id,ws,we);
     IF res->>'ok' IS DISTINCT FROM 'true' THEN RAISE EXCEPTION 'weekly_payout_original_club_bank_refused' USING DETAIL=res::text;END IF;
    END IF;
   ELSIF round=2 THEN
    res:=public.fn_settle_accounting_commission_stage(k,id,ws,we);
   ELSE
    res:=public.fn_settle_accounting_rakeback_stage(k,id,ws,we);
   END IF;
   IF round IN(2,3) AND (res->>'success' IS DISTINCT FROM 'true' OR res->>'routing_version' IS DISTINCT FROM '3'
    OR res->>'source_version' IS DISTINCT FROM '2' OR COALESCE((res->>'shortfalls')::integer,0)<>0
    OR res->>'batch_committed'='true' OR NOT EXISTS(SELECT FROM public.accounting_routed_settlement_runs x
     WHERE x.scope_kind=k AND x.scope_id=id AND x.period_start=ws AND x.period_end=we AND x.round_no=round AND x.result=(res-'duplicate')))
   THEN RAISE EXCEPTION 'weekly_payout_original_financial_receipt_required' USING ERRCODE='23514',DETAIL=res::text;END IF;
   IF k='union' THEN
    INSERT INTO public.union_settlement_rounds(union_id,period_start,period_end,round_no,round_name,payers,payees,amount,shortfalls,detail)
    VALUES(id,ws,we,round,CASE round WHEN 1 THEN 'union_to_clubs' WHEN 2 THEN 'club_to_agents' ELSE 'agents_to_players' END,
     CASE WHEN round=1 THEN 1 ELSE 0 END,COALESCE((res->>'payees')::integer,(res->>'clubs_paid')::integer,0),
     COALESCE((res->>'amount')::numeric,(res->>'total_rakeback')::numeric,0),COALESCE((res->>'shortfalls')::integer,0),res)
    ON CONFLICT(union_id,period_start,period_end,round_no)DO NOTHING;
   END IF;
   receipts:=receipts||jsonb_build_array(jsonb_build_object('scope',item,'round',round,'receipt',res));
  END LOOP;
 END LOOP;
 PERFORM public.fn_weekly_accounting_deadline_check();
 IF smarter_private.weekly_payout_clock()>=r.money_deadline_at THEN
  RAISE EXCEPTION 'weekly_payout_absolute_money_deadline' USING ERRCODE='57014';END IF;
 FOR item IN SELECT value FROM jsonb_array_elements(r.scope_plan) LOOP
  INSERT INTO smarter_private.weekly_payout_financial_receipts(scope_kind,scope_id,period_start,period_end,run_id,original_round_receipts)
  VALUES(item->>'kind',(item->>'id')::uuid,(item->>'period_start')::timestamptz,(item->>'period_end')::timestamptz,r.run_id,
   (SELECT jsonb_agg(j ORDER BY (j->>'round')::int) FROM jsonb_array_elements(receipts)j WHERE j->'scope'=item));
 END LOOP;
 DELETE FROM smarter_private.weekly_payout_owned_transactions WHERE backend_pid=pg_backend_pid() AND transaction_id=txid_current();
 PERFORM public.fn_weekly_accounting_attempt_end();
 res:=jsonb_build_object('success',true,'owns_tick',true,'advanced',true,'stage','weekly_payout_financial_complete',
  'run_id',r.run_id,'scheduled_for',r.money_starts_at,'financial_started_at',began,
  'financial_finished_at',smarter_private.weekly_payout_clock(),'books_complete',false,'original_receipts',receipts,
  'attempt_no',r.attempt_no,'deferred_scopes',deferred);
 UPDATE public.weekly_accounting_payout_pauses SET phase='released',result=res WHERE run_id=r.run_id;
 RETURN res;
END $function$

smarter_private.weekly_payout_fund_agent.def:
CREATE OR REPLACE FUNCTION smarter_private.weekly_payout_fund_agent_shortfalls(p_run uuid, p_kind text, p_id uuid, p_from timestamp with time zone, p_to timestamp with time zone)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
AS $function$
DECLARE d_from date:=(p_from AT TIME ZONE 'America/Los_Angeles')::date; s record; res jsonb; out jsonb:='[]'::jsonb; saved text:=current_setting('request.jwt.claims',true); saved_sub text:=current_setting('request.jwt.claim.sub',true);
BEGIN
 FOR s IN
  WITH f AS (SELECT c.club_id, fp.payer_user, fp.owed FROM public.accounting_rakeback_period_calculations c JOIN public.rakeback_periods rp ON rp.id=c.period_id
    CROSS JOIN LATERAL smarter_private.rakeback_certificate_wallets(c.id) fp
    JOIN public.clubs cl ON cl.id=c.club_id
    WHERE rp.period_start=d_from AND rp.status='pending' AND c.payer_kind<>'club'
     AND ((p_kind='union' AND c.coordinator_union_id=p_id) OR (p_kind='club' AND c.club_id=p_id AND c.coordinator_union_id IS NULL))
     AND fp.payer_kind<>'club' AND fp.payer_user IS NOT NULL AND fp.payer_user<>cl.owner_id AND fp.owed>0)
  SELECT f.club_id, f.payer_user, round(sum(f.owed),2) owed, a.agent_wallet_balance bal, cl.owner_id
  FROM f JOIN public.agents a ON a.club_id=f.club_id AND a.user_id=f.payer_user JOIN public.clubs cl ON cl.id=f.club_id
  GROUP BY f.club_id,f.payer_user,a.agent_wallet_balance,cl.owner_id HAVING round(sum(f.owed),2)>a.agent_wallet_balance
 LOOP
  PERFORM set_config('request.jwt.claims',jsonb_build_object('sub',s.owner_id,'role','authenticated')::text,true);
  PERFORM set_config('request.jwt.claim.sub',s.owner_id::text,true);
  res:=public.fn_club_bank_send(s.club_id,s.payer_user,round(s.owed-s.bal,2),'agent_wallet',
    'Weekly rakeback funding: agent wallet short for players (week ending '||to_char(p_to AT TIME ZONE 'America/Chicago','Mon DD')||')',
    md5(p_run::text||':'||s.club_id::text||':'||s.payer_user::text)::uuid);
  IF COALESCE(res->>'success','false')<>'true' THEN RAISE EXCEPTION 'weekly_payout_agent_funding_refused %',res::text; END IF;
  out:=out||jsonb_build_array(jsonb_build_object('club_id',s.club_id,'agent_user_id',s.payer_user,'owed',s.owed,'wallet_before',s.bal,'funded',round(s.owed-s.bal,2)));
 END LOOP;
 PERFORM set_config('request.jwt.claims',COALESCE(saved,''),true);
 PERFORM set_config('request.jwt.claim.sub',COALESCE(saved_sub,''),true);
 RETURN out;
END $function$

smarter_private.weekly_payout_next_round.def:
CREATE OR REPLACE FUNCTION smarter_private.weekly_payout_next_round()
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
AS $function$
DECLARE n timestamptz:=clock_timestamp(); e timestamptz:=public.fn_union_week_start(clock_timestamp()); due timestamptz; plan jsonb; r public.weekly_accounting_payout_pauses%ROWTYPE;
 item jsonb; ready jsonb:='[]'::jsonb; prep jsonb; pending boolean; k text; id uuid; ws timestamptz; we timestamptz; rnd int; res jsonb; funding jsonb; d_from date; cfg smarter_private.weekly_payout_rounds_config%ROWTYPE;
 summary jsonb; att int; admission_at timestamptz; announcement timestamptz;
 budget interval; policy smarter_private.daily_window_policy%ROWTYPE;
BEGIN
 IF NOT public.fn_caller_is_engine() THEN RAISE EXCEPTION 'service_role_required' USING ERRCODE='42501'; END IF;
 SELECT * INTO cfg FROM smarter_private.weekly_payout_rounds_config WHERE singleton;
 IF NOT FOUND OR NOT cfg.enabled THEN RETURN NULL; END IF;
 due:=public.fn_union_accounting_run_at(e);
 IF n<due OR n>=due+interval '24 hours' THEN RETURN NULL; END IF;
 -- Share the original entry/maintenance admission, before any financial lock.
 -- A busy maintenance writer is a definite deferral, never a queued money write.
 IF NOT pg_try_advisory_xact_lock_shared(530090,1) THEN
  RETURN jsonb_build_object('stage','maintenance_busy');
 END IF;
 IF public.fn_entry_purchases_frozen() IS DISTINCT FROM false OR public.fn_platform_frozen() IS DISTINCT FROM false THEN
  RETURN jsonb_build_object('stage','maintenance_frozen');
 END IF;
 -- Preserve the next published announcement's headroom using its maintained
 -- Chicago policy and this invocation's existing finite statement budget.
 admission_at:=clock_timestamp();
 budget:=current_setting('statement_timeout')::interval;
 IF budget<=interval '0' THEN RETURN jsonb_build_object('stage','maintenance_budget_unbounded'); END IF;
 SELECT * INTO STRICT policy FROM smarter_private.daily_window_policy WHERE singleton;
 announcement:=(((admission_at AT TIME ZONE policy.time_zone)::date+policy.last_hand) AT TIME ZONE policy.time_zone);
 IF announcement<=admission_at THEN
  announcement:=((((admission_at AT TIME ZONE policy.time_zone)::date+1)+policy.last_hand) AT TIME ZONE policy.time_zone);
 END IF;
 IF statement_timestamp()+budget<=admission_at OR statement_timestamp()+budget>=announcement THEN
  RETURN jsonb_build_object('stage','maintenance_headroom','announcement_at',announcement);
 END IF;
 IF NOT pg_try_advisory_xact_lock(hashtextextended('weekly-payout-rounds',0)) THEN RETURN jsonb_build_object('stage','rounds_busy'); END IF;
 IF NOT pg_try_advisory_xact_lock(hashtextextended('union-accounting-scheduler',0)) THEN RETURN jsonb_build_object('stage','scheduler_busy'); END IF;
 PERFORM set_config('app.weekly_accounting_chunked','on',true);
 SELECT * INTO r FROM public.weekly_accounting_payout_pauses p WHERE p.period_end=e AND p.instance_id='weekly-payout-rounds' AND p.phase<>'released' ORDER BY p.attempt_no DESC LIMIT 1;
 IF NOT FOUND THEN
  plan:=smarter_private.weekly_payout_scope_plan(e,n);
  IF plan IS NULL OR jsonb_array_length(plan)=0 THEN RETURN NULL; END IF;
  IF EXISTS(SELECT 1 FROM public.weekly_accounting_payout_pauses p WHERE p.period_end=e AND p.phase IN('draining','ready','paying')) THEN RETURN jsonb_build_object('stage','engine_boundary_open'); END IF;
  FOR item IN SELECT value FROM jsonb_array_elements(plan) LOOP
   BEGIN
    PERFORM public.fn_weekly_accounting_attempt_begin(item->>'kind'='union');
    PERFORM set_config('app.weekly_accounting_scope_deadline',(clock_timestamp()+interval '8 minutes')::text,true);
    prep:=public.fn_prepare_accounting_week(CASE WHEN item->>'kind'='union' THEN (item->>'id')::uuid END,CASE WHEN item->>'kind'='club' THEN (item->>'id')::uuid END,(item->>'period_start')::timestamptz,(item->>'period_end')::timestamptz);
    pending:=prep->>'success'='true' AND public.fn_accounting_close_windows_pending(CASE WHEN item->>'kind'='union' THEN (item->>'id')::uuid END,CASE WHEN item->>'kind'='club' THEN (item->>'id')::uuid END,(item->>'period_start')::timestamptz,(item->>'period_end')::timestamptz);
    PERFORM public.fn_weekly_accounting_attempt_end();
    IF prep->>'success'='true' AND NOT pending THEN ready:=ready||jsonb_build_array(item); END IF;
   EXCEPTION WHEN OTHERS THEN NULL;
   END;
  END LOOP;
  IF jsonb_array_length(ready)=0 OR (jsonb_array_length(ready)<jsonb_array_length(plan) AND n<due+interval '45 minutes') THEN
   RETURN jsonb_build_object('stage','rounds_waiting_for_preparation','ready',ready,'owed',plan);
  END IF;
  SELECT COALESCE(max(attempt_no),0)+1 INTO att FROM public.weekly_accounting_payout_pauses WHERE period_end=e;
  INSERT INTO public.weekly_accounting_payout_pauses(period_start,period_end,attempt_no,announced_at,money_starts_at,money_deadline_at,expires_at,scope_plan,phase,acknowledged_at,instance_id,lease_claims)
  VALUES(public.fn_union_prev_week_start(e),e,att,date_trunc('second',n)-interval '2 minutes',date_trunc('second',n),n+interval '20 hours',n+interval '20 hours 1 minute',ready,'ready',n,'weekly-payout-rounds','[]'::jsonb)
  RETURNING * INTO r;
  RETURN jsonb_build_object('stage','rounds_booked','run_id',r.run_id,'scopes',ready);
 END IF;
 -- The next unpaid unit: every scope's round 1, then round 2, then round 3.
 FOR rnd IN 1..3 LOOP
  FOR item IN SELECT value FROM jsonb_array_elements(r.scope_plan) LOOP
   k:=item->>'kind'; id:=(item->>'id')::uuid; ws:=(item->>'period_start')::timestamptz; we:=(item->>'period_end')::timestamptz;
   CONTINUE WHEN EXISTS(SELECT 1 FROM smarter_private.weekly_payout_round_receipts x WHERE x.run_id=r.run_id AND x.scope_kind=k AND x.scope_id=id AND x.round_no=rnd);
   UPDATE public.weekly_accounting_payout_pauses SET phase='paying' WHERE run_id=r.run_id AND phase<>'paying';
   PERFORM public.fn_weekly_accounting_attempt_begin(k='union');
   PERFORM set_config('app.weekly_accounting_scope_deadline',(r.money_deadline_at-interval '2 seconds')::text,true);
   prep:=public.fn_prepare_accounting_week(CASE WHEN k='union' THEN id END,CASE WHEN k='club' THEN id END,ws,we);
   IF prep->>'success' IS DISTINCT FROM 'true' THEN RAISE EXCEPTION 'weekly_payout_round_preparation_changed %',left(prep::text,1000); END IF;
   funding:=NULL;
   IF rnd=3 THEN funding:=smarter_private.weekly_payout_fund_agent_shortfalls(r.run_id,k,id,ws,we); END IF;
   INSERT INTO smarter_private.weekly_payout_owned_transactions(backend_pid,transaction_id,run_id,scope_kind,scope_id,period_start,period_end,round_no)
   VALUES(pg_backend_pid(),txid_current(),r.run_id,k,id,ws,we,rnd)
   ON CONFLICT(backend_pid,transaction_id) DO UPDATE SET run_id=EXCLUDED.run_id,scope_kind=EXCLUDED.scope_kind,scope_id=EXCLUDED.scope_id,period_start=EXCLUDED.period_start,period_end=EXCLUDED.period_end,round_no=EXCLUDED.round_no;
   IF rnd=1 THEN
    PERFORM set_config('app.union_close_defer_rake_debit','',true);
    IF k='union' THEN
     res:=public.fn_union_weekly_rakeback_close(id,ws,we);
     IF res->>'success' IS DISTINCT FROM 'true' AND res->>'error' IS DISTINCT FROM 'already_executed' THEN RAISE EXCEPTION 'weekly_payout_round1_refused %',left(res::text,1000); END IF;
    ELSE
     res:=public.fn_bank_standalone_week_rake(id,ws,we);
     IF res->>'ok' IS DISTINCT FROM 'true' THEN RAISE EXCEPTION 'weekly_payout_club_bank_refused %',left(res::text,1000); END IF;
    END IF;
   ELSIF rnd=2 THEN res:=public.fn_settle_accounting_commission_stage(k,id,ws,we);
   ELSE res:=public.fn_settle_accounting_rakeback_stage(k,id,ws,we);
   END IF;
   IF rnd IN(2,3) AND (res->>'success' IS DISTINCT FROM 'true' OR res->>'routing_version' IS DISTINCT FROM '3' OR res->>'source_version' IS DISTINCT FROM '2'
     OR COALESCE((res->>'shortfalls')::integer,0)<>0 OR res->>'batch_committed'='true'
     OR NOT EXISTS(SELECT FROM public.accounting_routed_settlement_runs x WHERE x.scope_kind=k AND x.scope_id=id AND x.period_start=ws AND x.period_end=we AND x.round_no=rnd AND x.result=(res-'duplicate')))
   THEN RAISE EXCEPTION 'weekly_payout_round_receipt_required %',left(res::text,1000); END IF;
   IF k='union' THEN
    INSERT INTO public.union_settlement_rounds(union_id,period_start,period_end,round_no,round_name,payers,payees,amount,shortfalls,detail)
    VALUES(id,ws,we,rnd,CASE rnd WHEN 1 THEN 'union_to_clubs' WHEN 2 THEN 'club_to_agents' ELSE 'agents_to_players' END,CASE WHEN rnd=1 THEN 1 ELSE 0 END,
     COALESCE((res->>'payees')::integer,(res->>'clubs_paid')::integer,0),COALESCE((res->>'amount')::numeric,(res->>'total_rakeback')::numeric,0),COALESCE((res->>'shortfalls')::integer,0),res)
    ON CONFLICT(union_id,period_start,period_end,round_no) DO NOTHING;
   END IF;
   INSERT INTO smarter_private.weekly_payout_round_receipts(run_id,scope_kind,scope_id,round_no,receipt,funding) VALUES(r.run_id,k,id,rnd,res,funding);
   DELETE FROM smarter_private.weekly_payout_owned_transactions WHERE backend_pid=pg_backend_pid() AND transaction_id=txid_current();
   PERFORM public.fn_weekly_accounting_attempt_end();
   RETURN jsonb_build_object('stage','round_paid','run_id',r.run_id,'scope',item,'round',rnd,'receipt',res,'funding',funding);
  END LOOP;
 END LOOP;
 -- Every round of every scope is paid: finalize once.
 RETURN smarter_private.weekly_payout_finalize(r.run_id);
END $function$

smarter_private.weekly_payout_prepare_du.def:
CREATE OR REPLACE FUNCTION smarter_private.weekly_payout_prepare_due()
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
AS $function$
DECLARE n timestamptz:=smarter_private.weekly_payout_clock();e timestamptz:=public.fn_union_week_start(n);
 due timestamptz:=public.fn_union_accounting_run_at(e);cutover timestamptz;plan jsonb;item jsonb;preparation jsonb;
 problems jsonb:='[]'::jsonb;ready jsonb:='[]'::jsonb;had_windows boolean;began timestamptz:=clock_timestamp();work_deadline timestamptz;saved_preparation_deadline text;r public.weekly_accounting_payout_pauses%ROWTYPE;
 latest public.weekly_accounting_payout_pauses%ROWTYPE;attempt integer:=1;slot timestamptz;final_call boolean;remaining integer;share interval;scope_deadline timestamptz;
 too_large jsonb:='[]'::jsonb;solo boolean:=false;
BEGIN
 IF NOT public.fn_caller_is_engine() THEN RAISE EXCEPTION 'service_role_required' USING ERRCODE='42501';END IF;
 SELECT cutover_period_end INTO STRICT cutover FROM smarter_private.weekly_payout_phase_configuration WHERE singleton;
 IF e<cutover OR n<e THEN RETURN NULL;END IF;
 IF COALESCE(current_setting('app.weekly_accounting_chunked',true),'')<>'on'
  OR current_setting('statement_timeout')::interval IS DISTINCT FROM interval '240 seconds'
 THEN RAISE EXCEPTION 'weekly_payout_original_bounded_tick_required' USING ERRCODE='55000';END IF;
 -- EVERY PREPARED SCOPE IS PAID; THE REST CATCH UP (20261031190020). The newest
 -- owned boundary of this closed week decides the next slot: the original 04:00
 -- slot, then one owned slot per hour for scopes an earlier slot did not pay.
 -- A boundary that is not released waits for its own slot and is never
 -- re-prepared here; weekly_payout_due executes it at its own money start.
 SELECT * INTO latest FROM public.weekly_accounting_payout_pauses p WHERE p.period_end=e ORDER BY p.attempt_no DESC LIMIT 1;
 IF FOUND THEN
  IF latest.phase<>'released' THEN
   RETURN jsonb_build_object('success',false,'owns_tick',true,'advanced',false,'stage','weekly_payout_prepared',
    'run_id',latest.run_id,'attempt_no',latest.attempt_no,'scheduled_for',latest.money_starts_at);
  END IF;
  attempt:=latest.attempt_no+1;
 END IF;
 slot:=due+make_interval(hours=>attempt-1);
 -- A slot needs its two-minute last-hand notice plus one more tick ahead of it.
 WHILE n>slot-interval '3 minutes' LOOP attempt:=attempt+1;slot:=due+make_interval(hours=>attempt-1);END LOOP;
 -- A WHOLE DAY OF CATCH-UP SLOTS (20261102): 24 owned hourly slots, not 8.
 -- More slots only retry scopes still owed; a paid scope is never owed again.
 IF attempt>24 THEN
  -- PRODUCTION ALERTS (20261031210000): every owned slot of this week is spent
  -- while the week still owes scopes. Recorded, never paged; no payer starts.
  IF jsonb_array_length(smarter_private.weekly_payout_scope_plan(e,n))>0 THEN
   BEGIN
    PERFORM public.fn_record_operational_alert('weekly-payout','unpaid-after-last-slot:'||e::text,'WeeklyPayoutUnpaidAfterLastSlot','firing','critical',
     jsonb_build_object('target_task_id','01a09b86-5ba8-7290-8657-1041f13dd3ca','period_end',e,'owed',smarter_private.weekly_payout_scope_plan(e,n),'observed_at',n));
   EXCEPTION WHEN OTHERS THEN NULL;
   END;
  END IF;
  RETURN NULL;
 END IF;
 plan:=smarter_private.weekly_payout_scope_plan(e,n);
 IF jsonb_array_length(plan)=0 THEN RETURN NULL;END IF;
 -- MEASURED MONEY ADMISSION (20261031223940): an owned slot pays all of its
 -- scopes inside ONE bounded 240-second money statement. Admission is by what
 -- this week's own money statements measured, never by size: (a) after a slot
 -- whose money statement was lost (its cron run started inside the money
 -- window and did not succeed: timeout, crash or restart), every later slot of
 -- this week owns ONE scope, standalone clubs first, so a scope whose money
 -- does not fit can never hold another unpaid; (b) a scope whose OWN solo
 -- money statement was lost this week gets no further slot and is recorded
 -- once for Production Alerts (never paged). It stays owed; nothing is paid
 -- twice: every lost statement rolled back whole, receipts are exactly-once.
 SELECT COALESCE(jsonb_agg(x.value),'[]'::jsonb) INTO too_large FROM jsonb_array_elements(plan) x
  WHERE EXISTS(SELECT FROM smarter_private.weekly_payout_money_losses l WHERE l.period_end=e
   AND l.scope_kind=x.value->>'kind' AND l.scope_id=(x.value->>'id')::uuid);
 IF jsonb_array_length(too_large)>0 THEN
  BEGIN
   PERFORM public.fn_record_operational_alert('weekly-payout','money-statement-lost:'||e::text,'WeeklyPayoutScopeMoneyStatementLost','firing','critical',
    jsonb_build_object('target_task_id','01a09b86-5ba8-7290-8657-1041f13dd3ca','period_end',e,'scopes',too_large,
     'losses',(SELECT jsonb_agg(to_jsonb(l)) FROM smarter_private.weekly_payout_money_losses l WHERE l.period_end=e),'observed_at',n));
  EXCEPTION WHEN OTHERS THEN NULL;
  END;
  SELECT COALESCE(jsonb_agg(x.j ORDER BY x.o),'[]'::jsonb) INTO plan FROM jsonb_array_elements(plan) WITH ORDINALITY x(j,o)
   WHERE NOT x.j IN (SELECT t.value FROM jsonb_array_elements(too_large) t);
  IF jsonb_array_length(plan)=0 THEN RETURN NULL;END IF;
 END IF;
 solo:=EXISTS(SELECT FROM public.weekly_accounting_payout_pauses p WHERE p.period_end=e AND p.phase='released' AND p.result->>'money_lost'='true');
 -- The last preparation ticks before a slot own it with the scopes that are
 -- ready; a scope still preparing is deferred to the next slot, never allowed
 -- to keep every other scope unpaid.
 final_call:=n>=slot-interval '10 minutes';
 remaining:=jsonb_array_length(plan);
 -- Standalone club books before union books, each with a fair share of this
 -- tick, so one large union cannot spend the whole tick of every scope.
 FOR item IN SELECT j FROM jsonb_array_elements(plan) WITH ORDINALITY x(j,o) ORDER BY (j->>'kind'='union'),o LOOP
  IF clock_timestamp()-began>interval '150 seconds' THEN
   problems:=problems||jsonb_build_array(jsonb_build_object('reason','preparation_budget','scope',item));
   remaining:=remaining-1;CONTINUE;
  END IF;
  PERFORM public.fn_weekly_accounting_attempt_begin(item->>'kind'='union');
  share:=GREATEST(interval '30 seconds',((began+interval '150 seconds')-clock_timestamp())/GREATEST(remaining,1));
  scope_deadline:=LEAST(NULLIF(current_setting('app.weekly_accounting_scope_deadline',true),'')::timestamptz,clock_timestamp()+share);
  PERFORM set_config('app.weekly_accounting_scope_deadline',scope_deadline::text,true);
  -- The original window provers stop at deadline-budget+120s (and never past
  -- the statement's own start+timeout-60s): this scope's budget is its share.
  PERFORM set_config('app.weekly_accounting_scope_budget',share::text,true);
  BEGIN
   -- Continue only this original R0 transition while its immutable source
   -- reviews prove positive progress. No other failure/result is retried.
   work_deadline:=LEAST(scope_deadline,slot-interval '3 minutes');
   saved_preparation_deadline:=current_setting('app.weekly_accounting_preparation_deadline',true);
   PERFORM set_config('app.weekly_accounting_preparation_deadline',work_deadline::text,true);
   LOOP
   preparation:=public.fn_prepare_accounting_week(CASE WHEN item->>'kind'='union' THEN (item->>'id')::uuid END,
    CASE WHEN item->>'kind'='club' THEN (item->>'id')::uuid END,(item->>'period_start')::timestamptz,(item->>'period_end')::timestamptz);
    EXIT WHEN NOT(coalesce(jsonb_array_length(preparation->'problems'),0)=1
      AND preparation#>>'{problems,0,reason}'='own_agent_source_interpretation_in_progress'
      AND coalesce((preparation#>>'{problems,0,source_check,reviewed}')::int,0)>0);
    EXIT WHEN preparation#>>'{problems,0,source_check,budget_exhausted}'='true'OR clock_timestamp()>=work_deadline;
   END LOOP;
   PERFORM set_config('app.weekly_accounting_preparation_deadline',coalesce(saved_preparation_deadline,''),true);
   had_windows:=false;
   IF preparation->>'success'='true' THEN
    had_windows:=public.fn_accounting_close_windows_pending(CASE WHEN item->>'kind'='union' THEN (item->>'id')::uuid END,
     CASE WHEN item->>'kind'='club' THEN (item->>'id')::uuid END,(item->>'period_start')::timestamptz,(item->>'period_end')::timestamptz);
   END IF;
   IF preparation->>'success' IS DISTINCT FROM 'true' OR had_windows THEN
    problems:=problems||jsonb_build_array(jsonb_build_object('scope',item,'preparation',preparation,'windows_pending',had_windows));
   ELSE
    ready:=ready||jsonb_build_array(item);
   END IF;
  EXCEPTION WHEN OTHERS THEN
   PERFORM set_config('app.weekly_accounting_preparation_deadline',coalesce(saved_preparation_deadline,''),true);
   problems:=problems||jsonb_build_array(jsonb_build_object('scope',item,'error',SQLERRM,'sqlstate',SQLSTATE));
  END;
  PERFORM public.fn_weekly_accounting_attempt_end();
  remaining:=remaining-1;
 END LOOP;
 -- After a lost money statement this week, one ready scope owns the slot.
 IF solo AND jsonb_array_length(ready)>1 THEN
  problems:=problems||COALESCE((SELECT jsonb_agg(jsonb_build_object('scope',x.j,'reason','one_scope_per_slot_after_lost_money_statement') ORDER BY (x.j->>'kind'='union'),x.o)
   FROM jsonb_array_elements(plan) WITH ORDINALITY x(j,o) WHERE x.j IN (SELECT value FROM jsonb_array_elements(ready))
    AND x.j IS DISTINCT FROM (SELECT y.j FROM jsonb_array_elements(plan) WITH ORDINALITY y(j,o) WHERE y.j IN (SELECT value FROM jsonb_array_elements(ready)) ORDER BY (y.j->>'kind'='union'),y.o LIMIT 1)),'[]'::jsonb);
  SELECT jsonb_build_array(y.j) INTO ready FROM jsonb_array_elements(plan) WITH ORDINALITY y(j,o)
   WHERE y.j IN (SELECT value FROM jsonb_array_elements(ready)) ORDER BY (y.j->>'kind'='union'),y.o LIMIT 1;
 END IF;
 IF jsonb_array_length(problems)>0 AND NOT((final_call OR solo) AND jsonb_array_length(ready)>0) THEN
  RETURN jsonb_build_object('success',false,'owns_tick',true,'advanced',true,'stage','weekly_payout_preparing',
   'attempt_no',attempt,'scheduled_for',slot,'ready_scopes',jsonb_array_length(ready),'problems',problems);
 END IF;
 -- ROUND RUNNER BOOKS ITS OWN BOUNDARY (owner, 2026-11-02): preparation is
 -- complete here; weekly_payout_next_round pays it round by round.
 IF EXISTS(SELECT FROM smarter_private.weekly_payout_rounds_config c WHERE c.singleton AND c.enabled) THEN
  RETURN jsonb_build_object('success',true,'owns_tick',true,'advanced',false,'stage','weekly_payout_ready_for_rounds','ready_scopes',ready,'problems',problems);
 END IF;
 -- The boundary keeps the original plan order of the scopes it pays.
 SELECT jsonb_agg(j ORDER BY o) INTO ready FROM jsonb_array_elements(plan) WITH ORDINALITY x(j,o) WHERE j IN (SELECT value FROM jsonb_array_elements(ready));
 INSERT INTO public.weekly_accounting_payout_pauses(period_start,period_end,attempt_no,announced_at,money_starts_at,money_deadline_at,expires_at,scope_plan)
 VALUES(public.fn_union_prev_week_start(e),e,attempt,slot-interval '2 minutes',slot,slot+interval '240 seconds',slot+interval '5 minutes',ready)
 ON CONFLICT(period_start,period_end,attempt_no)DO NOTHING;
 SELECT * INTO STRICT r FROM public.weekly_accounting_payout_pauses p WHERE p.period_end=e AND p.attempt_no=attempt;
 IF r.scope_plan IS DISTINCT FROM ready THEN RAISE EXCEPTION 'weekly_payout_prepared_scope_changed' USING ERRCODE='55000';END IF;
 IF jsonb_array_length(problems)>0 THEN
  BEGIN
   PERFORM public.fn_record_operational_alert('weekly-payout','deferred-at-preparation:'||r.run_id::text,'WeeklyPayoutScopeDeferred','firing','warning',
    jsonb_build_object('target_task_id','01a09b86-5ba8-7290-8657-1041f13dd3ca','period_start',r.period_start,'period_end',r.period_end,'attempt_no',attempt,'scheduled_for',slot,'deferred_scopes',problems,
     'next','still-preparing scopes are prepared for the next owned hourly slot'));
  EXCEPTION WHEN OTHERS THEN NULL;
  END;
 END IF;
 RETURN jsonb_build_object('success',false,'owns_tick',true,'advanced',true,'stage','weekly_payout_prepared','run_id',r.run_id,
  'attempt_no',attempt,'scheduled_for',slot,'deferred_scopes',problems);
END $function$

smarter_private.weekly_payout_readiness_.def:
CREATE OR REPLACE FUNCTION smarter_private.weekly_payout_readiness_check()
 RETURNS jsonb
 LANGUAGE plpgsql
 SET search_path TO 'pg_catalog', 'public'
AS $function$
DECLARE n timestamptz:=clock_timestamp(); e timestamptz:=public.fn_union_week_start(clock_timestamp()); due timestamptz; plan jsonb; missing jsonb; nw int; ok boolean;
BEGIN
 due:=public.fn_union_accounting_run_at(e);
 IF n<due-interval '30 minutes' OR n>=due-interval '25 minutes' THEN RETURN NULL; END IF;
 plan:=smarter_private.weekly_payout_scope_plan(e,n);
 IF plan IS NULL OR jsonb_array_length(plan)=0 THEN RETURN NULL; END IF;
 SELECT count(*) INTO nw FROM public.fn_accounting_close_windows(public.fn_union_prev_week_start(e),e);
 SELECT jsonb_agg(jsonb_build_object('scope',x,
   'own_agent_windows_clean',(SELECT count(*) FROM smarter_private.own_agent_clean_windows k WHERE k.scope_kind=x->>'kind' AND k.scope_id=(x->>'id')::uuid AND k.period_end=e),
   'round2_windows',(SELECT count(*) FROM public.accounting_close_partials p WHERE p.kind='round2_'||(x->>'kind')||'_window' AND p.union_id=(x->>'id')::uuid AND p.period_end=e AND p.computed_at>=e),
   'round3_windows',(SELECT count(*) FROM public.accounting_close_partials p WHERE p.kind='round3_'||(x->>'kind')||'_window' AND p.union_id=(x->>'id')::uuid AND p.period_end=e AND p.computed_at>=e),
   'calculations_not_complete',(SELECT count(*) FROM public.fn_accounting_week_clubs(CASE WHEN x->>'kind'='union' THEN (x->>'id')::uuid END,CASE WHEN x->>'kind'='club' THEN (x->>'id')::uuid END,(x->>'period_start')::timestamptz,(x->>'period_end')::timestamptz) c
     WHERE NOT EXISTS(SELECT 1 FROM public.accounting_period_recompute_requests q WHERE q.club_id=c.club_id AND q.period_start=((x->>'period_start')::timestamptz AT TIME ZONE 'America/Los_Angeles')::date AND q.status='complete' AND q.attempted_at>=e))))
 INTO missing FROM jsonb_array_elements(plan) x;
 SELECT bool_and((m->>'own_agent_windows_clean')::int>=nw AND (m->>'round2_windows')::int>=nw AND (m->>'round3_windows')::int>=nw AND (m->>'calculations_not_complete')::int=0) INTO ok FROM jsonb_array_elements(missing) m;
 IF ok THEN RETURN jsonb_build_object('ready',true,'scopes',missing); END IF;
 BEGIN
  PERFORM public.fn_record_operational_alert('weekly-payout','not-ready-at-0330:'||e::text,'WeeklyPayoutNotReadyHalfHourBefore','firing','critical',
   jsonb_build_object('target_task_id','01a09b86-5ba8-7290-8657-1041f13dd3ca','period_end',e,'due',due,'windows',nw,'scopes',missing,'observed_at',n));
 EXCEPTION WHEN OTHERS THEN NULL;
 END;
 RETURN jsonb_build_object('ready',false,'windows',nw,'scopes',missing);
END $function$

smarter_private.weekly_payout_scope_plan.def:
CREATE OR REPLACE FUNCTION smarter_private.weekly_payout_scope_plan(p_end timestamp with time zone, p_now timestamp with time zone)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
AS $function$
DECLARE c timestamptz;sc record;ws timestamptz;we timestamptz;result jsonb:='[]'::jsonb;
BEGIN
 SELECT cutover_period_end INTO STRICT c FROM smarter_private.weekly_payout_phase_configuration WHERE singleton;
 FOR sc IN SELECT * FROM smarter_private.weekly_payout_eligible_scopes(p_end,p_now) LOOP
  ws:=GREATEST(sc.first_week,public.fn_union_prev_week_start(c));
  IF ws IS NULL OR NOT isfinite(ws) OR ws<>public.fn_union_week_start(ws)
  THEN RAISE EXCEPTION 'weekly_payout_scope_calendar_unproven' USING ERRCODE='55000';END IF;
  WHILE ws<p_end LOOP
   we:=public.fn_union_week_start(ws+interval '8 days');
   IF we>p_end OR we<=ws THEN RAISE EXCEPTION 'weekly_payout_scope_calendar_invalid';END IF;
   IF NOT EXISTS(SELECT FROM smarter_private.weekly_payout_financial_receipts r
    WHERE r.scope_kind=sc.kind AND r.scope_id=sc.id AND r.period_start=ws AND r.period_end=we)
    AND NOT EXISTS(SELECT FROM public.union_accounting_runs q
     WHERE q.scope_kind=sc.kind AND q.scope_id=sc.id AND q.period_start=ws AND q.period_end=we
      AND q.status='complete' AND q.result->>'success'='true' AND q.result->>'accounting_version'='3') THEN
    result:=result||jsonb_build_array(jsonb_build_object('kind',sc.kind,'id',sc.id,'period_start',ws,'period_end',we));
   END IF;
   ws:=we;
  END LOOP;
 END LOOP;
 RETURN (SELECT COALESCE(jsonb_agg(j ORDER BY (j->>'kind'='union') DESC,(j->>'period_start')::timestamptz,j->>'id'),'[]'::jsonb)FROM jsonb_array_elements(result)j);
END $function$

smarter_private.weekly_prep_shard(IN p_s.def:
CREATE OR REPLACE PROCEDURE smarter_private.weekly_prep_shard(IN p_shard integer, IN p_shards integer)
 LANGUAGE plpgsql
AS $procedure$
DECLARE n timestamptz:=clock_timestamp(); e timestamptz; due timestamptz; plan jsonb; item jsonb; k text; id uuid; ps timestamptz; pe timestamptz;
 began timestamptz:=clock_timestamp(); run_id bigint; units int:=0; lbl text; c uuid; i int; nw int; step text; did boolean; d_from date; npages int;
BEGIN
 IF p_shards<1 OR p_shard<0 OR p_shard>=p_shards THEN RAISE EXCEPTION 'weekly_prep_shard_invalid'; END IF;
 e:=public.fn_union_week_start(n); due:=public.fn_union_accounting_run_at(e);
 -- Only between the week's close and twelve hours after its payout time.
 IF n<e OR n>=due+interval '12 hours' THEN RETURN; END IF;
 IF EXISTS(SELECT 1 FROM public.weekly_accounting_payout_pauses p WHERE p.period_end=e AND p.phase IN('draining','ready','paying')) THEN RETURN; END IF;
 plan:=smarter_private.weekly_payout_scope_plan(e,n);
 IF plan IS NULL OR jsonb_array_length(plan)=0 THEN RETURN; END IF;
 INSERT INTO smarter_private.weekly_prep_shard_runs(shard,period_end) VALUES(p_shard,e) RETURNING smarter_private.weekly_prep_shard_runs.id INTO run_id;
 COMMIT;
 -- Scope club lists, resolved once under the coordinator's own key (shard 0).
 IF p_shard=0 THEN
  FOR item IN SELECT value FROM jsonb_array_elements(plan) LOOP
   k:=item->>'kind'; id:=(item->>'id')::uuid; ps:=(item->>'period_start')::timestamptz; pe:=(item->>'period_end')::timestamptz;
   IF NOT EXISTS(SELECT 1 FROM smarter_private.weekly_prep_scope_clubs q WHERE q.scope_kind=k AND q.scope_id=id AND q.period_start=ps AND q.period_end=pe) THEN
    BEGIN
     SET LOCAL lock_timeout='3s';
     INSERT INTO smarter_private.weekly_prep_scope_clubs(scope_kind,scope_id,period_start,period_end,club_ids)
     SELECT k,id,ps,pe,r.club_ids FROM public.fn_resolve_accounting_routing_scope(k,id,ps,pe) r ON CONFLICT DO NOTHING;
    EXCEPTION WHEN lock_not_available THEN NULL;
    END;
    COMMIT;
   END IF;
  END LOOP;
 END IF;
 -- Stage order: own-agent markers, earned plan, calculator parts, round windows.
 FOREACH step IN ARRAY ARRAY['clean','earned','players','tq','counts','check','write','r2','r3'] LOOP
  FOR item IN SELECT value FROM jsonb_array_elements(plan) LOOP
   k:=item->>'kind'; id:=(item->>'id')::uuid; ps:=(item->>'period_start')::timestamptz; pe:=(item->>'period_end')::timestamptz;
   IF step='earned' AND k<>'union' THEN CONTINUE; END IF;
   IF step IN('clean','earned','r2','r3') THEN
    SELECT count(*) INTO nw FROM public.fn_accounting_close_windows(ps,pe);
    FOR i IN 0..nw-1 LOOP
     CONTINUE WHEN i%p_shards<>p_shard;
     IF clock_timestamp()>began+interval '45 seconds' THEN EXIT; END IF;
     BEGIN
      lbl:=smarter_private.weekly_prep_unit(k,id,ps,pe,step,NULL,i);
     EXCEPTION WHEN OTHERS THEN
      UPDATE smarter_private.weekly_prep_shard_runs SET last_error=left(step||' '||i||': '||SQLERRM,500) WHERE smarter_private.weekly_prep_shard_runs.id=run_id; lbl:=NULL;
     END;
     IF lbl IS NOT NULL THEN units:=units+1; UPDATE smarter_private.weekly_prep_shard_runs SET units=units+1,last_unit=lbl WHERE smarter_private.weekly_prep_shard_runs.id=run_id; END IF;
     COMMIT;
    END LOOP;
   ELSE
    FOR c IN SELECT w.club_id FROM public.fn_accounting_week_clubs(CASE WHEN k='union' THEN id END,CASE WHEN k='club' THEN id END,ps,pe) w ORDER BY w.club_id LOOP
     d_from:=(ps AT TIME ZONE 'America/Los_Angeles')::date;
     nw:=CASE step WHEN 'players' THEN 1 WHEN 'tq' THEN 29 WHEN 'counts' THEN 86 ELSE
       COALESCE((SELECT jsonb_array_length(value->'pages') FROM public.accounting_recompute_split_parts WHERE club_id=c AND period_start=d_from AND kind='players' AND part=0),0) END;
     FOR i IN 0..nw-1 LOOP
      CONTINUE WHEN (i+abs(hashtext(c::text)))%p_shards<>p_shard;
      IF clock_timestamp()>began+interval '45 seconds' THEN EXIT; END IF;
      BEGIN
       lbl:=smarter_private.weekly_prep_unit(k,id,ps,pe,step,c,i);
      EXCEPTION WHEN OTHERS THEN
       UPDATE smarter_private.weekly_prep_shard_runs SET last_error=left(step||' '||c||' '||i||': '||SQLERRM,500) WHERE smarter_private.weekly_prep_shard_runs.id=run_id; lbl:=NULL;
      END;
      IF lbl IS NOT NULL THEN units:=units+1; UPDATE smarter_private.weekly_prep_shard_runs SET units=units+1,last_unit=lbl WHERE smarter_private.weekly_prep_shard_runs.id=run_id; END IF;
      COMMIT;
     END LOOP;
    END LOOP;
   END IF;
  END LOOP;
  EXIT WHEN clock_timestamp()>began+interval '45 seconds';
 END LOOP;
 UPDATE smarter_private.weekly_prep_shard_runs SET finished_at=clock_timestamp() WHERE smarter_private.weekly_prep_shard_runs.id=run_id;
 COMMIT;
END $procedure$

smarter_private.weekly_prep_unit(p_kind.def:
CREATE OR REPLACE FUNCTION smarter_private.weekly_prep_unit(p_kind text, p_scope uuid, p_from timestamp with time zone, p_to timestamp with time zone, p_step text, p_club uuid, p_idx integer)
 RETURNS text
 LANGUAGE plpgsql
 SET search_path TO 'pg_catalog', 'public'
AS $function$
DECLARE w record; sc record; r record; v jsonb; d_from date; d_to date; v_from timestamptz; v_to timestamptz;
 pages jsonb; n_pages int; ids uuid[]; ev bigint; inc bigint; dr bigint; issue_count bigint; life interval:=public.fn_accounting_close_proof_lifetime();
 club_ids uuid[]; u uuid; s uuid;
BEGIN
 u:=CASE WHEN p_kind='union' THEN p_scope END; s:=CASE WHEN p_kind='club' THEN p_scope END;
 IF p_step IN('clean','earned','r2','r3') THEN
  SELECT c.window_start,c.window_end INTO w FROM public.fn_accounting_close_windows(p_from,p_to) c ORDER BY c.window_start OFFSET p_idx LIMIT 1;
  IF NOT FOUND THEN RETURN NULL; END IF;
 END IF;
 IF p_step='clean' THEN
  IF EXISTS(SELECT 1 FROM smarter_private.own_agent_clean_windows k WHERE k.scope_kind=p_kind AND k.scope_id=p_scope AND k.period_start=p_from AND k.period_end=p_to AND k.window_start=w.window_start) THEN RETURN NULL; END IF;
  INSERT INTO smarter_private.own_agent_clean_windows(scope_kind,scope_id,period_start,period_end,window_start,checked_at)
  SELECT p_kind,p_scope,p_from,p_to,w.window_start,statement_timestamp()
  WHERE NOT EXISTS(SELECT 1 FROM public.accounting_cash_rake_sources x WHERE x.earned_at>=w.window_start AND x.earned_at<w.window_end
    AND ((u IS NOT NULL AND x.coordinator_union_id=u) OR (s IS NOT NULL AND x.club_id=s AND x.coordinator_union_id IS NULL))
    AND coalesce(x.contract#>>'{membership,terms,role}','') IN('super_agent','agent','sub_agent') AND x.contract#>>'{tiers,0,user_id}' IS DISTINCT FROM x.player_id::text
    AND NOT(coalesce((x.contract#>>'{membership,terms,player_rakeback_pct}')::numeric=.70,false) AND EXISTS(SELECT FROM public.clubs c WHERE c.id=x.club_id AND c.owner_id=NULLIF(x.contract#>>'{membership,terms,agent_id}','')::uuid))
    AND NOT EXISTS(SELECT FROM public.accounting_own_agent_source_reviews a WHERE a.source_type='cash_rake_accrual' AND a.source_id=x.id))
   AND NOT EXISTS(SELECT 1 FROM public.accounting_payable_earning_sources x WHERE x.source_type='tournament_fee_accrual' AND x.earned_at>=w.window_start AND x.earned_at<w.window_end
    AND ((u IS NOT NULL AND x.coordinator_union_id=u) OR (s IS NOT NULL AND x.club_id=s AND x.coordinator_union_id IS NULL))
    AND coalesce(x.contract#>>'{membership,terms,role}','') IN('super_agent','agent','sub_agent') AND x.contract#>>'{tiers,0,user_id}' IS DISTINCT FROM x.player_id::text
    AND NOT EXISTS(SELECT FROM public.accounting_own_agent_source_reviews a WHERE a.source_type=x.source_type AND a.source_id=x.source_id))
  ON CONFLICT DO NOTHING;
  RETURN 'clean '||p_idx;
 END IF;
 IF p_step IN('earned','r2','r3') THEN
  IF EXISTS(SELECT 1 FROM public.accounting_close_partials p WHERE p.kind=CASE p_step WHEN 'earned' THEN 'earned_plan_window' WHEN 'r2' THEN 'round2_'||p_kind||'_window' ELSE 'round3_'||p_kind||'_window' END
    AND p.union_id=p_scope AND p.period_start=p_from AND p.period_end=p_to AND p.window_start=w.window_start AND p.window_end=w.window_end
    AND p.computed_at>=p_to AND p.computed_at>clock_timestamp()-life) THEN RETURN NULL; END IF;
  IF p_step='earned' THEN
   SELECT * INTO r FROM public.fn_accounting_union_earned_plan_window(p_scope,w.window_start,w.window_end);
   IF NOT FOUND THEN RETURN 'earned-unproved '||p_idx; END IF;
   INSERT INTO public.accounting_close_partials(kind,union_id,period_start,period_end,window_start,window_end,value,cash_ids,cash_md5,fee_ids,fee_md5,computed_at)
   VALUES('earned_plan_window',p_scope,p_from,p_to,w.window_start,w.window_end,r.value,r.cash_ids,r.cash_md5,r.fee_ids,r.fee_md5,clock_timestamp())
   ON CONFLICT(kind,union_id,period_start,period_end,window_start) DO UPDATE SET window_end=EXCLUDED.window_end,value=EXCLUDED.value,cash_ids=EXCLUDED.cash_ids,cash_md5=EXCLUDED.cash_md5,fee_ids=EXCLUDED.fee_ids,fee_md5=EXCLUDED.fee_md5,computed_at=EXCLUDED.computed_at;
  ELSIF p_step='r2' THEN
   IF EXISTS(SELECT 1 FROM public.accounting_routed_settlement_runs x WHERE x.scope_kind=p_kind AND x.scope_id=p_scope AND x.period_start=p_from AND x.period_end=p_to AND x.round_no=2) THEN RETURN NULL; END IF;
   SELECT q.club_ids INTO club_ids FROM smarter_private.weekly_prep_scope_clubs q WHERE q.scope_kind=p_kind AND q.scope_id=p_scope AND q.period_start=p_from AND q.period_end=p_to;
   IF club_ids IS NULL THEN RETURN NULL; END IF;
   SELECT * INTO r FROM public.fn_settle_accounting_commission_window(u,s,club_ids,w.window_start,w.window_end);
   INSERT INTO public.accounting_close_partials(kind,union_id,period_start,period_end,window_start,window_end,value,cash_ids,cash_md5,fee_ids,fee_md5,computed_at)
   VALUES('round2_'||p_kind||'_window',p_scope,p_from,p_to,w.window_start,w.window_end,r.value,r.cash_ids,r.cash_md5,r.fee_ids,r.fee_md5,clock_timestamp())
   ON CONFLICT(kind,union_id,period_start,period_end,window_start) DO UPDATE SET window_end=EXCLUDED.window_end,value=EXCLUDED.value,cash_ids=EXCLUDED.cash_ids,cash_md5=EXCLUDED.cash_md5,fee_ids=EXCLUDED.fee_ids,fee_md5=EXCLUDED.fee_md5,computed_at=EXCLUDED.computed_at;
  ELSE
   IF EXISTS(SELECT 1 FROM public.accounting_routed_settlement_runs x WHERE x.scope_kind=p_kind AND x.scope_id=p_scope AND x.period_start=p_from AND x.period_end=p_to AND x.round_no=3) THEN RETURN NULL; END IF;
   INSERT INTO public.accounting_close_partials(kind,union_id,period_start,period_end,window_start,window_end,value,computed_at)
   VALUES('round3_'||p_kind||'_window',p_scope,p_from,p_to,w.window_start,w.window_end,public.fn_settle_accounting_rakeback_window(u,s,w.window_start,w.window_end),clock_timestamp())
   ON CONFLICT(kind,union_id,period_start,period_end,window_start) DO UPDATE SET window_end=EXCLUDED.window_end,value=EXCLUDED.value,cash_ids=NULL,cash_md5=NULL,fee_ids=NULL,fee_md5=NULL,computed_at=EXCLUDED.computed_at;
  END IF;
  RETURN p_step||' '||p_idx;
 END IF;
 -- Split recompute parts of one club-week (the calculator's own parts).
 d_from:=(p_from AT TIME ZONE 'America/Los_Angeles')::date; d_to:=d_from+6;
 v_from:=d_from::timestamp AT TIME ZONE 'America/Los_Angeles'; v_to:=(d_to+1)::timestamp AT TIME ZONE 'America/Los_Angeles';
 IF v_to>clock_timestamp() THEN RETURN NULL; END IF;
 IF EXISTS(SELECT 1 FROM public.accounting_period_recompute_requests q WHERE q.club_id=p_club AND q.period_start=d_from AND q.period_end=d_to AND q.status='complete'
   AND q.attempted_at>=v_to AND q.last_requested_at<=q.attempted_at AND q.last_result->>'status'='ready') THEN RETURN NULL; END IF;
 IF p_step='players' THEN
  IF EXISTS(SELECT 1 FROM public.accounting_recompute_split_parts WHERE club_id=p_club AND period_start=d_from AND kind='players') THEN RETURN NULL; END IF;
  WITH p AS (SELECT x.player_id,count(*) AS n FROM public.accounting_payable_earning_sources x WHERE x.club_id=p_club AND x.earned_at>=v_from AND x.earned_at<v_to GROUP BY x.player_id),
  q AS (SELECT p.player_id,((sum(p.n) OVER(ORDER BY p.player_id)-p.n)/20000)::bigint AS pg FROM p)
  SELECT COALESCE(jsonb_agg(x.ids ORDER BY x.pg),'[]'::jsonb) INTO pages FROM (SELECT q.pg,jsonb_agg(q.player_id ORDER BY q.player_id) AS ids FROM q GROUP BY q.pg) x;
  INSERT INTO public.accounting_recompute_split_parts(club_id,period_start,period_end,kind,part,value) VALUES(p_club,d_from,d_to,'players',0,jsonb_build_object('pages',pages)) ON CONFLICT DO NOTHING;
  RETURN 'players';
 END IF;
 IF p_step='tq' THEN
  SELECT g INTO w FROM (SELECT (row_number() OVER(ORDER BY g)-1)::int AS i,g FROM generate_series(v_from,v_to-interval '1 microsecond',interval '6 hours') g) t WHERE t.i=p_idx;
  IF NOT FOUND OR EXISTS(SELECT 1 FROM public.accounting_recompute_split_parts WHERE club_id=p_club AND period_start=d_from AND kind='tq' AND part=p_idx) THEN RETURN NULL; END IF;
  INSERT INTO public.accounting_recompute_split_parts(club_id,period_start,period_end,kind,part,value)
  VALUES(p_club,d_from,d_to,'tq',p_idx,public.fn_accounting_tournament_week_quality(p_club,w.g,LEAST(w.g+interval '6 hours',v_to))) ON CONFLICT DO NOTHING;
  RETURN 'tq '||p_idx;
 END IF;
 IF p_step='counts' THEN
  SELECT g INTO w FROM (SELECT (row_number() OVER(ORDER BY g)-1)::int AS i,g FROM generate_series(v_from,v_to-interval '1 microsecond',interval '2 hours') g) t WHERE t.i=p_idx;
  IF NOT FOUND OR EXISTS(SELECT 1 FROM public.accounting_recompute_split_parts WHERE club_id=p_club AND period_start=d_from AND kind='counts' AND part=p_idx) THEN RETURN NULL; END IF;
  INSERT INTO public.accounting_recompute_split_parts(club_id,period_start,period_end,kind,part,value)
  VALUES(p_club,d_from,d_to,'counts',p_idx,public.fn_rakeback_split_counts(p_club,v_from,v_to,w.g,LEAST(w.g+interval '2 hours',v_to))) ON CONFLICT DO NOTHING;
  RETURN 'counts '||p_idx;
 END IF;
 -- check/write pages follow the calculator's own gates in its order.
 SELECT value->'pages' INTO pages FROM public.accounting_recompute_split_parts WHERE club_id=p_club AND period_start=d_from AND kind='players' AND part=0;
 IF pages IS NULL THEN RETURN NULL; END IF;
 n_pages:=jsonb_array_length(pages);
 IF p_idx>=n_pages THEN RETURN NULL; END IF;
 IF (SELECT count(*) FROM public.accounting_recompute_split_parts WHERE club_id=p_club AND period_start=d_from AND kind='tq')<>(SELECT count(*) FROM generate_series(v_from,v_to-interval '1 microsecond',interval '6 hours'))
  OR (SELECT count(*) FROM public.accounting_recompute_split_parts WHERE club_id=p_club AND period_start=d_from AND kind='counts')<>(SELECT count(*) FROM generate_series(v_from,v_to-interval '1 microsecond',interval '2 hours'))
  OR EXISTS(SELECT 1 FROM public.accounting_recompute_split_parts WHERE club_id=p_club AND period_start=d_from AND kind='tq' AND value->>'status' IS DISTINCT FROM 'ready') THEN RETURN NULL; END IF;
 SELECT sum((value->>'evidence')::bigint),sum((value->>'incomplete')::bigint),sum((value->>'drifted')::bigint) INTO ev,inc,dr FROM public.accounting_recompute_split_parts WHERE club_id=p_club AND period_start=d_from AND kind='counts';
 SELECT count(*) INTO issue_count FROM public.rakeback_periods rp WHERE rp.club_id=p_club AND rp.period_start<=d_to AND rp.period_end>=d_from
   AND (rp.status<>'pending' OR rp.period_start<>d_from OR rp.period_end<>d_to OR NOT EXISTS(SELECT 1 FROM public.accounting_rakeback_period_calculations c WHERE c.period_id=rp.id));
 IF ev>0 OR inc>0 OR dr>0 OR issue_count>0 THEN RETURN NULL; END IF;
 ids:=ARRAY(SELECT jsonb_array_elements_text(pages->p_idx)::uuid);
 IF p_step='check' THEN
  IF EXISTS(SELECT 1 FROM public.accounting_recompute_split_parts WHERE club_id=p_club AND period_start=d_from AND kind='check' AND part=p_idx) THEN RETURN NULL; END IF;
  INSERT INTO public.accounting_recompute_split_parts(club_id,period_start,period_end,kind,part,value)
  VALUES(p_club,d_from,d_to,'check',p_idx,public.fn_rakeback_split_check(p_club,d_from,d_to,ids)) ON CONFLICT DO NOTHING;
  RETURN 'check '||p_idx;
 END IF;
 IF p_step='write' THEN
  IF EXISTS(SELECT 1 FROM public.accounting_recompute_split_parts WHERE club_id=p_club AND period_start=d_from AND kind='write' AND part=p_idx)
   OR (SELECT count(*) FROM public.accounting_recompute_split_parts WHERE club_id=p_club AND period_start=d_from AND kind='check')<>n_pages
   OR EXISTS(SELECT 1 FROM public.accounting_recompute_split_parts WHERE club_id=p_club AND period_start=d_from AND kind='check' AND value ? 'reason') THEN RETURN NULL; END IF;
  -- One writer per page: the page's own lock, so two shards never write it twice.
  IF NOT pg_try_advisory_xact_lock(hashtextextended('weekly-prep-write:'||p_club||':'||d_from||':'||p_idx,0)) THEN RETURN NULL; END IF;
  INSERT INTO public.accounting_recompute_split_parts(club_id,period_start,period_end,kind,part,value)
  VALUES(p_club,d_from,d_to,'write',p_idx,public.fn_rakeback_split_write(p_club,d_from,d_to,ids)) ON CONFLICT DO NOTHING;
  RETURN 'write '||p_idx;
 END IF;
 RETURN NULL;
END $function$

smarter_private.zero_standalone_foreign_.def:
CREATE OR REPLACE FUNCTION smarter_private.zero_standalone_foreign_commissions_proven(p_club uuid, p_start timestamp with time zone, p_end timestamp with time zone)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public', 'smarter_private'
 SET "TimeZone" TO 'UTC'
AS $function$
DECLARE f uuid;comb jsonb;fr public.accounting_routed_settlement_runs%ROWTYPE;key text;
 had_windows boolean;had_clubs boolean;node_total numeric;bank_total numeric;down_total numeric;owner_total numeric;node_n int;owner_n int;paid_stamp timestamptz;stamp_n int;
BEGIN
 IF public.fn_caller_is_engine()IS DISTINCT FROM true OR public.fn_platform_frozen()IS DISTINCT FROM false
 OR to_regclass('pg_temp._routed_zero_standalone_context')IS NULL
 OR NOT EXISTS(SELECT FROM pg_class WHERE oid=to_regclass('pg_temp._routed_zero_standalone_context')AND pg_get_userbyid(relowner)='postgres')
 THEN RAISE EXCEPTION 'zero_standalone_original_stage_required' USING ERRCODE='42501';END IF;
 IF NOT EXISTS(SELECT FROM pg_temp._routed_zero_standalone_context c WHERE c.scope_kind='club'AND c.scope_id=p_club AND c.period_start=p_start AND c.period_end=p_end AND c.source_count=0 AND c.fingerprint=md5(''))
 OR EXISTS(SELECT FROM pg_temp._routed_nodes)OR EXISTS(SELECT FROM pg_temp._routed_edges)
 THEN RAISE EXCEPTION 'zero_standalone_full_original_empty_plan_required' USING ERRCODE='23514';END IF;
 IF EXISTS(SELECT FROM public.agent_commission_settlements cs WHERE cs.club_id=p_club AND cs.period_start<p_end AND cs.period_end>p_start
  AND(cs.union_id IS NULL OR cs.period_start IS DISTINCT FROM p_start OR cs.period_end IS DISTINCT FROM p_end OR cs.paid_at IS NULL))
 THEN RAISE EXCEPTION 'zero_standalone_legacy_or_partial_foreign_settlement' USING ERRCODE='55000';END IF;
 IF EXISTS(SELECT FROM public.chip_ledger l WHERE l.idempotency_key='standalone-rake-bank:'||p_club::text||':'||to_char(p_start AT TIME ZONE 'UTC','YYYY-MM-DD"T"HH24:MI:SS"Z"')||'..'||to_char(p_end AT TIME ZONE 'UTC','YYYY-MM-DD"T"HH24:MI:SS"Z"'))
 OR EXISTS(SELECT FROM public.ca_mint_ledger m WHERE m.op_id='standalone-rake-bank:'||p_club::text||':'||to_char(p_start AT TIME ZONE 'UTC','YYYY-MM-DD"T"HH24:MI:SS"Z"')||'..'||to_char(p_end AT TIME ZONE 'UTC','YYYY-MM-DD"T"HH24:MI:SS"Z"'))
 THEN RAISE EXCEPTION 'zero_standalone_positive_or_unknown_bank_basis_refused' USING ERRCODE='23514';END IF;
 -- The original combine touches exactly four temporary relations and no GUC.
 -- Save every preexisting window/club row; own nodes/edges are genuinely empty.
 -- V3 does not use _routed_clubs and may inherit it from an earlier stage.
 had_clubs:=to_regclass('pg_temp._routed_clubs')IS NOT NULL;
 IF had_clubs THEN
  CREATE TEMP TABLE IF NOT EXISTS _zero_saved_r2_clubs(LIKE pg_temp._routed_clubs INCLUDING ALL)ON COMMIT DROP;
  TRUNCATE pg_temp._zero_saved_r2_clubs;INSERT INTO pg_temp._zero_saved_r2_clubs SELECT * FROM pg_temp._routed_clubs;
 END IF;
 had_windows:=to_regclass('pg_temp._close_r2_windows')IS NOT NULL;
 IF had_windows THEN
  CREATE TEMP TABLE IF NOT EXISTS _zero_saved_r2_windows(LIKE pg_temp._close_r2_windows INCLUDING ALL)ON COMMIT DROP;
  TRUNCATE pg_temp._zero_saved_r2_windows;
  INSERT INTO pg_temp._zero_saved_r2_windows SELECT * FROM pg_temp._close_r2_windows;
 END IF;
 CREATE TEMP TABLE IF NOT EXISTS _zero_foreign_owner_nodes(club_id uuid,user_id uuid,own_amount numeric,PRIMARY KEY(club_id,user_id))ON COMMIT DROP;
 CREATE TEMP TABLE IF NOT EXISTS _zero_foreign_edges(club_id uuid,payer_user uuid,payee_user uuid,amount numeric,role text)ON COMMIT DROP;
 CREATE TEMP TABLE IF NOT EXISTS _zero_foreign_endpoints(club_id uuid,actor_id uuid,PRIMARY KEY(club_id,actor_id))ON COMMIT DROP;
 CREATE TEMP TABLE IF NOT EXISTS _zero_foreign_actual_r2_legs ON COMMIT DROP AS SELECT l.*FROM public.chip_ledger l WHERE false;
 FOR f IN SELECT DISTINCT cs.union_id FROM public.agent_commission_settlements cs
  WHERE cs.club_id=p_club AND cs.period_start<p_end AND cs.period_end>p_start ORDER BY cs.union_id
 LOOP
  SELECT * INTO fr FROM public.accounting_routed_settlement_runs r WHERE r.scope_kind='union'AND r.scope_id=f AND r.union_id=f
   AND r.period_start=p_start AND r.period_end=p_end AND r.round_no=2 FOR SHARE;
  IF NOT FOUND OR fr.completed_at IS NULL OR fr.routing_version IS DISTINCT FROM 3
   OR fr.result->>'success'IS DISTINCT FROM 'true'OR fr.result->>'scope_kind'IS DISTINCT FROM 'union'OR fr.result->>'scope_id'IS DISTINCT FROM f::text
   OR fr.result->>'round'IS DISTINCT FROM '2'OR fr.result->>'routing_version'IS DISTINCT FROM '3'OR fr.result->>'source_version'IS DISTINCT FROM '2'
   OR fr.result->>'source_contract_version'IS DISTINCT FROM '3'OR fr.result->>'shortfalls'IS DISTINCT FROM '0'OR fr.result->>'paid_to'IS DISTINCT FROM 'agent_wallet'
  THEN RAISE EXCEPTION 'zero_standalone_canonical_foreign_round_required' USING ERRCODE='55000';END IF;
  comb:=public.fn_settle_accounting_commission_combine('union',f,p_start,p_end);
  IF comb IS NULL OR comb->>'read_failed'IS DISTINCT FROM 'false'OR comb->>'full_path'IS DISTINCT FROM 'false'
   OR comb->>'hierarchy_bad'IS DISTINCT FROM 'false'OR comb->>'entitlement_bad'IS DISTINCT FROM 'false'OR comb->>'unclassified'IS DISTINCT FROM '0'
   OR comb->>'fingerprint'IS DISTINCT FROM fr.source_fingerprint OR(comb->>'sources')::bigint IS DISTINCT FROM(fr.result->>'sources')::bigint
  THEN RAISE EXCEPTION 'zero_standalone_current_original_foreign_windows_required' USING ERRCODE='55000';END IF;
  key:='round2:v3:'||f::text||':'||extract(epoch FROM p_start)::text||':'||extract(epoch FROM p_end)::text;
  PERFORM cs.id FROM pg_temp._routed_nodes n JOIN public.agent_commission_settlements cs
   ON cs.club_id=n.club_id AND cs.user_id=n.user_id AND cs.period_start=p_start AND cs.period_end=p_end
   ORDER BY cs.club_id,cs.user_id,cs.id FOR SHARE OF cs;
  -- Independently derived per-node authority, not the run's aggregate alone.
  IF EXISTS(SELECT FROM pg_temp._routed_nodes n WHERE(SELECT count(*)FROM public.agent_commission_settlements cs
    WHERE cs.club_id=n.club_id AND cs.user_id=n.user_id AND cs.union_id=f AND cs.period_start=p_start AND cs.period_end=p_end
     AND cs.amount=n.own_amount AND cs.rows_count=n.rows_count AND cs.settlement_ref=key AND cs.paid_at IS NOT NULL)<>1)
   OR EXISTS(SELECT FROM public.agent_commission_settlements cs WHERE cs.union_id=f AND cs.period_start<p_end AND cs.period_end>p_start
    AND(cs.period_start IS DISTINCT FROM p_start OR cs.period_end IS DISTINCT FROM p_end OR NOT EXISTS(SELECT FROM pg_temp._routed_nodes n
     WHERE n.club_id=cs.club_id AND n.user_id=cs.user_id AND n.own_amount=cs.amount AND n.rows_count=cs.rows_count AND cs.settlement_ref=key AND cs.paid_at IS NOT NULL)))
  THEN RAISE EXCEPTION 'zero_standalone_foreign_own_rows_not_bound' USING ERRCODE='23514';END IF;
  SELECT min(cs.paid_at),count(DISTINCT cs.paid_at)INTO paid_stamp,stamp_n FROM public.agent_commission_settlements cs
   WHERE cs.union_id=f AND cs.period_start=p_start AND cs.period_end=p_end AND cs.settlement_ref=key;
  IF stamp_n IS DISTINCT FROM 1 OR paid_stamp IS NULL OR fr.completed_at<paid_stamp
  THEN RAISE EXCEPTION 'zero_standalone_foreign_original_transaction_not_bound' USING ERRCODE='23514';END IF;
  -- The original writer inserts every edge with created_at DEFAULT now(),
  -- and every own settlement explicitly with paid_at=now(), in ONE transaction.
  -- Point-read every possible original source endpoint at that exact timestamp.
  -- No locale-dependent prefix range or whole-ledger metadata scan is used.
  -- This proves the canonical original writer's transaction, not global absence
  -- of unrelated later forged metadata or arbitrary foreign journal activity.
  TRUNCATE pg_temp._zero_foreign_endpoints,pg_temp._zero_foreign_actual_r2_legs;
  INSERT INTO pg_temp._zero_foreign_endpoints SELECT club_id,club_id FROM pg_temp._routed_clubs
   UNION SELECT club_id,user_id FROM pg_temp._routed_nodes;
  INSERT INTO pg_temp._zero_foreign_actual_r2_legs
   SELECT l.*FROM pg_temp._zero_foreign_endpoints ep CROSS JOIN LATERAL(
    SELECT z.*FROM public.chip_ledger z WHERE z.club_id=ep.club_id AND z.from_entity_id=ep.actor_id AND z.created_at=paid_stamp OFFSET 0)l
   WHERE l.idempotency_key LIKE key||':%'
    OR(l.category='commission'AND l.from_type IN('club_treasury','agent_wallet')
      AND(l.union_id=f OR l.metadata->>'accounting_scope_id'=f::text OR(l.union_id IS NULL AND NULLIF(l.metadata->>'accounting_scope_id','')IS NULL))
      AND CASE WHEN pg_input_is_valid(l.metadata->>'period_start','timestamptz')THEN(l.metadata->>'period_start')::timestamptz=p_start ELSE true END
      AND CASE WHEN pg_input_is_valid(l.metadata->>'period_end','timestamptz')THEN(l.metadata->>'period_end')::timestamptz=p_end ELSE true END)
    OR(l.category='treasury_transfer'AND l.metadata->>'payment_method'='owner_confirmed_existing_transfer'
      AND(l.union_id=f OR l.metadata->>'accounting_scope_id'=f::text OR(l.union_id IS NULL AND NULLIF(l.metadata->>'accounting_scope_id','')IS NULL))
      AND CASE WHEN pg_input_is_valid(l.metadata->>'period_start','timestamptz')THEN(l.metadata->>'period_start')::timestamptz=p_start ELSE true END
      AND CASE WHEN pg_input_is_valid(l.metadata->>'period_end','timestamptz')THEN(l.metadata->>'period_end')::timestamptz=p_end ELSE true END);

  TRUNCATE pg_temp._zero_foreign_owner_nodes,pg_temp._zero_foreign_edges;
  INSERT INTO pg_temp._zero_foreign_owner_nodes SELECT n.club_id,n.user_id,n.own_amount FROM pg_temp._routed_nodes n JOIN public.clubs c ON c.id=n.club_id AND c.owner_id=n.user_id;
  IF EXISTS(SELECT FROM pg_temp._routed_edges e JOIN pg_temp._zero_foreign_owner_nodes o ON o.club_id=e.club_id AND o.user_id=e.payee_user WHERE e.payer_user IS NOT NULL)
  THEN RAISE EXCEPTION 'zero_standalone_foreign_owner_hierarchy_changed' USING ERRCODE='23514';END IF;
  INSERT INTO pg_temp._zero_foreign_edges SELECT e.club_id,CASE WHEN o.user_id IS NULL THEN e.payer_user END,e.payee_user,sum(e.amount),min(e.role)
   FROM pg_temp._routed_edges e LEFT JOIN pg_temp._zero_foreign_owner_nodes o ON o.club_id=e.club_id AND o.user_id=e.payer_user
   WHERE NOT EXISTS(SELECT FROM pg_temp._zero_foreign_owner_nodes x WHERE x.club_id=e.club_id AND x.user_id=e.payee_user)
   GROUP BY e.club_id,CASE WHEN o.user_id IS NULL THEN e.payer_user END,e.payee_user;
  SELECT coalesce(sum(own_amount),0),count(*)INTO node_total,node_n FROM pg_temp._routed_nodes;
  SELECT coalesce(sum(own_amount),0),count(*)INTO owner_total,owner_n FROM pg_temp._zero_foreign_owner_nodes;
  SELECT coalesce(sum(amount)FILTER(WHERE payer_user IS NULL),0),coalesce(sum(amount)FILTER(WHERE payer_user IS NOT NULL),0)INTO bank_total,down_total FROM pg_temp._zero_foreign_edges;
  IF node_total IS DISTINCT FROM(fr.result->>'own_commission_amount')::numeric OR owner_total IS DISTINCT FROM(fr.result->>'owner_retained_in_club_bank')::numeric
   OR bank_total IS DISTINCT FROM(fr.result->>'amount')::numeric OR down_total IS DISTINCT FROM(fr.result->>'downstream_amount')::numeric
   OR node_n-owner_n IS DISTINCT FROM(fr.result->>'payees')::int OR bank_total+owner_total IS DISTINCT FROM node_total
   OR EXISTS(SELECT FROM pg_temp._routed_nodes n WHERE(CASE WHEN EXISTS(SELECT FROM pg_temp._zero_foreign_owner_nodes o WHERE o.club_id=n.club_id AND o.user_id=n.user_id)THEN 0 ELSE n.own_amount END)
    IS DISTINCT FROM coalesce((SELECT sum(amount)FROM pg_temp._zero_foreign_edges e WHERE e.club_id=n.club_id AND e.payee_user=n.user_id),0)-coalesce((SELECT sum(amount)FROM pg_temp._zero_foreign_edges e WHERE e.club_id=n.club_id AND e.payer_user=n.user_id),0))
  THEN RAISE EXCEPTION 'zero_standalone_foreign_original_plan_not_conserved' USING ERRCODE='23514';END IF;
  -- A paid prior-transfer discharge is a separate real reimbursement; bind its
  -- source fingerprint and gross own amount to the same independently read node.
  IF EXISTS(SELECT FROM smarter_private.existing_rakeback_transfer_allocations a JOIN public.chip_ledger r ON r.id=a.reimbursement_ledger_id
   WHERE a.obligation_role='commission'AND a.period_start=p_start AND a.period_end=p_end
    AND r.metadata->>'accounting_scope_kind'='union'AND r.metadata->>'accounting_scope_id'=f::text
    AND(r.created_at IS DISTINCT FROM paid_stamp OR NOT smarter_private.existing_rakeback_transfer_complete('commission',a.obligation_id)
     OR NOT EXISTS(SELECT FROM pg_temp._routed_nodes n JOIN public.clubs c ON c.id=n.club_id WHERE n.club_id=a.club_id AND n.user_id=a.beneficiary_id
      AND a.amount=n.own_amount AND a.original_payer_id=c.owner_id
      AND a.source_fingerprint=md5(jsonb_build_array('commission_own',a.club_id,a.beneficiary_id,p_start,p_end,fr.source_fingerprint,n.own_amount)::text))
     OR NOT EXISTS(SELECT FROM pg_temp._zero_foreign_edges e WHERE e.club_id=a.club_id AND e.payee_user=a.beneficiary_id AND e.payer_user IS NULL AND e.amount>=a.amount)))
  THEN RAISE EXCEPTION 'zero_standalone_foreign_prior_discharge_not_bound' USING ERRCODE='23514';END IF;
  UPDATE pg_temp._zero_foreign_edges e SET amount=e.amount-coalesce((SELECT sum(a.amount)FROM smarter_private.existing_rakeback_transfer_allocations a JOIN public.chip_ledger r ON r.id=a.reimbursement_ledger_id
   WHERE a.obligation_role='commission'AND a.club_id=e.club_id AND a.beneficiary_id=e.payee_user AND a.period_start=p_start AND a.period_end=p_end
   AND r.metadata->>'accounting_scope_kind'='union'AND r.metadata->>'accounting_scope_id'=f::text),0)WHERE e.payer_user IS NULL;
  DELETE FROM pg_temp._zero_foreign_edges WHERE amount=0;
  IF EXISTS(SELECT FROM pg_temp._zero_foreign_edges e WHERE(SELECT count(*)FROM public.chip_ledger l
    WHERE l.idempotency_key=key||':'||e.club_id::text||':'||coalesce(e.payer_user::text,'club')||':'||e.payee_user::text
    AND l.status='posted'AND l.category='commission'AND l.created_at=paid_stamp AND l.union_id=f AND l.club_id=e.club_id
    AND l.from_type=CASE WHEN e.payer_user IS NULL THEN 'club_treasury'ELSE 'agent_wallet'END AND l.from_entity_id=coalesce(e.payer_user,e.club_id)
    AND l.to_type='agent_wallet'AND l.to_entity_id=e.payee_user AND l.amount=e.amount
    AND l.pre_from_balance-l.post_from_balance=e.amount AND l.post_to_balance-l.pre_to_balance=e.amount
    AND l.metadata->>'routing_version'='3'AND l.metadata->>'accounting_scope_kind'='union'AND l.metadata->>'accounting_scope_id'=f::text
    AND(l.metadata->>'period_start')::timestamptz=p_start AND(l.metadata->>'period_end')::timestamptz=p_end AND l.metadata->>'paid_to'='agent_wallet'
    AND l.metadata->>'payee_role_at_transfer'=e.role
    AND(l.metadata->>'own_commission')::numeric=(SELECT n.own_amount-coalesce((SELECT sum(a.amount)FROM smarter_private.existing_rakeback_transfer_allocations a JOIN public.chip_ledger r ON r.id=a.reimbursement_ledger_id WHERE a.obligation_role='commission'AND a.club_id=n.club_id AND a.beneficiary_id=n.user_id AND a.period_start=p_start AND a.period_end=p_end AND r.metadata->>'accounting_scope_kind'='union'AND r.metadata->>'accounting_scope_id'=f::text),0)FROM pg_temp._routed_nodes n WHERE n.club_id=e.club_id AND n.user_id=e.payee_user)
    AND(l.metadata->>'pass_through')::boolean=(e.payer_user IS NOT NULL)
    AND(SELECT count(*)FROM public.settlement_invoices i WHERE i.source_ledger_id=l.id AND i.status='paid'AND i.chips_transferred AND i.message_sent AND i.gross_amount=l.amount AND i.net_amount=l.amount AND i.deductions=0)=1)<>1)
   OR EXISTS(SELECT FROM pg_temp._zero_foreign_actual_r2_legs l
    WHERE NOT EXISTS(SELECT FROM pg_temp._zero_foreign_edges e WHERE l.category='commission'AND l.idempotency_key=key||':'||e.club_id::text||':'||coalesce(e.payer_user::text,'club')||':'||e.payee_user::text)
     AND NOT EXISTS(SELECT FROM smarter_private.existing_rakeback_transfer_allocations a WHERE a.obligation_role='commission'AND a.reimbursement_ledger_id=l.id
      AND a.period_start=p_start AND a.period_end=p_end AND smarter_private.existing_rakeback_transfer_complete('commission',a.obligation_id))
     -- A legitimate R3 player reimbursement may share this same transaction.
     -- Classify it through its actual R3 certificate/admission, never role text alone.
     AND NOT EXISTS(SELECT FROM smarter_private.existing_rakeback_transfer_allocations a JOIN public.accounting_rakeback_period_calculations c ON c.id=a.certificate_id
      WHERE a.obligation_role='player'AND a.reimbursement_ledger_id=l.id AND a.period_start=p_start AND a.period_end=p_end AND c.coordinator_union_id=f
       AND l.union_id=f AND l.metadata->>'accounting_scope_kind'='union'AND l.metadata->>'accounting_scope_id'=f::text
       AND smarter_private.existing_rakeback_transfer_complete('player',a.obligation_id)))
  THEN RAISE EXCEPTION 'zero_standalone_foreign_actual_edge_receipt_not_bound' USING ERRCODE='23514';END IF;
 END LOOP;
 -- Restore every relation changed by the original combine, not a cached plan
 -- or a claimed zero. All original own-stage scalar facts remain untouched.
 TRUNCATE pg_temp._routed_nodes,pg_temp._routed_edges;
 IF had_clubs THEN TRUNCATE pg_temp._routed_clubs;INSERT INTO pg_temp._routed_clubs SELECT * FROM pg_temp._zero_saved_r2_clubs;
 ELSE DROP TABLE IF EXISTS pg_temp._routed_clubs;END IF;
 IF had_windows THEN TRUNCATE pg_temp._close_r2_windows;INSERT INTO pg_temp._close_r2_windows SELECT * FROM pg_temp._zero_saved_r2_windows;
 ELSE DROP TABLE IF EXISTS pg_temp._close_r2_windows;END IF;
END $function$
